==============================================================================
# El módulo SaveData se utiliza para manipular los datos de guardado. Contiene 
# los {Value}s que conforman los datos de guardado y {Conversion}s para resolver
# incompatibilidades entre Essentials y las versiones del juego.
# @see SaveData.register
# @see SaveData.register_conversion
module SaveData
  # Contiene la ruta del archivo de guardado.
  FILE_PATH = if File.directory?(System.data_directory)
                File.join(System.data_directory, "Game.rxdata")
              else
                "./Game.rxdata"
              end

  # @return [Boolean] si el archivo de guardado existe
  def self.exists?
    return File.file?(FILE_PATH)
  end

  # Obtiene los datos de guardado del archivo proporcionado.
  # Devuelve un Array en el caso de un archivo de guardado anterior a la 
  # versión 19.
  # @param file_path [String] ruta del archivo desde el que cargar
  # @return [Hash, Array] datos de guardado cargados
  # @raise [IOError, SystemCallError] si falla la apertura del archivo
  def self.get_data_from_file(file_path)
    validate file_path => String
    save_data = nil
    File.open(file_path) do |file|
      data = Marshal.load(file)
      if data.is_a?(Hash)
        save_data = data
        next
      end
      save_data = [data]
      save_data << Marshal.load(file) until file.eof?
    end
    return save_data
  end

  # Obtiene los datos de guardado del archivo proporcionado. Si necesita 
  # conversión, lo vuelve a guardar.
  # @param file_path [String] ruta del archivo desde el que leer
  # @return [Hash] datos de guardado en formato Hash
  # @raise (ver .get_data_from_file)
  def self.read_from_file(file_path)
    validate file_path => String
    save_data = get_data_from_file(file_path)
    save_data = to_hash_format(save_data) if save_data.is_a?(Array)
    if !save_data.empty? && run_conversions(save_data)
      File.open(file_path, "wb") { |file| Marshal.dump(save_data, file) }
    end
    return save_data
  end

  # Compila los datos de guardado y guarda una versión marshaled de ellos en
  # el archivo proporcionado.
  # @param file_path [String] ruta del archivo donde guardar
  # @raise [InvalidValueError] si se está guardando un valor no válido
  def self.save_to_file(file_path)
    validate file_path => String
    save_data = self.compile_save_hash
    File.open(file_path, "wb") { |file| Marshal.dump(save_data, file) }
  end

  # Elimina el archivo de guardado (y un posible archivo de respaldo .bak 
  # si existe)
  # @raise [Error::ENOENT]
  def self.delete_file
    File.delete(FILE_PATH)
    File.delete(FILE_PATH + ".bak") if File.file?(FILE_PATH + ".bak")
  end

  # Convierte los datos de formato anterior a la versión 19 al nuevo formato.
  # @param old_format [Array] datos de guardado en formato anterior a la 
  # versión 19
  # @return [Hash] datos de guardado en el nuevo formato
  def self.to_hash_format(old_format)
    validate old_format => Array
    hash = {}
    @values.each do |value|
      data = value.get_from_old_format(old_format)
      hash[value.id] = data unless data.nil?
    end
    return hash
  end
end

==============================================================================
# Script: SaveData_Value
==============================================================================
module SaveData
  # Contiene objetos Value para cada elemento de guardado.
  # Se llena durante el tiempo de ejecución mediante las llamadas a 
  # SaveData.register.
  # @type [Array<Value>]
  @values = []

  # Un error generado si se intenta guardar o cargar un valor de guardado no 
  # válido.
  class InvalidValueError < RuntimeError; end

  #=============================================================================
  # Representa un único valor en los datos de guardado.
  # Se añaden nuevos valores utilizando {SaveData.register}.
  class Value
    # @return [Symbol] el ID del valor
    attr_reader :id

    # @param id [Symbol] ID del valor
    def initialize(id, &block)
      validate id => Symbol, block => Proc
      @id = id
      @loaded = false
      @load_in_bootup = false
      @reset_on_new_game = false
      instance_eval(&block)
      raise "No save_value defined for save value #{id.inspect}" if @save_proc.nil?
      raise "No load_value defined for save value #{id.inspect}" if @load_proc.nil?
    end

    # @param value [Object] valor a verificar
    # @return [Boolean] si el valor proporcionado es válido
    def valid?(value)
      return true if @ensured_class.nil?
      return value.is_a?(Object.const_get(@ensured_class))
    end

    # Llama al procedimiento de guardado del valor y devuelve su valor.
    # @return [Object] valor del procedimiento de guardado
    # @raise [InvalidValueError] si se está guardando un valor no válido
    def load(value)
      validate_value(value)
      @load_proc.call(value)
      @loaded = true
    end

    # Llama al procedimiento de guardado del valor y devuelve su valor.
    # @return [Object] valor del procedimiento de guardado
    # @raise [InvalidValueError] si se está guardando un valor no válido
    def save
      value = @save_proc.call
      validate_value(value)
      return value
    end

    # @return [Boolean] si el valor tiene un procedimiento de nuevo juego 
    # definido
    def has_new_game_proc?
      return @new_game_value_proc.is_a?(Proc)
    end

    # Llama al procedimiento de carga del valor de guardado con el valor obtenido
    # del procedimiento de nuevo juego definido.
    # @raise (ver #load)
    def load_new_game_value
      unless self.has_new_game_proc?
        raise "Save value #{@id.inspect} has no new_game_value defined"
      end
      self.load(@new_game_value_proc.call)
    end

    # @return [Boolean] si el valor debe cargarse durante el arranque
    def load_in_bootup?
      return @load_in_bootup
    end

    def reset_on_new_game
      @reset_on_new_game = true
    end

    def reset_on_new_game?
      return @reset_on_new_game
    end

    # @return [Boolean] si el valor ha sido cargado
    def loaded?
      return @loaded
    end

    # Marca el valor como no cargado.
    def mark_as_unloaded
      @loaded = false
    end

    # Utiliza el procedimiento {#from_old_format} para seleccionar los datos correctos de
    # +old_format+ y devolverlos.
    # Devuelve nil si el procedimiento no está definido.
    # @param old_format [Array] formato antiguo para cargar el valor
    # @return [Object] datos del formato antiguo
    def get_from_old_format(old_format)
      return nil if @old_format_get_proc.nil?
      return @old_format_get_proc.call(old_format)
    end

    #---------------------------------------------------------------------------

    private

    # Genera un {InvalidValueError} si el valor proporcionado no es válido.
    # @param value [Object] valor a verificar
    # @raise [InvalidValueError] si el valor no es válido
    def validate_value(value)
      return if self.valid?(value)
      raise InvalidValueError, "El valor de guardado #{@id.inspect} no es un #{@ensured_class} (se proporcionó #{value.class.name})"
    end

    # @!group Configuración

    # Si está presente, asegura que el valor sea de la clase proporcionada.
    # @param class_name [Symbol] clase a asegurar
    # @see SaveData.register
    def ensure_class(class_name)
      validate class_name => Symbol
      @ensured_class = class_name
    end

    # Define cómo se coloca el valor cargado en una variable global.
    # Requiere un bloque con el valor cargado como parámetro.
    # @see SaveData.register
    def load_value(&block)
      raise ArgumentError, "No se proporcionó un bloque para load_value" unless block_given?
      @load_proc = block
    end

    # Define qué se guarda en los datos de guardado. Requiere un bloque.
    # @see SaveData.register
    def save_value(&block)
      raise ArgumentError, "No se proporcionó un bloque para save_value" unless block_given?
      @save_proc = block
    end

    # Si está presente, define a qué se establece el valor al comienzo de un nuevo juego.
    # @see SaveData.register
    def new_game_value(&block)
      raise ArgumentError, "No se proporcionó un bloque para new_game_value" unless block_given?
      @new_game_value_proc = block
    end

    # Si está presente, establece que el valor se cargue durante el arranque.
    # @see SaveData.register
    def load_in_bootup
      @load_in_bootup = true
    end

    # Si está presente, define cómo se debe obtener el valor del formato de guardado
    # anterior a la versión 19. Requiere un bloque con el antiguo formato como parámetro.
    # @see SaveData.register
    def from_old_format(&block)
      raise ArgumentError, "No se proporcionó un bloque para from_old_format" unless block_given?
      @old_format_get_proc = block
    end

    # @!endgroup
  end

  #=============================================================================
  # Registra un {Value} para ser guardado en los datos de guardado.
  # Toma un bloque que define los procedimientos de guardado ({Value#save_value})
  # y carga ({Value#load_value}) del valor.
  #
  # También es posible proporcionar un procedimiento para obtener el valor
  # del formato de guardado anterior a la versión 19 ({Value#from_old_format}),
  # definir un valor que se establecerá al iniciar un nuevo juego con {Value#new_game_value}
  # y asegurarse de que el valor guardado y cargado sea de la clase correcta con {Value#ensure_class}.
  #
  # Los valores se pueden registrar para cargarse durante el arranque con
  # {Value#load_in_bootup}. Si se define un procedimiento new_game_value, se
  # llamará cuando se lance el juego por primera vez,
  # o si los datos de guardado no contienen el valor en cuestión.
  #
  # @example Registrando un nuevo valor
  #   SaveData.register(:foo) do
  #     ensure_class :Foo
  #     save_value { $foo }
  #     load_value { |value| $foo = value }
  #     new_game_value { Foo.new }
  #   end
  # @example Registrando un valor para cargarse durante el arranque
  #   SaveData.register(:bar) do
  #     load_in_bootup
  #     save_value { $bar }
  #     load_value { |value| $bar = value }
  #     new_game_value { Bar.new }
  #   end
  # @param id [Symbol] id del valor
  # @yield el bloque de código que se guardará como un Value
  def self.register(id, &block)
    validate id => Symbol
    unless block_given?
      raise ArgumentError, "No se proporcionó un bloque para SaveData.register"
    end
    @values << Value.new(id, &block)
  end

  def self.unregister(id)
    validate id => Symbol
    @values.delete_if { |value| value.id == id }
  end

  # @param save_data [Hash] datos de guardado para validar
  # @return [Boolean] si los datos de guardado dados son válidos
  def self.valid?(save_data)
    validate save_data => Hash
    return @values.all? { |value| value.valid?(save_data[value.id]) }
  end

  # Carga valores desde los datos de guardado proporcionados.
  # Se puede pasar una condición opcional.
  # @param save_data [Hash] datos de guardado para cargar
  # @param condition_block [Proc] condición opcional
  # @api privado
  def self.load_values(save_data, &condition_block)
    @values.each do |value|
      next if block_given? && !condition_block.call(value)
      if save_data.has_key?(value.id)
        value.load(save_data[value.id])
      elsif value.has_new_game_proc?
        value.load_new_game_value
      end
    end
  end

  # Carga los valores desde los datos de guardado proporcionados
  # llamando al procedimiento {Value#load_value} de cada objeto {Value}.
  # Se omiten los valores que ya están cargados.
  # Si un valor no existe en los datos de guardado y tiene
  # un procedimiento {Value#new_game_value} definido, ese valor
  # se carga en su lugar.
  # @param save_data [Hash] datos de guardado para cargar
  # @raise [InvalidValueError] si se está cargando un valor no válido
  def self.load_all_values(save_data)
    validate save_data => Hash
    load_values(save_data) { |value| !value.loaded? }
  end

  # Marca como no cargados todos los valores que no están cargados al iniciar.
  def self.mark_values_as_unloaded
    @values.each do |value|
      value.mark_as_unloaded if !value.load_in_bootup? || value.reset_on_new_game?
    end
  end

  # Carga cada valor desde los datos de guardado que se ha
  # establecido para ser cargado durante el arranque. Se realiza cuando existe un archivo de guardado.
  # @param save_data [Hash] datos de guardado para cargar
  # @raise [InvalidValueError] si se está cargando un valor no válido
  def self.load_bootup_values(save_data)
    validate save_data => Hash
    load_values(save_data) { |value| !value.loaded? && value.load_in_bootup? }
  end

  # Recorre cada valor con {Value#load_in_bootup} habilitado y carga su
  # valor de nuevo juego, si está definido. Se realiza cuando no existe un 
  # archivo de guardado.
  def self.initialize_bootup_values
    @values.each do |value|
      next unless value.load_in_bootup?
      value.load_new_game_value if value.has_new_game_proc? && !value.loaded?
    end
  end

  # Carga el valor de nuevo juego de cada {Value}, si está definido. Se realiza
  # al comenzar un nuevo juego.
  def self.load_new_game_values
    @values.each do |value|
      value.load_new_game_value if value.has_new_game_proc? && (!value.loaded? || value.reset_on_new_game?)
    end
  end

  # @return [Hash{Symbol => Object}] una representación en forma de hash de los
  # datos de guardado
  # @raise [InvalidValueError] si se está guardando un valor no válido
  def self.compile_save_hash
    save_data = {}
    @values.each { |value| save_data[value.id] = value.save }
    return save_data
  end
end

==============================================================================
# Script: SaveData_Conversion
==============================================================================
module SaveData
  # Contains Conversion objects for each defined conversion:
  # {
  #   :essentials => {
  #     '19'    => [<Conversion>, ...],
  #     '19.1'  => [<Conversion>, ...],
  #     ...
  #   },
  #   :game => {
  #     '1.1.0' => [<Conversion>, ...],
  #     '1.2.0' => [<Conversion>, ...],
  #     ...
  #   }
  # }
  # Populated during runtime by SaveData.register_conversion calls.
  @conversions = {
    essentials: {},
    game:       {},
    lbdsky:     {}
  }

  #=============================================================================
  # Represents a conversion made to save data.
  # New conversions are added using {SaveData.register_conversion}.
  class Conversion
    # @return [Symbol] conversion ID
    attr_reader :id
    # @return [String] conversion title
    attr_reader :title
    # @return [Symbol] trigger type of the conversion (+:essentials+ or +:game+)
    attr_reader :trigger_type
    # @return [String] trigger version of the conversion
    attr_reader :version

    # @param id [String] conversion ID
    def initialize(id, &block)
      @id = id
      @value_procs = {}
      @all_proc = nil
      @title = "Running conversion #{@id}"
      @trigger_type = nil
      @version = nil
      instance_eval(&block)
      if @trigger_type.nil? || @version.nil?
        raise "Conversion #{@id} is missing a condition"
      end
    end

    # Returns whether the conversion should be run with the given version.
    # @param version [String] version to check
    # @return [Boolean] whether the conversion should be run
    def should_run?(version)
      return PluginManager.compare_versions(version, @version) < 0
    end

    # Runs the conversion on the given save data.
    # @param save_data [Hash]
    def run(save_data)
      @value_procs.each do |value_id, proc|
        unless save_data.has_key?(value_id)
          raise "Save data does not have value #{value_id.inspect}"
        end
        proc.call(save_data[value_id])
      end
      @all_proc.call(save_data) if @all_proc.is_a?(Proc)
    end

    # Runs the conversion on the given object.
    # @param object
    # @param key [Symbol]
    def run_single(object, key)
      @value_procs[key].call(object) if @value_procs[key].is_a?(Proc)
    end

    #---------------------------------------------------------------------------

    private

    # @!group Configuration

    # Sets the conversion's title.
    # @param new_title [String] conversion title
    # @note Since conversions are run before loading the player's chosen language,
    #   conversion titles can not be localized.
    # @see SaveData.register_conversion
    def display_title(new_title)
      validate new_title => String
      @title = new_title
    end

    # Sets the conversion to trigger for save files created below
    # the given Essentials version.
    # @param version [Numeric, String]
    # @see SaveData.register_conversion
    def essentials_version(version)
      validate version => [Numeric, String]
      raise "Multiple conditions in conversion #{@id}" unless @version.nil?
      @trigger_type = :essentials
      @version = version.to_s
    end

    # Sets the conversion to trigger for save files created below
    # the given game version.
    # @param version [Numeric, String]
    # @see SaveData.register_conversion
    def game_version(version)
      validate version => [Numeric, String]
      raise "Multiple conditions in conversion #{@id}" unless @version.nil?
      @trigger_type = :game
      @version = version.to_s
    end

    # Sets the conversion to trigger for save files created below
    # the given LBDSKY version.
    # @param version [Numeric, String]
    # @see SaveData.register_conversion
    def lbds_version(version)
      validate version => [Numeric, String]
      raise "Multiple conditions in conversion #{@id}" unless @version.nil?
      @trigger_type = :lbdsky
      @version = version.to_s
    end

    # Defines a conversion to the given save value.
    # @param value_id [Symbol] save value ID
    # @see SaveData.register_conversion
    def to_value(value_id, &block)
      validate value_id => Symbol
      raise ArgumentError, "No block given to to_value" unless block_given?
      if @value_procs[value_id].is_a?(Proc)
        raise "Multiple to_value definitions in conversion #{@id} for #{value_id}"
      end
      @value_procs[value_id] = block
    end

    # Defines a conversion to the entire save data.
    # @see SaveData.register_conversion
    def to_all(&block)
      raise ArgumentError, "No block given to to_all" unless block_given?
      if @all_proc.is_a?(Proc)
        raise "Multiple to_all definitions in conversion #{@id}"
      end
      @all_proc = block
    end

    # @!endgroup
  end

  #=============================================================================
  # Registers a {Conversion} to occur for save data that meets the given criteria.
  # Two types of criteria can be defined: {Conversion#essentials_version} and
  # {Conversion#game_version}. The conversion is automatically run on save data
  # that contains an older version number.
  #
  # A single value can be modified with {Conversion#to_value}. The entire save data
  # is accessed with {Conversion#to_all}, and a conversion title can be specified
  # with {Conversion#display_title}.
  # @example Registering a new conversion
  #   SaveData.register_conversion(:my_conversion) do
  #     game_version '1.1.0'
  #     display_title 'Converting some stuff'
  #     to_value :player do |player|
  #       # code that modifies the :player value
  #     end
  #     to_all do |save_data|
  #       save_data[:new_value] = Foo.new
  #     end
  #   end
  # @yield the block of code to be saved as a Conversion
  def self.register_conversion(id, &block)
    validate id => Symbol
    unless block_given?
      raise ArgumentError, "No block given to SaveData.register_conversion"
    end
    conversion = Conversion.new(id, &block)
    @conversions[conversion.trigger_type][conversion.version] ||= []
    @conversions[conversion.trigger_type][conversion.version] << conversion
  end

  # @param save_data [Hash] save data to get conversions for
  # @return [Array<Conversion>] all conversions that should be run on the data
  def self.get_conversions(save_data)
    conversions_to_run = []
    versions = {
      essentials: save_data[:essentials_version] || "18.1",
      game:       save_data[:game_version] || "0.0.0",
      lbdsky:     save_data[:lbdsky_version] || "0.0.0"
    }
    [:essentials, :game, :lbdsky].each do |trigger_type|
      # Ensure the versions are sorted from lowest to highest
      sorted_versions = @conversions[trigger_type].keys.sort do |v1, v2|
        PluginManager.compare_versions(v1, v2)
      end
      sorted_versions.each do |version|
        @conversions[trigger_type][version].each do |conversion|
          next unless conversion.should_run?(versions[trigger_type])
          conversions_to_run << conversion
        end
      end
    end
    return conversions_to_run
  end

  # Runs all possible conversions on the given save data.
  # Saves a backup before running conversions.
  # @param save_data [Hash] save data to run conversions on
  # @return [Boolean] whether conversions were run
  def self.run_conversions(save_data)
    validate save_data => Hash
    conversions_to_run = self.get_conversions(save_data)
    return false if conversions_to_run.none?
    File.open(SaveData::FILE_PATH + ".bak", "wb") { |f| Marshal.dump(save_data, f) }
    Console.echo_h1(_INTL("Converting save file"))
    conversions_to_run.each do |conversion|
      Console.echo_li("#{conversion.title}...")
      conversion.run(save_data)
      Console.echo_done(true)
    end
    Console.echoln_li_done(_INTL("Successfully applied {1} save file conversion(s)", conversions_to_run.length))
    save_data[:essentials_version] = Essentials::VERSION
    save_data[:game_version] = Settings::GAME_VERSION
    save_data[:lbdsky_version] = LBDSKY::VERSION
    return true
  end

  # Runs all possible conversions on the given object.
  # @param object [Hash] object to run conversions on
  # @param key [Hash] object's key in save data
  # @param save_data [Hash] save data to run conversions on
  def self.run_single_conversions(object, key, save_data)
    validate key => Symbol
    conversions_to_run = self.get_conversions(save_data)
    conversions_to_run.each do |conversion|
      conversion.run_single(object, key)
    end
  end
end

==============================================================================
# Script: Game_SaveValues
==============================================================================
# Contains the save values defined in Essentials by default.

SaveData.register(:player) do
  ensure_class :Player
  save_value { $player }
  load_value { |value| $player = value }
  new_game_value { Player.new("Unnamed", GameData::TrainerType.keys.first) }
end

# @deprecated This save data is slated to be removed in v22, as its use is
# replaced by $stats.play_time.
SaveData.register(:frame_count) do
  ensure_class :Integer
  save_value { Graphics.frame_count }
  load_value { |value| Graphics.frame_count = value }
  new_game_value { 0 }
end

SaveData.register(:game_system) do
  load_in_bootup
  ensure_class :Game_System
  save_value { $game_system }
  load_value { |value| $game_system = value }
  new_game_value { Game_System.new }
end

SaveData.register(:pokemon_system) do
  load_in_bootup
  ensure_class :PokemonSystem
  save_value { $PokemonSystem }
  load_value { |value| $PokemonSystem = value }
  new_game_value { PokemonSystem.new }
end

SaveData.register(:switches) do
  ensure_class :Game_Switches
  save_value { $game_switches }
  load_value { |value| $game_switches = value }
  new_game_value { Game_Switches.new }
end

SaveData.register(:variables) do
  ensure_class :Game_Variables
  save_value { $game_variables }
  load_value { |value| $game_variables = value }
  new_game_value { Game_Variables.new }
end

SaveData.register(:self_switches) do
  ensure_class :Game_SelfSwitches
  save_value { $game_self_switches }
  load_value { |value| $game_self_switches = value }
  new_game_value { Game_SelfSwitches.new }
end

SaveData.register(:game_screen) do
  ensure_class :Game_Screen
  save_value { $game_screen }
  load_value { |value| $game_screen = value }
  new_game_value { Game_Screen.new }
end

SaveData.register(:map_factory) do
  ensure_class :PokemonMapFactory
  save_value { $map_factory }
  load_value { |value| $map_factory = value }
end

SaveData.register(:game_player) do
  ensure_class :Game_Player
  save_value { $game_player }
  load_value { |value| $game_player = value }
  new_game_value { Game_Player.new }
end

