# Script: Scene_Map
==============================================================================
#===============================================================================
# ** Modified Scene_Map class for Pokémon.
#-------------------------------------------------------------------------------
#
#===============================================================================
class Scene_Map
  attr_reader :spritesetGlobal
  attr_reader :map_renderer

  def spriteset(map_id = -1)
    return @spritesets[map_id] if map_id > 0 && @spritesets[map_id]
    @spritesets.each_value do |i|
      return i if i.map == $game_map
    end
    return @spritesets.values[0]
  end

  def createSpritesets
    @map_renderer = TilemapRenderer.new(Spriteset_Map.viewport) if !@map_renderer || @map_renderer.disposed?
    @spritesetGlobal = Spriteset_Global.new if !@spritesetGlobal
    @spritesets = {}
    $map_factory.maps.each do |map|
      @spritesets[map.map_id] = Spriteset_Map.new(map)
    end
    $map_factory.setSceneStarted(self)
    updateSpritesets(true)
  end

  def createSingleSpriteset(map)
    temp = $scene.spriteset.getAnimations
    @spritesets[map] = Spriteset_Map.new($map_factory.maps[map])
    $scene.spriteset.restoreAnimations(temp)
    $map_factory.setSceneStarted(self)
    updateSpritesets(true)
  end

  def disposeSpritesets
    return if !@spritesets
    @spritesets.each_key do |i|
      next if !@spritesets[i]
      @spritesets[i].dispose
      @spritesets[i] = nil
    end
    @spritesets.clear
    @spritesets = {}
  end

  def dispose
    disposeSpritesets
    @map_renderer.dispose
    @map_renderer = nil
    @spritesetGlobal.dispose
    @spritesetGlobal = nil
  end

  def autofade(mapid)
    playingBGM = $game_system.playing_bgm
    playingBGS = $game_system.playing_bgs
    return if !playingBGM && !playingBGS
    map = load_data(sprintf("Data/Map%03d.rxdata", mapid))
    if playingBGM && map.autoplay_bgm
      test_filename = map.bgm.name
      test_filename += "_n" if PBDayNight.isNight? && FileTest.audio_exist?("Audio/BGM/" + test_filename + "_n")
      pbBGMFade(0.8) if playingBGM.name != test_filename
    end
    if playingBGS && map.autoplay_bgs && playingBGS.name != map.bgs.name
      pbBGSFade(0.8)
    end
    Graphics.frame_reset
  end

  def transfer_player(cancel_swimming = true)
    $game_temp.player_transferring = false
    pbCancelVehicles($game_temp.player_new_map_id, cancel_swimming)
    autofade($game_temp.player_new_map_id)
    pbBridgeOff
    @spritesetGlobal.playersprite.clearShadows
    if $game_map.map_id != $game_temp.player_new_map_id
      $map_factory.setup($game_temp.player_new_map_id)
    end
    $game_player.moveto($game_temp.player_new_x, $game_temp.player_new_y)
    case $game_temp.player_new_direction
    when 2 then $game_player.turn_down
    when 4 then $game_player.turn_left
    when 6 then $game_player.turn_right
    when 8 then $game_player.turn_up
    end
    $game_player.straighten
    $game_temp.followers.map_transfer_followers
    $game_map.update
    disposeSpritesets
    RPG::Cache.clear
    createSpritesets
    if $game_temp.transition_processing
      $game_temp.transition_processing = false
      Graphics.transition
    end
    $game_map.autoplay
    Graphics.frame_reset
    Input.update
    $game_player.clear_stair_data
  end

  def call_interact
    $game_temp.interact_calling = false
    triggered = false
    # Try to trigger an event the player is standing on, and one in front of
    # the player
    if !$game_temp.in_mini_update
      triggered ||= $game_player.check_event_trigger_here([0])
      triggered ||= $game_player.check_event_trigger_there([0, 2]) if !triggered
    end
    # Try to trigger an interaction with a tile
    if !triggered
      $game_player.straighten
      EventHandlers.trigger(:on_player_interact)
    end
  end

  def call_menu
    $game_temp.menu_calling = false
    $game_temp.in_menu = true
    $game_player.straighten
    $game_map.update
    sscene = PokemonPauseMenu_Scene.new
    sscreen = PokemonPauseMenu.new(sscene)
    sscreen.pbStartPokemonMenu
    $game_temp.in_menu = false
  end

  def call_ready_menu
    $game_temp.ready_menu_calling = false
    $game_player.straighten
    pbUseKeyItem
  end

  def call_debug
    $game_temp.debug_calling = false
    pbPlayDecisionSE
    $game_player.straighten
    pbFadeOutIn { pbDebugMenu }
  end

  def miniupdate
    $game_temp.in_mini_update = true
    loop do
      $game_player.update
      updateMaps
      $game_system.update
      $game_screen.update
      break if !$game_temp.player_transferring
      transfer_player(false)
      break if $game_temp.transition_processing
    end
    updateSpritesets
    $game_temp.in_mini_update = false
  end

  def updateMaps
    $map_factory.maps.each do |map|
      map.update
    end
    $map_factory.updateMaps(self)
  end

  def updateSpritesets(refresh = false)
    @spritesets = {} if !@spritesets
    $map_factory.maps.each do |map|
      @spritesets[map.map_id] = Spriteset_Map.new(map) if !@spritesets[map.map_id]
    end
    keys = @spritesets.keys.clone
    keys.each do |i|
      if $map_factory.hasMap?(i)
        @spritesets[i].update
      else
        @spritesets[i]&.dispose
        @spritesets[i] = nil
        @spritesets.delete(i)
      end
    end
    @spritesetGlobal.update
    pbDayNightTint(@map_renderer)
    @map_renderer.refresh if refresh
    @map_renderer.update
    EventHandlers.trigger(:on_frame_update)
  end

  def update
    loop do
      pbMapInterpreter.update
      $game_player.update
      updateMaps
      $game_system.update
      $game_screen.update
      break if !$game_temp.player_transferring
      transfer_player(false)
      break if $game_temp.transition_processing
    end
    updateSpritesets
    if $game_temp.title_screen_calling
      SaveData.mark_values_as_unloaded
      $scene = pbCallTitle
      return
    end
    if $game_temp.transition_processing
      $game_temp.transition_processing = false
      if $game_temp.transition_name == ""
        Graphics.transition
      else
        Graphics.transition(40, "Graphics/Transitions/" + $game_temp.transition_name)
      end
    end
    return if $game_temp.message_window_showing
    update_input if !pbMapInterpreterRunning? && !$PokemonGlobal.forced_movement?
    if !$game_player.moving?
      if $game_temp.interact_calling
        call_interact
      elsif $game_temp.menu_calling
        call_menu
      elsif $game_temp.ready_menu_calling
        call_ready_menu
      elsif $game_temp.debug_calling
        call_debug
      end
    end
  end

  def update_input
    if Input.trigger?(Input::USE)
      $game_temp.interact_calling = true
    elsif Input.trigger?(Input::BACK)
      if !$game_system.menu_disabled && !$game_player.moving?
        $game_temp.menu_calling = true
        $game_temp.menu_beep = true
      end
    elsif Input.trigger?(Input::SPECIAL) #Input.trigger?(Input::QUICK_UP) || Input.trigger?(Input::QUICK_DOWN)
      $game_temp.ready_menu_calling = true if !$game_player.moving?
      Input.update   # Prevents immediate moving of cursor in Ready Menu
    elsif Input.press?(Input::F9)
      $game_temp.debug_calling = true if $DEBUG
    end
  end

  def main
    createSpritesets
    # NOTE: I don't know why a duration of 4 is needed here to make the fade
    #       (slightly over) 0.4 seconds.
    Graphics.transition(4, "")
    loop do
      Graphics.update
      Input.update
      update
      break if $scene != self
    end
    Graphics.freeze
    dispose
    if $game_temp.title_screen_calling
      pbMapInterpreter.command_end if pbMapInterpreterRunning?
      $game_temp.last_uptime_refreshed_play_time = nil
      $game_temp.title_screen_calling = false
      pbBGMFade(1.0)
      # NOTE: I don't know why a duration of 4 is needed here to make the fade
      #       (slightly over) 0.4 seconds.
      Graphics.transition(4, "")
      Graphics.freeze
    end
  end
end

==============================================================================
# Script: Interpreter
==============================================================================
#===============================================================================
# ** Interpreter
#-------------------------------------------------------------------------------
#  This interpreter runs event commands. This class is used within the
#  Game_System class and the Game_Event class.
#===============================================================================
class Interpreter
  # Object Initialization
  #     depth : nest depth
  #     main  : main flag
  def initialize(depth = 0, main = false)
    @depth = depth
    @main  = main
    if depth > 100
      print("La llamada al evento común ha superado el límite máximo.")
      exit
    end
    clear
  end

  def inspect
    str = super.chop
    str << sprintf(" @event_id: %d>", @event_id)
    return str
  end

  def clear
    @map_id             = 0       # map ID when starting up
    @event_id           = 0
    @message_waiting    = false   # waiting for message to end
    @move_route_waiting = false   # waiting for move completion
    @wait_count         = 0
    @wait_start         = nil
    @child_interpreter  = nil
    @branch             = {}
    @buttonInput        = false
    @hidden_choices     = []
    @renamed_choices    = []
    end_follower_overrides
  end

  # Event Setup
  #     list     : list of event commands
  #     event_id : event ID
  def setup(list, event_id, map_id = nil)
    clear
    @map_id = map_id || $game_map.map_id
    @event_id = event_id
    @list = list
    @index = 0
    @branch.clear
  end

  def setup_starting_event
    $game_map.refresh if $game_map.need_refresh
    # Set up common event if one wants to start
    if $game_temp.common_event_id > 0
      setup($data_common_events[$game_temp.common_event_id].list, 0)
      $game_temp.common_event_id = 0
      return
    end
    # Check all map events for one that wants to start, and set it up
    $game_map.events.each_value do |event|
      next if !event.starting
      if event.trigger < 3   # Isn't autorun or parallel processing
        event.lock
        event.clear_starting
      end
      setup(event.list, event.id, event.map.map_id)
      return
    end
    # Check all common events for one that is autorun, and set it up
    $data_common_events.compact.each do |common_event|
      next if common_event.trigger != 1 || !$game_switches[common_event.switch_id]
      setup(common_event.list, 0)
      return
    end
  end

  def running?
    return !@list.nil?
  end

  def update
    @loop_count = 0
    loop do
      @loop_count += 1
      if @loop_count > 100   # Call Graphics.update for freeze prevention
        Graphics.update
        @loop_count = 0
      end
      # If this interpreter's map isn't the current map or connected to it,
      # forget this interpreter's event ID
      if $game_map.map_id != @map_id && !$map_factory.areConnected?($game_map.map_id, @map_id)
        @event_id = 0
      end
      # Update child interpreter if one exists
      if @child_interpreter
        @child_interpreter.update
        @child_interpreter = nil if !@child_interpreter.running?
        return if @child_interpreter
      end
      # Do nothing if a message is being shown
      return if @message_waiting
      # Do nothing if any event or the player is in the middle of a move route
      if @move_route_waiting
        return if $game_player.move_route_forcing
        $game_map.events.each_value do |event|
          return if event.move_route_forcing
        end
        $game_temp.followers.each_follower do |event, follower|
          return if event.move_route_forcing
        end
        @move_route_waiting = false
      end
      # Do nothing if the player is jumping out of surfing
      return if $game_temp.ending_surf
      # Do nothing while waiting
      if @wait_count > 0
        return if System.uptime - @wait_start < @wait_count
        @wait_count = 0
        @wait_start = nil
      end
      # Do nothing if the pause menu is going to open
      return if $game_temp.menu_calling
      # If there are no commands in the list, try to find something that wants to run
      if @list.nil?
        setup_starting_event if @main
        return if @list.nil?   # Couldn't find anything that wants to run
      end
      # Execute the next command
      return if execute_command == false
      # Move to the next @index
      @index += 1
    end
  end

  def execute_script(script)
    begin
      result = eval(script)
      return result
    rescue Exception
      e = $!
      raise if e.is_a?(SystemExit) || e.class.to_s == "Reset"
      event = get_self
      # Gather text for error message
      message = pbGetExceptionMessage(e)
      backtrace_text = ""
      if e.is_a?(SyntaxError)
        script.each_line do |line|
          line.gsub!(/\s+$/, "")
          if line[/^\s*\(/]
            message += "\r\n***La línea '#{line}' no debería comenzar con '('."
            message += "Intenta poner el '(' al final de la línea anterior en su"
            message += " lugar, o utiliza 'extendtext.exe'."
          end
        end
      else
        backtrace_text += "\r\n"
        backtrace_text += "Rastro de la traza:"
        e.backtrace[0, 10].each { |i| backtrace_text += "\r\n#{i}" }
        backtrace_text.gsub!(/Section(\d+)/) { $RGSS_SCRIPTS[$1.to_i][1] } rescue nil
        backtrace_text += "\r\n"
      end
      # Assemble error message
      err = "Error de Script en el Intérprete\r\n"
      if $game_map
        map_name = (pbGetBasicMapNameFromId($game_map.map_id) rescue nil) || "???"
        if event
          err = "Error de script en el evento #{event.id} (coordenadas #{event.x},#{event.y}), en el mapa #{$game_map.map_id} (#{map_name})\r\n"
        else
          err = "Error de script en el Evento Común, en el mapa #{$game_map.map_id} (#{map_name})\r\n"
        end
      end
      err += "Excepción: #{e.class}\r\n"
      err += "Mensaje: #{message}\r\n\r\n"
      err += "***Script completo:\r\n#{script}"   # \r\n"
      err += backtrace_text
      # Raise error
      raise EventScriptError.new(err)
    end
  end

  def get_character(parameter = 0)
    case parameter
    when -1   # player
      return $game_player
    when 0    # this event
      events = $game_map.events
      return (events) ? events[@event_id] : nil
    else      # specific event
      events = $game_map.events
      return (events) ? events[parameter] : nil
    end
  end

  def get_player
    return get_character(-1)
  end

  def get_self
    return get_character(0)
  end

  def get_event(parameter)
    return get_character(parameter)
  end

  # Freezes all events on the map (for use at the beginning of common events)
  def pbGlobalLock
    $game_map.events.each_value { |event| event.minilock }
  end

  # Unfreezes all events on the map (for use at the end of common events)
  def pbGlobalUnlock
    $game_map.events.each_value { |event| event.unlock }
  end

  # Gets the next index in the interpreter, ignoring certain commands between messages
  def pbNextIndex(index)
    return -1 if !@list || @list.length == 0
    i = index + 1
    loop do
      return i if i >= @list.length - 1
      case @list[i].code
      when 118, 108, 408   # Label, Comment
        i += 1
      when 413             # Repeat Above
        i = pbRepeatAbove(i)
      when 113             # Break Loop
        i = pbBreakLoop(i)
      when 119             # Jump to Label
        newI = pbJumpToLabel(i, @list[i].parameters[0])
        i = (newI > i) ? newI : i + 1
      else
        return i
      end
    end
  end

  def pbRepeatAbove(index)
    index = @list[index].indent
    loop do
      index -= 1
      return index + 1 if @list[index].indent == indent
    end
  end

  def pbBreakLoop(index)
    indent = @list[index].indent
    temp_index = index
    loop do
      temp_index += 1
      return index + 1 if temp_index >= @list.size - 1
      return temp_index + 1 if @list[temp_index].code == 413 &&
                               @list[temp_index].indent < indent
    end
  end

  def pbJumpToLabel(index, label_name)
    temp_index = 0
    loop do
      return index + 1 if temp_index >= @list.size - 1
      return temp_index + 1 if @list[temp_index].code == 118 &&
                               @list[temp_index].parameters[0] == label_name
      temp_index += 1
    end
  end

  def follower_move_route(id = nil)
    @follower_move_route = true
    @follower_move_route_id = id
  end

  def follower_animation(id = nil)
    @follower_animation = true
    @follower_animation_id = id
  end

  def end_follower_overrides
    @follower_move_route = false
    @follower_move_route_id = nil
    @follower_animation = false
    @follower_animation_id = nil
  end

  # Helper function that shows a picture in a script.
  def pbShowPicture(number, name, origin, x, y, zoomX = 100, zoomY = 100, opacity = 255, blendType = 0)
    number += ($game_temp.in_battle ? 50 : 0)
    $game_screen.pictures[number].show(name, origin, x, y, zoomX, zoomY, opacity, blendType)
  end

  # Erases an event and adds it to the list of erased events so that
  # it can stay erased when the game is saved then loaded again.
  def pbEraseThisEvent
    if $game_map.events[@event_id]
      $game_map.events[@event_id].erase
      $PokemonMap&.addErasedEvent(@event_id)
    end
    @index += 1
    return true
  end

  # Runs a common event.
  def pbCommonEvent(id)
    common_event = $data_common_events[id]
    return if !common_event
    if $game_temp.in_battle
      $game_system.battle_interpreter.setup(common_event.list, 0)
    else
      interp = Interpreter.new
      interp.setup(common_event.list, 0)
      loop do
        Graphics.update
        Input.update
        interp.update
        pbUpdateSceneMap
        break if !interp.running?
      end
    end
  end

  # Sets another event's self switch (eg. pbSetSelfSwitch(20, "A", true) ).
  def pbSetSelfSwitch(eventid, switch_name, value, mapid = -1)
    mapid = @map_id if mapid < 0
    changed = false
    case eventid
    when Array, Range
      eventid.each do |ev_id|
        old_value = $game_self_switches[[mapid, ev_id, switch_name]]
        $game_self_switches[[mapid, ev_id, switch_name]] = value
        changed = true if value != old_value
      end
    when Numeric
      old_value = $game_self_switches[[mapid, eventid, switch_name]]
      $game_self_switches[[mapid, eventid, switch_name]] = value
      changed = (value != old_value)
    end
    if changed && $map_factory.hasMap?(mapid)
      $map_factory.getMap(mapid, false).need_refresh = true
    end
  end

  def tsOff?(c)
    return get_self.tsOff?(c)
  end
  alias isTempSwitchOff? tsOff?

  def tsOn?(c)
    return get_self.tsOn?(c)
  end
  alias isTempSwitchOn? tsOn?

  def setTempSwitchOn(c)
    get_self.setTempSwitchOn(c)
  end

  def setTempSwitchOff(c)
    get_self.setTempSwitchOff(c)
  end

  def getVariable(*arg)
    if arg.length == 0
      return nil if !$PokemonGlobal.eventvars
      return $PokemonGlobal.eventvars[[@map_id, @event_id]]
    else
      return $game_variables[arg[0]]
    end
  end

  def setVariable(*arg)
    if arg.length == 1
      $PokemonGlobal.eventvars = {} if !$PokemonGlobal.eventvars
      $PokemonGlobal.eventvars[[@map_id, @event_id]] = arg[0]
    else
      $game_variables[arg[0]] = arg[1]
      $game_map.need_refresh = true
    end
  end

  def pbGetPokemon(id)
    var_value = pbGet(id)
    return nil if var_value.nil?
    if var_value.is_a?(Array)
      box = var_value[0]
      index = var_value[1]
      return $PokemonStorage[box][index]
    end
    return $player.party[var_value]
  end

  def pbSetEventTime(*arg)
    $PokemonGlobal.eventvars = {} if !$PokemonGlobal.eventvars
    time = pbGetTimeNow
    time = time.to_i
    pbSetSelfSwitch(@event_id, "A", true)
    $PokemonGlobal.eventvars[[@map_id, @event_id]] = time
    arg.each do |otherevt|
      pbSetSelfSwitch(otherevt, "A", true)
      $PokemonGlobal.eventvars[[@map_id, otherevt]] = time
    end
  end

  # Used in boulder events. Allows an event to be pushed.
  def pbPushThisEvent(strength = false)
    event = get_self
    old_x  = event.x
    old_y  = event.y
    # Apply strict version of passable, which treats tiles that are passable
    # only from certain directions as fully impassible
    return if !event.can_move_in_direction?($game_player.direction, true)
    $stats.strength_push_count += 1
    case $game_player.direction
    when 2 then event.move_down
    when 4 then event.move_left
    when 6 then event.move_right
    when 8 then event.move_up
    end
    $PokemonMap&.addMovedEvent(@event_id)
    if old_x != event.x || old_y != event.y
      pbSEPlay("Strength push") if strength
      $game_player.lock
      loop do
        Graphics.update
        Input.update
        pbUpdateSceneMap
        break if !event.moving?
      end
      $game_player.unlock
    end
  end

  def pbPushThisBoulder
    pbPushThisEvent(true) if $PokemonMap.strengthUsed
    return true
  end

  def pbSmashThisEvent
    event = get_self
    pbSmashEvent(event) if event
    @index += 1
    return true
  end

  def pbTrainerIntro(symbol)
    return true if $DEBUG && !GameData::TrainerType.exists?(symbol)
    tr_type = GameData::TrainerType.get(symbol).id
    pbGlobalLock
    pbPlayTrainerIntroBGM(tr_type)
    return true
  end

  def pbTrainerEnd
    pbGlobalUnlock
    event = get_self
    event&.erase_route
  end

  def setPrice(item, buy_price = -1, sell_price = -1)
    item = GameData::Item.get(item).id
    $game_temp.mart_prices[item] = [-1, -1] if !$game_temp.mart_prices[item]
    $game_temp.mart_prices[item][0] = buy_price if buy_price > 0
    if sell_price >= 0   # 0=can't sell
      $game_temp.mart_prices[item][1] = sell_price
    elsif buy_price > 0
      $game_temp.mart_prices[item][1] = buy_price / Settings::ITEM_SELL_PRICE_DIVISOR
    end
  end

  def setSellPrice(item, sell_price)
    setPrice(item, -1, sell_price)
  end
end

==============================================================================
# Script: Interpreter_Commands
==============================================================================
#===============================================================================
# ** Interpreter
#-------------------------------------------------------------------------------
#  This interpreter runs event commands. This class is used within the
#  Game_System class and the Game_Event class.
#===============================================================================
class Interpreter
  #-----------------------------------------------------------------------------
  # * Event Command Execution
  #-----------------------------------------------------------------------------
  def execute_command
    # Reached end of list of commands
    if @index >= @list.size - 1
      command_end
      return true
    end
    # Make current command's parameters available for reference via @parameters
    @parameters = @list[@index].parameters
    # Branch by command code
    case @list[@index].code
    when 101 then return command_101   # Show Text
    when 102 then return command_102   # Show Choices
    when 402 then return command_402   # When [**]
    when 403 then return command_403   # When Cancel
    when 103 then return command_103   # Input Number
    when 104 then return command_104   # Change Text Options
    when 105 then return command_105   # Button Input Processing
    when 106 then return command_106   # Wait
    when 111 then return command_111   # Conditional Branch
    when 411 then return command_411   # Else
    when 112 then return command_112   # Loop
    when 413 then return command_413   # Repeat Above
    when 113 then return command_113   # Break Loop
    when 115 then return command_115   # Exit Event Processing
    when 116 then return command_116   # Erase Event
    when 117 then return command_117   # Call Common Event
    when 118 then return command_118   # Label
    when 119 then return command_119   # Jump to Label
    when 121 then return command_121   # Control Switches
    when 122 then return command_122   # Control Variables
    when 123 then return command_123   # Control Self Switch
    when 124 then return command_124   # Control Timer
    when 125 then return command_125   # Change Gold
    when 126 then return command_126   # Change Items
    when 127 then return command_127   # Change Weapons
    when 128 then return command_128   # Change Armor
    when 129 then return command_129   # Change Party Member
    when 131 then return command_131   # Change Windowskin
    when 132 then return command_132   # Change Battle BGM
    when 133 then return command_133   # Change Battle End ME
    when 134 then return command_134   # Change Save Access
    when 135 then return command_135   # Change Menu Access
    when 136 then return command_136   # Change Encounter
    when 201 then return command_201   # Transfer Player
    when 202 then return command_202   # Set Event Location
    when 203 then return command_203   # Scroll Map
    when 204 then return command_204   # Change Map Settings
    when 205 then return command_205   # Change Fog Color Tone
    when 206 then return command_206   # Change Fog Opacity
    when 207 then return command_207   # Show Animation
    when 208 then return command_208   # Change Transparent Flag
    when 209 then return command_209   # Set Move Route
    when 210 then return command_210   # Wait for Move's Completion
    when 221 then return command_221   # Prepare for Transition
    when 222 then return command_222   # Execute Transition
    when 223 then return command_223   # Change Screen Color Tone
    when 224 then return command_224   # Screen Flash
    when 225 then return command_225   # Screen Shake
    when 231 then return command_231   # Show Picture
    when 232 then return command_232   # Move Picture
    when 233 then return command_233   # Rotate Picture
    when 234 then return command_234   # Change Picture Color Tone
    when 235 then return command_235   # Erase Picture
    when 236 then return command_236   # Set Weather Effects
    when 241 then return command_241   # Play BGM
    when 242 then return command_242   # Fade Out BGM
    when 245 then return command_245   # Play BGS
    when 246 then return command_246   # Fade Out BGS
    when 247 then return command_247   # Memorize BGM/BGS
    when 248 then return command_248   # Restore BGM/BGS
    when 249 then return command_249   # Play ME
    when 250 then return command_250   # Play SE
    when 251 then return command_251   # Stop SE
    when 301 then return command_301   # Battle Processing
    when 601 then return command_601   # If Win
    when 602 then return command_602   # If Escape
    when 603 then return command_603   # If Lose
    when 302 then return command_302   # Shop Processing
    when 303 then return command_303   # Name Input Processing
    when 311 then return command_311   # Change HP
    when 312 then return command_312   # Change SP
    when 313 then return command_313   # Change State
    when 314 then return command_314   # Recover All
    when 315 then return command_315   # Change EXP
    when 316 then return command_316   # Change Level
    when 317 then return command_317   # Change Parameters
    when 318 then return command_318   # Change Skills
    when 319 then return command_319   # Change Equipment
    when 320 then return command_320   # Change Actor Name
    when 321 then return command_321   # Change Actor Class
    when 322 then return command_322   # Change Actor Graphic
    when 331 then return command_331   # Change Enemy HP
    when 332 then return command_332   # Change Enemy SP
    when 333 then return command_333   # Change Enemy State
    when 334 then return command_334   # Enemy Recover All
    when 335 then return command_335   # Enemy Appearance
    when 336 then return command_336   # Enemy Transform
    when 337 then return command_337   # Show Battle Animation
    when 338 then return command_338   # Deal Damage
    when 339 then return command_339   # Force Action
    when 340 then return command_340   # Abort Battle
    when 351 then return command_351   # Call Menu Screen
    when 352 then return command_352   # Call Save Screen
    when 353 then return command_353   # Game Over
    when 354 then return command_354   # Return to Title Screen
    when 355 then return command_355   # Script
    else          return true          # Other
    end
  end

  def command_dummy
    return true
  end

  #-----------------------------------------------------------------------------
  # * End Event
  #-----------------------------------------------------------------------------
  def command_end
    @list = nil
    end_follower_overrides
    # If main map event and event ID are valid, unlock event
    if @main && @event_id > 0 && $game_map.events[@event_id]
      $game_map.events[@event_id].unlock
    end
  end

  #-----------------------------------------------------------------------------
  # * Command Skip
  #-----------------------------------------------------------------------------
  def command_skip
    indent = @list[@index].indent
    loop do
      return true if @list[@index + 1].indent == indent
      @index += 1
    end
  end

  #-----------------------------------------------------------------------------
  # * Command If
  #-----------------------------------------------------------------------------
  def command_if(value)
    if @branch[@list[@index].indent] == value
      @branch.delete(@list[@index].indent)
      return true
    end
    return command_skip
  end

  #-----------------------------------------------------------------------------
  # * Show Text
  #-----------------------------------------------------------------------------
  def command_101
    return false if $game_temp.message_window_showing
    message     = @list[@index].parameters[0]
    message_end = ""
    choices                 = nil
    number_input_variable   = nil
    number_input_max_digits = nil
    # Check the next command(s) for things to add on to this text
    loop do
      next_index = pbNextIndex(@index)
      case @list[next_index].code
      when 401   # Continuation of 101 Show Text
        text = @list[next_index].parameters[0]
        message += " " if text != "" && message[message.length - 1, 1] != " "
        message += text
        @index = next_index
        next
      when 101   # Show Text
        message_end = "\1"
      when 102   # Show Choices
        @index = next_index
        choices = setup_choices(@list[@index].parameters)
      when 103   # Input Number
        number_input_variable   = @list[next_index].parameters[0]
        number_input_max_digits = @list[next_index].parameters[1]
        @index = next_index
      end
      break
    end
    # Translate the text
    message = _MAPINTL($game_map.map_id, message)
    # Display the text, with choices/number choosing if appropriate
    @message_waiting = true   # Lets parallel process events work while a message is displayed
    if choices
      command = pbMessage(message + message_end, choices[0], choices[1])
      @branch[@list[@index].indent] = choices[2][command] || command
    elsif number_input_variable
      params = ChooseNumberParams.new
      params.setMaxDigits(number_input_max_digits)
      params.setDefaultValue($game_variables[number_input_variable])
      $game_variables[number_input_variable] = pbMessageChooseNumber(message + message_end, params)
      $game_map.need_refresh = true if $game_map
    else
      pbMessage(message + message_end)
    end
    @message_waiting = false
    return true
  end

  #-----------------------------------------------------------------------------
  # * Show Choices
  #-----------------------------------------------------------------------------
  def command_102
    choices = setup_choices(@list[@index].parameters)
    @message_waiting = true
    command = pbShowCommands(nil, choices[0], choices[1])
    @message_waiting = false
    @branch[@list[@index].indent] = choices[2][command] || command
    Input.update   # Must call Input.update again to avoid extra triggers
    return true
  end

  def setup_choices(params)
    # Get initial options
    choices = params[0].clone
    cancel_index = params[1]
    # Clone @list so the original isn't modified
    @list = Marshal.load(Marshal.dump(@list))
    # Get more choices
    @choice_branch_index = 4
    ret = add_more_choices(choices, cancel_index, @index + 1, @list[@index].indent)
    # Rename choices
    ret[0].each_with_index { |choice, i| ret[0][i] = @renamed_choices[i] if @renamed_choices[i] }
    @renamed_choices.clear
    # Remove hidden choices
    ret[2] = Array.new(ret[0].length) { |i| i }
    @hidden_choices.each_with_index do |condition, i|
      next if !condition
      ret[0][i] = nil
      ret[2][i] = nil
    end
    ret[0].compact!
    ret[2].compact!
    @hidden_choices.clear
    # Translate choices
    ret[0].map! { |ch| _MAPINTL($game_map.map_id, ch) }
    return ret
  end

  def add_more_choices(choices, cancel_index, choice_index, indent)
    # Find index of next command after the current Show Choices command
    loop do
      break if @list[choice_index].indent == indent && ![402, 403, 404].include?(@list[choice_index].code)
      choice_index += 1
    end
    next_cmd = @list[choice_index]
    # If the next command isn't another Show Choices, we're done
    return [choices, cancel_index] if next_cmd.code != 102
    # Add more choices
    old_length = choices.length
    choices += next_cmd.parameters[0]
    # Update cancel option
    if next_cmd.parameters[1] == 5   # Branch
      cancel_index = choices.length + 1
      @choice_branch_index = cancel_index - 1
    elsif next_cmd.parameters[1] > 0   # A choice
      cancel_index = old_length + next_cmd.parameters[1]
      @choice_branch_index = -1
    end
    # Update first Show Choices command to include all options and result of cancelling
    @list[@index].parameters[0] = choices
    @list[@index].parameters[1] = cancel_index
    # Find the "When" lines for this Show Choices command and update their index parameter
    temp_index = choice_index + 1
    loop do
      break if @list[temp_index].indent == indent && ![402, 403, 404].include?(@list[temp_index].code)
      if @list[temp_index].code == 402 && @list[temp_index].indent == indent
        @list[temp_index].parameters[0] += old_length
      end
      temp_index += 1
    end
    # Delete the "Show Choices" line
    @list.delete(next_cmd)
    # Find more choices to add
    return add_more_choices(choices, cancel_index, choice_index + 1, indent)
  end

  def hide_choice(number, condition = true)
    @hidden_choices[number - 1] = condition
  end

  def rename_choice(number, new_name, condition = true)
    return if !condition || nil_or_empty?(new_name)
    @renamed_choices[number - 1] = new_name
  end

  #-----------------------------------------------------------------------------
  # * When [**]
  #-----------------------------------------------------------------------------
  def command_402
    # @parameters[0] is 0/1/2/3 for Choice 1/2/3/4 respectively
    if @branch[@list[@index].indent] == @parameters[0]
      @branch.delete(@list[@index].indent)
      return true
    end
    return command_skip
  end

  #-----------------------------------------------------------------------------
  # * When Cancel
  #-----------------------------------------------------------------------------
  def command_403
    # @parameters[0] is 4 for "Branch"
    if @branch[@list[@index].indent] == @choice_branch_index
      @branch.delete(@list[@index].indent)
      return true
    end
    return command_skip
  end

  #-----------------------------------------------------------------------------
  # * Input Number
  #-----------------------------------------------------------------------------
  def command_103
    @message_waiting = true
    variable_number = @list[@index].parameters[0]
    params = ChooseNumberParams.new
    params.setMaxDigits(@list[@index].parameters[1])
    params.setDefaultValue($game_variables[variable_number])
    $game_variables[variable_number] = pbChooseNumber(nil, params)
    $game_map.need_refresh = true if $game_map
    @message_waiting = false
    return true
  end

  #-----------------------------------------------------------------------------
  # * Change Text Options
  #-----------------------------------------------------------------------------
  def command_104
    return false if $game_temp.message_window_showing
    $game_system.message_position = @parameters[0]
    $game_system.message_frame    = @parameters[1]
    return true
  end

  #-----------------------------------------------------------------------------
  # * Button Input Processing
  #-----------------------------------------------------------------------------
  def pbButtonInputProcessing(variable_number = 0, timeout_frames = 0)
    ret = 0
    timer_start = System.uptime
    loop do
      Graphics.update
      Input.update
      pbUpdateSceneMap
      # Check for input and break if there is one
      (1..18).each { |i| ret = i if Input.trigger?(i) }
      break if ret != 0
      # Break if the timer runs out
      break if timeout_frames > 0 && System.uptime - timer_start >= timeout_frames / 20.0
    end
    Input.update
    if variable_number && variable_number > 0
      $game_variables[variable_number] = ret
      $game_map.need_refresh = true if $game_map
    end
    return ret
  end

  def command_105
    return false if @buttonInput
    @buttonInput = true
    pbButtonInputProcessing(@list[@index].parameters[0])
    @buttonInput = false
    @index += 1
    return true
  end

  #-----------------------------------------------------------------------------
  # * Wait
  #-----------------------------------------------------------------------------
  def command_106
    @wait_count = @parameters[0] / 20.0
    @wait_start = System.uptime
    return true
  end

  #-----------------------------------------------------------------------------
  # * Conditional Branch
  #-----------------------------------------------------------------------------
  def command_111
    result = false
    case @parameters[0]
    when 0   # switch
      switch_name = $data_system.switches[@parameters[1]]
      if switch_name && switch_name[/^s\:/]
        result = (eval($~.post_match) == (@parameters[2] == 0))
      else
        result = ($game_switches[@parameters[1]] == (@parameters[2] == 0))
      end
    when 1   # variable
      variable1_name = $data_system.variables[@parameters[1]]
      if variable1_name && variable1_name[/^s\:/]
        value1 = eval($~.post_match)
      else
        value1 = $game_variables[@parameters[1]]
      end
      if @parameters[2] == 0
        value2 = @parameters[3]
      else
        variable2_name = $data_system.variables[@parameters[3]]
        if variable2_name && variable2_name[/^s\:/]
          value2 = eval($~.post_match)
        else
          value2 = $game_variables[@parameters[3]]
        end
      end
      case @parameters[4]
      when 0 then result = (value1 == value2)
      when 1 then result = (value1 >= value2)
      when 2 then result = (value1 <= value2)
      when 3 then result = (value1 > value2)
      when 4 then result = (value1 < value2)
      when 5 then result = (value1 != value2)
      end
    when 2   # self switch
      if @event_id > 0
        key = [$game_map.map_id, @event_id, @parameters[1]]
        result = ($game_self_switches[key] == (@parameters[2] == 0))
      end
    when 3   # timer
      if $game_system.timer_start
        sec = $game_system.timer
        result = (@parameters[2] == 0) ? (sec >= @parameters[1]) : (sec <= @parameters[1])
      end
#    when 4, 5   # actor, enemy
    when 6   # character
      character = get_character(@parameters[1])
      result = (character.direction == @parameters[2]) if character
    when 7   # gold
      gold = $player.money
      result = (@parameters[2] == 0) ? (gold >= @parameters[1]) : (gold <= @parameters[1])
#    when 8, 9, 10   # item, weapon, armor
    when 11   # button
      result = Input.press?(@parameters[1])
    when 12   # script
      result = execute_script(@parameters[1])
    end
    # Store result in hash
    @branch[@list[@index].indent] = result
    if @branch[@list[@index].indent]
      @branch.delete(@list[@index].indent)
      return true
    end
    return command_skip
  end

  #-----------------------------------------------------------------------------
  # * Else
  #-----------------------------------------------------------------------------
  def command_411
    if @branch[@list[@index].indent] == false   # Could be nil, so intentionally checks for false
      @branch.delete(@list[@index].indent)
      return true
    end
    return command_skip
  end

  #-----------------------------------------------------------------------------
  # * Loop
  #-----------------------------------------------------------------------------
  def command_112
    return true
  end

  #-----------------------------------------------------------------------------
  # * Repeat Above
  #-----------------------------------------------------------------------------
  def command_413
    indent = @list[@index].indent
    loop do
      @index -= 1
      return true if @list[@index].indent == indent
    end
  end

  #-----------------------------------------------------------------------------
  # * Break Loop
  #-----------------------------------------------------------------------------
  def command_113
    indent = @list[@index].indent
    temp_index = @index
    loop do
      temp_index += 1
      return true if temp_index >= @list.size - 1   # Reached end of commands
      # Skip ahead to after the [Repeat Above] end of the current loop
      if @list[temp_index].code == 413 && @list[temp_index].indent < indent
        @index = temp_index
        return true
      end
    end
  end

  #-----------------------------------------------------------------------------
  # * Exit Event Processing
  #-----------------------------------------------------------------------------
  def command_115
    command_end
    return true
  end

  #-----------------------------------------------------------------------------
  # * Erase Event
  #-----------------------------------------------------------------------------
  def command_116
    if @event_id > 0
      $game_map.events[@event_id]&.erase
      $PokemonMap&.addErasedEvent(@event_id)
    end
    @index += 1
    return false
  end

  #-----------------------------------------------------------------------------
  # * Call Common Event
  #-----------------------------------------------------------------------------
  def command_117
    common_event = $data_common_events[@parameters[0]]
    if common_event
      @child_interpreter = Interpreter.new(@depth + 1)
      @child_interpreter.setup(common_event.list, @event_id)
    end
    return true
  end

  #-----------------------------------------------------------------------------
  # * Label
  #-----------------------------------------------------------------------------
  def command_118
    return true
  end

  #-----------------------------------------------------------------------------
  # * Jump to Label
  #-----------------------------------------------------------------------------
  def command_119
    label_name = @parameters[0]
    temp_index = 0
    loop do
      return true if temp_index >= @list.size - 1   # Reached end of commands
      # Check whether this command is a label with the desired name
      if @list[temp_index].code == 118 &&
         @list[temp_index].parameters[0] == label_name
        @index = temp_index
        return true
      end
      # Command isn't the desired label, increment temp_index and keep looking
      temp_index += 1
    end
  end

  #-----------------------------------------------------------------------------
  # * Control Switches
  #-----------------------------------------------------------------------------
  def command_121
    should_refresh = false
    (@parameters[0]..@parameters[1]).each do |i|
      next if $game_switches[i] == (@parameters[2] == 0)
      $game_switches[i] = (@parameters[2] == 0)
      should_refresh = true
    end
    # Refresh map
    $game_map.need_refresh = true if should_refresh
    return true
  end

  #-----------------------------------------------------------------------------
  # * Control Variables
  #-----------------------------------------------------------------------------
  def command_122
    value = 0
    case @parameters[3]
    when 0   # invariable (fixed value)
      value = @parameters[4]
    when 1   # variable
      value = $game_variables[@parameters[4]]
    when 2   # random number
      value = @parameters[4] + rand(@parameters[5] - @parameters[4] + 1)
#    when 3, 4, 5   # item, actor, enemy
    when 6   # character
      character = get_character(@parameters[4])
      if character
        case @parameters[5]
        when 0 then value = character.x             # x-coordinate
        when 1 then value = character.y             # y-coordinate
        when 2 then value = character.direction     # direction
        when 3 then value = character.screen_x      # screen x-coordinate
        when 4 then value = character.screen_y      # screen y-coordinate
        when 5 then value = character.terrain_tag.id_number   # terrain tag
        end
      end
    when 7   # other
      case @parameters[4]
      when 0 then value = $game_map.map_id          # map ID
      when 1 then value = $player.pokemon_count     # party members
      when 2 then value = $player.money             # gold
      when 3 then value = $stats.distance_moved     # steps
      when 4 then value = $stats.play_time          # play time
      when 5 then value = $game_system.timer        # timer
      when 6 then value = $game_system.save_count   # save count
      end
    end
    # Apply value and operation to all specified game variables
    (@parameters[0]..@parameters[1]).each do |i|
      case @parameters[2]
      when 0   # set
        next if $game_variables[i] == value
        $game_variables[i] = value
      when 1   # add
        next if $game_variables[i] >= 99_999_999
        $game_variables[i] += value
      when 2   # subtract
        next if $game_variables[i] <= -99_999_999
        $game_variables[i] -= value
      when 3   # multiply
        next if value == 1
        $game_variables[i] *= value
      when 4   # divide
        next if [0, 1].include?(value)
        $game_variables[i] /= value
      when 5   # remainder
        next if [0, 1].include?(value)
        $game_variables[i] %= value
      end
      $game_variables[i] = 99_999_999 if $game_variables[i] > 99_999_999
      $game_variables[i] = -99_999_999 if $game_variables[i] < -99_999_999
      $game_map.need_refresh = true
    end
    return true
  end

