==============================================================================
# Script: Sprite_Picture
==============================================================================
class Sprite_Picture
  def initialize(viewport, picture)
    @viewport = viewport
    @picture = picture
    @sprite = nil
    update
  end

  def dispose
    @sprite&.dispose
  end

  def update
    @sprite&.update
    # If picture file name is different from current one
    if @picture_name != @picture.name
      # Remember file name to instance variables
      @picture_name = @picture.name
      # If file name is not empty
      if @picture_name != ""
        # Get picture graphic
        @sprite = IconSprite.new(0, 0, @viewport) if !@sprite
        @sprite.setBitmap("Graphics/Pictures/" + @picture_name)
      end
    end
    # If file name is empty
    if @picture_name == ""
      # Set sprite to invisible
      if @sprite
        @sprite&.dispose
        @sprite = nil
      end
      return
    end
    # Set sprite to visible
    @sprite.visible = true
    # Set transfer starting point
    if @picture.origin == 0
      @sprite.ox = 0
      @sprite.oy = 0
    else
      @sprite.ox = @sprite.bitmap.width / 2
      @sprite.oy = @sprite.bitmap.height / 2
    end
    # Set sprite coordinates
    @sprite.x = @picture.x
    @sprite.y = @picture.y
    @sprite.z = @picture.number
    # Set zoom rate, opacity level, and blend method
    @sprite.zoom_x = @picture.zoom_x / 100.0
    @sprite.zoom_y = @picture.zoom_y / 100.0
    @sprite.opacity = @picture.opacity
    @sprite.blend_type = @picture.blend_type
    # Set rotation angle and color tone
    @sprite.angle = @picture.angle
    @sprite.tone = @picture.tone
  end
end


==============================================================================
# Script: Sprite_Timer
==============================================================================
class Sprite_Timer
  def initialize(viewport = nil)
    @viewport = viewport
    @timer = nil
    @total_sec = nil
    @disposed = false
  end

  def dispose
    @timer&.dispose
    @timer = nil
    @disposed = true
  end

  def disposed?
    @disposed
  end

  def update
    return if disposed?
    if $game_system.timer_start
      @timer.visible = true if @timer
      if !@timer
        @timer = Window_AdvancedTextPokemon.newWithSize("", Graphics.width - 120, 0, 120, 64)
        @timer.width = @timer.borderX + 96
        @timer.x = Graphics.width - @timer.width
        @timer.viewport = @viewport
        @timer.z = 99998
      end
      curtime = $game_system.timer
      curtime = 0 if curtime < 0
      if curtime != @total_sec
        # Calculate total number of seconds
        @total_sec = curtime
        # Make a string for displaying the timer
        min = @total_sec / 60
        sec = @total_sec % 60
        @timer.text = _ISPRINTF("<ac>{1:02d}:{2:02d}", min, sec)
      end
      @timer.update
    elsif @timer
      @timer.visible = false
    end
  end
end


==============================================================================
# Script: Sprite_Character
==============================================================================
#===============================================================================
#
#===============================================================================
class BushBitmap
  def initialize(bitmap, isTile, depth)
    @bitmaps  = []
    @bitmap   = bitmap
    @isTile   = isTile
    @isBitmap = @bitmap.is_a?(Bitmap)
    @depth    = depth
  end

  def dispose
    @bitmaps.each { |b| b&.dispose }
  end

  def bitmap
    thisBitmap = (@isBitmap) ? @bitmap : @bitmap.bitmap
    current = (@isBitmap) ? 0 : @bitmap.currentIndex
    if !@bitmaps[current]
      if @isTile
        @bitmaps[current] = pbBushDepthTile(thisBitmap, @depth)
      else
        @bitmaps[current] = pbBushDepthBitmap(thisBitmap, @depth)
      end
    end
    return @bitmaps[current]
  end

  def pbBushDepthBitmap(bitmap, depth)
    ret = Bitmap.new(bitmap.width, bitmap.height)
    charheight = ret.height / 4
    cy = charheight - depth - 2
    4.times do |i|
      y = i * charheight
      if cy >= 0
        ret.blt(0, y, bitmap, Rect.new(0, y, ret.width, cy))
        ret.blt(0, y + cy, bitmap, Rect.new(0, y + cy, ret.width, 2), 170)
      end
      ret.blt(0, y + cy + 2, bitmap, Rect.new(0, y + cy + 2, ret.width, 2), 85) if cy + 2 >= 0
    end
    return ret
  end

  def pbBushDepthTile(bitmap, depth)
    ret = Bitmap.new(bitmap.width, bitmap.height)
    charheight = ret.height
    cy = charheight - depth - 2
    y = charheight
    if cy >= 0
      ret.blt(0, y, bitmap, Rect.new(0, y, ret.width, cy))
      ret.blt(0, y + cy, bitmap, Rect.new(0, y + cy, ret.width, 2), 170)
    end
    ret.blt(0, y + cy + 2, bitmap, Rect.new(0, y + cy + 2, ret.width, 2), 85) if cy + 2 >= 0
    return ret
  end
end

#===============================================================================
#
#===============================================================================
class Sprite_Character < RPG::Sprite
  attr_accessor :character

  def initialize(viewport, character = nil)
    super(viewport)
    @character = character
    @old_bush_depth = 0
    @spriteoffset = false
    if !character || character == $game_player || (character.name[/reflection/i] rescue false)
      @reflection = Sprite_Reflection.new(self, viewport)
    end
    @surfbase = Sprite_SurfBase.new(self, viewport) if character == $game_player
    self.zoom_x = TilemapRenderer::ZOOM_X
    self.zoom_y = TilemapRenderer::ZOOM_Y
    update
  end

  def dispose
    @bushbitmap&.dispose
    @bushbitmap = nil
    @charbitmap&.dispose
    @charbitmap = nil
    @reflection&.dispose
    @reflection = nil
    @surfbase&.dispose
    @surfbase = nil
    @character = nil
    super
  end

  #-----------------------------------------------------------------------------

  def visible=(value)
    super(value)
    @reflection.visible = value if @reflection
  end

  # Used by class Sprite_Reflection.
  def ground_y
    return @character.screen_y_ground
  end

  def source_frame_x
    return @character.pattern
  end

  def source_frame_y
    return (@character.direction - 2) / 2
  end

  def screen_x
    ret = @character.screen_x
    ret = ((ret - (Graphics.width / 2)) * TilemapRenderer::ZOOM_X) + (Graphics.width / 2) if TilemapRenderer::ZOOM_X != 1
    return ret
  end

  def screen_y
    ret = @character.screen_y
    ret = ((ret - (Graphics.height / 2)) * TilemapRenderer::ZOOM_Y) + (Graphics.height / 2) if TilemapRenderer::ZOOM_Y != 1
    return ret
  end

  def screen_z
    return @character.screen_z(@ch)
  end

  def bush_depth
    return @character.bush_depth
  end

  #-----------------------------------------------------------------------------

  def refresh_graphic
    return if @tile_id == @character.tile_id &&
              @character_name == @character.character_name &&
              @character_hue == @character.character_hue &&
              @old_bush_depth == @character.bush_depth
    @tile_id        = @character.tile_id
    @character_name = @character.character_name
    @character_hue  = @character.character_hue
    @old_bush_depth = @character.bush_depth
    @charbitmap&.dispose
    @charbitmap = nil
    @bushbitmap&.dispose
    @bushbitmap = nil
    if @tile_id >= TilemapRenderer::TILESET_START_ID
      set_tile_graphic
    elsif @character_name != ""
      set_charset_graphic
    else
      self.bitmap = nil
      @cw = 0
      @ch = 0
      @reflection&.update
    end
    @character.sprite_size = [@cw, @ch]
  end

  def set_tile_graphic
    @charbitmap = pbGetTileBitmap(@character.map.tileset_name, @tile_id,
                                  @character_hue, @character.width, @character.height)
    @charbitmapAnimated = false
    @spriteoffset = false
    @cw = Game_Map::TILE_WIDTH * @character.width
    @ch = Game_Map::TILE_HEIGHT * @character.height
    self.src_rect.set(0, 0, @cw, @ch)
    self.ox = @cw / 2
    self.oy = @ch
  end

  def set_charset_graphic
    @charbitmap = AnimatedBitmap.new(
      "Graphics/Characters/" + @character_name, @character_hue
    )
    RPG::Cache.retain("Graphics/Characters/", @character_name, @character_hue) if @character == $game_player
    @charbitmapAnimated = true
    @spriteoffset = @character_name[/offset/i]
    @cw = @charbitmap.width / 4
    @ch = @charbitmap.height / 4
    self.ox = @cw / 2
  end

  #-----------------------------------------------------------------------------

  def update
    return if @character.is_a?(Game_Event) && !@character.should_update?
    super
    refresh_graphic   # Check if it has changed, and changes it if so
    return if !@charbitmap
    @charbitmap.update if @charbitmapAnimated
    # Update graphic
    update_bitmap   # For bush bitmaps and animated charbitmaps
    update_charset_frame
    # Update position
    update_charset_offset
    self.x = screen_x
    self.y = screen_y
    self.z = screen_z
    # Update appearance
    update_visibility
    self.opacity = @character.opacity
    self.blend_type = @character.blend_type
    update_tone
    # Update extra animation
    start_pending_animation
    # Update child graphics
    update_child_graphics
  end

  #-----------------------------------------------------------------------------

  private

  # Update animated bitmap, and alternate between bitmaps depending on whether
  # self has a bush depth (i.e. it makes the bottom few pixels transparent).
  def update_bitmap
    bushdepth = bush_depth
    if bushdepth == 0
      # Not in a bush, just update self's bitmap
      self.bitmap = (@charbitmapAnimated) ? @charbitmap.bitmap : @charbitmap
      return
    end
    # Make and use a bush bitmap
    @bushbitmap = BushBitmap.new(@charbitmap, (@tile_id >= TilemapRenderer::TILESET_START_ID), bushdepth) if !@bushbitmap
    self.bitmap = @bushbitmap.bitmap
  end

  def update_visibility
    self.visible = !@character.transparent
  end

  def update_charset_frame
    return if @tile_id > 0   # Is using a tile
    sx = source_frame_x * @cw
    sy = source_frame_y * @ch
    self.src_rect.set(sx, sy, @cw, @ch)
    self.oy = (@spriteoffset rescue false) ? @ch - 16 : @ch
  end

  def update_charset_offset
    return if @tile_id > 0   # Is using a tile
    self.oy -= @character.bob_height   # For the player when surfing/diving
  end

  def update_tone
    return if !self.visible
    if @character.is_a?(Game_Event) && @character.name[/regulartone/i]
      self.tone.set(0, 0, 0, 0)
      return
    end
    pbDayNightTint(self)
  end

  def start_pending_animation
    return if !@character.animation_id || @character.animation_id == 0
    animation = $data_animations[@character.animation_id]
    animation(animation, true, @character.animation_height || 3, @character.animation_regular_tone || false)
    @character.animation_id = 0
  end

  def update_child_graphics
    @reflection&.update
    @surfbase&.update
  end
end

==============================================================================
# Script: Sprite_Reflection
==============================================================================
class Sprite_Reflection
  attr_reader :visible

  def initialize(parent_sprite, viewport = nil)
    @parent_sprite = parent_sprite
    @sprite = nil
    @height = 0
    @fixedheight = false
    if @parent_sprite.character && @parent_sprite.character != $game_player &&
       @parent_sprite.character.name[/reflection\((\d+)\)/i]
      @height = $~[1].to_i || 0
      @fixedheight = true
    end
    @viewport = viewport
    @disposed = false
    update
  end

  def dispose
    return if @disposed
    @sprite&.dispose
    @sprite = nil
    @parent_sprite = nil
    @disposed = true
  end

  def disposed?
    return @disposed
  end

  def event
    return @parent_sprite.character
  end

  def visible=(value)
    @visible = value
    @sprite.visible = value if @sprite && !@sprite.disposed?
  end

  def update
    return if disposed?
    shouldShow = @parent_sprite.visible
    if !shouldShow
      # Just-in-time disposal of sprite
      if @sprite
        @sprite.dispose
        @sprite = nil
      end
      return
    end
    # Just-in-time creation of sprite
    @sprite = Sprite.new(@viewport) if !@sprite
    if @sprite
      x = @parent_sprite.x - (@parent_sprite.ox * TilemapRenderer::ZOOM_X)
      y = @parent_sprite.y - (@parent_sprite.oy * TilemapRenderer::ZOOM_Y)
      y -= Game_Map::TILE_HEIGHT * TilemapRenderer::ZOOM_Y if event.character_name[/offset/i]
      @height = $PokemonGlobal.bridge if !@fixedheight
      y += @height * TilemapRenderer::ZOOM_Y * Game_Map::TILE_HEIGHT / 2
      width  = @parent_sprite.src_rect.width
      height = @parent_sprite.src_rect.height
      @sprite.x        = x + ((width / 2) * TilemapRenderer::ZOOM_X)
      @sprite.y        = y + ((height + (height / 2)) * TilemapRenderer::ZOOM_Y)
      @sprite.ox       = width / 2
      @sprite.oy       = (height / 2) - 2   # Hard-coded 2 pixel shift up
      @sprite.oy       -= event.bob_height * 2
      @sprite.z        = @parent_sprite.ground_y - (Graphics.height / 2)
      @sprite.z        -= 1000   # Still water is -2000, map is 0 and above
      @sprite.z        += 1 if event == $game_player
      @sprite.zoom_x   = @parent_sprite.zoom_x
      if Settings::ANIMATE_REFLECTIONS && !GameData::MapMetadata.try_get(event.map_id)&.still_reflections
        @sprite.zoom_x   += 0.05 * @sprite.zoom_x * Math.sin(2 * Math::PI * System.uptime)
      end
      @sprite.zoom_y   = @parent_sprite.zoom_y
      @sprite.angle    = 180.0
      @sprite.mirror   = true
      @sprite.bitmap   = @parent_sprite.bitmap
      @sprite.tone     = @parent_sprite.tone
      if @height > 0
        @sprite.color   = Color.new(48, 96, 160, 255)   # Dark still water
        @sprite.opacity = @parent_sprite.opacity
        @sprite.visible = !Settings::TIME_SHADING   # Can't time-tone a colored sprite
      else
        @sprite.color   = Color.new(224, 224, 224, 96)
        @sprite.opacity = @parent_sprite.opacity * 3 / 4
        @sprite.visible = true
      end
      @sprite.src_rect = @parent_sprite.src_rect
    end
  end
end

==============================================================================
# Script: Sprite_SurfBase
==============================================================================
class Sprite_SurfBase
  attr_reader :visible

  def initialize(parent_sprite, viewport = nil)
    @parent_sprite = parent_sprite
    @sprite = nil
    @viewport = viewport
    @disposed = false
    @surfbitmap = AnimatedBitmap.new("Graphics/Characters/base_surf")
    @divebitmap = AnimatedBitmap.new("Graphics/Characters/base_dive")
    RPG::Cache.retain("Graphics/Characters/base_surf")
    RPG::Cache.retain("Graphics/Characters/base_dive")
    @cws = @surfbitmap.width / 4
    @chs = @surfbitmap.height / 4
    @cwd = @divebitmap.width / 4
    @chd = @divebitmap.height / 4
    update
  end

  def dispose
    return if @disposed
    @sprite&.dispose
    @sprite = nil
    @parent_sprite = nil
    @surfbitmap.dispose
    @divebitmap.dispose
    @disposed = true
  end

  def disposed?
    return @disposed
  end

  def event
    return @parent_sprite.character
  end

  def visible=(value)
    @visible = value
    @sprite.visible = value if @sprite && !@sprite.disposed?
  end

  def update
    return if disposed?
    if !$PokemonGlobal.surfing && !$PokemonGlobal.diving
      # Just-in-time disposal of sprite
      if @sprite
        @sprite.dispose
        @sprite = nil
      end
      return
    end
    # Just-in-time creation of sprite
    @sprite = Sprite.new(@viewport) if !@sprite
    return if !@sprite
    if $PokemonGlobal.surfing
      @sprite.bitmap = @surfbitmap.bitmap
      cw = @cws
      ch = @chs
    elsif $PokemonGlobal.diving
      @sprite.bitmap = @divebitmap.bitmap
      cw = @cwd
      ch = @chd
    end
    sx = event.pattern_surf * cw
    sy = ((event.direction - 2) / 2) * ch
    @sprite.src_rect.set(sx, sy, cw, ch)
    if $game_temp.surf_base_coords
      spr_x = ((($game_temp.surf_base_coords[0] * Game_Map::REAL_RES_X) - event.map.display_x).to_f / Game_Map::X_SUBPIXELS).round
      spr_x += (Game_Map::TILE_WIDTH / 2)
      spr_x = ((spr_x - (Graphics.width / 2)) * TilemapRenderer::ZOOM_X) + (Graphics.width / 2) if TilemapRenderer::ZOOM_X != 1
      @sprite.x = spr_x
      spr_y = ((($game_temp.surf_base_coords[1] * Game_Map::REAL_RES_Y) - event.map.display_y).to_f / Game_Map::Y_SUBPIXELS).round
      spr_y += (Game_Map::TILE_HEIGHT / 2) + 16
      spr_y = ((spr_y - (Graphics.height / 2)) * TilemapRenderer::ZOOM_Y) + (Graphics.height / 2) if TilemapRenderer::ZOOM_Y != 1
      @sprite.y = spr_y
    else
      @sprite.x = @parent_sprite.x
      @sprite.y = @parent_sprite.y
    end
    @sprite.ox      = cw / 2
    @sprite.oy      = ch - 16   # Assume base needs offsetting
    @sprite.oy      -= event.bob_height
    @sprite.z       = event.screen_z(ch) - 1
    @sprite.zoom_x  = @parent_sprite.zoom_x
    @sprite.zoom_y  = @parent_sprite.zoom_y
    @sprite.tone    = @parent_sprite.tone
    @sprite.color   = @parent_sprite.color
    @sprite.opacity = @parent_sprite.opacity
  end
end


==============================================================================
# Script: Spriteset_Global
==============================================================================
class Spriteset_Global
  attr_reader :playersprite

  @@viewport2 = Viewport.new(0, 0, Settings::SCREEN_WIDTH, Settings::SCREEN_HEIGHT)
  @@viewport2.z = 200

  def initialize
    @map_id = $game_map&.map_id || 0
    @follower_sprites = FollowerSprites.new(Spriteset_Map.viewport)
    @playersprite = Sprite_Character.new(Spriteset_Map.viewport, $game_player)
    @weather = RPG::Weather.new(Spriteset_Map.viewport)
    @picture_sprites = []
    (1..100).each do |i|
      @picture_sprites.push(Sprite_Picture.new(@@viewport2, $game_screen.pictures[i]))
    end
    @timer_sprite = Sprite_Timer.new
    update
  end

  def dispose
    @follower_sprites.dispose
    @follower_sprites = nil
    @playersprite.dispose
    @playersprite = nil
    @weather.dispose
    @weather = nil
    @picture_sprites.each { |sprite| sprite.dispose }
    @picture_sprites.clear
    @timer_sprite.dispose
    @timer_sprite = nil
  end

  def update
    @follower_sprites.update
    @playersprite.update
    if @weather.type != $game_screen.weather_type
      @weather.fade_in($game_screen.weather_type, $game_screen.weather_max, $game_screen.weather_duration)
    end
    if @map_id != $game_map.map_id
      offsets = $map_factory.getRelativePos(@map_id, 0, 0, $game_map.map_id, 0, 0)
      if offsets == [0, 0]
        @weather.ox_offset = 0
        @weather.oy_offset = 0
      else
        @weather.ox_offset += offsets[0] * Game_Map::TILE_WIDTH
        @weather.oy_offset += offsets[1] * Game_Map::TILE_HEIGHT
      end
      @map_id = $game_map.map_id
    end
    @weather.ox = ($game_map.display_x / Game_Map::X_SUBPIXELS).round
    @weather.oy = ($game_map.display_y / Game_Map::Y_SUBPIXELS).round
    @weather.update
    @picture_sprites.each { |sprite| sprite.update }
    @timer_sprite.update
  end
end


