module MessageConfig
  LIGHT_TEXT_MAIN_COLOR    = Color.new(248, 248, 248)
  LIGHT_TEXT_SHADOW_COLOR  = Color.new(72, 80, 88)
  DARK_TEXT_MAIN_COLOR     = Color.new(80, 80, 88)
  DARK_TEXT_SHADOW_COLOR   = Color.new(160, 160, 168)
  MALE_TEXT_MAIN_COLOR     = Color.new(48, 80, 200)   # Used by message tag "\b"
  MALE_TEXT_SHADOW_COLOR   = Color.new(208, 208, 200)
  FEMALE_TEXT_MAIN_COLOR   = Color.new(224, 8, 8)   # Used by message tag "\r"
  FEMALE_TEXT_SHADOW_COLOR = Color.new(208, 208, 200)
  FONT_NAME                = "Power Green"
  FONT_SIZE                = 27
  FONT_Y_OFFSET            = 8
  SMALL_FONT_NAME          = "Power Green Small"
  SMALL_FONT_SIZE          = 21
  SMALL_FONT_Y_OFFSET      = 8
  TINY_FONT_SIZE           = 15
  TINY_FONT_Y_OFFSET       = 7
  NARROW_FONT_NAME         = "Power Green Narrow"
  NARROW_FONT_SIZE         = 27
  NARROW_FONT_Y_OFFSET     = 8
  # 0 = Pause cursor is displayed at end of text
  # 1 = Pause cursor is displayed at bottom right
  # 2 = Pause cursor is displayed at lower middle side
  CURSOR_POSITION          = 1
  WINDOW_OPACITY           = 255
  TEXT_SPEED               = nil   # Time in seconds between two characters
  @@systemFrame     = nil
  @@defaultTextSkin = nil
  @@textSpeed       = nil
  @@systemFont      = nil
  @@smallFont       = nil
  @@narrowFont      = nil

  module_function

  def pbDefaultSystemFrame
    if $PokemonSystem
      path = File.join("Graphics", "Windowskins", Settings::MENU_WINDOWSKINS[$PokemonSystem.frame])
      return pbResolveBitmap(path) || ""
    else
      path = File.join("Graphics", "Windowskins", Settings::MENU_WINDOWSKINS[0])
      return pbResolveBitmap(path) || ""
    end
  end

  def pbDefaultSpeechFrame
    if $PokemonSystem
      path = File.join("Graphics", "Windowskins", Settings::SPEECH_WINDOWSKINS[$PokemonSystem.textskin])
      return pbResolveBitmap(path) || ""
    else
      path = File.join("Graphics", "Windowskins", Settings::SPEECH_WINDOWSKINS[0])
      return pbResolveBitmap(path) || ""
    end
  end

  def pbDefaultWindowskin
    skin = ($data_system) ? $data_system.windowskin_name : nil
    if skin && skin != ""
      path = File.join("Graphics", "Windowskins", skin)
      skin = pbResolveBitmap(path) || ""
    end
    path = File.join("Graphics", "System", "Window")
    skin = pbResolveBitmap(path) if nil_or_empty?(skin)
    path = File.join("Graphics", "Windowskins", "001-Blue01")
    skin = pbResolveBitmap(path) if nil_or_empty?(skin)
    return skin || ""
  end

  def pbGetSystemFrame
    if !@@systemFrame
      skin = MessageConfig.pbDefaultSystemFrame
      skin = MessageConfig.pbDefaultWindowskin if nil_or_empty?(skin)
      @@systemFrame = skin || ""
    end
    return @@systemFrame
  end

  def pbGetSpeechFrame
    if !@@defaultTextSkin
      skin = MessageConfig.pbDefaultSpeechFrame
      skin = MessageConfig.pbDefaultWindowskin if nil_or_empty?(skin)
      @@defaultTextSkin = skin || ""
    end
    return @@defaultTextSkin
  end

  def pbSetSystemFrame(value)
    @@systemFrame = pbResolveBitmap(value) || ""
  end

  def pbSetSpeechFrame(value)
    @@defaultTextSkin = pbResolveBitmap(value) || ""
  end

  #-----------------------------------------------------------------------------

  def pbDefaultTextSpeed
    return ($PokemonSystem) ? pbSettingToTextSpeed($PokemonSystem.textspeed) : pbSettingToTextSpeed(nil)
  end

  def pbGetTextSpeed
    @@textSpeed = pbDefaultTextSpeed if !@@textSpeed
    return @@textSpeed
  end

  def pbSetTextSpeed(value)
    @@textSpeed = value
  end

  # Text speed is the delay in seconds between two adjacent characters being
  # shown.
  def pbSettingToTextSpeed(speed)
    case speed
    when 0 then return 4 / 80.0   # Slow
    when 1 then return 2 / 80.0   # Medium
    when 2 then return 1 / 80.0   # Fast
    when 3 then return 0          # Instant
    end
    return TEXT_SPEED || (2 / 80.0)   # Normal
  end

  #-----------------------------------------------------------------------------

  def pbDefaultSystemFontName
    return MessageConfig.pbTryFonts(FONT_NAME)
  end

  def pbDefaultSmallFontName
    return MessageConfig.pbTryFonts(SMALL_FONT_NAME)
  end

  def pbDefaultNarrowFontName
    return MessageConfig.pbTryFonts(NARROW_FONT_NAME)
  end

  def pbGetSystemFontName
    @@systemFont = pbDefaultSystemFontName if !@@systemFont
    return @@systemFont
  end

  def pbGetSmallFontName
    @@smallFont = pbDefaultSmallFontName if !@@smallFont
    return @@smallFont
  end

  def pbGetNarrowFontName
    @@narrowFont = pbDefaultNarrowFontName if !@@narrowFont
    return @@narrowFont
  end

  def pbSetSystemFontName(value)
    @@systemFont = MessageConfig.pbTryFonts(value)
    @@systemFont = MessageConfig.pbDefaultSystemFontName if @@systemFont == ""
  end

  def pbSetSmallFontName(value)
    @@smallFont = MessageConfig.pbTryFonts(value)
    @@smallFont = MessageConfig.pbDefaultSmallFontName if @@smallFont == ""
  end

  def pbSetNarrowFontName(value)
    @@narrowFont = MessageConfig.pbTryFonts(value)
    @@narrowFont = MessageConfig.pbDefaultNarrowFontName if @@narrowFont == ""
  end

  def pbTryFonts(*args)
    args.each do |a|
      next if !a
      case a
      when String
        return a if Font.exist?(a)
      when Array
        a.each do |aa|
          ret = MessageConfig.pbTryFonts(aa)
          return ret if ret != ""
        end
      end
    end
    return ""
  end
end

#===============================================================================
# Position a window.
#===============================================================================
def pbBottomRight(window)
  window.x = Graphics.width - window.width
  window.y = Graphics.height - window.height
end

def pbBottomLeft(window)
  window.x = 0
  window.y = Graphics.height - window.height
end

def pbBottomLeftLines(window, lines, width = nil)
  window.x = 0
  window.width = width || Graphics.width
  window.height = (window.borderY rescue 32) + (lines * 32)
  window.y = Graphics.height - window.height
end

def pbPositionFaceWindow(facewindow, msgwindow)
  return if !facewindow
  if msgwindow
    if facewindow.height <= msgwindow.height
      facewindow.y = msgwindow.y
    else
      facewindow.y = msgwindow.y + msgwindow.height - facewindow.height
    end
    facewindow.x = Graphics.width - facewindow.width
    msgwindow.x = 0
    msgwindow.width = Graphics.width - facewindow.width
  else
    facewindow.height = Graphics.height if facewindow.height > Graphics.height
    facewindow.x = 0
    facewindow.y = 0
  end
end

def pbPositionNearMsgWindow(cmdwindow, msgwindow, side)
  return if !cmdwindow
  if msgwindow
    height = [cmdwindow.height, Graphics.height - msgwindow.height].min
    cmdwindow.height = height if cmdwindow.height != height
    cmdwindow.y = msgwindow.y - cmdwindow.height
    if cmdwindow.y < 0
      cmdwindow.y = msgwindow.y + msgwindow.height
      if cmdwindow.y + cmdwindow.height > Graphics.height
        cmdwindow.y = msgwindow.y - cmdwindow.height
      end
    end
    case side
    when :left
      cmdwindow.x = msgwindow.x
    when :right
      cmdwindow.x = msgwindow.x + msgwindow.width - cmdwindow.width
    else
      cmdwindow.x = msgwindow.x + msgwindow.width - cmdwindow.width
    end
  else
    cmdwindow.height = Graphics.height if cmdwindow.height > Graphics.height
    cmdwindow.x = 0
    cmdwindow.y = 0
  end
end

# internal function
def pbRepositionMessageWindow(msgwindow, linecount = 2)
  msgwindow.height = (32 * linecount) + msgwindow.borderY
  msgwindow.y = (Graphics.height) - (msgwindow.height)
  case $game_system&.message_position || 2
  when 0   # top
    msgwindow.y = 0
  when 1   # middle
    msgwindow.y = (Graphics.height - msgwindow.height) / 2
  when 2   # bottom
    msgwindow.y = Graphics.height - msgwindow.height
  end
  msgwindow.opacity = 0 if ($game_system&.message_frame || 0) != 0
end

# internal function
def pbUpdateMsgWindowPos(msgwindow, event, eventChanged = false)
  if event
    if eventChanged
      msgwindow.resizeToFit2(msgwindow.text, Graphics.width * 2 / 3, msgwindow.height)
    end
    msgwindow.y = event.screen_y - 48 - msgwindow.height
    msgwindow.y = event.screen_y + 24 if msgwindow.y < 0
    msgwindow.x = event.screen_x - (msgwindow.width / 2)
    msgwindow.x = 0 if msgwindow.x < 0
    if msgwindow.x > Graphics.width - msgwindow.width
      msgwindow.x = Graphics.width - msgwindow.width
    end
  else
    curwidth = msgwindow.width
    if curwidth != Graphics.width
      msgwindow.width = Graphics.width
      msgwindow.width = Graphics.width
    end
  end
end

#===============================================================================
# Determine the colour of a background.
#===============================================================================
def isDarkBackground(background, rect = nil)
  return true if !background || background.disposed?
  rect = background.rect if !rect
  return true if rect.width <= 0 || rect.height <= 0
  xSeg = (rect.width / 16)
  xLoop = (xSeg == 0) ? 1 : 16
  xStart = (xSeg == 0) ? rect.x + (rect.width / 2) : rect.x + (xSeg / 2)
  ySeg = (rect.height / 16)
  yLoop = (ySeg == 0) ? 1 : 16
  yStart = (ySeg == 0) ? rect.y + (rect.height / 2) : rect.y + (ySeg / 2)
  count = 0
  y = yStart
  r = g = b = 0
  yLoop.times do
    x = xStart
    xLoop.times do
      clr = background.get_pixel(x, y)
      if clr.alpha != 0
        r += clr.red
        g += clr.green
        b += clr.blue
        count += 1
      end
      x += xSeg
    end
    y += ySeg
  end
  return true if count == 0
  r /= count
  g /= count
  b /= count
  return ((r * 0.299) + (g * 0.587) + (b * 0.114)) < 160
end

def isDarkWindowskin(windowskin)
  return true if !windowskin || windowskin.disposed?
  if windowskin.width == 192 && windowskin.height == 128
    return isDarkBackground(windowskin, Rect.new(0, 0, 128, 128))
  elsif windowskin.width == 128 && windowskin.height == 128
    return isDarkBackground(windowskin, Rect.new(0, 0, 64, 64))
  elsif windowskin.width == 96 && windowskin.height == 48
    return isDarkBackground(windowskin, Rect.new(32, 16, 16, 16))
  else
    clr = windowskin.get_pixel(windowskin.width / 2, windowskin.height / 2)
    return ((clr.red * 0.299) + (clr.green * 0.587) + (clr.blue * 0.114)) < 160
  end
end

#===============================================================================
# Determine which text colours to use based on the darkness of the background.
#===============================================================================
def get_text_colors_for_windowskin(windowskin, color, isDarkSkin, no_ctag = true)
  if windowskin && !windowskin.disposed? && windowskin.width == 128 && windowskin.height == 128
    color = 0 if color >= 32
    x = 64 + ((color % 8) * 8)
    y = 96 + ((color / 8) * 8)
    pixel = windowskin.get_pixel(x, y)
    return no_ctag ? [pixel, pixel.get_contrast_color] : shadowc3tag(pixel, pixel.get_contrast_color)
  end
    # Base color, shadow color (these are reversed on dark windowskins)
    # Values in arrays are RGB numbers
    textcolors = [
      [  0, 112, 248], [120, 184, 232],   # 1  Blue
      [232,  32,  16], [248, 168, 184],   # 2  Red
      [ 96, 176,  72], [174, 208, 144],   # 3  Green
      [ 72, 216, 216], [168, 224, 224],   # 4  Cyan
      [208,  56, 184], [232, 160, 224],   # 5  Magenta
      [232, 208,  32], [248, 232, 136],   # 6  Yellow
      [160, 160, 168], [208, 208, 216],   # 7  Gray
      [240, 240, 248], [120, 120, 128],   # 8  White
      [114,  64, 232], [184, 168, 224],   # 9  Purple
      [248, 152,  24], [248, 200, 152],   # 10 Orange
      MessageConfig::DARK_TEXT_MAIN_COLOR,
      MessageConfig::DARK_TEXT_SHADOW_COLOR,   # 11 Dark default
      MessageConfig::LIGHT_TEXT_MAIN_COLOR,
      MessageConfig::LIGHT_TEXT_SHADOW_COLOR,   # 12 Light default
      [120, 120, 128], [240, 240, 248],   # 13  White with black background
      [138,  90,  43], [216, 184, 154],   # 14 Brown
      [240,  96, 144], [248, 184, 200],   # 15 Pink
      [152, 224,  32], [216, 240, 168],   # 16 Lime
      [ 32,  56, 112], [144, 168, 216],   # 17 Navy
      [140,  32,  32], [216, 160, 160],   # 18 Maroon
      [ 32, 128, 112], [152, 200, 184],   # 19 Teal
      [ 88, 168, 240], [184, 216, 248],   # 20 Sky Blue
      [128, 128,  32], [200, 200, 160],   # 21 Olive
      [224, 200, 160], [248, 232, 208],   # 22 Beige
      [184, 144, 224], [224, 208, 248],   # 23 Lavender
      [216, 176,  32], [240, 224, 168],   # 24 Gold
      [240, 160,  32], [248, 216, 168],   # 25 Amber
      [248, 160, 144], [248, 216, 200],   # 26 Peach
      [200,  32,  48], [240, 160, 168],   # 27 Crimson
      [248, 120,  88], [248, 200, 184],   # 28 Coral
      [ 64,  64, 168], [184, 184, 232],   # 29 Indigo
      [ 96, 120, 160], [192, 208, 232],   # 30 Slate Blue
      [ 96, 216, 168], [200, 240, 224],   # 31 Mint
      [ 32,  96,  32], [152, 192, 152],   # 32 Forest Green
      [112,  32,  64], [200, 160, 184],   # 33 Plum
      [168, 144, 120], [224, 208, 200],   # 34 Warm Gray
      [128, 144, 168], [208, 216, 232]    # 35 Cool Gray
    ]
    if color == 0 || color > textcolors.length / 2   # No special colour, use default
      if isDarkSkin   # Dark background, light text
        return no_ctag ? [MessageConfig::LIGHT_TEXT_MAIN_COLOR, MessageConfig::LIGHT_TEXT_SHADOW_COLOR] : shadowc3tag(MessageConfig::LIGHT_TEXT_MAIN_COLOR, MessageConfig::LIGHT_TEXT_SHADOW_COLOR)
        # return shadowc3tag(MessageConfig::LIGHT_TEXT_MAIN_COLOR, MessageConfig::LIGHT_TEXT_SHADOW_COLOR) 
      end
      # Light background, dark text
      return no_ctag ? [MessageConfig::DARK_TEXT_MAIN_COLOR, MessageConfig::DARK_TEXT_SHADOW_COLOR] : shadowc3tag(MessageConfig::DARK_TEXT_MAIN_COLOR, MessageConfig::DARK_TEXT_SHADOW_COLOR)
      # return shadowc3tag(MessageConfig::DARK_TEXT_MAIN_COLOR, MessageConfig::DARK_TEXT_SHADOW_COLOR)
    end
    # Special colour as listed above
    if isDarkSkin && color != 12   # Dark background, light text
      if textcolors[2 * (color - 1)].is_a?(Color)
        if no_ctag
          return textcolors[(2 * (color - 1)) + 1], textcolors[2 * (color - 1)]
        else
          return shadowc3tag(textcolors[(2 * (color - 1)) + 1], textcolors[2 * (color - 1)])
        end
      else
        if no_ctag
          return Color.new(*textcolors[(2 * (color - 1)) + 1]), Color.new(*textcolors[2 * (color - 1)])
        else
          return shadowc3tag(Color.new(*textcolors[(2 * (color - 1)) + 1]), Color.new(*textcolors[2 * (color - 1)]))
        end
      end
    end
    # Light background, dark text
    if textcolors[2 * (color - 1)].is_a?(Color)
      if no_ctag
        return textcolors[2 * (color - 1)], textcolors[(2 * (color - 1)) + 1]
      end
      return shadowc3tag(textcolors[2 * (color - 1)], textcolors[(2 * (color - 1)) + 1])
    end
    if no_ctag
      return Color.new(*textcolors[2 * (color - 1)]), Color.new(*textcolors[(2 * (color - 1)) + 1])
    end
    return shadowc3tag(Color.new(*textcolors[2 * (color - 1)]), Color.new(*textcolors[(2 * (color - 1)) + 1]))
end

def getDefaultTextColors(windowskin)
  # VX windowskin
  if windowskin && !windowskin.disposed? && windowskin.width == 128 && windowskin.height == 128
    color = windowskin.get_pixel(64, 96)
    shadow = nil
    isDark = (color.red + color.green + color.blue) / 3 < 128
    if isDark
      shadow = Color.new(color.red + 64, color.green + 64, color.blue + 64)
    else
      shadow = Color.new(color.red - 64, color.green - 64, color.blue - 64)
    end
    return color, shadow
  end
  # No windowskin or not a VX windowskin
  if isDarkWindowskin(windowskin)
    return MessageConfig::LIGHT_TEXT_MAIN_COLOR, MessageConfig::LIGHT_TEXT_SHADOW_COLOR   # White
  end
  return MessageConfig::DARK_TEXT_MAIN_COLOR, MessageConfig::DARK_TEXT_SHADOW_COLOR   # Dark gray
end

#===============================================================================
# Makes sure a bitmap exists.
#===============================================================================
def pbDoEnsureBitmap(bitmap, dwidth, dheight)
  if !bitmap || bitmap.disposed? || bitmap.width < dwidth || bitmap.height < dheight
    oldfont = (bitmap && !bitmap.disposed?) ? bitmap.font : nil
    bitmap&.dispose
    bitmap = Bitmap.new([1, dwidth].max, [1, dheight].max)
    (oldfont) ? bitmap.font = oldfont : pbSetSystemFont(bitmap)
    bitmap.font.shadow = false if bitmap.font.respond_to?("shadow")
  end
  return bitmap
end

#===============================================================================
# Set a bitmap's font.
#===============================================================================
# Sets a bitmap's font to the system font.
def pbSetSystemFont(bitmap)
  bitmap.font.name = MessageConfig.pbGetSystemFontName
  bitmap.font.size = MessageConfig::FONT_SIZE
  bitmap.text_offset_y = MessageConfig::FONT_Y_OFFSET
end

# Sets a bitmap's font to the system small font.
def pbSetSmallFont(bitmap)
  bitmap.font.name = MessageConfig.pbGetSmallFontName
  bitmap.font.size = MessageConfig::SMALL_FONT_SIZE
  bitmap.text_offset_y = MessageConfig::SMALL_FONT_Y_OFFSET
end

def pbSetTinyFont(bitmap)
  bitmap.font.name = MessageConfig.pbGetSmallFontName
  bitmap.font.size = MessageConfig::TINY_FONT_SIZE
  bitmap.text_offset_y = MessageConfig::TINY_FONT_Y_OFFSET
end

# Sets a bitmap's font to the system narrow font.
def pbSetNarrowFont(bitmap)
  bitmap.font.name = MessageConfig.pbGetNarrowFontName
  bitmap.font.size = MessageConfig::NARROW_FONT_SIZE
  bitmap.text_offset_y = MessageConfig::NARROW_FONT_Y_OFFSET
end

#===============================================================================
# Blend colours, set the colour of all bitmaps in a sprite hash.
#===============================================================================
def pbAlphaBlend(dstColor, srcColor)
  r = (255 * (srcColor.red - dstColor.red) / 255) + dstColor.red
  g = (255 * (srcColor.green - dstColor.green) / 255) + dstColor.green
  b = (255 * (srcColor.blue - dstColor.blue) / 255) + dstColor.blue
  a = (255 * (srcColor.alpha - dstColor.alpha) / 255) + dstColor.alpha
  return Color.new(r, g, b, a)
end

def pbSrcOver(dstColor, srcColor)
  er = srcColor.red * srcColor.alpha / 255
  eg = srcColor.green * srcColor.alpha / 255
  eb = srcColor.blue * srcColor.alpha / 255
  iea = 255 - srcColor.alpha
  cr = dstColor.red * dstColor.alpha / 255
  cg = dstColor.green * dstColor.alpha / 255
  cb = dstColor.blue * dstColor.alpha / 255
  ica = 255 - dstColor.alpha
  a = 255 - ((iea * ica) / 255)
  r = ((iea * cr) / 255) + er
  g = ((iea * cg) / 255) + eg
  b = ((iea * cb) / 255) + eb
  r = (a == 0) ? 0 : r * 255 / a
  g = (a == 0) ? 0 : g * 255 / a
  b = (a == 0) ? 0 : b * 255 / a
  return Color.new(r, g, b, a)
end

def pbSetSpritesToColor(sprites, color)
  return if !sprites || !color
  colors = {}
  sprites.each do |i|
    next if !i[1] || pbDisposed?(i[1])
    colors[i[0]] = i[1].color.clone
    i[1].color = pbSrcOver(i[1].color, color)
  end
  Graphics.update
  Input.update
  colors.each do |i|
    next if !sprites[i[0]]
    sprites[i[0]].color = i[1]
  end
end

#===============================================================================
# Update and dispose sprite hashes.
#===============================================================================
def using(window)
  begin
    yield if block_given?
  ensure
    window.dispose
  end
end

def pbUpdateSpriteHash(windows)
  windows&.each do |i|
    window = i[1]
    if window
      if window.is_a?(Sprite) || window.is_a?(Window)
        window.update if !pbDisposed?(window)
      elsif window.is_a?(Plane)
        begin
          window.update if !window.disposed?
        rescue NoMethodError
        end
      elsif window.respond_to?("update")
        begin
          window.update
        rescue RGSSError
        end
      end
    end
  end
end

# Disposes all objects in the specified hash.
def pbDisposeSpriteHash(sprites)
  return if !sprites
  sprites.each_key do |i|
    pbDisposeSprite(sprites, i)
  end
  sprites.clear
end

# Disposes the specified graphics object within the specified hash. Basically
# like:   sprites[id].dispose
def pbDisposeSprite(sprites, id)
  sprite = sprites[id]
  sprite.dispose if sprite && !pbDisposed?(sprite)
  sprites[id] = nil
end

def pbDisposed?(x)
  return true if !x
  return x.disposed? if !x.is_a?(Viewport)
  begin
    x.rect = x.rect
  rescue
    return true
  end
  return false
end

#===============================================================================
# Fades and window activations for sprite hashes.
#===============================================================================
def pbPushFade
  $game_temp.fadestate = [$game_temp.fadestate + 1, 0].max if $game_temp
end

def pbPopFade
  $game_temp.fadestate = [$game_temp.fadestate - 1, 0].max if $game_temp
end

def pbIsFaded?
  return ($game_temp) ? $game_temp.fadestate > 0 : false
end

# pbFadeOutIn(z) { block }
# Fades out the screen before a block is run and fades it back in after the
# block exits. z indicates the z-coordinate of the viewport used for this effect.
def pbFadeOutIn(z = 99999, nofadeout = false)
  duration = 0.4   # In seconds
  col = Color.new(0, 0, 0, 0)
  viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
  viewport.z = z
  timer_start = System.uptime
  loop do
    col.set(0, 0, 0, lerp(0, 255, duration, timer_start, System.uptime))
    viewport.color = col
    Graphics.update
    Input.update
    break if col.alpha == 255
  end
  pbPushFade
  begin
    val = 0
    val = yield if block_given?
    nofadeout = true if val == 99999   # Ugly hack used by Town Map in the Bag/Pokégear
  ensure
    pbPopFade
    if !nofadeout
      timer_start = System.uptime
      loop do
        col.set(0, 0, 0, lerp(255, 0, duration, timer_start, System.uptime))
        viewport.color = col
        Graphics.update
        Input.update
        break if col.alpha == 0
      end
    end
    viewport.dispose
  end
end

def pbFadeOutInWithUpdate(sprites, z = 99999, nofadeout = false)
  duration = 0.4   # In seconds
  col = Color.new(0, 0, 0, 0)
  viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
  viewport.z = z
  timer_start = System.uptime
  loop do
    col.set(0, 0, 0, lerp(0, 255, duration, timer_start, System.uptime))
    viewport.color = col
    pbUpdateSpriteHash(sprites)
    Graphics.update
    Input.update
    break if col.alpha == 255
  end
  pbPushFade
  begin
    yield if block_given?
  ensure
    pbPopFade
    if !nofadeout
      timer_start = System.uptime
      loop do
        col.set(0, 0, 0, lerp(255, 0, duration, timer_start, System.uptime))
        viewport.color = col
        pbUpdateSpriteHash(sprites)
        Graphics.update
        Input.update
        break if col.alpha == 0
      end
    end
    viewport.dispose
  end
end

# Similar to pbFadeOutIn, but pauses the music as it fades out.
# Requires scripts "Audio" (for bgm_pause) and "SpriteWindow" (for pbFadeOutIn).
def pbFadeOutInWithMusic(zViewport = 99999)
  playingBGS = $game_system.getPlayingBGS
  playingBGM = $game_system.getPlayingBGM
  $game_system.bgm_pause(1.0)
  $game_system.bgs_pause(1.0)
  pos = $game_system.bgm_position
  pbFadeOutIn(zViewport) do
    yield
    $game_system.bgm_position = pos
    $game_system.bgm_resume(playingBGM)
    $game_system.bgs_resume(playingBGS)
  end
end

def pbFadeOutAndHide(sprites)
  duration = 0.4   # In seconds
  col = Color.new(0, 0, 0, 0)
  visiblesprites = {}
  pbDeactivateWindows(sprites) do
    timer_start = System.uptime
    loop do
      col.alpha = lerp(0, 255, duration, timer_start, System.uptime)
      pbSetSpritesToColor(sprites, col)
      (block_given?) ? yield : pbUpdateSpriteHash(sprites)
      break if col.alpha == 255
    end
  end
  sprites.each do |i|
    next if !i[1]
    next if pbDisposed?(i[1])
    visiblesprites[i[0]] = true if i[1].visible
    i[1].visible = false
  end
  return visiblesprites
end

def pbFadeInAndShow(sprites, visiblesprites = nil)
  duration = 0.4   # In seconds
  col = Color.new(0, 0, 0, 0)
  if visiblesprites
    visiblesprites.each do |i|
      if i[1] && sprites[i[0]] && !pbDisposed?(sprites[i[0]])
        sprites[i[0]].visible = true
      end
    end
  end
  pbDeactivateWindows(sprites) do
    timer_start = System.uptime
    loop do
      col.alpha = lerp(255, 0, duration, timer_start, System.uptime)
      pbSetSpritesToColor(sprites, col)
      (block_given?) ? yield : pbUpdateSpriteHash(sprites)
      break if col.alpha == 0
    end
  end
end

# Restores which windows are active for the given sprite hash.
# _activeStatuses_ is the result of a previous call to pbActivateWindows
def pbRestoreActivations(sprites, activeStatuses)
  return if !sprites || !activeStatuses
  activeStatuses.each_key do |k|
    if sprites[k].is_a?(Window) && !pbDisposed?(sprites[k])
      sprites[k].active = activeStatuses[k] ? true : false
    end
  end
end

# Deactivates all windows. If a code block is given, deactivates all windows,
# runs the code in the block, and reactivates them.
def pbDeactivateWindows(sprites)
  if block_given?
    pbActivateWindow(sprites, nil) { yield }
  else
    pbActivateWindow(sprites, nil)
  end
end

# Activates a specific window of a sprite hash. _key_ is the key of the window
# in the sprite hash. If a code block is given, deactivates all windows except
# the specified window, runs the code in the block, and reactivates them.
def pbActivateWindow(sprites, key)
  return if !sprites
  activeStatuses = {}
  sprites.each do |i|
    if i[1].is_a?(Window) && !pbDisposed?(i[1])
      activeStatuses[i[0]] = i[1].active
      i[1].active = (i[0] == key)
    end
  end
  if block_given?
    begin
      yield
    ensure
      pbRestoreActivations(sprites, activeStatuses)
    end
    return {}
  else
    return activeStatuses
  end
end

#===============================================================================
# Create background planes for a sprite hash.
#===============================================================================
# Adds a background to the sprite hash.
# _planename_ is the hash key of the background.
# _background_ is a filename within the Graphics/UI/ folder and can be
#     an animated image.
# _viewport_ is a viewport to place the background in.
def addBackgroundPlane(sprites, planename, background, viewport = nil)
  sprites[planename] = AnimatedPlane.new(viewport)
  bitmapName = pbResolveBitmap("Graphics/UI/#{background}")
  if bitmapName.nil?
    # Plane should exist in any case
    sprites[planename].bitmap = nil
    sprites[planename].visible = false
  else
    sprites[planename].setBitmap(bitmapName)
    sprites.each_value do |spr|
      spr.windowskin = nil if spr.is_a?(Window)
    end
  end
end

# Adds a background to the sprite hash.
# _planename_ is the hash key of the background.
# _background_ is a filename within the Graphics/UI/ folder and can be
#       an animated image.
# _color_ is the color to use if the background can't be found.
# _viewport_ is a viewport to place the background in.
def addBackgroundOrColoredPlane(sprites, planename, background, color, viewport = nil)
  bitmapName = pbResolveBitmap("Graphics/UI/#{background}")
  if bitmapName.nil?
    # Plane should exist in any case
    sprites[planename] = ColoredPlane.new(color, viewport)
  else
    sprites[planename] = AnimatedPlane.new(viewport)
    sprites[planename].setBitmap(bitmapName)
    sprites.each_value do |spr|
      spr.windowskin = nil if spr.is_a?(Window)
    end
  end
end

#===============================================================================
# Ensure required method definitions.
#===============================================================================
module Graphics
  if !self.respond_to?("width")
    def self.width; return 640; end
  end

  if !self.respond_to?("height")
    def self.height; return 480; end
  end
end

#===============================================================================
# Ensure required method definitions.
#===============================================================================
if !defined?(_INTL)
  def _INTL(*args)
    string = args[0].clone
    (1...args.length).each { |i| string.gsub!(/\{#{i}\}/, args[i].to_s) }
    return string
  end
end

if !defined?(_ISPRINTF)
  def _ISPRINTF(*args)
    string = args[0].clone
    (1...args.length).each do |i|
      string.gsub!(/\{#{i}\:([^\}]+?)\}/) { |m| next sprintf("%" + $1, args[i]) }
    end
    return string
  end
end

if !defined?(_MAPINTL)
  def _MAPINTL(*args)
    string = args[1].clone
    (2...args.length).each { |i| string.gsub!(/\{#{i}\}/, args[i + 1].to_s) }
    return string
  end
end

==============================================================================
# Script: Window
==============================================================================
#===============================================================================
#
#===============================================================================
class WindowCursorRect < Rect
  def initialize(window)
    super(0, 0, 0, 0)
    @window = window
  end

  def empty
    return unless needs_update?(0, 0, 0, 0)
    set(0, 0, 0, 0)
  end

  def empty?
    return self.x == 0 && self.y == 0 && self.width == 0 && self.height == 0
  end

  def set(x, y, width, height)
    return unless needs_update?(x, y, width, height)
    super(x, y, width, height)
    @window.width = @window.width
  end

  def height=(value)
    super(value)
    @window.width = @window.width
  end

  def width=(value)
    super(value)
    @window.width = @window.width
  end

  def x=(value)
    super(value)
    @window.width = @window.width
  end

  def y=(value)
    super(value)
    @window.width = @window.width
  end

  #-----------------------------------------------------------------------------

  private

  def needs_update?(x, y, width, height)
    return self.x != x || self.y != y || self.width != width || self.height != height
  end
end

#===============================================================================
#
#===============================================================================
class Window
  attr_reader :tone
  attr_reader :color
  attr_reader :blend_type
  attr_reader :contents_blend_type
  attr_reader :viewport
  attr_reader :contents
  attr_reader :ox
  attr_reader :oy
  attr_reader :x
  attr_reader :y
  attr_reader :z
  attr_reader :width
  attr_reader :active
  attr_reader :pause
  attr_reader :height
  attr_reader :opacity
  attr_reader :back_opacity
  attr_reader :contents_opacity
  attr_reader :visible
  attr_reader :cursor_rect
  attr_reader :openness
  attr_reader :stretch

  def windowskin
    @_windowskin
  end

  def initialize(viewport = nil)
    @sprites = {}
    @spritekeys = [
      "back",
      "corner0", "side0", "scroll0",
      "corner1", "side1", "scroll1",
      "corner2", "side2", "scroll2",
      "corner3", "side3", "scroll3",
      "cursor", "contents", "pause"
    ]
    @sidebitmaps = [nil, nil, nil, nil]
    @cursorbitmap = nil
    @bgbitmap = nil
    @viewport = viewport
    @spritekeys.each do |i|
      @sprites[i] = Sprite.new(@viewport)
    end
    @disposed = false
    @tone = Tone.new(0, 0, 0)
    @color = Color.new(0, 0, 0, 0)
    @blankcontents = Bitmap.new(1, 1) # RGSS2 requires this
    @contents = @blankcontents
    @_windowskin = nil
    @rpgvx = false # Set to true to emulate RPGVX windows
    @x = 0
    @y = 0
    @width = 0
    @openness = 255
    @height = 0
    @ox = 0
    @oy = 0
    @z = 0
    @stretch = true
    @visible = true
    @active = true
    @blend_type = 0
    @contents_blend_type = 0
    @opacity = 255
    @back_opacity = 255
    @contents_opacity = 255
    @cursor_rect = WindowCursorRect.new(self)
    @cursoropacity = 255
    @pause = false
    @pauseopacity = 255
    @pauseframe = 0
    privRefresh(true)
  end

  def dispose
    if !self.disposed?
      @sprites.each do |i|
        i[1]&.dispose
        @sprites[i[0]] = nil
      end
      @sidebitmaps.each_with_index do |bitmap, i|
        bitmap&.dispose
        @sidebitmaps[i] = nil
      end
      @blankcontents.dispose
      @cursorbitmap&.dispose
      @backbitmap&.dispose
      @sprites.clear
      @sidebitmaps.clear
      @_windowskin = nil
      @_contents = nil
      @disposed = true
    end
  end

  def openness=(value)
    @openness = value
    @openness = 0 if @openness < 0
    @openness = 255 if @openness > 255
    privRefresh
  end

  def stretch=(value)
    @stretch = value
    privRefresh(true)
  end

  def visible=(value)
    @visible = value
    privRefresh
  end

  def viewport=(value)
    @viewport = value
    @spritekeys.each do |i|
      @sprites[i].dispose
      if @sprites[i].is_a?(Sprite)
        @sprites[i] = Sprite.new(@viewport)
      else
        @sprites[i] = nil
      end
    end
    privRefresh(true)
  end

  def z=(value)
    @z = value
    privRefresh
  end

  def disposed?
    return @disposed
  end

  def contents=(value)
    @contents = value
    privRefresh
  end

  def windowskin=(value)
    @_windowskin = value
    if value.is_a?(Bitmap) && !value.disposed? && value.width == 128
      @rpgvx = true
    else
      @rpgvx = false
    end
    privRefresh(true)
  end

  def ox=(value)
    @ox = value
    privRefresh
  end

  def active=(value)
    @active = value
    privRefresh(true)
  end

  def cursor_rect=(value)
    if value
      @cursor_rect.set(value.x, value.y, value.width, value.height)
    else
      @cursor_rect.empty
    end
  end

  def oy=(value)
    @oy = value
    privRefresh
  end

  def width=(value)
    @width = value
    privRefresh(true)
  end

  def height=(value)
    @height = value
    privRefresh(true)
  end

  def pause=(value)
    @pause = value
    @pauseopacity = 0 if !value
    privRefresh
  end

  def x=(value)
    @x = value
    privRefresh
  end

  def y=(value)
    @y = value
    privRefresh
  end

  def opacity=(value)
    @opacity = value
    @opacity = 0 if @opacity < 0
    @opacity = 255 if @opacity > 255
    privRefresh
  end

  def back_opacity=(value)
    @back_opacity = value
    @back_opacity = 0 if @back_opacity < 0
    @back_opacity = 255 if @back_opacity > 255
    privRefresh
  end

  def contents_opacity=(value)
    @contents_opacity = value
    @contents_opacity = 0 if @contents_opacity < 0
    @contents_opacity = 255 if @contents_opacity > 255
    privRefresh
  end

  def tone=(value)
    @tone = value
    privRefresh
  end

  def color=(value)
    @color = value
    privRefresh
  end

  def blend_type=(value)
    @blend_type = value
    privRefresh
  end

  def flash(color, duration)
    return if disposed?
    @sprites.each do |i|
      i[1].flash(color, duration)
    end
  end

  def update
    return if disposed?
    mustchange = false
    if @active
      cursor_time = System.uptime / 0.4
      if cursor_time.to_i.even?
        @cursoropacity = lerp(255, 128, 0.4, cursor_time % 2)
      else
        @cursoropacity = lerp(128, 255, 0.4, (cursor_time - 1) % 2)
      end
      mustchange = true if !@cursor_rect.empty?
    else
      mustchange = true if @cursoropacity != 128
      @cursoropacity = 128
    end
    if @pause
      @pauseframe = (System.uptime * 5).to_i % 4   # 4 frames, 5 frames per second
      @pauseopacity = [@pauseopacity + 64, 255].min
      mustchange = true
    end
    privRefresh if mustchange
    @sprites.each do |i|
      i[1].update
    end
  end

  #-----------------------------------------------------------------------------

  private

  def ensureBitmap(bitmap, dwidth, dheight)
    if !bitmap || bitmap.disposed? || bitmap.width < dwidth || bitmap.height < dheight
      bitmap&.dispose
      bitmap = Bitmap.new([1, dwidth].max, [1, dheight].max)
    end
    return bitmap
  end

  def tileBitmap(dstbitmap, dstrect, srcbitmap, srcrect)
    return if !srcbitmap || srcbitmap.disposed?
    left = dstrect.x
    top = dstrect.y
    y = 0
    loop do
      break unless y < dstrect.height
      x = 0
      loop do
        break unless x < dstrect.width
        dstbitmap.blt(x + left, y + top, srcbitmap, srcrect)
        x += srcrect.width
      end
      y += srcrect.height
    end
  end

  def privRefresh(change_bitmap = false)
    return if self.disposed?
    backopac = self.back_opacity * self.opacity / 255
    contopac = self.contents_opacity
    cursoropac = @cursoropacity * contopac / 255
    4.times do |i|
      @sprites["corner#{i}"].bitmap = @_windowskin
      @sprites["scroll#{i}"].bitmap = @_windowskin
    end
    @sprites["pause"].bitmap = @_windowskin
    @sprites["contents"].bitmap = @contents
    if @_windowskin && !@_windowskin.disposed?
      4.times do |i|
        @sprites["corner#{i}"].opacity = @opacity
        @sprites["corner#{i}"].tone = @tone
        @sprites["corner#{i}"].color = @color
        @sprites["corner#{i}"].blend_type = @blend_type
        @sprites["corner#{i}"].visible = @visible
        @sprites["side#{i}"].opacity = @opacity
        @sprites["side#{i}"].tone = @tone
        @sprites["side#{i}"].color = @color
        @sprites["side#{i}"].blend_type = @blend_type
        @sprites["side#{i}"].visible = @visible
        @sprites["scroll#{i}"].opacity = @opacity
        @sprites["scroll#{i}"].tone = @tone
        @sprites["scroll#{i}"].blend_type = @blend_type
        @sprites["scroll#{i}"].color = @color
        @sprites["scroll#{i}"].visible = @visible
      end
      ["back", "cursor", "pause", "contents"].each do |i|
        @sprites[i].color = @color
        @sprites[i].tone = @tone
        @sprites[i].blend_type = @blend_type
      end
      @sprites["contents"].blend_type = @contents_blend_type
      @sprites["back"].opacity = backopac
      @sprites["contents"].opacity = contopac
      @sprites["cursor"].opacity = cursoropac
      @sprites["pause"].opacity = @pauseopacity
      @sprites["back"].visible = @visible
      @sprites["contents"].visible = @visible && @openness == 255
      @sprites["pause"].visible = @visible && @pause
      @sprites["cursor"].visible = @visible && @openness == 255
      hascontents = (@contents && !@contents.disposed?)
      @sprites["scroll0"].visible = @visible && hascontents && @oy > 0
      @sprites["scroll1"].visible = @visible && hascontents && @ox > 0
      @sprites["scroll2"].visible = @visible && hascontents &&
                                    (@contents.width - @ox) > @width - 32
      @sprites["scroll3"].visible = @visible && hascontents &&
                                    (@contents.height - @oy) > @height - 32
    else
      4.times do |i|
        @sprites["corner#{i}"].visible = false
        @sprites["side#{i}"].visible = false
        @sprites["scroll#{i}"].visible = false
      end
      @sprites["contents"].visible = @visible && @openness == 255
      @sprites["contents"].color = @color
      @sprites["contents"].tone = @tone
      @sprites["contents"].blend_type = @contents_blend_type
      @sprites["contents"].opacity = contopac
      @sprites["back"].visible = false
      @sprites["pause"].visible = false
      @sprites["cursor"].visible = false
    end
    @sprites.each do |i|
      i[1].z = @z
    end
    if @rpgvx
      @sprites["cursor"].z = @z # For Compatibility
      @sprites["contents"].z = @z # For Compatibility
      @sprites["pause"].z = @z # For Compatibility
    else
      @sprites["cursor"].z = @z + 1 # For Compatibility
      @sprites["contents"].z = @z + 2 # For Compatibility
      @sprites["pause"].z = @z + 2 # For Compatibility
    end
    if @rpgvx
      trimX = 64
      trimY = 0
      backRect = Rect.new(0, 0, 64, 64)
      blindsRect = Rect.new(0, 64, 64, 64)
    else
      trimX = 128
      trimY = 0
      backRect = Rect.new(0, 0, 128, 128)
      blindsRect = nil
    end
    @sprites["corner0"].src_rect.set(trimX, trimY + 0, 16, 16)
    @sprites["corner1"].src_rect.set(trimX + 48, trimY + 0, 16, 16)
    @sprites["corner2"].src_rect.set(trimX, trimY + 48, 16, 16)
    @sprites["corner3"].src_rect.set(trimX + 48, trimY + 48, 16, 16)
    @sprites["scroll0"].src_rect.set(trimX + 24, trimY + 16, 16, 8) # up
    @sprites["scroll3"].src_rect.set(trimX + 24, trimY + 40, 16, 8) # down
    @sprites["scroll1"].src_rect.set(trimX + 16, trimY + 24, 8, 16) # left
    @sprites["scroll2"].src_rect.set(trimX + 40, trimY + 24, 8, 16) # right
    cursorX = trimX
    cursorY = trimY + 64
    sideRects = [
      Rect.new(trimX + 16, trimY + 0, 32, 16),
      Rect.new(trimX, trimY + 16, 16, 32),
      Rect.new(trimX + 48, trimY + 16, 16, 32),
      Rect.new(trimX + 16, trimY + 48, 32, 16)
    ]
    if @width > 32 && @height > 32
      @sprites["contents"].src_rect.set(@ox, @oy, @width - 32, @height - 32)
    else
      @sprites["contents"].src_rect.set(0, 0, 0, 0)
    end
    pauseRects = [
      trimX + 32, trimY + 64,
      trimX + 48, trimY + 64,
      trimX + 32, trimY + 80,
      trimX + 48, trimY + 80
    ]
    pauseWidth = 16
    pauseHeight = 16
    @sprites["pause"].src_rect.set(pauseRects[@pauseframe * 2],
                                   pauseRects[(@pauseframe * 2) + 1],
                                   pauseWidth,
                                   pauseHeight)
    @sprites["pause"].x = @x + (@width / 2) - (pauseWidth / 2)
    @sprites["pause"].y = @y + @height - 16 # 16 refers to skin margin
    @sprites["contents"].x = @x + 16
    @sprites["contents"].y = @y + 16
    @sprites["corner0"].x = @x
    @sprites["corner0"].y = @y
    @sprites["corner1"].x = @x + @width - 16
    @sprites["corner1"].y = @y
    @sprites["corner2"].x = @x
    @sprites["corner2"].y = @y + @height - 16
    @sprites["corner3"].x = @x + @width - 16
    @sprites["corner3"].y = @y + @height - 16
    @sprites["side0"].x = @x + 16
    @sprites["side0"].y = @y
    @sprites["side1"].x = @x
    @sprites["side1"].y = @y + 16
    @sprites["side2"].x = @x + @width - 16
    @sprites["side2"].y = @y + 16
    @sprites["side3"].x = @x + 16
    @sprites["side3"].y = @y + @height - 16
    @sprites["scroll0"].x = @x + (@width / 2) - 8
    @sprites["scroll0"].y = @y + 8
    @sprites["scroll1"].x = @x + 8
    @sprites["scroll1"].y = @y + (@height / 2) - 8
    @sprites["scroll2"].x = @x + @width - 16
    @sprites["scroll2"].y = @y + (@height / 2) - 8
    @sprites["scroll3"].x = @x + (@width / 2) - 8
    @sprites["scroll3"].y = @y + @height - 16
    @sprites["back"].x = @x + 2
    @sprites["back"].y = @y + 2
    @sprites["cursor"].x = @x + 16 + @cursor_rect.x
    @sprites["cursor"].y = @y + 16 + @cursor_rect.y
    if change_bitmap && @_windowskin && !@_windowskin.disposed?
      width = @cursor_rect.width
      height = @cursor_rect.height
      if width > 0 && height > 0
        cursorrects = [
          # sides
          Rect.new(cursorX + 2, cursorY + 0, 28, 2),
          Rect.new(cursorX + 0, cursorY + 2, 2, 28),
          Rect.new(cursorX + 30, cursorY + 2, 2, 28),
          Rect.new(cursorX + 2, cursorY + 30, 28, 2),
          # corners
          Rect.new(cursorX + 0, cursorY + 0, 2, 2),
          Rect.new(cursorX + 30, cursorY + 0, 2, 2),
          Rect.new(cursorX + 0, cursorY + 30, 2, 2),
          Rect.new(cursorX + 30, cursorY + 30, 2, 2),
          # back
          Rect.new(cursorX + 2, cursorY + 2, 28, 28)
        ]
        margin = 2
        fullmargin = 4
        @cursorbitmap = ensureBitmap(@cursorbitmap, width, height)
        @cursorbitmap.clear
        @sprites["cursor"].bitmap = @cursorbitmap
        @sprites["cursor"].src_rect.set(0, 0, width, height)
        rect = Rect.new(margin, margin, width - fullmargin, height - fullmargin)
        @cursorbitmap.stretch_blt(rect, @_windowskin, cursorrects[8])
        @cursorbitmap.blt(0, 0, @_windowskin, cursorrects[4])   # top left
        @cursorbitmap.blt(width - margin, 0, @_windowskin, cursorrects[5])   # top right
        @cursorbitmap.blt(0, height - margin, @_windowskin, cursorrects[6])   # bottom right
        @cursorbitmap.blt(width - margin, height - margin, @_windowskin, cursorrects[7])   # bottom left
        rect = Rect.new(margin, 0, width - fullmargin, margin)
        @cursorbitmap.stretch_blt(rect, @_windowskin, cursorrects[0])
        rect = Rect.new(0, margin, margin, height - fullmargin)
        @cursorbitmap.stretch_blt(rect, @_windowskin, cursorrects[1])
        rect = Rect.new(width - margin, margin, margin, height - fullmargin)
        @cursorbitmap.stretch_blt(rect, @_windowskin, cursorrects[2])
        rect = Rect.new(margin, height - margin, width - fullmargin, margin)
        @cursorbitmap.stretch_blt(rect, @_windowskin, cursorrects[3])
      else
        @sprites["cursor"].visible = false
        @sprites["cursor"].src_rect.set(0, 0, 0, 0)
      end
      4.times do |i|
        dwidth  = [0, 3].include?(i) ? @width - 32 : 16
        dheight = [0, 3].include?(i) ? 16 : @height - 32
        @sidebitmaps[i] = ensureBitmap(@sidebitmaps[i], dwidth, dheight)
        @sprites["side#{i}"].bitmap = @sidebitmaps[i]
        @sprites["side#{i}"].src_rect.set(0, 0, dwidth, dheight)
        @sidebitmaps[i].clear
        if sideRects[i].width > 0 && sideRects[i].height > 0
          @sidebitmaps[i].stretch_blt(@sprites["side#{i}"].src_rect, @_windowskin, sideRects[i])
        end
      end
      backwidth = @width - 4
      backheight = @height - 4
      if backwidth > 0 && backheight > 0
        @backbitmap = ensureBitmap(@backbitmap, backwidth, backheight)
        @sprites["back"].bitmap = @backbitmap
        @sprites["back"].src_rect.set(0, 0, backwidth, backheight)
        @backbitmap.clear
        if @stretch
          @backbitmap.stretch_blt(@sprites["back"].src_rect, @_windowskin, backRect)
        else
          tileBitmap(@backbitmap, @sprites["back"].src_rect, @_windowskin, backRect)
        end
        if blindsRect
          tileBitmap(@backbitmap, @sprites["back"].src_rect, @_windowskin, blindsRect)
        end
      else
        @sprites["back"].visible = false
        @sprites["back"].src_rect.set(0, 0, 0, 0)
      end
    end
    if @openness == 255
      @spritekeys.each do |k|
        sprite = @sprites[k]
        sprite.zoom_y = 1.0
      end
    else
      opn = @openness / 255.0
      @spritekeys.each do |k|
        sprite = @sprites[k]
        ratio = (@height <= 0) ? 0 : (sprite.y - @y) / @height.to_f
        sprite.zoom_y = opn
        sprite.oy = 0
        sprite.y = (@y + (@height / 2.0) + (@height * ratio * opn) - (@height / 2 * opn)).floor
      end
    end
    i = 0
    # Ensure Z order
    @spritekeys.each do |k|
      sprite = @sprites[k]
      y = sprite.y
      sprite.y = i
      sprite.oy = (sprite.zoom_y <= 0) ? 0 : (i - y) / sprite.zoom_y
    end
  end
end


==============================================================================
# Script: SpriteWindow
==============================================================================
#===============================================================================
# SpriteWindow is a class based on Window which emulates Window's functionality.
# This class is necessary in order to change the viewport of windows (with
# viewport=) and to make windows fade in and out (with tone=).
#===============================================================================
class SpriteWindow < Window
  attr_reader :tone
  attr_reader :color
  attr_reader :viewport
  attr_reader :contents
  attr_reader :ox
  attr_reader :oy
  attr_reader :x
  attr_reader :y
  attr_reader :z
  attr_reader :zoom_x
  attr_reader :zoom_y
  attr_reader :offset_x
  attr_reader :offset_y
  attr_reader :width
  attr_reader :active
  attr_reader :pause
  attr_reader :height
  attr_reader :opacity
  attr_reader :back_opacity
  attr_reader :contents_opacity
  attr_reader :visible
  attr_reader :cursor_rect
  attr_reader :contents_blend_type
  attr_reader :blend_type
  attr_reader :openness

  def windowskin
    @_windowskin
  end

  # Flags used to preserve compatibility with RGSS/RGSS2's version of Window.
  module CompatBits
    CORRECT_Z          = 1
    EXPAND_BACK        = 2
    SHOW_SCROLL_ARROWS = 4
    STRETCH_SIDES      = 8
    SHOW_PAUSE         = 16
    SHOW_CURSOR        = 32
  end

  attr_reader :compat
  attr_reader :skinformat
  attr_reader :skinrect

  def compat=(value)
    @compat = value
    privRefresh(true)
  end

  def initialize(viewport = nil)
    @sprites = {}
    @spritekeys = [
      "back",
      "corner0", "side0", "scroll0",
      "corner1", "side1", "scroll1",
      "corner2", "side2", "scroll2",
      "corner3", "side3", "scroll3",
      "cursor", "contents", "pause"
    ]
    @viewport = viewport
    @sidebitmaps = [nil, nil, nil, nil]
    @cursorbitmap = nil
    @bgbitmap = nil
    @spritekeys.each do |i|
      @sprites[i] = Sprite.new(@viewport)
    end
    @disposed = false
    @tone = Tone.new(0, 0, 0)
    @color = Color.new(0, 0, 0, 0)
    @blankcontents = Bitmap.new(1, 1) # RGSS2 requires this
    @contents = @blankcontents
    @_windowskin = nil
    @rpgvx = false
    @compat = CompatBits::EXPAND_BACK | CompatBits::STRETCH_SIDES
    @x = 0
    @y = 0
    @width = 0
    @height = 0
    @offset_x = 0
    @offset_y = 0
    @zoom_x = 1.0
    @zoom_y = 1.0
    @ox = 0
    @oy = 0
    @z = 0
    @stretch = true
    @visible = true
    @active = true
    @openness = 255
    @opacity = 255
    @back_opacity = 255
    @blend_type = 0
    @contents_blend_type = 0
    @contents_opacity = 255
    @cursor_rect = WindowCursorRect.new(self)
    @cursoropacity = 255
    @pause = false
    @pauseframe = 0
    @flash_duration = 0
    @pauseopacity = 0
    @skinformat = 0
    @skinrect = Rect.new(0, 0, 0, 0)
    @trim = [16, 16, 16, 16]
    privRefresh(true)
  end

  def dispose
    if !self.disposed?
      @sprites.each do |i|
        i[1]&.dispose
        @sprites[i[0]] = nil
      end
      @sidebitmaps.each_with_index do |bitmap, i|
        bitmap&.dispose
        @sidebitmaps[i] = nil
      end
      @blankcontents.dispose
      @cursorbitmap&.dispose
      @backbitmap&.dispose
      @sprites.clear
      @sidebitmaps.clear
      @_windowskin = nil
      @disposed = true
    end
  end

  def stretch=(value)
    @stretch = value
    privRefresh(true)
  end

  def visible=(value)
    @visible = value
    privRefresh
  end

  def viewport=(value)
    @viewport = value
    @spritekeys.each do |i|
      @sprites[i]&.dispose
      if @sprites[i].is_a?(Sprite)
        @sprites[i] = Sprite.new(@viewport)
      else
        @sprites[i] = nil
      end
    end
    privRefresh(true)
  end

  def z=(value)
    @z = value
    privRefresh
  end

  def disposed?
    return @disposed
  end

  def contents=(value)
    if @contents != value
      @contents = value
      privRefresh if @visible
    end
  end

  def ox=(value)
    if @ox != value
      @ox = value
      privRefresh if @visible
    end
  end

  def oy=(value)
    if @oy != value
      @oy = value
      privRefresh if @visible
    end
  end

  def active=(value)
    @active = value
    privRefresh(true)
  end

  def cursor_rect=(value)
    if value
      @cursor_rect.set(value.x, value.y, value.width, value.height)
    else
      @cursor_rect.empty
    end
  end

  def openness=(value)
    @openness = value
    @openness = 0 if @openness < 0
    @openness = 255 if @openness > 255
    privRefresh
  end

  def width=(value)
    @width = value
    privRefresh(true)
  end

  def height=(value)
    @height = value
    privRefresh(true)
  end

  def pause=(value)
    @pause = value
    @pauseopacity = 0 if !value
    privRefresh if @visible
  end

  def x=(value)
    @x = value
    privRefresh if @visible
  end

  def y=(value)
    @y = value
    privRefresh if @visible
  end

  def zoom_x=(value)
    @zoom_x = value
    privRefresh if @visible
  end

  def zoom_y=(value)
    @zoom_y = value
    privRefresh if @visible
  end

  def offset_x=(value)
    @x = value
    privRefresh if @visible
  end

  def offset_y=(value)
    @y = value
    privRefresh if @visible
  end

  def opacity=(value)
    @opacity = value
    @opacity = 0 if @opacity < 0
    @opacity = 255 if @opacity > 255
    privRefresh if @visible
  end

  def back_opacity=(value)
    @back_opacity = value
    @back_opacity = 0 if @back_opacity < 0
    @back_opacity = 255 if @back_opacity > 255
    privRefresh if @visible
  end

  def contents_opacity=(value)
    @contents_opacity = value
    @contents_opacity = 0 if @contents_opacity < 0
    @contents_opacity = 255 if @contents_opacity > 255
    privRefresh if @visible
  end

  def tone=(value)
    @tone = value
    privRefresh if @visible
  end

  def color=(value)
    @color = value
    privRefresh if @visible
  end

  def blend_type=(value)
    @blend_type = value
    privRefresh if @visible
  end

  # duration is in 1/20ths of a second
  def flash(color, duration)
    return if disposed?
    @flash_duration = duration / 20.0
    @flash_timer_start = System.uptime
    @sprites.each do |i|
      i[1].flash(color, (@flash_duration * Graphics.frame_rate).to_i)   # Must be in frames
    end
  end

  def update
    return if disposed?
    mustchange = false
    if @active
      cursor_time = System.uptime / 0.4
      if cursor_time.to_i.even?
        @cursoropacity = lerp(255, 128, 0.4, cursor_time % 2)
      else
        @cursoropacity = lerp(128, 255, 0.4, (cursor_time - 1) % 2)
      end
    else
      @cursoropacity = 128
    end
    privRefreshCursor
    if @pause
      oldpauseframe = @pauseframe
      oldpauseopacity = @pauseopacity
      @pauseframe = (System.uptime * 5).to_i % 4   # 4 frames, 5 frames per second
      @pauseopacity = [@pauseopacity + 64, 255].min
      mustchange = @pauseframe != oldpauseframe || @pauseopacity != oldpauseopacity
    end
    privRefresh if mustchange
    if @flash_timer_start
      @sprites.each_value { |i| i.update }
      @flash_timer_start = nil if System.uptime - @flash_timer_start >= @flash_duration
    end
  end

  def loadSkinFile(_file)
    if (self.windowskin.width == 80 || self.windowskin.width == 96) &&
       self.windowskin.height == 48
      # Body = X, Y, width, height of body rectangle within windowskin
      @skinrect.set(32, 16, 16, 16)
      # Trim = X, Y, width, height of trim rectangle within windowskin
      @trim = [32, 16, 16, 16]
    elsif self.windowskin.width == 80 && self.windowskin.height == 80
      @skinrect.set(32, 32, 16, 16)
      @trim = [32, 16, 16, 48]
    end
  end

  def windowskin=(value)
    oldSkinWidth = (@_windowskin && !@_windowskin.disposed?) ? @_windowskin.width : -1
    oldSkinHeight = (@_windowskin && !@_windowskin.disposed?) ? @_windowskin.height : -1
    @_windowskin = value
    if @skinformat == 1
      @rpgvx = false
      if @_windowskin && !@_windowskin.disposed?
        if @_windowskin.width != oldSkinWidth || @_windowskin.height != oldSkinHeight
          # Update skinrect and trim if windowskin's dimensions have changed
          @skinrect.set((@_windowskin.width - 16) / 2, (@_windowskin.height - 16) / 2, 16, 16)
          @trim = [@skinrect.x, @skinrect.y, @skinrect.x, @skinrect.y]
        end
      else
        @skinrect.set(16, 16, 16, 16)
        @trim = [16, 16, 16, 16]
      end
    else
      if value.is_a?(Bitmap) && !value.disposed? && value.width == 128
        @rpgvx = true
      else
        @rpgvx = false
      end
      @trim = [16, 16, 16, 16]
    end
    privRefresh(true)
  end

  def skinrect=(value)
    @skinrect = value
    privRefresh
  end

  def skinformat=(value)
    if @skinformat != value
      @skinformat = value
      privRefresh(true)
    end
  end

  def borderX
    return 32 if !@trim || skinformat == 0
    if @_windowskin && !@_windowskin.disposed?
      return @trim[0] + (@_windowskin.width - @trim[2] - @trim[0])
    end
    return 32
  end

  def borderY
    return 32 if !@trim || skinformat == 0
    if @_windowskin && !@_windowskin.disposed?
      return @trim[1] + (@_windowskin.height - @trim[3] - @trim[1])
    end
    return 32
  end

  def leftEdge; self.startX; end
  def topEdge; self.startY; end
  def rightEdge; self.borderX - self.leftEdge; end
  def bottomEdge; self.borderY - self.topEdge; end

  def startX
    return !@trim || skinformat == 0  ? 16 : @trim[0]
  end

  def startY
    return !@trim || skinformat == 0  ? 16 : @trim[1]
  end

  def endX
    return !@trim || skinformat == 0  ? 16 : @trim[2]
  end

  def endY
    return !@trim || skinformat == 0  ? 16 : @trim[3]
  end

  def startX=(value)
    @trim[0] = value
    privRefresh
  end

  def startY=(value)
    @trim[1] = value
    privRefresh
  end

  def endX=(value)
    @trim[2] = value
    privRefresh
  end

  def endY=(value)
    @trim[3] = value
    privRefresh
  end

  #-----------------------------------------------------------------------------

  private

  def ensureBitmap(bitmap, dwidth, dheight)
    if !bitmap || bitmap.disposed? || bitmap.width < dwidth || bitmap.height < dheight
      bitmap&.dispose
      bitmap = Bitmap.new([1, dwidth].max, [1, dheight].max)
    end
    return bitmap
  end

  def tileBitmap(dstbitmap, dstrect, srcbitmap, srcrect)
    return if !srcbitmap || srcbitmap.disposed?
    left = dstrect.x
    top = dstrect.y
    y = 0
    loop do
      break unless y < dstrect.height
      x = 0
      loop do
        break unless x < dstrect.width
        dstbitmap.blt(x + left, y + top, srcbitmap, srcrect)
        x += srcrect.width
      end
      y += srcrect.height
    end
  end

  def privRefreshCursor
    contopac = self.contents_opacity
    cursoropac = @cursoropacity * contopac / 255
    @sprites["cursor"].opacity = cursoropac
  end

  def privRefresh(change_bitmap = false)
    return if !self || self.disposed?
    backopac = self.back_opacity * self.opacity / 255
    contopac = self.contents_opacity
    cursoropac = @cursoropacity * contopac / 255
    haveskin = @_windowskin && !@_windowskin.disposed?
    4.times do |i|
      @sprites["corner#{i}"].bitmap = @_windowskin
      @sprites["scroll#{i}"].bitmap = @_windowskin
    end
    @sprites["pause"].bitmap = @_windowskin
    @sprites["contents"].bitmap = @contents
    if haveskin
      4.times do |i|
        @sprites["corner#{i}"].opacity = backopac
        @sprites["corner#{i}"].tone = @tone
        @sprites["corner#{i}"].color = @color
        @sprites["corner#{i}"].visible = @visible
        @sprites["corner#{i}"].blend_type = @blend_type
        @sprites["side#{i}"].opacity = backopac
        @sprites["side#{i}"].tone = @tone
        @sprites["side#{i}"].color = @color
        @sprites["side#{i}"].blend_type = @blend_type
        @sprites["side#{i}"].visible = @visible
        @sprites["scroll#{i}"].opacity = @opacity
        @sprites["scroll#{i}"].tone = @tone
        @sprites["scroll#{i}"].color = @color
        @sprites["scroll#{i}"].visible = @visible
        @sprites["scroll#{i}"].blend_type = @blend_type
      end
      ["back", "cursor", "pause", "contents"].each do |i|
        @sprites[i].color = @color
        @sprites[i].tone = @tone
        @sprites[i].blend_type = @blend_type
      end
      @sprites["contents"].blend_type = @contents_blend_type
      @sprites["back"].opacity = backopac
      @sprites["contents"].opacity = contopac
      @sprites["cursor"].opacity = cursoropac
      @sprites["pause"].opacity = @pauseopacity
      supported = (@skinformat == 0)
      hascontents = (@contents && !@contents.disposed?)
      @sprites["back"].visible = @visible
      @sprites["contents"].visible = @visible && @openness == 255
      @sprites["pause"].visible = supported && @visible && @pause &&
                                  (@combat & CompatBits::SHOW_PAUSE)
      @sprites["cursor"].visible = supported && @visible && @openness == 255 &&
                                   (@combat & CompatBits::SHOW_CURSOR)
      @sprites["scroll0"].visible = false
      @sprites["scroll1"].visible = false
      @sprites["scroll2"].visible = false
      @sprites["scroll3"].visible = false
    else
      4.times do |i|
        @sprites["corner#{i}"].visible = false
        @sprites["side#{i}"].visible = false
        @sprites["scroll#{i}"].visible = false
      end
      @sprites["contents"].visible = @visible && @openness == 255
      @sprites["contents"].color = @color
      @sprites["contents"].tone = @tone
      @sprites["contents"].blend_type = @contents_blend_type
      @sprites["contents"].opacity = contopac
      @sprites["back"].visible = false
      @sprites["pause"].visible = false
      @sprites["cursor"].visible = false
    end
    @spritekeys.each do |i|
      @sprites[i].z = @z
    end
    if (@compat & CompatBits::CORRECT_Z) > 0 && @skinformat == 0 && !@rpgvx
      # Compatibility Mode: Cursor, pause, and contents have higher Z
      @sprites["cursor"].z = @z + 1
      @sprites["contents"].z = @z + 2
      @sprites["pause"].z = @z + 2
    end
    if @skinformat == 0
      startX = 16
      startY = 16
      endX = 16
      endY = 16
      trimStartX = 16
      trimStartY = 16
      trimWidth = 32
      trimHeight = 32
      if @rpgvx
        trimX = 64
        trimY = 0
        backRect = Rect.new(0, 0, 64, 64)
        blindsRect = Rect.new(0, 64, 64, 64)
      else
        trimX = 128
        trimY = 0
        backRect = Rect.new(0, 0, 128, 128)
        blindsRect = nil
      end
      if @_windowskin && !@_windowskin.disposed?
        @sprites["corner0"].src_rect.set(trimX, trimY + 0, 16, 16)
        @sprites["corner1"].src_rect.set(trimX + 48, trimY + 0, 16, 16)
        @sprites["corner2"].src_rect.set(trimX, trimY + 48, 16, 16)
        @sprites["corner3"].src_rect.set(trimX + 48, trimY + 48, 16, 16)
        @sprites["scroll0"].src_rect.set(trimX + 24, trimY + 16, 16, 8) # up
        @sprites["scroll3"].src_rect.set(trimX + 24, trimY + 40, 16, 8) # down
        @sprites["scroll1"].src_rect.set(trimX + 16, trimY + 24, 8, 16) # left
        @sprites["scroll2"].src_rect.set(trimX + 40, trimY + 24, 8, 16) # right
        cursorX = trimX
        cursorY = trimY + 64
        sideRects = [Rect.new(trimX + 16, trimY + 0, 32, 16),
                     Rect.new(trimX, trimY + 16, 16, 32),
                     Rect.new(trimX + 48, trimY + 16, 16, 32),
                     Rect.new(trimX + 16, trimY + 48, 32, 16)]
        pauseRects = [trimX + 32, trimY + 64,
                      trimX + 48, trimY + 64,
                      trimX + 32, trimY + 80,
                      trimX + 48, trimY + 80]
        pauseWidth = 16
        pauseHeight = 16
        @sprites["pause"].src_rect.set(
          pauseRects[@pauseframe * 2],
          pauseRects[(@pauseframe * 2) + 1],
          pauseWidth, pauseHeight
        )
      end
    else
      trimStartX = @trim[0]
      trimStartY = @trim[1]
      trimWidth = @trim[0] + (@skinrect.width - @trim[2] + @trim[0])
      trimHeight = @trim[1] + (@skinrect.height - @trim[3] + @trim[1])
      if @_windowskin && !@_windowskin.disposed?
        # width of left end of window
        startX = @skinrect.x
        # width of top end of window
        startY = @skinrect.y
        cx = @skinrect.x + @skinrect.width # right side of BODY rect
        cy = @skinrect.y + @skinrect.height # bottom side of BODY rect
        # width of right end of window
        endX = (!@_windowskin || @_windowskin.disposed?) ? @skinrect.x : @_windowskin.width - cx
        # height of bottom end of window
        endY = (!@_windowskin || @_windowskin.disposed?) ? @skinrect.y : @_windowskin.height - cy
        @sprites["corner0"].src_rect.set(0, 0, startX, startY)
        @sprites["corner1"].src_rect.set(cx, 0, endX, startY)
        @sprites["corner2"].src_rect.set(0, cy, startX, endY)
        @sprites["corner3"].src_rect.set(cx, cy, endX, endY)
        backRect = Rect.new(@skinrect.x, @skinrect.y, @skinrect.width, @skinrect.height)
        blindsRect = nil
        sideRects = [
          Rect.new(startX, 0, @skinrect.width, startY),  # side0 (top)
          Rect.new(0, startY, startX, @skinrect.height), # side1 (left)
          Rect.new(cx, startY, endX, @skinrect.height),  # side2 (right)
          Rect.new(startX, cy, @skinrect.width, endY)    # side3 (bottom)
        ]
      end
    end
    if @width > trimWidth && @height > trimHeight
      @sprites["contents"].src_rect.set(@ox, @oy, @width - trimWidth, @height - trimHeight)
    else
      @sprites["contents"].src_rect.set(0, 0, 0, 0)
    end
    @sprites["contents"].x = @x + trimStartX
    @sprites["contents"].y = @y + trimStartY
    if (@compat & CompatBits::SHOW_SCROLL_ARROWS) > 0 && @skinformat == 0 &&
       @_windowskin && !@_windowskin.disposed? &&
       @contents && !@contents.disposed?
      @sprites["scroll0"].visible = @visible && hascontents && @oy > 0
      @sprites["scroll1"].visible = @visible && hascontents && @ox > 0
      @sprites["scroll2"].visible = @visible && (@contents.width - @ox) > @width - trimWidth
      @sprites["scroll3"].visible = @visible && (@contents.height - @oy) > @height - trimHeight
    end
    if @_windowskin && !@_windowskin.disposed?
      borderX = startX + endX
      borderY = startY + endY
      @sprites["corner0"].x = @x
      @sprites["corner0"].y = @y
      @sprites["corner1"].x = @x + @width - endX
      @sprites["corner1"].y = @y
      @sprites["corner2"].x = @x
      @sprites["corner2"].y = @y + @height - endY
      @sprites["corner3"].x = @x + @width - endX
      @sprites["corner3"].y = @y + @height - endY
      @sprites["side0"].x = @x + startX
      @sprites["side0"].y = @y
      @sprites["side1"].x = @x
      @sprites["side1"].y = @y + startY
      @sprites["side2"].x = @x + @width - endX
      @sprites["side2"].y = @y + startY
      @sprites["side3"].x = @x + startX
      @sprites["side3"].y = @y + @height - endY
      @sprites["scroll0"].x = @x + (@width / 2) - 8
      @sprites["scroll0"].y = @y + 8
      @sprites["scroll1"].x = @x + 8
      @sprites["scroll1"].y = @y + (@height / 2) - 8
      @sprites["scroll2"].x = @x + @width - 16
      @sprites["scroll2"].y = @y + (@height / 2) - 8
      @sprites["scroll3"].x = @x + (@width / 2) - 8
      @sprites["scroll3"].y = @y + @height - 16
      @sprites["cursor"].x = @x + startX + @cursor_rect.x
      @sprites["cursor"].y = @y + startY + @cursor_rect.y
      if (@compat & CompatBits::EXPAND_BACK) > 0 && @skinformat == 0
        # Compatibility mode: Expand background
        @sprites["back"].x = @x + 2
        @sprites["back"].y = @y + 2
      else
        @sprites["back"].x = @x + startX
        @sprites["back"].y = @y + startY
      end
    end
    if change_bitmap && @_windowskin && !@_windowskin.disposed?
      if @skinformat == 0
        @sprites["cursor"].x = @x + startX + @cursor_rect.x
        @sprites["cursor"].y = @y + startY + @cursor_rect.y
        width = @cursor_rect.width
        height = @cursor_rect.height
        if width > 0 && height > 0
          cursorrects = [
            # sides
            Rect.new(cursorX + 2, cursorY + 0, 28, 2),
            Rect.new(cursorX + 0, cursorY + 2, 2, 28),
            Rect.new(cursorX + 30, cursorY + 2, 2, 28),
            Rect.new(cursorX + 2, cursorY + 30, 28, 2),
            # corners
            Rect.new(cursorX + 0, cursorY + 0, 2, 2),
            Rect.new(cursorX + 30, cursorY + 0, 2, 2),
            Rect.new(cursorX + 0, cursorY + 30, 2, 2),
            Rect.new(cursorX + 30, cursorY + 30, 2, 2),
            # back
            Rect.new(cursorX + 2, cursorY + 2, 28, 28)
          ]
          margin = 2
          fullmargin = 4
          @cursorbitmap = ensureBitmap(@cursorbitmap, width, height)
          @cursorbitmap.clear
          @sprites["cursor"].bitmap = @cursorbitmap
          @sprites["cursor"].src_rect.set(0, 0, width, height)
          rect = Rect.new(margin, margin, width - fullmargin, height - fullmargin)
          @cursorbitmap.stretch_blt(rect, @_windowskin, cursorrects[8])
          @cursorbitmap.blt(0, 0, @_windowskin, cursorrects[4])   # top left
          @cursorbitmap.blt(width - margin, 0, @_windowskin, cursorrects[5])   # top right
          @cursorbitmap.blt(0, height - margin, @_windowskin, cursorrects[6])   # bottom right
          @cursorbitmap.blt(width - margin, height - margin, @_windowskin, cursorrects[7])   # bottom left
          rect = Rect.new(margin, 0, width - fullmargin, margin)
          @cursorbitmap.stretch_blt(rect, @_windowskin, cursorrects[0])
          rect = Rect.new(0, margin, margin, height - fullmargin)
          @cursorbitmap.stretch_blt(rect, @_windowskin, cursorrects[1])
          rect = Rect.new(width - margin, margin, margin, height - fullmargin)
          @cursorbitmap.stretch_blt(rect, @_windowskin, cursorrects[2])
          rect = Rect.new(margin, height - margin, width - fullmargin, margin)
          @cursorbitmap.stretch_blt(rect, @_windowskin, cursorrects[3])
        else
          @sprites["cursor"].visible = false
          @sprites["cursor"].src_rect.set(0, 0, 0, 0)
        end
      end
      4.times do |i|
        case i
        when 0
          dwidth  = @width - startX - endX
          dheight = startY
        when 1
          dwidth  = startX
          dheight = @height - startY - endY
        when 2
          dwidth  = endX
          dheight = @height - startY - endY
        when 3
          dwidth  = @width - startX - endX
          dheight = endY
        end
        @sidebitmaps[i] = ensureBitmap(@sidebitmaps[i], dwidth, dheight)
        @sprites["side#{i}"].bitmap = @sidebitmaps[i]
        @sprites["side#{i}"].src_rect.set(0, 0, dwidth, dheight)
        @sidebitmaps[i].clear
        if sideRects[i].width > 0 && sideRects[i].height > 0
          if (@compat & CompatBits::STRETCH_SIDES) > 0 && @skinformat == 0
            # Compatibility mode: Stretch sides
            @sidebitmaps[i].stretch_blt(@sprites["side#{i}"].src_rect,
                                        @_windowskin, sideRects[i])
          else
            tileBitmap(@sidebitmaps[i], @sprites["side#{i}"].src_rect,
                       @_windowskin, sideRects[i])
          end
        end
      end
      if (@compat & CompatBits::EXPAND_BACK) > 0 && @skinformat == 0
        # Compatibility mode: Expand background
        backwidth = @width - 4
        backheight = @height - 4
      else
        backwidth = @width - borderX
        backheight = @height - borderY
      end
      if backwidth > 0 && backheight > 0
        @backbitmap = ensureBitmap(@backbitmap, backwidth, backheight)
        @sprites["back"].bitmap = @backbitmap
        @sprites["back"].src_rect.set(0, 0, backwidth, backheight)
        @backbitmap.clear
        if @stretch
          @backbitmap.stretch_blt(@sprites["back"].src_rect, @_windowskin, backRect)
        else
          tileBitmap(@backbitmap, @sprites["back"].src_rect, @_windowskin, backRect)
        end
        if blindsRect
          tileBitmap(@backbitmap, @sprites["back"].src_rect, @_windowskin, blindsRect)
        end
      else
        @sprites["back"].visible = false
        @sprites["back"].src_rect.set(0, 0, 0, 0)
      end
    end
    if @openness == 255
      @spritekeys.each do |k|
        sprite = @sprites[k]
        sprite.zoom_x = 1.0
        sprite.zoom_y = 1.0
      end
    else
      opn = @openness / 255.0
      @spritekeys.each do |k|
        sprite = @sprites[k]
        ratio = (@height <= 0) ? 0 : (sprite.y - @y) / @height.to_f
        sprite.zoom_y = opn
        sprite.zoom_x = 1.0
        sprite.oy = 0
        sprite.y = (@y + (@height / 2.0) + (@height * ratio * opn) - (@height / 2 * opn)).floor
      end
    end
    i = 0
    # Ensure Z order
    @spritekeys.each do |k|
      sprite = @sprites[k]
      y = sprite.y
      sprite.y = i
      sprite.oy = (sprite.zoom_y <= 0) ? 0 : (i - y) / sprite.zoom_y
      sprite.zoom_x *= @zoom_x
      sprite.zoom_y *= @zoom_y
      sprite.x *= @zoom_x
      sprite.y *= @zoom_y
      sprite.x += (@offset_x / sprite.zoom_x)
      sprite.y += (@offset_y / sprite.zoom_y)
    end
  end
end

#===============================================================================
#
#===============================================================================
class SpriteWindow_Base < SpriteWindow
  TEXT_PADDING = 4   # In pixels

  def initialize(x, y, width, height)
    super()
    self.x = x
    self.y = y
    self.width = width
    self.height = height
    self.z = 100
    @curframe = MessageConfig.pbGetSystemFrame
    @curfont = MessageConfig.pbGetSystemFontName
    @sysframe = AnimatedBitmap.new(@curframe)
    RPG::Cache.retain(@curframe) if @curframe && !@curframe.empty?
    @customskin = nil
    __setWindowskin(@sysframe.bitmap)
    __resolveSystemFrame
    pbSetSystemFont(self.contents) if self.contents
  end

  def __setWindowskin(skin)
    if skin && ((skin.width == 192 && skin.height == 128) ||   # RPGXP Windowskin
       (skin.width == 128 && skin.height == 128))              # RPGVX Windowskin
      self.skinformat = 0
    else
      self.skinformat = 1
    end
    self.windowskin = skin
  end

  def __resolveSystemFrame
    if self.skinformat == 1
      if !@resolvedFrame
        @resolvedFrame = MessageConfig.pbGetSystemFrame
        @resolvedFrame.sub!(/\.[^\.\/\\]+$/, "")
      end
      self.loadSkinFile("#{@resolvedFrame}.txt") if @resolvedFrame != ""
    end
  end

  # Filename of windowskin to apply. Supports XP, VX, and animated skins.
  def setSkin(skin)
    @customskin&.dispose
    @customskin = nil
    resolvedName = pbResolveBitmap(skin)
    return if nil_or_empty?(resolvedName)
    @windowskin_name = skin
    @customskin = AnimatedBitmap.new(resolvedName)
    RPG::Cache.retain(resolvedName)
    __setWindowskin(@customskin.bitmap)
    if self.skinformat == 1
      skinbase = resolvedName.sub(/\.[^\.\/\\]+$/, "")
      self.loadSkinFile("#{skinbase}.txt")
    end
  end

  def setSystemFrame
    @customskin&.dispose
    @customskin = nil
    __setWindowskin(@sysframe.bitmap)
    __resolveSystemFrame
  end

  def update
    super
    if self.windowskin
      if @customskin
        if @customskin.totalFrames > 1
          @customskin.update
          __setWindowskin(@customskin.bitmap)
        end
      elsif @sysframe
        if @sysframe.totalFrames > 1
          @sysframe.update
          __setWindowskin(@sysframe.bitmap)
        end
      end
    end
    if @curframe != MessageConfig.pbGetSystemFrame
      @curframe = MessageConfig.pbGetSystemFrame
      if @sysframe && !@customskin
        @sysframe&.dispose
        @sysframe = AnimatedBitmap.new(@curframe)
        RPG::Cache.retain(@curframe) if @curframe && !@curframe.empty?
        @resolvedFrame = nil
        __setWindowskin(@sysframe.bitmap)
        __resolveSystemFrame
      end
      begin
        refresh
      rescue NoMethodError
      end
    end
    if @curfont != MessageConfig.pbGetSystemFontName
      @curfont = MessageConfig.pbGetSystemFontName
      if self.contents && !self.contents.disposed?
        pbSetSystemFont(self.contents)
      end
      begin
        refresh
      rescue NoMethodError
      end
    end
  end

  def dispose
    self.contents&.dispose
    @sysframe.dispose
    @customskin&.dispose
    super
  end
end

==============================================================================
# Script: SpriteWindow_text
==============================================================================
#===============================================================================
# Represents a window with no formatting capabilities. Its text color can be set,
# though, and line breaks are supported, but the text is generally unformatted.
#===============================================================================
class Window_UnformattedTextPokemon < SpriteWindow_Base
  attr_reader :text
  attr_reader :baseColor
  attr_reader :shadowColor
  # Letter-by-letter mode. This mode is not supported in this class.
  attr_accessor :letterbyletter

  def text=(value)
    @text = value || ""
    refresh
  end

  def baseColor=(value)
    @baseColor = value
    refresh
  end

  def shadowColor=(value)
    @shadowColor = value
    refresh
  end

  def initialize(text = "")
    super(0, 0, 33, 33)
    self.contents = Bitmap.new(1, 1)
    pbSetSystemFont(self.contents)
    @text = text
    @letterbyletter = false # Not supported in this class
    @baseColor, @shadowColor = getDefaultTextColors(self.windowskin)
    resizeToFit(text)
  end

  def self.newWithSize(text, x, y, width, height, viewport = nil)
    ret = self.new(text)
    ret.x = x
    ret.y = y
    ret.width = width
    ret.height = height
    ret.viewport = viewport
    ret.refresh
    return ret
  end

  # maxwidth is maximum acceptable window width.
  def resizeToFitInternal(text, maxwidth)
    dims = [0, 0]
    cwidth = maxwidth < 0 ? Graphics.width : maxwidth
    getLineBrokenChunks(self.contents, text,
                        cwidth - self.borderX - SpriteWindow_Base::TEXT_PADDING, dims, true)
    return dims
  end

  def setTextToFit(text, maxwidth = -1)
    resizeToFit(text, maxwidth)
    self.text = text
  end

  # maxwidth is maximum acceptable window width.
  def resizeToFit(text, maxwidth = -1)
    dims = resizeToFitInternal(text, maxwidth)
    self.width = dims[0] + self.borderX + SpriteWindow_Base::TEXT_PADDING
    self.height = dims[1] + self.borderY
    refresh
  end

  # width is current window width.
  def resizeHeightToFit(text, width = -1)
    dims = resizeToFitInternal(text, width)
    self.width  = (width < 0) ? Graphics.width : width
    self.height = dims[1] + self.borderY
    refresh
  end

  def setSkin(skin)
    super(skin)
    privRefresh(true)
    oldbaser = @baseColor.red
    oldbaseg = @baseColor.green
    oldbaseb = @baseColor.blue
    oldbasea = @baseColor.alpha
    oldshadowr = @shadowColor.red
    oldshadowg = @shadowColor.green
    oldshadowb = @shadowColor.blue
    oldshadowa = @shadowColor.alpha
    @baseColor, @shadowColor = getDefaultTextColors(self.windowskin)
    if oldbaser != @baseColor.red || oldbaseg != @baseColor.green ||
       oldbaseb != @baseColor.blue || oldbasea != @baseColor.alpha ||
       oldshadowr != @shadowColor.red || oldshadowg != @shadowColor.green ||
       oldshadowb != @shadowColor.blue || oldshadowa != @shadowColor.alpha
      self.text = self.text
    end
  end

  def refresh
    self.contents = pbDoEnsureBitmap(self.contents, self.width - self.borderX,
                                     self.height - self.borderY)
    self.contents.clear
    drawTextEx(self.contents, 0, -2, self.contents.width, 0,   # TEXT OFFSET
               @text.gsub(/\r/, ""), @baseColor, @shadowColor)
  end
end

#===============================================================================
#
#===============================================================================
class Window_AdvancedTextPokemon < SpriteWindow_Base
  attr_reader   :text
  attr_reader   :baseColor
  attr_reader   :shadowColor
  attr_accessor :letterbyletter
  attr_reader   :waitcount

  def initialize(text = "")
    @cursorMode         = MessageConfig::CURSOR_POSITION
    @endOfText          = nil
    @scrollstate        = 0
    @scrollY            = 0
    @scroll_timer_start = nil
    @realframes         = 0
    @nodraw             = false
    @lineHeight         = 32
    @linesdrawn         = 0
    @bufferbitmap       = nil
    @letterbyletter     = false
    @starting           = true
    @displaying         = false
    @lastDrawnChar      = -1
    @fmtchars           = []
    @text_delay_changed = false
    @text_delay         = MessageConfig.pbGetTextSpeed
    super(0, 0, 33, 33)
    @pausesprite        = nil
    @text               = ""
    self.contents = Bitmap.new(1, 1)
    pbSetSystemFont(self.contents)
    self.resizeToFit(text, Graphics.width)
    @baseColor, @shadowColor = getDefaultTextColors(self.windowskin)
    self.text           = text
    @starting           = false
  end

  def self.newWithSize(text, x, y, width, height, viewport = nil)
    ret = self.new(text)
    ret.x        = x
    ret.y        = y
    ret.width    = width
    ret.height   = height
    ret.viewport = viewport
    return ret
  end

  def dispose
    return if disposed?
    @pausesprite&.dispose
    @pausesprite = nil
    super
  end

  def waitcount=(value)
    @waitcount = (value <= 0) ? 0 : value
    @wait_timer_start = System.uptime if !@wait_timer_start && value > 0
  end

  attr_reader :cursorMode

  def cursorMode=(value)
    @cursorMode = value
    moveCursor
  end

  def lineHeight=(value)
    @lineHeight = value
    self.text = self.text
  end

  def baseColor=(value)
    @baseColor = value
    refresh
  end

  def shadowColor=(value)
    @shadowColor = value
    refresh
  end

  # Delay in seconds between two adjacent characters appearing.
  def textspeed
    return @text_delay
  end

  def textspeed=(value)
    @text_delay_changed = true if @text_delay != value
    @text_delay = value
  end

  def width=(value)
    super
    self.text = self.text if !@starting
  end

  def height=(value)
    super
    self.text = self.text if !@starting
  end

  def resizeToFit(text, maxwidth = -1)
    dims = resizeToFitInternal(text, maxwidth)
    oldstarting = @starting
    @starting = true
    self.width  = dims[0] + self.borderX + SpriteWindow_Base::TEXT_PADDING
    self.height = dims[1] + self.borderY
    @starting = oldstarting
    redrawText
  end

  def resizeToFit2(text, maxwidth, maxheight)
    dims = resizeToFitInternal(text, maxwidth)
    oldstarting = @starting
    @starting = true
    self.width  = [dims[0] + self.borderX + SpriteWindow_Base::TEXT_PADDING, maxwidth].min
    self.height = [dims[1] + self.borderY, maxheight].min
    @starting = oldstarting
    redrawText
  end

  def resizeToFitInternal(text, maxwidth)
    dims = [0, 0]
    cwidth = (maxwidth < 0) ? Graphics.width : maxwidth
    chars = getFormattedTextForDims(self.contents, 0, 0,
                                    cwidth - self.borderX - SpriteWindow_Base::TEXT_PADDING, -1, text, @lineHeight, true)
    chars.each do |ch|
      dims[0] = [dims[0], ch[1] + ch[3]].max
      dims[1] = [dims[1], ch[2] + ch[4]].max
    end
    return dims
  end

  def resizeHeightToFit(text, width = -1)
    dims = resizeToFitInternal(text, width)
    oldstarting = @starting
    @starting = true
    self.width  = (width < 0) ? Graphics.width : width
    self.height = dims[1] + self.borderY + 2   # TEXT OFFSET
    @starting = oldstarting
    redrawText
  end

  def setSkin(skin, redrawText = true)
    super(skin)
    privRefresh(true)
    oldbaser = @baseColor.red
    oldbaseg = @baseColor.green
    oldbaseb = @baseColor.blue
    oldbasea = @baseColor.alpha
    oldshadowr = @shadowColor.red
    oldshadowg = @shadowColor.green
    oldshadowb = @shadowColor.blue
    oldshadowa = @shadowColor.alpha
    @baseColor, @shadowColor = getDefaultTextColors(self.windowskin)
    if redrawText &&
       (oldbaser != @baseColor.red || oldbaseg != @baseColor.green ||
       oldbaseb != @baseColor.blue || oldbasea != @baseColor.alpha ||
       oldshadowr != @shadowColor.red || oldshadowg != @shadowColor.green ||
       oldshadowb != @shadowColor.blue || oldshadowa != @shadowColor.alpha)
      setText(self.text)
    end
    @pausesprite&.dispose
    @pausesprite = nil
  end

  def setTextToFit(text, maxwidth = -1)
    resizeToFit(text, maxwidth)
    self.text = text
  end

  def text=(value)
    setText(value)
  end

  def setText(value)
    @waitcount = 0
    @wait_timer_start = nil
    @display_timer = 0.0
    @display_last_updated = System.uptime
    @curchar = 0
    @drawncurchar = -1
    @lastDrawnChar = -1
    @text = value
    @textlength = unformattedTextLength(value)
    @scrollstate = 0
    @scrollY = 0
    @scroll_timer_start = nil
    @linesdrawn = 0
    @realframes = 0
    @textchars = []
    width = 1
    height = 1
    numlines = 0
    visiblelines = (self.height - self.borderY) / @lineHeight
    if value.length == 0
      @fmtchars = []
      @bitmapwidth = width
      @bitmapheight = height
      @numtextchars = 0
    else
      if @letterbyletter
        @fmtchars = []
        fmt = getFormattedText(self.contents, 0, 0,
                               self.width - self.borderX - SpriteWindow_Base::TEXT_PADDING, -1,
                               shadowc3tag(@baseColor, @shadowColor) + value, @lineHeight, true)
        @oldfont = self.contents.font.clone
        fmt.each do |ch|
          chx = ch[1] + ch[3]
          chy = ch[2] + ch[4]
          width  = chx if width < chx
          height = chy if height < chy
          if !ch[5] && ch[0] == "\n"
            numlines += 1
            if numlines >= visiblelines
              fclone = ch.clone
              fclone[0] = "\1"
              @fmtchars.push(fclone)
              @textchars.push("\1")
            end
          end
          # Don't add newline characters, since they
          # can slow down letter-by-letter display
          if ch[5] || (ch[0] != "\r")
            @fmtchars.push(ch)
            @textchars.push(ch[5] ? "" : ch[0])
          end
        end
        fmt.clear
      else
        @fmtchars = getFormattedText(self.contents, 0, 0,
                                     self.width - self.borderX - SpriteWindow_Base::TEXT_PADDING, -1,
                                     shadowc3tag(@baseColor, @shadowColor) + value, @lineHeight, true)
        @oldfont = self.contents.font.clone
        @fmtchars.each do |ch|
          chx = ch[1] + ch[3]
          chy = ch[2] + ch[4]
          width = chx if width < chx
          height = chy if height < chy
          @textchars.push(ch[5] ? "" : ch[0])
        end
      end
      @bitmapwidth = width
      @bitmapheight = height
      @numtextchars = @textchars.length
    end
    stopPause
    @displaying = @letterbyletter
    @needclear = true
    @nodraw = @letterbyletter
    refresh
  end

  def busy?
    return @displaying
  end

  def pausing?
    return @pausing && @displaying
  end

  def resume
    if !busy?
      self.stopPause
      return true
    end
    if @pausing
      @pausing = false
      self.stopPause
      return false
    end
    return true
  end

  def position
    return 0 if @lastDrawnChar < 0
    return @numtextchars if @lastDrawnChar >= @fmtchars.length
    # index after the last character's index
    return @fmtchars[@lastDrawnChar][14] + 1
  end

  def maxPosition
    pos = 0
    @fmtchars.each do |ch|
      # index after the last character's index
      pos = ch[14] + 1 if pos < ch[14] + 1
    end
    return pos
  end

  def skipAhead
    return if !busy?
    return if @textchars[@curchar] == "\n"
    resume
    if curcharSkip(true)
      visiblelines = (self.height - self.borderY) / @lineHeight
      if @textchars[@curchar] == "\n" && @linesdrawn >= visiblelines - 1
        @scroll_timer_start = System.uptime
      elsif @textchars[@curchar] == "\1"
        @pausing = true if @curchar < @numtextchars - 1
        self.startPause
        refresh
      end
    end
  end

  def allocPause
    return if @pausesprite
    arrow_filename = "Graphics/Windowskins/pause_arrow"
    if @windowskin_name
      try_arrow_filename = "Graphics/Windowskins/#{File.basename(@windowskin_name, ".*")}_arrow"
      arrow_filename = try_arrow_filename if pbResolveBitmap(try_arrow_filename)
    end
    @pausesprite = AnimatedSprite.create(arrow_filename, 4, 3)
    @pausesprite.z       = 100000
    @pausesprite.visible = false
  end

  def startPause
    allocPause
    @pausesprite.visible = true
    @pausesprite.frame   = 0
    @pausesprite.start
    moveCursor
  end

  def stopPause
    return if !@pausesprite
    @pausesprite.stop
    @pausesprite.visible = false
  end

  def moveCursor
    return if !@pausesprite
    cursor = @cursorMode
    cursor = 2 if cursor == 0 && !@endOfText
    case cursor
    when 0   # End of text
      @pausesprite.x = self.x + self.startX + @endOfText.x + @endOfText.width - 2
      @pausesprite.y = self.y + self.startY + @endOfText.y - @scrollY
    when 1   # Lower right
      pauseWidth  = @pausesprite.bitmap ? @pausesprite.framewidth : 16
      pauseHeight = @pausesprite.bitmap ? @pausesprite.frameheight : 16
      @pausesprite.x = self.x + self.width - 40 + (pauseWidth / 2)
      @pausesprite.y = self.y + self.height - 60 + (pauseHeight / 2)
    when 2   # Lower middle
      pauseWidth  = @pausesprite.bitmap ? @pausesprite.framewidth : 16
      pauseHeight = @pausesprite.bitmap ? @pausesprite.frameheight : 16
      @pausesprite.x = self.x + (self.width / 2) - (pauseWidth / 2)
      @pausesprite.y = self.y + self.height - 36 + (pauseHeight / 2)
    end
  end

  def refresh
    oldcontents = self.contents
    self.contents = pbDoEnsureBitmap(oldcontents, @bitmapwidth, @bitmapheight)
    self.oy       = @scrollY
    numchars = @numtextchars
    numchars = [@curchar, @numtextchars].min if self.letterbyletter
    return if busy? && @drawncurchar == @curchar && !@scroll_timer_start
    if !self.letterbyletter || !oldcontents.equal?(self.contents)
      @drawncurchar = -1
      @needclear    = true
    end
    if @needclear
      self.contents.font = @oldfont if @oldfont
      self.contents.clear
      @needclear = false
    end
    if @nodraw
      @nodraw = false
      return
    end
    maxX = self.width - self.borderX
    maxY = self.height - self.borderY
    (@drawncurchar + 1..numchars).each do |i|
      next if i >= @fmtchars.length
      if !self.letterbyletter
        next if @fmtchars[i][1] >= maxX
        next if @fmtchars[i][2] >= maxY
      end
      drawSingleFormattedChar(self.contents, @fmtchars[i])
      @lastDrawnChar = i
    end
    # all characters were drawn, reset old font
    self.contents.font = @oldfont if !self.letterbyletter && @oldfont
    if numchars > 0 && numchars != @numtextchars
      fch = @fmtchars[numchars - 1]
      if fch
        rcdst = Rect.new(fch[1], fch[2], fch[3], fch[4])
        if @textchars[numchars] == "\1"
          @endOfText = rcdst
          allocPause
          moveCursor
        else
          @endOfText = Rect.new(rcdst.x + rcdst.width, rcdst.y, 8, 1)
        end
      end
    end
    @drawncurchar = @curchar
  end

  def redrawText
    if @letterbyletter
      oldPosition = self.position
      self.text = self.text   # Clears the text already drawn
      oldPosition = @numtextchars if oldPosition > @numtextchars
      while self.position != oldPosition
        refresh
        updateInternal
      end
    else
      self.text = self.text
    end
  end

  def updateInternal
    time_now = System.uptime
    @display_last_updated = time_now if !@display_last_updated
    delta_t = time_now - @display_last_updated
    @display_last_updated = time_now
    visiblelines = (self.height - self.borderY) / @lineHeight
    @lastchar = -1 if !@lastchar
    show_more_characters = false
    # Pauses and new lines
    if @textchars[@curchar] == "\1"   # Waiting
      show_more_characters = true if !@pausing
    elsif @textchars[@curchar] == "\n"   # Move to new line
      if @linesdrawn >= visiblelines - 1   # Need to scroll text to show new line
        if @scroll_timer_start
          old_y = @scrollstate
          new_y = lerp(0, @lineHeight, 0.1, @scroll_timer_start, time_now)
          @scrollstate = new_y
          @scrollY += new_y - old_y
          if @scrollstate >= @lineHeight
            @scrollstate = 0
            @scroll_timer_start = nil
            @linesdrawn += 1
            show_more_characters = true
          end
        else
          show_more_characters = true
        end
      else   # New line but the next line can be shown without scrolling to it
        @linesdrawn += 1 if @lastchar < @curchar
        show_more_characters = true
      end
    elsif @curchar <= @numtextchars   # Displaying more text
      show_more_characters = true
    else
      @displaying = false
      @scrollstate = 0
      @scrollY = 0
      @scroll_timer_start = nil
      @linesdrawn = 0
    end
    @lastchar = @curchar
    # Keep displaying more text
    if show_more_characters
      @display_timer += delta_t
      if curcharSkip
        if @textchars[@curchar] == "\n" && @linesdrawn >= visiblelines - 1
          @scroll_timer_start = time_now
        elsif @textchars[@curchar] == "\1"
          @pausing = true if @curchar < @numtextchars - 1
          self.startPause
          refresh
        end
      end
    end
  end

  def update
    super
    @pausesprite.update if @pausesprite&.visible
    if @wait_timer_start
      if System.uptime - @wait_timer_start >= @waitcount
        @wait_timer_start = nil
        @waitcount = 0
        @display_last_updated = nil
      end
      return if @wait_timer_start
    end
    if busy?
      refresh if !@text_delay_changed
      updateInternal
      refresh if @text_delay_changed   # Needed to allow "textspeed=0" to work seamlessly
    end
    @text_delay_changed = false
  end

  #-----------------------------------------------------------------------------

  private

  def curcharSkip(instant = false)
    ret = false
    loop do
      break if @display_timer < @text_delay && !instant
      @display_timer -= @text_delay if !instant
      ret = true
      @curchar += 1
      break if @textchars[@curchar] == "\n" ||   # newline
               @textchars[@curchar] == "\1" ||   # pause: "\!"
               @textchars[@curchar] == "\2" ||   # letter-by-letter break: "\wt[]", "\wtnp[]", "\.", "\|"
               @textchars[@curchar].nil?
    end
    return ret
  end
end

