==============================================================================
module GameData
  class Species
    attr_reader :id
    attr_reader :species
    attr_reader :form
    attr_reader :real_name
    attr_reader :real_form_name
    attr_reader :real_category
    attr_reader :real_pokedex_entry
    attr_reader :pokedex_form
    attr_reader :types
    attr_reader :base_stats
    attr_reader :evs
    attr_reader :base_exp
    attr_reader :growth_rate
    attr_reader :gender_ratio
    attr_reader :catch_rate
    attr_reader :happiness
    attr_reader :moves
    attr_reader :tutor_moves
    attr_reader :egg_moves
    attr_reader :abilities
    attr_reader :hidden_abilities
    attr_reader :wild_item_common
    attr_reader :wild_item_uncommon
    attr_reader :wild_item_rare
    attr_reader :egg_groups
    attr_reader :hatch_steps
    attr_reader :incense
    attr_reader :offspring
    attr_reader :evolutions
    attr_reader :height
    attr_reader :weight
    attr_reader :color
    attr_reader :shape
    attr_reader :habitat
    attr_reader :generation
    attr_reader :flags
    attr_reader :mega_stone
    attr_reader :mega_move
    attr_reader :unmega_form
    attr_reader :mega_message
    attr_reader :pbs_file_suffix

    DATA = {}
    DATA_FILENAME = "species.dat"
    PBS_BASE_FILENAME = ["pokemon", "pokemon_forms"]

    extend ClassMethodsSymbols
    include InstanceMethods

    def self.schema(compiling_forms = false)
      ret = {}
      if compiling_forms
        ret["SectionName"]    = [:id,                 "ev", :Species]
      else
        ret["SectionName"]    = [:id,                 "m"]
        ret["Name"]           = [:real_name,          "s"]
      end
      ret["FormName"]         = [:real_form_name,     "q"]
      if compiling_forms
        ret["PokedexForm"]    = [:pokedex_form,       "u"]
        ret["MegaStone"]      = [:mega_stone,         "e", :Item]
        ret["MegaMove"]       = [:mega_move,          "e", :Move]
        ret["UnmegaForm"]     = [:unmega_form,        "i"]
        ret["MegaMessage"]    = [:mega_message,       "u"]
      end
      ret["Types"]            = [:types,              "*e", :Type]
      ret["BaseStats"]        = [:base_stats,         "vvvvvv"]
      if !compiling_forms
        ret["GenderRatio"]    = [:gender_ratio,       "e", :GenderRatio]
        ret["GrowthRate"]     = [:growth_rate,        "e", :GrowthRate]
      end
      ret["BaseExp"]          = [:base_exp,           "v"]
      ret["EVs"]              = [:evs,                "*ev", :Stat]
      ret["CatchRate"]        = [:catch_rate,         "u"]
      ret["Happiness"]        = [:happiness,          "u"]
      ret["Abilities"]        = [:abilities,          "*e", :Ability]
      ret["HiddenAbilities"]  = [:hidden_abilities,   "*e", :Ability]
      ret["Moves"]            = [:moves,              "*ie", nil, :Move]
      ret["TutorMoves"]       = [:tutor_moves,        "*e", :Move]
      ret["EggMoves"]         = [:egg_moves,          "*e", :Move]
      ret["EggGroups"]        = [:egg_groups,         "*e", :EggGroup]
      ret["HatchSteps"]       = [:hatch_steps,        "v"]
      if compiling_forms
        ret["Offspring"]      = [:offspring,          "*e", :Species]
      else
        ret["Incense"]        = [:incense,            "e", :Item]
        ret["Offspring"]      = [:offspring,          "*s"]
      end
      ret["Height"]           = [:height,             "f"]
      ret["Weight"]           = [:weight,             "f"]
      ret["Color"]            = [:color,              "e", :BodyColor]
      ret["Shape"]            = [:shape,              "e", :BodyShape]
      ret["Habitat"]          = [:habitat,            "e", :Habitat]
      ret["Category"]         = [:real_category,      "s"]
      ret["Pokedex"]          = [:real_pokedex_entry, "q"]
      ret["Generation"]       = [:generation,         "i"]
      ret["Flags"]            = [:flags,              "*s"]
      ret["WildItemCommon"]   = [:wild_item_common,   "*e", :Item]
      ret["WildItemUncommon"] = [:wild_item_uncommon, "*e", :Item]
      ret["WildItemRare"]     = [:wild_item_rare,     "*e", :Item]
      if compiling_forms
        ret["Evolutions"]     = [:evolutions,         "*ees", :Species, :Evolution]
        ret["Evolution"]      = [:evolutions,         "^eeS", :Species, :Evolution]
      else
        ret["Evolutions"]     = [:evolutions,         "*ses", nil, :Evolution]
        ret["Evolution"]      = [:evolutions,         "^seS", nil, :Evolution]
      end
      return ret
    end

    def self.editor_properties
      return [
        ["ID",                ReadOnlyProperty,                   _INTL("El ID del Pokémon.")],
        ["Name",              LimitStringProperty.new(Pokemon::MAX_NAME_SIZE), _INTL("Nombre del Pokémon.")],
        ["FormName",          StringProperty,                     _INTL("Nombre de esta forma del Pokémon.")],
        ["Types",             GameDataPoolProperty.new(:Type, false), _INTL("El/los tipo/s del Pokémon.")],
        ["BaseStats",         BaseStatsProperty,                  _INTL("Estadísticas base del Pokémon.")],
        ["GenderRatio",       GameDataProperty.new(:GenderRatio), _INTL("Proporción de machos a hembras para esta especie.")],
        ["GrowthRate",        GameDataProperty.new(:GrowthRate),  _INTL("Ratio de crecimiento del Pokémon.")],
        ["BaseExp",           LimitProperty.new(9999),            _INTL("Experiencia base ganada cuando se derrota a esta especie.")],
        ["EVs",               EffortValuesProperty,               _INTL("Cantidad de Puntos de Esfuerzo (EVs) obtenidos cuando se derrota a esta especie.")],
        ["CatchRate",         LimitProperty.new(255),             _INTL("Ratio de captura de esta especie (0-255).")],
        ["Happiness",         LimitProperty.new(255),             _INTL("Felicidad base de esta especie (0-255).")],
        ["Abilities",         AbilitiesProperty.new,              _INTL("Habilidades que puede tener este Pokémon (max. 2).")],
        ["HiddenAbilities",   AbilitiesProperty.new,              _INTL("Habilidades Ocultas que puede tener este Pokémon.")],
        ["Moves",             LevelUpMovesProperty,               _INTL("Movimientos que aprende el Pokémon por nivel.")],
        ["TutorMoves",        EggMovesProperty.new,               _INTL("Movimientos que se pueden enseñar al Pokémon por MT/MO/Tutor de Movimientos.")],
        ["EggMoves",          EggMovesProperty.new,               _INTL("Movimientos que puede aprender el Pokémon mediante crianza.")],
        ["EggGroups",         EggGroupsProperty.new,              _INTL("Grupos Huevo a los que pertenece el Pokémon con fines de crianza.")],
        ["HatchSteps",        LimitProperty.new(99_999),          _INTL("Número de pasos hasta que eclosiona un huevo de esta especie.")],
        ["Incense",           ItemProperty,                       _INTL("Objeto que debe llevar uno de los padres para producir un huevo de esta especie.")],
        ["Offspring",         GameDataPoolProperty.new(:Species), _INTL("Todas las especies que puede ser la descendencia al criar para un huevo de esta especie (si está en blanco, el huevo sólo puede ser de esta especie).")],
        ["Height",            NonzeroLimitProperty.new(999),      _INTL("Altura del Pokémon en 0.1 metros (e.g. 42 = 4.2m).")],
        ["Weight",            NonzeroLimitProperty.new(9999),     _INTL("Peso del Pokémon en 0.1 kilogramos (e.g. 42 = 4.2kg).")],
        ["Color",             GameDataProperty.new(:BodyColor),   _INTL("Color del cuerpo del Pokémon.")],
        ["Shape",             GameDataProperty.new(:BodyShape),   _INTL("Forma corporal de esta especie.")],
        ["Habitat",           GameDataProperty.new(:Habitat),     _INTL("Hábitat de esta especie.")],
        ["Category",          StringProperty,                     _INTL("Tipo de especie de Pokémon.")],
        ["Pokedex",           StringProperty,                     _INTL("Descripción del Pokémon como se muestra en la Pokédex.")],
        ["Generation",        LimitProperty.new(99_999),          _INTL("Número de la generación en la que debutó el Pokémon.")],
        ["Flags",             StringListProperty,                 _INTL("Palabras/frases que distinguen esta especie de otras.")],
        ["WildItemCommon",    GameDataPoolProperty.new(:Item),    _INTL("Objeto(s) comúnmente llevado(s) por Pokémon salvajes de esta especie.")],
        ["WildItemUncommon",  GameDataPoolProperty.new(:Item),    _INTL("Objeto(s) raramente llevado(s) por Pokémon salvajes de esta especie.")],
        ["WildItemRare",      GameDataPoolProperty.new(:Item),    _INTL("Objeto(s) muy raramente llevado(s) por Pokémon salvajes de esta especie.")],
        ["Evolutions",        EvolutionsProperty.new,             _INTL("Caminos evolutivos de esta especie.")]
      ]
    end

    # @param species [Symbol, self, String]
    # @param form [Integer]
    # @return [self, nil]
    def self.get_species_form(species, form)
      return nil if !species || !form
      validate species => [Symbol, self, String]
      validate form => Integer
      species = species.species if species.is_a?(self)
      species = species.to_sym if species.is_a?(String)
      trial = sprintf("%s_%d", species, form).to_sym
      species_form = (DATA[trial].nil?) ? species : trial
      return (DATA.has_key?(species_form)) ? DATA[species_form] : nil
    end

    def self.each_species
      DATA.each_value { |species| yield species if species.form == 0 }
    end

    def self.each_form_for_species(this_species)
      DATA.each_value { |species| yield species if species.species == this_species }
    end

    def self.species_count
      ret = 0
      self.each_species { |species| ret += 1 }
      return ret
    end

    def self.get_all_base_forms(id_only = false)
      ret = []
      keys = DATA.keys
      keys.each do |key|
        species = DATA[key]
        next if species.mega_form? || species.has_flag?("ExcludeFromBaseForms")
        ret << (id_only ? species.id : species)
      end
      return ret
    end

    def self.base_species_count
      return get_all_base_forms.count
    end

    #---------------------------------------------------------------------------

    def initialize(hash)
      @id                 = hash[:id]
      @species            = hash[:species]            || @id
      @form               = hash[:form]               || 0
      @real_name          = hash[:real_name]          || "Unnamed"
      @real_form_name     = hash[:real_form_name]
      @real_category      = hash[:real_category]      || "???"
      @real_pokedex_entry = hash[:real_pokedex_entry] || "???"
      @pokedex_form       = hash[:pokedex_form]       || @form
      @types              = hash[:types]              || [:NORMAL]
      @base_stats         = hash[:base_stats]         || {}
      @evs                = hash[:evs]                || {}
      GameData::Stat.each_main do |s|
        @base_stats[s.id] = 1 if !@base_stats[s.id] || @base_stats[s.id] <= 0
        @evs[s.id]        = 0 if !@evs[s.id] || @evs[s.id] < 0
      end
      @base_exp           = hash[:base_exp]           || 100
      @growth_rate        = hash[:growth_rate]        || :Medium
      @gender_ratio       = hash[:gender_ratio]       || :Female50Percent
      @catch_rate         = hash[:catch_rate]         || 255
      @happiness          = hash[:happiness]          || 70
      @moves              = hash[:moves]              || []
      @tutor_moves        = hash[:tutor_moves]        || []
      @egg_moves          = hash[:egg_moves]          || []
      @abilities          = hash[:abilities]          || []
      @hidden_abilities   = hash[:hidden_abilities]   || []
      @wild_item_common   = hash[:wild_item_common]   || []
      @wild_item_uncommon = hash[:wild_item_uncommon] || []
      @wild_item_rare     = hash[:wild_item_rare]     || []
      @egg_groups         = hash[:egg_groups]         || [:Undiscovered]
      @hatch_steps        = hash[:hatch_steps]        || 1
      @incense            = hash[:incense]
      @offspring          = hash[:offspring]          || []
      @evolutions         = hash[:evolutions]         || []
      @height             = hash[:height]             || 1
      @weight             = hash[:weight]             || 1
      @color              = hash[:color]              || :Red
      @shape              = hash[:shape]              || :Head
      @habitat            = hash[:habitat]            || :None
      @generation         = hash[:generation]         || 0
      @flags              = hash[:flags]              || []
      @mega_stone         = hash[:mega_stone]
      @mega_move          = hash[:mega_move]
      @unmega_form        = hash[:unmega_form]        || -2
      @mega_message       = hash[:mega_message]       || 0
      @pbs_file_suffix    = hash[:pbs_file_suffix]    || ""
    end

    # @return [String] the translated name of this species
    def name
      return pbGetMessageFromHash(MessageTypes::SPECIES_NAMES, @real_name)
    end

    # @return [String] the translated name of this form of this species
    def form_name
      return pbGetMessageFromHash(MessageTypes::SPECIES_FORM_NAMES, @real_form_name)
    end

    # @return [String] the translated Pokédex category of this species
    def category
      return pbGetMessageFromHash(MessageTypes::SPECIES_CATEGORIES, @real_category)
    end

    # @return [String] the translated Pokédex entry of this species
    def pokedex_entry
      return pbGetMessageFromHash(MessageTypes::POKEDEX_ENTRIES, @real_pokedex_entry)
    end

    def default_form
      @flags.each do |flag|
        return $~[1].to_i if flag[/^DefaultForm_(\d+)$/i]
      end
      return -1
    end

    def base_form
      default = default_form
      return (default >= 0) ? default : @form
    end

    def mega_form?
      return (@unmega_form == @form && @form != base_form) || @unmega_form == -2 || @mega_stone || @mega_move ? true : false 
    end

    def single_gendered?
      return GameData::GenderRatio.get(@gender_ratio).single_gendered?
    end

    def base_stat_total
      return @base_stats.values.sum
    end

    def has_flag?(flag)
      return @flags.any? { |f| f.downcase == flag.downcase }
    end

    def apply_metrics_to_sprite(sprite, index, shadow = false)
      metrics_data = GameData::SpeciesMetrics.get_species_form(@species, @form)
      metrics_data.apply_metrics_to_sprite(sprite, index, shadow)
    end

    def shows_shadow?
      metrics_data = GameData::SpeciesMetrics.get_species_form(@species, @form)
      return metrics_data.shows_shadow?
    end

    def get_evolutions(exclude_invalid = false)
      ret = []
      @evolutions.each do |evo|
        next if evo[3]   # Is the prevolution
        next if evo[1] == :None && exclude_invalid
        ret.push([evo[0], evo[1], evo[2]])   # [Species, method, parameter]
      end
      return ret
    end

    def get_family_evolutions(exclude_invalid = true)
      evos = get_evolutions(exclude_invalid)
      evos = evos.sort { |a, b| GameData::Species.keys.index(a[0]) <=> GameData::Species.keys.index(b[0]) }
      ret = []
      evos.each do |evo|
        ret.push([@species].concat(evo))   # [Prevo species, evo species, method, parameter]
        evo_array = GameData::Species.get(evo[0]).get_family_evolutions(exclude_invalid)
        ret.concat(evo_array) if evo_array && evo_array.length > 0
      end
      return ret
    end

    def get_previous_species
      return @species if @evolutions.length == 0
      @evolutions.each { |evo| return evo[0] if evo[3] }   # Is the prevolution
      return @species
    end

    def get_baby_species(check_items = false, item1 = nil, item2 = nil)
      ret = @species
      return ret if @evolutions.length == 0
      @evolutions.each do |evo|
        next if !evo[3]   # Check only the prevolution
        if check_items && Settings::MECHANICS_GENERATION < 9
          incense = GameData::Species.get(evo[0]).incense
          ret = evo[0] if !incense || item1 == incense || item2 == incense
        else
          ret = evo[0]   # Species of prevolution
        end
        break
      end
      ret = GameData::Species.get(ret).get_baby_species(check_items, item1, item2) if ret != @species
      return ret
    end

    # Returns an array of all the species in this species' evolution family.
    def get_family_species(exclude_invalid = false)
      sp = get_baby_species
      evos = GameData::Species.get(sp).get_family_evolutions(exclude_invalid)
      return [sp] if evos.length == 0
      return [sp].concat(evos.map { |e| e[1] }).uniq
    end

    # This takes into account whether other_species is evolved.
    def breeding_can_produce?(other_species)
      other_family = GameData::Species.get(other_species).get_family_species
      if @offspring.length > 0
        return (other_family & @offspring).length > 0
      end
      return other_family.include?(@species)
    end

    # If this species doesn't have egg moves, looks at prevolutions one at a
    # time and returns theirs instead.
    def get_egg_moves
      return @egg_moves if !@egg_moves.empty?
      prevo = get_previous_species
      return GameData::Species.get_species_form(prevo, @form).get_egg_moves if prevo != @species
      return @egg_moves
    end

    def family_evolutions_have_method?(check_method, check_param = nil)
      sp = get_baby_species
      evos = GameData::Species.get(sp).get_family_evolutions
      return false if evos.empty?

      evos.each do |evo|
        if check_method.is_a?(Array)
          next unless check_method.include?(evo[2])
        elsif evo[2] != check_method
          next
        end
        return true if check_param.nil? || evo[3] == check_param
      end
      false
    end

    # Used by the Moon Ball when checking if a Pokémon's evolution family
    # includes an evolution that uses the Moon Stone.
    def family_item_evolutions_use_item?(check_item = nil)
      sp = get_baby_species
      evos = GameData::Species.get(sp).get_family_evolutions
      return false if !evos || evos.empty?

      evos.each do |evo|
        next if GameData::Evolution.get(evo[2]).use_item_proc.nil?
        return true if check_item.nil? || evo[3] == check_item
      end
      false
    end

    # utility function to get the first species in the evolutionary line
    def first_evo
      prev = GameData::Species.get(@id).previous_evo
      return @id if prev == @id

      GameData::Species.get(prev).previous_evo
    end

    # utility function to get the previous species in the evolutionary line
    def previous_evo
      return @id if @evolutions.empty?

      @evolutions.each { |evo| return GameData::Species.get_species_form(evo[0], @form).id if evo[3] } # Get prevolution
      @id
    end

    # utility function to get every evolution after defined species
    def next_evos
      evo = GameData::Species.get(@id).get_evolutions
      all = []
      return [@id] if evo.empty?

      evo.each do |arr|
        all += [GameData::Species.get_species_form(arr[0], @form).id]
        all += GameData::Species.get_species_form(arr[0], @form).next_evos
      end
      all.uniq
    end

    # utility function to get all species inside an evolutionary line
    def evolutionary_line
      sp = first_evo
      ([sp] + GameData::Species.get(sp).next_evos).uniq
    end

    def minimum_level
      return 1 if @evolutions.length == 0
      @evolutions.each do |evo|
        next if !evo[3]   # Check only the prevolution
        prevo_data = GameData::Species.get_species_form(evo[0], base_form)
        return 1 if !prevo_data.incense.nil?
        prevo_min_level = prevo_data.minimum_level
        evo_method_data = GameData::Evolution.get(evo[1])
        return prevo_min_level if evo_method_data.level_up_proc.nil? &&
                                  evo_method_data.battle_level_up_proc.nil? &&
                                  evo_method_data.id != :Shedinja
        any_level_up = evo_method_data.any_level_up
        return (any_level_up) ? prevo_min_level + 1 : evo[2]
      end
      return 1
    end

    alias __orig__get_property_for_PBS get_property_for_PBS unless method_defined?(:__orig__get_property_for_PBS)
    def get_property_for_PBS(key, writing_form = false)
      key = "SectionName" if key == "ID"
      ret = nil
      if self.class.schema(writing_form).include?(key)
        ret = self.send(self.class.schema(writing_form)[key][0])
        ret = nil if ret == false || (ret.is_a?(Array) && ret.length == 0)
      end
      case key
      when "SectionName"
        ret = [@species, @form] if writing_form
      when "FormName"
        ret = nil if nil_or_empty?(ret)
      when "PokedexForm"
        ret = nil if ret == @form
      when "UnmegaForm", "MegaMessage", "Generation"
        ret = nil if ret == 0
      when "BaseStats"
        new_ret = []
        GameData::Stat.each_main do |s|
          new_ret[s.pbs_order] = ret[s.id] if s.pbs_order >= 0
        end
        ret = new_ret
      when "EVs"
        new_ret = []
        GameData::Stat.each_main do |s|
          new_ret.push([s.id, ret[s.id]]) if ret[s.id] > 0 && s.pbs_order >= 0
        end
        ret = new_ret
      when "Height", "Weight"
        ret = ret.to_f / 10
      when "Habitat"
        ret = nil if ret == :None
      when "Evolutions", "Evolution"
        if ret
          ret = ret.reject { |evo| evo[3] }   # Remove prevolutions
          ret.each do |evo|
            param_type = GameData::Evolution.get(evo[1]).parameter
            if !param_type.nil?
              if param_type.is_a?(Symbol) && !GameData.const_defined?(param_type)
                evo[2] = getConstantName(param_type, evo[2])
              else
                evo[2] = evo[2].to_s
              end
            end
          end
          ret.each_with_index { |evo, i| ret[i] = evo[0, 3] }
          ret = nil if ret.length == 0
        end
      end
      if writing_form && !ret.nil?
        base_form = GameData::Species.get(@species)
        if !["WildItemCommon", "WildItemUncommon", "WildItemRare"].include?(key) ||
           (base_form.wild_item_common == @wild_item_common &&
           base_form.wild_item_uncommon == @wild_item_uncommon &&
           base_form.wild_item_rare == @wild_item_rare)
          ret = nil if base_form.get_property_for_PBS(key) == ret
        end
      end
      return ret
    end
  end
end

==============================================================================
# Script: Species_files
==============================================================================
module GameData
  class Species
    def self.check_graphic_file(path, species, form = 0, gender = 0, shiny = false, shadow = false, subfolder = "")
      try_subfolder = sprintf("%s/", subfolder)
      try_species = species
      try_form    = (form > 0) ? sprintf("_%d", form) : ""
      try_gender  = (gender == 1) ? "_female" : ""
      try_shadow  = (shadow) ? "_shadow" : ""
      factors = []
      factors.push([4, sprintf("%s shiny/", subfolder), try_subfolder]) if shiny
      factors.push([3, try_shadow, ""]) if shadow
      factors.push([2, try_gender, ""]) if gender == 1
      factors.push([1, try_form, ""]) if form > 0
      factors.push([0, try_species, "000"])
      # Go through each combination of parameters in turn to find an existing sprite
      (2**factors.length).times do |i|
        # Set try_ parameters for this combination
        factors.each_with_index do |factor, index|
          value = ((i / (2**index)).even?) ? factor[1] : factor[2]
          case factor[0]
          when 0 then try_species   = value
          when 1 then try_form      = value
          when 2 then try_gender    = value
          when 3 then try_shadow    = value
          when 4 then try_subfolder = value   # Shininess
          end
        end
        # Look for a graphic matching this combination's parameters
        try_species_text = try_species
        ret = pbResolveBitmap(sprintf("%s%s%s%s%s%s", path, try_subfolder,
                                      try_species_text, try_form, try_gender, try_shadow))
        return ret if ret
      end
      return nil
    end

    def self.check_egg_graphic_file(path, species, form, suffix = "")
      species_data = self.get_species_form(species, form)
      return nil if species_data.nil?
      
      if form > 0
        ret = pbResolveBitmap(sprintf("%s%s_%d%s", path, species_data.species, form, suffix))
        return ret if ret
      end
      
      ret = pbResolveBitmap(sprintf("%s%s%s", path, species_data.species, suffix))
      return ret if ret
      
      # Try baby species as fallback
      baby_species = species_data.get_baby_species
      return nil unless baby_species
      
      if form > 0
        ret = pbResolveBitmap(sprintf("%s%s_%d%s", path, baby_species, form, suffix))
        return ret if ret
      end
      
      pbResolveBitmap(sprintf("%s%s%s", path, baby_species, suffix))
    end

    def self.front_sprite_filename(species, form = 0, gender = 0, shiny = false, shadow = false)
      return self.check_graphic_file("Graphics/Pokemon/", species, form, gender, shiny, shadow, "Front")
    end

    def self.back_sprite_filename(species, form = 0, gender = 0, shiny = false, shadow = false)
      return self.check_graphic_file("Graphics/Pokemon/", species, form, gender, shiny, shadow, "Back")
    end

    def self.egg_sprite_filename(species, form)
      ret = self.check_egg_graphic_file("Graphics/Pokemon/Eggs/", species, form)
      return (ret) ? ret : pbResolveBitmap("Graphics/Pokemon/Eggs/000")
    end

    def self.egg_cracks_sprite_filename(species, form)
      ret = self.check_egg_graphic_file("Graphics/Pokemon/Eggs/", species, form, "_cracks")
      return (ret) ? ret : pbResolveBitmap("Graphics/Pokemon/Eggs/000_cracks")
    end

    def self.sprite_filename(species, form = 0, gender = 0, shiny = false, shadow = false, back = false, egg = false)
      return self.egg_sprite_filename(species, form) if egg
      return self.back_sprite_filename(species, form, gender, shiny, shadow) if back
      return self.front_sprite_filename(species, form, gender, shiny, shadow)
    end

    def self.front_sprite_bitmap(species, form = 0, gender = 0, shiny = false, shadow = false)
      filename = self.front_sprite_filename(species, form, gender, shiny, shadow)
      return (filename) ? AnimatedBitmap.new(filename) : nil
    end

    def self.back_sprite_bitmap(species, form = 0, gender = 0, shiny = false, shadow = false)
      filename = self.back_sprite_filename(species, form, gender, shiny, shadow)
      return (filename) ? AnimatedBitmap.new(filename) : nil
    end

    def self.egg_sprite_bitmap(species, form = 0)
      filename = self.egg_sprite_filename(species, form)
      return (filename) ? AnimatedBitmap.new(filename) : nil
    end

    def self.sprite_bitmap(species, form = 0, gender = 0, shiny = false, shadow = false, back = false, egg = false)
      return self.egg_sprite_bitmap(species, form) if egg
      return self.back_sprite_bitmap(species, form, gender, shiny, shadow) if back
      return self.front_sprite_bitmap(species, form, gender, shiny, shadow)
    end

    def self.sprite_bitmap_from_pokemon(pkmn, back = false, species = nil)
      species = pkmn.species if !species
      species = GameData::Species.get(species).species   # Just to be sure it's a symbol
      return self.egg_sprite_bitmap(species, pkmn.form) if pkmn.egg?
      if back
        ret = self.back_sprite_bitmap(species, pkmn.form, pkmn.gender, pkmn.shiny?, pkmn.shadowPokemon?)
      else
        ret = self.front_sprite_bitmap(species, pkmn.form, pkmn.gender, pkmn.shiny?, pkmn.shadowPokemon?)
      end
      alter_bitmap_function = MultipleForms.getFunction(species, "alterBitmap")
      if ret && alter_bitmap_function
        new_ret = ret.copy
        ret.dispose
        new_ret.each { |bitmap| alter_bitmap_function.call(pkmn, bitmap) }
        ret = new_ret
      end
      return ret
    end

    #===========================================================================

    def self.egg_icon_filename(species, form)
      ret = self.check_egg_graphic_file("Graphics/Pokemon/Eggs/", species, form, "_icon")
      return (ret) ? ret : pbResolveBitmap("Graphics/Pokemon/Eggs/000_icon")
    end

    def self.icon_filename(species, form = 0, gender = 0, shiny = false, shadow = false, egg = false)
      return self.egg_icon_filename(species, form) if egg
      return self.check_graphic_file("Graphics/Pokemon/", species, form, gender, shiny, shadow, "Icons")
    end

    def self.icon_filename_from_pokemon(pkmn)
      return self.icon_filename(pkmn.species, pkmn.form, pkmn.gender, pkmn.shiny?, pkmn.shadowPokemon?, pkmn.egg?)
    end

    def self.egg_icon_bitmap(species, form)
      filename = self.egg_icon_filename(species, form)
      return (filename) ? AnimatedBitmap.new(filename).deanimate : nil
    end

    def self.icon_bitmap(species, form = 0, gender = 0, shiny = false, shadow = false, egg = false)
      return self.egg_icon_bitmap(species, form) if egg
      filename = self.icon_filename(species, form, gender, shiny, shadow)
      return (filename) ? AnimatedBitmap.new(filename).deanimate : nil
    end

    def self.icon_bitmap_from_pokemon(pkmn)
      return self.icon_bitmap(pkmn.species, pkmn.form, pkmn.gender, pkmn.shiny?, pkmn.shadowPokemon?, pkmn.egg?)
    end

    #===========================================================================

    def self.footprint_filename(species, form = 0)
      species_data = self.get_species_form(species, form)
      return nil if species_data.nil?
      if form > 0
        ret = pbResolveBitmap(sprintf("Graphics/Pokemon/Footprints/%s_%d", species_data.species, form))
        return ret if ret
      end
      return pbResolveBitmap(sprintf("Graphics/Pokemon/Footprints/%s", species_data.species))
    end

    #===========================================================================

    def self.shadow_filename(species, form = 0)
      species_data = self.get_species_form(species, form)
      return nil if species_data.nil?
      # Look for species-specific shadow graphic
      if form > 0
        ret = pbResolveBitmap(sprintf("Graphics/Pokemon/Shadow/%s_%d", species_data.species, form))
        return ret if ret
      end
      ret = pbResolveBitmap(sprintf("Graphics/Pokemon/Shadow/%s", species_data.species))
      return ret if ret
      # Use general shadow graphic
      metrics_data = GameData::SpeciesMetrics.get_species_form(species_data.species, form)
      return pbResolveBitmap(sprintf("Graphics/Pokemon/Shadow/%d", metrics_data.shadow_size))
    end

    def self.shadow_bitmap(species, form = 0)
      filename = self.shadow_filename(species, form)
      return (filename) ? AnimatedBitmap.new(filename) : nil
    end

    def self.shadow_bitmap_from_pokemon(pkmn)
      filename = self.shadow_filename(pkmn.species, pkmn.form)
      return (filename) ? AnimatedBitmap.new(filename) : nil
    end

    #===========================================================================

    def self.check_cry_file(species, form, suffix = "")
      species_data = self.get_species_form(species, form)
      return nil if species_data.nil?
      if form > 0
        ret = sprintf("Cries/%s_%d%s", species_data.species, form, suffix)
        return ret if pbResolveAudioSE(ret)
      end
      ret = sprintf("Cries/%s%s", species_data.species, suffix)
      return (pbResolveAudioSE(ret)) ? ret : nil
    end

    def self.cry_filename(species, form = 0, suffix = "")
      return self.check_cry_file(species, form || 0, suffix)
    end

    def self.cry_filename_from_pokemon(pkmn, suffix = "")
      return self.check_cry_file(pkmn.species, pkmn.form, suffix)
    end

    def self.play_cry_from_species(species, form = 0, volume = 90, pitch = 100)
      filename = self.cry_filename(species, form)
      return if !filename
      pbPokemonCryPlay(RPG::AudioFile.new(filename, volume, pitch)) rescue nil
    end

    def self.play_cry_from_pokemon(pkmn, volume = 90, pitch = 100)
      return if !pkmn || pkmn.egg?
      filename = self.cry_filename_from_pokemon(pkmn)
      return if !filename
      pitch ||= 100
      pbPokemonCryPlay(RPG::AudioFile.new(filename, volume, pitch)) rescue nil
    end

    def self.play_cry(pkmn, volume = 90, pitch = 100)
      if pkmn.is_a?(Pokemon)
        self.play_cry_from_pokemon(pkmn, volume, pitch)
      else
        self.play_cry_from_species(pkmn, 0, volume, pitch)
      end
    end

    def self.cry_length(species, form = 0, pitch = 100, suffix = "")
      pitch ||= 100
      return 0 if !species || pitch <= 0
      pitch = pitch.to_f / 100
      ret = 0.0
      if species.is_a?(Pokemon)
        if !species.egg?
          filename = self.cry_filename_from_pokemon(species, suffix)
          filename = self.cry_filename_from_pokemon(species) if !filename && !nil_or_empty?(suffix)
          filename = pbResolveAudioSE(filename)
          ret = getPlayTime(filename) if filename
        end
      else
        filename = self.cry_filename(species, form, suffix)
        filename = self.cry_filename(species, form) if !filename && !nil_or_empty?(suffix)
        filename = pbResolveAudioSE(filename)
        ret = getPlayTime(filename) if filename
      end
      ret /= pitch   # Sound played at a lower pitch lasts longer
      return ret
    end
  end
end

==============================================================================
# Script: SpeciesMetrics
==============================================================================
module GameData
  class SpeciesMetrics
    attr_reader   :id
    attr_reader   :species
    attr_reader   :form
    attr_accessor :back_sprite
    attr_accessor :front_sprite
    attr_accessor :front_sprite_altitude
    attr_accessor :shadow_x
    attr_accessor :shadow_size
    attr_reader   :pbs_file_suffix

    DATA = {}
    DATA_FILENAME = "species_metrics.dat"
    PBS_BASE_FILENAME = "pokemon_metrics"

    SCHEMA = {
      "SectionName"         => [:id,                    "eV", :Species],
      "BackSprite"          => [:back_sprite,           "ii"],
      "FrontSprite"         => [:front_sprite,          "ii"],
      "FrontSpriteAltitude" => [:front_sprite_altitude, "i"],
      "ShadowX"             => [:shadow_x,              "i"],
      "ShadowSize"          => [:shadow_size,           "u"]
    }

    extend ClassMethodsSymbols
    include InstanceMethods

    # @param species [Symbol, String]
    # @param form [Integer]
    # @return [self, nil]
    def self.get_species_form(species, form)
      return nil if !species || !form
      validate species => [Symbol, String]
      validate form => Integer
      raise _INTL("Especie no definida {1}.", species) if !GameData::Species.exists?(species)
      species = species.to_sym if species.is_a?(String)
      if form > 0
        trial = sprintf("%s_%d", species, form).to_sym
        if !DATA.has_key?(trial)
          self.register({:id => species}) if !DATA[species]
          self.register({
            :id                    => trial,
            :species               => species,
            :form                  => form,
            :back_sprite           => DATA[species].back_sprite.clone,
            :front_sprite          => DATA[species].front_sprite.clone,
            :front_sprite_altitude => DATA[species].front_sprite_altitude,
            :shadow_x              => DATA[species].shadow_x,
            :shadow_size           => DATA[species].shadow_size
          })
        end
        return DATA[trial]
      end
      self.register({:id => species}) if !DATA[species]
      return DATA[species]
    end

    def initialize(hash)
      @id                    = hash[:id]
      @species               = hash[:species]               || @id
      @form                  = hash[:form]                  || 0
      @back_sprite           = hash[:back_sprite]           || [0, 0]
      @front_sprite          = hash[:front_sprite]          || [0, 0]
      @front_sprite_altitude = hash[:front_sprite_altitude] || 0
      @shadow_x              = hash[:shadow_x]              || 0
      @shadow_size           = hash[:shadow_size]           || 2
      @pbs_file_suffix       = hash[:pbs_file_suffix]       || ""
    end

    def apply_metrics_to_sprite(sprite, index, shadow = false)
      if shadow
        sprite.x += @shadow_x * 2 if (index & 1) == 1   # Foe Pokémon
      elsif (index & 1) == 0   # Player's Pokémon
        sprite.x += @back_sprite[0] * 2
        sprite.y += @back_sprite[1] * 2
      else                     # Foe Pokémon
        sprite.x += @front_sprite[0] * 2
        sprite.y += @front_sprite[1] * 2
        sprite.y -= @front_sprite_altitude * 2
      end
    end

    def shows_shadow?
      return true
#      return @front_sprite_altitude > 0
    end

    alias __orig__get_property_for_PBS get_property_for_PBS unless method_defined?(:__orig__get_property_for_PBS)
    def get_property_for_PBS(key)
      ret = __orig__get_property_for_PBS(key)
      case key
      when "SectionName"
        ret = [@species, (@form > 0) ? @form : nil]
      when "FrontSpriteAltitude"
        ret = nil if ret == 0
      end
      return ret
    end
  end
end


