==============================================================================
# Script: Battle
==============================================================================
#===============================================================================
# Results of battle (see module Outcome):
#    0 - Undecided or aborted
#    1 - Player won
#    2 - Player lost
#    3 - Player or wild Pokémon ran from battle, or player forfeited the match
#    4 - Wild Pokémon was caught
#    5 - Draw
# Possible actions a battler can take in a round:
#    :None
#    :UseMove
#    :SwitchOut
#    :UseItem
#    :Call
#    :Run
#    :Shift
# NOTE: If you want to have more than 3 Pokémon on a side at once, you will need
#       to edit some code. Mainly this is to change/add coordinates for the
#       sprites, describe the relationships between Pokémon and trainers, and to
#       change messages. The methods that will need editing are as follows:
#           class Battle
#             def setBattleMode
#             def pbGetOwnerIndexFromBattlerIndex
#             def pbGetOpposingIndicesInOrder
#             def nearBattlers?
#             def pbStartBattleSendOut
#             def pbEORShiftDistantBattlers
#             def pbCanShift?
#             def pbEndOfRoundPhase
#           class Battle::Scene::TargetMenu
#             def initialize
#           class Battle::Scene::PokemonDataBox
#             def initializeDataBoxGraphic
#           class Battle::Scene
#             def self.pbBattlerPosition
#             def self.pbTrainerPosition
#           class Game_Temp
#             def add_battle_rule
#       (There is no guarantee that this list is complete.)
#===============================================================================
class Battle
  module Outcome
    UNDECIDED = 0
    WIN       = 1
    LOSE      = 2   # Also used when player forfeits a trainer battle
    FLEE      = 3   # Player or wild Pokémon ran away, count as a win
    CATCH     = 4   # Counts as a win
    DRAW      = 5

    def self.decided?(decision)
      return decision != UNDECIDED
    end

    def self.should_black_out?(decision)
      return decision == LOSE || decision == DRAW
    end

    def self.success?(decision)
      return !self.should_black_out?(decision)
    end
  end

  #-----------------------------------------------------------------------------

  attr_reader   :scene            # Scene object for this battle
  attr_reader   :peer
  attr_reader   :field            # Effects common to the whole of a battle
  attr_reader   :sides            # Effects common to each side of a battle
  attr_reader   :positions        # Effects that apply to a battler position
  attr_reader   :battlers         # Currently active Pokémon
  attr_reader   :sideSizes        # Array of number of battlers per side
  attr_accessor :backdrop         # Filename fragment used for background graphics
  attr_accessor :backdropBase     # Filename fragment used for base graphics
  attr_accessor :time             # Time of day (0=day, 1=eve, 2=night)
  attr_accessor :environment      # Battle surroundings (for mechanics purposes)
  attr_reader   :turnCount
  attr_accessor :decision         # Outcome of battle
  attr_reader   :player           # Player trainer (or array of trainers)
  attr_reader   :opponent         # Opponent trainer (or array of trainers)
  attr_accessor :items            # Items held by opponents
  attr_accessor :ally_items       # Items held by allies
  attr_accessor :party1starts     # Array of start indexes for each player-side trainer's party
  attr_accessor :party2starts     # Array of start indexes for each opponent-side trainer's party
  attr_accessor :internalBattle   # Internal battle flag
  attr_accessor :debug            # Debug flag
  attr_accessor :controlPlayer    # Whether player's Pokémon are AI controlled
  attr_accessor :sendToBoxes      # Send to Boxes (0=ask, 1=don't ask, 2=must add to party)
  attr_accessor :rules
  attr_accessor :choices          # Choices made by each Pokémon this round
  attr_accessor :megaEvolution    # Battle index of each trainer's Pokémon to Mega Evolve
  attr_reader   :initialItems
  attr_reader   :recycleItems
  attr_reader   :belch
  attr_reader   :abilitiesUsedPerSwitchIn   # Records use of abilities that can only be used once per switch in
  attr_reader   :abilitiesUsedOnce          # Records use of abilities that can only be used once per battle
  attr_reader   :corrosiveGas
  attr_reader   :usedInBattle     # Whether each Pokémon was used in battle (for Burmy)
  attr_reader   :hitsTakenCounts  # For Rage Fist
  attr_reader   :sideFaintCounts  # For Last Respects
  attr_reader   :successStates    # Success states
  attr_accessor :lastMoveUsed     # Last move used
  attr_accessor :lastMoveUser     # Last move user
  attr_accessor :first_poke_ball  # ID of the first thrown Poké Ball that failed
  attr_accessor :poke_ball_failed # Set after first_poke_ball to prevent it being set again
  attr_reader   :switching        # True if during the switching phase of the round
  attr_reader   :futureSight      # True if Future Sight is hitting
  attr_reader   :command_phase
  attr_reader   :endOfRound       # True during the end of round
  attr_accessor :moldBreaker      # True if Mold Breaker applies
  attr_reader   :struggle         # The Struggle move
  attr_accessor :adjust_levels
  attr_accessor :adjust_levels_reset_moves
  def pbRandom(x); return rand(x); end

  #=============================================================================
  # Creating the battle class
  #=============================================================================
  def initialize(scene, p1, p2, player, opponent)
    if p1.length == 0
      raise ArgumentError.new(_INTL("Equipo 1 no tiene Pokémon."))
    elsif p2.length == 0
      raise ArgumentError.new(_INTL("Equipo 2 no tiene Pokémon."))
    end
    @scene             = scene
    @peer              = Peer.new
    @field             = ActiveField.new    # Whole field (gravity/rooms)
    @sides             = [ActiveSide.new,   # Player's side
                          ActiveSide.new]   # Foe's side
    @positions         = []                 # Battler positions
    @battlers          = []
    @sideSizes         = [1, 1]   # Single battle, 1v1
    @backdrop          = ""
    @backdropBase      = nil
    @time              = 0
    @environment       = :None   # e.g. Tall grass, cave, still water
    @turnCount         = 0
    @decision          = Outcome::UNDECIDED
    @caughtPokemon     = []
    player   = [player] if !player.nil? && !player.is_a?(Array)
    opponent = [opponent] if !opponent.nil? && !opponent.is_a?(Array)
    @player            = player     # Array of Player/NPCTrainer objects, or nil
    @opponent          = opponent   # Array of NPCTrainer objects, or nil
    @items             = nil
    @ally_items        = nil        # Array of items held by ally. This is just used for Mega Evolution for now.
    @party1            = p1
    @party2            = p2
    @party1order       = Array.new(@party1.length) { |i| i }
    @party2order       = Array.new(@party2.length) { |i| i }
    @party1starts      = [0]
    @party2starts      = [0]
    @internalBattle    = true
    @debug             = false
    @controlPlayer     = false
    @sendToBoxes       = 1
    @rules             = {}
    @priority          = []
    @priorityTrickRoom = false
    @choices           = []
    @megaEvolution     = [
      [-1] * (@player ? @player.length : 1),
      [-1] * (@opponent ? @opponent.length : 1)
    ]
    @initialItems      = [
      Array.new(@party1.length) { |i| [@party1[i]&.item_id, 0, i, false] },
      Array.new(@party2.length) { |i| [@party2[i]&.item_id, 1, i, false] }
    ]
    @recycleItems      = [Array.new(@party1.length, nil),   Array.new(@party2.length, nil)]
    @belch             = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
    @abilitiesUsedPerSwitchIn = [Array.new(@party1.length) { |i| [] }, Array.new(@party2.length) { |i| [] }]
    @abilitiesUsedOnce        = [Array.new(@party1.length) { |i| [] }, Array.new(@party2.length) { |i| [] }]
    @corrosiveGas      = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
    @usedInBattle      = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
    @hitsTakenCounts   = [Array.new(@party1.length, 0),     Array.new(@party2.length, 0)]
    @sideFaintCounts   = [0, 0]
    @successStates     = []
    @lastMoveUsed      = nil
    @lastMoveUser      = -1
    @switching         = false
    @futureSight       = false
    @command_phase     = false
    @endOfRound        = false
    @moldBreaker       = false
    @runCommand        = 0
    @nextPickupUse     = 0
    @struggle          = Move::Struggle.new(self, nil)
    @mega_rings        = []
    GameData::Item.each { |item| @mega_rings.push(item.id) if item.has_flag?("MegaRing") }
    @battleAI          = AI.new(self)
    @adjust_levels   = false
    @adjust_levels_reset_moves   = false
  end

  def decided?
    return Outcome.decided?(@decision)
  end

  #-----------------------------------------------------------------------------
  # Information about the type and size of the battle.
  #-----------------------------------------------------------------------------

  def wildBattle?;    return @opponent.nil?;  end
  def trainerBattle?; return !@opponent.nil?; end

  # Sets the number of battler slots on each side of the field independently.
  # For "1v2" names, the first number is for the player's side and the second
  # number is for the opposing side.
  def setBattleMode(mode)
    @sideSizes =
      case mode
      when "triple", "3v3" then [3, 3]
      when "3v2"           then [3, 2]
      when "3v1"           then [3, 1]
      when "2v3"           then [2, 3]
      when "double", "2v2" then [2, 2]
      when "2v1"           then [2, 1]
      when "1v3"           then [1, 3]
      when "1v2"           then [1, 2]
      else                      [1, 1]   # Single, 1v1 (default)
      end
  end

  def singleBattle?
    return pbSideSize(0) == 1 && pbSideSize(1) == 1
  end

  def pbSideSize(index)
    return @sideSizes[index % 2]
  end

  def maxBattlerIndex
    return (pbSideSize(0) > pbSideSize(1)) ? (pbSideSize(0) - 1) * 2 : (pbSideSize(1) * 2) - 1
  end

  #-----------------------------------------------------------------------------
  # Trainers and owner-related methods.
  #-----------------------------------------------------------------------------

  def pbPlayer; return @player[0]; end

  # Given a battler index, returns the index within @player/@opponent of the
  # trainer that controls that battler index.
  # NOTE: You shouldn't ever have more trainers on a side than there are battler
  #       positions on that side. This method doesn't account for if you do.
  def pbGetOwnerIndexFromBattlerIndex(idxBattler)
    trainer = (opposes?(idxBattler)) ? @opponent : @player
    return 0 if !trainer
    case trainer.length
    when 2
      n = pbSideSize(idxBattler % 2)
      return [0, 0, 1][idxBattler / 2] if n == 3
      return idxBattler / 2   # Same as [0,1][idxBattler/2], i.e. 2 battler slots
    when 3
      return idxBattler / 2
    end
    return 0
  end

  def pbGetOwnerFromBattlerIndex(idxBattler)
    idxTrainer = pbGetOwnerIndexFromBattlerIndex(idxBattler)
    trainer = (opposes?(idxBattler)) ? @opponent : @player
    return (trainer.nil?) ? nil : trainer[idxTrainer]
  end

  def pbGetOwnerIndexFromPartyIndex(idxBattler, idxParty)
    ret = -1
    pbPartyStarts(idxBattler).each_with_index do |start, i|
      break if start > idxParty
      ret = i
    end
    return ret
  end

  # Only used for the purpose of an error message when one trainer tries to
  # switch another trainer's Pokémon.
  def pbGetOwnerFromPartyIndex(idxBattler, idxParty)
    idxTrainer = pbGetOwnerIndexFromPartyIndex(idxBattler, idxParty)
    trainer = (opposes?(idxBattler)) ? @opponent : @player
    return (trainer.nil?) ? nil : trainer[idxTrainer]
  end

  def pbGetOwnerName(idxBattler)
    idxTrainer = pbGetOwnerIndexFromBattlerIndex(idxBattler)
    return @opponent[idxTrainer].full_name if opposes?(idxBattler)   # Opponent
    return @player[idxTrainer].full_name if idxTrainer > 0   # Ally trainer
    return @player[idxTrainer].name   # Player
  end

  def pbGetOwnerItems(idxBattler)
    if opposes?(idxBattler)
      return [] if !@items
      return @items[pbGetOwnerIndexFromBattlerIndex(idxBattler)]
    end
    return [] if !@ally_items
    return @ally_items[pbGetOwnerIndexFromBattlerIndex(idxBattler)]
  end

  # Returns whether the battler in position idxBattler is owned by the same
  # trainer that owns the Pokémon in party slot idxParty. This assumes that
  # both the battler position and the party slot are from the same side.
  def pbIsOwner?(idxBattler, idxParty)
    idxTrainer1 = pbGetOwnerIndexFromBattlerIndex(idxBattler)
    idxTrainer2 = pbGetOwnerIndexFromPartyIndex(idxBattler, idxParty)
    return idxTrainer1 == idxTrainer2
  end

  def pbOwnedByPlayer?(idxBattler)
    return false if opposes?(idxBattler)
    return pbGetOwnerIndexFromBattlerIndex(idxBattler) == 0
  end

  # Returns the number of Pokémon positions controlled by the given trainerIndex
  # on the given side of battle.
  def pbNumPositions(side, idxTrainer)
    ret = 0
    pbSideSize(side).times do |i|
      t = pbGetOwnerIndexFromBattlerIndex((i * 2) + side)
      next if t != idxTrainer
      ret += 1
    end
    return ret
  end

  #-----------------------------------------------------------------------------
  # Get party information (counts all teams on the same side).
  #-----------------------------------------------------------------------------

  def pbParty(idxBattler)
    return (opposes?(idxBattler)) ? @party2 : @party1
  end

  def pbOpposingParty(idxBattler)
    return (opposes?(idxBattler)) ? @party1 : @party2
  end

  def pbPartyOrder(idxBattler)
    return (opposes?(idxBattler)) ? @party2order : @party1order
  end

  def pbPartyStarts(idxBattler)
    return (opposes?(idxBattler)) ? @party2starts : @party1starts
  end

  # Returns the player's team in its display order. Used when showing the party
  # screen.
  def pbPlayerDisplayParty(idxBattler = 0)
    partyOrders = pbPartyOrder(idxBattler)
    idxStart, _idxEnd = pbTeamIndexRangeFromBattlerIndex(idxBattler)
    ret = []
    eachInTeamFromBattlerIndex(idxBattler) { |pkmn, i| ret[partyOrders[i] - idxStart] = pkmn }
    return ret
  end

  def pbAbleCount(idxBattler = 0)
    party = pbParty(idxBattler)
    count = 0
    party.each { |pkmn| count += 1 if pkmn&.able? }
    return count
  end

  def pbAbleNonActiveCount(idxBattler = 0)
    party = pbParty(idxBattler)
    inBattleIndices = allSameSideBattlers(idxBattler, true).map { |b| b.pokemonIndex }
    count = 0
    party.each_with_index do |pkmn, idxParty|
      next if !pkmn || !pkmn.able?
      next if inBattleIndices.include?(idxParty)
      count += 1
    end
    return count
  end

  def pbAllFainted?(idxBattler = 0)
    return pbAbleCount(idxBattler) == 0
  end

  def pbTeamAbleNonActiveCount(idxBattler = 0)
    inBattleIndices = allSameSideBattlers(idxBattler, true).map { |b| b.pokemonIndex }
    count = 0
    eachInTeamFromBattlerIndex(idxBattler) do |pkmn, i|
      next if !pkmn || !pkmn.able?
      next if inBattleIndices.include?(i)
      count += 1
    end
    return count
  end

  # For the given side of the field (0=player's, 1=opponent's), returns an array
  # containing the number of able Pokémon in each team.
  def pbAbleTeamCounts(side)
    party = pbParty(side)
    partyStarts = pbPartyStarts(side)
    ret = []
    idxTeam = -1
    nextStart = 0
    party.each_with_index do |pkmn, i|
      if i >= nextStart
        idxTeam += 1
        nextStart = (idxTeam < partyStarts.length - 1) ? partyStarts[idxTeam + 1] : party.length
      end
      next if !pkmn || !pkmn.able?
      ret[idxTeam] = 0 if !ret[idxTeam]
      ret[idxTeam] += 1
    end
    return ret
  end

  #-----------------------------------------------------------------------------
  # Get team information (a team is only the Pokémon owned by a particular
  # trainer).
  #-----------------------------------------------------------------------------

  def pbTeamIndexRangeFromBattlerIndex(idxBattler)
    partyStarts = pbPartyStarts(idxBattler)
    idxTrainer = pbGetOwnerIndexFromBattlerIndex(idxBattler)
    idxPartyStart = partyStarts[idxTrainer]
    idxPartyEnd   = (idxTrainer < partyStarts.length - 1) ? partyStarts[idxTrainer + 1] : pbParty(idxBattler).length
    return idxPartyStart, idxPartyEnd
  end

  def pbTeamLengthFromBattlerIndex(idxBattler)
    idxPartyStart, idxPartyEnd = pbTeamIndexRangeFromBattlerIndex(idxBattler)
    return idxPartyEnd - idxPartyStart
  end

  def eachInTeamFromBattlerIndex(idxBattler)
    party = pbParty(idxBattler)
    idxPartyStart, idxPartyEnd = pbTeamIndexRangeFromBattlerIndex(idxBattler)
    party.each_with_index { |pkmn, i| yield pkmn, i if pkmn && i >= idxPartyStart && i < idxPartyEnd }
  end

  def eachInTeam(side, idxTrainer)
    party       = pbParty(side)
    partyStarts = pbPartyStarts(side)
    idxPartyStart = partyStarts[idxTrainer]
    idxPartyEnd   = (idxTrainer < partyStarts.length - 1) ? partyStarts[idxTrainer + 1] : party.length
    party.each_with_index { |pkmn, i| yield pkmn, i if pkmn && i >= idxPartyStart && i < idxPartyEnd }
  end

  # Used for Illusion.
  # NOTE: This cares about the temporary rearranged order of the team. That is,
  #       if you do some switching, the last Pokémon in the team could change
  #       and the Illusion could be a different Pokémon.
  def pbLastInTeam(idxBattler)
    party       = pbParty(idxBattler)
    partyOrders = pbPartyOrder(idxBattler)
    idxPartyStart, idxPartyEnd = pbTeamIndexRangeFromBattlerIndex(idxBattler)
    ret = -1
    party.each_with_index do |pkmn, i|
      next if i < idxPartyStart || i >= idxPartyEnd   # Check the team only
      next if !pkmn || !pkmn.able?   # Can't copy a non-fainted Pokémon or egg
      ret = i if ret < 0 || partyOrders[i] > partyOrders[ret]
    end
    return ret
  end

  # Used to calculate money gained/lost after winning/losing a battle.
  def pbMaxLevelInTeam(side, idxTrainer)
    ret = 1
    eachInTeam(side, idxTrainer) do |pkmn, _i|
      ret = pkmn.level if pkmn.level > ret
    end
    return ret
  end

  #-----------------------------------------------------------------------------
  # Iterate through battlers.
  #-----------------------------------------------------------------------------

  def allBattlers(with_commanders = false)
    return @battlers.select { |b| b && !b.fainted? && (with_commanders || b.effects[PBEffects::Commanding] < 0) }
  end

  # Unused
  def eachBattler(with_commanders = false)
    allBattlers(with_commanders).each { |b| yield b }
  end

  def allSameSideBattlers(idxBattler = 0, with_commanders = false)
    idxBattler = idxBattler.index if idxBattler.respond_to?("index")
    return @battlers.select { |b| b && !b.fainted? && !b.opposes?(idxBattler) &&
                                  (with_commanders || b.effects[PBEffects::Commanding] < 0) }
  end

  # Unused
  def eachSameSideBattler(idxBattler = 0, with_commanders = false)
    allSameSideBattlers(idxBattler, with_commanders).each { |b| yield b }
  end

  def allOtherSideBattlers(idxBattler = 0, with_commanders = false)
    idxBattler = idxBattler.index if idxBattler.respond_to?("index")
    return @battlers.select { |b| b && !b.fainted? && b.opposes?(idxBattler) &&
                                  (with_commanders || b.effects[PBEffects::Commanding] < 0) }
  end

  # Unused
  def eachOtherSideBattler(idxBattler = 0, with_commanders = false)
    allOtherSideBattlers(idxBattler).each { |b| yield b }
  end

  def pbSideBattlerCount(idxBattler = 0, with_commanders = false)
    return allSameSideBattlers(idxBattler, with_commanders).length
  end

  def pbOpposingBattlerCount(idxBattler = 0, with_commanders = false)
    return allOtherSideBattlers(idxBattler, with_commanders).length
  end

  # This method only counts the player's Pokémon, not a partner trainer's.
  def pbPlayerBattlerCount
    return allSameSideBattlers(0, true).select { |b| b.pbOwnedByPlayer? }.length
  end

  def pbCheckGlobalAbility(abil, check_mold_breaker = false)
    allBattlers.each do |b|
      return b if b.hasActiveAbility?(abil) && (!check_mold_breaker || !b.beingMoldBroken?)
    end
    return nil
  end

  def pbCheckOpposingAbility(abil, idxBattler = 0, nearOnly = false)
    allOtherSideBattlers(idxBattler).each do |b|
      next if nearOnly && !b.near?(idxBattler)
      return b if b.hasActiveAbility?(abil)
    end
    return nil
  end

  # Returns an array containing the IDs of all active abilities.
  def pbAllActiveAbilities
    ret = []
    allBattlers.each { |b| ret.push(b.ability_id) if b.abilityActive? }
    return ret
  end

  # Given a battler index, and using battle side sizes, returns an array of
  # battler indices from the opposing side that are in order of most "opposite".
  # Used when choosing a target and pressing up/down to move the cursor to the
  # opposite side, and also when deciding which target to select first for some
  # moves.
  def pbGetOpposingIndicesInOrder(idxBattler)
    case pbSideSize(0)
    when 1
      case pbSideSize(1)
      when 1   # 1v1 single
        return [0] if opposes?(idxBattler)
        return [1]
      when 2   # 1v2
        return [0] if opposes?(idxBattler)
        return [3, 1]
      when 3   # 1v3
        return [0] if opposes?(idxBattler)
        return [3, 5, 1]
      end
    when 2
      case pbSideSize(1)
      when 1   # 2v1
        return [0, 2] if opposes?(idxBattler)
        return [1]
      when 2   # 2v2 double
        return [[3, 1], [2, 0], [1, 3], [0, 2]][idxBattler]
      when 3   # 2v3
        return [[5, 3, 1], [2, 0], [3, 1, 5]][idxBattler] if idxBattler < 3
        return [0, 2]
      end
    when 3
      case pbSideSize(1)
      when 1   # 3v1
        return [2, 0, 4] if opposes?(idxBattler)
        return [1]
      when 2   # 3v2
        return [[3, 1], [2, 4, 0], [3, 1], [2, 0, 4], [1, 3]][idxBattler]
      when 3   # 3v3 triple
        return [[5, 3, 1], [4, 2, 0], [3, 5, 1], [2, 0, 4], [1, 3, 5], [0, 2, 4]][idxBattler]
      end
    end
    return [idxBattler]
  end

  #-----------------------------------------------------------------------------
  # Comparing the positions of two battlers.
  #-----------------------------------------------------------------------------

  def opposes?(idxBattler1, idxBattler2 = 0)
    idxBattler1 = idxBattler1.index if idxBattler1.respond_to?("index")
    idxBattler2 = idxBattler2.index if idxBattler2.respond_to?("index")
    return (idxBattler1 & 1) != (idxBattler2 & 1)
  end

  def nearBattlers?(idxBattler1, idxBattler2)
    return false if idxBattler1 == idxBattler2
    return true if pbSideSize(0) <= 2 && pbSideSize(1) <= 2
    # Get all pairs of battler positions that are not close to each other
    pairsArray = [[0, 4], [1, 5]]   # Covers 3v1 and 1v3
    case pbSideSize(0)
    when 3
      case pbSideSize(1)
      when 3   # 3v3 (triple)
        pairsArray.push([0, 1])
        pairsArray.push([4, 5])
      when 2   # 3v2
        pairsArray.push([0, 1])
        pairsArray.push([3, 4])
      end
    when 2       # 2v3
      pairsArray.push([0, 1])
      pairsArray.push([2, 5])
    end
    # See if any pair matches the two battlers being assessed
    pairsArray.each do |pair|
      return false if pair.include?(idxBattler1) && pair.include?(idxBattler2)
    end
    return true
  end

  #-----------------------------------------------------------------------------
  # Altering a party or rearranging battlers.
  #-----------------------------------------------------------------------------

  def pbRemoveFromParty(idxBattler, idxParty)
    party = pbParty(idxBattler)
    # Erase the Pokémon from the party
    party[idxParty] = nil
    # Rearrange the display order of the team to place the erased Pokémon last
    # in it (to avoid gaps)
    partyOrders = pbPartyOrder(idxBattler)
    partyStarts = pbPartyStarts(idxBattler)
    idxTrainer = pbGetOwnerIndexFromPartyIndex(idxBattler, idxParty)
    idxPartyStart = partyStarts[idxTrainer]
    idxPartyEnd   = (idxTrainer < partyStarts.length - 1) ? partyStarts[idxTrainer + 1] : party.length
    origPartyPos = partyOrders[idxParty]   # Position of erased Pokémon initially
    partyOrders[idxParty] = idxPartyEnd   # Put erased Pokémon last in the team
    party.each_with_index do |_pkmn, i|
      next if i < idxPartyStart || i >= idxPartyEnd   # Only check the team
      next if partyOrders[i] < origPartyPos   # Appeared before erased Pokémon
      partyOrders[i] -= 1   # Appeared after erased Pokémon; bump it up by 1
    end
  end

  def pbSwapBattlers(idxA, idxB)
    return false if !@battlers[idxA] || !@battlers[idxB]
    # Can't swap if battlers aren't owned by the same trainer
    return false if opposes?(idxA, idxB)
    return false if pbGetOwnerIndexFromBattlerIndex(idxA) != pbGetOwnerIndexFromBattlerIndex(idxB)
    @battlers[idxA],       @battlers[idxB]       = @battlers[idxB],       @battlers[idxA]
    @battlers[idxA].index, @battlers[idxB].index = @battlers[idxB].index, @battlers[idxA].index
    @choices[idxA],        @choices[idxB]        = @choices[idxB],        @choices[idxA]
    @scene.pbSwapBattlerSprites(idxA, idxB)
    # Swap the target of any battlers' effects that point at either of the
    # swapped battlers, to ensure they still point at the correct target
    # NOTE: LeechSeed is not swapped, because drained HP goes to whichever
    #       Pokémon is in the position that Leech Seed was used from.
    # NOTE: PerishSongUser doesn't need to change, as it's only used to
    #       determine which side the Perish Song user was on, and a battler
    #       can't change sides.
    effectsToSwap = [PBEffects::Attract,
                     PBEffects::BideTarget,
                     PBEffects::CommandedBy,
                     PBEffects::Commanding,
                     PBEffects::CounterTarget,
                     PBEffects::JawLock,
                     PBEffects::LockOnPos,
                     PBEffects::MeanLook,
                     PBEffects::MirrorCoatTarget,
                     PBEffects::Octolock,
                     PBEffects::SkyDrop,
                     PBEffects::SyrupBombUser,
                     PBEffects::TrappingUser]
    allBattlers(true).each do |b|
      effectsToSwap.each do |i|
        next if b.effects[i] != idxA && b.effects[i] != idxB
        b.effects[i] = (b.effects[i] == idxA) ? idxB : idxA
      end
    end
    return true
  end

  #-----------------------------------------------------------------------------
  #
  #-----------------------------------------------------------------------------

  # Returns the battler representing the Pokémon at index idxParty in its party,
  # on the same side as a battler with battler index of idxBattlerOther.
  def pbFindBattler(idxParty, idxBattlerOther = 0)
    allSameSideBattlers(idxBattlerOther, true).each { |b| return b if b.pokemonIndex == idxParty }
    return nil
  end

  # Only used for Wish, as the Wishing Pokémon will no longer be in battle.
  def pbThisEx(idxBattler, idxParty)
    party = pbParty(idxBattler)
    if opposes?(idxBattler)
      return _INTL("El {1} enemigo", party[idxParty].name) if trainerBattle?
      return _INTL("El {1} salvaje", party[idxParty].name)
    end
    return _INTL("El {1} aliado", party[idxParty].name) if !pbOwnedByPlayer?(idxBattler)
    return party[idxParty].name
  end

  def pbSetSeen(battler)
    return if !battler || !@internalBattle
    if battler.is_a?(Battler)
      pbPlayer.pokedex.register(battler.displaySpecies, battler.displayGender,
                                battler.displayForm, battler.shiny?)
    else
      pbPlayer.pokedex.register(battler)
    end
  end

  def pbSetCaught(battler)
    return if !battler || !@internalBattle
    if battler.is_a?(Battler)
      pbPlayer.pokedex.register_caught(battler.displaySpecies)
    else
      pbPlayer.pokedex.register_caught(battler.species)
    end
  end

  def pbSetDefeated(battler)
    return if !battler || !@internalBattle
    if battler.is_a?(Battler)
      pbPlayer.pokedex.register_defeated(battler.displaySpecies)
    else
      pbPlayer.pokedex.register_defeated(battler.species)
    end
    
    # Add counter for evolution method Bisharp -> Kingambit
    return if battler.lastFoeAttacker.empty?
    attacker = @battlers[battler.lastFoeAttacker.last]
    return if !attacker || !attacker.pbOwnedByPlayer?
    return if attacker.species != battler.species
    attacker.pokemon.leaders_crest_evolution(battler.item_id)
  end

  def initialItem(side, idxParty)
    @initialItems.each do |this_side|
      this_side.each do |this_pkmn|
        return this_pkmn[0] if this_pkmn[1] == side && this_pkmn[2] == idxParty
      end
    end
    return nil
  end

  def swapHeldItems(battler1, battler2)
    item1 = battler1.item_id
    item2 = battler2.item_id
    battler1.item = item2
    battler1.effects[PBEffects::ChoiceBand] = nil if !battler1.hasActiveAbility?(:GORILLATACTICS)
    battler1.effects[PBEffects::Unburden]   = (item1 && !battler1.item) if battler1.hasActiveAbility?(:UNBURDEN)
    battler2.item = item1
    battler2.effects[PBEffects::ChoiceBand] = nil if !battler2.hasActiveAbility?(:GORILLATACTICS)
    battler2.effects[PBEffects::Unburden]   = (item2 && !battler2.item) if battler2.hasActiveAbility?(:UNBURDEN)
    s1 = battler1.idxOwnSide
    p1 = battler1.pokemonIndex
    s2 = battler2.idxOwnSide
    p2 = battler2.pokemonIndex
    @initialItems[s1][p1], @initialItems[s2][p2] = @initialItems[s2][p2], @initialItems[s1][p1]
  end

  def knockOffItem(side, idxParty)
    @initialItems[side][idxParty][3] = true
  end

  def recycleItem(side, idxParty)
    return @recycleItems[side][idxParty]
  end

  def setRecycleItem(side, idxParty, new_item)
    @recycleItems[side][idxParty] = new_item
  end

  def clearStagesChangeRecords
    allBattlers(true).each { |b| b.clearStagesChangeRecord }
  end

  # For Opportunist/Mirror Herb to copy stat raises.
  def checkStatChangeResponses
    allBattlers(true).each do |b|
      if b.abilityActive?
        Battle::AbilityEffects.triggerCopyStatChanges(b.ability, b, self)
      end
      if b.itemActive?
        Battle::ItemEffects.triggerCopyStatChanges(b.item, b, self)
      end
    end
    clearStagesChangeRecords
  end

  def nextPickupUse
    @nextPickupUse += 1
    return @nextPickupUse
  end

  #=============================================================================
  # Weather
  #=============================================================================
  def defaultWeather=(value)
    @field.defaultWeather  = value
    @field.weather         = value
    @field.weatherDuration = -1
  end

  # Returns the effective weather (note that weather effects can be negated)
  def pbWeather
    return :None if allBattlers.any? { |b| b.hasActiveAbility?([:CLOUDNINE, :AIRLOCK]) }
    return @field.weather
  end

  def pbCanStartWeather?(newWeather, ignore_primal = false)
    return false if @field.weather == newWeather
    primal_weathers = [:HarshSun, :HeavyRain, :StrongWinds]
    if !ignore_primal && primal_weathers.include?(@field.weather)
      return newWeather == :None || primal_weathers.include?(newWeather)
    end
    return false if Settings::DEFAULT_WEATHER_AND_TERRAIN_CANNOT_BE_REPLACED &&
                    ![:None, newWeather].include?(@field.defaultWeather) &&
                    !primal_weathers.include?(newWeather)
    return true
  end

  # Used for causing weather by a move or by an ability.
  def pbStartWeather(user, newWeather, fixedDuration = false, showAnim = true, message = nil)
    return if !pbCanStartWeather?(newWeather)
    old_weather = @field.weather
    @field.weather = newWeather
    duration = (fixedDuration) ? 5 : -1
    if duration > 0 && user && user.itemActive?
      duration = Battle::ItemEffects.triggerWeatherExtender(user.item, @field.weather,
                                                            duration, user, self)
    end
    @field.weatherDuration = duration
    weather_data = GameData::BattleWeather.try_get(@field.weather)
    pbCommonAnimation(weather_data.animation) if showAnim && weather_data
    pbHideAbilitySplash(user) if user
    if message
      pbDisplay(message)
    else
      case @field.weather
      when :Sun         then pbDisplay(_INTL("¡El sol pega fuerte!"))
      when :Rain        then pbDisplay(_INTL("¡Ha empezado a llover!"))
      when :Sandstorm   then pbDisplay(_INTL("¡Se ha desatado una tormenta de arena!"))
      when :Hail        then pbDisplay(_INTL("¡Ha empezado a granizar!"))
      when :Snowstorm   then pbDisplay(_INTL("¡Ha empezado a nevar!"))
      when :HarshSun    then pbDisplay(_INTL("¡El sol que hace ahora es realmente abrasador!"))
      when :HeavyRain   then pbDisplay(_INTL("¡Ha empezado a diluviar!"))
      when :StrongWinds then pbDisplay(_INTL("¡Las misteriosas turbulencias protegen a los Pokémon de tipo Volador!"))
      when :ShadowSky   then pbDisplay(_INTL("¡El cielo se volvió oscuro!"))
      end
    end
    # Check for end of primordial weather, and weather-triggered form changes
    allBattlers(true).each { |b| b.pbCheckFormOnWeatherChange }
    allBattlers(true).each { |b| b.pbAbilityOnWeatherChange(old_weather) }
    allBattlers(true).each { |b| b.pbItemOnWeatherChange(old_weather) }
    pbEndPrimordialWeather
  end

  # This doesn't reinstate the default weather. It just handles what happens
  # when a weather ends.
  def pbEndWeather
    old_weather = @field.weather
    case @field.weather
    when :Sun, :HarshSun    then pbDisplay(_INTL("¡El sol vuelve a brillar como siempre!"))
    when :Rain, :HeavyRain  then pbDisplay(_INTL("¡Ha dejado de llover!"))
    when :Sandstorm         then pbDisplay(_INTL("La tormenta de arena ha amainado."))
    when :Hail              then pbDisplay(_INTL("¡Ha dejado de granizar!"))
    when :Snowstorm         then pbDisplay(_INTL("¡Ha dejado de nevar!"))
    # when :Hail
    #     case Settings::HAIL_WEATHER_TYPE
    #     when 0 then pbDisplay(_INTL("Ha dejado de granizar."))
    #     when 1 then pbDisplay(_INTL("Ha dejado de nevar."))
    #     when 2 then pbDisplay(_INTL("Ha dejado de granizar."))
        # end
    when :StrongWinds       then pbDisplay(_INTL("¡Las misteriosas turbulencias han amainado!"))
    when :ShadowSky         then pbDisplay(_INTL("El cielo sombrío se desvaneció."))
    end
    @field.weather = :None
    # Check for form changes/abilities/items caused by the weather changing
    allBattlers(true).each { |b| b.pbCheckFormOnWeatherChange }
    allBattlers(true).each { |b| b.pbAbilityOnWeatherChange(old_weather) }
    allBattlers(true).each { |b| b.pbItemOnWeatherChange(old_weather) }
  end

  def pbEndPrimordialWeather
    return if @field.weather == @field.defaultWeather
    old_weather = @field.weather
    # End Primordial Sea, Desolate Land, Delta Stream
    case @field.weather
    when :HarshSun
      if !pbCheckGlobalAbility(:DESOLATELAND)
        @field.weather = :None
        pbDisplay("¡El sol vuelve a brillar como siempre!")
      end
    when :HeavyRain
      if !pbCheckGlobalAbility(:PRIMORDIALSEA)
        @field.weather = :None
        pbDisplay("¡Ha dejado de diluviar!")
      end
    when :StrongWinds
      if !pbCheckGlobalAbility(:DELTASTREAM)
        @field.weather = :None
        pbDisplay("¡Las misteriosas turbulencias han amainado!")
      end
    end
    if @field.weather != old_weather
      # Check for form changes caused by the weather changing
      allBattlers(true).each { |b| b.pbCheckFormOnWeatherChange }
      allBattlers(true).each { |b| b.pbAbilityOnWeatherChange(old_weather) }
      allBattlers(true).each { |b| b.pbItemOnWeatherChange(old_weather) }
      # Start up the default weather
      pbStartWeather(nil, @field.defaultWeather) if @field.defaultWeather != :None
    end
  end

  def pbStartWeatherAbility(new_weather, battler, ignore_primal = false, message = nil)
    return if !pbCanStartWeather?(new_weather, ignore_primal)
    pbShowAbilitySplash(battler)
    if !Scene::USE_ABILITY_SPLASH
      pbDisplay(_INTL("¡{2} de {1} se activó!", battler.pbThis, battler.abilityName))
    end
    fixed_duration = false
    fixed_duration = true if Settings::FIXED_DURATION_WEATHER_FROM_ABILITY &&
                             ![:HarshSun, :HeavyRain, :StrongWinds].include?(new_weather)
    pbStartWeather(battler, new_weather, fixed_duration, true, message)
    # NOTE: The ability splash is hidden again in def pbStartWeather.
  end

  #=============================================================================
  # Terrain
  #=============================================================================
  def defaultTerrain=(value)
    @field.defaultTerrain  = value
    @field.terrain         = value
    @field.terrainDuration = -1
  end

  def pbCanStartTerrain?(newTerrain)
    return false if @field.terrain == newTerrain
    return false if Settings::DEFAULT_WEATHER_AND_TERRAIN_CANNOT_BE_REPLACED &&
                    ![:None, newTerrain].include?(@field.defaultTerrain)
    return true
  end

  def pbStartTerrain(user, newTerrain, fixedDuration = true, message = nil)
    return if !pbCanStartTerrain?(newTerrain)
    old_terrain = @field.terrain
    @field.terrain = newTerrain
    duration = (fixedDuration) ? 5 : -1
    if duration > 0 && user && user.itemActive?
      duration = Battle::ItemEffects.triggerTerrainExtender(user.item, newTerrain,
                                                            duration, user, self)
    end
    @field.terrainDuration = duration
    terrain_data = GameData::BattleTerrain.try_get(@field.terrain)
    pbCommonAnimation(terrain_data.animation) if terrain_data
    
    pbHideAbilitySplash(user) if user
    if message
      pbDisplay(message)
    else
      case @field.terrain
      when :Electric then pbDisplay(_INTL("¡Se ha formado un campo de corriente eléctrica en el terreno de combate!"))
      when :Grassy   then pbDisplay(_INTL("¡El terreno de combate se ha cubierto de hierba!"))
      when :Misty    then pbDisplay(_INTL("¡La niebla ha envuelto el terreno de combate!"))
      when :Psychic  then pbDisplay(_INTL("¡El terreno de combate se ha vuelto muy extraño!"))
      end
    end
    on_terrain_start
    # Check for abilities/items that trigger upon the terrain changing
    allBattlers(true).each { |b| b.pbCheckFormOnTerrainChange }
    allBattlers(true).each { |b| b.pbAbilityOnTerrainChange(old_terrain) }
    allBattlers(true).each { |b| b.pbItemOnTerrainChange(old_terrain) }
  end

  # This doesn't reinstate the default terrain. It just handles what happens
  # when a terrain ends.
  def pbEndTerrain
    old_terrain = @field.terrain
    case @field.terrain
    when :Electric then pbDisplay(_INTL("El campo de corriente eléctrica ha desaparecido."))
    when :Grassy   then pbDisplay(_INTL("La hierba ha desaparecido."))
    when :Misty    then pbDisplay(_INTL("La niebla se ha disipado."))
    when :Psychic  then pbDisplay(_INTL("Ha desaparecido la extraña sensación que se percibía en el terreno de combate."))
    end
    @field.terrain = :None
    # Check for form changes/abilities/items caused by the terrain changing
    allBattlers(true).each { |b| b.pbCheckFormOnTerrainChange }
    allBattlers(true).each { |b| b.pbAbilityOnTerrainChange(old_terrain) }
    allBattlers(true).each { |b| b.pbItemOnTerrainChange(old_terrain) }
  end

  def pbStartTerrainAbility(new_terrain, battler, message = nil)
    return if !pbCanStartTerrain?(new_terrain)
    pbShowAbilitySplash(battler)
    if !Scene::USE_ABILITY_SPLASH
      pbDisplay(_INTL("¡{2} de {1} se activó!", battler.pbThis, battler.abilityName))
    end
    fixed_duration = true
    pbStartTerrain(battler, new_terrain, fixed_duration, message)
    # NOTE: The ability splash is hidden again in def pbStartTerrain.
  end

  #-----------------------------------------------------------------------------
  # Messages and animations.
  #-----------------------------------------------------------------------------

  def pbDisplay(msg, &block)
    @scene.pbDisplayMessage(msg, &block)
  end

  def pbDisplayBrief(msg)
    @scene.pbDisplayMessage(msg, true)
  end

  def pbDisplayPaused(msg, &block)
    @scene.pbDisplayPausedMessage(msg, &block)
  end

  def pbDisplayConfirm(msg)
    return @scene.pbDisplayConfirmMessage(msg)
  end

  # defaultValue of -1 means "can't cancel". If it's 0 or greater, returns that
  # value when pressing the "Back" button.
  def pbShowCommands(msg, commands, defaultValue = -1)
    return @scene.pbShowCommands(msg, commands, defaultValue)
  end

  def pbAnimation(move, user, targets, hitNum = 0)
    @scene.pbAnimation(move, user, targets, hitNum) if !@rules[:no_battle_animations]
  end

  def pbCommonAnimation(name, user = nil, targets = nil)
    @scene.pbCommonAnimation(name, user, targets) if !@rules[:no_battle_animations]
  end

  def pbShowAbilitySplash(battler, delay = false, logTrigger = true)
    PBDebug.log("[Ability triggered] #{battler.pbThis}'s #{battler.abilityName}") if logTrigger
    return if !Scene::USE_ABILITY_SPLASH
    @scene.pbShowAbilitySplash(battler)
    if delay
      timer_start = System.uptime
      until System.uptime - timer_start >= 1   # 1 second
        @scene.pbUpdate
      end
    end
  end

  def pbHideAbilitySplash(battler)
    return if !Scene::USE_ABILITY_SPLASH
    @scene.pbHideAbilitySplash(battler)
  end

  def pbReplaceAbilitySplash(battler)
    return if !Scene::USE_ABILITY_SPLASH
    @scene.pbReplaceAbilitySplash(battler)
  end
  
  #-----------------------------------------------------------------------------
  # Type calculation
  #-----------------------------------------------------------------------------
  # Utilizado cuando Arceus tiene una Tabla y usa el movimiento Sentencia.
  # Calcula el tipo ideal contra el enemigo
  # Randomiza el tipo si hay multiples con el mismo poder
  # No cambiará el tipo si check_type ya es uno de los mejores tipos a usar.
  # Si el usuario no tiene tipo, por ejemplo un tipo fuego puro que haya usado 
  # el movimiento Llama Final
  # y el objetivo no tiene habilidades, objetos o efectos en juego que
  # pudieran afectar el tipo elegido, entonces el tipo Normal será el elegido
  #-----------------------------------------------------------------------------
  # Los siguientes factores son considerados al calcular el tipo:
  #   -Efectividad de tipos.
  #   -Si el objetivo tiene un tercer tipo
  #   -Inmunidades, si las hay.
  #   -Inmunidades por habilidad
  #   -Habilidades que modifiquen el daño. (Ignífugo, Sebo, etc.)
  #   -Inmunidades por objetos. (Globo Helio, etc.)
  #   -Modificacion de daño por efectos del usuario. (Carga)
  #   -Inmunidades del objetivo por estados. (Levitón, Antiaéreo, etc.)
  #   -Modificacion de daño por cambios en el campo. (Chapoteo lodo, Hidrochorro)
  #   -Modificaiones de daño por Climas y Terrenos.
  #-----------------------------------------------------------------------------
  #   *Note: The opponent's type-weakening berries are not considered.
  #-----------------------------------------------------------------------------
  def pbGetBestTypeJudgment(user, target, move = nil, check_type = nil)
    return :NORMAL if !target
    all_types = []
    effective_types = Hash.new { |key, value| key[value] = [] }
    target_types = target.pbTypes(true)
    move = Move.from_pokemon_move(self, Pokemon::Move.new(:JUDGMENT)) if !move
    GameData::Type.each do |type_data|
      next if type_data.pseudo_type
      type = type_data.id
      all_types.push(type)
      next if pbTargetHasTypeImmunity?(user, target, move, type, target_types)
      multipliers = {
        :power_multiplier  => 1.0,
        :attack_multiplier       => 1.0,
        :defense_multiplier      => 1.0,
        :final_damage_multiplier => 1.0
      }
      pbCalcTypeMultsJudgment(user, target, move, type, target_types, multipliers)
      baseMult = [multipliers[:power_multiplier].round,        1].max
      atkMult  = [multipliers[:attack_multiplier].round,       1].max
      defMult  = [multipliers[:defense_multiplier].round,      1].max
      dmgMult  = [multipliers[:final_damage_multiplier].round, 1].max
      strength = ((baseMult * atkMult / defMult) * dmgMult).floor
      effective_types[strength] << type
    end
    best_types = (effective_types.empty?) ? all_types : effective_types.sort.last[1]
    bestType = pbCalcOptimalType(user, target, move, best_types, target_types, check_type)
    return bestType
  end
  
  #-----------------------------------------------------------------------------
  # Checks if the target is immune to a given type by its typing, ability, or effect.
  #-----------------------------------------------------------------------------
  def pbTargetHasTypeImmunity?(user, target, move, type, target_types)
    return true if type == :FIRE  && target.effectiveWeather == :HeavyRain
    return true if type == :WATER && target.effectiveWeather == :HarshSun
    return true if move.pbCalcTypeMod(type, user, target) == Effectiveness::INEFFECTIVE
    if target.abilityActive? && !@moldBreaker
      return true if Battle::AbilityEffects.triggerMoveImmunity(
        target.ability, user, target, move, type, self, false)
    end
    return false
  end
  
  #-----------------------------------------------------------------------------
  # Calculates the effectiveness of a given type used against the target.
  #-----------------------------------------------------------------------------
  def pbCalcTypeMultsJudgment(user, target, move, type, target_types, multipliers)
    if (pbCheckGlobalAbility(:DARKAURA)  && type == :DARK) ||
       (pbCheckGlobalAbility(:FAIRYAURA) && type == :FAIRY)
      if pbCheckGlobalAbility(:AURABREAK)
        multipliers[:power_multiplier] *= 2 / 3.0
      else
        multipliers[:power_multiplier] *= 4 / 3.0
      end
    end
    if target.abilityActive? && !@moldBreaker
      Battle::AbilityEffects.triggerDamageCalcFromTarget(
        target.ability, user, target, move, multipliers, move.baseDamage, type
      )
      Battle::AbilityEffects.triggerDamageCalcFromTargetNonIgnorable(
        target.ability, user, target, move, multipliers, move.baseDamage, type
      )
    end
    type_calc = move.pbCalcTypeMod(type, user, target)
    if type_calc > Effectiveness::INEFFECTIVE
      multipliers[:final_damage_multiplier] *= type_calc
    end
    case type
    when :FIRE
      multipliers[:power_multiplier] /= 3 if @field.effects[PBEffects::WaterSportField] > 0
    when :ELECTRIC
      multipliers[:power_multiplier] *= 2 if user.effects[PBEffects::Charge] > 0
      multipliers[:power_multiplier] /= 3 if @field.effects[PBEffects::MudSportField] > 0
    end
    if user.affectedByTerrain?
      case @field.terrain
      when :Electric then multipliers[:power_multiplier] *= 1.3 if type == :ELECTRIC
      when :Grassy   then multipliers[:power_multiplier] *= 1.3 if type == :GRASS
      when :Psychic  then multipliers[:power_multiplier] *= 1.3 if type == :PSYCHIC
      when :Misty    then multipliers[:power_multiplier] /= 2   if type == :DRAGON
      end
    end
    case user.effectiveWeather
    when :Sun, :HarshSun
      multipliers[:final_damage_multiplier] *= 1.5 if type == :FIRE
      multipliers[:final_damage_multiplier] /= 2   if type == :WATER
    when :Rain, :HeavyRain
      multipliers[:final_damage_multiplier] *= 1.5 if type == :WATER
      multipliers[:final_damage_multiplier] /= 2   if type == :FIRE
    end
  end
  
  #-----------------------------------------------------------------------------
  # Determina la selección óptima del array de tipos más efectivos.
  #-----------------------------------------------------------------------------
  # -Devuelve el tipo más efectivo si solo 1 tipo es el más efectivo
  # -Si más de 1 tipo es el más efectivo, devuelve el mejor tipo en base al tipo primario del enemigo
  # -Si aún hay mas de 1 tipo efectivo, devuelve el mejor tipo en base al tipo secundario del enemigo
  # -Si aún hay mas de 1 tipo efectivo, devolvera el tipo en base al tipo del ultimo movimiento utilizado
  # -De lo contrario devuelve un tipo efectivo aleatorio
  #-----------------------------------------------------------------------------
  def pbCalcOptimalType(user, target, move, effective_types, target_types, check_type)
    return effective_types[0] if effective_types.length == 1
    target_types.each do |target_type|
      effectiveness = Hash.new { |key, value| key[value] = [] }
      effective_types.each do |type|
        strength = move.pbCalcTypeModSingle(target_type, type, user, target)
        effectiveness[strength] << type
      end
      effective_types = effectiveness.sort.first[1].clone
      break if effective_types.length == 1
    end
    return check_type if effective_types.include?(check_type)
    return effective_types.sample
  end
end


==============================================================================
# Script: Battle_StartAndEnd
==============================================================================
#===============================================================================
#
#===============================================================================
class Battle
  class BattleAbortedException < Exception; end

  #-----------------------------------------------------------------------------

  def pbAbort
    raise BattleAbortedException.new("Battle aborted")
  end

  # Makes sure all Pokémon exist that need to. Alter the type of battle if
  # necessary. Will never try to create battler positions, only delete them
  # (except for wild Pokémon whose number of positions are fixed). Reduces the
  # size of each side by 1 and tries again. If the side sizes are uneven, only
  # the larger side's size will be reduced by 1 each time, until both sides are
  # an equal size (then both sides will be reduced equally).
  def pbEnsureParticipants
    # Prevent battles larger than 2v2 if both sides have multiple trainers
    # NOTE: This is necessary to ensure that battlers can never become unable to
    #       hit each other due to being too far away. In such situations,
    #       battlers will move to the centre position at the end of a round, but
    #       because they cannot move into a position owned by a different
    #       trainer, it's possible that battlers will be unable to move close
    #       enough to hit each other if there are multiple trainers on both
    #       sides.
    if trainerBattle? && (@sideSizes[0] > 2 || @sideSizes[1] > 2) &&
       @player.length > 1 && @opponent.length > 1
      raise _INTL("No se pueden tener batallas de más de 2 contra 2 en las que ambos bandos tengan varios entrenadores.")
    end
    # Find out how many Pokémon each trainer has
    side1counts = pbAbleTeamCounts(0)
    side2counts = pbAbleTeamCounts(1)
    # Change the size of the battle depending on how many wild Pokémon there are
    if wildBattle? && side2counts[0] != @sideSizes[1]
      if @sideSizes[0] == @sideSizes[1]
        # Even number of battlers per side, change both equally
        @sideSizes = [side2counts[0], side2counts[0]]
      else
        # Uneven number of battlers per side, just change wild side's size
        @sideSizes[1] = side2counts[0]
      end
    end
    # Check if battle is possible, including changing the number of battlers per
    # side if necessary
    loop do
      needsChanging = false
      2.times do |side|   # Each side in turn
        next if side == 1 && wildBattle?   # Wild side's size already checked above
        sideCounts = (side == 0) ? side1counts : side2counts
        requireds = []
        # Find out how many Pokémon each trainer on side needs to have
        @sideSizes[side].times do |i|
          idxTrainer = pbGetOwnerIndexFromBattlerIndex((i * 2) + side)
          requireds[idxTrainer] = 0 if requireds[idxTrainer].nil?
          requireds[idxTrainer] += 1
        end
        # Compare the have values with the need values
        if requireds.length > sideCounts.length
          raise _INTL("Error: def pbGetOwnerIndexFromBattlerIndex proporciona un índice de propietario no válido ({1} para el tipo de batalla {2} contra {3}, entrenadores {4} contra {5})",
                      requireds.length - 1, @sideSizes[0], @sideSizes[1], side1counts.length, side2counts.length)
        end
        sideCounts.each_with_index do |_count, i|
          if !requireds[i] || requireds[i] == 0
            case side
            when 0
              raise _INTL("El entrenador del lado del jugador {1} no tiene una posición asignada para que sus Pokémon combatan (intentando una batalla {2} contra {3})",
                          i + 1, @sideSizes[0], @sideSizes[1])
            when 1
              raise _INTL("El entrenador rival {1} no tiene una posición asignada para que sus Pokémon combatan (intentando una batalla {2} contra {3})",
                          i + 1, @sideSizes[0], @sideSizes[1])
            end
          end
          next if requireds[i] <= sideCounts[i]   # Trainer has enough Pokémon to fill their positions
          if requireds[i] == 1
            raise _INTL("El entrenador del lado del jugador {1} no tiene Pokémon válidos", i + 1) if side == 0
            raise _INTL("El entrenador rival {1} no tiene Pokémon válidos", i + 1) if side == 1
          end
          # Not enough Pokémon, try lowering the number of battler positions
          needsChanging = true
          break
        end
        break if needsChanging
      end
      break if !needsChanging
      # Reduce one or both side's sizes by 1 and try again
      if wildBattle?
        PBDebug.log("#{@sideSizes[0]}v#{@sideSizes[1]} battle isn't possible " +
                    "(#{side1counts} player-side teams versus #{side2counts[0]} wild Pokémon)")
        newSize = @sideSizes[0] - 1
      else
        PBDebug.log("#{@sideSizes[0]}v#{@sideSizes[1]} battle isn't possible " +
                    "(#{side1counts} player-side teams versus #{side2counts} opposing teams)")
        newSize = @sideSizes.max - 1
      end
      if newSize == 0
        raise _INTL("No se pudo reducir más el tamaño de ninguno de los bandos, la batalla no es posible")
      end
      2.times do |side|
        next if side == 1 && wildBattle?   # Wild Pokémon's side size is fixed
        next if @sideSizes[side] == 1 || newSize > @sideSizes[side]
        @sideSizes[side] = newSize
      end
      PBDebug.log("Trying #{@sideSizes[0]}v#{@sideSizes[1]} battle instead")
    end
  end

  #-----------------------------------------------------------------------------
  # Set up all battlers
  #-----------------------------------------------------------------------------

  def pbCreateBattler(idxBattler, pkmn, idxParty)
    if !@battlers[idxBattler].nil?
      raise _INTL("El índice de batalla {1} ya existe", idxBattler)
    end
    @battlers[idxBattler] = Battler.new(self, idxBattler)
    @positions[idxBattler] = ActivePosition.new
    pbClearChoice(idxBattler)
    @successStates[idxBattler] = SuccessState.new
    @battlers[idxBattler].pbInitialize(pkmn, idxParty)
  end

  def pbSetUpSides
    ret = [[], []]
    2.times do |side|
      # Set up wild Pokémon
      if side == 1 && wildBattle?
        pbParty(1).each_with_index do |pkmn, idxPkmn|
          pbCreateBattler((2 * idxPkmn) + side, pkmn, idxPkmn)
          # Changes the Pokémon's form upon entering battle (if it should)
          @peer.pbOnEnteringBattle(self, @battlers[(2 * idxPkmn) + side], pkmn, true)
          pbSetSeen(@battlers[(2 * idxPkmn) + side])
          @usedInBattle[side][idxPkmn] = true
        end
        next
      end
      # Set up player's Pokémon and trainers' Pokémon
      trainer = (side == 0) ? @player : @opponent
      requireds = []
      # Find out how many Pokémon each trainer on side needs to have
      @sideSizes[side].times do |i|
        idxTrainer = pbGetOwnerIndexFromBattlerIndex((i * 2) + side)
        requireds[idxTrainer] = 0 if requireds[idxTrainer].nil?
        requireds[idxTrainer] += 1
      end
      # For each trainer in turn, find the needed number of Pokémon for them to
      # send out, and initialize them
      battlerNumber = 0
      partyOrder = pbPartyOrder(side)
      starts = pbPartyStarts(side)
      trainer.each_with_index do |_t, idxTrainer|
        ret[side][idxTrainer] = []
        eachInTeam(side, idxTrainer) do |pkmn, idxPkmn|
          next if !pkmn.able?
          idxBattler = (2 * battlerNumber) + side
          pbCreateBattler(idxBattler, pkmn, idxPkmn)
          ret[side][idxTrainer].push(idxBattler)
          if idxPkmn != starts[idxTrainer] + battlerNumber
            idxOther = starts[idxTrainer] + battlerNumber
            partyOrder[idxPkmn], partyOrder[idxOther] = partyOrder[idxOther], partyOrder[idxPkmn]
          end
          battlerNumber += 1
          break if ret[side][idxTrainer].length >= requireds[idxTrainer]
        end
      end
    end
    return ret
  end

  #=============================================================================
  # Send out all battlers at the start of battle
  #=============================================================================
  def pbStartBattleSendOut(sendOuts)
    # "Want to battle" messages
    if wildBattle?
      foeParty = pbParty(1)
      case foeParty.length
      when 1
        pbDisplayPaused(_INTL("¡Un {1} salvaje te corta el paso!", foeParty[0].name))
      when 2
        pbDisplayPaused(_INTL("¡Un {1} y un {2} salvajes te cortan el paso!", foeParty[0].name,
                              foeParty[1].name))
      when 3
        pbDisplayPaused(_INTL("¡Un {1} , un {2} y un {3} salvajes te cortan el paso!", foeParty[0].name,
                              foeParty[1].name, foeParty[2].name))
      end
    else   # Trainer battle
      case @opponent.length
      when 1
        pbDisplayPaused(_INTL("¡{1} te desafía!", @opponent[0].full_name))
      when 2
        pbDisplayPaused(_INTL("¡{1} y {2} te desafían!", @opponent[0].full_name,
                              @opponent[1].full_name))
      when 3
        pbDisplayPaused(_INTL("¡{1}, {2} y {3} te desafían!",
                              @opponent[0].full_name, @opponent[1].full_name, @opponent[2].full_name))
      end
    end
    # Send out Pokémon (opposing trainers first)
    [1, 0].each do |side|
      next if side == 1 && wildBattle?
      msg = ""
      toSendOut = []
      trainers = (side == 0) ? @player : @opponent
      # Opposing trainers and partner trainers's messages about sending out Pokémon
      trainers.each_with_index do |t, i|
        next if side == 0 && i == 0   # The player's message is shown last
        msg += "\n" if msg.length > 0
        sent = sendOuts[side][i]
        case sent.length
        when 1
          msg += _INTL("¡{1} saca a {2}!", t.full_name, @battlers[sent[0]].name)
        when 2
          msg += _INTL("¡{1} saca a {2} y {3}!", t.full_name,
                       @battlers[sent[0]].name, @battlers[sent[1]].name)
        when 3
          msg += _INTL("¡{1} saca a {2}, {3} y {4}!", t.full_name,
                       @battlers[sent[0]].name, @battlers[sent[1]].name, @battlers[sent[2]].name)
        end
        toSendOut.concat(sent)
      end
      # The player's message about sending out Pokémon
      if side == 0
        msg += "\n" if msg.length > 0
        sent = sendOuts[side][0]
        case sent.length
        when 1
          msg += _INTL("¡Adelante, {1}!", @battlers[sent[0]].name)
        when 2
          msg += _INTL("¡Adelante, {1} y {2}!", @battlers[sent[0]].name, @battlers[sent[1]].name)
        when 3
          msg += _INTL("¡Adelante, {1}, {2} y {3}!", @battlers[sent[0]].name,
                       @battlers[sent[1]].name, @battlers[sent[2]].name)
        end
        toSendOut.concat(sent)
      end
      pbDisplayBrief(msg) if msg.length > 0
      # The actual sending out of Pokémon
      animSendOuts = []
      toSendOut.each do |idxBattler|
        animSendOuts.push([idxBattler, @battlers[idxBattler].pokemon])
      end
      pbSendOut(animSendOuts, true)
    end
  end

  #=============================================================================
  # Start a battle
  #=============================================================================
  def pbStartBattle
    PBDebug.log("")
    PBDebug.log("================================================================")
    PBDebug.log("")
    logMsg = "[Started battle] "
    if @sideSizes[0] == 1 && @sideSizes[1] == 1
      logMsg += "Single "
    elsif @sideSizes[0] == 2 && @sideSizes[1] == 2
      logMsg += "Double "
    elsif @sideSizes[0] == 3 && @sideSizes[1] == 3
      logMsg += "Triple "
    else
      logMsg += "#{@sideSizes[0]}v#{@sideSizes[1]} "
    end
    logMsg += "wild " if wildBattle?
    logMsg += "trainer " if trainerBattle?
    logMsg += "battle (#{@player.length} trainer(s) vs. "
    logMsg += "#{pbParty(1).length} wild Pokémon)" if wildBattle?
    logMsg += "#{@opponent.length} trainer(s))" if trainerBattle?
    PBDebug.log(logMsg)
    pbEnsureParticipants
    pbParty(0).each { |pkmn| @peer.pbOnStartingBattle(self, pkmn, wildBattle?) if pkmn }
    pbParty(1).each { |pkmn| @peer.pbOnStartingBattle(self, pkmn, wildBattle?) if pkmn }
    begin
      pbStartBattleCore
    rescue BattleAbortedException
      @decision = Outcome::UNDECIDED
      @scene.pbEndBattle(@decision)
    end
    return @decision
  end

  def pbStartBattleCore(battle_loop = true)
    # Set up the battlers on each side
    sendOuts = pbSetUpSides
    @battleAI.create_ai_objects
    # Create all the sprites and play the battle intro animation
    @scene.pbStartBattle(self)
    # Show trainers on both sides sending out Pokémon
    pbStartBattleSendOut(sendOuts)
    # Weather announcement
    weather_data = GameData::BattleWeather.try_get(@field.weather)
    pbCommonAnimation(weather_data.animation) if weather_data
    case @field.weather
    when :Sun         then pbDisplay(_INTL("¡El sol pega fuerte!"))
    when :Rain        then pbDisplay(_INTL("¡Ha empezado a llover!"))
    when :Sandstorm   then pbDisplay(_INTL("¡Se ha desatado una tormenta de arena!"))
    when :Hail        then pbDisplay(_INTL("¡Ha empezado a granizar!"))
    when :Snowstorm   then pbDisplay(_INTL("¡Ha empezado a nevar!"))
    when :HarshSun    then pbDisplay(_INTL("¡El sol que hace ahora es realmente abrasador!"))
    when :HeavyRain   then pbDisplay(_INTL("¡Ha empezado a diluviar!"))
    when :StrongWinds then pbDisplay(_INTL("¡Las misteriosas turbulencias protegen a los Pokémon de tipo Volador!"))
    when :ShadowSky   then pbDisplay(_INTL("¡El cielo se volvió oscuro!"))
    end
    # Terrain announcement
    terrain_data = GameData::BattleTerrain.try_get(@field.terrain)
    pbCommonAnimation(terrain_data.animation) if terrain_data
    
    case @field.terrain
    when :Electric
      pbDisplay(_INTL("¡Se ha formado un campo de corriente eléctrica en el terreno de combate!"))
    when :Grassy
      pbDisplay(_INTL("¡El terreno de combate se ha cubierto de hierba!"))
    when :Misty
      pbDisplay(_INTL("¡La niebla ha envuelto el terreno de combate!"))
    when :Psychic
      pbDisplay(_INTL("¡El terreno de combate se ha vuelto muy extraño!"))
    end
    on_terrain_start
    # Abilities upon entering battle
    pbOnAllBattlersEnteringBattle
    # Main battle loop
    pbBattleLoop if battle_loop
  end 

  #=============================================================================
  # Main battle loop
  #=============================================================================
  def pbBattleLoop
    @turnCount = 0
    loop do   # Now begin the battle loop
      PBDebug.log("")
      PBDebug.log_header("===== Round #{@turnCount + 1} =====")
      if @debug && @turnCount >= 100
        @decision = pbDecisionOnTime
        PBDebug.log("")
        PBDebug.log("***Undecided after 100 rounds, aborting***")
        pbAbort
        break
      end
      PBDebug.log("")
      # Command phase
      PBDebug.logonerr { pbCommandPhase }
      break if decided?
      # Attack phase
      PBDebug.logonerr { pbAttackPhase }
      break if decided?
      # End of round phase
      PBDebug.logonerr { pbEndOfRoundPhase }
      break if decided?
      @turnCount += 1
    end
    pbEndOfBattle
  end

  #=============================================================================
  # End of battle
  #=============================================================================
  def pbGainMoney
    return if !@internalBattle || @rules[:no_money_gain]
    # Money rewarded from opposing trainers
    if trainerBattle?
      tMoney = 0
      @opponent.each_with_index do |t, i|
        tMoney += pbMaxLevelInTeam(1, i) * t.base_money
      end
      tMoney *= 2 if @field.effects[PBEffects::AmuletCoin]
      tMoney *= 2 if @field.effects[PBEffects::HappyHour]
      oldMoney = pbPlayer.money
      pbPlayer.money += tMoney
      moneyGained = pbPlayer.money - oldMoney
      if moneyGained > 0
        $stats.battle_money_gained += moneyGained
        pbDisplayPaused(_INTL("¡Has ganado {1}$ por vencer!", moneyGained.to_s_formatted))
      end
    end
    # Pick up money scattered by Pay Day
    if @field.effects[PBEffects::PayDay] > 0
      @field.effects[PBEffects::PayDay] *= 2 if @field.effects[PBEffects::AmuletCoin]
      @field.effects[PBEffects::PayDay] *= 2 if @field.effects[PBEffects::HappyHour]
      oldMoney = pbPlayer.money
      pbPlayer.money += @field.effects[PBEffects::PayDay]
      moneyGained = pbPlayer.money - oldMoney
      if moneyGained > 0
        $stats.battle_money_gained += moneyGained
        pbDisplayPaused(_INTL("¡Has recogido {1}$!", moneyGained.to_s_formatted))
      end
    end
  end

  def pbLoseMoney
    return if !@internalBattle || @rules[:no_money_gain]
    return if $game_switches[Settings::NO_MONEY_LOSS]
    maxLevel = pbMaxLevelInTeam(0, 0)   # Player's Pokémon only, not partner's
    multiplier = [8, 16, 24, 36, 48, 64, 80, 100, 120]
    idxMultiplier = [pbPlayer.badge_count, multiplier.length - 1].min
    tMoney = maxLevel * multiplier[idxMultiplier]
    tMoney = pbPlayer.money if tMoney > pbPlayer.money
    oldMoney = pbPlayer.money
    pbPlayer.money -= tMoney
    moneyLost = oldMoney - pbPlayer.money
    if moneyLost > 0
      $stats.battle_money_lost += moneyLost
      if trainerBattle?
        pbDisplayPaused(_INTL("Has pagado {1}$ por haber perdido el combate.", moneyLost.to_s_formatted))
      else
        pbDisplayPaused(_INTL("Te has desconcentrado y se te han caído {1}$...", moneyLost.to_s_formatted))
      end
    end
  end

  def pbEndOfBattle
    oldDecision = @decision
    @decision = Outcome::CATCH if @decision == Outcome::WIN && wildBattle? && @caughtPokemon.length > 0
    case oldDecision
    when Outcome::WIN
      PBDebug.log("")
      PBDebug.log_header("===== Player won =====")
      PBDebug.log("")
      if trainerBattle?
        @scene.pbTrainerBattleSuccess
        case @opponent.length
        when 1
          pbDisplayPaused(_INTL("¡{1} ha perdido!", @opponent[0].full_name))
        when 2
          pbDisplayPaused(_INTL("¡{1} y {2} han perdido!", @opponent[0].full_name,
                                @opponent[1].full_name))
        when 3
          pbDisplayPaused(_INTL("¡{1}, {2} y {3} han perdido!", @opponent[0].full_name,
                                @opponent[1].full_name, @opponent[2].full_name))
        end
        @opponent.each_with_index do |trainer, i|
          @scene.pbShowOpponent(i)
          msg = trainer.lose_text
          msg = "..." if !msg || msg.empty?
          pbDisplayPaused(msg.gsub(/\\[Pp][Nn]/, pbPlayer.name).gsub(/\\[Nn]/, "\n"))
        end
        PBDebug.log("")
      end
      # Gain money from winning a trainer battle, and from Pay Day
      pbGainMoney if @decision != Outcome::CATCH
      # Hide remaining trainer
      @scene.pbShowOpponent(@opponent.length) if trainerBattle? && @caughtPokemon.length > 0
    when Outcome::LOSE, Outcome::DRAW
      PBDebug.log("")
      PBDebug.log_header("===== Player lost =====") if @decision == Outcome::LOSE
      PBDebug.log_header("===== Player drew with opponent =====") if @decision == Outcome::DRAW
      PBDebug.log("")
      if @internalBattle
        if pbPlayerBattlerCount == 0
          pbDisplayPaused(_INTL("¡No te quedan Pokémon!"))
          if trainerBattle?
            case @opponent.length
            when 1
              pbDisplayPaused(_INTL("¡Has perdido contra {1}!", @opponent[0].full_name))
            when 2
              pbDisplayPaused(_INTL("¡Has perdido contra {1} y {2}!",
                                    @opponent[0].full_name, @opponent[1].full_name))
            when 3
              pbDisplayPaused(_INTL("¡Has perdido contra {1}, {2} y {3}!",
                                    @opponent[0].full_name, @opponent[1].full_name, @opponent[2].full_name))
            end
          end
        end
        # Lose money from losing a battle
        pbLoseMoney
        pbDisplayPaused(_INTL("¡Estás fuera de combate!")) if !@rules[:continue_if_lose] && pbPlayerBattlerCount == 0
      elsif @decision == Outcome::LOSE   # Lost in a Battle Frontier battle
        if @opponent
          @opponent.each_with_index do |trainer, i|
            @scene.pbShowOpponent(i)
            msg = trainer.win_text
            msg = "..." if !msg || msg.empty?
            pbDisplayPaused(msg.gsub(/\\[Pp][Nn]/, pbPlayer.name).gsub(/\\[Nn]/, "\n"))
          end
          PBDebug.log("")
        end
      end
    when Outcome::CATCH
      PBDebug.log("")
      PBDebug.log_header("===== Pokémon caught =====")
      PBDebug.log("")
      @scene.pbWildBattleSuccess if !Settings::GAIN_EXP_FOR_CAPTURE
    end
    # Swap held items back to their original holders (in trainer battles only)
    if trainerBattle?
      2.times do |side|
        pbParty(side).length.times do |i|
          pkmn = pbParty(side)[i]
          next if !pkmn
          next if @initialItems[side][i][1] == side && @initialItems[side][i][2] == i
          # Find other Pokémon holding the item originally held by pkmn
          other_side = side
          other_i = i
          @initialItems.each_with_index do |side_items, this_side|
            side_items.each_with_index do |pkmn_item, this_i|
              next if pkmn_item[1] != side || pkmn_item[2] != i
              other_side = this_side
              other_i = this_i
              break
            end
            break if other_side != side || other_i != i
          end
          # Swap items
          pkmn.item, pbParty(other_side)[other_i].item = pbParty(other_side)[other_i].item, pkmn.item
          @initialItems[side][i], @initialItems[other_side][other_i] = @initialItems[other_side][other_i], @initialItems[side][i]
        end
      end
    end
    # Restore knocked-off items and some consumed items
    @initialItems.each_with_index do |side_items, side|
      side_items.each_with_index do |pkmn_item, i|
        next if pkmn_item[0].nil?   # No initial item to restore
        next if !pbParty(side)[i] || pbParty(side)[i].hasItem?   # Can't restore item if already holding one
        if pkmn_item[3] ||   # Knocked off
           (Settings::MECHANICS_GENERATION >= 9 &&   # Only restores consumed items in Gen 9+
            !GameData::Item.get(pkmn_item[0]).is_berry?)   # Can't restore consumed berries
          # Restore knocked off/consumed item
          pbParty(side)[i].item = pkmn_item[0]
        end
      end
    end
    # Register captured Pokémon in the Pokédex, and store them
    pbRecordAndStoreCaughtPokemon
    # Collect Pay Day money in a wild battle that ended in a capture
    pbGainMoney if @decision == Outcome::CATCH
    # Pass on Pokérus within the party
    if @internalBattle
      infected = []
      $player.party.each_with_index do |pkmn, i|
        infected.push(i) if pkmn.pokerusStage == 1
      end
      infected.each do |idxParty|
        strain = $player.party[idxParty].pokerusStrain
        if idxParty > 0 && $player.party[idxParty - 1].pokerusStage == 0 && rand(3) == 0   # 33%
          $player.party[idxParty - 1].givePokerus(strain)
        end
        if idxParty < $player.party.length - 1 && $player.party[idxParty + 1].pokerusStage == 0 && rand(3) == 0   # 33%
          $player.party[idxParty + 1].givePokerus(strain)
        end
      end
    end
    # Clean up battle stuff
    @scene.pbEndBattle(@decision)
    @battlers.each do |b|
      next if !b
      pbCancelChoice(b.index)   # Restore unused items to Bag
      Battle::AbilityEffects.triggerOnSwitchOut(b.ability, b, true) if b.abilityActive?
      b.pokemon.makeUnmega if b.mega? 
    end
    # Reset Pokémon forms upon leaving battle
    2.times do |side|   # We do both sides in case the foe side includes a caught wild Pokémon
      pbParty(side).each_with_index do |pkmn, i|
        next if !pkmn
        @peer.pbOnLeavingBattle(self, pkmn, @usedInBattle[side][i], true)
      end
    end
    
    if Settings::UPDATE_PARTY_LEAD_BATTLE_END && decided? && @battlers[0] && !@battlers[0].fainted?
      new_lead_index = @battlers[0].pokemonIndex
      if new_lead_index && new_lead_index > 0 && new_lead_index < $player.party.length
        # Intercambiamos el líder actual (0) con el Pokémon que terminó la batalla
        $player.party[0], $player.party[new_lead_index] = $player.party[new_lead_index], $player.party[0]
      end
    end
    

    return @decision
  end

  #=============================================================================
  # Judging
  #=============================================================================
  def pbJudgeCheckpoint(user, move = nil); end

  def pbDecisionOnTime
    counts   = [0, 0]
    hpTotals = [0, 0]
    2.times do |side|
      pbParty(side).each do |pkmn|
        next if !pkmn || !pkmn.able?
        counts[side]   += 1
        hpTotals[side] += pkmn.hp
      end
    end
    return Outcome::WIN  if counts[0] > counts[1]        # Win (player has more able Pokémon)
    return Outcome::LOSE if counts[0] < counts[1]       # Loss (foe has more able Pokémon)
    return Outcome::WIN  if hpTotals[0] > hpTotals[1]    # Win (player has more HP in total)
    return Outcome::LOSE if hpTotals[0] < hpTotals[1]   # Loss (foe has more HP in total)
    return Outcome::DRAW
  end

  # Unused
  def pbDecisionOnTime2
    counts   = [0, 0]
    hpTotals = [0, 0]
    2.times do |side|
      pbParty(side).each do |pkmn|
        next if !pkmn || !pkmn.able?
        counts[side]   += 1
        hpTotals[side] += 100 * pkmn.hp / pkmn.totalhp
      end
      hpTotals[side] /= counts[side] if counts[side] > 1
    end
    return Outcome::WIN  if counts[0] > counts[1]        # Win (player has more able Pokémon)
    return Outcome::LOSE if counts[0] < counts[1]       # Loss (foe has more able Pokémon)
    return Outcome::WIN  if hpTotals[0] > hpTotals[1]    # Win (player has a bigger average HP %)
    return Outcome::LOSE if hpTotals[0] < hpTotals[1]   # Loss (foe has a bigger average HP %)
    return Outcome::DRAW
  end

  def pbDecisionOnDraw; return Outcome::DRAW; end   # Draw

  def pbJudge
    fainted1 = pbAllFainted?(0)
    fainted2 = pbAllFainted?(1)
    if fainted1 && fainted2
      @decision = pbDecisionOnDraw
    elsif fainted1
      @decision = Outcome::LOSE
    elsif fainted2
      @decision = Outcome::WIN
    end
  end
end

==============================================================================
# Script: Battle_ExpAndMoveLearning
==============================================================================
class Battle
  #=============================================================================
  # Gaining Experience
  #=============================================================================
  def pbGainExp
    # Play wild victory music if it's the end of the battle (has to be here)
    @scene.pbWildBattleSuccess if wildBattle? && pbAllFainted?(1) && !pbAllFainted?(0)
    return if !@internalBattle || @rules[:no_exp_gain]
    # Go through each battler in turn to find the Pokémon that participated in
    # battle against it, and award those Pokémon Exp/EVs
    expAll = $player.has_exp_all || $bag.has?(:EXPALL)
    p1 = pbParty(0)
    @battlers.each do |b|
      next unless b&.opposes?   # Can only gain Exp from fainted foes
      next if b.participants.length == 0
      next unless b.fainted? || b.captured
      # Count the number of participants
      numPartic = 0
      b.participants.each do |partic|
        next unless p1[partic]&.able? && pbIsOwner?(0, partic)
        numPartic += 1
      end
      # Find which Pokémon have an Exp Share
      expShare = []
      if !expAll
        eachInTeam(0, 0) do |pkmn, i|
          next if !pkmn.able?
          next if !pkmn.hasItem?(:EXPSHARE) && initialItem(0, i) != :EXPSHARE
          expShare.push(i)
        end
      end
      # Calculate EV and Exp gains for the participants
      if numPartic > 0 || expShare.length > 0 || expAll
        unGroupMessage = !Settings::GROUP_EXP_SHARE_MESSAGE && expShare.length > 0 && expShare.length > b.participants.length ? true : false
        # Gain EVs and Exp for participants
        eachInTeam(0, 0) do |pkmn, i|
          next if !pkmn.able?
          next unless b.participants.include?(i) || expShare.include?(i)
          showMessage = b.participants.include?(i) || unGroupMessage ? true : false
          pbGainEVsOne(i, b)
          pbGainExpOne(i, b, numPartic, expShare, expAll, showMessage)
        end
        if !unGroupMessage && (expShare.length > numPartic && pbParty(0).length > 1)
          pbDisplayPaused(_INTL("¡Tus otros Pokémon también ganaron puntos de experiencia!"))
        end
        # Gain EVs and Exp for all other Pokémon because of Exp All
        if expAll
          showMessage = true
          eachInTeam(0, 0) do |pkmn, i|
            next if !pkmn.able?
            next if b.participants.include?(i) || expShare.include?(i)
            pbDisplayPaused(_INTL("¡Tus otros Pokémon también ganaron puntos de experiencia!")) if showMessage && (expShare.length > numPartic && pbParty(0).length > 1)
            showMessage = false
            pbGainEVsOne(i, b)
            pbGainExpOne(i, b, numPartic, expShare, expAll, false)
          end
        end
      end
      # Clear the participants array
      b.participants = []
    end
  end

  def pbGainEVsOne(idxParty, defeatedBattler)
    pkmn = pbParty(0)[idxParty]   # The Pokémon gaining EVs from defeatedBattler
    evYield = defeatedBattler.pokemon.evYield
    # Num of effort points pkmn already has
    evTotal = 0
    GameData::Stat.each_main { |s| evTotal += pkmn.ev[s.id] }
    # Modify EV yield based on pkmn's held item
    if !Battle::ItemEffects.triggerEVGainModifier(pkmn.item, pkmn, evYield)
      Battle::ItemEffects.triggerEVGainModifier(initialItem(0, idxParty), pkmn, evYield)
    end
    # Double EV gain because of Pokérus
    if pkmn.pokerusStage >= 1   # Infected or cured
      evYield.each_key { |stat| evYield[stat] *= 2 }
    end
    # Gain EVs for each stat in turn
    if pkmn.shadowPokemon? && pkmn.heartStage <= 3 && pkmn.saved_ev
      pkmn.saved_ev.each_value { |e| evTotal += e }
      GameData::Stat.each_main do |s|
        evGain = evYield[s.id].clamp(0, Pokemon::EV_STAT_LIMIT - pkmn.ev[s.id] - pkmn.saved_ev[s.id])
        evGain = evGain.clamp(0, Pokemon::EV_LIMIT - evTotal)
        pkmn.saved_ev[s.id] += evGain
        evTotal += evGain
      end
    else
      GameData::Stat.each_main do |s|
        evGain = evYield[s.id].clamp(0, Pokemon::EV_STAT_LIMIT - pkmn.ev[s.id])
        evGain = evGain.clamp(0, Pokemon::EV_LIMIT - evTotal)
        pkmn.ev[s.id] += evGain
        evTotal += evGain
      end
    end
  end

  def pbGainExpOne(idxParty, defeatedBattler, numPartic, expShare, expAll, showMessages = true)
    pkmn = pbParty(0)[idxParty]   # The Pokémon gaining Exp from defeatedBattler
    growth_rate = pkmn.growth_rate
    # Don't bother calculating if gainer is already at max Exp
    if pkmn.exp >= growth_rate.maximum_exp
      pkmn.calc_stats   # To ensure new EVs still have an effect
      return
    end
    isPartic    = defeatedBattler.participants.include?(idxParty)
    hasExpShare = expShare.include?(idxParty)
    level = defeatedBattler.level
    # Main Exp calculation
    exp = 0
    a = level * defeatedBattler.pokemon.base_exp
    if expShare.length > 0 && (isPartic || hasExpShare)
      if numPartic == 0   # No participants, all Exp goes to Exp Share holders
        exp = a / (Settings::SPLIT_EXP_BETWEEN_GAINERS ? expShare.length : 1)
      elsif Settings::SPLIT_EXP_BETWEEN_GAINERS   # Gain from participating and/or Exp Share
        exp = a / (2 * numPartic) if isPartic
        exp += a / (2 * expShare.length) if hasExpShare
      else   # Gain from participating and/or Exp Share (Exp not split)
        exp = (isPartic) ? a : a / 2
      end
    elsif isPartic   # Participated in battle, no Exp Shares held by anyone
      exp = a / (Settings::SPLIT_EXP_BETWEEN_GAINERS ? numPartic : 1)
    elsif expAll   # Didn't participate in battle, gaining Exp due to Exp All
      # NOTE: Exp All works like the Exp Share from Gen 6+, not like the Exp All
      #       from Gen 1, i.e. Exp isn't split between all Pokémon gaining it.
      exp = a / 2
    end
    return if exp <= 0
    # Pokémon gain more Exp from trainer battles
    exp = (exp * 1.5).floor if Settings::MORE_EXP_FROM_TRAINER_POKEMON && trainerBattle?
    # Scale the gained Exp based on the gainer's level (or not)
    if Settings::SCALED_EXP_FORMULA
      exp /= 5
      levelAdjust = ((2 * level) + 10.0) / (pkmn.level + level + 10.0)
      levelAdjust **= 5
      levelAdjust = Math.sqrt(levelAdjust)
      exp *= levelAdjust
      exp = exp.floor
      exp += 1 if isPartic || hasExpShare
    else
      exp /= 7
    end
    # Foreign Pokémon gain more Exp
    isOutsider = (pkmn.owner.id != pbPlayer.id ||
                 (pkmn.owner.language != 0 && pkmn.owner.language != pbPlayer.language))
    if isOutsider
      if pkmn.owner.language != 0 && pkmn.owner.language != pbPlayer.language
        exp = (exp * 1.7).floor
      else
        exp = (exp * 1.5).floor
      end
    end
    # Exp. Charm increases Exp gained
    exp = exp * 3 / 2 if $bag.has?(:EXPCHARM)
    # Modify Exp gain based on pkmn's held item
    i = Battle::ItemEffects.triggerExpGainModifier(pkmn.item, pkmn, exp)
    if i < 0
      i = Battle::ItemEffects.triggerExpGainModifier(initialItem(0, idxParty), pkmn, exp)
    end
    exp = i if i >= 0
    # Boost Exp gained with high affection
    if Settings::AFFECTION_EFFECTS && @internalBattle && pkmn.affection_level >= 4 && !pkmn.mega?
      exp = exp * 6 / 5
      isOutsider = true   # To show the "boosted Exp" message
    end
    # Make sure Exp doesn't exceed the maximum
    expFinal = growth_rate.add_exp(pkmn.exp, exp)
    expGained = expFinal - pkmn.exp
    return if expGained <= 0
    # "Exp gained" message
    if showMessages
      if isOutsider
        pbDisplayPaused(_INTL("¡{1} obtuvo {2} puntos de experiencia extra!", pkmn.name, expGained))
      else
        pbDisplayPaused(_INTL("¡{1} obtuvo {2} puntos de experiencia!", pkmn.name, expGained))
      end
    end
    curLevel = pkmn.level
    newLevel = growth_rate.level_from_exp(expFinal)
    if newLevel < curLevel
      debugInfo = "Levels: #{curLevel}->#{newLevel} | Exp: #{pkmn.exp}->#{expFinal} | gain: #{expGained}"
      raise _INTL("El nuevo nivel de {1} es menor que su nivel actual, lo que no debería suceder.", pkmn.name) + "\n[#{debugInfo}]"
    end
    # Give Exp
    if pkmn.shadowPokemon?
      if pkmn.heartStage <= 3
        pkmn.exp += expGained
        $stats.total_exp_gained += expGained
      end
      return
    end
    $stats.total_exp_gained += expGained
    tempExp1 = pkmn.exp
    battler = pbFindBattler(idxParty)
    loop do   # For each level gained in turn...
      # EXP Bar animation
      levelMinExp = growth_rate.minimum_exp_for_level(curLevel)
      levelMaxExp = growth_rate.minimum_exp_for_level(curLevel + 1)
      tempExp2 = (levelMaxExp < expFinal) ? levelMaxExp : expFinal
      pkmn.exp = tempExp2
      @scene.pbEXPBar(battler, levelMinExp, levelMaxExp, tempExp1, tempExp2)
      tempExp1 = tempExp2
      curLevel += 1
      if curLevel > newLevel
        # Gained all the Exp now, end the animation
        pkmn.calc_stats
        battler&.pbUpdate(false)
        @scene.pbRefreshOne(battler.index) if battler
        break
      end
      # Levelled up
      pbCommonAnimation("LevelUp", battler) if battler
      oldTotalHP = pkmn.totalhp
      oldAttack  = pkmn.attack
      oldDefense = pkmn.defense
      oldSpAtk   = pkmn.spatk
      oldSpDef   = pkmn.spdef
      oldSpeed   = pkmn.speed
      battler.pokemon.changeHappiness("levelup") if battler&.pokemon
      pkmn.calc_stats
      battler&.pbUpdate(false)
      @scene.pbRefreshOne(battler.index) if battler
      pbDisplayPaused(_INTL("¡{1} subió al nivel {2}!", pkmn.name, curLevel) + "\\se[Pkmn level up]\\wtnp[30]")
      @scene.pbLevelUp(pkmn, battler, oldTotalHP, oldAttack, oldDefense,
                       oldSpAtk, oldSpDef, oldSpeed)
      # Learn all moves learned at this level
      moveList = pkmn.getMoveList
      moveList.each { |m| pbLearnMove(idxParty, m[1]) if m[0] == curLevel }
    end
  end

  #=============================================================================
  # Learning a move
  #=============================================================================
  def pbLearnMove(idxParty, newMove)
    return if $PokemonSystem.skip_move_learning == 0
    pkmn = pbParty(0)[idxParty]
    return if !pkmn
    pkmnName = pkmn.name
    battler = pbFindBattler(idxParty)
    moveName = GameData::Move.get(newMove).name
    # Pokémon already knows the move
    return if pkmn.hasMove?(newMove)
    # Pokémon has space for the new move; just learn it
    if pkmn.numMoves < Pokemon::MAX_MOVES
      pkmn.learn_move(newMove)
      pbDisplay(_INTL("¡{1} ha aprendido {2}!", pkmnName, moveName) + "\\se[Pkmn move learnt]\\wtnp[30]")
      if battler
        battler.moves.push(Move.from_pokemon_move(self, pkmn.moves.last))
        battler.pbCheckFormOnMovesetChange
      end
      $PokemonGlobal.add_seen_move(pkmn.species, newMove)
      return
    end
    # Pokémon already knows the maximum number of moves; try to forget one to learn the new move
    pbDisplayPaused(_INTL("{1} quiere aprender {2}, pero ya conoce {3} movimientos.",
                          pkmnName, moveName, pkmn.numMoves.to_word))
    if pbDisplayConfirm(_INTL("¿Quieres que {1} olvide un movimiento para aprender {2}?", pkmnName, moveName))
      loop do
        forgetMove = @scene.pbForgetMove(pkmn, newMove)
        if forgetMove >= 0
          oldMoveName = pkmn.moves[forgetMove].name
          pkmn.moves[forgetMove] = Pokemon::Move.new(newMove)   # Replaces current/total PP
          battler.moves[forgetMove] = Move.from_pokemon_move(self, pkmn.moves[forgetMove]) if battler
          pbDisplayPaused(_INTL("1, 2, y... ... ... ¡Puf!") + "\\se[Battle ball drop]\\wtnp[10]")
          pbDisplayPaused(_INTL("{1} olvidó como usar {2}. Y...", pkmnName, oldMoveName))
          pbDisplay(_INTL("¡{1} aprendió {2}!", pkmnName, moveName) + "\\se[Pkmn move learnt]\\wtnp[30]")
          battler&.pbCheckFormOnMovesetChange
          $PokemonGlobal.add_seen_move(pkmn.species, newMove)
          break
        elsif pbDisplayConfirm(_INTL("¿Quieres que no aprenda {1}?", moveName))
          pbDisplay(_INTL("{1} no aprendió {2}.", pkmnName, moveName))
          break
        end
      end
    else
      pbDisplay(_INTL("{1} no aprendió {2}.", pkmnName, moveName))
    end
  end
end

==============================================================================
# Script: Battle_ActionAttacksPriority
==============================================================================
class Battle
  #=============================================================================
  # Choosing a move/target
  #=============================================================================
  def pbCanChooseMove?(idxBattler, idxMove, showMessages, sleepTalk = false)
    battler = @battlers[idxBattler]
    move = battler.moves[idxMove]
    return false unless move
    if move.pp == 0 && move.total_pp > 0 && !sleepTalk
      pbDisplayPaused(_INTL("¡No quedan PP para este movimiento!")) if showMessages
      return false
    end
    if battler.effects[PBEffects::Encore] > 0
      idxEncoredMove = battler.pbEncoredMoveIndex
      return false if idxEncoredMove >= 0 && idxMove != idxEncoredMove
    end
    return battler.pbCanChooseMove?(move, true, showMessages, sleepTalk)
  end

  def pbCanChooseAnyMove?(idxBattler, sleepTalk = false)
    battler = @battlers[idxBattler]
    battler.eachMoveWithIndex do |m, i|
      next if m.pp == 0 && m.total_pp > 0 && !sleepTalk
      if battler.effects[PBEffects::Encore] > 0
        idxEncoredMove = battler.pbEncoredMoveIndex
        next if idxEncoredMove >= 0 && i != idxEncoredMove
      end
      next if !battler.pbCanChooseMove?(m, true, false, sleepTalk)
      return true
    end
    return false
  end

  # Called when the Pokémon is Encored, or if it can't use any of its moves.
  # Makes the Pokémon use the Encored move (if Encored), or Struggle.
  def pbAutoChooseMove(idxBattler, showMessages = true)
    battler = @battlers[idxBattler]
    if battler.fainted?
      pbClearChoice(idxBattler)
      return true
    end
    # Encore
    idxEncoredMove = battler.pbEncoredMoveIndex
    if idxEncoredMove >= 0 && pbCanChooseMove?(idxBattler, idxEncoredMove, false)
      encoreMove = battler.moves[idxEncoredMove]
      @choices[idxBattler][0] = :UseMove         # "Use move"
      @choices[idxBattler][1] = idxEncoredMove   # Index of move to be used
      @choices[idxBattler][2] = encoreMove       # Battle::Move object
      @choices[idxBattler][3] = -1               # No target chosen yet
      return true if singleBattle?
      if pbOwnedByPlayer?(idxBattler)
        if showMessages
          pbDisplayPaused(_INTL("¡{1} tiene que usar {2}!", battler.name, encoreMove.name))
        end
        return pbChooseTarget(battler, encoreMove)
      end
      return true
    end
    # Struggle
    if pbOwnedByPlayer?(idxBattler) && showMessages
      pbDisplayPaused(_INTL("¡A {1} no le quedan movimientos!", battler.name))
    end
    @choices[idxBattler][0] = :UseMove    # "Use move"
    @choices[idxBattler][1] = -1          # Index of move to be used
    @choices[idxBattler][2] = @struggle   # Struggle Battle::Move object
    @choices[idxBattler][3] = -1          # No target chosen yet
    return true
  end

  def pbRegisterMove(idxBattler, idxMove, showMessages = true)
    battler = @battlers[idxBattler]
    move = battler.moves[idxMove]
    return false if !pbCanChooseMove?(idxBattler, idxMove, showMessages)
    @choices[idxBattler][0] = :UseMove   # "Use move"
    @choices[idxBattler][1] = idxMove    # Index of move to be used
    @choices[idxBattler][2] = move       # Battle::Move object
    @choices[idxBattler][3] = -1         # No target chosen yet
    return true
  end

  def pbChoseMove?(idxBattler, moveID)
    return false if !@battlers[idxBattler] || @battlers[idxBattler].fainted?
    if @choices[idxBattler][0] == :UseMove && @choices[idxBattler][1]
      return @choices[idxBattler][2].id == moveID
    end
    return false
  end

  def pbChoseMoveFunctionCode?(idxBattler, code)
    return false if @battlers[idxBattler].fainted?
    if @choices[idxBattler][0] == :UseMove && @choices[idxBattler][1]
      return @choices[idxBattler][2].function_code == code
    end
    return false
  end

  def pbRegisterTarget(idxBattler, idxTarget)
    @choices[idxBattler][3] = idxTarget   # Set target of move
  end

  # Returns whether the idxTarget will be targeted by a move with target_data
  # used by a battler in idxUser.
  def pbMoveCanTarget?(idxUser, idxTarget, target_data)
    return false if target_data.num_targets == 0
    case target_data.id
    when :NearAlly
      return false if opposes?(idxUser, idxTarget)
      return false if !nearBattlers?(idxUser, idxTarget)
    when :UserOrNearAlly
      return true if idxUser == idxTarget
      return false if opposes?(idxUser, idxTarget)
      return false if !nearBattlers?(idxUser, idxTarget)
    when :AllAllies
      return false if idxUser == idxTarget
      return false if opposes?(idxUser, idxTarget)
    when :UserAndAllies
      return false if opposes?(idxUser, idxTarget)
    when :NearFoe, :RandomNearFoe, :AllNearFoes
      return false if !opposes?(idxUser, idxTarget)
      return false if !nearBattlers?(idxUser, idxTarget)
    when :Foe
      return false if !opposes?(idxUser, idxTarget)
    when :AllFoes
      return false if !opposes?(idxUser, idxTarget)
    when :NearOther, :AllNearOthers
      return false if !nearBattlers?(idxUser, idxTarget)
    when :Other
      return false if idxUser == idxTarget
    end
    return true
  end

  #=============================================================================
  # Turn order calculation (priority)
  #=============================================================================
  def pbCalculatePriority(fullCalc = false, indexArray = nil)
    needRearranging = false
    if fullCalc
      @priorityTrickRoom = (@field.effects[PBEffects::TrickRoom] > 0)
      # Recalculate everything from scratch
      randomOrder = Array.new(maxBattlerIndex + 1) { |i| i }
      (randomOrder.length - 1).times do |i|   # Can't use shuffle! here
        r = i + pbRandom(randomOrder.length - i)
        randomOrder[i], randomOrder[r] = randomOrder[r], randomOrder[i]
      end
      @priority.clear
      (0..maxBattlerIndex).each do |i|
        b = @battlers[i]
        next if !b
        # [battler, speed, sub-priority from ability, sub-priority from item,
        #  final sub-priority, priority, tie-breaker order]
        entry = [b, b.pbSpeed, 0, 0, 0, 0, randomOrder[i]]
        if @choices[b.index][0] == :UseMove || @choices[b.index][0] == :Shift
          # Calculate move's priority
          if @choices[b.index][0] == :UseMove
            move = @choices[b.index][2]
            pri = move.pbPriority(b)
            if b.abilityActive?
              pri = Battle::AbilityEffects.triggerPriorityChange(b.ability, b, move, pri)
            end
            if b.itemActive?
              pri = Battle::ItemEffects.triggerPriorityChange(b.item, b, move, pri)
            end
            entry[5] = pri
            @choices[b.index][4] = pri
          end
          # Calculate sub-priority changes (first/last within priority bracket)
          # Abilities (Stall, Quick Draw, Mycelium Might)
          if b.abilityActive?
            entry[2] = Battle::AbilityEffects.triggerPriorityBracketChange(b.ability, b, self)
          end
          # Items (Quick Claw, Custap Berry, Lagging Tail, Full Incense)
          if b.itemActive?
            entry[3] = Battle::ItemEffects.triggerPriorityBracketChange(b.item, b, self)
            entry[3] = 0 if b.hasActiveAbility?(:MYCELIUMMIGHT) && entry[2] < 0
          end
        end
        @priority.push(entry)
      end
      needRearranging = true
    else
      if (@field.effects[PBEffects::TrickRoom] > 0) != @priorityTrickRoom
        needRearranging = true
        @priorityTrickRoom = (@field.effects[PBEffects::TrickRoom] > 0)
      end
      # Recheck all battler speeds and changes to priority caused by abilities
      @priority.each do |entry|
        next if !entry
        next if indexArray && !indexArray.include?(entry[0].index)
        # Recalculate speed of battler
        newSpeed = entry[0].pbSpeed
        needRearranging = true if newSpeed != entry[1]
        entry[1] = newSpeed
        # Recalculate move's priority in case ability has changed
        choice = @choices[entry[0].index]
        if choice[0] == :UseMove
          move = choice[2]
          pri = move.pbPriority(entry[0])
          if entry[0].abilityActive?
            pri = Battle::AbilityEffects.triggerPriorityChange(entry[0].ability, entry[0], move, pri)
          end
          if entry[0].itemActive?
            pri = Battle::ItemEffects.triggerPriorityChange(entry[0].item, entry[0], move, pri)
          end
          needRearranging = true if pri != entry[5]
          entry[5] = pri
          choice[4] = pri
        end
        # NOTE: If the battler's ability at the start of this round was one with
        #       a PriorityBracketChange handler (i.e. Quick Draw), but it Mega
        #       Evolved and now doesn't have that ability, that old ability's
        #       priority bracket modifier will still apply. Similarly, if its
        #       old ability did not have a PriorityBracketChange handler but it
        #       Mega Evolved and now does have it, it will not apply this round.
        #       This is because the message saying that it had an effect appears
        #       before Mega Evolution happens, and recalculating it now would
        #       make that message inaccurate because Quick Draw only has a
        #       chance of triggering. However, since Quick Draw is exclusive to
        #       a species that doesn't Mega Evolve, these circumstances should
        #       never arise and no one will notice that the priority bracket
        #       change isn't recalculated when technically it should be.
      end
    end
    # Calculate each battler's overall sub-priority, and whether its ability or
    # item is responsible
    # NOTE: Going fast beats going slow. A Pokémon with Stall and Quick Claw
    #       will go first in its priority bracket if Quick Claw triggers,
    #       regardless of Stall.
    @priority.each do |entry|
      entry[0].effects[PBEffects::PriorityAbility] = false
      entry[0].effects[PBEffects::PriorityItem] = false
      subpri = entry[2]   # Sub-priority from ability
      if (subpri == 0 && entry[3] != 0) ||   # Ability has no effect, item has effect
         (subpri < 0 && entry[3] >= 1)   # Ability makes it slower, item makes it faster
        subpri = entry[3]   # Sub-priority from item
        entry[0].effects[PBEffects::PriorityItem] = true
      elsif subpri != 0   # Ability has effect, item had superfluous/no effect
        entry[0].effects[PBEffects::PriorityAbility] = true
      end
      entry[4] = subpri   # Final sub-priority
    end
    # Reorder the priority array
    if needRearranging
      @priority.sort! do |a, b|
        if a[5] != b[5]
          # Sort by priority (highest value first)
          b[5] <=> a[5]
        elsif a[4] != b[4]
          # Sort by sub-priority (highest value first)
          b[4] <=> a[4]
        elsif @priorityTrickRoom
          # Sort by speed (lowest first), and use tie-breaker if necessary
          (a[1] == b[1]) ? b[6] <=> a[6] : a[1] <=> b[1]
        else
          # Sort by speed (highest first), and use tie-breaker if necessary
          (a[1] == b[1]) ? b[6] <=> a[6] : b[1] <=> a[1]
        end
      end
      # Write the priority order to the debug log
      if fullCalc && $INTERNAL
        logMsg = "[Round order] "
        @priority.each_with_index do |entry, i|
          logMsg += ", " if i > 0
          logMsg += "#{entry[0].pbThis(i > 0)} (#{entry[0].index})"
        end
        PBDebug.log(logMsg)
      end
    end
  end

  def pbPriority(onlySpeedSort = false, with_commanders = false)
    ret = []
    if onlySpeedSort
      # Sort battlers by their speed stats and tie-breaker order only.
      tempArray = []
      @priority.each { |pArray| tempArray.push([pArray[0], pArray[1], pArray[6]]) }
      tempArray.sort! { |a, b| (a[1] == b[1]) ? b[2] <=> a[2] : b[1] <=> a[1] }
      tempArray.each { |tArray| ret.push(tArray[0]) }
    else
      # Sort battlers by priority, sub-priority and their speed. Ties are
      # resolved in the same way each time this method is called in a round.
      @priority.each { |pArray| ret.push(pArray[0]) if !pArray[0].fainted? }
    end
    if !with_commanders
      ret.delete_if { |b| b.effects[PBEffects::Commanding] >= 0 }
    end
    return ret
  end
end

==============================================================================
# Script: Battle_ActionSwitching
==============================================================================
class Battle
  #=============================================================================
  # Choosing Pokémon to switch
  #=============================================================================
  # Checks whether the replacement Pokémon (at party index idxParty) can enter
  # battle.
  # NOTE: Messages are only shown while in the party screen when choosing a
  #       command for the next round.
  def pbCanSwitchIn?(idxBattler, idxParty, party_screen = nil)
    return true if idxParty < 0
    party = pbParty(idxBattler)
    return false if idxParty >= party.length
    return false if !party[idxParty]
    if party[idxParty].egg?
      party_screen&.pbDisplay(_INTL("¡Un huevo no puede combatir!"))
      return false
    end
    if !pbIsOwner?(idxBattler, idxParty)
      if party_screen
        owner = pbGetOwnerFromPartyIndex(idxBattler, idxParty)
        party_screen.pbDisplay(_INTL("¡No puedes cambiar un Pokémon de {1} por uno de los tuyos!", owner.name))
      end
      return false
    end
    if party[idxParty].fainted?
      party_screen&.pbDisplay(_INTL("¡A {1} no le quedan energías para luchar!", party[idxParty].name))
      return false
    end
    if pbFindBattler(idxParty, idxBattler)
      party_screen&.pbDisplay(_INTL("¡{1} ya está en combate!", party[idxParty].name))
      return false
    end
    return true
  end

  # Check whether the currently active Pokémon (at battler index idxBattler) can
  # switch out.
  def pbCanSwitchOut?(idxBattler, party_screen = nil)
    battler = @battlers[idxBattler]
    return true if battler.fainted?
    return false if battler.effects[PBEffects::Commanding] >= 0 || battler.effects[PBEffects::CommandedBy] >= 0
    # Ability/item effects that allow switching no matter what
    if battler.abilityActive? && Battle::AbilityEffects.triggerCertainSwitching(battler.ability, battler, self)
      return true
    end
    if battler.itemActive? && Battle::ItemEffects.triggerCertainSwitching(battler.item, battler, self)
      return true
    end
    # Other certain switching effects
    return true if Settings::MORE_TYPE_EFFECTS && battler.pbHasType?(:GHOST)
    # Other certain trapping effects
    if battler.trappedInBattle?
      party_screen&.pbDisplay(_INTL("¡{1} no puede ser cambiado!", battler.pbThis))
      return false
    end
    # Trapping abilities/items
    allOtherSideBattlers(idxBattler).each do |b|
      next if !b.abilityActive?
      if Battle::AbilityEffects.triggerTrappingByTarget(b.ability, battler, b, self)
        party_screen&.pbDisplay(_INTL("¡{1} de {2} previene el cambio!", b.abilityName, b.pbThis))
        return false
      end
    end
    allOtherSideBattlers(idxBattler).each do |b|
      next if !b.itemActive?
      if Battle::ItemEffects.triggerTrappingByTarget(b.item, battler, b, self)
        party_screen&.pbDisplay(_INTL("¡{1} de {2} previene el cambio!", b.itemName, b.pbThis))
        return false
      end
    end
    return true
  end

  # Check whether the currently active Pokémon (at battler index idxBattler) can
  # switch out (and that its replacement at party index idxParty can switch in).
  # NOTE: Messages are only shown while in the party screen when choosing a
  #       command for the next round.
  def pbCanSwitch?(idxBattler, idxParty = -1, party_screen = nil)
    # Check whether party Pokémon can switch in
    return false if !pbCanSwitchIn?(idxBattler, idxParty, party_screen)
    # Make sure another battler isn't already choosing to switch to the party
    # Pokémon
    allSameSideBattlers(idxBattler).each do |b|
      next if choices[b.index][0] != :SwitchOut || choices[b.index][1] != idxParty
      party_screen&.pbDisplay(_INTL("{1} ya ha sido seleccionado.",
                                  pbParty(idxBattler)[idxParty].name))
      return false
    end
    # Check whether battler can switch out
    return pbCanSwitchOut?(idxBattler, party_screen)
  end

  def pbCanChooseNonActive?(idxBattler)
    pbParty(idxBattler).each_with_index do |_pkmn, i|
      return true if pbCanSwitchIn?(idxBattler, i)
    end
    return false
  end

  def pbRegisterSwitch(idxBattler, idxParty)
    return false if !pbCanSwitch?(idxBattler, idxParty)
    @choices[idxBattler][0] = :SwitchOut
    @choices[idxBattler][1] = idxParty   # Party index of Pokémon to switch in
    @choices[idxBattler][2] = nil
    return true
  end

  #=============================================================================
  # Open the party screen and potentially pick a replacement Pokémon (or AI
  # chooses replacement)
  #=============================================================================
  # Open party screen and potentially choose a Pokémon to switch with. Used in
  # all instances where the party screen is opened.
  def pbPartyScreen(idxBattler, checkLaxOnly = false, canCancel = false, shouldRegister = false)
    ret = -1
    @scene.pbPartyScreen(idxBattler, canCancel) do |idxParty, party_screen|
      if checkLaxOnly
        next false if !pbCanSwitchIn?(idxBattler, idxParty, party_screen)
      elsif !pbCanSwitch?(idxBattler, idxParty, party_screen)
        next false
      end
      if shouldRegister && (idxParty < 0 || !pbRegisterSwitch(idxBattler, idxParty))
        next false
      end
      ret = idxParty
      next true
    end
    return ret
  end

  # For choosing a replacement Pokémon when prompted in the middle of other
  # things happening (U-turn, Baton Pass, in def pbEORSwitch).
  def pbSwitchInBetween(idxBattler, checkLaxOnly = false, canCancel = false)
    return pbPartyScreen(idxBattler, checkLaxOnly, canCancel) if !@controlPlayer && pbOwnedByPlayer?(idxBattler)
    return @battleAI.pbDefaultChooseNewEnemy(idxBattler)
  end

  #=============================================================================
  # Switching Pokémon
  #=============================================================================
  # General switching method that checks if any Pokémon need to be sent out and,
  # if so, does. Called at the end of each round.
  def pbEORSwitch(favorDraws = false)
    return if decided? && !favorDraws
    return if @decision == Outcome::DRAW && favorDraws
    pbJudge
    return if decided?
    # Check through each fainted battler to see if that spot can be filled.
    switched = []
    loop do
      switched.clear
      @battlers.each do |b|
        next if !b || !b.fainted?
        idxBattler = b.index
        next if !pbCanChooseNonActive?(idxBattler)
        if !pbOwnedByPlayer?(idxBattler)   # Opponent/ally is switching in
          next if b.wild?   # Wild Pokémon can't switch
          idxPartyNew = pbSwitchInBetween(idxBattler)
          opponent = pbGetOwnerFromBattlerIndex(idxBattler)
          # NOTE: The player is only offered the chance to switch their own
          #       Pokémon when an opponent replaces a fainted Pokémon in single
          #       battles. In double battles, etc. there is no such offer.
          if @internalBattle && !@rules[:no_switch_style] && trainerBattle? && pbSideSize(0) == 1 &&
             opposes?(idxBattler) && !@battlers[0].fainted? && !switched.include?(0) &&
             pbCanChooseNonActive?(0) && @battlers[0].effects[PBEffects::Outrage] == 0
            idxPartyForName = idxPartyNew
            enemyParty = pbParty(idxBattler)
            if enemyParty[idxPartyNew].ability == :ILLUSION && !pbCheckGlobalAbility(:NEUTRALIZINGGAS)
              new_index = pbLastInTeam(idxBattler)
              idxPartyForName = new_index if new_index >= 0 && new_index != idxPartyNew
            end
            if pbDisplayConfirm(_INTL("{1} va a sacar a {2}. ¿Quieres cambiar de Pokémon?",
                                      opponent.full_name, enemyParty[idxPartyForName].name))
              idxPlayerPartyNew = pbSwitchInBetween(0, false, true)
              if idxPlayerPartyNew >= 0
                pbMessageOnRecall(@battlers[0])
                pbRecallAndReplace(0, idxPlayerPartyNew)
                switched.push(0)
              end
            end
          end
          pbRecallAndReplace(idxBattler, idxPartyNew)
          switched.push(idxBattler)
        elsif trainerBattle?   # Player switches in in a trainer battle
          idxPlayerPartyNew = pbGetReplacementPokemonIndex(idxBattler)   # Owner chooses
          pbRecallAndReplace(idxBattler, idxPlayerPartyNew)
          switched.push(idxBattler)
        else   # Player's Pokémon has fainted in a wild battle
          switch = false
          if pbPlayerBattlerCount > 0
            switch = true
          elsif pbDisplayConfirm(_INTL("¿Quieres sacar a otro Pokémon?"))
            switch = true
          else
            switch = (pbRun(idxBattler, true) <= 0)
          end
          if switch
            idxPlayerPartyNew = pbGetReplacementPokemonIndex(idxBattler)   # Owner chooses
            pbRecallAndReplace(idxBattler, idxPlayerPartyNew)
            switched.push(idxBattler)
          end
        end
      end
      break if switched.length == 0
      pbOnBattlerEnteringBattle(switched)
    end
  end

  def pbGetReplacementPokemonIndex(idxBattler, random = false)
    if random
      choices = []   # Find all Pokémon that can switch in
      eachInTeamFromBattlerIndex(idxBattler) do |_pkmn, i|
        choices.push(i) if pbCanSwitchIn?(idxBattler, i)
      end
      return -1 if choices.length == 0
      return choices[pbRandom(choices.length)]
    else
      return pbSwitchInBetween(idxBattler, true)
    end
  end

  # Actually performs the recalling and sending out in all situations.
  def pbRecallAndReplace(idxBattler, idxParty, randomReplacement = false, batonPass = false)
    @scene.pbRecall(idxBattler) if !@battlers[idxBattler].fainted?
    @battlers[idxBattler].pbAbilitiesOnSwitchOut   # Inc. primordial weather check
    @scene.pbShowPartyLineup(idxBattler & 1) if pbSideSize(idxBattler) == 1
    pbMessagesOnReplace(idxBattler, idxParty) if !randomReplacement
    pbReplace(idxBattler, idxParty, batonPass)
  end

  def pbMessageOnRecall(battler)
    if battler.pbOwnedByPlayer?
      if battler.hp <= battler.totalhp / 4
        pbDisplayBrief(_INTL("¡Buen trabajo, {1}! ¡Regresa!", battler.name))
      elsif battler.hp <= battler.totalhp / 2
        pbDisplayBrief(_INTL("¡OK, {1}! ¡Regresa!", battler.name))
      elsif battler.turnCount >= 5
        pbDisplayBrief(_INTL("¡{1}, es suficiente! ¡Regresa!", battler.name))
      elsif battler.turnCount >= 2
        pbDisplayBrief(_INTL("¡{1}, regresa!", battler.name))
      else
        pbDisplayBrief(_INTL("¡{1}, cambia! ¡Regresa!", battler.name))
      end
    else
      owner = pbGetOwnerName(battler.index)
      pbDisplayBrief(_INTL("¡{1} retiró a {2}!", owner, battler.name))
    end
  end

  # Only called from def pbRecallAndReplace and Battle Arena's def pbSwitch.
  def pbMessagesOnReplace(idxBattler, idxParty)
    party = pbParty(idxBattler)
    newPkmnName = party[idxParty].name
    if party[idxParty].ability == :ILLUSION && !pbCheckGlobalAbility(:NEUTRALIZINGGAS)
      new_index = pbLastInTeam(idxBattler)
      newPkmnName = party[new_index].name if new_index >= 0 && new_index != idxParty
    end
    if pbOwnedByPlayer?(idxBattler)
      opposing = @battlers[idxBattler].pbDirectOpposing
      if opposing.fainted? || opposing.hp == opposing.totalhp
        pbDisplayBrief(_INTL("¡Te toca, {1}!", newPkmnName))
      elsif opposing.hp >= opposing.totalhp / 2
        pbDisplayBrief(_INTL("¡Adelante, {1}!", newPkmnName))
      elsif opposing.hp >= opposing.totalhp / 4
        pbDisplayBrief(_INTL("¡Solo un poco más! ¡Aguanta, {1}!", newPkmnName))
      else
        pbDisplayBrief(_INTL("¡Tu oponente está débil! ¡A por él, {1}!", newPkmnName))
      end
    else
      owner = pbGetOwnerFromBattlerIndex(idxBattler)
      pbDisplayBrief(_INTL("¡{1} sacó a {2}!", owner.full_name, newPkmnName))
    end
  end

  # Only called from def pbRecallAndReplace above and Battle Arena's def
  # pbSwitch.
  def pbReplace(idxBattler, idxParty, batonPass = false)
    party = pbParty(idxBattler)
    idxPartyOld = @battlers[idxBattler].pokemonIndex
    # Initialise the new Pokémon
    @battlers[idxBattler].pbInitialize(party[idxParty], idxParty, batonPass)
    # Reorder the party for this battle
    partyOrder = pbPartyOrder(idxBattler)
    partyOrder[idxParty], partyOrder[idxPartyOld] = partyOrder[idxPartyOld], partyOrder[idxParty]
    # Send out the new Pokémon
    pbSendOut([[idxBattler, party[idxParty]]])
    pbCalculatePriority(false, [idxBattler]) if Settings::RECALCULATE_TURN_ORDER_AFTER_SPEED_CHANGES
  end

  # Called from def pbReplace above and at the start of battle.
  # sendOuts is an array; each element is itself an array: [idxBattler,pkmn]
  def pbSendOut(sendOuts, startBattle = false)
    sendOuts.each { |b| @peer.pbOnEnteringBattle(self, @battlers[b[0]], b[1]) }
    @scene.pbSendOutBattlers(sendOuts, startBattle)
    sendOuts.each do |b|
      @scene.pbResetCommandsIndex(b[0])
      pbSetSeen(@battlers[b[0]])
      @usedInBattle[b[0] & 1][b[0] / 2] = true
    end
  end

  #=============================================================================
  # Effects upon a Pokémon entering battle
  #=============================================================================
  # Called at the start of battle only.
  def pbOnAllBattlersEnteringBattle
    pbCalculatePriority(true)
    battler_indices = []
    allBattlers(true).each { |b| battler_indices.push(b.index) }
    pbOnBattlerEnteringBattle(battler_indices)
    pbCalculatePriority
    # Check forms are correct
    allBattlers(true).each { |b| b.pbCheckForm }
  end

  # Called when one or more Pokémon switch in. Does a lot of things, including
  # entry hazards, form changes and items/abilities that trigger upon switching
  # in.
  def pbOnBattlerEnteringBattle(battler_index, skip_event_reset = false)
    clearStagesChangeRecords
    battler_index = [battler_index] if !battler_index.is_a?(Array)
    battler_index.flatten!
    # NOTE: This isn't done for switch commands, because they previously call
    #       pbRecallAndReplace, which could cause Neutralizing Gas to end, which
    #       in turn could cause Intimidate to trigger another Pokémon's Eject
    #       Pack. That Eject Pack should trigger at the end of this method, but
    #       this resetting would prevent that from happening, so it is skipped
    #       and instead done earlier in def pbAttackPhaseSwitch.
    if !skip_event_reset
      allBattlers(true).each do |b|
        b.droppedBelowHalfHP = false
        b.droppedBelowThirdHP = false
        b.statsDropped = false
      end
    end
    # For each battler that entered battle, in speed order
    pbPriority(true).each do |b|
      next if !battler_index.include?(b.index) || b.fainted?
      pbRecordBattlerAsParticipated(b)
      pbMessagesOnBattlerEnteringBattle(b)
      # Position/field effects triggered by the battler appearing
      pbEffectsOnBattlerEnteringPosition(b)   # Healing Wish/Lunar Dance
      pbEntryHazards(b)
      # Battler faints if it is knocked out because of an entry hazard above
      if b.fainted?
        b.pbFaint
        pbGainExp
        pbJudge
        next
      end
      b.pbCheckForm
      # Primal Revert upon entering battle
      pbPrimalReversion(b.index)
      # Check for end of primordial weather
      pbEndPrimordialWeather
      # Abilities that trigger upon switching in
      if (!b.fainted? && b.unstoppableAbility?) || b.abilityActive?
        Battle::AbilityEffects.triggerOnSwitchIn(b.ability, b, self, true)
      end
      # Check for end of primordial weather
      pbEndPrimordialWeather
      # Items that trigger upon switching in (Air Balloon message)
      if b.itemActive?
        Battle::ItemEffects.triggerOnSwitchIn(b.item, b, self)
      end
      # Berry check, status-curing ability check
      b.pbHeldItemTriggerCheck
      b.pbAbilityStatusCureCheck
    end
    # Ending primordial weather, checking Trace
    pbPriority(true).each { |b| b.pbContinualAbilityChecks(true) }
    checkStatChangeResponses
    # Check for triggering of Emergency Exit/Wimp Out/Eject Pack (only one will
    # be triggered)
    pbPriority(true, true).each do |b|
      break if b.pbItemOnStatDropped
      break if b.pbAbilitiesOnDamageTaken
    end
    checkStatChangeResponses
    allBattlers(true).each do |b|
      b.droppedBelowHalfHP = false
      b.droppedBelowThirdHP = false
      b.statsDropped = false
    end
  end

  def pbRecordBattlerAsParticipated(battler)
    # Record money-doubling effect of Amulet Coin/Luck Incense
    if !battler.opposes? && [:AMULETCOIN, :LUCKINCENSE].include?(battler.item_id)
      @field.effects[PBEffects::AmuletCoin] = true
    end
    # Update battlers' participants (who will gain Exp/EVs when a battler faints)
    allBattlers(true).each { |b| b.pbUpdateParticipants }
  end

  def pbMessagesOnBattlerEnteringBattle(battler)
    # Introduce Shadow Pokémon
    if battler.shadowPokemon?
      pbCommonAnimation("Shadow", battler)
      pbDisplay(_INTL("¡Oh!\n¡Un Pokémon Oscuro!")) if battler.opposes?
    end
  end

  # Called when a Pokémon enters battle, and when Ally Switch is used.
  def pbEffectsOnBattlerEnteringPosition(battler)
    position = @positions[battler.index]
    # Healing Wish
    if position.effects[PBEffects::HealingWish]
      if battler.canHeal? || battler.status != :NONE
        pbCommonAnimation("HealingWish", battler)
        pbDisplay(_INTL("¡El deseo de curación se hizo realidad para {1}!", battler.pbThis(true)))
        battler.pbRecoverHP(battler.totalhp)
        battler.pbCureStatus(false)
        position.effects[PBEffects::HealingWish] = false
      elsif Settings::MECHANICS_GENERATION < 8
        position.effects[PBEffects::HealingWish] = false
      end
    end
    # Lunar Dance
    if position.effects[PBEffects::LunarDance]
      full_pp = true
      battler.eachMove { |m| full_pp = false if m.pp < m.total_pp }
      if battler.canHeal? || battler.status != :NONE || !full_pp
        pbCommonAnimation("LunarDance", battler)
        pbDisplay(_INTL("¡Un místico halo de luz de luna envuelve a {1}!", battler.pbThis(true)))
        battler.pbRecoverHP(battler.totalhp)
        battler.pbCureStatus(false)
        battler.eachMove { |m| battler.pbSetPP(m, m.total_pp) }
        position.effects[PBEffects::LunarDance] = false
      elsif Settings::MECHANICS_GENERATION < 8
        position.effects[PBEffects::LunarDance] = false
      end
    end
  end

  def pbEntryHazards(battler)
    battler_side = battler.pbOwnSide
    # Stealth Rock
    if battler_side.effects[PBEffects::StealthRock] && battler.takesIndirectDamage? &&
       GameData::Type.exists?(:ROCK) && !battler.hasActiveItem?(:HEAVYDUTYBOOTS)
      bTypes = battler.pbTypes(true)
      eff = Effectiveness.calculate(:ROCK, *bTypes)
      if !Effectiveness.ineffective?(eff)
        battler.pbReduceHP(battler.totalhp * eff / 8, false)
        pbDisplay(_INTL("¡Unas piedras puntiagudas han dañado a {1}!", battler.pbThis(true)))
        battler.pbItemHPHealCheck
      end
    end
    # Spikes
    if battler_side.effects[PBEffects::Spikes] > 0 && battler.takesIndirectDamage? &&
       !battler.airborne? && !battler.hasActiveItem?(:HEAVYDUTYBOOTS)
      spikesDiv = [8, 6, 4][battler_side.effects[PBEffects::Spikes] - 1]
      battler.pbReduceHP(battler.totalhp / spikesDiv, false)
      pbDisplay(_INTL("¡Las púas han herido al {1}!", battler.pbThis(true)))
      battler.pbItemHPHealCheck
    end
    # Toxic Spikes
    if battler_side.effects[PBEffects::ToxicSpikes] > 0 && !battler.fainted? && !battler.airborne?
      if battler.pbHasType?(:POISON)
        battler_side.effects[PBEffects::ToxicSpikes] = 0
        @scene.pbUpdateHazardSprites if @scene.respond_to?(:pbUpdateHazardSprites)
        pbDisplay(_INTL("¡Las púas tóxicas lanzadas a {1} han desaparecido!", battler.pbThis(true)))
      elsif battler.pbCanPoison?(nil, false) && !battler.hasActiveItem?(:HEAVYDUTYBOOTS)
        if battler_side.effects[PBEffects::ToxicSpikes] == 2
          battler.pbPoison(nil, _INTL("¡{1} ha sido envenenado por las púas tóxicas!", battler.pbThis), true)
        else
          battler.pbPoison(nil, _INTL("¡{1} ha sido gravemente envenenado por las púas tóxicas!", battler.pbThis))
        end
      end
    end
    # Sticky Web
    if battler_side.effects[PBEffects::StickyWeb] && !battler.fainted? && !battler.airborne? &&
       !battler.hasActiveItem?(:HEAVYDUTYBOOTS)
      pbDisplay(_INTL("¡{1} ha caído en una red viscosa!", battler.pbThis))
      if battler.pbCanLowerStatStage?(:SPEED)
        battler.pbLowerStatStage(:SPEED, 1, nil)
        battler.pbItemStatRestoreCheck
      end
    end
  end
end

==============================================================================
# Script: Battle_ActionUseItem
==============================================================================
class Battle
  #=============================================================================
  # Choosing to use an item
  #=============================================================================
  def pbCanUseItemOnPokemon?(item, pkmn, battler, scene, showMessages = true)
    if !pkmn || pkmn.egg?
      scene.pbDisplay(_INTL("No tendrá ningún efecto.")) if showMessages
      return false
    end
    # Embargo
    if battler && battler.effects[PBEffects::Embargo] > 0
      if showMessages
        scene.pbDisplay(_INTL("El efecto de Embargo impide usar objetos en {1}!",
                              battler.pbThis(true)))
      end
      return false
    end
    # Hyper Mode and non-Scents
    if pkmn.hyper_mode && !GameData::Item.get(item)&.is_scent?
      scene.pbDisplay(_INTL("No tendrá ningún efecto.")) if showMessages
      return false
    end
    return true
  end

  # NOTE: Using a Poké Ball consumes all your actions for the round. The method
  #       below is one half of making this happen; the other half is in the
  #       ItemHandlers::CanUseInBattle for Poké Balls.
  def pbItemUsesAllActions?(item)
    return true if GameData::Item.get(item).is_poke_ball?
    return false
  end

  def pbRegisterItem(idxBattler, item, idxTarget = nil, idxMove = nil)
    # Register for use of item on a Pokémon in the party
    @choices[idxBattler][0] = :UseItem
    @choices[idxBattler][1] = item        # ID of item to be used
    @choices[idxBattler][2] = idxTarget   # Party index of Pokémon to use item on
    @choices[idxBattler][3] = idxMove     # Index of move to recharge (Ethers)
    # Delete the item from the Bag. If it turns out it will have no effect, it
    # will be re-added to the Bag later.
    pbConsumeItemInBag(item, idxBattler)
    return true
  end

  #=============================================================================
  # Using an item
  #=============================================================================
  def pbConsumeItemInBag(item, idxBattler)
    return if !item
    return if !GameData::Item.get(item).consumed_after_use?
    if pbOwnedByPlayer?(idxBattler)
      if !$bag.remove(item)
        raise _INTL("Se ha intentado consumir un objeto que no estaba en la Mochila de alguna manera.")
      end
    else
      items = pbGetOwnerItems(idxBattler)
      items.delete_at(items.index(item))
    end
  end

  def pbReturnUnusedItemToBag(item, idxBattler)
    return if !item
    return if !GameData::Item.get(item).consumed_after_use?
    if pbOwnedByPlayer?(idxBattler)
      if $bag&.can_add?(item)
        $bag.add(item)
      else
        raise _INTL("No se pudo devolver el artículo no utilizado a la Mochila de alguna manera.")
      end
    else
      items = pbGetOwnerItems(idxBattler)
      items&.push(item)
    end
  end

  def pbUseItemMessage(item, trainer_name, battler = nil)
    item_data = GameData::Item.get(item)
    # one_target_of_many = 
    item_name = item_data.portion_name
    if battler && !battler.allAllies.empty?
      # Specify which Pokémon the item was used on (only for Pokémon in battle,
      # because the effects of items used on party Pokémon all mention the
      # Pokémon's name so it doesn't need specifying here too)
      pbDisplayBrief(_INTL("{1} usó {2} en {3}.", trainer_name, item_name, battler.name))
    else
      pbDisplayBrief(_INTL("{1} usó {2}.", trainer_name, item_name))
    end
  end

  # Uses an item on a Pokémon in the trainer's party.
  def pbUseItemOnPokemon(item, idxParty, userBattler)
    trainerName = pbGetOwnerName(userBattler.index)
    pbUseItemMessage(item, trainerName)
    pkmn = pbParty(userBattler.index)[idxParty]
    battler = pbFindBattler(idxParty, userBattler.index)
    ch = @choices[userBattler.index]
    if ItemHandlers.triggerCanUseInBattle(item, pkmn, battler, ch[3], true, self, @scene, false)
      ItemHandlers.triggerBattleUseOnPokemon(item, pkmn, battler, ch, @scene)
      ch[1] = nil   # Delete item from choice
      return
    end
    pbDisplay(_INTL("¡Pero no tuvo efecto!"))
    # Return unused item to Bag
    pbReturnUnusedItemToBag(item, userBattler.index)
  end

  # Uses an item on a Pokémon in battle that belongs to the trainer.
  def pbUseItemOnBattler(item, idxParty, userBattler)
    trainerName = pbGetOwnerName(userBattler.index)
    battler = pbFindBattler(idxParty, userBattler.index)
    pbUseItemMessage(item, trainerName, battler)
    ch = @choices[userBattler.index]
    if battler
      if ItemHandlers.triggerCanUseInBattle(item, battler.pokemon, battler, ch[3], true, self, @scene, false)
        ItemHandlers.triggerBattleUseOnBattler(item, battler, @scene)
        ch[1] = nil   # Delete item from choice
        battler.pbItemOnStatDropped
        return
      else
        pbDisplay(_INTL("¡Pero no tuvo efecto!"))
      end
    else
      pbDisplay(_INTL("¡Pero no es donde se puede usar este objeto.!"))
    end
    # Return unused item to Bag
    pbReturnUnusedItemToBag(item, userBattler.index)
  end

  # Uses a Poké Ball in battle directly.
  def pbUsePokeBallInBattle(item, idxBattler, userBattler)
    idxBattler = userBattler.index if idxBattler < 0
    battler = @battlers[idxBattler]
    ItemHandlers.triggerUseInBattle(item, battler, self)
    @choices[userBattler.index][1] = nil   # Delete item from choice
  end

  # Uses an item in battle directly.
  def pbUseItemInBattle(item, idxBattler, userBattler)
    trainerName = pbGetOwnerName(userBattler.index)
    pbUseItemMessage(item, trainerName)
    battler = (idxBattler < 0) ? userBattler : @battlers[idxBattler]
    pkmn = battler.pokemon
    ch = @choices[userBattler.index]
    if ItemHandlers.triggerCanUseInBattle(item, pkmn, battler, ch[3], true, self, @scene, false)
      ItemHandlers.triggerUseInBattle(item, battler, self)
      ch[1] = nil   # Delete item from choice
      return
    end
    pbDisplay(_INTL("¡Pero no tuvo efecto!"))
    # Return unused item to Bag
    pbReturnUnusedItemToBag(item, userBattler.index)
  end
end

==============================================================================
# Script: Battle_ActionRunning
==============================================================================
#===============================================================================
#
#===============================================================================
class Battle
  #-----------------------------------------------------------------------------
  # Running from battle
  #-----------------------------------------------------------------------------

  def pbCanRun?(idxBattler)
    return false if trainerBattle?
    battler = @battlers[idxBattler]
    return false if @rules[:cannot_run] && !battler.opposes?
    return false if battler.effects[PBEffects::Commanding] >= 0 || battler.effects[PBEffects::CommandedBy] >= 0
    return true if battler.pbHasType?(:GHOST) && Settings::MORE_TYPE_EFFECTS
    return true if battler.abilityActive? &&
                   Battle::AbilityEffects.triggerCertainEscapeFromBattle(battler.ability, battler)
    return true if battler.itemActive? &&
                   Battle::ItemEffects.triggerCertainEscapeFromBattle(battler.item, battler)
    return false if battler.trappedInBattle?
    allOtherSideBattlers(idxBattler).each do |b|
      return false if b.abilityActive? &&
                      Battle::AbilityEffects.triggerTrappingByTarget(b.ability, battler, b, self)
      return false if b.itemActive? &&
                      Battle::ItemEffects.triggerTrappingByTarget(b.item, battler, b, self)
    end
    return true
  end

  # Return values:
  # -1: Chose not to end the battle via Debug means
  #  0: Couldn't end the battle via Debug means; carry on trying to run
  #  1: Ended the battle via Debug means
  def pbDebugRun
    return 0 if !$DEBUG || !Input.press?(Input::CTRL)
    commands = [_INTL("Victoria"), _INTL("Derrota"),
                _INTL("Empate"), _INTL("Rendirse")]
    commands.push(_INTL("Captura")) if wildBattle?
    commands.push(_INTL("Cancelar"))
    case pbShowCommands(_INTL("Elige un resultado para este combate."), commands)
    when 0
      @decision = Outcome::WIN
    when 1
      @decision = Outcome::LOSE
    when 2
      @decision = Outcome::DRAW
    when 3
      pbSEPlay("Battle flee")
      pbDisplayPaused(_INTL("¡Escapas sin problemas!"))
      @decision = Outcome::FLEE
    when 4   # Capture
      return -1 if trainerBattle?
      @decision = Outcome::CATCH
    else
      return -1
    end
    return 1
  end

  # Return values:
  # -1: Failed fleeing
  #  0: Wasn't possible to attempt fleeing, continue choosing action for the round
  #  1: Succeeded at fleeing, battle will end
  # duringBattle is true for replacing a fainted Pokémon during the End Of Round
  # phase, and false for choosing the Run command.
  def pbRun(idxBattler, duringBattle = false)
    battler = @battlers[idxBattler]
    if battler.opposes?
      return 0 if trainerBattle?
      @choices[idxBattler][0] = :Run
      @choices[idxBattler][1] = 0
      @choices[idxBattler][2] = nil
      return -1
    end
    # Debug ending the battle
    debug_ret = pbDebugRun
    return debug_ret if debug_ret != 0
    # Running from trainer battles
    if trainerBattle?
      if @internalBattle
      
        if Settings::CAN_FORFEIT_TRAINER_BATTLES
          pbDisplayPaused(_INTL("¿Quieres perder el combate y abandonar ahora?"))
          if pbDisplayConfirm(_INTL("Abandonar el combate es lo mismo que perderlo. ¿Estás seguro?"))
            @decision = Outcome::LOSE   # Treated as a loss
            return 1
          end
        else
          pbDisplayPaused(_INTL("¡No puedes huir de un combate contra un Entrenador!"))
        end
      elsif pbDisplayConfirm(_INTL("¿Quieres perder el combate y abandonar ahora?"))
        pbSEPlay("Battle flee")
        pbDisplay(_INTL("{1} perdió el combate!", self.pbPlayer.name))
        @decision = Outcome::FLEE
        return 1
      end
      return 0
    end
    if @rules[:cannot_run]
      pbDisplayPaused(_INTL("¡No puedes escapar!"))
      return 0
    end
    if !duringBattle
      if battler.pbHasType?(:GHOST) && Settings::MORE_TYPE_EFFECTS
        pbSEPlay("Battle flee")
        pbDisplayPaused(_INTL("¡Escapas sin problemas!"))
        @decision = Outcome::FLEE
        return 1
      end
      # Abilities that guarantee escape
      if battler.abilityActive? &&
         Battle::AbilityEffects.triggerCertainEscapeFromBattle(battler.ability, battler)
        pbShowAbilitySplash(battler, true)
        pbHideAbilitySplash(battler)
        pbSEPlay("Battle flee")
        pbDisplayPaused(_INTL("¡Escapas sin problemas!"))
        @decision = Outcome::FLEE
        return 1
      end
      # Held items that guarantee escape
      if battler.itemActive? &&
         Battle::ItemEffects.triggerCertainEscapeFromBattle(battler.item, battler)
        pbSEPlay("Battle flee")
        pbDisplayPaused(_INTL("¡{1} escapó usando {2}!", battler.pbThis, battler.itemName))
        @decision = Outcome::FLEE
        return 1
      end
      # Other certain trapping effects
      if battler.trappedInBattle?
        pbDisplayPaused(_INTL("¡No puedes huir!"))
        return 0
      end
      # Trapping abilities/items
      allOtherSideBattlers(idxBattler).each do |b|
        next if !b.abilityActive?
        if Battle::AbilityEffects.triggerTrappingByTarget(b.ability, battler, b, self)
          pbDisplayPaused(_INTL("¡{1} evita que se huya con {2}!", b.pbThis, b.abilityName))
          return 0
        end
      end
      allOtherSideBattlers(idxBattler).each do |b|
        next if !b.itemActive?
        if Battle::ItemEffects.triggerTrappingByTarget(b.item, battler, b, self)
          pbDisplayPaused(_INTL("¡{1} evita que se huya con {2}!", b.pbThis, b.itemName))
          return 0
        end
      end
    end
    # Fleeing calculation
    # Get the speeds of the Pokémon fleeing and the fastest opponent
    # NOTE: Not pbSpeed, because using unmodified Speed.
    @runCommand += 1 if !duringBattle   # Make it easier to flee next time
    speedPlayer = @battlers[idxBattler].speed
    speedEnemy = 1
    allOtherSideBattlers(idxBattler).each do |b|
      speed = b.speed
      speedEnemy = speed if speedEnemy < speed
    end
    # Compare speeds and perform fleeing calculation
    if speedPlayer > speedEnemy
      rate = 256
    else
      rate = (speedPlayer * 128) / speedEnemy
      rate += @runCommand * 30
    end
    if rate >= 256 || @battleAI.pbAIRandom(256) < rate
      pbSEPlay("Battle flee")
      pbDisplayPaused(_INTL("¡Escapas sin problemas!"))
      @decision = Outcome::FLEE
      return 1
    end
    pbDisplayPaused(_INTL("¡No puedes huir!"))
    return -1
  end
end

==============================================================================
# Script: Battle_ActionOther
==============================================================================
class Battle
  #=============================================================================
  # Shifting a battler to another position in a battle larger than double
  #=============================================================================
  def pbCanShift?(idxBattler)
    return false if pbSideSize(0) <= 2 && pbSideSize(1) <= 2   # Double battle or smaller
    idxOther = -1
    case pbSideSize(idxBattler)
    when 1
      return false   # Only one battler on that side
    when 2
      idxOther = (idxBattler + 2) % 4
    when 3
      return false if [2, 3].include?(idxBattler)   # In middle spot already
      idxOther = (idxBattler.even?) ? 2 : 3
    end
    return false if pbGetOwnerIndexFromBattlerIndex(idxBattler) != pbGetOwnerIndexFromBattlerIndex(idxOther)
    return true
  end

  def pbRegisterShift(idxBattler)
    @choices[idxBattler][0] = :Shift
    @choices[idxBattler][1] = 0
    @choices[idxBattler][2] = nil
    return true
  end

  #=============================================================================
  # Calling at a battler
  #=============================================================================
  def pbRegisterCall(idxBattler)
    @choices[idxBattler][0] = :Call
    @choices[idxBattler][1] = 0
    @choices[idxBattler][2] = nil
    return true
  end

  def pbCall(idxBattler)
    clearStagesChangeRecords
    battler = @battlers[idxBattler]
    trainerName = pbGetOwnerName(idxBattler)
    pbDisplay(_INTL("¡{1} llamó a {2}!", trainerName, battler.pbThis(true)))
    pbDisplay(_INTL("¡{1}!", battler.name))
    if battler.shadowPokemon?
      if battler.inHyperMode?
        battler.pokemon.hyper_mode = false
        battler.pokemon.change_heart_gauge("call")
        pbDisplay(_INTL("¡{1} volvió en sí ante la llamada de su entrenador!", battler.pbThis))
      else
        pbDisplay(_INTL("¡Pero no sucedió nada!"))
      end
    elsif battler.status == :SLEEP
      battler.pbCureStatus
    elsif battler.pbCanRaiseStatStage?(:ACCURACY, battler)
      battler.pbRaiseStatStage(:ACCURACY, 1, battler)
      battler.pbItemOnStatDropped
    else
      pbDisplay(_INTL("¡Pero no sucedió nada!"))
    end
    checkStatChangeResponses
  end

  #=============================================================================
  # Choosing to Mega Evolve a battler
  #=============================================================================
  def pbHasMegaRing?(idxBattler)
    if pbOwnedByPlayer?(idxBattler)
      @mega_rings.each { |item| return true if $bag.has?(item) }
    else
      trainer_items = pbGetOwnerItems(idxBattler)
      return false if !trainer_items
      @mega_rings.each { |item| return true if trainer_items.include?(item) }
    end
    return false
  end

  def pbGetMegaRingName(idxBattler)
    if !@mega_rings.empty?
      if pbOwnedByPlayer?(idxBattler)
        @mega_rings.each { |item| return GameData::Item.get(item).name if $bag.has?(item) }
      else
        trainer_items = pbGetOwnerItems(idxBattler)
        if trainer_items
          @mega_rings.each { |item| return GameData::Item.get(item).name if trainer_items.include?(item) }
        end
      end
    end
    return _INTL("Mega-aro")
  end

  def pbCanMegaEvolve?(idxBattler)
    return false if $game_switches[Settings::NO_MEGA_EVOLUTION]
    return false if !@battlers[idxBattler].hasMega?
    return false if @battlers[idxBattler].wild?
    return true if $DEBUG && Input.press?(Input::CTRL)
    return false if @battlers[idxBattler].effects[PBEffects::SkyDrop] >= 0
    return false if !pbHasMegaRing?(idxBattler)
    side  = @battlers[idxBattler].idxOwnSide
    owner = pbGetOwnerIndexFromBattlerIndex(idxBattler)
    return @megaEvolution[side][owner] == -1
  end

  def pbRegisterMegaEvolution(idxBattler)
    side  = @battlers[idxBattler].idxOwnSide
    owner = pbGetOwnerIndexFromBattlerIndex(idxBattler)
    @megaEvolution[side][owner] = idxBattler
  end

  def pbUnregisterMegaEvolution(idxBattler)
    side  = @battlers[idxBattler].idxOwnSide
    owner = pbGetOwnerIndexFromBattlerIndex(idxBattler)
    @megaEvolution[side][owner] = -1 if @megaEvolution[side][owner] == idxBattler
  end

  def pbToggleRegisteredMegaEvolution(idxBattler)
    side  = @battlers[idxBattler].idxOwnSide
    owner = pbGetOwnerIndexFromBattlerIndex(idxBattler)
    if @megaEvolution[side][owner] == idxBattler
      @megaEvolution[side][owner] = -1
    else
      @megaEvolution[side][owner] = idxBattler
    end
  end

  def pbRegisteredMegaEvolution?(idxBattler)
    side  = @battlers[idxBattler].idxOwnSide
    owner = pbGetOwnerIndexFromBattlerIndex(idxBattler)
    return @megaEvolution[side][owner] == idxBattler
  end

  #=============================================================================
  # Mega Evolving a battler
  #=============================================================================
  def pbMegaEvolve(idxBattler)
    battler = @battlers[idxBattler]
    return if !battler || !battler.pokemon
    return if !battler.hasMega? || battler.mega?
    $stats.mega_evolution_count += 1 if battler.pbOwnedByPlayer?
    trainerName = pbGetOwnerName(idxBattler)
    old_ability = battler.ability_id
    # Break Illusion
    if battler.hasActiveAbility?(:ILLUSION)
      Battle::AbilityEffects.triggerOnBeingHit(battler.ability, nil, battler, nil, self)
    end
    # Mega Evolve
    case battler.pokemon.megaMessage
    when 1   # Rayquaza
      pbDisplay(_INTL("¡El ruego vehemente de {1} alcanza a {2}!", trainerName, battler.pbThis(true)))
    else
      pbDisplay(_INTL("¡La {2} de {1} está reaccionando al {4} de {3}!",
                      battler.pbThis(true), battler.itemName, trainerName, pbGetMegaRingName(idxBattler)))
    end
    pbCommonAnimation("MegaEvolution", battler)
    battler.pokemon.makeMega
    battler.form = battler.pokemon.form
    battler.pbUpdate(true)
    @scene.pbChangePokemon(battler, battler.pokemon)
    @scene.pbRefreshOne(idxBattler)
    pbCommonAnimation("MegaEvolution2", battler)
    megaName = battler.pokemon.megaName
    megaName = _INTL("Mega-{1}", battler.pokemon.speciesName) if nil_or_empty?(megaName)
    pbDisplay(_INTL("¡{1} ha evolucionado a {2}!", battler.pbThis, megaName))
    side  = battler.idxOwnSide
    owner = pbGetOwnerIndexFromBattlerIndex(idxBattler)
    @megaEvolution[side][owner] = -2
    MultipleForms.call("changePokemonOnMegaEvolving", battler, battler.pokemon)
    if battler.isSpecies?(:GENGAR) && battler.mega?
      battler.effects[PBEffects::Telekinesis] = 0
    end
    # Trigger ability
    battler.pbOnLosingAbility(old_ability)
    battler.pbTriggerAbilityOnGainingIt
    # Recalculate turn order
    pbCalculatePriority(false, [idxBattler]) if Settings::RECALCULATE_TURN_ORDER_AFTER_MEGA_EVOLUTION
  end

  #=============================================================================
  # Primal Reverting a battler
  #=============================================================================
  def pbPrimalReversion(idxBattler)
    battler = @battlers[idxBattler]
    return if !battler || !battler.pokemon || battler.fainted?
    return if !battler.hasPrimal? || battler.primal?
    $stats.primal_reversion_count += 1 if battler.pbOwnedByPlayer?
    if battler.isSpecies?(:KYOGRE)
      pbCommonAnimation("PrimalKyogre", battler)
    elsif battler.isSpecies?(:GROUDON)
      pbCommonAnimation("PrimalGroudon", battler)
    end
    battler.pokemon.makePrimal
    battler.form = battler.pokemon.form
    battler.pbUpdate(true)
    @scene.pbChangePokemon(battler, battler.pokemon)
    @scene.pbRefreshOne(idxBattler)
    if battler.isSpecies?(:KYOGRE)
      pbCommonAnimation("PrimalKyogre2", battler)
    elsif battler.isSpecies?(:GROUDON)
      pbCommonAnimation("PrimalGroudon2", battler)
    end
    pbDisplay(_INTL("¡{1} ha experimentado una Regresión Primigenia y ha recobrado su apariencia primitiva!", battler.pbThis))
  end
end


==============================================================================
# Script: Battle_CommandPhase
==============================================================================
class Battle
  #=============================================================================
  # Clear commands
  #=============================================================================
  def pbClearChoice(idxBattler)
    @choices[idxBattler] = [] if !@choices[idxBattler]
    @choices[idxBattler][0] = :None
    @choices[idxBattler][1] = 0
    @choices[idxBattler][2] = nil
    @choices[idxBattler][3] = -1
  end

  def pbCancelChoice(idxBattler)
    # If idxBattler's choice was to use an item, return that item to the Bag
    if @choices[idxBattler][0] == :UseItem
      item = @choices[idxBattler][1]
      pbReturnUnusedItemToBag(item, idxBattler) if item
    end
    # If idxBattler chose to Mega Evolve, cancel it
    pbUnregisterMegaEvolution(idxBattler)
    # Clear idxBattler's choice
    pbClearChoice(idxBattler)
  end

  #=============================================================================
  # Use main command menu (Fight/Pokémon/Bag/Run)
  #=============================================================================
  def pbCommandMenu(idxBattler, firstAction)
    return @scene.pbCommandMenu(idxBattler, firstAction)
  end

  #=============================================================================
  # Check whether actions can be taken
  #=============================================================================
  def pbCanShowCommands?(idxBattler)
    battler = @battlers[idxBattler]
    return false if !battler || battler.fainted?
    return false if battler.effects[PBEffects::Commanding] >= 0
    return false if battler.usingMultiTurnAttack?
    return true
  end

  def pbCanShowFightMenu?(idxBattler)
    battler = @battlers[idxBattler]
    # Encore
    return false if battler.effects[PBEffects::Encore] > 0
    # No moves that can be chosen (will Struggle instead)
    usable = false
    battler.eachMoveWithIndex do |_m, i|
      next if !pbCanChooseMove?(idxBattler, i, false)
      usable = true
      break
    end
    return usable
  end

  #=============================================================================
  # Use sub-menus to choose an action, and register it if is allowed
  #=============================================================================
  # Returns true if a choice was made, false if cancelled.
  def pbFightMenu(idxBattler)
    # Auto-use Encored move or no moves choosable, so auto-use Struggle
    return pbAutoChooseMove(idxBattler) if !pbCanShowFightMenu?(idxBattler)
    # Battle Palace only
    return true if pbAutoFightMenu(idxBattler)
    # Regular move selection
    ret = false
    @scene.pbFightMenu(idxBattler, pbCanMegaEvolve?(idxBattler)) do |cmd|
      case cmd
      when -1   # Cancel
      when -2   # Toggle Mega Evolution
        pbToggleRegisteredMegaEvolution(idxBattler)
        next false
      when -3   # Shift
        pbUnregisterMegaEvolution(idxBattler)
        pbRegisterShift(idxBattler)
        ret = true
      else      # Chose a move to use
        next false if cmd < 0 || !@battlers[idxBattler].moves[cmd] ||
                      !@battlers[idxBattler].moves[cmd].id
        next false if !pbRegisterMove(idxBattler, cmd)
        next false if !singleBattle? &&
                      !pbChooseTarget(@battlers[idxBattler], @battlers[idxBattler].moves[cmd])
        ret = true
      end
      next true
    end
    return ret
  end

  def pbAutoFightMenu(idxBattler); return false; end

  def pbChooseTarget(battler, move)
    target_data = move.pbTarget(battler)
    idxTarget = @scene.pbChooseTarget(battler.index, target_data)
    return false if idxTarget < 0
    pbRegisterTarget(battler.index, idxTarget)
    return true
  end

  def pbItemMenu(idxBattler, firstAction)
    if !@internalBattle
      pbDisplay(_INTL("Aquí no se pueden usar objetos."))
      return false
    end
    ret = false
    @scene.pbItemMenu(idxBattler, firstAction) do |item, useType, idxPkmn, idxMove, itemScene|
      next false if !item
      battler = pkmn = nil
      case useType
      when 1, 2   # Use on Pokémon/Pokémon's move
        next false if !ItemHandlers.hasBattleUseOnPokemon(item)
        battler = pbFindBattler(idxPkmn, idxBattler)
        pkmn    = pbParty(idxBattler)[idxPkmn]
        next false if !pbCanUseItemOnPokemon?(item, pkmn, battler, itemScene)
      when 3   # Use on battler
        next false if !ItemHandlers.hasBattleUseOnBattler(item)
        battler = pbFindBattler(idxPkmn, idxBattler)
        pkmn    = battler.pokemon if battler
        next false if !pbCanUseItemOnPokemon?(item, pkmn, battler, itemScene)
      when 4   # Poké Balls
        next false if idxPkmn < 0
        battler = @battlers[idxPkmn]
        pkmn    = battler.pokemon if battler
      when 5   # No target (Poké Doll, Guard Spec., Launcher items)
        battler = @battlers[idxBattler]
        pkmn    = battler.pokemon if battler
      else
        next false
      end
      next false if !pkmn
      next false if !ItemHandlers.triggerCanUseInBattle(item, pkmn, battler, idxMove,
                                                        firstAction, self, itemScene)
      next false if !pbRegisterItem(idxBattler, item, idxPkmn, idxMove)
      ret = true
      next true
    end
    return ret
  end

  def pbPartyMenu(idxBattler)
    ret = -1
    if @debug
      ret = @battleAI.pbDefaultChooseNewEnemy(idxBattler)
    else
      ret = pbPartyScreen(idxBattler, false, true, true)
    end
    battler = @battlers[idxBattler]
    @battlers[idxBattler].refresh_moves if !battler.effects[PBEffects::Transform]
    return ret >= 0
  end

  def pbRunMenu(idxBattler)
    # Regardless of succeeding or failing to run, stop choosing actions
    return pbRun(idxBattler) != 0
  end

  def pbCallMenu(idxBattler)
    return pbRegisterCall(idxBattler)
  end

  def pbDebugMenu
    pbBattleDebug(self)
    @scene.pbRefreshEverything
    allBattlers(true).each { |b| b.pbCheckFormOnWeatherChange }
    allBattlers(true).each { |b| b.pbCheckFormOnTerrainChange }
    pbEndPrimordialWeather
    allBattlers(true).each { |b| b.pbAbilityOnWeatherChange(@field.weather) }
    allBattlers(true).each { |b| b.pbAbilityOnTerrainChange(@field.terrain) }
    allBattlers(true).each do |b|
      b.pbCheckFormOnMovesetChange
      b.pbCheckFormOnStatusChange
    end
  end

  #=============================================================================
  # Command phase
  #=============================================================================
  def pbCommandPhase
    @command_phase = true
    @scene.pbBeginCommandPhase
    # Reset choices if commands can be shown
    @battlers.each_with_index do |b, i|
      next if !b
      pbClearChoice(i) if pbCanShowCommands?(i)
    end
    # Reset choices to perform Mega Evolution if it wasn't done somehow
    2.times do |side|
      @megaEvolution[side].each_with_index do |megaEvo, i|
        @megaEvolution[side][i] = -1 if megaEvo >= 0
      end
    end
    # Choose actions for the round (player first, then AI)
    pbCommandPhaseLoop(true)    # Player chooses their actions
    if decided?   # Battle ended, stop choosing actions
      @command_phase = false
      return
    end
    pbCommandPhaseLoop(false)   # AI chooses their actions
    @command_phase = false
  end

  def pbCommandPhaseLoop(isPlayer)
    # NOTE: Doing some things (e.g. running, throwing a Poké Ball) takes up all
    #       your actions in a round.
    actioned = []
    idxBattler = -1
    loop do
      break if decided?   # Battle ended, stop choosing actions
      idxBattler += 1
      break if idxBattler >= @battlers.length
      next if !@battlers[idxBattler] || pbOwnedByPlayer?(idxBattler) != isPlayer
      next if @battlers[idxBattler].effects[PBEffects::Commanding] >= 0
      if @choices[idxBattler][0] != :None || !pbCanShowCommands?(idxBattler)
        # Action is forced, can't choose one
        PBDebug.log("[Command phase] #{@battlers[idxBattler].pbThis} (#{idxBattler}) is forced to use a multi-turn move")
        next
      end
      # AI controls this battler
      if @controlPlayer || !pbOwnedByPlayer?(idxBattler)
        @battleAI.pbDefaultChooseEnemyCommand(idxBattler)
        next
      end
      # Player chooses an action
      actioned.push(idxBattler)
      commandsEnd = false   # Whether to cancel choosing all other actions this round
      loop do
        cmd = pbCommandMenu(idxBattler, actioned.length == 1)
        # If being Sky Dropped, can't do anything except use a move
        if cmd > 0 && @battlers[idxBattler].effects[PBEffects::SkyDrop] >= 0
          pbDisplay(_INTL("¡Caída Libre no deja cambiar a {1}!", @battlers[idxBattler].pbThis(true)))
          next
        end
        case cmd
        when 0    # Fight
          break if pbFightMenu(idxBattler)
        when 1    # Bag
          if pbItemMenu(idxBattler, actioned.length == 1)
            commandsEnd = true if pbItemUsesAllActions?(@choices[idxBattler][1])
            break
          end
        when 2    # Pokémon
          break if pbPartyMenu(idxBattler)
        when 3    # Run
          # NOTE: "Run" is only an available option for the first battler the
          #       player chooses an action for in a round. Attempting to run
          #       from battle prevents you from choosing any other actions in
          #       that round.
          if pbRunMenu(idxBattler)
            commandsEnd = true
            break
          end
        when 4    # Call
          break if pbCallMenu(idxBattler)
        when -2   # Debug
          pbDebugMenu
          next
        when -1   # Go back to previous battler's action choice
          next if actioned.length <= 1
          actioned.pop   # Forget this battler was done
          idxBattler = actioned.last - 1
          pbCancelChoice(idxBattler + 1)   # Clear the previous battler's choice
          actioned.pop   # Forget the previous battler was done
          break
        end
        pbCancelChoice(idxBattler)
      end
      break if commandsEnd
    end
  end
end

==============================================================================
# Script: Battle_AttackPhase
==============================================================================
class Battle
  #=============================================================================
  # Attack phase actions
  #=============================================================================
  # Quick Claw, Custap Berry's "X let it move first!" message.
  def pbAttackPhasePriorityChangeMessages
    pbPriority.each do |b|
      if b.effects[PBEffects::PriorityAbility] && b.abilityActive?
        Battle::AbilityEffects.triggerPriorityBracketUse(b.ability, b, self)
      elsif b.effects[PBEffects::PriorityItem] && b.itemActive?
        Battle::ItemEffects.triggerPriorityBracketUse(b.item, b, self)
      end
    end
  end

  def pbAttackPhaseCall
    pbPriority.each do |b|
      next unless @choices[b.index][0] == :Call && !b.fainted?
      b.lastMoveFailed = false   # Counts as a successful move for Stomping Tantrum
      pbCall(b.index)
    end
  end

  def pbPursuit(idxSwitcher)
    @switching = true
    pbPriority.each do |b|
      next if b.fainted? || !b.opposes?(idxSwitcher)   # Shouldn't hit an ally
      next if b.movedThisRound? || !pbChoseMoveFunctionCode?(b.index, "PursueSwitchingFoe")
      # Check whether Pursuit can be used
      next unless pbMoveCanTarget?(b.index, idxSwitcher, @choices[b.index][2].pbTarget(b))
      next unless pbCanChooseMove?(b.index, @choices[b.index][1], false)
      next if b.status == :SLEEP || b.status == :FROZEN
      next if b.effects[PBEffects::SkyDrop] >= 0
      next if b.hasActiveAbility?(:TRUANT) && b.effects[PBEffects::Truant]
      # Mega Evolve
      if !b.wild?
        owner = pbGetOwnerIndexFromBattlerIndex(b.index)
        pbMegaEvolve(b.index) if @megaEvolution[b.idxOwnSide][owner] == b.index
      end
      # Use Pursuit
      @choices[b.index][3] = idxSwitcher   # Change Pursuit's target
      b.pbProcessTurn(@choices[b.index], false)
      break if decided? || @battlers[idxSwitcher].fainted?
    end
    @switching = false
  end

  def pbAttackPhaseSwitch
    clearStagesChangeRecords
    pbPriority.each do |b|
      next unless @choices[b.index][0] == :SwitchOut && !b.fainted?
      idxNewPkmn = @choices[b.index][1]   # Party index of Pokémon to switch to
      b.lastMoveFailed = false   # Counts as a successful move for Stomping Tantrum
      @lastMoveUser = b.index
      # Switching message
      pbMessageOnRecall(b)
      # Pursuit interrupts switching
      pbPursuit(b.index)
      return if decided?
      # Switch Pokémon
      allBattlers(true).each do |b2|
        b2.droppedBelowHalfHP = false
        b2.droppedBelowThirdHP = false
        b2.statsDropped = false
      end
      pbRecallAndReplace(b.index, idxNewPkmn)
      pbOnBattlerEnteringBattle(b.index, true)
    end
  end

  def pbAttackPhaseItems
    clearStagesChangeRecords
    pbPriority.each do |b|
      next unless @choices[b.index][0] == :UseItem && !b.fainted?
      b.lastMoveFailed = false   # Counts as a successful move for Stomping Tantrum
      item = @choices[b.index][1]
      next if !item
      case GameData::Item.get(item).battle_use
      when 1, 2   # Use on Pokémon/Pokémon's move
        pbUseItemOnPokemon(item, @choices[b.index][2], b) if @choices[b.index][2] >= 0
      when 3      # Use on battler
        pbUseItemOnBattler(item, @choices[b.index][2], b)
      when 4      # Use Poké Ball
        pbUsePokeBallInBattle(item, @choices[b.index][2], b)
      when 5      # Use directly
        pbUseItemInBattle(item, @choices[b.index][2], b)
      else
        next
      end
      return if decided?
    end
    checkStatChangeResponses
    pbCalculatePriority if Settings::RECALCULATE_TURN_ORDER_AFTER_SPEED_CHANGES
  end

  def pbAttackPhaseMegaEvolution
    clearStagesChangeRecords
    pbPriority.each do |b|
      next if b.wild?
      next unless @choices[b.index][0] == :UseMove && !b.fainted?
      owner = pbGetOwnerIndexFromBattlerIndex(b.index)
      next if @megaEvolution[b.idxOwnSide][owner] != b.index
      pbMegaEvolve(b.index)
    end
    checkStatChangeResponses
  end

  def pbAttackPhaseMoves
    # Show charging messages (Focus Punch)
    pbPriority.each do |b|
      next unless @choices[b.index][0] == :UseMove && !b.fainted?
      next if b.movedThisRound?
      @choices[b.index][2].pbDisplayChargeMessage(b)
    end
    # Main move processing loop
    loop do
      priority = pbPriority
      # Forced to go next
      advance = false
      priority.each do |b|
        next unless b.effects[PBEffects::MoveNext] && !b.fainted?
        next unless @choices[b.index][0] == :UseMove || @choices[b.index][0] == :Shift
        next if b.movedThisRound?
        advance = b.pbProcessTurn(@choices[b.index])
        break if advance
      end
      return if decided?
      next if advance
      # Regular priority order
      priority.each do |b|
        next if b.effects[PBEffects::Quash] > 0 || b.fainted?
        next unless @choices[b.index][0] == :UseMove || @choices[b.index][0] == :Shift
        next if b.movedThisRound?
        advance = b.pbProcessTurn(@choices[b.index])
        break if advance
      end
      return if decided?
      next if advance
      # Quashed
      if Settings::MECHANICS_GENERATION >= 8
        priority.each do |b|
          next unless b.effects[PBEffects::Quash] > 0 && !b.fainted?
          next unless @choices[b.index][0] == :UseMove || @choices[b.index][0] == :Shift
          next if b.movedThisRound?
          advance = b.pbProcessTurn(@choices[b.index])
          break if advance
        end
      else
        quashLevel = 0
        loop do
          quashLevel += 1
          moreQuash = false
          priority.each do |b|
            moreQuash = true if b.effects[PBEffects::Quash] > quashLevel
            next unless b.effects[PBEffects::Quash] == quashLevel && !b.fainted?
            next unless @choices[b.index][0] == :UseMove || @choices[b.index][0] == :Shift
            next if b.movedThisRound?
            advance = b.pbProcessTurn(@choices[b.index])
            break
          end
          break if advance || !moreQuash
        end
      end
      return if decided?
      next if advance
      # Check for all done
      priority.each do |b|
        next if b.fainted?
        next if b.movedThisRound? || ![:UseMove, :Shift].include?(@choices[b.index][0])
        advance = true
        break
      end
      next if advance
      # All Pokémon have moved; end the loop
      break
    end
  end

  #=============================================================================
  # Attack phase
  #=============================================================================
  def pbAttackPhase
    @scene.pbBeginAttackPhase
    # Reset certain effects
    @battlers.each_with_index do |b, i|
      next if !b
      b.turnCount += 1 if !b.fainted? && b.effects[PBEffects::Commanding] < 0
      @successStates[i].clear
      if ![:UseMove, :Shift, :SwitchOut].include?(@choices[i][0])
        b.effects[PBEffects::DestinyBond] = false
        b.effects[PBEffects::Grudge]      = false
      end
      b.effects[PBEffects::Rage] = false if !pbChoseMoveFunctionCode?(i, "StartRaiseUserAtk1WhenDamaged")
    end
    # Calculate move order for this round
    pbCalculatePriority(true)
    PBDebug.log("")
    # Perform actions
    pbAttackPhasePriorityChangeMessages
    pbAttackPhaseCall
    pbAttackPhaseSwitch
    return if decided?
    pbAttackPhaseItems
    return if decided?
    pbAttackPhaseMegaEvolution
    pbAttackPhaseMoves
  end
end

==============================================================================
# Script: Battle_EndOfRoundPhase
==============================================================================
class Battle
  #=============================================================================
  # End Of Round end weather check and weather effects
  #=============================================================================
  def pbEOREndWeather(priority)
    # NOTE: Primordial weather doesn't need to be checked here, because if it
    #       could wear off here, it will have worn off already.
    # Count down weather duration
    @field.weatherDuration -= 1 if @field.weatherDuration > 0
    # Weather wears off
    if @field.weather != :None && @field.weatherDuration == 0
      pbEndWeather
      # Start up the default weather
      pbStartWeather(nil, @field.defaultWeather, false) if @field.defaultWeather != :None
      return if @field.weather == :None
    end
    # Weather continues
    weather_data = GameData::BattleWeather.try_get(@field.weather)
    pbCommonAnimation(weather_data.animation) if weather_data
    case @field.weather
    when :Sun         then pbDisplay(_INTL("El sol pega fuerte."))
    when :Rain        then pbDisplay(_INTL("Sigue lloviendo."))
    when :Sandstorm   then pbDisplay(_INTL("La tormenta de arena arrecia."))
    when :Hail        then pbDisplay(_INTL("Sigue granizando."))
    when :Snowstorm   then pbDisplay(_INTL("Sigue nevando."))
    when :HarshSun    then pbDisplay(_INTL("El sol es realmente abrasador."))
    when :HeavyRain   then pbDisplay(_INTL("La lluvia está siendo muy intensa."))
    when :StrongWinds then pbDisplay(_INTL("El aire está lleno de turbulencias."))
    when :ShadowSky   then pbDisplay(_INTL("El cielo está muy oscuro."))
    end
    # Effects due to weather
    priority.each do |battler|
      # Weather-related abilities
      if battler.abilityActive?
        Battle::AbilityEffects.triggerEndOfRoundWeather(battler.ability, battler.effectiveWeather, battler, self)
        battler.pbFaint if battler.fainted?
      end
      # Weather damage
      pbEORWeatherDamage(battler)
    end
  end

  def pbEORWeatherDamage(battler)
    return if battler.fainted?
    amt = -1
    case battler.effectiveWeather
    when :Sandstorm
      return if !battler.takesSandstormDamage?
      pbDisplay(_INTL("¡La tormenta de arena zarandea a {1}!", battler.pbThis(true)))
      amt = battler.totalhp / 16
    when :Hail
      return if !battler.takesHailDamage?
      pbDisplay(_INTL("¡El granizo golpea a {1}!", battler.pbThis(true)))
      amt = battler.totalhp / 16
    when :ShadowSky
      return if !battler.takesShadowSkyDamage?
      pbDisplay(_INTL("¡El cielo sombrío daña a {1}!", battler.pbThis(true)))
      amt = battler.totalhp / 16
    end
    return if amt < 0
    @scene.pbDamageAnimation(battler)
    battler.pbReduceHP(amt, false)
    battler.pbItemHPHealCheck
    battler.pbFaint if battler.fainted?
  end

  #=============================================================================
  # End Of Round use delayed moves (Future Sight, Doom Desire)
  #=============================================================================
  def pbEORUseFutureSight(position, position_index)
    return if !position || position.effects[PBEffects::FutureSightCounter] == 0
    position.effects[PBEffects::FutureSightCounter] -= 1
    return if position.effects[PBEffects::FutureSightCounter] > 0
    return if !@battlers[position_index] || @battlers[position_index].fainted? ||
              @battlers[position_index].effects[PBEffects::Commanding] >= 0   # No target
    moveUser = nil
    allBattlers(true).each do |battler|
      next if battler.opposes?(position.effects[PBEffects::FutureSightUserIndex])
      next if battler.pokemonIndex != position.effects[PBEffects::FutureSightUserPartyIndex]
      moveUser = battler
      break
    end
    return if moveUser && moveUser.index == position_index   # Target is the user
    if !moveUser   # User isn't in battle, get it from the party
      party = pbParty(position.effects[PBEffects::FutureSightUserIndex])
      pkmn = party[position.effects[PBEffects::FutureSightUserPartyIndex]]
      if pkmn&.able?
        moveUser = Battler.new(self, position.effects[PBEffects::FutureSightUserIndex])
        moveUser.pbInitDummyPokemon(pkmn, position.effects[PBEffects::FutureSightUserPartyIndex])
      end
    end
    return if !moveUser   # User is fainted
    move = position.effects[PBEffects::FutureSightMove]
    pbDisplay(_INTL("¡{1} ha sido alcanzado por {2}!", @battlers[position_index].pbThis,
                    GameData::Move.get(move).name))
    # NOTE: Future Sight failing against the target here doesn't count towards
    #       Stomping Tantrum.
    userLastMoveFailed = moveUser.lastMoveFailed
    @futureSight = true
    moveUser.pbUseMoveSimple(move, position_index)
    @futureSight = false
    moveUser.lastMoveFailed = userLastMoveFailed
    @battlers[position_index].pbFaint if @battlers[position_index].fainted?
    position.effects[PBEffects::FutureSightCounter]        = 0
    position.effects[PBEffects::FutureSightMove]           = nil
    position.effects[PBEffects::FutureSightUserIndex]      = -1
    position.effects[PBEffects::FutureSightUserPartyIndex] = -1
  end

  #=============================================================================
  # End Of Round healing from Wish
  #=============================================================================
  def pbEORWishHealing
    @positions.each_with_index do |pos, idxPos|
      next if !pos || pos.effects[PBEffects::Wish] == 0
      pos.effects[PBEffects::Wish] -= 1
      next if pos.effects[PBEffects::Wish] > 0
      next if !@battlers[idxPos] || !@battlers[idxPos].canHeal?
      wishMaker = pbThisEx(idxPos, pos.effects[PBEffects::WishMaker])
      @battlers[idxPos].pbRecoverHP(pos.effects[PBEffects::WishAmount])
      pbDisplay(_INTL("¡El deseo de {1} se ha hecho realidad!", wishMaker))
    end
  end

  #=============================================================================
  # End Of Round Sea of Fire damage (Fire Pledge + Grass Pledge combination)
  #=============================================================================
  def pbEORSeaOfFireDamage(priority)
    2.times do |side|
      next if sides[side].effects[PBEffects::SeaOfFire] == 0
      sides[side].effects[PBEffects::SeaOfFire] -= 1
      pbCommonAnimation("SeaOfFire") if side == 0
      pbCommonAnimation("SeaOfFireOpp") if side == 1
      priority.each do |battler|
        next if battler.opposes?(side)
        next if !battler.takesIndirectDamage? || battler.pbHasType?(:FIRE)
        @scene.pbDamageAnimation(battler)
        battler.pbTakeEffectDamage(battler.totalhp / 8, false) do |hp_lost|
          pbDisplay(_INTL("¡El mar de llamas ha dañado a {1}!", battler.pbThis(true)))
        end
      end
    end
  end

  #=============================================================================
  # End Of Round healing from Grassy Terrain
  #=============================================================================
  def pbEORTerrainHealing(battler)
    return if battler.fainted?
    # Grassy Terrain (healing)
    if @field.terrain == :Grassy && battler.affectedByTerrain? && battler.canHeal?
      PBDebug.log("[Lingering effect] Grassy Terrain heals #{battler.pbThis(true)}")
      battler.pbRecoverHP(battler.totalhp / 16)
      pbDisplay(_INTL("¡{1} ha recuperado PS!", battler.pbThis))
    end
  end

  #=============================================================================
  # End Of Round various healing effects
  #=============================================================================
  def pbEORHealingEffects(priority)
    # Aqua Ring
    priority.each do |battler|
      next if !battler.effects[PBEffects::AquaRing]
      next if !battler.canHeal?
      pbCommonAnimation("AquaRing", battler)
      hpGain = battler.totalhp / 16
      hpGain = (hpGain * 1.3).floor if battler.hasActiveItem?(:BIGROOT)
      battler.pbRecoverHP(hpGain)
      pbDisplay(_INTL("¡{1} ha recuperado algunos PS gracias al manto de agua que rodea su cuerpo!", battler.pbThis))
    end
    # Ingrain
    priority.each do |battler|
      next if !battler.effects[PBEffects::Ingrain]
      next if !battler.canHeal?
      pbCommonAnimation("Ingrain", battler)
      hpGain = battler.totalhp / 16
      hpGain = (hpGain * 1.3).floor if battler.hasActiveItem?(:BIGROOT)
      battler.pbRecoverHP(hpGain)
      pbDisplay(_INTL("¡{1} ha absorbido nutrientes gracias a sus raíces!", battler.pbThis))
    end
    # Leech Seed
    priority.each do |battler|
      next if battler.effects[PBEffects::LeechSeed] < 0
      next if !battler.takesIndirectDamage?
      recipient = @battlers[battler.effects[PBEffects::LeechSeed]]
      next if !recipient || recipient.fainted?
      pbCommonAnimation("LeechSeed", recipient, battler)
      battler.pbTakeEffectDamage(battler.totalhp / 8) do |hp_lost|
        recipient.pbRecoverHPFromDrain(hp_lost, battler,
                                       _INTL("¡Las drenadoras han restado salud a {1}!", battler.pbThis(true)))
        recipient.pbAbilitiesOnDamageTaken
      end
      recipient.pbFaint if recipient.fainted?
    end
  end

  #=============================================================================
  # End Of Round deal damage from status problems
  #=============================================================================
  def pbEORStatusProblemDamage(priority)
    # Damage from poisoning
    priority.each do |battler|
      next if battler.fainted?
      next if battler.status != :POISON
      if battler.statusCount > 0
        battler.effects[PBEffects::Toxic] += 1
        battler.effects[PBEffects::Toxic] = 16 if battler.effects[PBEffects::Toxic] > 16
      end
      if battler.hasActiveAbility?(:POISONHEAL)
        if battler.canHeal?
          anim_name = GameData::Status.get(:POISON).animation
          pbCommonAnimation(anim_name, battler) if anim_name
          pbShowAbilitySplash(battler)
          battler.pbRecoverHP(battler.totalhp / 8)
          if Scene::USE_ABILITY_SPLASH
            pbDisplay(_INTL("{1} ha recuperado PS.", battler.pbThis))
          else
            pbDisplay(_INTL("{1} ha recuperado PS gracias a {2}.", battler.pbThis, battler.abilityName))
          end
          pbHideAbilitySplash(battler)
        end
      elsif battler.takesIndirectDamage?
        battler.droppedBelowHalfHP = false
        battler.droppedBelowThirdHP = false
        dmg = battler.totalhp / 8
        dmg = battler.totalhp * battler.effects[PBEffects::Toxic] / 16 if battler.statusCount > 0
        battler.pbContinueStatus { battler.pbReduceHP(dmg, false) }
        battler.pbItemHPHealCheck
        battler.pbAbilitiesOnDamageTaken
        battler.pbFaint if battler.fainted?
        battler.droppedBelowHalfHP = false
        battler.droppedBelowThirdHP = false
      end
    end
    # Damage from burn
    priority.each do |battler|
      next if battler.status != :BURN || !battler.takesIndirectDamage?
      battler.droppedBelowHalfHP = false
      battler.droppedBelowThirdHP = false
      dmg = (Settings::MECHANICS_GENERATION >= 7) ? battler.totalhp / 16 : battler.totalhp / 8
      dmg = (dmg / 2.0).round if battler.hasActiveAbility?(:HEATPROOF)
      battler.pbContinueStatus { battler.pbReduceHP(dmg, false) }
      battler.pbItemHPHealCheck
      battler.pbAbilitiesOnDamageTaken
      battler.pbFaint if battler.fainted?
      battler.droppedBelowHalfHP = false
      battler.droppedBelowThirdHP = false
    end
    
    # Damage from frostbite
    priority.each do |battler|
      next if battler.status != :FROSTBITE || !battler.takesIndirectDamage?
      battler.droppedBelowHalfHP = false
      battler.droppedBelowThirdHP = false
      dmg = battler.totalhp / 16
      battler.pbContinueStatus { battler.pbReduceHP(dmg, false) }
      battler.pbItemHPHealCheck
      battler.pbAbilitiesOnDamageTaken
      battler.pbFaint if battler.fainted?
      battler.droppedBelowHalfHP = false
      battler.droppedBelowThirdHP = false
    end
  end

  #=============================================================================
  # End Of Round deal damage from effects (except by trapping)
  #=============================================================================
  def pbEOREffectDamage(priority)
    # Damage from sleep (Nightmare)
    priority.each do |battler|
      battler.effects[PBEffects::Nightmare] = false if !battler.asleep?
      next if !battler.effects[PBEffects::Nightmare] || !battler.takesIndirectDamage?

      pbCommonAnimation("Nightmare", battler)
      battler.pbTakeEffectDamage(battler.totalhp / 4) do |hp_lost|
        pbDisplay(_INTL("¡{1} está inmerso en una pesadilla!", battler.pbThis))
      end
    end
    # Curse
    priority.each do |battler|
      next if !battler.effects[PBEffects::Curse] || !battler.takesIndirectDamage?
      pbCommonAnimation("Curse", battler)
      battler.pbTakeEffectDamage(battler.totalhp / 4) do |hp_lost|
        pbDisplay(_INTL("¡{1} es víctima de una maldición!", battler.pbThis))
      end
    end
    
    # priority.each do |battler|
    #   next if battler.effects[PBEffects::Splinters] == 0 || !battler.takesIndirectDamage?
    #   pbCommonAnimation("Splinters", battler)
    #   battlerTypes = battler.pbTypes(true)
    #   splinterType = battler.effects[PBEffects::SplintersType] || :QMARKS
    #   effectiveness = [1, Effectiveness.calculate(splinterType, *battlerTypes)].max
    #   damage = ((((2.0 * battler.level / 5) + 2).floor * 25 * battler.attack / battler.defense).floor / 50).floor + 2
    #   damage *= effectiveness.to_f / Effectiveness::NORMAL_EFFECTIVE
    #   battler.pbTakeEffectDamage(damage) { |hp_lost|
    #     pbDisplay(_INTL("¡{1} es dañado por las astillas dentadas!", battler.pbThis))
    #   }
    # end
    priority.each do |battler|
      next if !battler.effects[PBEffects::SaltCure] || !battler.takesIndirectDamage?
      pbCommonAnimation("SaltCure", battler)
      fraction = (battler.pbHasType?(:STEEL) || battler.pbHasType?(:WATER)) ? 4 : 8
      battler.pbTakeEffectDamage(battler.totalhp / fraction) { |hp_lost|
        pbDisplay(_INTL("¡{1} es dañado por la salazón!", battler.pbThis))
      }
    end
  end

  #=============================================================================
  # End Of Round deal damage to trapped battlers
  #=============================================================================
  TRAPPING_MOVE_COMMON_ANIMATIONS = {
    :BIND        => "Bind",
    :CLAMP       => "Clamp",
    :FIRESPIN    => "FireSpin",
    :INFESTATION => "Infestation",
    :MAGMASTORM  => "MagmaStorm",
    :SANDTOMB    => "SandTomb",
    :WRAP        => "Wrap"
  }

  def pbEORTrappingDamage(battler)
    return if battler.fainted? || battler.effects[PBEffects::Trapping] == 0
    battler.effects[PBEffects::Trapping] -= 1
    move_name = GameData::Move.get(battler.effects[PBEffects::TrappingMove]).name
    if battler.effects[PBEffects::Trapping] == 0
      pbDisplay(_INTL("¡{1} se liberó de {2}!", battler.pbThis, move_name))
      return
    end
    anim = TRAPPING_MOVE_COMMON_ANIMATIONS[battler.effects[PBEffects::TrappingMove]] || "Wrap"
    pbCommonAnimation(anim, battler)
    return if !battler.takesIndirectDamage?
    hpLoss = (Settings::MECHANICS_GENERATION >= 6) ? battler.totalhp / 8 : battler.totalhp / 16
    if @battlers[battler.effects[PBEffects::TrappingUser]].hasActiveItem?(:BINDINGBAND)
      hpLoss = (Settings::MECHANICS_GENERATION >= 6) ? battler.totalhp / 6 : battler.totalhp / 8
    end
    @scene.pbDamageAnimation(battler)
    battler.pbTakeEffectDamage(hpLoss, false) do |hp_lost|
      pbDisplay(_INTL("¡{1} es dañado por {2}!", battler.pbThis, move_name))
    end
  end

  #-----------------------------------------------------------------------------
  # End Of Round end effects that apply to a battler.
  #-----------------------------------------------------------------------------

  def pbEORStatChanges(battler)
    # Octolock
    if !battler.fainted? && battler.effects[PBEffects::Octolock] >= 0
      pbCommonAnimation("Octolock", battler)
      battler.pbLowerStatStage(:DEFENSE, 1, nil) if battler.pbCanLowerStatStage?(:DEFENSE)
      battler.pbLowerStatStage(:SPECIAL_DEFENSE, 1, nil) if battler.pbCanLowerStatStage?(:SPECIAL_DEFENSE)
      battler.pbItemOnStatDropped
    end
    # Syrup Bomb
    if !battler.fainted? && battler.effects[PBEffects::SyrupBomb] > 0
      pbCommonAnimation("SyrupBomb", battler)
      battler.pbLowerStatStage(:SPEED, 1, nil) if battler.pbCanLowerStatStage?(:SPEED)
      battler.pbItemOnStatDropped
      battler.effects[PBEffects::SyrupBomb] -= 1
    end
  end

  def pbEORCountDownBattlerEffect(priority, effect)
    priority.each do |battler|
      next if battler.fainted? || battler.effects[effect] == 0
      battler.effects[effect] -= 1
      yield battler if block_given? && battler.effects[effect] == 0
    end
  end

  def pbEOREndBattlerEffects(priority)
    # Cud Chew
    pbEORCountDownBattlerEffect(priority, PBEffects::CudChewCounter) do |battler|
      if battler.effects[PBEffects::CudChewBerry] &&
         GameData::Item.get(battler.effects[PBEffects::CudChewBerry]).is_berry?
        item = battler.effects[PBEffects::CudChewBerry]
        item_name = GameData::Item.get(battler.effects[PBEffects::CudChewBerry]).name
        battler.setBelched
        pbDisplay(_INTL("{1} robó y comió la {2} de su objetivo!", battler.pbThis, item_name))
        battler.pbHeldItemTriggerCheck(item)
        battler.pbSymbiosis
      end
      battler.effects[PBEffects::CudChewBerry] = nil
    end
    # Taunt
    pbEORCountDownBattlerEffect(priority, PBEffects::Taunt) do |battler|
      pbDisplay(_INTL("¡{1} ya se ha olvidado de la mofa!", battler.pbThis))
    end
    # Encore
    priority.each do |battler|
      next if battler.fainted? || battler.effects[PBEffects::Encore] == 0
      idxEncoreMove = battler.pbEncoredMoveIndex
      if idxEncoreMove >= 0
        battler.effects[PBEffects::Encore] -= 1
        if battler.effects[PBEffects::Encore] == 0 || battler.moves[idxEncoreMove].pp == 0
          battler.effects[PBEffects::Encore] = 0
          pbDisplay(_INTL("¡{1} ya no sufre los efectos de Otra Vez!", battler.pbThis))
        end
      else
        PBDebug.log("[End of effect] #{battler.pbThis}'s encore ended (encored move no longer known)")
        battler.effects[PBEffects::Encore]     = 0
        battler.effects[PBEffects::EncoreMove] = nil
      end
    end
    # Disable/Cursed Body
    pbEORCountDownBattlerEffect(priority, PBEffects::Disable) do |battler|
      battler.effects[PBEffects::DisableMove] = nil
      pbDisplay(_INTL("¡El movimiento de {1} ya no está anulado!", battler.pbThis(true)))
    end
    # Magnet Rise
    pbEORCountDownBattlerEffect(priority, PBEffects::MagnetRise) do |battler|
      pbDisplay(_INTL("¡El campo electromagnético de {1} se ha disipado!", battler.pbThis(true)))
    end
    # Telekinesis
    pbEORCountDownBattlerEffect(priority, PBEffects::Telekinesis) do |battler|
      pbDisplay(_INTL("¡{1} se ha liberado de telequinesis!", battler.pbThis))
    end
    # Heal Block
    pbEORCountDownBattlerEffect(priority, PBEffects::HealBlock) do |battler|
      pbDisplay(_INTL("¡Se han pasado los efectos de Anticura en {1}!", battler.pbThis(true)))
    end
    # Embargo
    pbEORCountDownBattlerEffect(priority, PBEffects::Embargo) do |battler|
      pbDisplay(_INTL("¡{1} ya puede usar objetos de nuevo!", battler.pbThis))
      battler.pbItemOnWeatherChange(@field.weather)
      battler.pbItemOnTerrainChange(@field.terrain)
    end
    # Yawn
    pbEORCountDownBattlerEffect(priority, PBEffects::Yawn) do |battler|
      if battler.pbCanSleepYawn?
        PBDebug.log("[Lingering effect] #{battler.pbThis} fell asleep because of Yawn")
        battler.pbSleep
      end
    end
    # Perish Song
    perishSongUsers = []
    priority.each do |battler|
      next if battler.fainted? || battler.effects[PBEffects::PerishSong] == 0
      battler.effects[PBEffects::PerishSong] -= 1
      pbDisplay(_INTL("El contador de {1} bajó a {2}!", battler.pbThis(true), battler.effects[PBEffects::PerishSong]))
      if battler.effects[PBEffects::PerishSong] == 0
        perishSongUsers.push(battler.effects[PBEffects::PerishSongUser])
        battler.pbReduceHP(battler.hp)
      end
      battler.pbItemHPHealCheck
      battler.pbFaint if battler.fainted?
    end
    # Judge if all remaining Pokemon fainted by a Perish Song triggered by a single side
    if perishSongUsers.length > 0 &&
       ((perishSongUsers.find_all { |idxBattler| opposes?(idxBattler) }.length == perishSongUsers.length) ||
       (perishSongUsers.find_all { |idxBattler| !opposes?(idxBattler) }.length == perishSongUsers.length))
      pbJudgeCheckpoint(@battlers[perishSongUsers[0]])
    end
  end

  #-----------------------------------------------------------------------------
  # End Of Round end effects that apply to one side of the field.
  #-----------------------------------------------------------------------------

  def pbEORCountDownSideEffect(side, effect, msg)
    return if @sides[side].effects[effect] <= 0
    @sides[side].effects[effect] -= 1
    pbDisplay(msg) if @sides[side].effects[effect] == 0
  end

  def pbEOREndSideEffects(side, priority)
    # Reflect
    pbEORCountDownSideEffect(side, PBEffects::Reflect,
                             _INTL("El efecto de Reflejo en {1} se ha disipado.", @battlers[side].pbTeam(true)))
    # Light Screen
    pbEORCountDownSideEffect(side, PBEffects::LightScreen,
                             _INTL("El efecto de Pantalla de Luz en {1} se ha disipado.", @battlers[side].pbTeam(true)))
    # Safeguard
    pbEORCountDownSideEffect(side, PBEffects::Safeguard,
                             _INTL("El efecto de Velo Sagrado en {1} se ha disipado.", @battlers[side].pbTeam(true)))
    # Mist
    pbEORCountDownSideEffect(side, PBEffects::Mist,
                             _INTL("El efecto de Neblina en {1} se ha disipado.", @battlers[side].pbTeam(true)))
    # Tailwind
    pbEORCountDownSideEffect(side, PBEffects::Tailwind,
                             _INTL("Ha cesado el Viento Afín de {1}.", @battlers[side].pbTeam(true)))
    # Lucky Chant
    pbEORCountDownSideEffect(side, PBEffects::LuckyChant,
                             _INTL("El conjuro de {1} se ha desvanecido.", @battlers[side].pbTeam(true)))
    # Pledge Rainbow
    pbEORCountDownSideEffect(side, PBEffects::Rainbow,
                             _INTL("El arcoíris sobre {1} ha desaparecido.", @battlers[side].pbTeam(true)))
    # Pledge Sea of Fire
    pbEORCountDownSideEffect(side, PBEffects::SeaOfFire,
                             _INTL("El mar de llamas que rodeaba a {1} ha desaparecido.", @battlers[side].pbTeam(true)))
    # Pledge Swamp
    pbEORCountDownSideEffect(side, PBEffects::Swamp,
                             _INTL("El pantano que rodeaba a {1} ha desaparecido!", @battlers[side].pbTeam(true)))
    # Aurora Veil
    pbEORCountDownSideEffect(side, PBEffects::AuroraVeil,
                             _INTL("El efecto de Velo Aurora en {1} se ha disipado.", @battlers[side].pbTeam(true)))
  end

  #=============================================================================
  # End Of Round end effects that apply to the whole field
  #=============================================================================
  def pbEORCountDownFieldEffect(effect, msg)
    return if @field.effects[effect] <= 0
    @field.effects[effect] -= 1
    return if @field.effects[effect] > 0
    pbDisplay(msg)
    if effect == PBEffects::MagicRoom
      pbPriority(true, true).each do |battler|
        battler.pbItemOnWeatherChange(@field.weather)
        battler.pbItemOnTerrainChange(@field.terrain)
      end
    end
  end

  def pbEOREndFieldEffects(priority)
    # Trick Room
    pbEORCountDownFieldEffect(PBEffects::TrickRoom,
                              _INTL("Se han restaurado las dimensiones alteradas."))
    # Gravity
    pbEORCountDownFieldEffect(PBEffects::Gravity,
                              _INTL("La gravedad ha vuelto a su estado normal."))
    # Water Sport
    pbEORCountDownFieldEffect(PBEffects::WaterSportField,
                              _INTL("Los efectos de Hidrochorro han desaparecido."))
    # Mud Sport
    pbEORCountDownFieldEffect(PBEffects::MudSportField,
                              _INTL("Los efectos de Chapoteo Lodo han desaparecido."))
    # Wonder Room
    pbEORCountDownFieldEffect(PBEffects::WonderRoom,
                              _INTL("¡Los efectos de Zona Extraña sobre la Defensa y la Defensa Especial han desaparecido!"))
    # Magic Room
    pbEORCountDownFieldEffect(PBEffects::MagicRoom,
                              _INTL("Los efectos de Zona Mágica sobre los objetos han desaparecido."))
  end

  #=============================================================================
  # End Of Round end terrain check
  #=============================================================================
  def pbEOREndTerrain
    # Count down terrain duration
    @field.terrainDuration -= 1 if @field.terrainDuration > 0
    # Terrain wears off
    if @field.terrain != :None && @field.terrainDuration == 0
      pbEndTerrain
      # Start up the default terrain
      pbStartTerrain(nil, @field.defaultTerrain, false) if @field.defaultTerrain != :None
      return if @field.terrain == :None
    end
    # Terrain continues
    terrain_data = GameData::BattleTerrain.try_get(@field.terrain)
    pbCommonAnimation(terrain_data.animation) if terrain_data
    case @field.terrain
    when :Electric then pbDisplay(_INTL("¡Se ha formado un campo de corriente eléctrica en el terreno de combate!"))
    when :Grassy then pbDisplay(_INTL("¡El terreno de combate se ha cubierto de hierba!"))
    when :Misty then pbDisplay(_INTL("¡La niebla ha envuelto el terreno de combate!"))
    when :Psychic then pbDisplay(_INTL("¡El terreno de combate se ha vuelto muy extraño!"))
    end
  end

  #=============================================================================
  # End Of Round end self-inflicted effects on battler
  #=============================================================================
  def pbEOREndBattlerSelfEffects(battler)
    return if battler.fainted?
    # Hyper Mode (Shadow Pokémon)
    if battler.inHyperMode?
      if pbRandom(100) < 10
        battler.pokemon.hyper_mode = false
        pbDisplay(_INTL("¡{1} volvió en sí!", battler.pbThis))
      else
        pbDisplay(_INTL("¡{1} está imbuido de un poder salvaje!", battler.pbThis))
      end
    end
    # Uproar
    if battler.effects[PBEffects::Uproar] > 0
      battler.effects[PBEffects::Uproar] -= 1
      if battler.effects[PBEffects::Uproar] == 0
        pbDisplay(_INTL("{1} se ha calmado.", battler.pbThis))
      else
        pbDisplay(_INTL("¡{1} ha montado un alboroto!", battler.pbThis))
      end
    end
    # Slow Start's end message
    if battler.effects[PBEffects::SlowStart] > 0
      battler.effects[PBEffects::SlowStart] -= 1
      if battler.effects[PBEffects::SlowStart] == 0
        pbDisplay(_INTL("¡{1} finalmente actuó con su potencial!", battler.pbThis))
      end
    end
  end

  #-----------------------------------------------------------------------------
  # End Of Round shift distant battlers to middle positions.
  #-----------------------------------------------------------------------------

  def pbEORShiftDistantBattlers
    # Move battlers around if none are near to each other
    # NOTE: This code assumes each side has a maximum of 3 battlers on it, and
    #       is not generalised to larger side sizes.
    if !singleBattle?
      swaps = []   # Each element is an array of two battler indices to swap
      2.times do |side|
        next if pbSideSize(side) == 1   # Only battlers on sides of size 2+ need to move
        # Check if any battler on this side is near any battler on the other side
        anyNear = false
        allSameSideBattlers(side).each do |battler|
          anyNear = allOtherSideBattlers(battler).any? { |other| nearBattlers?(other.index, battler.index) }
          break if anyNear
        end
        break if anyNear
        # No battlers on this side are near any battlers on the other side; try
        # to move them
        # NOTE: If we get to here (assuming both sides are of size 3 or less),
        #       there is definitely only 1 able battler on this side, so we
        #       don't need to worry about multiple battlers trying to move into
        #       the same position. If you add support for a side of size 4+,
        #       this code will need revising to account for that, as well as to
        #       add more complex code to ensure battlers will end up near each
        #       other.
        allSameSideBattlers(side).each do |battler|
          # Get the position to move to
          pos = -1
          case pbSideSize(side)
          when 2 then pos = [2, 3, 0, 1][battler.index]   # The unoccupied position
          when 3 then pos = (side == 0) ? 2 : 3    # The centre position
          end
          next if pos < 0
          # Can't move if the same trainer doesn't control both positions
          idxOwner = pbGetOwnerIndexFromBattlerIndex(battler.index)
          next if pbGetOwnerIndexFromBattlerIndex(pos) != idxOwner
          swaps.push([battler.index, pos])
        end
      end
      # Move battlers around
      swaps.each do |pair|
        next if pbSideSize(pair[0]) == 2 && swaps.length > 1
        next if !pbSwapBattlers(pair[0], pair[1])
        case pbSideSize(pair[1])
        when 2
          pbDisplay(_INTL("¡{1} avanzó!", @battlers[pair[1]].pbThis))
        when 3
          pbDisplay(_INTL("¡{1} se movió al centro!", @battlers[pair[1]].pbThis))
        end
      end
    end
  end

  #=============================================================================
  # Main End Of Round phase method
  #=============================================================================
  def pbEndOfRoundPhase
    PBDebug.log("")
    PBDebug.log("[End of round #{@turnCount + 1}]")
    @endOfRound = true
    @scene.pbBeginEndOfRoundPhase
    clearStagesChangeRecords
    pbCalculatePriority                 # recalculate speeds
    priority = pbPriority(true, true)   # in order of fastest -> slowest speeds only
    # Weather
    pbEOREndWeather(priority)
    # Future Sight/Doom Desire
    @positions.each_with_index { |pos, idxPos| pbEORUseFutureSight(pos, idxPos) }
    # Wish
    pbEORWishHealing
    # Sea of Fire damage (Fire Pledge + Grass Pledge combination)
    pbEORSeaOfFireDamage(priority)
    # Status-curing effects/abilities and HP-healing items
    priority.each do |battler|
      pbEORTerrainHealing(battler)
      # Healer, Hydration, Shed Skin
      if battler.abilityActive?
        Battle::AbilityEffects.triggerEndOfRoundHealing(battler.ability, battler, self)
      end
      # Black Sludge, Leftovers
      if battler.itemActive?
        Battle::ItemEffects.triggerEndOfRoundHealing(battler.item, battler, self)
      end
    end
    # Self-curing of status due to affection
    if Settings::AFFECTION_EFFECTS && @internalBattle
      priority.each do |battler|
        next if battler.fainted? || battler.status == :NONE
        next if !battler.pbOwnedByPlayer? || battler.affection_level < 4 || battler.mega?
        next if pbRandom(100) < 80
        old_status = battler.status
        battler.pbCureStatus(false)
        case old_status
        when :SLEEP
          pbDisplay(_INTL("¡{1} se despertó para no decepcionarte!", battler.pbThis))
        when :POISON
          pbDisplay(_INTL("¡{1} logró expulsar el veneno para no decepcionarte!", battler.pbThis))
        when :BURN
          pbDisplay(_INTL("¡{1} curó su quemadura con su pura determinación para no decepcionarte!", battler.pbThis))
        when :PARALYSIS
          pbDisplay(_INTL("¡{1} reunió toda su energía para romper su parálisis para no decepcionarte!", battler.pbThis))
        when :FROZEN
          pbDisplay(_INTL("¡{1} derritió el hielo con su ardiente determinación para no decepcionarte!", battler.pbThis))
        end
      end
    end
    # Healing from Aqua Ring, Ingrain, Leech Seed
    pbEORHealingEffects(priority)
    # Damage from Hyper Mode (Shadow Pokémon)
    priority.each do |battler|
      next if !battler.inHyperMode? || @choices[battler.index][0] != :UseMove
      hpLoss = battler.totalhp / 24
      @scene.pbDamageAnimation(battler)
      battler.pbReduceHP(hpLoss, false)
      pbDisplay(_INTL("¡El poder salvaje hiere a {1}!", battler.pbThis(true)))
      battler.pbFaint if battler.fainted?
    end
    # Damage from poison/burn
    pbEORStatusProblemDamage(priority)
    # Damage from Nightmare and Curse
    pbEOREffectDamage(priority)
    # Trapping attacks (Bind/Clamp/Fire Spin/Magma Storm/Sand Tomb/Whirlpool/Wrap)
    priority.each { |battler| pbEORTrappingDamage(battler) }
    # Stat changes (Octolock, Syrup Bomb)
    priority.each { |battler| pbEORStatChanges(battler) }
    # Effects that apply to a battler that wear off after a number of rounds
    pbEOREndBattlerEffects(priority)
    # Check for end of battle (i.e. because of Perish Song)
    if decided?
      pbGainExp
      return
    end
    # Effects that apply to a side that wear off after a number of rounds
    2.times { |side| pbEOREndSideEffects(side, priority) }
    # Effects that apply to the whole field that wear off after a number of rounds
    pbEOREndFieldEffects(priority)
    # End of terrains
    pbEOREndTerrain
    priority.each do |battler|
      # Self-inflicted effects that wear off after a number of rounds
      pbEOREndBattlerSelfEffects(battler)
      # Bad Dreams, Moody, Speed Boost
      if battler.abilityActive?
        Battle::AbilityEffects.triggerEndOfRoundEffect(battler.ability, battler, self)
      end
      # Flame Orb, Sticky Barb, Toxic Orb
      if battler.itemActive?
        Battle::ItemEffects.triggerEndOfRoundEffect(battler.item, battler, self)
      end
      # Harvest, Pickup, Ball Fetch
      if battler.abilityActive?
        Battle::AbilityEffects.triggerEndOfRoundGainItem(battler.ability, battler, self)
      end
    end
    checkStatChangeResponses
    pbGainExp
    return if decided?
    # Form checks
    priority.each { |battler| battler.pbCheckForm(true) }
    # Switch Pokémon in if possible
    pbEORSwitch
    return if decided?
    # In battles with at least one side of size 3+, move battlers around if none
    # are near to any foes
    pbEORShiftDistantBattlers
    # Try to make Trace work, check for end of primordial weather
    priority.each { |battler| battler.pbContinualAbilityChecks }
    checkStatChangeResponses
    # Reset/count down battler-specific effects (no messages)
    allBattlers(true).each do |battler|
      battler.effects[PBEffects::BanefulBunker]    = false
      battler.effects[PBEffects::BurningBulwark]   = false
      battler.effects[PBEffects::Charge]           -= 1 if battler.effects[PBEffects::Charge] > 0
      battler.effects[PBEffects::Counter]          = -1
      battler.effects[PBEffects::CounterTarget]    = -1
      battler.effects[PBEffects::Electrify]        = false
      battler.effects[PBEffects::Endure]           = false
      battler.effects[PBEffects::FirstPledge]      = nil
      battler.effects[PBEffects::Flinch]           = false
      battler.effects[PBEffects::FocusPunch]       = false
      battler.effects[PBEffects::FollowMe]         = 0
      battler.effects[PBEffects::HelpingHand]      = false
      battler.effects[PBEffects::HyperBeam]        -= 1 if battler.effects[PBEffects::HyperBeam] > 0
      battler.effects[PBEffects::KingsShield]      = false
      battler.effects[PBEffects::LaserFocus]       -= 1 if battler.effects[PBEffects::LaserFocus] > 0
      if battler.effects[PBEffects::LockOn] > 0   # Also Mind Reader
        battler.effects[PBEffects::LockOn]         -= 1
        battler.effects[PBEffects::LockOnPos]      = -1 if battler.effects[PBEffects::LockOn] == 0
      end
      battler.effects[PBEffects::MagicBounce]      = false
      battler.effects[PBEffects::MagicCoat]        = false
      battler.effects[PBEffects::MirrorCoat]       = -1
      battler.effects[PBEffects::MirrorCoatTarget] = -1
      battler.effects[PBEffects::Obstruct]         = false
      battler.effects[PBEffects::Powder]           = false
      battler.effects[PBEffects::Prankster]        = false
      battler.effects[PBEffects::PriorityAbility]  = false
      battler.effects[PBEffects::PriorityItem]     = false
      battler.effects[PBEffects::Protect]          = false
      battler.effects[PBEffects::RagePowder]       = false
      battler.effects[PBEffects::Roost]            = false
      battler.effects[PBEffects::SilkTrap]         = false
      battler.effects[PBEffects::Snatch]           = 0
      battler.effects[PBEffects::SpikyShield]      = false
      battler.effects[PBEffects::Spotlight]        = 0
      battler.effects[PBEffects::ThroatChop]       -= 1 if battler.effects[PBEffects::ThroatChop] > 0
      battler.lastHPLost                           = 0
      battler.lastHPLostFromFoe                    = 0
      battler.droppedBelowHalfHP                   = false
      battler.droppedBelowThirdHP                  = false
      battler.statsDropped                         = false
      battler.tookMoveDamageThisRound              = false
      battler.tookDamageThisRound                  = false
      battler.tookPhysicalHit                      = false
      battler.statsRaisedThisRound                 = false
      battler.statsLoweredThisRound                = false
      battler.canRestoreIceFace                    = false
      battler.lastRoundMoveFailed                  = battler.lastMoveFailed
      battler.lastAttacker.clear
      battler.lastFoeAttacker.clear
      if Settings::MECHANICS_GENERATION >= 9
        battler.effects[PBEffects::Charge]   += 1 if battler.effects[PBEffects::Charge]     > 0
      end
      # battler.effects[PBEffects::GlaiveRush] -= 1 if battler.effects[PBEffects::GlaiveRush] > 0
      @scene.pbRefreshOne(battler.index)
    end
    # Reset/count down side-specific effects (no messages)
    2.times do |side|
      @sides[side].effects[PBEffects::CraftyShield]         = false
      if !@sides[side].effects[PBEffects::EchoedVoiceUsed]
        @sides[side].effects[PBEffects::EchoedVoiceCounter] = 0
      end
      @sides[side].effects[PBEffects::EchoedVoiceUsed]      = false
      @sides[side].effects[PBEffects::MatBlock]             = false
      @sides[side].effects[PBEffects::QuickGuard]           = false
      @sides[side].effects[PBEffects::Round]                = false
      @sides[side].effects[PBEffects::WideGuard]            = false
    end
    # Reset/count down field-specific effects (no messages)
    @field.effects[PBEffects::IonDeluge]   = false
    @field.effects[PBEffects::FairyLock]   -= 1 if @field.effects[PBEffects::FairyLock] > 0
    @field.effects[PBEffects::FusionBolt]  = false
    @field.effects[PBEffects::FusionFlare] = false
    @endOfRound = false
  end
end

