==============================================================================
# Script: Battle_Move
==============================================================================
#===============================================================================
#
#===============================================================================
class Battle::Move
  attr_reader   :battle
  attr_reader   :realMove
  attr_accessor :id
  attr_reader   :name
  attr_reader   :function_code
  attr_reader   :power
  attr_reader   :type
  attr_reader   :category
  attr_reader   :accuracy
  attr_accessor :pp
  attr_writer   :total_pp
  attr_reader   :addlEffect
  attr_reader   :target
  attr_reader   :priority
  attr_reader   :flags
  attr_accessor :calcType
  attr_accessor :powerBoost
  attr_accessor :snatched

  CRITICAL_HIT_RATIOS = (Settings::NEW_CRITICAL_HIT_RATE_MECHANICS) ? [24, 8, 2, 1] : [16, 8, 4, 3, 2]

  def to_int; return @id; end

  # @deprecated This method is slated to be removed in v22.
  def baseDamage
    Deprecation.warn_method("baseDamage", "v22", "power")
    return @power
  end

  #=============================================================================
  # Creating a move
  #=============================================================================
  def initialize(battle, move)
    @battle        = battle
    @realMove      = move
    @id            = move.id
    @name          = move.name   # Get the move's name
    # Get data on the move
    @function_code = move.function_code
    @power         = move.power
    @type          = move.type
    @category      = move.category
    @accuracy      = move.accuracy
    @pp            = move.pp   # Can be changed with Mimic/Transform
    @target        = move.target
    @priority      = move.priority
    @flags         = move.flags.clone
    @addlEffect    = move.effect_chance
    @powerBoost    = false   # For Aerilate, Pixilate, Refrigerate, Galvanize
    @snatched      = false
  end

  # This is the code actually used to generate a Battle::Move object. The
  # object generated is a subclass of this one which depends on the move's
  # function code.
  def self.from_pokemon_move(battle, move)
    validate move => Pokemon::Move
    code = move.function_code || "None"
    if code[/^\d/]   # Begins with a digit
      class_name = sprintf("Battle::Move::Effect%s", code)
    else
      class_name = sprintf("Battle::Move::%s", code)
    end
    if Object.const_defined?(class_name)
      return Object.const_get(class_name).new(battle, move)
    end
    return Battle::Move::Unimplemented.new(battle, move)
  end

  #-----------------------------------------------------------------------------
  # About the move.
  #-----------------------------------------------------------------------------

  def pbTarget(_user); return GameData::Target.get(@target); end

  def total_pp
    return @total_pp if @total_pp && @total_pp > 0   # Usually undefined
    return @realMove.total_pp if @realMove
    return 0
  end

  # NOTE: This method is only ever called while using a move (and also by the
  #       AI), so using @calcType here is acceptable.
  def physicalMove?(thisType = nil)
    return (@category == 0) if Settings::MOVE_CATEGORY_PER_MOVE
    thisType ||= @calcType
    thisType ||= @type
    return true if !thisType
    return GameData::Type.get(thisType).physical?
  end

  # NOTE: This method is only ever called while using a move (and also by the
  #       AI), so using @calcType here is acceptable.
  def specialMove?(thisType = nil)
    return (@category == 1) if Settings::MOVE_CATEGORY_PER_MOVE
    thisType ||= @calcType
    thisType ||= @type
    return false if !thisType
    return GameData::Type.get(thisType).special?
  end

  def damagingMove?; return @category != 2; end
  def statusMove?;   return @category == 2; end

  def pbPriority(user); return @priority; end

  def usableWhenAsleep?;            return false; end
  def unusableInGravity?;           return false; end
  def healingMove?;                 return false; end
  def recoilMove?;                  return false; end
  def flinchingMove?;               return false; end
  def callsAnotherMove?;            return false; end
  # Whether the move can/will hit more than once in the same turn (including
  # Beat Up which may instead hit just once). Not the same as pbNumHits>1.
  def multiHitMove?;                return false; end
  def chargingTurnMove?;            return false; end
  def successCheckPerHit?;          return false; end
  def hitsFlyingTargets?;           return false; end
  def hitsDiggingTargets?;          return false; end
  def hitsDivingTargets?;           return false; end
  def ignoresReflect?;              return false; end   # For Brick Break
  def targetsPosition?;             return false; end   # For Future Sight/Doom Desire
  def cannotRedirect?;              return false; end   # For Snipe Shot
  def worksWithNoTargets?;          return false; end   # For Explosion
  def damageReducedByBurn?;         return true;  end   # For Facade
  def triggersHyperMode?;           return false; end
  def canSnatch?;                   return false; end
  def canMagicCoat?;                return false; end
  def additionalEffectAffectsUser?; return false; end   # Shield Dust doesn't stop it if true

  def contactMove?;       return @flags.any? { |f| f[/^Contact$/i] };             end
  def canProtectAgainst?; return @flags.any? { |f| f[/^CanProtect$/i] };          end
  def canMirrorMove?;     return @flags.any? { |f| f[/^CanMirrorMove$/i] };       end
  def thawsUser?;         return @flags.any? { |f| f[/^ThawsUser$/i] };           end
  def highCriticalRate?;  return @flags.any? { |f| f[/^HighCriticalHitRate$/i] }; end
  def bitingMove?;        return @flags.any? { |f| f[/^Biting$/i] };              end
  def punchingMove?;      return @flags.any? { |f| f[/^Punching$/i] };            end
  def kickingMove?;       return @flags.any? { |f| f[/^Kicking$/i] };             end
  def soundMove?;         return @flags.any? { |f| f[/^Sound$/i] };               end
  def powderMove?;        return @flags.any? { |f| f[/^Powder$/i] };              end
  def pulseMove?;         return @flags.any? { |f| f[/^Pulse$/i] };               end
  def bombMove?;          return @flags.any? { |f| f[/^Bomb$/i] };                end
  def danceMove?;         return @flags.any? { |f| f[/^Dance$/i] };               end
  def slicingMove?;       return @flags.any? { |f| f[/^Slicing$/i] };             end
  def windMove?;          return @flags.any? { |f| f[/^Wind$/i] };                end
  # Causes perfect accuracy and double damage if target used Minimize. Perfect accuracy only with Gen 6+ mechanics.
  def tramplesMinimize?;  return @flags.any? { |f| f[/^TramplesMinimize$/i] };    end

  def nonLethal?(_user, _target); return false; end   # For False Swipe
  def preventsBattlerConsumingHealingBerry?(battler, targets); return false; end   # For Bug Bite/Pluck

  # user is the Pokémon using this move.
  def ignoresSubstitute?(user)
    if Settings::MECHANICS_GENERATION >= 6
      return true if soundMove?
      return true if user&.hasActiveAbility?(:INFILTRATOR)
    end
    return false
  end

  def display_type(battler)
    case @function_code
    when "TypeDependsOnUserMorpekoFormRaiseUserSpeed1"
      if battler.isSpecies?(:MORPEKO) || battler.effects[PBEffects::TransformSpecies] == :MORPEKO
        return pbBaseType(battler)
      end
    when "TypeDependsOnUserPlate", "TypeDependsOnUserMemory",
         "TypeDependsOnUserDrive", "TypeAndPowerDependOnUserBerry",
         "TypeIsUserFirstType", "TypeAndPowerDependOnWeather",
         "TypeAndPowerDependOnTerrain",
         "TypeIsUserSecondType",              # Ivy Cudgel
         "TypeIsUserSecondTypeRemoveScreens"  # Raging Bull
      return pbBaseType(battler) if Settings::SHOW_MODIFIED_MOVE_PROPERTIES
    end
    return @realMove.display_type(battler.pokemon)
  end

  def display_power(battler)
    if Settings::SHOW_MODIFIED_MOVE_PROPERTIES
      case @function_code
      when "TypeAndPowerDependOnUserBerry"
        return pbNaturalGiftBaseDamage(battler.item_id)
      when "TypeAndPowerDependOnWeather", "TypeAndPowerDependOnTerrain",
           "PowerHigherWithUserHP", "PowerLowerWithUserHP",
           "PowerHigherWithUserHappiness", "PowerLowerWithUserHappiness",
           "PowerHigherWithUserPositiveStatStages", "PowerDependsOnUserStockpile",
           "PowerHigherWithTimesHit", "PowerHigherWithFaintedAllies",
           "IncreasePowerInElectricTerrain", "DoublePowerIfUserPoisonedBurnedParalyzed",
           "DoublePowerIfUserHasNoItem", "DoublePowerIfUserLastMoveFailed",
           "DoublePowerIfAllyFaintedLastTurn"
        return pbBasePower(@power, battler, nil)
      end
    end
    return @realMove.display_power(battler.pokemon)
  end

  def display_category(battler)
    if Settings::SHOW_MODIFIED_MOVE_PROPERTIES
      case @function_code
      when "CategoryDependsOnHigherDamageIgnoreTargetAbility"
        pbOnStartUse(user, nil)
        return @calcCategory
      end
    end
    return @realMove.display_category(battler.pokemon)
  end

  def display_accuracy(battler); return @realMove.display_accuracy(battler.pokemon); end
end

==============================================================================
# Script: Move_Usage
==============================================================================
class Battle::Move
  #=============================================================================
  # Effect methods per move usage
  #=============================================================================
  def pbCanChooseMove?(user, commandPhase, showMessages); return true; end   # For Belch
  def pbDisplayChargeMessage(user); end   # For Focus Punch/shell Trap/Beak Blast
  def pbOnStartUse(user, targets); end
  def pbAddTarget(targets, user); end   # For Counter, etc. and Bide
  def pbModifyTargets(targets, user); end   # For Dragon Darts

  # Reset move usage counters (child classes can increment them).
  def pbChangeUsageCounters(user, specialUsage)
    user.effects[PBEffects::AllySwitchRate] = 1
    user.effects[PBEffects::FuryCutter]     = 0
    user.effects[PBEffects::GigatonHammer]  = false
    user.effects[PBEffects::ParentalBond]   = 0
    user.effects[PBEffects::ProtectRate]    = 1
    @battle.field.effects[PBEffects::FusionBolt]  = false
    @battle.field.effects[PBEffects::FusionFlare] = false
    user.pokemon.move_count_evolution(@id) if user.pbOwnedByPlayer?
  end

  def pbDisplayUseMessage(user)
    @battle.pbDisplayBrief(_INTL("¡{1} ha usado {2}!", user.pbThis, @name))
  end

  def pbShowFailMessages?(targets); return true; end
  def pbMissMessage(user, target); return false; end

  #=============================================================================
  #
  #=============================================================================
  # Whether the move is currently in the "charging" turn of a two-turn move.
  # Is false if Power Herb or another effect lets a two-turn move charge and
  # attack in the same turn.
  # user.effects[PBEffects::TwoTurnAttack] is set to the move's ID during the
  # charging turn, and is nil during the attack turn.
  def pbIsChargingTurn?(user); return false; end
  def pbDamagingMove?; return damagingMove?; end

  def pbContactMove?(user)
    return false if user.hasActiveAbility?(:LONGREACH)
    return false if punchingMove? && user.hasActiveItem?(:PUNCHINGGLOVE)
    return contactMove?
  end

  # The maximum number of hits in a round this move will actually perform. This
  # can be 1 for Beat Up, and can be 2 for any moves affected by Parental Bond.
  def pbNumHits(user, targets)
    if user.hasActiveAbility?(:PARENTALBOND) && pbDamagingMove? &&
       !chargingTurnMove? && targets.length == 1
      # Record that Parental Bond applies, to weaken the second attack
      user.effects[PBEffects::ParentalBond] = 3
      return 2
    end
    return 1
  end

  # For two-turn moves when they charge and attack in the same turn.
  def pbQuickChargingMove(user, targets); end

  #-----------------------------------------------------------------------------
  # Effect methods per hit.
  #-----------------------------------------------------------------------------

  def pbOverrideSuccessCheckPerHit(user, target); return false; end
  def pbCrashDamage(user); end
  def pbInitialEffect(user, targets, hitNum); end
  def pbDesignateTargetsForHit(targets, hitNum); return targets; end   # For Dragon Darts
  def pbRepeatHit?; return false; end   # For Dragon Darts

  def pbShowAnimation(id, user, targets, hitNum = 0, showAnimation = true)
    return if !showAnimation
    if user.effects[PBEffects::ParentalBond] == 1
      @battle.pbCommonAnimation("ParentalBond", user, targets)
    else
      @battle.pbAnimation(id, user, targets, hitNum)
    end
  end

  def pbSelfKO(user); end
  def pbEffectWhenDealingDamage(user, target); end
  def pbEffectAgainstTarget(user, target); end
  def pbEffectGeneral(user); end
  def pbAdditionalEffect(user, target); end
  def pbEffectAfterAllHits(user, target); end   # Move effects that occur after all hits
  def pbSwitchOutTargetEffect(user, targets, numHits, switched_battlers); end
  def pbEndOfMoveUsageEffect(user, targets, numHits, switchedBattlers); end

  #-----------------------------------------------------------------------------
  # Check if target is immune to the move because of its ability.
  #-----------------------------------------------------------------------------

  def pbImmunityByAbility(user, target, show_message)
    ret = false
    if target.abilityActive? && !target.beingMoldBroken?
      ret = Battle::AbilityEffects.triggerMoveImmunity(target.ability, user, target,
                                                       self, @calcType, @battle, show_message)
    end
    return ret
  end

  #-----------------------------------------------------------------------------
  # Move failure checks.
  #-----------------------------------------------------------------------------

  # Check whether the move fails completely due to move-specific requirements.
  def pbMoveFailed?(user, targets); return false; end
  # Checks whether the move will be ineffective against the target.
  def pbFailsAgainstTarget?(user, target, show_message); return false; end

  def pbMoveFailedLastInRound?(user, showMessage = true)
    unmoved = @battle.allBattlers.any? do |b|
      next b.index != user.index &&
           [:UseMove, :Shift].include?(@battle.choices[b.index][0]) &&
           !b.movedThisRound?
    end
    if !unmoved
      @battle.pbDisplay(_INTL("¡Pero ha fallado!")) if showMessage
      return true
    end
    return false
  end

  def pbMoveFailedTargetAlreadyMoved?(target, showMessage = true)
    if (@battle.choices[target.index][0] != :UseMove &&
       @battle.choices[target.index][0] != :Shift) || target.movedThisRound?
      @battle.pbDisplay(_INTL("¡Pero ha fallado!")) if showMessage
      return true
    end
    return false
  end

  def pbMoveFailedAromaVeil?(user, target, showMessage = true)
    if target.hasActiveAbility?(:AROMAVEIL) && !target.beingMoldBroken?
      if showMessage
        @battle.pbShowAbilitySplash(target)
        if Battle::Scene::USE_ABILITY_SPLASH
          @battle.pbDisplay(_INTL("No afecta a {1}...", target.pbThis(true)))
        else
          @battle.pbDisplay(_INTL("No afecta a {1} debido a {2}.",
                                  target.pbThis(true), target.abilityName))
        end
        @battle.pbHideAbilitySplash(target)
      end
      return true
    end
    target.allAllies.each do |b|
      next if !b.hasActiveAbility?(:AROMAVEIL) || b.beingMoldBroken?
      if showMessage
        @battle.pbShowAbilitySplash(b)
        if Battle::Scene::USE_ABILITY_SPLASH
          @battle.pbDisplay(_INTL("No afecta a {1}...", target.pbThis(true)))
        else
          @battle.pbDisplay(_INTL("No afecta a {1} debido a {2} de {3}.",
                                  target.pbThis(true), b.pbThis(true), b.abilityName))
        end
        @battle.pbHideAbilitySplash(b)
      end
      return true
    end
    return false
  end

  #-----------------------------------------------------------------------------
  # Weaken the damage dealt (doesn't actually change a battler's HP).
  #-----------------------------------------------------------------------------

  def pbCheckDamageAbsorption(user, target)
    # Substitute will take the damage
    if target.effects[PBEffects::Substitute] > 0 && !ignoresSubstitute?(user) &&
       (!user || user.index != target.index)
      target.damageState.substitute = true
      return
    end
    # Ice Face will take the damage
    if !target.beingMoldBroken? && target.isSpecies?(:EISCUE) &&
       target.form == 0 && target.ability == :ICEFACE && physicalMove?
      target.damageState.iceFace = true
      return
    end
    # Disguise will take the damage
    if !target.beingMoldBroken? && target.isSpecies?(:MIMIKYU) &&
       target.form == 0 && target.ability == :DISGUISE
      target.damageState.disguise = true
      return
    end
  end

  def pbReduceDamage(user, target)
    damage = target.damageState.calcDamage
    # Substitute takes the damage
    if target.damageState.substitute
      damage = target.effects[PBEffects::Substitute] if damage > target.effects[PBEffects::Substitute]
      target.damageState.hpLost       = damage
      target.damageState.totalHPLost += damage
      return
    end
    # Disguise/Ice Face takes the damage
    return if target.damageState.disguise || target.damageState.iceFace
    # Target takes the damage
    if damage >= target.hp
      damage = target.hp
      # Survive a lethal hit with 1 HP effects
      if nonLethal?(user, target)
        damage -= 1
      elsif target.effects[PBEffects::Endure]
        target.damageState.endured = true
        damage -= 1
      elsif target.hasActiveAbility?(:STURDY) && !target.beingMoldBroken? && target.hp == target.totalhp
        target.damageState.sturdy = true
        damage -= 1
      elsif target.hasActiveItem?(:FOCUSSASH) && target.hp == target.totalhp
        target.damageState.focusSash = true
        damage -= 1
      elsif target.hasActiveItem?(:FOCUSBAND) && @battle.pbRandom(100) < 10
        target.damageState.focusBand = true
        damage -= 1
      elsif Settings::AFFECTION_EFFECTS && @battle.internalBattle &&
            target.pbOwnedByPlayer? && !target.mega?
        chance = [0, 0, 0, 10, 15, 25][target.affection_level]
        if chance > 0 && @battle.pbRandom(100) < chance
          target.damageState.affection_endured = true
          damage -= 1
        end
      end
    end
    damage = 0 if damage < 0
    target.damageState.hpLost       = damage
    target.damageState.totalHPLost += damage
  end

  #-----------------------------------------------------------------------------
  # Change the target's HP by the amount calculated above.
  #-----------------------------------------------------------------------------

  def pbInflictHPDamage(target)
    if target.damageState.substitute
      target.effects[PBEffects::Substitute] -= target.damageState.hpLost
    elsif target.damageState.hpLost > 0
      target.pbReduceHP(target.damageState.hpLost, false, true, false)
    end
  end

  #-----------------------------------------------------------------------------
  # Animate the damage dealt, including lowering the HP.
  #-----------------------------------------------------------------------------

  # Animate being damaged and losing HP (by a move)
  def pbAnimateHitAndHPLost(user, targets)
    # Animate allies first, then foes
    animArray = []
    2.times do |side|   # side here means "allies first, then foes"
      targets.each do |b|
        next if b.damageState.unaffected || b.damageState.hpLost == 0
        next if (side == 0 && b.opposes?(user)) || (side == 1 && !b.opposes?(user))
        oldHP = b.hp
        if b.damageState.substitute
          old_sub_hp = b.effects[PBEffects::Substitute] + b.damageState.hpLost
          PBDebug.log("[Substitute HP change] #{b.pbThis}'s substitute lost #{b.damageState.hpLost} HP (#{old_sub_hp} -> #{b.effects[PBEffects::Substitute]})")
        else
          oldHP += b.damageState.hpLost
        end
        effectiveness = 0
        if !self.is_a?(Battle::Move::FixedDamageMove)
          if Effectiveness.resistant?(b.damageState.typeMod)
            effectiveness = 1
          elsif Effectiveness.super_effective?(b.damageState.typeMod)
            effectiveness = 2
          end
        end
        animArray.push([b, oldHP, effectiveness])
      end
      if animArray.length > 0
        @battle.scene.pbHitAndHPLossAnimation(animArray)
        animArray.clear
      end
    end
  end

  #-----------------------------------------------------------------------------
  # Messages upon being hit.
  #-----------------------------------------------------------------------------

  def pbEffectivenessMessage(user, target, numTargets = 1)
    return if self.is_a?(Battle::Move::FixedDamageMove)
    return if target.damageState.disguise || target.damageState.iceFace
    if Effectiveness.super_effective?(target.damageState.typeMod)
      if numTargets > 1
        @battle.pbDisplay(_INTL("¡Es supereficaz contra {1}!", target.pbThis(true)))
      else
        @battle.pbDisplay(_INTL("¡Es supereficaz!"))
      end
    elsif Effectiveness.not_very_effective?(target.damageState.typeMod)
      if numTargets > 1
        @battle.pbDisplay(_INTL("No es muy eficaz contra {1}...", target.pbThis(true)))
      else
        @battle.pbDisplay(_INTL("No es muy eficaz..."))
      end
    end
  end

  def pbHitEffectivenessMessages(user, target, numTargets = 1)
    return if target.damageState.disguise || target.damageState.iceFace
    if target.damageState.substitute
      @battle.pbDisplay(_INTL("El sustituto recibió el daño por {1}!", target.pbThis(true)))
    end
    if target.damageState.critical
      if user.pokemon.isSpecies?(:FARFETCHD) && user.pokemon.form == 1
        user.pokemon.evolution_counter += 1
      end
      crit_color = Battle::Scene::MESSAGE_BASE_CRITICAL_COLOR.to_rgb24 + "," + Battle::Scene::MESSAGE_SHADOW_CRITICAL_COLOR.to_rgb24
      if target.damageState.affection_critical
        if numTargets > 1
          @battle.pbDisplay(_INTL("{1} <c3={2}>asestó un golpe crítico</c3> a {3} para impresionarte!",
                                  user.pbThis, crit_color, target.pbThis(true)))
        else
          @battle.pbDisplay(_INTL("{1} <c3={2}>asestó un golpe crítico para impresionarte!</c3>", user.pbThis, crit_color))
        end
      elsif numTargets > 1
        @battle.pbDisplay(_INTL("¡<c3={1}>{2} recibió un golpe crítico!</c3>", crit_color, target.pbThis(true)))
      else
        @battle.pbDisplay(_INTL("<c3={1}>¡Un golpe crítico!</c3>", crit_color))
      end
    end
    # Effectiveness message, for moves with 1 hit
    if !multiHitMove? && user.effects[PBEffects::ParentalBond] == 0
      pbEffectivenessMessage(user, target, numTargets)
    end
    if target.damageState.substitute && target.effects[PBEffects::Substitute] == 0
      target.effects[PBEffects::Substitute] = 0
      @battle.pbDisplay(_INTL("¡El sustituto de {1} cayó!", target.pbThis))
    end
  end

  def pbEndureKOMessage(target)
    if target.damageState.disguise
      @battle.pbShowAbilitySplash(target)
      if Battle::Scene::USE_ABILITY_SPLASH
        @battle.pbDisplay(_INTL("¡El disfraz ha actuado como señuelo!"))
      else
        @battle.pbDisplay(_INTL("¡El disfraz de {1} ha actuado como señuelo!", target.pbThis(true)))
      end
      @battle.pbHideAbilitySplash(target)
      target.pbChangeForm(1, _INTL("¡El disfraz de {1} se ha roto!", target.pbThis(true)))
      target.pbReduceHP(target.totalhp / 8, false) if Settings::MECHANICS_GENERATION >= 8
    elsif target.damageState.iceFace
      @battle.pbShowAbilitySplash(target)
      if !Battle::Scene::USE_ABILITY_SPLASH
        @battle.pbDisplay(_INTL("¡Se activó {2} de {1}!", target.pbThis(true), target.abilityName))
      end
      target.pbChangeForm(1, _INTL("¡{1} se transformó!", target.pbThis))
      @battle.pbHideAbilitySplash(target)
    elsif target.damageState.endured
      @battle.pbDisplay(_INTL("¡{1} ha aguantado el golpe!", target.pbThis))
    elsif target.damageState.sturdy
      @battle.pbShowAbilitySplash(target)
      if Battle::Scene::USE_ABILITY_SPLASH
        @battle.pbDisplay(_INTL("¡{1} ha aguantado el golpe!", target.pbThis))
      else
        @battle.pbDisplay(_INTL("¡{1} aguantó con Robustez!", target.pbThis))
      end
      @battle.pbHideAbilitySplash(target)
    elsif target.damageState.focusSash
      @battle.pbCommonAnimation("UseItem", target)
      @battle.pbDisplay(_INTL("¡{1} ha usado la Banda Aguante y ha logrado resistir!", target.pbThis))
      target.pbConsumeItem
    elsif target.damageState.focusBand
      @battle.pbCommonAnimation("UseItem", target)
      @battle.pbDisplay(_INTL("¡{1} ha usado la Cinta Aguante y ha logrado resistir!", target.pbThis))
    elsif target.damageState.affection_endured
      @battle.pbDisplay(_INTL("¡{1} ha aguantado el golpe para impresionarte!", target.pbThis))
    end
  end

  # Used by Counter/Mirror Coat/Metal Burst/Revenge/Focus Punch/Bide/Assurance.
  def pbRecordDamageLost(user, target)
    damage = target.damageState.hpLost
    # NOTE: In Gen 3 where a move's category depends on its type, Hidden Power
    #       is for some reason countered by Counter rather than Mirror Coat,
    #       regardless of its calculated type. Hence the following two lines of
    #       code.
    moveType = nil
    moveType = :NORMAL if @function_code == "TypeDependsOnUserIVs"   # Hidden Power
    if !target.damageState.substitute
      if physicalMove?(moveType)
        target.effects[PBEffects::Counter]       = damage
        target.effects[PBEffects::CounterTarget] = user.index
      elsif specialMove?(moveType)
        target.effects[PBEffects::MirrorCoat]       = damage
        target.effects[PBEffects::MirrorCoatTarget] = user.index
      end
      if target.opposes?(user)
        target.lastHPLostFromFoe = damage                # For Metal Burst
        target.lastFoeAttacker.push(user.pokemonIndex)   # For Metal Burst
      end
    end
    if target.effects[PBEffects::Bide] > 0
      target.effects[PBEffects::BideDamage] += damage
      target.effects[PBEffects::BideTarget] = user.index
    end
    target.damageState.fainted = true if target.fainted?
    target.lastHPLost = damage
    target.tookMoveDamageThisRound = true if damage > 0 && !target.damageState.substitute   # For Focus Punch
    target.tookDamageThisRound = true if damage > 0   # For Assurance
    target.lastAttacker.push(user.index)              # For Revenge
    if target.pokemon.isSpecies?(:YAMASK) && target.pokemon.form == 1
      target.pokemon.evolution_counter += damage
    end
  end
end

==============================================================================
# Script: Move_UsageCalculations
==============================================================================
class Battle::Move
  #=============================================================================
  # Move's type calculation
  #=============================================================================
  def pbBaseType(user)
    ret = @type
    if ret && user.abilityActive?
      ret = Battle::AbilityEffects.triggerModifyMoveBaseType(user.ability, user, self, ret)
    end
    return ret
  end

  def pbCalcType(user)
    @powerBoost = false
    ret = pbBaseType(user)
    if ret && GameData::Type.exists?(:ELECTRIC)
      if @battle.field.effects[PBEffects::IonDeluge] && ret == :NORMAL
        ret = :ELECTRIC
        @powerBoost = false
      end
      if user.effects[PBEffects::Electrify]
        ret = :ELECTRIC
        @powerBoost = false
      end
    end
    return ret
  end

  #=============================================================================
  # Type effectiveness calculation
  #=============================================================================
  def pbCalcTypeModSingle(moveType, defType, user, target)
    ret = Effectiveness.calculate(moveType, defType)
    if Effectiveness.ineffective_type?(moveType, defType)
      # Ring Target
      if target.hasActiveItem?(:RINGTARGET)
        ret = Effectiveness::NORMAL_EFFECTIVE_MULTIPLIER
      end
      # Foresight
      if (user.hasActiveAbility?(:SCRAPPY) || user.hasActiveAbility?(:MINDSEYE) ||
          target.effects[PBEffects::Foresight]) && defType == :GHOST
        ret = Effectiveness::NORMAL_EFFECTIVE_MULTIPLIER
      end
      # Miracle Eye
      if target.effects[PBEffects::MiracleEye] && defType == :DARK
        ret = Effectiveness::NORMAL_EFFECTIVE_MULTIPLIER
      end
    elsif Effectiveness.super_effective_type?(moveType, defType)
      # Delta Stream's weather
      if target.effectiveWeather == :StrongWinds && defType == :FLYING
        ret = Effectiveness::NORMAL_EFFECTIVE_MULTIPLIER
      end
    end
    # Grounded Flying-type Pokémon become susceptible to Ground moves
    if !target.airborne? && defType == :FLYING && moveType == :GROUND
      ret = Effectiveness::NORMAL_EFFECTIVE_MULTIPLIER
    end
    return ret
  end

  def pbCalcTypeMod(moveType, user, target)
    ret = Effectiveness::NORMAL_EFFECTIVE_MULTIPLIER
    return ret if !moveType
    return ret if moveType == :GROUND && target.pbHasType?(:FLYING) && target.hasActiveItem?(:IRONBALL)
    # Get effectivenesses
    if moveType == :SHADOW
      if target.shadowPokemon?
        ret = Effectiveness::NOT_VERY_EFFECTIVE_MULTIPLIER
      else
        ret = Effectiveness::SUPER_EFFECTIVE_MULTIPLIER
      end
    else
      target.pbTypes(true).each do |type|
        ret *= pbCalcTypeModSingle(moveType, type, user, target)
      end
      ret *= 2 if target.effects[PBEffects::TarShot] && moveType == :FIRE
    end
    return ret
  end

  #=============================================================================
  # Accuracy check
  #=============================================================================
  def pbBaseAccuracy(user, target); return @accuracy; end

  # Accuracy calculations for one-hit KO moves are handled elsewhere.
  def pbAccuracyCheck(user, target)
    # "Always hit" effects and "always hit" accuracy
    return true if target.effects[PBEffects::Telekinesis] > 0
    return true if target.effects[PBEffects::Minimize] && tramplesMinimize? && Settings::MECHANICS_GENERATION >= 6
    baseAcc = pbBaseAccuracy(user, target)
    return true if baseAcc == 0
    # Calculate all multiplier effects
    modifiers = {}
    modifiers[:base_accuracy]  = baseAcc
    modifiers[:accuracy_stage] = user.stages[:ACCURACY]
    modifiers[:evasion_stage]  = target.stages[:EVASION]
    modifiers[:accuracy_multiplier] = 1.0
    modifiers[:evasion_multiplier]  = 1.0
    pbCalcAccuracyModifiers(user, target, modifiers)
    # Check if move can't miss
    return true if modifiers[:base_accuracy] == 0
    # Calculation
    max_stage = Battle::Battler::STAT_STAGE_MAXIMUM
    accStage = [[modifiers[:accuracy_stage], -max_stage].max, max_stage].min + max_stage
    evaStage = [[modifiers[:evasion_stage], -max_stage].max, max_stage].min + max_stage
    stageMul = Battle::Battler::ACC_EVA_STAGE_MULTIPLIERS
    stageDiv = Battle::Battler::ACC_EVA_STAGE_DIVISORS
    accuracy = 100.0 * stageMul[accStage] / stageDiv[accStage]
    evasion  = 100.0 * stageMul[evaStage] / stageDiv[evaStage]
    accuracy = (accuracy * modifiers[:accuracy_multiplier]).round
    evasion  = (evasion  * modifiers[:evasion_multiplier]).round
    evasion = 1 if evasion < 1
    threshold = modifiers[:base_accuracy] * accuracy / evasion
    # Calculation
    r = @battle.pbRandom(100)
    if Settings::AFFECTION_EFFECTS && @battle.internalBattle &&
       target.pbOwnedByPlayer? && target.affection_level == 5 && !target.mega?
      return true if r < threshold - 10
      target.damageState.affection_missed = true if r < threshold
      return false
    end
    return r < threshold
  end

  def pbCalcAccuracyModifiers(user, target, modifiers)
    # Ability effects that alter accuracy calculation
    if user.abilityActive?
      Battle::AbilityEffects.triggerAccuracyCalcFromUser(
        user.ability, modifiers, user, target, self, @calcType
      )
    end
    user.allAllies.each do |b|
      next if !b.abilityActive?
      Battle::AbilityEffects.triggerAccuracyCalcFromAlly(
        b.ability, modifiers, user, target, self, @calcType
      )
    end
    if target.abilityActive? && !target.beingMoldBroken?
      Battle::AbilityEffects.triggerAccuracyCalcFromTarget(
        target.ability, modifiers, user, target, self, @calcType
      )
    end
    # Item effects that alter accuracy calculation
    if user.itemActive?
      Battle::ItemEffects.triggerAccuracyCalcFromUser(
        user.item, modifiers, user, target, self, @calcType
      )
    end
    if target.itemActive?
      Battle::ItemEffects.triggerAccuracyCalcFromTarget(
        target.item, modifiers, user, target, self, @calcType
      )
    end
    # Other effects, inc. ones that set accuracy_multiplier or evasion_stage to
    # specific values
    if @battle.field.effects[PBEffects::Gravity] > 0
      modifiers[:accuracy_multiplier] *= 5 / 3.0
    end
    if user.effects[PBEffects::MicleBerry]
      user.effects[PBEffects::MicleBerry] = false
      modifiers[:accuracy_multiplier] *= 1.2
    end
    modifiers[:evasion_stage] = 0 if target.effects[PBEffects::Foresight] && modifiers[:evasion_stage] > 0
    modifiers[:evasion_stage] = 0 if target.effects[PBEffects::MiracleEye] && modifiers[:evasion_stage] > 0
  end

  #=============================================================================
  # Critical hit check
  #=============================================================================
  # Return values:
  #   -1: Never a critical hit.
  #    0: Calculate normally.
  #    1: Always a critical hit.
  def pbCritialOverride(user, target); return 0; end

  # Returns whether the move will be a critical hit.
  def pbIsCritical?(user, target)
    return false if target.pbOwnSide.effects[PBEffects::LuckyChant] > 0
    c = 0
    # Ability effects that alter critical hit rate
    if c >= 0 && user.abilityActive?
      c = Battle::AbilityEffects.triggerCriticalCalcFromUser(user.ability, user, target, c, self)
    end
    if c >= 0 && target.abilityActive? && !target.beingMoldBroken?
      c = Battle::AbilityEffects.triggerCriticalCalcFromTarget(target.ability, user, target, c, self)
    end
    # Item effects that alter critical hit rate
    if c >= 0 && user.itemActive?
      c = Battle::ItemEffects.triggerCriticalCalcFromUser(user.item, user, target, c, self)
    end
    if c >= 0 && target.itemActive?
      c = Battle::ItemEffects.triggerCriticalCalcFromTarget(target.item, user, target, c, self)
    end
    return false if c < 0
    # Move-specific "always/never a critical hit" effects
    case pbCritialOverride(user, target)
    when 1  then return true
    when -1 then return false
    end
    # Other effects
    return true if c > 50   # Merciless
    return true if user.effects[PBEffects::LaserFocus] > 0
    c += 1 if highCriticalRate?
    c += user.criticalHitRate
    c += 1 if user.inHyperMode? && @type == :SHADOW
    # Set up the critical hit ratios
    ratios = CRITICAL_HIT_RATIOS
    c = ratios.length - 1 if c >= ratios.length
    # Calculation
    return true if ratios[c] == 1
    r = @battle.pbRandom(ratios[c])
    return true if r == 0
    if r == 1 && Settings::AFFECTION_EFFECTS && @battle.internalBattle &&
       user.pbOwnedByPlayer? && user.affection_level == 5 && !target.mega?
      target.damageState.affection_critical = true
      return true
    end
    return false
  end

  #-----------------------------------------------------------------------------
  # Damage calculation.
  #-----------------------------------------------------------------------------

  def pbBasePower(base_power, user, target);           return base_power; end
  alias pbBaseDamage pbBasePower
  def pbBasePowerMultiplier(damageMult, user, target); return damageMult; end
  alias pbBaseDamageMultiplier pbBasePowerMultiplier
  def pbModifyDamage(damageMult, user, target);        return damageMult; end

  def pbGetAttackStats(user, target)
    return user.spatk, user.stages[:SPECIAL_ATTACK] + Battle::Battler::STAT_STAGE_MAXIMUM if specialMove?
    return user.attack, user.stages[:ATTACK] + Battle::Battler::STAT_STAGE_MAXIMUM
  end

  def pbGetDefenseStats(user, target)
    return target.spdef, target.stages[:SPECIAL_DEFENSE] + Battle::Battler::STAT_STAGE_MAXIMUM if specialMove?
    return target.defense, target.stages[:DEFENSE] + Battle::Battler::STAT_STAGE_MAXIMUM
  end

  def pbCalcDamage(user, target, numTargets = 1)
    return if statusMove?
    if target.damageState.disguise || target.damageState.iceFace
      target.damageState.calcDamage = 1
      return
    end
    max_stage = Battle::Battler::STAT_STAGE_MAXIMUM
    stageMul = Battle::Battler::STAT_STAGE_MULTIPLIERS
    stageDiv = Battle::Battler::STAT_STAGE_DIVISORS
    # Get the move's type
    type = @calcType   # nil is treated as physical
    # Calculate whether this hit deals critical damage
    target.damageState.critical = pbIsCritical?(user, target)
    # Calcuate base power of move
    baseDmg = pbBasePower(@power, user, target)
    # Calculate user's attack stat
    atk, atkStage = pbGetAttackStats(user, target)
    if !target.hasActiveAbility?(:UNAWARE) || target.beingMoldBroken?
      atkStage = max_stage if target.damageState.critical && atkStage < max_stage
      atk = (atk.to_f * stageMul[atkStage] / stageDiv[atkStage]).floor
    end
    # Calculate target's defense stat
    defense, defStage = pbGetDefenseStats(user, target)
    if !user.hasActiveAbility?(:UNAWARE)
      defStage = max_stage if target.damageState.critical && defStage > max_stage
      defense = (defense.to_f * stageMul[defStage] / stageDiv[defStage]).floor
    end
    # Calculate all multiplier effects
    multipliers = {
      :power_multiplier        => 1.0,
      :attack_multiplier       => 1.0,
      :defense_multiplier      => 1.0,
      :final_damage_multiplier => 1.0
    }
    pbCalcDamageMultipliers(user, target, numTargets, type, baseDmg, multipliers)
    # Main damage calculation
    baseDmg = [(baseDmg * multipliers[:power_multiplier]).round, 1].max
    atk     = [(atk     * multipliers[:attack_multiplier]).round, 1].max
    defense = [(defense * multipliers[:defense_multiplier]).round, 1].max
    damage  = ((((2.0 * user.level / 5) + 2).floor * baseDmg * atk / defense).floor / 50).floor + 2
    damage  = [(damage * multipliers[:final_damage_multiplier]).round, 1].max
    target.damageState.calcDamage = damage
  end

  def pbCalcDamageMultipliers(user, target, numTargets, type, baseDmg, multipliers)
    if !self.is_a?(Battle::Move::Confusion)
      pbCalcDamageMultipliersGlobalAbilities(user, target, numTargets, type, baseDmg, multipliers)
      pbCalcDamageMultipliersAbilities(user, target, numTargets, type, baseDmg, multipliers)
      pbCalcDamageMultipliersHeldItems(user, target, numTargets, type, baseDmg, multipliers)
      pbCalcDamageMultipliersGymBadges(user, target, numTargets, type, baseDmg, multipliers)
      pbCalcDamageMultipliersLingeringEffects(user, target, numTargets, type, baseDmg, multipliers)
      pbCalcDamageMultipliersStatusConditions(user, target, numTargets, type, baseDmg, multipliers)
    end
    pbCalcDamageMultipliersMoveEffects(user, target, numTargets, type, baseDmg, multipliers)
    # Random variance
    random = 85 + @battle.pbRandom(16)
    multipliers[:final_damage_multiplier] *= random / 100.0
    # Multi-targeting attacks
    multipliers[:final_damage_multiplier] *= 0.75 if numTargets > 1
    # Critical hits
    if target.damageState.critical
      if Settings::NEW_CRITICAL_HIT_RATE_MECHANICS
        multipliers[:final_damage_multiplier] *= 1.5
      else
        multipliers[:final_damage_multiplier] *= 2
      end
    end
    # STAB
    if type && user.pbHasType?(type)
      if user.hasActiveAbility?(:ADAPTABILITY)
        multipliers[:final_damage_multiplier] *= 2
      else
        multipliers[:final_damage_multiplier] *= 1.5
      end
    end
    # Type effectiveness
    multipliers[:final_damage_multiplier] *= target.damageState.typeMod
  end

  # Global ability effects that alter damage.
  def pbCalcDamageMultipliersGlobalAbilities(user, target, numTargets, type, baseDmg, multipliers)
    all_abilities = @battle.pbAllActiveAbilities
    if (all_abilities.include?(:DARKAURA) && type == :DARK) ||
       (all_abilities.include?(:FAIRYAURA) && type == :FAIRY)
      if all_abilities.include?(:AURABREAK)
        multipliers[:power_multiplier] *= 3 / 4.0
      else
        multipliers[:power_multiplier] *= 4 / 3.0
      end
    end
    if all_abilities.include?(:TABLETSOFRUIN) && user.ability_id != :TABLETSOFRUIN
      multipliers[:power_multiplier] *= 3 / 4.0 if physicalMove?
    end
    if all_abilities.include?(:VESSELOFRUIN) && user.ability_id != :VESSELOFRUIN
      multipliers[:power_multiplier] *= 3 / 4.0 if specialMove?
    end
    if all_abilities.include?(:SWORDOFRUIN) && user.ability_id != :SWORDOFRUIN
      if @battle.field.effects[PBEffects::WonderRoom] > 0
        multipliers[:defense_multiplier] *= 3 / 4.0 if specialMove?
      else
        multipliers[:defense_multiplier] *= 3 / 4.0 if physicalMove?
      end
    end
    if all_abilities.include?(:BEADSOFRUIN) && user.ability_id != :BEADSOFRUIN
      if @battle.field.effects[PBEffects::WonderRoom] > 0
        multipliers[:defense_multiplier] *= 3 / 4.0 if physicalMove?
      else
        multipliers[:defense_multiplier] *= 3 / 4.0 if specialMove?
      end
    end
  end

  # Ability effects that alter damage.
  def pbCalcDamageMultipliersAbilities(user, target, numTargets, type, baseDmg, multipliers)
    if user.abilityActive?
      Battle::AbilityEffects.triggerDamageCalcFromUser(
        user.ability, user, target, self, multipliers, baseDmg, type
      )
    end
    # NOTE: It's odd that the user's Mold Breaker prevents its partner's
    #       beneficial abilities (i.e. Flower Gift boosting Atk), but that's
    #       how it works.
    user.allAllies.each do |b|
      next if !b.abilityActive? || b.beingMoldBroken?
      Battle::AbilityEffects.triggerDamageCalcFromAlly(
        b.ability, user, target, self, multipliers, baseDmg, type
      )
    end
    if target.abilityActive?
      if !target.beingMoldBroken?
        Battle::AbilityEffects.triggerDamageCalcFromTarget(
          target.ability, user, target, self, multipliers, baseDmg, type
        )
      end
      Battle::AbilityEffects.triggerDamageCalcFromTargetNonIgnorable(
        target.ability, user, target, self, multipliers, baseDmg, type
      )
    end
    target.allAllies.each do |b|
      next if !b.abilityActive? || b.beingMoldBroken?
      Battle::AbilityEffects.triggerDamageCalcFromTargetAlly(
        b.ability, user, target, self, multipliers, baseDmg, type
      )
    end
  end

  # Item effects that alter damage.
  def pbCalcDamageMultipliersHeldItems(user, target, numTargets, type, baseDmg, multipliers)
    if user.itemActive?
      Battle::ItemEffects.triggerDamageCalcFromUser(
        user.item, user, target, self, multipliers, baseDmg, type
      )
    end
    if target.itemActive?
      Battle::ItemEffects.triggerDamageCalcFromTarget(
        target.item, user, target, self, multipliers, baseDmg, type
      )
    end
  end

  # Stat multipliers conferred by Gym Badges.
  def pbCalcDamageMultipliersGymBadges(user, target, numTargets, type, baseDmg, multipliers)
    return if !@battle.internalBattle
    if user.pbOwnedByPlayer?
      if physicalMove? && @battle.pbPlayer.badge_count >= Settings::NUM_BADGES_BOOST_ATTACK
        multipliers[:attack_multiplier] *= 1.1
      elsif specialMove? && @battle.pbPlayer.badge_count >= Settings::NUM_BADGES_BOOST_SPATK
        multipliers[:attack_multiplier] *= 1.1
      end
    end
    if target.pbOwnedByPlayer?
      if physicalMove? && @battle.pbPlayer.badge_count >= Settings::NUM_BADGES_BOOST_DEFENSE
        multipliers[:defense_multiplier] *= 1.1
      elsif specialMove? && @battle.pbPlayer.badge_count >= Settings::NUM_BADGES_BOOST_SPDEF
        multipliers[:defense_multiplier] *= 1.1
      end
    end
  end

  # Various effects that were started on the user/target/field/side, including
  # weather and terrain, that alter damage.
  def pbCalcDamageMultipliersLingeringEffects(user, target, numTargets, type, baseDmg, multipliers)
    # Parental Bond's second attack
    if user.effects[PBEffects::ParentalBond] == 1
      multipliers[:power_multiplier] /= (Settings::MECHANICS_GENERATION >= 7) ? 4 : 2
    end
    # Other
    if user.effects[PBEffects::MeFirst]
      multipliers[:power_multiplier] *= 1.5
    end
    if user.effects[PBEffects::HelpingHand]
      multipliers[:power_multiplier] *= 1.5
    end
    if user.effects[PBEffects::Charge] > 0 && type == :ELECTRIC
      multipliers[:power_multiplier] *= 2
    end
    if target.effects[PBEffects::Vulnerable]
      multipliers[:final_damage_multiplier] *= 2
    end
    # Mud Sport
    if type == :ELECTRIC
      if @battle.allBattlers.any? { |b| b.effects[PBEffects::MudSport] }
        multipliers[:power_multiplier] /= 3
      end
      if @battle.field.effects[PBEffects::MudSportField] > 0
        multipliers[:power_multiplier] /= 3
      end
    end
    # Water Sport
    if type == :FIRE
      if @battle.allBattlers.any? { |b| b.effects[PBEffects::WaterSport] }
        multipliers[:power_multiplier] /= 3
      end
      if @battle.field.effects[PBEffects::WaterSportField] > 0
        multipliers[:power_multiplier] /= 3
      end
    end
    # Terrain moves
    terrain_multiplier = (Settings::MECHANICS_GENERATION >= 8) ? 1.3 : 1.5
    case @battle.field.terrain
    when :Electric
      multipliers[:power_multiplier] *= terrain_multiplier if type == :ELECTRIC && user.affectedByTerrain?
    when :Grassy
      multipliers[:power_multiplier] *= terrain_multiplier if type == :GRASS && user.affectedByTerrain?
    when :Psychic
      multipliers[:power_multiplier] *= terrain_multiplier if type == :PSYCHIC && user.affectedByTerrain?
    when :Misty
      multipliers[:power_multiplier] /= 2 if type == :DRAGON && target.affectedByTerrain?
    end
    # Weather
    case target.effectiveWeather
    when :Sun, :HarshSun
      case type
      when :FIRE
        multipliers[:final_damage_multiplier] *= 1.5
      when :WATER
        if @function_code == "IncreasePowerInSun" && [:Sun, :HarshSun].include?(user.effectiveWeather)
          multipliers[:final_damage_multiplier] *= 1.5
        else
          multipliers[:final_damage_multiplier] /= 2
        end
      end
    when :Rain, :HeavyRain
      case type
      when :FIRE
        multipliers[:final_damage_multiplier] /= 2
      when :WATER
        multipliers[:final_damage_multiplier] *= 1.5
      end
    when :Sandstorm
      if target.pbHasType?(:ROCK) && specialMove? && @function_code != "UseTargetDefenseInsteadOfTargetSpDef"
        multipliers[:defense_multiplier] *= 1.5
      end
    when :ShadowSky
      multipliers[:final_damage_multiplier] *= 1.5 if type == :SHADOW
    when :Snowstorm
      if target.pbHasType?(:ICE) && 
         (physicalMove? || @function_code == "UseTargetDefenseInsteadOfTargetSpDef")
        multipliers[:defense_multiplier] *= 1.5
      end
    end
    # Aurora Veil, Reflect, Light Screen
    if !ignoresReflect? && !target.damageState.critical &&
       !user.hasActiveAbility?(:INFILTRATOR)
      if target.pbOwnSide.effects[PBEffects::AuroraVeil] > 0
        if @battle.pbSideBattlerCount(target) > 1
          multipliers[:final_damage_multiplier] *= 2 / 3.0
        else
          multipliers[:final_damage_multiplier] /= 2
        end
      elsif target.pbOwnSide.effects[PBEffects::Reflect] > 0 && physicalMove?
        if @battle.pbSideBattlerCount(target) > 1
          multipliers[:final_damage_multiplier] *= 2 / 3.0
        else
          multipliers[:final_damage_multiplier] /= 2
        end
      elsif target.pbOwnSide.effects[PBEffects::LightScreen] > 0 && specialMove?
        if @battle.pbSideBattlerCount(target) > 1
          multipliers[:final_damage_multiplier] *= 2 / 3.0
        else
          multipliers[:final_damage_multiplier] /= 2
        end
      end
    end
  end

  # Status conditions that alter damage.
  def pbCalcDamageMultipliersStatusConditions(user, target, numTargets, type, baseDmg, multipliers)
    # Burn
    if user.status == :BURN && physicalMove? && damageReducedByBurn? &&
       !user.hasActiveAbility?(:GUTS)
      multipliers[:final_damage_multiplier] /= 2
    end
  end

  # Move-specific properties and effects that alter damage.
  def pbCalcDamageMultipliersMoveEffects(user, target, numTargets, type, baseDmg, multipliers)
    # Minimize
    if target.effects[PBEffects::Minimize] && tramplesMinimize?
      multipliers[:final_damage_multiplier] *= 2
    end
    # Move-specific base damage modifiers
    multipliers[:power_multiplier] = pbBasePowerMultiplier(multipliers[:power_multiplier], user, target)
    # Move-specific final damage modifiers
    multipliers[:final_damage_multiplier] = pbModifyDamage(multipliers[:final_damage_multiplier], user, target)
  end

  #-----------------------------------------------------------------------------
  # Additional effect chance.
  #-----------------------------------------------------------------------------

  def pbAdditionalEffectChance(user, target, effectChance = 0)
    return 0 if target.hasActiveAbility?(:SHIELDDUST) && !target.beingMoldBroken? &&
                !additionalEffectAffectsUser?
    ret = (effectChance > 0) ? effectChance : @addlEffect
    return ret if ret > 100
    if (Settings::MECHANICS_GENERATION >= 6 || @function_code != "EffectDependsOnEnvironment") &&
       (user.hasActiveAbility?(:SERENEGRACE) || user.pbOwnSide.effects[PBEffects::Rainbow] > 0)
      ret *= 2
    end
    ret = 100 if $DEBUG && Input.press?(Input::CTRL)
    return ret if [0, 100].include?(ret)
    if [:Hail, :Snowstorm].include?(@battle.pbWeather) &&
       (@function_code.include?("FrostbiteTarget") ||
       (Settings::FREEZE_EFFECTS_CAUSE_FROSTBITE && @function_code.include?("FreezeTarget")))
      ret *= 2
    end
    return [ret, 100].min
  end

  # NOTE: Flinching caused by a move's effect is applied in that move's code,
  #       not here.
  def pbFlinchChance(user, target)
    return 0 if flinchingMove?
    return 0 if !target.affectedByAdditionalEffects?
    return 0 if target.hasActiveAbility?(:SHIELDDUST) && !target.beingMoldBroken?
    ret = 0
    if user.hasActiveAbility?(:STENCH, true) ||
       user.hasActiveItem?([:KINGSROCK, :RAZORFANG], true)
      ret = 10
    end
    ret *= 2 if user.hasActiveAbility?(:SERENEGRACE) ||
                user.pbOwnSide.effects[PBEffects::Rainbow] > 0
    return ret
  end
end

==============================================================================
# Script: Move_BaseEffects
==============================================================================
# DO NOT USE ANY CLASS NAMES IN HERE AS FUNCTION CODES!
# These are base classes for other classes to build on; those other classes are
# named after function codes, so use those instead.

#===============================================================================
# Superclass that handles moves using a non-existent function code.
# Damaging moves just do damage with no additional effect.
# Status moves always fail.
#===============================================================================
class Battle::Move::Unimplemented < Battle::Move
  def pbMoveFailed?(user, targets)
    if statusMove?
      @battle.pbDisplay(_INTL("¡Pero ha fallado!"))
      return true
    end
    return false
  end
end

#===============================================================================
# Pseudomove for confusion damage.
#===============================================================================
class Battle::Move::Confusion < Battle::Move
  def initialize(battle, move)
    @battle        = battle
    @realMove      = move
    @id            = :CONFUSEDAMAGE
    @name          = ""
    @function_code = "None"
    @power         = 40
    @type          = nil
    @category      = 0
    @accuracy      = 100
    @pp            = -1
    @target        = :User
    @priority      = 0
    @flags         = []
    @addlEffect    = 0
    @powerBoost    = false
    @snatched      = false
  end

  def physicalMove?(thisType = nil);   return true;  end
  def specialMove?(thisType = nil);    return false; end
  def pbCritialOverride(user, target); return -1;    end
end

#===============================================================================
# Struggle.
#===============================================================================
class Battle::Move::Struggle < Battle::Move
  def initialize(battle, move)
    @battle        = battle
    @realMove      = nil                     # Not associated with a move
    @id            = :STRUGGLE
    @name          = _INTL("Forcejeo")
    @function_code = "Struggle"
    @power         = 50
    @type          = nil
    @category      = 0
    @accuracy      = 0
    @pp            = -1
    @target        = :RandomNearFoe
    @priority      = 0
    @flags         = ["Contact", "CanProtect"]
    @addlEffect    = 0
    @powerBoost    = false
    @snatched      = false
  end

  def physicalMove?(thisType = nil); return true;  end
  def specialMove?(thisType = nil);  return false; end

  def pbEffectAfterAllHits(user, target)
    return if target.damageState.unaffected
    user.pbReduceHP((user.totalhp / 4.0).round, false)
    @battle.pbDisplay(_INTL("¡{1} también se ha hecho daño!", user.pbThis))
    user.pbItemHPHealCheck
  end
end

#===============================================================================
# Raise one of user's stats.
#===============================================================================
class Battle::Move::StatUpMove < Battle::Move
  attr_reader :statUp

  def canSnatch?;                   return true; end
  def additionalEffectAffectsUser?; return true; end

  def pbMoveFailed?(user, targets)
    return false if damagingMove?
    return !user.pbCanRaiseStatStage?(@statUp[0], user, self, true)
  end

  def pbEffectGeneral(user)
    return if damagingMove?
    user.pbRaiseStatStage(@statUp[0], @statUp[1], user)
  end

  def pbAdditionalEffect(user, target)
    if user.pbCanRaiseStatStage?(@statUp[0], user, self)
      user.pbRaiseStatStage(@statUp[0], @statUp[1], user)
    end
  end
end

#===============================================================================
# Raise multiple of user's stats.
#===============================================================================
class Battle::Move::MultiStatUpMove < Battle::Move
  attr_reader :statUp

  def canSnatch?;                   return true; end
  def additionalEffectAffectsUser?; return true; end

  def pbMoveFailed?(user, targets)
    return false if damagingMove?
    failed = true
    (@statUp.length / 2).times do |i|
      next if !user.pbCanRaiseStatStage?(@statUp[i * 2], user, self)
      failed = false
      break
    end
    if failed
      @battle.pbDisplay(_INTL("¡Las estadísticas de {1} no pueden aumentar más!", user.pbThis(true)))
      return true
    end
    return false
  end

  def pbEffectGeneral(user)
    return if damagingMove?
    showAnim = true
    (@statUp.length / 2).times do |i|
      next if !user.pbCanRaiseStatStage?(@statUp[i * 2], user, self)
      if user.pbRaiseStatStage(@statUp[i * 2], @statUp[(i * 2) + 1], user, showAnim)
        showAnim = false
      end
    end
  end

  def pbAdditionalEffect(user, target)
    showAnim = true
    (@statUp.length / 2).times do |i|
      next if !user.pbCanRaiseStatStage?(@statUp[i * 2], user, self)
      if user.pbRaiseStatStage(@statUp[i * 2], @statUp[(i * 2) + 1], user, showAnim)
        showAnim = false
      end
    end
  end
end

#===============================================================================
# Lower multiple of user's stats.
#===============================================================================
class Battle::Move::StatDownMove < Battle::Move
  attr_reader :statDown

  def pbOnStartUse(user, targets)
    @stats_lowered = false
  end

  def pbEffectWhenDealingDamage(user, target)
    return if @stats_lowered
    return if @battle.pbAllFainted?(target.idxOwnSide)
    @stats_lowered = true
    showAnim = true
    (@statDown.length / 2).times do |i|
      next if !user.pbCanLowerStatStage?(@statDown[i * 2], user, self)
      if user.pbLowerStatStage(@statDown[i * 2], @statDown[(i * 2) + 1], user, showAnim)
        showAnim = false
      end
    end
  end
end

#===============================================================================
# Lower one of target's stats.
#===============================================================================
class Battle::Move::TargetStatDownMove < Battle::Move
  attr_reader :statDown

  def canMagicCoat?; return true; end

  def pbFailsAgainstTarget?(user, target, show_message)
    return false if damagingMove?
    return !target.pbCanLowerStatStage?(@statDown[0], user, self, show_message)
  end

  def pbEffectAgainstTarget(user, target)
    return if damagingMove?
    target.pbLowerStatStage(@statDown[0], @statDown[1], user)
  end

  def pbAdditionalEffect(user, target)
    return if !target.affectedByAdditionalEffects?
    return if target.damageState.substitute
    return if !target.pbCanLowerStatStage?(@statDown[0], user, self)
    target.pbLowerStatStage(@statDown[0], @statDown[1], user)
  end
end

#===============================================================================
# Lower multiple of target's stats.
#===============================================================================
class Battle::Move::TargetMultiStatDownMove < Battle::Move
  attr_reader :statDown

  def canMagicCoat?; return true; end

  def pbFailsAgainstTarget?(user, target, show_message)
    return false if damagingMove?
    failed = true
    (@statDown.length / 2).times do |i|
      next if !target.pbCanLowerStatStage?(@statDown[i * 2], user, self)
      failed = false
      break
    end
    if failed
      # NOTE: It's a bit of a faff to make sure the appropriate failure message
      #       is shown here, I know.
      canLower = false
      if target.hasActiveAbility?(:CONTRARY) && !target.beingMoldBroken?
        (@statDown.length / 2).times do |i|
          next if target.statStageAtMax?(@statDown[i * 2])
          canLower = true
          break
        end
        @battle.pbDisplay(_INTL("¡Las estadísticas de {1} no pueden aumentar más!", user.pbThis(true))) if !canLower && show_message
      else
        (@statDown.length / 2).times do |i|
          next if target.statStageAtMin?(@statDown[i * 2])
          canLower = true
          break
        end
        @battle.pbDisplay(_INTL("¡Las estadísticas de {1} no pueden disminuir más!", user.pbThis(true))) if !canLower && show_message
      end
      if canLower
        target.pbCanLowerStatStage?(@statDown[0], user, self, show_message)
      end
      return true
    end
    return false
  end

  def pbCheckForMirrorArmor(user, target)
    if target.hasActiveAbility?(:MIRRORARMOR) && user.index != target.index
      failed = true
      (@statDown.length / 2).times do |i|
        next if target.statStageAtMin?(@statDown[i * 2])
        next if !user.pbCanLowerStatStage?(@statDown[i * 2], target, self, false, false, true)
        failed = false
        break
      end
      if failed
        @battle.pbShowAbilitySplash(target)
        if !Battle::Scene::USE_ABILITY_SPLASH
          @battle.pbDisplay(_INTL("¡Se activó {1} de {2}!", target.pbThis(true), target.abilityName))
        end
        user.pbCanLowerStatStage?(@statDown[0], target, self, true, false, true)   # Show fail message
        @battle.pbHideAbilitySplash(target)
        return false
      end
    end
    return true
  end

  def pbLowerTargetMultipleStats(user, target)
    return if !pbCheckForMirrorArmor(user, target)
    showAnim = true
    showMirrorArmorSplash = true
    (@statDown.length / 2).times do |i|
      next if !target.pbCanLowerStatStage?(@statDown[i * 2], user, self)
      if target.pbLowerStatStage(@statDown[i * 2], @statDown[(i * 2) + 1], user,
                                 showAnim, false, (showMirrorArmorSplash) ? 1 : 3)
        showAnim = false
      end
      showMirrorArmorSplash = false
    end
    @battle.pbHideAbilitySplash(target)   # To hide target's Mirror Armor splash
  end

  def pbEffectAgainstTarget(user, target)
    pbLowerTargetMultipleStats(user, target) if !damagingMove?
  end

  def pbAdditionalEffect(user, target)
    return if !target.affectedByAdditionalEffects?
    return if target.damageState.substitute
    pbLowerTargetMultipleStats(user, target)
  end
end

#===============================================================================
# Fixed damage-inflicting move.
#===============================================================================
class Battle::Move::FixedDamageMove < Battle::Move
  def pbFixedDamage(user, target); return 1; end

  def pbCalcDamage(user, target, numTargets = 1)
    target.damageState.critical   = false
    target.damageState.calcDamage = pbFixedDamage(user, target)
    target.damageState.calcDamage = 1 if target.damageState.calcDamage < 1
  end
end

#===============================================================================
# Two turn move.
#===============================================================================
class Battle::Move::TwoTurnMove < Battle::Move
  attr_reader :chargingTurn

  def chargingTurnMove?; return true; end

  # user.effects[PBEffects::TwoTurnAttack] is set to the move's ID if this
  # method returns true, or nil if false.
  # Non-nil means the charging turn. nil means the attacking turn.
  def pbIsChargingTurn?(user)
    @powerHerb = false
    @chargingTurn = false   # Assume damaging turn by default
    @damagingTurn = true
    # nil at start of charging turn, move's ID at start of damaging turn
    if !user.effects[PBEffects::TwoTurnAttack]
      @powerHerb = user.hasActiveItem?(:POWERHERB)
      @chargingTurn = true
      @damagingTurn = @powerHerb
    end
    return !@damagingTurn   # Deliberately not "return @chargingTurn"
  end

  # Stops damage being dealt in the first (charging) turn.
  def pbDamagingMove?
    return false if !@damagingTurn
    return super
  end

  # Does the charging part of this move, for when this move only takes one round
  # to use.
  def pbQuickChargingMove(user, targets)
    return if !@chargingTurn || !@damagingTurn   # Move only takes one turn to use
    pbChargingTurnMessage(user, targets)
    pbShowAnimation(@id, user, targets, 1)   # Charging anim
    targets.each { |b| pbChargingTurnEffect(user, b) }
    if @powerHerb
      # Moves that would make the user semi-invulnerable will hide the user
      # after the charging animation, so the "UseItem" animation shouldn't show
      # for it
      if !["TwoTurnAttackInvulnerableInSky",
           "TwoTurnAttackInvulnerableUnderground",
           "TwoTurnAttackInvulnerableUnderwater",
           "TwoTurnAttackInvulnerableInSkyParalyzeTarget",
           "TwoTurnAttackInvulnerableRemoveProtections",
           "TwoTurnAttackInvulnerableInSkyTargetCannotAct"].include?(@function_code)
        @battle.pbCommonAnimation("UseItem", user)
      end
      @battle.pbDisplay(_INTL("¡{1} ya está listo gracias a la hierba única!", user.pbThis))
      user.pbConsumeItem
    end
  end

  def pbAccuracyCheck(user, target)
    return true if !@damagingTurn
    return super
  end

  def pbInitialEffect(user, targets, hitNum)
    if @damagingTurn
      pbAttackingTurnMessage(user, targets)
    elsif @chargingTurn
      pbChargingTurnMessage(user, targets)
    end
  end

  def pbChargingTurnMessage(user, targets)
    @battle.pbDisplay(_INTL("¡{1} está preparándose para atacar!", user.pbThis))
  end

  def pbAttackingTurnMessage(user, targets); end

  def pbEffectAgainstTarget(user, target)
    if @damagingTurn
      pbAttackingTurnEffect(user, target)
    elsif @chargingTurn
      pbChargingTurnEffect(user, target)
    end
  end

  def pbChargingTurnEffect(user, target)
    # Skull Bash/Sky Drop are the only two-turn moves with an effect here, and
    # the latter just records the target is being Sky Dropped
  end

  def pbAttackingTurnEffect(user, target); end

  def pbShowAnimation(id, user, targets, hitNum = 0, showAnimation = true)
    hitNum = 1 if @chargingTurn && !@damagingTurn   # Charging anim
    super
  end
end

#===============================================================================
# Healing move.
#===============================================================================
class Battle::Move::HealingMove < Battle::Move
  def healingMove?;       return true; end
  def pbHealAmount(user); return 1;    end
  def canSnatch?;         return true; end

  def pbMoveFailed?(user, targets)
    if user.hp == user.totalhp
      @battle.pbDisplay(_INTL("¡Los PS de {1} están al máximo!", user.pbThis(true)))
      return true
    end
    return false
  end

  def pbEffectGeneral(user)
    amt = pbHealAmount(user)
    user.pbRecoverHP(amt)
    @battle.pbDisplay(_INTL("¡{1} ha recuperado PS!", user.pbThis))
  end
end

#===============================================================================
# Recoil move.
#===============================================================================
class Battle::Move::RecoilMove < Battle::Move
  def recoilMove?;                  return true; end
  def pbRecoilDamage(user, target); return 1;    end

  def pbEffectAfterAllHits(user, target)
    return if target.damageState.unaffected
    return if !user.takesIndirectDamage?
    return if user.hasActiveAbility?(:ROCKHEAD)
    amt = pbRecoilDamage(user, target)
    amt = 1 if amt < 1
    if user.pokemon.isSpecies?(:BASCULIN) && [2, 3].include?(user.pokemon.form)
      user.pokemon.evolution_counter += amt
    end
    user.pokemon.recoil_evolution(amt)
    user.pbReduceHP(amt, false)
    @battle.pbDisplay(_INTL("¡{1} también se ha hecho daño!", user.pbThis))
    user.pbItemHPHealCheck
  end
end

#===============================================================================
# Protect move.
#===============================================================================
class Battle::Move::ProtectMove < Battle::Move
  def initialize(battle, move)
    super
    @sidedEffect = false
  end

  def pbChangeUsageCounters(user, specialUsage)
    oldVal = user.effects[PBEffects::ProtectRate]
    super
    user.effects[PBEffects::ProtectRate] = oldVal
  end

  def pbMoveFailed?(user, targets)
    if @sidedEffect
      if user.pbOwnSide.effects[@effect]
        user.effects[PBEffects::ProtectRate] = 1
        @battle.pbDisplay(_INTL("¡Pero ha fallado!"))
        return true
      end
    elsif user.effects[@effect]
      user.effects[PBEffects::ProtectRate] = 1
      @battle.pbDisplay(_INTL("¡Pero ha fallado!"))
      return true
    end
    if (!@sidedEffect || Settings::MECHANICS_GENERATION <= 5) &&
       user.effects[PBEffects::ProtectRate] > 1 &&
       @battle.pbRandom(user.effects[PBEffects::ProtectRate]) != 0
      user.effects[PBEffects::ProtectRate] = 1
      @battle.pbDisplay(_INTL("¡Pero ha fallado!"))
      return true
    end
    if pbMoveFailedLastInRound?(user)
      user.effects[PBEffects::ProtectRate] = 1
      return true
    end
    return false
  end

  def pbEffectGeneral(user)
    if @sidedEffect
      user.pbOwnSide.effects[@effect] = true
    else
      user.effects[@effect] = true
    end
    user.effects[PBEffects::ProtectRate] *= (Settings::MECHANICS_GENERATION >= 6) ? 3 : 2
    pbProtectMessage(user)
  end

  def pbProtectMessage(user)
    if @sidedEffect
      @battle.pbDisplay(_INTL("¡{1} protege {2}!", @name, user.pbTeam(true)))
    else
      @battle.pbDisplay(_INTL("¡{1} se está protegiendo!", user.pbThis))
    end
  end
end

#===============================================================================
# Weather-inducing move.
#===============================================================================
class Battle::Move::WeatherMove < Battle::Move
  attr_reader :weatherType

  def initialize(battle, move)
    super
    @weatherType = :None
  end

  def pbMoveFailed?(user, targets)
    case @battle.field.weather
    when :HarshSun
      @battle.pbDisplay(_INTL("¡El calor abrasador se mantiene sin perder un ápice de intensidad!"))
      return true
    when :HeavyRain
      @battle.pbDisplay(_INTL("¡No parece que vaya a dejar de diluviar!"))
      return true
    when :StrongWinds
      @battle.pbDisplay(_INTL("¡Las misteriosas turbulencias continúan sin cesar!"))
      return true
    end
    if !@battle.pbCanStartWeather?(@weatherType)
      @battle.pbDisplay(_INTL("¡Pero ha fallado!"))
      return true
    end
    return false
  end

  def pbEffectGeneral(user)
    @battle.pbStartWeather(user, @weatherType, true, false)
  end
end

