#===============================================================================
# Pledge move.
#===============================================================================
class Battle::Move::PledgeMove < Battle::Move
  def pbOnStartUse(user, targets)
    @pledgeSetup = false
    @pledgeCombo = false
    @pledgeOtherUser = nil
    @comboEffect = nil
    @overrideAnim = nil
    # Check whether this is the use of a combo move
    @combos.each do |i|
      next if i[0] != user.effects[PBEffects::FirstPledge]
      @battle.pbDisplay(_INTL("¡Los dos movimientos se han unido! ¡Es un movimiento combinado!"))
      @pledgeCombo = true
      @comboEffect = i[1]
      @overrideAnim = i[3]
      break
    end
    return if @pledgeCombo
    # Check whether this is the setup of a combo move
    user.allAllies.each do |b|
      next if @battle.choices[b.index][0] != :UseMove || b.movedThisRound?
      move = @battle.choices[b.index][2]
      next if !move
      @combos.each do |i|
        next if i[0] != move.function_code
        @pledgeSetup = true
        @pledgeOtherUser = b
        break
      end
      break if @pledgeSetup
    end
  end

  def pbDamagingMove?
    return false if @pledgeSetup
    return super
  end

  def pbBaseType(user)
    # This method is called before pbOnStartUse, so it has to calculate the type
    # separately
    @combos.each do |i|
      next if i[0] != user.effects[PBEffects::FirstPledge]
      next if !GameData::Type.exists?(i[2])
      return i[2]
    end
    return super
  end

  def pbBasePower(base_power, user, target)
    base_power *= 2 if @pledgeCombo
    return base_power
  end

  def pbEffectGeneral(user)
    user.effects[PBEffects::FirstPledge] = nil
    return if !@pledgeSetup
    @battle.pbDisplay(_INTL("{1} está esperando a {2}...",
                            user.pbThis, @pledgeOtherUser.pbThis(true)))
    @pledgeOtherUser.effects[PBEffects::FirstPledge] = @function_code
    @pledgeOtherUser.effects[PBEffects::MoveNext]    = true
    user.lastMoveFailed = true   # Treated as a failure for Stomping Tantrum
  end

  def pbEffectAfterAllHits(user, target)
    return if !@pledgeCombo
    msg = nil
    animName = nil
    case @comboEffect
    when :SeaOfFire   # Grass + Fire
      if user.pbOpposingSide.effects[PBEffects::SeaOfFire] == 0
        user.pbOpposingSide.effects[PBEffects::SeaOfFire] = 4
        msg = _INTL("¡{1} se ve rodeado por un mar de llamas!", user.pbOpposingTeam(true))
        animName = (user.opposes?) ? "SeaOfFire" : "SeaOfFireOpp"
      end
    when :Rainbow   # Fire + Water
      if user.pbOwnSide.effects[PBEffects::Rainbow] == 0
        user.pbOwnSide.effects[PBEffects::Rainbow] = 4
        msg = _INTL("¡Ha aparecido un arcoíris sobre {1}!", user.pbTeam(true))
        animName = (user.opposes?) ? "RainbowOpp" : "Rainbow"
      end
    when :Swamp   # Water + Grass
      if user.pbOpposingSide.effects[PBEffects::Swamp] == 0
        user.pbOpposingSide.effects[PBEffects::Swamp] = 4
        msg = _INTL("¡Ha aparecido un pantano alrededor de {1}!", user.pbOpposingTeam(true))
        animName = (user.opposes?) ? "Swamp" : "SwampOpp"
      end
    end
    @battle.pbDisplay(msg) if msg
    @battle.pbCommonAnimation(animName) if animName
  end

  def pbShowAnimation(id, user, targets, hitNum = 0, showAnimation = true)
    return if @pledgeSetup   # No animation for setting up
    id = @overrideAnim if @overrideAnim
    return super
  end
end

class Battle::Move::TerapagosCategoryDependsOnHigherDamage < Battle::Move

  def initialize(battle, move)
    super
    @calcCategory = 1
  end

  def pbTarget(user)
    # Si es Terapagos en forma astral (forma 2) en combate doble, golpea a ambos rivales
    if @battle.pbSideSize(0) > 1 && user.species == :TERAPAGOS && user.form == 2
      return GameData::Target.get(:AllNearFoes)  # Golpea a todos los rivales cercanos
    end
    # Comportamiento normal: un solo objetivo
    return GameData::Target.get(:NearOther)
  end

  def pbBaseType(user)
    # Si es Terapagos en forma astral, usar tipo Stellar
    if user.species == :TERAPAGOS && user.form == 2
      return :STELLAR if GameData::Type.exists?(:STELLAR)
    end
    # Si no, mantener tipo Normal
    return :NORMAL
  end

  def pbCalcTypeModSingle(moveType, defType, user, target)
    # Si es tipo Stellar vs Pokémon teracristalizados, es supereficaz
    if moveType == :STELLAR && target.tera?
      return Effectiveness::SUPER_EFFECTIVE_MULTIPLIER
    end
    # Si es tipo Stellar vs Pokémon normales, es neutral
    if moveType == :STELLAR
      return Effectiveness::NORMAL_EFFECTIVE_MULTIPLIER
    end
    # Para otros casos, cálculo normal
    return super
  end
end

