#===============================================================================
# Weakens Electric attacks. Lasts for 5 rounds (Gen 6+) or as long as the user
# is in battle (Gen 5-). (Mud Sport)
#===============================================================================
class Battle::Move::StartWeakenElectricMoves < Battle::Move
  def pbMoveFailed?(user, targets)
    if Settings::MECHANICS_GENERATION >= 6
      if @battle.field.effects[PBEffects::MudSportField] > 0
        @battle.pbDisplay(_INTL("¡Pero ha fallado!"))
        return true
      end
    elsif @battle.allBattlers.any? { |b| b.effects[PBEffects::MudSport] }
      @battle.pbDisplay(_INTL("¡Pero ha fallado!"))
      return true
    end
    return false
  end

  def pbEffectGeneral(user)
    if Settings::MECHANICS_GENERATION >= 6
      @battle.field.effects[PBEffects::MudSportField] = 5
    else
      user.effects[PBEffects::MudSport] = true
    end
    @battle.pbDisplay(_INTL("¡Se han debilitado los ataques de tipo Eléctrico!"))
  end
end

