#===============================================================================
# This round, reflects all moves that can be Magic Coated which target the user
# or which have no target back at their origin. (Magic Coat)
#===============================================================================
class Battle::Move::BounceBackProblemCausingStatusMoves < Battle::Move
  def pbEffectGeneral(user)
    user.effects[PBEffects::MagicCoat] = true
    @battle.pbDisplay(_INTL("¡{1} se cubrió con Capa Mágica!", user.pbThis))
  end
end

#===============================================================================
# This round, snatches all used moves that can be Snatched. (Snatch)
#===============================================================================
class Battle::Move::StealAndUseBeneficialStatusMove < Battle::Move
  def pbEffectGeneral(user)
    user.effects[PBEffects::Snatch] = 1
    @battle.allBattlers.each do |b|
      next if b.effects[PBEffects::Snatch] < user.effects[PBEffects::Snatch]
      user.effects[PBEffects::Snatch] = b.effects[PBEffects::Snatch] + 1
    end
    @battle.pbDisplay(_INTL("¡{1} espera a que su rival haga algún movimiento!", user.pbThis))
  end
end

#===============================================================================
# This move turns into the last move used by the target, until user switches
# out. (Mimic)
#===============================================================================
class Battle::Move::ReplaceMoveThisBattleWithTargetLastMoveUsed < Battle::Move
  attr_reader :moveBlacklist

  def ignoresSubstitute?(user); return true; end

  def initialize(battle, move)
    super
    @moveBlacklist = [
      "UseRandomMove",                                 # Metronome
      # Struggle
      "Struggle",                                      # Struggle
      # Moves that affect the moveset
      "ReplaceMoveThisBattleWithTargetLastMoveUsed",   # Mimic
      "ReplaceMoveWithTargetLastMoveUsed",             # Sketch
      "TransformUserIntoTarget",                        # Transform
      "StarmobileBurnTarget",                  # Blazing Torque
      "StarmobileParalyzeTarget",              # Combat Torque
      "StarmobileConfuseTarget",               # Magical Torque
      "StarmobilePoisonTarget",                # Noxious Torque
      "StarmobileSleepTarget",                 # Wicked Torque
      "TerapagosCategoryDependsOnHigherDamage" # Tera Starstorm
    ]
  end

  def pbMoveFailed?(user, targets)
    if user.effects[PBEffects::Transform] || !user.pbHasMove?(@id)
      @battle.pbDisplay(_INTL("¡Pero ha fallado!"))
      return true
    end
    return false
  end

  def pbFailsAgainstTarget?(user, target, show_message)
    lastMoveData = GameData::Move.try_get(target.lastRegularMoveUsed)
    if !lastMoveData ||
       user.pbHasMove?(target.lastRegularMoveUsed) ||
       @moveBlacklist.include?(lastMoveData.function_code) ||
       lastMoveData.type == :SHADOW
      @battle.pbDisplay(_INTL("¡Pero ha fallado!")) if show_message
      return true
    end
    return false
  end

  def pbEffectAgainstTarget(user, target)
    user.eachMoveWithIndex do |m, i|
      next if m.id != @id
      newMove = Pokemon::Move.new(target.lastRegularMoveUsed)
      user.moves[i] = Battle::Move.from_pokemon_move(@battle, newMove)
      @battle.pbDisplay(_INTL("¡{1} ha aprendido {2}!", user.pbThis, newMove.name))
      user.pbCheckFormOnMovesetChange
      break
    end
  end
end

#===============================================================================
# This move permanently turns into the last move used by the target. (Sketch)
#===============================================================================
class Battle::Move::ReplaceMoveWithTargetLastMoveUsed < Battle::Move
  attr_reader :moveBlacklist

  def ignoresSubstitute?(user); return true; end

  def initialize(battle, move)
    super
    @moveBlacklist = [
      "ReplaceMoveWithTargetLastMoveUsed",   # Sketch (this move)
      "RevivePokemonToHalfHP",               # Revival Blessing
      "Struggle"                             # Struggle
    ]
    @signatureMoveBlacklist = []
    if Settings::MECHANICS_GENERATION >= 9
      @signatureMoveBlacklist = [
        :DARKVOID,
        :HYPERSPACEFURY,
        :TERASTARSTORM
      ]
    end
  end

  def pbMoveFailed?(user, targets)
    if user.effects[PBEffects::Transform] || !user.pbHasMove?(@id)
      @battle.pbDisplay(_INTL("¡Pero ha fallado!"))
      return true
    end
    return false
  end

  def pbFailsAgainstTarget?(user, target, show_message)
    lastMoveData = GameData::Move.try_get(target.lastRegularMoveUsed)
    if !lastMoveData ||
       user.pbHasMove?(target.lastRegularMoveUsed) ||
       @moveBlacklist.include?(lastMoveData.function_code) ||
       @signatureMoveBlacklist.include?(lastMoveData.id) ||
       lastMoveData.type == :SHADOW
      @battle.pbDisplay(_INTL("¡Pero ha fallado!")) if show_message
      return true
    end
    return false
  end

  def pbEffectAgainstTarget(user, target)
    user.eachMoveWithIndex do |m, i|
      next if m.id != @id
      newMove = Pokemon::Move.new(target.lastRegularMoveUsed)
      user.pokemon.moves[i] = newMove
      user.moves[i] = Battle::Move.from_pokemon_move(@battle, newMove)
      @battle.pbDisplay(_INTL("¡{1} ha aprendido {2}!", user.pbThis, newMove.name))
      user.pbCheckFormOnMovesetChange
      break
    end
  end
end

==============================================================================
# Script: MoveEffects_SwitchingActing
==============================================================================
#===============================================================================
# User flees from battle. (Teleport (Gen 7-))
#===============================================================================
class Battle::Move::FleeFromBattle < Battle::Move
  def pbMoveFailed?(user, targets)
    if !@battle.pbCanRun?(user.index) || (user.wild? && user.allAllies.length > 0)
      @battle.pbDisplay(_INTL("¡Pero ha fallado!"))
      return true
    end
    return false
  end

  def pbEffectGeneral(user)
    @battle.pbDisplay(_INTL("¡{1} ha huido del combate!", user.pbThis))
    @battle.decision = Battle::Outcome::FLEE
  end
end

#===============================================================================
# User switches out. If user is a wild Pokémon, ends the battle instead.
# (Teleport (Gen 8+))
#===============================================================================
class Battle::Move::SwitchOutUserStatusMove < Battle::Move
  def pbMoveFailed?(user, targets)
    if user.wild?
      if !@battle.pbCanRun?(user.index) || user.allAllies.length > 0
        @battle.pbDisplay(_INTL("¡Pero ha fallado!"))
        return true
      end
    elsif !@battle.pbCanChooseNonActive?(user.index) ||
          user.effects[PBEffects::Commanding] >= 0 || user.effects[PBEffects::CommandedBy] >= 0
      @battle.pbDisplay(_INTL("¡Pero ha fallado!"))
      return true
    end
    return false
  end

  def pbEffectGeneral(user)
    if user.wild?
      @battle.pbDisplay(_INTL("¡{1} ha huido del combate!", user.pbThis))
      @battle.decision = Battle::Outcome::FLEE
    end
  end

  def pbEndOfMoveUsageEffect(user, targets, numHits, switchedBattlers)
    return if user.wild?
    @battle.pbDisplay(_INTL("¡{1} volvió con {2}!", user.pbThis,
                            @battle.pbGetOwnerName(user.index)))
    @battle.pbPursuit(user.index)
    return if user.fainted?
    newPkmn = @battle.pbGetReplacementPokemonIndex(user.index)   # Owner chooses
    return if newPkmn < 0
    @battle.pbRecallAndReplace(user.index, newPkmn)
    @battle.pbClearChoice(user.index)   # Replacement Pokémon does nothing this round
    @battle.moldBreaker = false
    @battle.pbOnBattlerEnteringBattle(user.index)
    switchedBattlers.push(user.index)
  end
end

#===============================================================================
# After inflicting damage, user switches out. Ignores trapping moves.
# (Flip Turn, U-turn, Volt Switch)
#===============================================================================
class Battle::Move::SwitchOutUserDamagingMove < Battle::Move
  def pbEndOfMoveUsageEffect(user, targets, numHits, switchedBattlers)
    return if user.fainted? || numHits == 0 || @battle.pbAllFainted?(user.idxOpposingSide)
    targetSwitched = true
    targets.each do |b|
      targetSwitched = false if !switchedBattlers.include?(b.index)
    end
    return if targetSwitched
    return if !@battle.pbCanChooseNonActive?(user.index)
    return if user.effects[PBEffects::Commanding] >= 0 || user.effects[PBEffects::CommandedBy] >= 0
    @battle.pbDisplay(_INTL("¡{1} ha vuelto con {2}!", user.pbThis,
                            @battle.pbGetOwnerName(user.index)))
    @battle.pbPursuit(user.index)
    return if user.fainted?
    newPkmn = @battle.pbGetReplacementPokemonIndex(user.index)   # Owner chooses
    return if newPkmn < 0
    @battle.pbRecallAndReplace(user.index, newPkmn)
    @battle.pbClearChoice(user.index)   # Replacement Pokémon does nothing this round
    @battle.moldBreaker = false
    @battle.pbOnBattlerEnteringBattle(user.index)
    switchedBattlers.push(user.index)
  end
end

#===============================================================================
# Decreases the target's Attack and Special Attack by 1 stage each. Then, user
# switches out. Ignores trapping moves. (Parting Shot)
#===============================================================================
class Battle::Move::LowerTargetAtkSpAtk1SwitchOutUser < Battle::Move::TargetMultiStatDownMove
  def initialize(battle, move)
    super
    @statDown = [:ATTACK, 1, :SPECIAL_ATTACK, 1]
  end

  def pbEndOfMoveUsageEffect(user, targets, numHits, switchedBattlers)
    switcher = user
    targets.each do |b|
      next if switchedBattlers.include?(b.index)
      switcher = b if b.effects[PBEffects::MagicCoat] || b.effects[PBEffects::MagicBounce]
    end
    return if switcher.fainted? || numHits == 0
    return if !@battle.pbCanChooseNonActive?(switcher.index)
    return if user.effects[PBEffects::Commanding] >= 0 || user.effects[PBEffects::CommandedBy] >= 0
    @battle.pbDisplay(_INTL("¡{1} ha vuelto con {2}!", switcher.pbThis,
                            @battle.pbGetOwnerName(switcher.index)))
    @battle.pbPursuit(switcher.index)
    return if switcher.fainted?
    newPkmn = @battle.pbGetReplacementPokemonIndex(switcher.index)   # Owner chooses
    return if newPkmn < 0
    @battle.pbRecallAndReplace(switcher.index, newPkmn)
    @battle.pbClearChoice(switcher.index)   # Replacement Pokémon does nothing this round
    @battle.moldBreaker = false if switcher.index == user.index
    @battle.pbOnBattlerEnteringBattle(switcher.index)
    switchedBattlers.push(switcher.index)
  end
end

#===============================================================================
# User switches out. Various effects affecting the user are passed to the
# replacement. (Baton Pass)
#===============================================================================
class Battle::Move::SwitchOutUserPassOnEffects < Battle::Move
  def pbMoveFailed?(user, targets)
    if !@battle.pbCanChooseNonActive?(user.index) ||
       user.effects[PBEffects::Commanding] >= 0 || user.effects[PBEffects::CommandedBy] >= 0
      @battle.pbDisplay(_INTL("¡Pero ha fallado!"))
      return true
    end
    return false
  end

  def pbEndOfMoveUsageEffect(user, targets, numHits, switchedBattlers)
    return if user.fainted? || numHits == 0
    return if !@battle.pbCanChooseNonActive?(user.index)
    @battle.pbPursuit(user.index)
    return if user.fainted?
    newPkmn = @battle.pbGetReplacementPokemonIndex(user.index)   # Owner chooses
    return if newPkmn < 0
    @battle.pbRecallAndReplace(user.index, newPkmn, false, true)
    @battle.pbClearChoice(user.index)   # Replacement Pokémon does nothing this round
    @battle.moldBreaker = false
    @battle.pbOnBattlerEnteringBattle(user.index)
    switchedBattlers.push(user.index)
  end
end

#===============================================================================
# User turns 1/2 of max HP into a substitute (it has 1/4 of max HP). User
# switches out. (Shed Tail)
#===============================================================================
class Battle::Move::UserMakeSubstituteSwitchOutUser < Battle::Move
  def pbMoveFailed?(user, targets)
    if user.effects[PBEffects::Substitute] > 0
      @battle.pbDisplay(_INTL("¡Pero ha fallado!"))
      return true
    end
    @subLife = [(user.totalhp / 2.0).ceil, 1].max
    if user.hp <= @subLife
      @battle.pbDisplay(_INTL("¡Pero ha fallado!"))
      return true
    end
    if user.wild? || !@battle.pbCanChooseNonActive?(user.index)
      @battle.pbDisplay(_INTL("¡Pero ha fallado!"))
      return true
    end
    if user.effects[PBEffects::Commanding] >= 0 || user.effects[PBEffects::CommandedBy] >= 0
      @battle.pbDisplay(_INTL("¡Pero ha fallado!"))
      return true
    end
    return false
  end

  def pbOnStartUse(user, targets)
    user.pbReduceHP(@subLife, false, false)
    user.pbItemHPHealCheck
  end

  def pbEffectGeneral(user)
    user.effects[PBEffects::Trapping]     = 0
    user.effects[PBEffects::TrappingMove] = nil
    user.effects[PBEffects::Substitute]   = @subLife / 2
    @battle.pbDisplay(_INTL("¡{1} ha creado un sustituto!", user.pbThis))
  end

  def pbEndOfMoveUsageEffect(user, targets, numHits, switchedBattlers)
    return if user.wild? || !@battle.pbCanChooseNonActive?(user.index)
    @battle.pbDisplay(_INTL("¡{1} ha vuelto con {2}!", user.pbThis,
                            @battle.pbGetOwnerName(user.index)))
    @battle.pbPursuit(user.index)
    return if user.fainted?
    newPkmn = @battle.pbGetReplacementPokemonIndex(user.index)   # Owner chooses
    return if newPkmn < 0
    user.effects[PBEffects::ShedTail] = true   # Ensures substitute isn't lost
    @battle.pbRecallAndReplace(user.index, newPkmn)
    user.effects[PBEffects::ShedTail] = false
    @battle.pbClearChoice(user.index)   # Replacement Pokémon does nothing this round
    @battle.moldBreaker = false
    @battle.pbOnBattlerEnteringBattle(user.index)
    switchedBattlers.push(user.index)
  end
end

#===============================================================================
# Starts snowstorm weather. User switches out. (Chilly Reception)
#===============================================================================
class Battle::Move::StartSnowstormWeatherSwitchOutUser < Battle::Move
  def pbDisplayChargeMessage(user)
    @battle.pbDisplay(_INTL("¡{1} se está preparando para contar un chiste escalofriantemente malo!", user.pbThis))
  end

  def pbMoveFailed?(user, targets)
    if user.wild? || !@battle.pbCanChooseNonActive?(user.index)
      weather = Settings::HAIL_WEATHER_TYPE == 0 ? :Hail : :Snowstorm 
      if !@battle.pbCanStartWeather?(weather)
        @battle.pbDisplay(_INTL("¡Pero ha fallado!"))
        return true
      end
    end
    return false
  end

  def pbEffectGeneral(user)
    weather = Settings::HAIL_WEATHER_TYPE == 0 ? :Hail : :Snowstorm 
    @battle.pbStartWeather(user, weather, true, false)
  end

  def pbEndOfMoveUsageEffect(user, targets, numHits, switchedBattlers)
    return if user.wild? || !@battle.pbCanChooseNonActive?(user.index)
    return if user.effects[PBEffects::Commanding] >= 0 || user.effects[PBEffects::CommandedBy] >= 0
    @battle.pbDisplay(_INTL("{1} ha vuelto con {2}!", user.pbThis,
                            @battle.pbGetOwnerName(user.index)))
    @battle.pbPursuit(user.index)
    return if user.fainted?
    newPkmn = @battle.pbGetReplacementPokemonIndex(user.index)   # Owner chooses
    return if newPkmn < 0
    @battle.pbRecallAndReplace(user.index, newPkmn)
    @battle.pbClearChoice(user.index)   # Replacement Pokémon does nothing this round
    @battle.moldBreaker = false
    @battle.pbOnBattlerEnteringBattle(user.index)
    switchedBattlers.push(user.index)
  end
end

#===============================================================================
# When used in a wild Pokémon battle with only 1 Pokémon on each side, makes
# target flee and ends the battle; fails if target is a higher level than the
# user.
# Otherwise, when used against a trainer's Pokémon, target switches out.
# For status moves. (Roar, Whirlwind)
#===============================================================================
class Battle::Move::SwitchOutTargetStatusMove < Battle::Move
  def ignoresSubstitute?(user); return true; end
  def canMagicCoat?;            return true; end

  def pbFailsAgainstTarget?(user, target, show_message)
    return true if !target.canBeForcedOutOfBattle?(show_message)
    if user.allAllies(true).length == 0 && target.allAllies(true).length == 0 &&
       @battle.wildBattle? && !@battle.rules[:cannot_run]
      # End the battle
      if target.level > user.level
        @battle.pbDisplay(_INTL("¡Pero ha fallado!")) if show_message
        return true
      end
    elsif target.wild?
      @battle.pbDisplay(_INTL("¡Pero ha fallado!")) if show_message
      return true
    else
      canSwitch = false
      @battle.eachInTeamFromBattlerIndex(target.index) do |_pkmn, i|
        canSwitch = @battle.pbCanSwitchIn?(target.index, i)
        break if canSwitch
      end
      if !canSwitch
        @battle.pbDisplay(_INTL("¡Pero ha fallado!")) if show_message
        return true
      end
    end
    return false
  end

  def pbEffectAgainstTarget(user, target)
    if user.allAllies(true).length == 0 && target.allAllies(true).length == 0 &&
       @battle.wildBattle? && !@battle.rules[:cannot_run]
      @battle.decision = Battle::Outcome::FLEE
    end
  end

  def pbSwitchOutTargetEffect(user, targets, numHits, switched_battlers)
    return if !switched_battlers.empty?
    return if user.fainted? || numHits == 0
    targets.each do |b|
      next if b.fainted? || b.damageState.unaffected
      next if b.wild?
      next if !b.canBeForcedOutOfBattle?(false)
      newPkmn = @battle.pbGetReplacementPokemonIndex(b.index, true)   # Random
      next if newPkmn < 0
      @battle.pbRecallAndReplace(b.index, newPkmn, true)
      @battle.pbDisplay(_INTL("¡{1} fue arrastrado al combate!", b.pbThis))
      @battle.pbClearChoice(b.index)   # Replacement Pokémon does nothing this round
      @battle.pbOnBattlerEnteringBattle(b.index)
      switched_battlers.push(b.index)
      break
    end
  end
end

#===============================================================================
# When used in a wild Pokémon battle with only 1 Pokémon on each side, makes
# target flee and ends the battle; fails if target is a higher level than the
# user.
# Otherwise, when used against a trainer's Pokémon, target switches out.
# For damaging moves. (Circle Throw, Dragon Tail)
#===============================================================================
class Battle::Move::SwitchOutTargetDamagingMove < Battle::Move
  def pbEffectAgainstTarget(user, target)
    if user.allAllies(true).length == 0 && target.allAllies(true).length == 0 &&
       @battle.wildBattle? && !@battle.rules[:cannot_run] &&
       target.level <= user.level &&
       (target.effects[PBEffects::Substitute] == 0 || ignoresSubstitute?(user))
      @battle.decision = Battle::Outcome::FLEE
    end
  end

  def pbSwitchOutTargetEffect(user, targets, numHits, switched_battlers)
    return if !switched_battlers.empty?
    return if user.fainted? || numHits == 0
    targets.each do |b|
      next if b.fainted? || b.damageState.unaffected || b.damageState.substitute
      next if b.wild?
      next if !b.canBeForcedOutOfBattle?(false)
      newPkmn = @battle.pbGetReplacementPokemonIndex(b.index, true)   # Random
      next if newPkmn < 0
      @battle.pbRecallAndReplace(b.index, newPkmn, true)
      @battle.pbDisplay(_INTL("¡{1} fue arrastrado al combate!", b.pbThis))
      @battle.pbClearChoice(b.index)   # Replacement Pokémon does nothing this round
      @battle.pbOnBattlerEnteringBattle(b.index)
      switched_battlers.push(b.index)
      break
    end
  end
end

#===============================================================================
# Trapping move. Traps for 5 or 6 rounds. Trapped Pokémon lose 1/16 of max HP
# at end of each round.
#===============================================================================
class Battle::Move::BindTarget < Battle::Move
  def pbEffectAgainstTarget(user, target)
    return if target.fainted? || target.damageState.substitute
    return if target.effects[PBEffects::Trapping] > 0
    # Set trapping effect duration and info
    if user.hasActiveItem?(:GRIPCLAW)
      target.effects[PBEffects::Trapping] = 8
    else
      target.effects[PBEffects::Trapping] = 5 + @battle.pbRandom(2)
    end
    target.effects[PBEffects::TrappingMove] = @id
    target.effects[PBEffects::TrappingUser] = user.index
    # Message
    msg = _INTL("¡{1} fue atrapado en el torbellino!", target.pbThis)
    case @id
    when :BIND
      msg = _INTL("¡Atadura de {1} oprime a {2}!", user.pbThis(true), target.pbThis(true))
    when :CLAMP
      msg = _INTL("¡{1} atenazó a {2}!", user.pbThis, target.pbThis(true))
    when :FIRESPIN
      msg = _INTL("¡{1} fue atrapado en el torbellino de fuego!", target.pbThis)
    when :INFESTATION
      msg = _INTL("¡{1} es presa del acoso de {2}!", target.pbThis, user.pbThis(true))
    when :MAGMASTORM
      msg = _INTL("¡Lluvia Ígnea atrapó a {1}!", target.pbThis(true))
    when :SANDTOMB
      msg = _INTL("¡Bucle Arena atrapó a {1}!", target.pbThis(true))
    when :WHIRLPOOL
      msg = _INTL("¡{1} fue atrapado en el torbellino!", target.pbThis)
    when :WRAP
      msg = _INTL("¡{1} fue atrapado por {2}!", target.pbThis, user.pbThis(true))
    end
    @battle.pbDisplay(msg)
  end
end

#===============================================================================
# Trapping move. Traps for 5 or 6 rounds. Trapped Pokémon lose 1/16 of max HP
# at end of each round. (Whirlpool)
# Power is doubled if target is using Dive. Hits some semi-invulnerable targets.
#===============================================================================
class Battle::Move::BindTargetDoublePowerIfTargetUnderwater < Battle::Move::BindTarget
  def hitsDivingTargets?; return true; end

  def pbModifyDamage(damageMult, user, target)
    damageMult *= 2 if target.inTwoTurnAttack?("TwoTurnAttackInvulnerableUnderwater")
    return damageMult
  end
end

#===============================================================================
# Target can no longer switch out or flee, as long as the user remains active.
# Trapping is considered an additional effect for damaging moves.
# (Anchor Shot, Block, Mean Look, Spider Web, Spirit Shackle)
#===============================================================================
class Battle::Move::TrapTargetInBattle < Battle::Move
  def canMagicCoat?; return true; end

  def pbFailsAgainstTarget?(user, target, show_message)
    return false if damagingMove?
    if target.effects[PBEffects::MeanLook] >= 0
      @battle.pbDisplay(_INTL("¡Pero ha fallado!")) if show_message
      return true
    end
    if Settings::MORE_TYPE_EFFECTS && target.pbHasType?(:GHOST)
      @battle.pbDisplay(_INTL("No afecta al {1}...", target.pbThis(true))) if show_message
      return true
    end
    return false
  end

  def pbEffectAgainstTarget(user, target)
    return if damagingMove?
    target.effects[PBEffects::MeanLook] = user.index
    @battle.pbDisplay(_INTL("¡{1} no puede escapar!", target.pbThis))
  end

  def pbAdditionalEffect(user, target)
    return if target.fainted? || target.damageState.substitute
    return if target.effects[PBEffects::MeanLook] >= 0
    return if Settings::MORE_TYPE_EFFECTS && target.pbHasType?(:GHOST)
    target.effects[PBEffects::MeanLook] = user.index
    @battle.pbDisplay(_INTL("¡{1} no puede escapar!", target.pbThis))
  end
end

