#===============================================================================
# Base class for all three menu classes below
#===============================================================================
class Battle::Scene::MenuBase
  attr_accessor :x
  attr_accessor :y
  attr_reader   :z
  attr_reader   :visible
  attr_reader   :color
  attr_reader   :index
  attr_reader   :mode

  # NOTE: Button width is half the width of the graphic containing them all.
  BUTTON_HEIGHT = 46
  TEXT_BASE_COLOR   = Battle::Scene::MESSAGE_BASE_COLOR
  TEXT_SHADOW_COLOR = Battle::Scene::MESSAGE_SHADOW_COLOR
  # Common menu dimensions
  MENU_HEIGHT = 96

  def initialize(viewport = nil)
    @x          = 0
    @y          = 0
    @z          = 0
    @visible    = false
    @color      = Color.new(0, 0, 0, 0)
    @index      = 0
    @mode       = 0
    @disposed   = false
    @sprites    = {}
    @visibility = {}
  end

  def dispose
    return if disposed?
    pbDisposeSpriteHash(@sprites)
    @disposed = true
  end

  def disposed?; return @disposed; end

  def z=(value)
    @z = value
    @sprites.each do |i|
      i[1].z = value if !i[1].disposed?
    end
  end

  def visible=(value)
    @visible = value
    @sprites.each do |i|
      i[1].visible = (value && @visibility[i[0]]) if !i[1].disposed?
    end
  end

  def color=(value)
    @color = value
    @sprites.each do |i|
      i[1].color = value if !i[1].disposed?
    end
  end

  def index=(value)
    oldValue = @index
    @index = value
    @cmdWindow.index = @index if @cmdWindow
    refresh if @index != oldValue
  end

  def mode=(value)
    oldValue = @mode
    @mode = value
    refresh if @mode != oldValue
  end

  def addSprite(key, sprite)
    @sprites[key]    = sprite
    @visibility[key] = true
  end

  def setIndexAndMode(index, mode)
    oldIndex = @index
    oldMode  = @mode
    @index = index
    @mode  = mode
    @cmdWindow.index = @index if @cmdWindow
    refresh if @index != oldIndex || @mode != oldMode
  end

  def refresh; end

  def update
    pbUpdateSpriteHash(@sprites)
  end
end

#===============================================================================
# Command menu (Fight/Pokémon/Bag/Run)
#===============================================================================
class Battle::Scene::CommandMenu < Battle::Scene::MenuBase
  attr_accessor :buttons
  # If true, displays graphics from Graphics/UI/Battle/overlay_command.png
  #     and Graphics/UI/Battle/cursor_command.png.
  # If false, just displays text and the command window over the graphic
  #     Graphics/UI/Battle/overlay_message.png. You will need to edit def
  #     pbShowWindow to make the graphic appear while the command menu is being
  #     displayed.
  USE_GRAPHICS = true
  # Lists of which button graphics to use in different situations/types of battle.
  MODES = [
    [0, 2, 1, 3],   # 0 = Regular battle
    [0, 2, 1, 9],   # 1 = Regular battle with "Cancel" instead of "Run"
    [0, 2, 1, 4],   # 2 = Regular battle with "Call" instead of "Run"
    [5, 7, 6, 3],   # 3 = Safari Zone
    [0, 8, 1, 3]    # 4 = Bug-Catching Contest
  ]

  # Layout Command
  TEXT_OFFSET_X      = 12
  TEXT_OFFSET_Y      = 2
  TEXT_WIDTH         = 240
  BUTTON_X_START     = 260
  BUTTON_Y_OFFSET    = 6
  BUTTON_X_OVERLAP   = 4
  BUTTON_Y_OVERLAP   = 4
  WINDOW_WIDTH       = 240
  WINDOW_COL_SPACING = 4

  def initialize(viewport, z)
    super(viewport)
    self.x = 0
    self.y = Graphics.height - MENU_HEIGHT
    # Create message box (shows "What will X do?")
    @msgBox = Window_UnformattedTextPokemon.newWithSize(
      "", self.x + TEXT_OFFSET_X, self.y + TEXT_OFFSET_Y, TEXT_WIDTH, Graphics.height - self.y, viewport
    )
    @msgBox.baseColor   = TEXT_BASE_COLOR
    @msgBox.shadowColor = TEXT_SHADOW_COLOR
    @msgBox.windowskin  = nil
    addSprite("msgBox", @msgBox)
    if USE_GRAPHICS
      # Create background graphic
      background = IconSprite.new(self.x, self.y, viewport)
      background.setBitmap("Graphics/UI/Battle/overlay_command")
      addSprite("background", background)
      # Create bitmaps
      @buttonBitmap = AnimatedBitmap.new(_INTL("Graphics/UI/Battle/cursor_command"))
      # Create action buttons
      @buttons = Array.new(4) do |i|   # 4 command options, therefore 4 buttons
        button = Sprite.new(viewport)
        button.bitmap = @buttonBitmap.bitmap
        button.x = self.x + Graphics.width - BUTTON_X_START
        button.x += (i.even? ? 0 : (@buttonBitmap.width / 2) - BUTTON_X_OVERLAP)
        button.y = self.y + BUTTON_Y_OFFSET
        button.y += (((i / 2) == 0) ? 0 : BUTTON_HEIGHT - BUTTON_Y_OVERLAP)
        button.src_rect.width  = @buttonBitmap.width / 2
        button.src_rect.height = BUTTON_HEIGHT
        addSprite("button_#{i}", button)
        next button
      end
    else
      # Create command window (shows Fight/Bag/Pokémon/Run)
      @cmdWindow = Window_CommandPokemon.newWithSize(
        [], self.x + Graphics.width - WINDOW_WIDTH, self.y, WINDOW_WIDTH, Graphics.height - self.y, viewport
      )
      @cmdWindow.columns       = 2
      @cmdWindow.columnSpacing = WINDOW_COL_SPACING
      @cmdWindow.ignore_input  = true
      addSprite("cmdWindow", @cmdWindow)
    end
    self.z = z
    refresh
  end

  def dispose
    super
    @buttonBitmap&.dispose
  end

  def z=(value)
    super
    @msgBox.z    += 1
    @cmdWindow.z += 1 if @cmdWindow
  end

  def setTexts(value)
    @msgBox.text = value[0]
    return if USE_GRAPHICS
    commands = []
    (1..4).each { |i| commands.push(value[i]) if value[i] }
    @cmdWindow.commands = commands
  end

  def refreshButtons
    return if !USE_GRAPHICS
    @buttons.each_with_index do |button, i|
      button.src_rect.x = (i == @index) ? @buttonBitmap.width / 2 : 0
      button.src_rect.y = MODES[@mode][i] * BUTTON_HEIGHT
      button.z          = self.z + ((i == @index) ? 3 : 2)
    end
  end

  def refresh
    @msgBox.refresh
    @cmdWindow&.refresh
    refreshButtons
  end
end

#===============================================================================
# Fight menu (choose a move)
#===============================================================================
class Battle::Scene::FightMenu < Battle::Scene::MenuBase
  attr_reader :battler
  attr_reader :shiftMode
  attr_accessor :buttons

  GET_MOVE_TEXT_COLOR_FROM_MOVE_BUTTON = false

  # If true, displays graphics from Graphics/UI/Battle/overlay_fight.png
  #     and Graphics/UI/Battle/cursor_fight.png.
  # If false, just displays text and the command window over the graphic
  #     Graphics/UI/Battle/overlay_message.png. You will need to edit def
  #     pbShowWindow to make the graphic appear while the command menu is being
  #     displayed.
  USE_GRAPHICS     = true
  TYPE_ICON_HEIGHT = 28
  # Text colours of PP of selected move
  PP_COLORS = [
    Color.new(248, 72, 72), Color.new(136, 48, 48),    # Red, zero PP
    Color.new(248, 136, 32), Color.new(144, 72, 24),   # Orange, 1/4 of total PP or less
    Color.new(248, 192, 0), Color.new(144, 104, 0),    # Yellow, 1/2 of total PP or less
    TEXT_BASE_COLOR, TEXT_SHADOW_COLOR                 # Black, more than 1/2 of total PP
  ]

  # Layout Figth
  BUTTON_X_OFFSET     = 4
  BUTTON_Y_OFFSET     = 6
  BUTTON_X_OVERLAP    = 4
  BUTTON_Y_OVERLAP    = 4
  TYPE_ICON_X         = 416
  TYPE_ICON_Y         = 20
  MEGA_BUTTON_X       = 120
  MEGA_BUTTON_SHIFT_X = 204
  SHIFT_BUTTON_X      = 4
  TEXT_Y_OFFSET       = 14
  PP_TEXT_X           = 448
  PP_TEXT_Y           = 56
  
  # Windows
  WINDOW_X_OFFSET     = 320
  WINDOW_WIDTH        = 320
  WINDOW_COL_SPACING  = 4

  # Pixel check coordinates for text color
  PIXEL_CHECK_X       = 10
  PIXEL_CHECK_Y       = 34

  def initialize(viewport, z)
    super(viewport)
    self.x = 0
    self.y = Graphics.height - MENU_HEIGHT
    @battler   = nil
    @shiftMode = 0
    # NOTE: @mode is for the display of the Mega Evolution button.
    #       0=don't show, 1=show unpressed, 2=show pressed
    if USE_GRAPHICS
      # Create bitmaps
      @buttonBitmap  = AnimatedBitmap.new(_INTL("Graphics/UI/Battle/cursor_fight"))
      @typeBitmap    = AnimatedBitmap.new(_INTL("Graphics/UI/types"))
      @megaEvoBitmap = AnimatedBitmap.new(_INTL("Graphics/UI/Battle/cursor_mega"))
      @shiftBitmap   = AnimatedBitmap.new(_INTL("Graphics/UI/Battle/cursor_shift"))
      # Create background graphic
      background = IconSprite.new(0, Graphics.height - MENU_HEIGHT, viewport)
      background.setBitmap("Graphics/UI/Battle/overlay_fight")
      addSprite("background", background)
      # Create move buttons
      @buttons = Array.new(Pokemon::MAX_MOVES) do |i|
        button = Sprite.new(viewport)
        button.bitmap = @buttonBitmap.bitmap
        button.x = self.x + BUTTON_X_OFFSET
        button.x += (i.even? ? 0 : (@buttonBitmap.width / 2) - BUTTON_X_OVERLAP)
        button.y = self.y + BUTTON_Y_OFFSET
        button.y += (((i / 2) == 0) ? 0 : BUTTON_HEIGHT - BUTTON_Y_OVERLAP)
        button.src_rect.width  = @buttonBitmap.width / 2
        button.src_rect.height = BUTTON_HEIGHT
        addSprite("button_#{i}", button)
        next button
      end
      # Create overlay for buttons (shows move names)
      @overlay = BitmapSprite.new(Graphics.width, Graphics.height - self.y, viewport)
      @overlay.x = self.x
      @overlay.y = self.y
      pbSetNarrowFont(@overlay.bitmap)
      addSprite("overlay", @overlay)
      # Create overlay for selected move's info (shows move's PP)
      @infoOverlay = BitmapSprite.new(Graphics.width, Graphics.height - self.y, viewport)
      @infoOverlay.x = self.x
      @infoOverlay.y = self.y
      pbSetNarrowFont(@infoOverlay.bitmap)
      addSprite("infoOverlay", @infoOverlay)
      # Create type icon
      @typeIcon = Sprite.new(viewport)
      @typeIcon.bitmap = @typeBitmap.bitmap
      @typeIcon.x      = self.x + TYPE_ICON_X
      @typeIcon.y      = self.y + TYPE_ICON_Y
      @typeIcon.src_rect.height = TYPE_ICON_HEIGHT
      addSprite("typeIcon", @typeIcon)
      # Create Mega Evolution button
      @megaButton = Sprite.new(viewport)
      @megaButton.bitmap = @megaEvoBitmap.bitmap
      @megaButton.x      = self.x + MEGA_BUTTON_X
      @megaButton.y      = self.y - (@megaEvoBitmap.height / 2)
      @megaButton.src_rect.height = @megaEvoBitmap.height / 2
      addSprite("megaButton", @megaButton)
      # Create Shift button
      @shiftButton = Sprite.new(viewport)
      @shiftButton.bitmap = @shiftBitmap.bitmap
      @shiftButton.x      = self.x + SHIFT_BUTTON_X
      @shiftButton.y      = self.y - @shiftBitmap.height
      addSprite("shiftButton", @shiftButton)
    else
      # Create message box (shows type and PP of selected move)
      @msgBox = Window_AdvancedTextPokemon.newWithSize(
        "", self.x + WINDOW_X_OFFSET, self.y, Graphics.width - WINDOW_X_OFFSET, Graphics.height - self.y, viewport
      )
      @msgBox.baseColor   = TEXT_BASE_COLOR
      @msgBox.shadowColor = TEXT_SHADOW_COLOR
      pbSetNarrowFont(@msgBox.contents)
      addSprite("msgBox", @msgBox)
      # Create command window (shows moves)
      @cmdWindow = Window_CommandPokemon.newWithSize(
        [], self.x, self.y, WINDOW_WIDTH, Graphics.height - self.y, viewport
      )
      @cmdWindow.columns       = 2
      @cmdWindow.columnSpacing = WINDOW_COL_SPACING
      @cmdWindow.ignore_input  = true
      pbSetNarrowFont(@cmdWindow.contents)
      addSprite("cmdWindow", @cmdWindow)
    end
    self.z = z
  end

  def dispose
    super
    @buttonBitmap&.dispose
    @typeBitmap&.dispose
    @megaEvoBitmap&.dispose
    @shiftBitmap&.dispose
  end

  def z=(value)
    super
    @msgBox.z      += 1 if @msgBox
    @cmdWindow.z   += 2 if @cmdWindow
    @overlay.z     += 5 if @overlay
    @infoOverlay.z += 6 if @infoOverlay
    @typeIcon.z    += 1 if @typeIcon
  end

  def battler=(value)
    @battler = value
    refresh
    refreshButtonNames
  end

  def shiftMode=(value)
    oldValue = @shiftMode
    @shiftMode = value
    refreshShiftButton if @shiftMode != oldValue
  end

  def refreshButtonNames
    moves = (@battler) ? @battler.moves : []
    if !USE_GRAPHICS
      # Fill in command window
      commands = []
      [4, moves.length].max.times do |i|
        commands.push((moves[i]) ? moves[i].name : "-")
      end
      @cmdWindow.commands = commands
      return
    end
    # Draw move names onto overlay
    @overlay.bitmap.clear
    textPos = []
    @buttons.each_with_index do |button, i|
      next if !@visibility["button_#{i}"]
      x = button.x - self.x + (button.src_rect.width / 2)
      y = button.y - self.y + TEXT_Y_OFFSET
      moveNameBase = TEXT_BASE_COLOR
      if GET_MOVE_TEXT_COLOR_FROM_MOVE_BUTTON && moves[i].display_type(@battler)
        # NOTE: This takes a color from a particular pixel in the button
        #       graphic and makes the move name's base color that same color.
        #       The pixel is at coordinates 10,34 in the button box. If you
        #       change the graphic, you may want to change the below line of
        #       code to ensure the font is an appropriate color.
        moveNameBase = button.bitmap.get_pixel(PIXEL_CHECK_X, button.src_rect.y + PIXEL_CHECK_Y)
      end
      textPos.push([moves[i].name, x, y, :center, moveNameBase, TEXT_SHADOW_COLOR])
    end
    pbDrawTextPositions(@overlay.bitmap, textPos)
  end

  def refreshSelection
    moves = (@battler) ? @battler.moves : []
    if USE_GRAPHICS
      # Choose appropriate button graphics and z positions
      @buttons.each_with_index do |button, i|
        if !moves[i]
          @visibility["button_#{i}"] = false
          next
        end
        @visibility["button_#{i}"] = true
        button.src_rect.x = (i == @index) ? @buttonBitmap.width / 2 : 0
        button.src_rect.y = GameData::Type.get(moves[i].display_type(@battler)).icon_position * BUTTON_HEIGHT
        button.z          = self.z + ((i == @index) ? 4 : 3)
      end
    end
    refreshMoveData(moves[@index])
  end

  def refreshMoveData(move)
    # Write PP and type of the selected move
    if !USE_GRAPHICS
      return if !move
      moveType = GameData::Type.get(move.display_type(@battler)).name
      if move.total_pp <= 0
        @msgBox.text = _INTL("PP: ---<br>TIPO/{1}", moveType)
      else
        @msgBox.text = _ISPRINTF("PP: {1: 2d}/{2: 2d}<br>TIPO/{3:s}",
                                 move.pp, move.total_pp, moveType)
      end
      return
    end
    @infoOverlay.bitmap.clear
    if !move
      @visibility["typeIcon"] = false
      return
    end
    @visibility["typeIcon"] = true
    # Type icon
    type_number = GameData::Type.get(move.display_type(@battler)).icon_position
    @typeIcon.src_rect.y = type_number * TYPE_ICON_HEIGHT
    # PP text
    if move.total_pp > 0
      ppFraction = [(4.0 * move.pp / move.total_pp).ceil, 3].min
      textPos = []
      textPos.push([_INTL("PP: {1}/{2}", move.pp, move.total_pp),
                    PP_TEXT_X, PP_TEXT_Y, :center, PP_COLORS[ppFraction * 2], PP_COLORS[(ppFraction * 2) + 1]])
      pbDrawTextPositions(@infoOverlay.bitmap, textPos)
    end
  end

  def refreshMegaEvolutionButton
    return if !USE_GRAPHICS
    @megaButton.src_rect.y    = (@mode - 1) * @megaEvoBitmap.height / 2
    @megaButton.x             = self.x + ((@shiftMode > 0) ? MEGA_BUTTON_SHIFT_X : MEGA_BUTTON_X)
    @megaButton.z             = self.z - 1
    @visibility["megaButton"] = (@mode > 0)
  end

  def refreshShiftButton
    return if !USE_GRAPHICS
    @shiftButton.src_rect.y    = (@shiftMode - 1) * @shiftBitmap.height
    @shiftButton.z             = self.z - 1
    @visibility["shiftButton"] = (@shiftMode > 0)
  end

  def refresh(refresh_button_names = false)
    return if !@battler
    refreshSelection
    refreshButtonNames if refresh_button_names
    refreshMegaEvolutionButton
    refreshShiftButton
  end
end

#===============================================================================
# Target menu (choose a move's target)
# NOTE: Unlike the command and fight menus, this one doesn't have a textbox-only
#       version.
#===============================================================================
class Battle::Scene::TargetMenu < Battle::Scene::MenuBase
  attr_accessor :mode
  attr_accessor :buttons

  # Lists of which button graphics to use in different situations/types of battle.
  MODES = [
    [0, 2, 1, 3],   # 0 = Regular battle
    [0, 2, 1, 9],   # 1 = Regular battle with "Cancel" instead of "Run"
    [0, 2, 1, 4],   # 2 = Regular battle with "Call" instead of "Run"
    [5, 7, 6, 3],   # 3 = Safari Zone
    [0, 8, 1, 3]    # 4 = Bug-Catching Contest
  ]
  CMD_BUTTON_WIDTH_SMALL = 170
  TEXT_BASE_COLOR   = Color.new(240, 248, 224)
  TEXT_SHADOW_COLOR = Color.new(64, 64, 64)
  
  # Layout Target
  BUTTON_Y_OFFSET         = 6
  BUTTON_Y_OVERLAP        = 4
  BUTTON_X_START_SMALL    = 170
  BUTTON_X_START_NORMAL   = 138
  BUTTON_OFFSETS_SMALL    = [0, 82, 166]
  BUTTON_OFFSETS_NORMAL   = [0, 116]
  BUTTON_OVERLAP_X_OFFSET = 4
  TEXT_Y_OFFSET           = 14

  def initialize(viewport, z, sideSizes)
    super(viewport)
    @sideSizes = sideSizes
    maxIndex = (@sideSizes[0] > @sideSizes[1]) ? (@sideSizes[0] - 1) * 2 : (@sideSizes[1] * 2) - 1
    @smallButtons = (@sideSizes.max > 2)
    self.x = 0
    self.y = Graphics.height - MENU_HEIGHT
    @texts = []
    # NOTE: @mode is for which buttons are shown as selected.
    #       0=select 1 button (@index), 1=select all buttons with text
    # Create bitmaps
    @buttonBitmap = AnimatedBitmap.new("Graphics/UI/Battle/cursor_target")
    # Create target buttons
    @buttons = Array.new(maxIndex + 1) do |i|
      numButtons = @sideSizes[i % 2]
      next if numButtons <= i / 2
      # NOTE: Battler indices go from left to right from the perspective of
      #       that side's trainer, so inc is different for each side for the
      #       same value of i/2.
      inc = (i.even?) ? i / 2 : numButtons - 1 - (i / 2)
      button = Sprite.new(viewport)
      button.bitmap = @buttonBitmap.bitmap
      button.src_rect.width  = (@smallButtons) ? CMD_BUTTON_WIDTH_SMALL : @buttonBitmap.width / 2
      button.src_rect.height = BUTTON_HEIGHT
      if @smallButtons
        button.x    = self.x + BUTTON_X_START_SMALL - BUTTON_OFFSETS_SMALL[numButtons - 1]
      else
        button.x    = self.x + BUTTON_X_START_NORMAL - BUTTON_OFFSETS_NORMAL[numButtons - 1]
      end
      button.x += (button.src_rect.width - BUTTON_OVERLAP_X_OFFSET) * inc
      button.y = self.y + BUTTON_Y_OFFSET
      button.y += (BUTTON_HEIGHT - BUTTON_Y_OVERLAP) * ((i + 1) % 2)
      addSprite("button_#{i}", button)
      next button
    end
    # Create overlay (shows target names)
    @overlay = BitmapSprite.new(Graphics.width, Graphics.height - self.y, viewport)
    @overlay.x = self.x
    @overlay.y = self.y
    pbSetNarrowFont(@overlay.bitmap)
    addSprite("overlay", @overlay)
    self.z = z
    refresh
  end

  def dispose
    super
    @buttonBitmap&.dispose
  end

  def z=(value)
    super
    @overlay.z += 5 if @overlay
  end

  def setDetails(texts, mode)
    @texts = texts
    @mode  = mode
    refresh
  end

  def refreshButtons
    # Choose appropriate button graphics and z positions
    @buttons.each_with_index do |button, i|
      next if !button
      sel = false
      buttonType = 0
      if @texts[i]
        sel ||= (@mode == 0 && i == @index)
        sel ||= (@mode == 1)
        buttonType = (i.even?) ? 1 : 2
      end
      buttonType = (2 * buttonType) + ((@smallButtons) ? 1 : 0)
      button.src_rect.x = (sel) ? @buttonBitmap.width / 2 : 0
      button.src_rect.y = buttonType * BUTTON_HEIGHT
      button.z          = self.z + ((sel) ? 3 : 2)
    end
    # Draw target names onto overlay
    @overlay.bitmap.clear
    textpos = []
    @buttons.each_with_index do |button, i|
      next if !button || nil_or_empty?(@texts[i])
      x = button.x - self.x + (button.src_rect.width / 2)
      y = button.y - self.y + TEXT_Y_OFFSET
      textpos.push([@texts[i], x, y, :center, TEXT_BASE_COLOR, TEXT_SHADOW_COLOR])
    end
    pbDrawTextPositions(@overlay.bitmap, textpos)
  end

  def refresh
    refreshButtons
  end
end


==============================================================================
# Script: Battle_Scene_Objects
==============================================================================
#===============================================================================
# Data box for regular battles
#===============================================================================
class Battle::Scene::PokemonDataBox < Sprite
  attr_reader   :battler
  attr_accessor :selected

  # Time in seconds to fully fill the Exp bar (from empty).
  EXP_BAR_FILL_TIME = 1.75
  # Time in seconds for this data box to flash when the Exp fully fills.
  EXP_FULL_FLASH_DURATION = 0.2
  # Maximum time in seconds to make a change to the HP bar.
  HP_BAR_CHANGE_TIME = 1.0
  # Time (in seconds) for one complete sprite bob cycle (up and down) while
  # choosing a command for this battler or when this battler is being chosen as
  # a target. Set to nil to prevent bobbing.
  BOBBING_DURATION = 0.6
  # Height in pixels of a status icon
  STATUS_ICON_HEIGHT = 16
  # Text colors
  NAME_BASE_COLOR         = Color.new(72, 72, 72)
  NAME_SHADOW_COLOR       = Color.new(184, 184, 184)
  MALE_BASE_COLOR         = Color.new(48, 96, 216)
  MALE_SHADOW_COLOR       = NAME_SHADOW_COLOR
  FEMALE_BASE_COLOR       = Color.new(248, 88, 40)
  FEMALE_SHADOW_COLOR     = NAME_SHADOW_COLOR
  # Layout constants
  PLAYER_BOX_X_OFFSET = 244
  PLAYER_BOX_Y_OFFSET = 192
  PLAYER_BASE_X       = 34
  FOE_BOX_X           = -16
  FOE_BOX_Y           = 36
  FOE_BASE_X          = 16
  DATABOX_BASE_Z      = 150

  # Side size offsets
  SIDE_2_X_OFFSETS          = [-12, 12, 0, 0]
  SIDE_2_Y_OFFSETS_PERCENT  = [-20, -34, 34, 45]
  SIDE_2_Y_OFFSETS_NORMAL   = [-20, -34, 34, 20]
  SIDE_3_X_OFFSETS          = [-12, 12, -6, 6, 0, 0]
  SIDE_3_Y_OFFSETS          = [-42, -46, 4, 0, 50, 46]
  
  # Component relative positions
  HP_BAR_X          = 102
  HP_BAR_Y          = 40
  EXP_BAR_X         = 6
  EXP_BAR_Y         = 74
  HP_NUMBERS_X      = 80
  HP_NUMBERS_Y      = 52
  HP_NUMBERS_WIDTH  = 124
  HP_NUMBERS_HEIGHT = 16
  HP_PERCENT_X      = 131
  HP_PERCENT_Y      = 61
  HP_PERCENT_WIDTH  = 124
  HP_PERCENT_HEIGHT = 16 
  # Drawing coordinates
  NAME_X            = 8
  NAME_Y            = 12
  NAME_MAX_WIDTH    = 116
  LEVEL_ICON_X      = 140
  LEVEL_ICON_Y      = 16
  LEVEL_NUMBER_X    = 162
  LEVEL_NUMBER_Y    = 16
  GENDER_X          = 126
  GENDER_Y          = 12
  STATUS_ICON_X     = 24
  STATUS_ICON_Y     = 36
  SHINY_ICON_FOE_X  = 206
  SHINY_ICON_PLYR_X = -6
  SHINY_ICON_Y      = 36
  OWNED_ICON_X      = 8
  OWNED_ICON_Y      = 36
  MEGA_ICON_FOE_X   = 212
  MEGA_ICON_FOE_Y   = 8
  MEGA_ICON_PLYR_X  = -28
  MEGA_ICON_PLYR_Y  = 8
  PRIMAL_FOE_X      = 210
  PRIMAL_PLYR_X     = -30
  PRIMAL_ICON_Y     = 4
  # HP Number drawing
  HP_NUM_CURRENT_X  = 54
  HP_NUM_CURRENT_Y  = 2
  HP_NUM_MAX_X      = 70
  HP_NUM_MAX_Y      = 2

  def initialize(battler, sideSize, viewport = nil)
    super(viewport)
    @battler         = battler
    @sprites         = {}
    @spriteX         = 0
    @spriteY         = 0
    @spriteBaseX     = 0
    @selected        = 0
    @show_hp_numbers = false
    @show_hp_percent = false
    @show_exp_bar    = false
    initializeDataBoxGraphic(sideSize)
    initializeOtherGraphics(viewport)
    refresh
  end

  def initializeDataBoxGraphic(sideSize)
    onPlayerSide = @battler.index.even?
    # Get the data box graphic and set whether the HP numbers/Exp bar are shown
    if sideSize == 1   # One Pokémon on side, use the regular dara box BG
      if onPlayerSide
        @show_hp_numbers = true
        @show_exp_bar    = true
      else
        @show_hp_percent = Settings::SHOW_ENEMY_HP_PERCENTAGE
        foe_bitmap = @show_hp_percent ? _INTL("Graphics/UI/Battle/databox_normal_foe_percent") : _INTL("Graphics/UI/Battle/databox_normal_foe")
      end

      bgFilename = [_INTL("Graphics/UI/Battle/databox_normal"),
                    foe_bitmap][@battler.index % 2]

    else   # Multiple Pokémon on side, use the thin dara box BG
      foe_bitmap = Settings::SHOW_ENEMY_HP_PERCENTAGE && sideSize < 3 ? _INTL("Graphics/UI/Battle/databox_thin_foe_percent") : _INTL("Graphics/UI/Battle/databox_thin_foe")
      bgFilename = [_INTL("Graphics/UI/Battle/databox_thin"),
                    foe_bitmap][@battler.index % 2]
    end
    @databoxBitmap&.dispose
    @databoxBitmap = AnimatedBitmap.new(bgFilename)
    # Determine the co-ordinates of the data box and the left edge padding width
    if onPlayerSide
      @spriteX = Graphics.width - PLAYER_BOX_X_OFFSET
      @spriteY = Graphics.height - PLAYER_BOX_Y_OFFSET
      @spriteBaseX = PLAYER_BASE_X
    else
      @spriteX = FOE_BOX_X
      @spriteY = FOE_BOX_Y
      @spriteBaseX = FOE_BASE_X
      @show_hp_percent = Settings::SHOW_ENEMY_HP_PERCENTAGE && sideSize < 3
    end
    case sideSize
    when 2
      @spriteX += SIDE_2_X_OFFSETS[@battler.index]
      if @show_hp_percent
        @spriteY += SIDE_2_Y_OFFSETS_PERCENT[@battler.index]
      else
        @spriteY += SIDE_2_Y_OFFSETS_NORMAL[@battler.index]  
      end
    when 3
      @spriteX += SIDE_3_X_OFFSETS[@battler.index]
      @spriteY += SIDE_3_Y_OFFSETS[@battler.index]
    end
  end

  def initializeOtherGraphics(viewport)
    # Create other bitmaps
    @numbersBitmap = AnimatedBitmap.new("Graphics/UI/Battle/icon_numbers")
    @hpBarBitmap   = AnimatedBitmap.new("Graphics/UI/Battle/overlay_hp")
    @expBarBitmap  = AnimatedBitmap.new("Graphics/UI/Battle/overlay_exp")
    # Create sprite to draw HP numbers on
    @hpNumbers = BitmapSprite.new(HP_NUMBERS_WIDTH, HP_NUMBERS_HEIGHT, viewport)
    # pbSetSmallFont(@hpNumbers.bitmap)
    @sprites["hpNumbers"] = @hpNumbers

    @hpPercent = BitmapSprite.new(HP_PERCENT_WIDTH, HP_PERCENT_HEIGHT, viewport)
    pbSetSmallFont(@hpPercent.bitmap)
    @sprites["hpPercent"] = @hpPercent
    # Create sprite wrapper that displays HP bar
    @hpBar = Sprite.new(viewport)
    @hpBar.bitmap = @hpBarBitmap.bitmap
    @hpBar.src_rect.height = @hpBarBitmap.height / 3
    @sprites["hpBar"] = @hpBar
    # Create sprite wrapper that displays Exp bar
    @expBar = Sprite.new(viewport)
    @expBar.bitmap = @expBarBitmap.bitmap
    @sprites["expBar"] = @expBar
    # Create sprite wrapper that displays everything except the above
    @contents = Bitmap.new(@databoxBitmap.width, @databoxBitmap.height)
    self.bitmap  = @contents
    self.visible = false
    self.z       = DATABOX_BASE_Z + ((@battler.index / 2) * 5)
    pbSetSystemFont(self.bitmap)
  end

  def dispose
    pbDisposeSpriteHash(@sprites)
    @databoxBitmap.dispose
    @numbersBitmap.dispose
    @hpBarBitmap.dispose
    @hpPercent&.dispose
    @expBarBitmap.dispose
    @contents.dispose
    super
  end

  def x=(value)
    super
    @hpBar.x     = value + @spriteBaseX + HP_BAR_X
    @expBar.x    = value + @spriteBaseX + EXP_BAR_X
    @hpNumbers.x = value + @spriteBaseX + HP_NUMBERS_X
    @hpPercent&.x = value + @spriteBaseX + HP_PERCENT_X
  end

  def y=(value)
    super
    @hpBar.y     = value + HP_BAR_Y
    @expBar.y    = value + EXP_BAR_Y
    @hpNumbers.y = value + HP_NUMBERS_Y
    @hpPercent&.y = value + HP_PERCENT_Y  
  end

  def z=(value)
    super
    @hpBar.z     = value + 1
    @expBar.z    = value + 1
    @hpNumbers.z = value + 2
    @hpPercent&.z = value + 2
  end

  def opacity=(value)
    super
    @sprites.each do |i|
      i[1].opacity = value if !i[1].disposed?
    end
  end

  def visible=(value)
    super
    @sprites.each do |i|
      i[1].visible = value if !i[1].disposed?
    end
    @expBar.visible = (value && @show_exp_bar)
  end

  def color=(value)
    super
    @sprites.each do |i|
      i[1].color = value if !i[1].disposed?
    end
  end

  def battler=(b)
    @battler = b
    self.visible = (@battler && !@battler.fainted?)
  end

  def hp
    return (animating_hp?) ? @anim_hp_current : @battler.hp
  end

  def exp_fraction
    if animating_exp?
      return 0.0 if @anim_exp_range == 0
      return @anim_exp_current.to_f / @anim_exp_range
    end
    return @battler.pokemon.exp_fraction
  end

  # NOTE: A change in HP takes the same amount of time to animate, no matter how
  #       big a change it is.
  def animate_hp(old_val, new_val)
    return if old_val == new_val
    @anim_hp_start = old_val
    @anim_hp_end = new_val
    @anim_hp_current = old_val
    @anim_hp_timer_start = System.uptime
  end

  def animating_hp?
    return @anim_hp_timer_start != nil
  end

  # NOTE: Filling the Exp bar from empty to full takes EXP_BAR_FILL_TIME seconds
  #       no matter what. Filling half of it takes half as long, etc.
  def animate_exp(old_val, new_val, range)
    return if old_val == new_val || range == 0 || !@show_exp_bar
    @anim_exp_start = old_val
    @anim_exp_end = new_val
    @anim_exp_range = range
    @anim_exp_duration_mult = (new_val - old_val).abs / range.to_f
    @anim_exp_current = old_val
    @anim_exp_timer_start = System.uptime
    pbSEPlay("Pkmn exp gain") if @show_exp_bar
  end

  def animating_exp?
    return @anim_exp_timer_start != nil
  end

  def pbDrawNumber(number, btmp, startX, startY, align = :left)
    # -1 means draw the / character
    # -2 means draw the % character
    n = case number
    when -1
      [10]
    when -2
      [11]
    else
      number.to_i.digits.reverse
    end
    # n = (number == -1) ? [10] : number.to_i.digits.reverse
    charWidth  = @numbersBitmap.width / 12
    charHeight = @numbersBitmap.height
    startX -= charWidth * n.length if align == :right
    n.each do |i|
      btmp.blt(startX, startY, @numbersBitmap.bitmap, Rect.new(i * charWidth, 0, charWidth, charHeight))
      startX += charWidth
    end
  end

  def draw_background
    self.bitmap.blt(0, 0, @databoxBitmap.bitmap, Rect.new(0, 0, @databoxBitmap.width, @databoxBitmap.height))
  end

  def draw_name
    nameWidth = self.bitmap.text_size(@battler.name).width
    nameOffset = 0
    nameOffset = nameWidth - NAME_MAX_WIDTH if nameWidth > NAME_MAX_WIDTH
    pbDrawTextPositions(self.bitmap, [[@battler.name, @spriteBaseX + NAME_X - nameOffset, NAME_Y, :left,
                                       NAME_BASE_COLOR, NAME_SHADOW_COLOR]]
    )
  end

  def draw_level
    # "Lv" graphic
    pbDrawImagePositions(self.bitmap, [[_INTL("Graphics/UI/Battle/overlay_lv"), @spriteBaseX + LEVEL_ICON_X, LEVEL_ICON_Y]])
    # Level number
    pbDrawNumber(@battler.level, self.bitmap, @spriteBaseX + LEVEL_NUMBER_X, LEVEL_NUMBER_Y)
  end

  def draw_gender
    gender = @battler.displayGender
    return if ![0, 1].include?(gender)
    gender_text  = (gender == 0) ? _INTL("♂") : _INTL("♀")
    base_color   = (gender == 0) ? MALE_BASE_COLOR : FEMALE_BASE_COLOR
    shadow_color = (gender == 0) ? MALE_SHADOW_COLOR : FEMALE_SHADOW_COLOR
    pbDrawTextPositions(self.bitmap, [[gender_text, @spriteBaseX + GENDER_X, GENDER_Y, :left, base_color, shadow_color]])
  end

  def draw_status
    return if @battler.status == :NONE
    if @battler.status == :POISON && @battler.statusCount > 0   # Badly poisoned
      s = GameData::Status.count - 1
    else
      s = GameData::Status.get(@battler.status).icon_position
    end
    return if s < 0
    pbDrawImagePositions(self.bitmap, [[_INTL("Graphics/UI/Battle/icon_statuses"), @spriteBaseX + STATUS_ICON_X, STATUS_ICON_Y,
                                        0, s * STATUS_ICON_HEIGHT, -1, STATUS_ICON_HEIGHT]])
  end

  def draw_shiny_icon
    return if !@battler.shiny?
    shiny_x = (@battler.opposes?(0)) ? SHINY_ICON_FOE_X : SHINY_ICON_PLYR_X   # Foe's/player's
    pbDrawImagePositions(self.bitmap, [["Graphics/UI/shiny", @spriteBaseX + shiny_x, SHINY_ICON_Y]])
  end

  def draw_special_form_icon
    # Mega Evolution/Primal Reversion icon
    if @battler.mega?
      mega_x = (@battler.opposes?(0)) ? MEGA_ICON_FOE_X : MEGA_ICON_PLYR_X
      mega_y = (@battler.opposes?(0)) ? MEGA_ICON_FOE_Y  : MEGA_ICON_PLYR_Y
      pbDrawImagePositions(self.bitmap, [["Graphics/UI/Battle/icon_mega", @spriteBaseX + mega_x, mega_y]])
    elsif @battler.primal?
      filename = nil
      if @battler.isSpecies?(:GROUDON)
        filename = "Graphics/UI/Battle/icon_primal_Groudon"
      elsif @battler.isSpecies?(:KYOGRE)
        filename = "Graphics/UI/Battle/icon_primal_Kyogre"
      end
      primalX = (@battler.opposes?) ? PRIMAL_FOE_X : PRIMAL_PLYR_X   # Foe's/player's
      pbDrawImagePositions(self.bitmap, [[filename, @spriteBaseX + primalX, PRIMAL_ICON_Y]]) if filename
    end
  end

  def draw_owned_icon
    return if !@battler.owned? || !@battler.opposes?(0)   # Draw for foe Pokémon only
    pbDrawImagePositions(self.bitmap, [["Graphics/UI/Battle/icon_own", @spriteBaseX + OWNED_ICON_X, OWNED_ICON_Y]])
  end

  def refresh
    self.bitmap.clear
    return if !@battler.pokemon
    draw_background
    draw_name
    draw_level
    draw_gender
    draw_status
    draw_shiny_icon
    draw_special_form_icon
    draw_owned_icon
    refresh_hp
    refresh_exp
  end

  def refresh_hp
    @hpNumbers.bitmap.clear
    @hpPercent.bitmap.clear
    return if !@battler.pokemon
    # Show HP numbers
    if @show_hp_numbers
      pbDrawNumber(self.hp, @hpNumbers.bitmap, HP_NUM_CURRENT_X, HP_NUM_CURRENT_Y, :right)
      pbDrawNumber(-1, @hpNumbers.bitmap, HP_NUM_CURRENT_X, HP_NUM_CURRENT_Y)   # / char
      pbDrawNumber(@battler.totalhp, @hpNumbers.bitmap, HP_NUM_MAX_X, HP_NUM_MAX_Y)
    end
    if @show_hp_percent
      hp_percent_value = ((self.hp / @battler.totalhp.to_f) * 100).ceil.to_i
      pbDrawNumber(hp_percent_value, @hpPercent.bitmap, HP_NUM_CURRENT_X, HP_NUM_CURRENT_Y, :right)
      pbDrawNumber(-2, @hpPercent.bitmap, HP_NUM_CURRENT_X, HP_NUM_CURRENT_Y)   # % char
    end
    # Resize HP bar
    w = 0
    if self.hp > 0
      w = @hpBarBitmap.width.to_f * self.hp / @battler.totalhp
      w = 1 if w < 1
      # NOTE: The line below snaps the bar's width to the nearest 2 pixels, to
      #       fit in with the rest of the graphics which are doubled in size.
      w = ((w / 2.0).round) * 2
    end
    @hpBar.src_rect.width = w
    hpColor = 0                                      # Green bar
    hpColor = 1 if self.hp <= @battler.totalhp / 2   # Yellow bar
    hpColor = 2 if self.hp <= @battler.totalhp / 4   # Red bar
    @hpBar.src_rect.y = hpColor * @hpBarBitmap.height / 3
  end

  def refresh_exp
    return if !@show_exp_bar
    w = exp_fraction * @expBarBitmap.width
    # NOTE: The line below snaps the bar's width to the nearest 2 pixels, to
    #       fit in with the rest of the graphics which are doubled in size.
    w = ((w / 2).round) * 2
    @expBar.src_rect.width = w
  end

  def update_hp_animation
    return if !animating_hp?
    @anim_hp_current = lerp(@anim_hp_start, @anim_hp_end, HP_BAR_CHANGE_TIME,
                            @anim_hp_timer_start, System.uptime)
    # Refresh the HP bar/numbers
    refresh_hp
    # End the HP bar filling animation
    if @anim_hp_current == @anim_hp_end
      @anim_hp_start = nil
      @anim_hp_end = nil
      @anim_hp_timer_start = nil
      @anim_hp_current = nil
    end
  end

  def update_exp_animation
    return if !animating_exp?
    if !@show_exp_bar   # Not showing the Exp bar, no need to waste time animating it
      @anim_exp_timer_start = nil
      return
    end
    duration = EXP_BAR_FILL_TIME * @anim_exp_duration_mult
    @anim_exp_current = lerp(@anim_exp_start, @anim_exp_end, duration,
                             @anim_exp_timer_start, System.uptime)
    # Refresh the Exp bar
    refresh_exp
    return if @anim_exp_current != @anim_exp_end   # Exp bar still has more to animate
    # End the Exp bar filling animation
    if @anim_exp_current >= @anim_exp_range
      if @anim_exp_flash_timer_start
        # Waiting for Exp full flash to finish
        return if System.uptime - @anim_exp_flash_timer_start < EXP_FULL_FLASH_DURATION
      else
        # Show the Exp full flash
        @anim_exp_flash_timer_start = System.uptime
        pbSEStop
        pbSEPlay("Pkmn exp full")
        flash_duration = EXP_FULL_FLASH_DURATION * Graphics.frame_rate   # Must be in frames, not seconds
        self.flash(Color.new(64, 200, 248, 192), flash_duration)
        @sprites.each do |i|
          i[1].flash(Color.new(64, 200, 248, 192), flash_duration) if !i[1].disposed?
        end
        return
      end
    end
    pbSEStop if !@anim_exp_flash_timer_start
    @anim_exp_start = nil
    @anim_exp_end = nil
    @anim_exp_duration_mult = nil
    @anim_exp_current = nil
    @anim_exp_timer_start = nil
    @anim_exp_flash_timer_start = nil
  end

  def update_positions
    self.x = @spriteX
    self.y = @spriteY
    # Data box bobbing while Pokémon is selected
    if (@selected == 1 || @selected == 2) && BOBBING_DURATION   # Choosing commands/targeted
      bob_delta = System.uptime % BOBBING_DURATION   # 0-BOBBING_DURATION
      bob_frame = (4 * bob_delta / BOBBING_DURATION).floor
      case bob_frame
      when 1 then self.y = @spriteY - 2
      when 3 then self.y = @spriteY + 2
      end
    end
  end

  def update
    super
    # Animate HP bar
    update_hp_animation
    # Animate Exp bar
    update_exp_animation
    # Update coordinates of the data box
    update_positions
    pbUpdateSpriteHash(@sprites)
  end
end

#===============================================================================
# Splash bar to announce a triggered ability
#===============================================================================
class Battle::Scene::AbilitySplashBar < Sprite
  attr_reader :battler

  TEXT_BASE_COLOR   = Color.new(0, 0, 0)
  TEXT_SHADOW_COLOR = Color.new(248, 248, 248)

  # Layout Ability
  PLAYER_Y        = 180
  FOE_Y           = 80
  TEXT_X_OFFSET   = 10
  TEXT_X_MARGIN   = 8
  ABILITY_NAME_Y  = 8
  POKEMON_NAME_Y  = 38

  def initialize(side, viewport = nil)
    super(viewport)
    @side    = side
    @battler = nil
    # Create sprite wrapper that displays background graphic
    @bgBitmap = AnimatedBitmap.new("Graphics/UI/Battle/ability_bar")
    @bgSprite = Sprite.new(viewport)
    @bgSprite.bitmap = @bgBitmap.bitmap
    @bgSprite.src_rect.y      = (side == 0) ? 0 : @bgBitmap.height / 2
    @bgSprite.src_rect.height = @bgBitmap.height / 2
    # Create bitmap that displays the text
    @contents = Bitmap.new(@bgBitmap.width, @bgBitmap.height / 2)
    self.bitmap = @contents
    pbSetSystemFont(self.bitmap)
    # Position the bar
    self.x       = (side == 0) ? -Graphics.width / 2 : Graphics.width
    self.y       = (side == 0) ? PLAYER_Y : FOE_Y
    self.z       = 120
    self.visible = false
  end

  def dispose
    @bgSprite.dispose
    @bgBitmap.dispose
    @contents.dispose
    super
  end

  def x=(value)
    super
    @bgSprite.x = value
  end

  def y=(value)
    super
    @bgSprite.y = value
  end

  def z=(value)
    super
    @bgSprite.z = value - 1
  end

  def opacity=(value)
    super
    @bgSprite.opacity = value
  end

  def visible=(value)
    super
    @bgSprite.visible = value
  end

  def color=(value)
    super
    @bgSprite.color = value
  end

  def battler=(value)
    @battler = value
    refresh
  end

  def refresh
    self.bitmap.clear
    return if !@battler
    textPos = []
    textX = (@side == 0) ? TEXT_X_OFFSET : self.bitmap.width - TEXT_X_MARGIN
    align = (@side == 0) ? :left : :right
    # Draw Pokémon's ability
    textPos.push([@battler.abilityName, textX, ABILITY_NAME_Y, align,
                  TEXT_BASE_COLOR, TEXT_SHADOW_COLOR, :outline])
    # Draw Pokémon's name
    textPos.push([_INTL("de {1}", @battler.name), textX, POKEMON_NAME_Y, align,
                  TEXT_BASE_COLOR, TEXT_SHADOW_COLOR, :outline])
    pbDrawTextPositions(self.bitmap, textPos)
  end

  def update
    super
    @bgSprite.update
  end
end

#===============================================================================
# Pokémon sprite (used in battle)
#===============================================================================
class Battle::Scene::BattlerSprite < RPG::Sprite
  attr_reader   :pkmn
  attr_accessor :index
  attr_accessor :selected
  attr_reader   :sideSize

  # Time (in seconds) for one complete sprite bob cycle (up and down) while
  # choosing a command for this battler. Set to nil to prevent bobbing.
  COMMAND_BOBBING_DURATION = 0.6
  # Time (in seconds) for one complete blinking cycle while this battler is
  # being chosen as a target. Set to nil to prevent blinking.
  TARGET_BLINKING_DURATION = 0.3

  BATTLER_BASE_Z = 50

  def initialize(viewport, sideSize, index, battleAnimations)
    super(viewport)
    @pkmn             = nil
    @sideSize         = sideSize
    @index            = index
    @battleAnimations = battleAnimations
    # @selected: 0 = not selected, 1 = choosing action bobbing for this Pokémon,
    #            2 = flashing when targeted
    @selected         = 0
    @updating         = false
    @spriteX          = 0   # Actual x coordinate
    @spriteY          = 0   # Actual y coordinate
    @spriteXExtra     = 0   # Offset due to "bobbing" animation
    @spriteYExtra     = 0   # Offset due to "bobbing" animation
    @_iconBitmap      = nil
    self.visible      = false
  end

  def dispose
    @_iconBitmap&.dispose
    @_iconBitmap = nil
    self.bitmap = nil if !self.disposed?
    super
  end

  def x; return @spriteX; end
  def y; return @spriteY; end

  def x=(value)
    @spriteX = value
    super(value + @spriteXExtra)
  end

  def y=(value)
    @spriteY = value
    super(value + @spriteYExtra)
  end

  def width;  return (self.bitmap) ? self.bitmap.width : 0;  end
  def height; return (self.bitmap) ? self.bitmap.height : 0; end

  def visible=(value)
    @spriteVisible = value if !@updating   # For selection/targeting flashing
    super
  end

  # Set sprite's origin to bottom middle
  def pbSetOrigin
    return if !@_iconBitmap
    self.ox = @_iconBitmap.width / 2
    self.oy = @_iconBitmap.height
  end

  def pbSetPosition
    return if !@_iconBitmap
    pbSetOrigin
    if @index.even?
      self.z = BATTLER_BASE_Z + (5 * @index / 2)
    else
      self.z = BATTLER_BASE_Z - (5 * (@index + 1) / 2)
    end
    # Set original position
    p = Battle::Scene.pbBattlerPosition(@index, @sideSize)
    @spriteX = p[0]
    @spriteY = p[1]
    # Apply metrics
    @pkmn.species_data.apply_metrics_to_sprite(self, @index)
  end

  def setPokemonBitmap(pkmn, back = false)
    @pkmn = pkmn
    @_iconBitmap&.dispose
    @_iconBitmap = GameData::Species.sprite_bitmap_from_pokemon(@pkmn, back)
    self.bitmap = (@_iconBitmap) ? @_iconBitmap.bitmap : nil
    pbSetPosition
  end

  # This method plays the battle entrance animation of a Pokémon. By default
  # this is just playing the Pokémon's cry, but you can expand on it. The
  # recommendation is to create a PictureEx animation and push it into
  # the @battleAnimations array.
  def pbPlayIntroAnimation(pictureEx = nil)
    @pkmn&.play_cry
  end

  def update
    return if !@_iconBitmap
    @updating = true
    # Update bitmap
    @_iconBitmap.update
    self.bitmap = @_iconBitmap.bitmap
    # Pokémon sprite bobbing while Pokémon is selected
    @spriteYExtra = 0
    if @selected == 1 && COMMAND_BOBBING_DURATION    # When choosing commands for this Pokémon
      bob_delta = System.uptime % COMMAND_BOBBING_DURATION   # 0-COMMAND_BOBBING_DURATION
      bob_frame = (4 * bob_delta / COMMAND_BOBBING_DURATION).floor
      case bob_frame
      when 1 then @spriteYExtra = 2
      when 3 then @spriteYExtra = -2
      end
    end
    self.x       = self.x
    self.y       = self.y
    self.visible = @spriteVisible
    # Pokémon sprite blinking when targeted
    if @selected == 2 && @spriteVisible && TARGET_BLINKING_DURATION
      blink_delta = System.uptime % TARGET_BLINKING_DURATION   # 0-TARGET_BLINKING_DURATION
      blink_frame = (3 * blink_delta / TARGET_BLINKING_DURATION).floor
      self.visible = (blink_frame != 0)
    end
    @updating = false
  end
end

#===============================================================================
# Shadow sprite for Pokémon (used in battle)
#===============================================================================
class Battle::Scene::BattlerShadowSprite < RPG::Sprite
  attr_reader   :pkmn
  attr_accessor :index
  attr_accessor :selected

  def initialize(viewport, sideSize, index)
    super(viewport)
    @pkmn        = nil
    @sideSize    = sideSize
    @index       = index
    @_iconBitmap = nil
    self.visible = false
  end

  def dispose
    @_iconBitmap&.dispose
    @_iconBitmap = nil
    self.bitmap = nil if !self.disposed?
    super
  end

  def width;  return (self.bitmap) ? self.bitmap.width : 0;  end
  def height; return (self.bitmap) ? self.bitmap.height : 0; end

  # Set sprite's origin to centre
  def pbSetOrigin
    return if !@_iconBitmap
    self.ox = @_iconBitmap.width / 2
    self.oy = @_iconBitmap.height / 2
  end

  def pbSetPosition
    return if !@_iconBitmap
    pbSetOrigin
    self.z = 3
    # Set original position
    p = Battle::Scene.pbBattlerPosition(@index, @sideSize)
    self.x = p[0]
    self.y = p[1]
    # Apply metrics
    @pkmn.species_data.apply_metrics_to_sprite(self, @index, true)
  end

  def setPokemonBitmap(pkmn)
    @pkmn = pkmn
    @_iconBitmap&.dispose
    @_iconBitmap = GameData::Species.shadow_bitmap_from_pokemon(@pkmn)
    self.bitmap = (@_iconBitmap) ? @_iconBitmap.bitmap : nil
    pbSetPosition
  end

  def update
    return if !@_iconBitmap
    # Update bitmap
    @_iconBitmap.update
    self.bitmap = @_iconBitmap.bitmap
  end
end


==============================================================================
# Script: Battle_Scene_BaseAnimation
==============================================================================
#===============================================================================
# Base class for all hardcoded battle animations.
#===============================================================================
class Battle::Scene::Animation
  def initialize(sprites, viewport)
    @sprites  = sprites
    @viewport = viewport
    @pictureEx      = []   # For all the PictureEx
    @pictureSprites = []   # For all the sprites
    @tempSprites    = []   # For sprites that exist only for this animation
    @animDone       = false
    createProcesses
  end

  def dispose
    @tempSprites.each { |s| s&.dispose }
  end

  def createProcesses; end
  def empty?; return @pictureEx.length == 0; end
  def animDone?; return @animDone; end

  def addSprite(s, origin = PictureOrigin::TOP_LEFT)
    num = @pictureEx.length
    picture = PictureEx.new(s.z)
    picture.x       = s.x
    picture.y       = s.y
    picture.visible = s.visible
    picture.color   = s.color.clone
    picture.tone    = s.tone.clone
    picture.setOrigin(0, origin)
    @pictureEx[num] = picture
    @pictureSprites[num] = s
    return picture
  end

  def addNewSprite(x, y, name, origin = PictureOrigin::TOP_LEFT)
    num = @pictureEx.length
    picture = PictureEx.new(num)
    picture.setXY(0, x, y)
    picture.setName(0, name)
    picture.setOrigin(0, origin)
    @pictureEx[num] = picture
    s = IconSprite.new(x, y, @viewport)
    s.setBitmap(name)
    @pictureSprites[num] = s
    @tempSprites.push(s)
    return picture
  end

  def update
    return if @animDone
    @tempSprites.each { |s| s&.update }
    finished = true
    @pictureEx.each_with_index do |p, i|
      next if !p.running?
      finished = false
      p.update
      setPictureIconSprite(@pictureSprites[i], p)
    end
    @animDone = true if finished
  end
end

#===============================================================================
# Mixin module for certain hardcoded battle animations that involve Poké Balls.
#===============================================================================
module Battle::Scene::Animation::BallAnimationMixin

  BALL_START_X_DIVISOR = 32
  TRAINER_BACK_SPRITE_X_OFFSET = 44
  TRAINER_BACK_SPRITE_Y_OFFSET = 32
  BALL_START_X_INCREMENT = 8
  ARM_MID_THROW_X = -10
  ARM_MID_THROW_Y = -36
  ARM_START_OF_THROW_X = 118
  ARM_START_OF_THROW_Y = -4
  STRETCH_THROW_MOVE_DELTA_X = 5
  STRETCH_THROW_MOVE_DELTA_Y = -5
  STRETCH_THROW_SET_DELTA_X = -12
  STRETCH_THROW_SET_DELTA_Y = 0

  MID_THROW_MOVE_DELTA_X = 2
  MID_THROW_MOVE_DELTA_Y = -2
  MID_THROW_SET_DELTA_X = 34
  MID_THROW_SET_DELTA_Y = 0

  START_THROW_SET_DELTA_X = -14
  START_THROW_SET_DELTA_Y = 0

  # Ball burst / particle / star placement constants (centralized for scaling)
  BALL_BURST_RAY_MIN_RADIUS = 24
  BALL_BURST_PARTICLE_MAX_RADIUS_MIN = 256
  BALL_BURST_PARTICLE_MAX_RADIUS_MAX = 384

  BALL_BURST_CAPTURE_BASE_ANGLE = 270
  BALL_BURST_CAPTURE_BASE_RADIUS = 144
  BALL_BURST_CAPTURE_MASTER_BASE_RADIUS = 192

  BALL_BURST_RECALL_BASE_RADIUS = 64

  BALL_CAPTURE_STAR_OFFSETS = [[0, 74, 52], [0, 62, 28], [0, 74, 48]]
  BALL_CAPTURE_STAR_ZOOMS = [50, 50, 33]
  BALL_CAPTURE_STAR_START_ANGLES = [0, 345, 15]
  BALL_CAPTURE_STAR_MOVE_ANGLES = [144, 0, 45]

  TRAINER_THROWING_FRAMES_SET_DELTA = {
    :set_delta => [ #delay, deltaX, deltaY
                    [0, -12, 0],
                    [5, 34, 0],
                    [7, -14, 0],
                    [9, 28, 0],
                  ],
    :move_delta => [ #delay, duration, deltaX, deltaY
                    [10, 3, -6, 6]
                  ],
    :set_delta2 => [ #delay, deltaX, deltaY
                    [18, -4, 0],
                    [19, -26, -6]
                  ]

  }.freeze

  # Named coordinate sets so resolution-dependent changes are centralized.
  THROW_COORDS_POKEMONTRAINER_LEAF   = [[-30, -30], [-18, -36], [118, -6]]
  THROW_COORDS_POKEMONTRAINER_BRENDAN = [[-46, -40], [-4, -30], [118, -2]]
  THROW_COORDS_POKEMONTRAINER_MAY     = [[-44, -38], [-8, -30], [122, 0]]

  THROW_COORDS_CHARS = {
    :POKEMONTRAINER_Leaf   => THROW_COORDS_POKEMONTRAINER_LEAF,
    :POKEMONTRAINER_Brendan => THROW_COORDS_POKEMONTRAINER_BRENDAN,
    :POKEMONTRAINER_May     => THROW_COORDS_POKEMONTRAINER_MAY
  }



  # Returns the color that the Pokémon turns when it goes into or out of its
  # Poké Ball.
  def getBattlerColorFromPokeBall(poke_ball)
    case poke_ball
    when :GREATBALL   then return Color.new(132, 189, 247)
    when :SAFARIBALL  then return Color.new(189, 247, 165)
    when :ULTRABALL   then return Color.new(255, 255, 123)
    when :MASTERBALL  then return Color.new(189, 165, 231)
    when :NETBALL     then return Color.new(173, 255, 206)
    when :DIVEBALL    then return Color.new(99, 206, 247)
    when :NESTBALL    then return Color.new(247, 222,  82)
    when :REPEATBALL  then return Color.new(255, 198, 132)
    when :TIMERBALL   then return Color.new(239, 247, 247)
    when :LUXURYBALL  then return Color.new(255, 140,  82)
    when :PREMIERBALL then return Color.new(255,  74,  82)
    when :DUSKBALL    then return Color.new(115, 115, 140)
    when :HEALBALL    then return Color.new(255, 198, 231)
    when :QUICKBALL   then return Color.new(140, 214, 255)
    when :CHERISHBALL then return Color.new(247,  66,  41)
    end
    return Color.new(255, 181, 247)   # Poké Ball, Sport Ball, Apricorn Balls, others
  end

  def addBallSprite(ballX, ballY, poke_ball)
    file_path = sprintf("Graphics/Battle animations/ball_%s", poke_ball)
    ball = addNewSprite(ballX, ballY, file_path, PictureOrigin::CENTER)
    @ballSprite = @pictureSprites.last
    if @ballSprite.bitmap.width >= @ballSprite.bitmap.height
      @ballSprite.src_rect.width = @ballSprite.bitmap.height / 2
      ball.setSrcSize(0, @ballSprite.bitmap.height / 2, @ballSprite.bitmap.height)
    end
    return ball
  end

  def ballTracksHand(ball, traSprite, safariThrow = false)
    # Back sprite isn't animated, no hand-tracking needed
    if traSprite.bitmap.width < traSprite.bitmap.height * 2
      ball.setVisible(7, true)
      ballStartX = traSprite.x
      ballStartX -= ball.totalDuration * (Graphics.width / BALL_START_X_DIVISOR) if !safariThrow
      ballStartY = traSprite.y - (traSprite.bitmap.height / 2)
      return ballStartX, ballStartY
    end
    # Back sprite is animated, make the Poké Ball track the trainer's hand
    coordSets = [[traSprite.x - TRAINER_BACK_SPRITE_X_OFFSET, traSprite.y - TRAINER_BACK_SPRITE_Y_OFFSET], [ARM_MID_THROW_X, ARM_MID_THROW_Y], [ARM_START_OF_THROW_X, ARM_START_OF_THROW_Y]]
    coords_set = THROW_COORDS_CHARS.fetch(@trainer.trainer_type, nil)
    if coords_set
      coordSets = [[traSprite.x + coords_set[0][0], traSprite.y + coords_set[0][1]], coords_set[1], coords_set[2]]
    end
    # Arm stretched out behind player
    ball.setVisible(0, true)
    ball.setXY(0, coordSets[0][0], coordSets[0][1])
    ball.moveDelta(0, STRETCH_THROW_MOVE_DELTA_X, STRETCH_THROW_MOVE_DELTA_Y * (Graphics.width / BALL_START_X_DIVISOR), 0) if !safariThrow
    ball.setDelta(0, STRETCH_THROW_SET_DELTA_X, STRETCH_THROW_SET_DELTA_Y) if safariThrow
    # Arm mid throw
    ball.setDelta(5, coordSets[1][0], coordSets[1][1])
    ball.moveDelta(5, MID_THROW_MOVE_DELTA_X, MID_THROW_MOVE_DELTA_Y * (Graphics.width / BALL_START_X_DIVISOR), 0) if !safariThrow
    ball.setDelta(5, MID_THROW_SET_DELTA_X, MID_THROW_SET_DELTA_Y) if safariThrow
    # Start of throw
    ball.setDelta(7, coordSets[2][0], coordSets[2][1])
    ball.setDelta(7, START_THROW_SET_DELTA_X, START_THROW_SET_DELTA_Y) if safariThrow
    # Update Poké Ball trajectory's start position
    ballStartX = ballStartY = 0
    coordSets.each do |c|
      ballStartX += c[0]
      ballStartY += c[1]
    end
    ballStartX -= ball.totalDuration * (Graphics.width / BALL_START_X_DIVISOR) if !safariThrow
    ballStartX += BALL_START_X_INCREMENT if safariThrow   # -12 + 34 - 14
    return ballStartX, ballStartY
  end

  def trainerThrowingFrames(ball, trainer, traSprite)
    ball.setZ(0, traSprite.z - 1)
    # Change trainer's frames
    size = traSprite.src_rect.width   # Width per frame
    trainer.setSrc(0, size, 0)
    trainer.setSrc(5, size * 2, 0)
    trainer.setSrc(7, size * 3, 0)
    trainer.setSrc(9, size * 4, 0)
    trainer.setSrc(18, 0, 0)
    # Alter trainer's positioning
    TRAINER_THROWING_FRAMES_SET_DELTA.each do |action, deltas|
      deltas.each do |params|
        if action == :set_delta
          trainer.setDelta(params[0], params[1], params[2])
        elsif action == :move_delta
          trainer.moveDelta(params[0], params[1], params[2], params[3])
        elsif action == :set_delta2
          trainer.setDelta(params[0], params[1], params[2])
        end
      end
    end
    # Make ball track the trainer's hand
    ballStartX, ballStartY = ballTracksHand(ball, traSprite, true)
    return ballStartX, ballStartY
  end

  def createBallTrajectory(ball, delay, duration, startX, startY, midX, midY, endX, endY)
    # NOTE: This trajectory is the same regardless of whether the player's
    #       sprite is being shown on-screen (and sliding off while animating a
    #       throw). Instead, that throw animation and initialDelay are designed
    #       to make sure the Ball's trajectory starts at the same position.
    ball.setVisible(delay, true)
    a = (2 * startY) - (4 * midY) + (2 * endY)
    b = (4 * midY) - (3 * startY) - endY
    c = startY
    (1..duration).each do |i|
      t = i.to_f / duration                # t ranges from 0 to 1
      x = startX + ((endX - startX) * t)   # Linear in t
      y = (a * (t**2)) + (b * t) + c       # Quadratic in t
      ball.moveXY(delay + i - 1, 1, x, y)
    end
    createBallTumbling(ball, delay, duration)
  end

  def createBallTumbling(ball, delay, duration)
    # Animate ball frames
    numTumbles = 1
    numFrames  = 1
    if @ballSprite && @ballSprite.bitmap.width >= @ballSprite.bitmap.height
      # 2* because each frame is twice as tall as it is wide
      numFrames = 2 * @ballSprite.bitmap.width / @ballSprite.bitmap.height
    end
    if numFrames > 1
      curFrame = 0
      (1..duration).each do |i|
        thisFrame = numFrames * numTumbles * i / duration
        if thisFrame > curFrame
          curFrame = thisFrame
          ball.setSrc(delay + i - 1, (curFrame % numFrames) * @ballSprite.bitmap.height / 2, 0)
        end
      end
      ball.setSrc(delay + duration, 0, 0)
    end
    # Rotate ball
    ball.moveAngle(delay, duration, 360 * 3)
    ball.setAngle(delay + duration, 0)
  end

  def ballSetOpen(ball, delay, poke_ball)
    file_path = sprintf("Graphics/Battle animations/ball_%s_open", poke_ball)
    ball.setName(delay, file_path)
    if @ballSprite && @ballSprite.bitmap.width >= @ballSprite.bitmap.height
      ball.setSrcSize(delay, @ballSprite.bitmap.height / 2, @ballSprite.bitmap.height)
    end
  end

  def ballSetClosed(ball, delay, poke_ball)
    file_path = sprintf("Graphics/Battle animations/ball_%s", poke_ball)
    ball.setName(delay, file_path)
    if @ballSprite && @ballSprite.bitmap.width >= @ballSprite.bitmap.height
      ball.setSrcSize(delay, @ballSprite.bitmap.height / 2, @ballSprite.bitmap.height)
    end
  end

  def ballOpenUp(ball, delay, poke_ball, showSquish = true, playSE = true)
    if showSquish
      ball.moveZoomXY(delay, 1, 120, 80)   # Squish
      ball.moveZoom(delay + 5, 1, 100)     # Unsquish
      delay += 6
    end
    ball.setSE(delay, "Battle recall") if playSE
    ballSetOpen(ball, delay, poke_ball)
  end

  def battlerAppear(battler, delay, battlerX, battlerY, batSprite, color)
    battler.setVisible(delay, true)
    battler.setOpacity(delay, 255)
    battler.moveXY(delay, 5, battlerX, battlerY)
    battler.moveZoom(delay, 5, 100, [batSprite, :pbPlayIntroAnimation])
    # NOTE: As soon as the battler sprite finishes zooming, and just as it
    #       starts changing its tone to normal, it plays its intro animation.
    color.alpha = 0
    battler.moveColor(delay + 5, 10, color)
  end

  def battlerAbsorb(battler, delay, battlerX, battlerY, color)
    color.alpha = 255
    battler.moveColor(delay, 10, color)   # Change color of battler to a solid shade
    delay = battler.totalDuration
    battler.moveXY(delay, 5, battlerX, battlerY)
    battler.moveZoom(delay, 5, 0)   # Shrink battler into Poké Ball
    battler.setVisible(delay + 5, false)
  end

  # NOTE: This array makes the Ball Burst animation differ between types of Poké
  #       Ball in certain simple ways. The HGSS animations occasionally have
  #       additional differences, which haven't been coded yet in Essentials as
  #       they're more complex and I couldn't be bothered.
  BALL_BURST_VARIANCES = {
    # [ray start tone, ray end tone,
    #  top particle filename, top particle start tone, top particle end tone,
    #  bottom particle filename, bottom particle start tone, bottom particle end tone,
    #  top glare filename, top glare start tone, top glare end tone,
    #  bottom glare filename, bottom glare start tone, bottom glare end tone]
    :POKEBALL    => [Tone.new(0, 0, 0), Tone.new(0, 0, -192),   # White, yellow
                     "particle", Tone.new(0, 0, 0), Tone.new(0, 0, 0),   # White, white
                     "particle", Tone.new(0, 0, -96), Tone.new(0, -128, -248),   # Yellow, dark orange
                     "particle", Tone.new(0, 0, 0), Tone.new(0, 0, 0),   # White, white
