  proc { |score, move, user, ai, battle|
    score = ai.get_score_for_target_stat_raise(score, user, move.move.statUp)
    if user.status != :NONE
      score += (user.wants_status_problem?(user.status)) ? -10 : 10
    end
    next score
  }
)

