#
#===============================================================================
class Battle::DamageState
  attr_accessor :typeMod         # Type effectiveness
  attr_accessor :unaffected
  attr_accessor :protected
  attr_accessor :magicCoat
  attr_accessor :magicBounce
  attr_accessor :totalHPLost     # Like hpLost, but cumulative over all hits
  attr_accessor :fainted         # Whether battler was knocked out by the move

  attr_accessor :missed          # Whether the move failed the accuracy check
  attr_accessor :affection_missed
  attr_accessor :invulnerable    # If the move missed due to two turn move invulnerability
  attr_accessor :calcDamage      # Calculated damage
  attr_accessor :hpLost          # HP lost by opponent, inc. HP lost by a substitute
  attr_accessor :critical        # Critical hit flag
  attr_accessor :affection_critical
  attr_accessor :substitute      # Whether a substitute took the damage
  attr_accessor :focusBand       # Focus Band used
  attr_accessor :focusSash       # Focus Sash used
  attr_accessor :sturdy          # Sturdy ability used
  attr_accessor :disguise        # Disguise ability used
  attr_accessor :iceFace         # Ice Face ability used
  attr_accessor :endured         # Damage was endured
  attr_accessor :affection_endured
  attr_accessor :berryWeakened   # Whether a type-resisting berry was used

  def initialize; reset; end

  def reset
    @typeMod          = Effectiveness::INEFFECTIVE_MULTIPLIER
    @unaffected       = false
    @protected        = false
    @missed           = false
    @affection_missed = false
    @invulnerable     = false
    @magicCoat        = false
    @magicBounce      = false
    @totalHPLost      = 0
    @fainted          = false
    resetPerHit
  end

  def resetPerHit
    @calcDamage         = 0
    @hpLost             = 0
    @critical           = false
    @affection_critical = false
    @substitute         = false
    @focusBand          = false
    @focusSash          = false
    @sturdy             = false
    @disguise           = false
    @iceFace            = false
    @endured            = false
    @affection_endured  = false
    @berryWeakened      = false
  end
end

==============================================================================
# Script: Battle_Peers
==============================================================================
#===============================================================================
#
#===============================================================================
class Battle::Peer
  def pbStorePokemon(player, pkmn)
    if !player.party_full?
      player.party[player.party.length] = pkmn
      return -1
    end
    if Settings::HEAL_STORED_POKEMON
      old_ready_evo = pkmn.ready_to_evolve
      pkmn.heal
      pkmn.ready_to_evolve = old_ready_evo
    end
    oldCurBox = pbCurrentBox
    storedBox = $PokemonStorage.pbStoreCaught(pkmn)
    if storedBox < 0
      # NOTE: Poké Balls can't be used if storage is full, so you shouldn't ever
      #       see this message.
      pbDisplayPaused(_INTL("No se pueden capturar más Pokémon..."))
      return oldCurBox
    end
    return storedBox
  end

  def pbGetStorageCreatorName
    return pbGetStorageCreator if $player.seen_storage_creator
    return nil
  end

  def pbCurrentBox
    return $PokemonStorage.currentBox
  end

  def pbBoxName(box)
    return (box < 0) ? "" : $PokemonStorage[box].name
  end

  def pbOnStartingBattle(battle, pkmn, wild = false)
    f = MultipleForms.call("getFormOnStartingBattle", pkmn, wild)
    pkmn.form = f if f
    MultipleForms.call("changePokemonOnStartingBattle", pkmn, battle)
  end

  def pbOnEnteringBattle(battle, battler, pkmn, wild = false)
    f = MultipleForms.call("getFormOnEnteringBattle", pkmn, wild)
    pkmn.form = f if f
    battler.form = pkmn.form if battler.form != pkmn.form
    MultipleForms.call("changePokemonOnEnteringBattle", battler, pkmn, battle)
  end

  # For switching out, including due to fainting, and for the end of battle
  def pbOnLeavingBattle(battle, pkmn, usedInBattle, endBattle = false)
    return if !pkmn
    f = MultipleForms.call("getFormOnLeavingBattle", pkmn, battle, usedInBattle, endBattle)
    pkmn.form = f if f && pkmn.form != f
    pkmn.hp = pkmn.totalhp if pkmn.hp > pkmn.totalhp
    MultipleForms.call("changePokemonOnLeavingBattle", pkmn, battle, usedInBattle, endBattle)
  end
end

#===============================================================================
# Unused class.
#===============================================================================
class Battle::NullPeer
  def pbOnEnteringBattle(battle, battler, pkmn, wild = false); end
  def pbOnLeavingBattle(battle, pkmn, usedInBattle, endBattle = false); end

  def pbStorePokemon(player, pkmn)
    player.party[player.party.length] = pkmn if !player.party_full?
    return -1
  end

  def pbGetStorageCreatorName; return nil; end
  def pbCurrentBox;            return -1;  end
  def pbBoxName(box);          return "";  end
end


==============================================================================
# Script: Battle_CatchAndStoreMixin
==============================================================================
module Battle::CatchAndStoreMixin
  #=============================================================================
  # Store caught Pokémon
  #=============================================================================
  def pbStorePokemon(pkmn)
    # Nickname the Pokémon (unless it's a Shadow Pokémon)
    if !pkmn.shadowPokemon?
      if $PokemonSystem.givenicknames == 0 &&
         pbDisplayConfirm(_INTL("¿Quieres ponerle un mote a {1}?", pkmn.name))
        nickname = @scene.pbNameEntry(_INTL("¿Mote de {1}?", pkmn.speciesName), pkmn)
        pkmn.name = nickname
      end
    end
    # Store the Pokémon
    if pbPlayer.party_full? && (@sendToBoxes == 0 || @sendToBoxes == 2)   # Ask/must add to party
      cmds = [_INTL("Añadir al equipo"),
              _INTL("Enviarlo al PC"),
              _INTL("Ver los datos de {1}", pkmn.name),
              _INTL("Comprobar equipo")]
      cmds.delete_at(1) if @sendToBoxes == 2 # Remove "Send to a Box" option
      loop do
        cmd = pbShowCommands(_INTL("¿Qué quieres hacer con {1}?", pkmn.name), cmds, 99)
        next if cmd == 99 && @sendToBoxes == 2   # Can't cancel if must add to party
        break if cmd == 99   # Cancelling = send to a Box
        cmd += 1 if cmd >= 1 && @sendToBoxes == 2
        case cmd
        when 0   # Add to your party
          pbDisplay(_INTL("Elige un Pokémon de tu equipo para reemplazarlo."))
          party_index = -1
          @scene.pbPartyScreen(0, (@sendToBoxes != 2), 1) do |idxParty, _partyScene|
            party_index = idxParty
            next true
          end
          next if party_index < 0   # Cancelled
          party_size = pbPlayer.party.length
          # Get chosen Pokémon and clear battle-related conditions
          send_pkmn = pbPlayer.party[party_index]
          @peer.pbOnLeavingBattle(self, send_pkmn, @usedInBattle[0][party_index], true)
          send_pkmn.statusCount = 0 if send_pkmn.status == :POISON   # Bad poison becomes regular
          send_pkmn.makeUnmega
          send_pkmn.makeUnprimal
          # Send chosen Pokémon to storage
          stored_box = @peer.pbStorePokemon(pbPlayer, send_pkmn)
          pbPlayer.party.delete_at(party_index)
          box_name = @peer.pbBoxName(stored_box)
          pbDisplayPaused(_INTL("Has enviado a {1} a la Caja \"{2}\".", send_pkmn.name, box_name))
          # Rearrange all remembered properties of party Pokémon
          (party_index...party_size).each do |idx|
            if idx < party_size - 1
              @usedInBattle[0][idx] = @usedInBattle[0][idx + 1]
              $game_temp.party_levels_before_battle[idx] = $game_temp.party_levels_before_battle[idx + 1]
            else
              @usedInBattle[0][idx] = nil
              $game_temp.party_levels_before_battle[idx] = nil
            end
          end
          break
        when 1   # Send to a Box
          break
        when 2   # See X's summary
          pbFadeOutIn do
            summary_scene = PokemonSummary_Scene.new
            summary_screen = PokemonSummaryScreen.new(summary_scene, true)
            summary_screen.pbStartScreen([pkmn], 0)
          end
        when 3   # Check party
          @scene.pbPartyScreen(0, true, 2)
        end
      end
    end
    # Store as normal (add to party if there's space, or send to a Box if not)
    stored_box = @peer.pbStorePokemon(pbPlayer, pkmn)
    if stored_box < 0
      pbDisplayPaused(_INTL("{1} se ha añadido a tu equipo.", pkmn.name))
    else
      # Messages saying the Pokémon was stored in a PC box
      box_name = @peer.pbBoxName(stored_box)
      pbDisplayPaused(_INTL("¡{1} se ha enviado a la Caja \"{2}\"!", pkmn.name, box_name))
    end
  end

  # Register all caught Pokémon in the Pokédex, and store them.
  def pbRecordAndStoreCaughtPokemon
    @caughtPokemon.each do |pkmn|
      pbSetCaught(pkmn)
      pbSetSeen(pkmn)   # In case the form changed upon leaving battle
      # Record the Pokémon's species as owned in the Pokédex
      if !pbPlayer.owned?(pkmn.species)
        pbPlayer.pokedex.set_owned(pkmn.species)
        if $player.has_pokedex && $player.pokedex.species_in_unlocked_dex?(pkmn.species)
          pbDisplayPaused(_INTL("Los datos de {1} se han añadido a la Pokédex.", pkmn.name))
          pbPlayer.pokedex.register_last_seen(pkmn)
          @scene.pbShowPokedex(pkmn.species)
        end
      end
      # Record a Shadow Pokémon's species as having been caught
      pbPlayer.pokedex.set_shadow_pokemon_owned(pkmn.species) if pkmn.shadowPokemon?
      # Store caught Pokémon
      pbStorePokemon(pkmn)
    end
    @caughtPokemon.clear
  end

  #=============================================================================
  # Throw a Poké Ball
  #=============================================================================
  def pbThrowPokeBall(idxBattler, ball, catch_rate = nil, showPlayer = false)
    # Determine which Pokémon you're throwing the Poké Ball at
    battler = @battlers[idxBattler]
    battler = @battlers[idxBattler].pbDirectOpposing(true) if !battler.opposes?
    battler = battler.allAllies[0] if battler.fainted?
    pkmn = battler.pokemon
    # Throw message
    pbThrowPokeBallMessage(battler, ball)
    # Failure checks (Pokémon is fainted, or opposing trainer blocks the Poké
    # Ball)
    return if pbThrowPokeBallNegated?(battler, ball)
    # Calculate the number of shakes (4=capture)
    @criticalCapture = false
    num_shakes = pbCaptureCalc(pkmn, battler, catch_rate, ball)
    if num_shakes != 4
      @first_poke_ball = ball if !@poke_ball_failed   # For Ball Fetch
      @poke_ball_failed = true                        # For Ball Fetch
    end
    # Animation of Ball throw, absorb, shake and capture/burst out
    @scene.pbThrow(ball, num_shakes, @criticalCapture, battler.index, showPlayer)
    # Outcome
    pbThrowPokeBallOutcome(battler, pkmn, ball, num_shakes)
  end

  def pbThrowPokeBallMessage(battler, ball)
    return if battler.fainted?   # Messages are shown in def pbThrowPokeBallNegated? for this
    item_name = GameData::Item.get(ball).name
    if item_name.starts_with_vowel?
      pbDisplayBrief(_INTL("¡{1} lanzó un {2}!", pbPlayer.name, item_name))
    else
      pbDisplayBrief(_INTL("¡{1} lanzó una {2}!", pbPlayer.name, item_name))
    end
  end

  def pbThrowPokeBallNegated?(battler, ball)
    if battler.fainted?
      item_name = GameData::Item.get(ball).name
      PBDebug.log("[Threw Poké Ball] #{item_name}, failed due to no target")
      if item_name.starts_with_vowel?
        pbDisplay(_INTL("¡{1} lanzó un {2}!", pbPlayer.name, item_name))
      else
        pbDisplay(_INTL("¡{1} lanzó una {2}!", pbPlayer.name, item_name))
      end
      pbDisplay(_INTL("Pero no había objetivo..."))
      return true
    end
    if trainerBattle? && !(GameData::Item.get(ball).is_snag_ball? && battler.shadowPokemon?)
      item_name = GameData::Item.get(ball).name
      PBDebug.log("[Threw Poké Ball] #{item_name}, failed due to opposing trainer blocking")
      @scene.pbThrowAndDeflect(ball, 1)   # Animation
      pbDisplay(_INTL("¡El Entrenador bloqueó tu {1}! ¡Robar está mal!", item_name))
      return true
    end
    return false
  end

  #-----------------------------------------------------------------------------
  # Calculate how many shakes a thrown Poké Ball will make (4 = capture).
  #-----------------------------------------------------------------------------

  def pbCaptureCalc(pkmn, battler, base_catch_rate, ball)
    # Certain capture checks
    return 4 if $DEBUG && Input.press?(Input::CTRL)
    return 4 if Battle::PokeBallEffects.isUnconditional?(ball, self, battler)
    return 4 if @rules[:certain_capture]
    # Get a catch rate if one wasn't provided
    base_catch_rate = pkmn.species_data.catch_rate if !base_catch_rate
    # Modify catch_rate depending on the Poké Ball's effect
    if !pkmn.species_data.has_flag?("UltraBeast") || ball == :BEASTBALL
      base_catch_rate = Battle::PokeBallEffects.modifyCatchRate(ball, base_catch_rate, self, battler)
    else
      base_catch_rate = [base_catch_rate / 10.0, 1].max
    end
    # Modify catch_rate depending on HP
    mod_catch_rate = base_catch_rate * 4096
    mod_catch_rate *= ((3 * battler.totalhp) - (2 * battler.hp)) / (3 * battler.totalhp).to_f
    # Higher wild level penalty if the player can't make the Pokémon obey
    if Settings::CATCH_RATE_PENALTY_IF_POKEMON_WILL_NOT_OBEY &&
       pkmn.level > battler.pbMaxLevelBadgeObedience + 5
      badges_needed = battler.pbBadgesNeededToObey
      mod_catch_rate *= 0.8**badges_needed if badges_needed > 0
    end
    # Floor the mod_catch_rate
    mod_catch_rate = mod_catch_rate.floor
    mod_catch_rate = 1 if mod_catch_rate < 1
    # Status bonus
    if battler.status == :SLEEP || battler.status == :FROZEN
      mod_catch_rate *= 2.5
    elsif battler.status != :NONE
      mod_catch_rate *= 1.5
    end
    # Low wild level bonus (Gen 9's version)
    if Settings::CATCH_RATE_BONUS_FOR_LOW_LEVEL
      mod_catch_rate *= [(36 - (2 * pkmn.level)) / 10.0, 1].max
    end
    # Higher wild level penalty if the player doesn't have enough Gym Badges (Gen 8 only)
    if Settings::NUM_BADGES_TO_NOT_MAKE_HIGHER_LEVEL_CAPTURES_HARDER > $player.badge_count
      max_player_level = 0
      allSameSideBattlers(0, true).each { |b| max_player_level = b.level if b.level > max_player_level }
      mod_catch_rate /= 10.0 if pkmn.level > max_player_level
    end
    # Floor the mod_catch_rate
    mod_catch_rate = mod_catch_rate.floor
    mod_catch_rate = 1 if mod_catch_rate < 1
    # Definite capture, no need to perform randomness checks
    return 4 if mod_catch_rate >= 255 * 4096
    # Second half of the shakes calculation (from Gen 6)
    shake_chance = (65_536 * ((mod_catch_rate.to_f / (255 * 4096))**0.1875)).floor
    # Critical capture check
    if Settings::ENABLE_CRITICAL_CAPTURES
      dex_modifier = 0
      num_owned = $player.pokedex.owned_count
      if num_owned > 600
        dex_modifier = 5
      elsif num_owned > 450
        dex_modifier = 4
      elsif num_owned > 300
        dex_modifier = 3
      elsif num_owned > 150
        dex_modifier = 2
      elsif num_owned > 30
        dex_modifier = 1
      end
      dex_modifier *= 2 if $bag.has?(:CATCHINGCHARM)
      critical_chance = mod_catch_rate * dex_modifier / 12
      # Calculate the number of shakes
      if critical_chance > 0 && pbRandom(256) < critical_chance
        @criticalCapture = true
        return 4 if pbRandom(65_536) < shake_chance
        return 0
      end
    end
    # Calculate the number of shakes
    num_shakes = 0
    4.times do |i|
      break if num_shakes < i
      num_shakes += 1 if pbRandom(65_536) < shake_chance
    end
    return num_shakes
  end

  #-----------------------------------------------------------------------------
  # The outcome of the capture attempt (after the animation).
  #-----------------------------------------------------------------------------

  def pbThrowPokeBallOutcome(battler, pkmn, ball, num_shakes)
    # Succeeded
    if num_shakes == 4
      PBDebug.log("[Threw Poké Ball] #{GameData::Item.get(ball).name}, #{num_shakes} shakes (succeeded)")
      pbThrowPokeBallSuccess(battler, pkmn, ball)
      return
    end
    # Failed
    PBDebug.log("[Threw Poké Ball] #{GameData::Item.get(ball).name}, #{num_shakes} shakes (failed)")
    case num_shakes
    when 0 then pbDisplay(_INTL("¡Oh, no! ¡El Pokémon se ha escapado!"))
    when 1 then pbDisplay(_INTL("¡Vaya! ¡Parecía que lo habías atrapado!"))
    when 2 then pbDisplay(_INTL("¡Qué pena! ¡Te ha faltado poco!"))
    when 3 then pbDisplay(_INTL("¡Uy! ¡Casi lo consigues!"))
    end
    Battle::PokeBallEffects.onFailCatch(ball, self, battler)
  end

  def pbThrowPokeBallSuccess(battler, pkmn, ball)
    pbDisplayBrief(_INTL("¡Ya está! ¡{1} atrapado!", pkmn.name))
    @scene.pbThrowSuccess   # Play capture success jingle
    pbRemoveFromParty(battler.index, battler.pokemonIndex)
    # Gain Exp
    if Settings::GAIN_EXP_FOR_CAPTURE
      battler.captured = true
      pbGainExp
      battler.captured = false
    end
    battler.pbReset
    if pbAllFainted?(battler.index)
      @decision = (trainerBattle?) ? Battle::Outcome::WIN : Battle::Outcome::CATCH
    end
    # Modify the Pokémon's properties because of the capture
    if GameData::Item.get(ball).is_snag_ball?
      pkmn.owner = Pokemon::Owner.new_from_trainer(pbPlayer)
    end
    Battle::PokeBallEffects.onCatch(ball, self, pkmn)
    pkmn.poke_ball = ball
    pkmn.makeUnmega if pkmn.mega?
    pkmn.makeUnprimal
    pkmn.update_shadow_moves if pkmn.shadowPokemon?
    pkmn.record_first_moves
    # Reset form
    pkmn.forced_form = nil if MultipleForms.hasFunction?(pkmn.species, "getForm")
    @peer.pbOnLeavingBattle(self, pkmn, true, true)
    # Make the Poké Ball and data box disappear
    @scene.pbHideCaptureBall(battler.index)
    # Save the Pokémon for storage at the end of battle
    @caughtPokemon.push(pkmn)
  end
end

#===============================================================================
#
#===============================================================================
class Battle
  include Battle::CatchAndStoreMixin
end

==============================================================================
# Script: Battle_Clauses
==============================================================================
#===============================================================================
# This script modifies the battle system to implement battle rules.
#===============================================================================
class Battle
  unless @__clauses__aliased
    alias __clauses__pbDecisionOnDraw pbDecisionOnDraw
    alias __clauses__pbEndOfRoundPhase pbEndOfRoundPhase
    @__clauses__aliased = true
  end

  def pbDecisionOnDraw
    if @rules["selfkoclause"]
      if self.lastMoveUser < 0
        # in extreme cases there may be no last move user
        return Outcome::DRAW
      elsif opposes?(self.lastMoveUser)
        return Outcome::LOSE
      else
        return Outcome::WIN
      end
    end
    return __clauses__pbDecisionOnDraw
  end

  def pbJudgeCheckpoint(user, move = nil)
    if pbAllFainted?(0) && pbAllFainted?(1)
      if @rules["drawclause"]   # NOTE: Also includes Life Orb (not implemented)
        if !(move && move.function_code == "HealUserByHalfOfDamageDone")
          # Not a draw if fainting occurred due to Liquid Ooze
          @decision = (user.opposes?) ? Outcome::WIN : Outcome::LOSE
        end
      elsif @rules["modifiedselfdestructclause"]
        if move && move.function_code == "UserFaintsExplosive"   # Self-Destruct
          @decision = (user.opposes?) ? Outcome::WIN : Outcome::LOSE
        end
      end
    end
  end

  def pbEndOfRoundPhase
    __clauses__pbEndOfRoundPhase
    if @rules["suddendeath"] && !decided?
      p1able = pbAbleCount(0)
      p2able = pbAbleCount(1)
      if p1able > p2able
        @decision = Outcome::WIN
      elsif p1able < p2able
        @decision = Outcome::LOSE
      end
    end
  end
end

#===============================================================================
#
#===============================================================================
class Battle::Battler
  unless @__clauses__aliased
    alias __clauses__pbCanSleep? pbCanSleep?
    alias __clauses__pbCanSleepYawn? pbCanSleepYawn?
    alias __clauses__pbCanFreeze? pbCanFreeze?
    alias __clauses__pbUseMove pbUseMove
    @__clauses__aliased = true
  end

  def pbCanSleep?(user, showMessages, move = nil, ignoreStatus = false)
    selfsleep = (user && user.index == @index)
    if ((@battle.rules["modifiedsleepclause"]) || (!selfsleep && @battle.rules["sleepclause"])) &&
       pbHasStatusPokemon?(:SLEEP)
      if showMessages
        @battle.pbDisplay(_INTL("¡Pero {1} no se ha podido dormir!", pbThis(true)))
      end
      return false
    end
    return __clauses__pbCanSleep?(user, showMessages, move, ignoreStatus)
  end

  def pbCanSleepYawn?
    if (@battle.rules["sleepclause"] || @battle.rules["modifiedsleepclause"]) &&
       pbHasStatusPokemon?(:SLEEP)
      return false
    end
    return __clauses__pbCanSleepYawn?
  end

  def pbCanFreeze?(*arg)
    if @battle.rules["freezeclause"] && pbHasStatusPokemon?(:FROZEN)
      return false
    end
    return __clauses__pbCanFreeze?(*arg)
  end

  def pbHasStatusPokemon?(status)
    count = 0
    @battle.pbParty(@index).each do |pkmn|
      next if !pkmn || pkmn.egg?
      next if pkmn.status != status
      count += 1
    end
    return count > 0
  end
end

