  }
)

Battle::ItemEffects::StatusCure.add(:LUMBERRY,
  proc { |item, battler, battle, forced|
    next false if !forced && !battler.canConsumeBerry?
    next false if battler.status == :NONE &&
                  battler.effects[PBEffects::Confusion] == 0
    itemName = GameData::Item.get(item).name
    PBDebug.log("[Item triggered] #{battler.pbThis}'s #{itemName}") if forced
    battle.pbCommonAnimation("EatBerry", battler) if !forced
    oldStatus = battler.status
    oldConfusion = (battler.effects[PBEffects::Confusion] > 0)
    battler.pbCureStatus(forced)
    battler.pbCureConfusion
    if forced
      battle.pbDisplay(_INTL("¡{1} ya no está confuso!", battler.pbThis)) if oldConfusion
    else
      case oldStatus
      when :SLEEP
        battle.pbDisplay(_INTL("¡{1} se ha despertado con {2}!", battler.pbThis, itemName))
      when :POISON
        battle.pbDisplay(_INTL("¡{1} se ha curado del envenenamiento con {2}!", battler.pbThis, itemName))
      when :BURN
        battle.pbDisplay(_INTL("¡{1} se ha curado de las quemaduras con {2}!", battler.pbThis, itemName))
      when :PARALYSIS
        battle.pbDisplay(_INTL("¡{1} se ha curado de la parálisis con {2}!", battler.pbThis, itemName))
      when :FROZEN, :FROSTBITE
        battle.pbDisplay(_INTL("¡{1} se ha descongelado con {2}!", battler.pbThis, itemName))
      end
      if oldConfusion
        battle.pbDisplay(_INTL("¡{1} ya no está confuso gracias a {2}!", battler.pbThis, itemName))
      end
    end
    next true
  }
)

Battle::ItemEffects::StatusCure.add(:MENTALHERB,
  proc { |item, battler, battle, forced|
    next false if battler.effects[PBEffects::Attract] == -1 &&
                  battler.effects[PBEffects::Taunt] == 0 &&
                  battler.effects[PBEffects::Encore] == 0 &&
                  !battler.effects[PBEffects::Torment] &&
                  battler.effects[PBEffects::Disable] == 0 &&
                  battler.effects[PBEffects::HealBlock] == 0
    itemName = GameData::Item.get(item).name
    PBDebug.log("[Item triggered] #{battler.pbThis}'s #{itemName}")
    battle.pbCommonAnimation("UseItem", battler) if !forced
    if battler.effects[PBEffects::Attract] >= 0
      if forced
        battle.pbDisplay(_INTL("¡{1} se ha liberado del enamoramiento!", battler.pbThis))
      else
        battle.pbDisplay(_INTL("¡{1} se ha liberado del enamoramiento con {2}!",
           battler.pbThis, itemName))
      end
      battler.pbCureAttract
    end
    battle.pbDisplay(_INTL("¡{1} ya se ha olvidado de la mofa!", battler.pbThis)) if battler.effects[PBEffects::Taunt] > 0
    battler.effects[PBEffects::Taunt] = 0
    battle.pbDisplay(_INTL("¡{1} ya no sufre los efectos de Otra Vez!", battler.pbThis)) if battler.effects[PBEffects::Encore] > 0
    battler.effects[PBEffects::Encore]     = 0
    battler.effects[PBEffects::EncoreMove] = nil
    battle.pbDisplay(_INTL("¡Tormento ya no surte efecto en {1}!", battler.pbThis(true))) if battler.effects[PBEffects::Torment]
    battler.effects[PBEffects::Torment] = false
    battle.pbDisplay(_INTL("¡El movimiento de {1} ya no está anulado!", battler.pbThis(true))) if battler.effects[PBEffects::Disable] > 0
    battler.effects[PBEffects::Disable] = 0
    battle.pbDisplay(_INTL("¡Se han pasado los efectos de Anticura en {1}!", battler.pbThis(true))) if battler.effects[PBEffects::HealBlock] > 0
    battler.effects[PBEffects::HealBlock] = 0
    next true
  }
)

