HiddenMoveHandlers::ConfirmUseMove.add(:TELEPORT, proc { |move, pkmn|
  healing = $PokemonGlobal.healingSpot
  healing = GameData::PlayerMetadata.get($player.character_ID)&.home if !healing
  healing = GameData::Metadata.get.home if !healing   # Home
  next false if !healing
  mapname = pbGetMapNameFromId(healing[0])
  next pbConfirmMessage(_INTL("¿Quieres volver al último punto de cura en {1}?", mapname))
})

HiddenMoveHandlers::UseMove.add(:TELEPORT, proc { |move, pokemon|
  healing = $PokemonGlobal.healingSpot
  healing = GameData::PlayerMetadata.get($player.character_ID)&.home if !healing
  healing = GameData::Metadata.get.home if !healing   # Home
  next false if !healing
  if !pbHiddenMoveAnimation(pokemon)
    pbMessage(_INTL("¡{1} usó {2}!", pokemon.name, GameData::Move.get(move).name))
  end
  pbFadeOutIn do
    $game_temp.player_new_map_id    = healing[0]
    $game_temp.player_new_x         = healing[1]
    $game_temp.player_new_y         = healing[2]
    $game_temp.player_new_direction = 2
    pbDismountBike
    $scene.transfer_player
    $game_map.autoplay
    $game_map.refresh
  end
  pbEraseEscapePoint
  next true
})

#===============================================================================
# Waterfall
#===============================================================================
# Starts the ascending of a waterfall.
def pbAscendWaterfall
  return if $game_player.direction != 8   # Can't ascend if not facing up
  terrain = $game_player.pbFacingTerrainTag
  return if !terrain.waterfall && !terrain.waterfall_crest
  $stats.waterfall_count += 1
  $PokemonGlobal.ascending_waterfall = true
  $game_player.through = true
end

# Triggers after finishing each step while ascending/descending a waterfall.
def pbTraverseWaterfall
  if $game_player.direction == 2   # Facing down; descending
    terrain = $game_player.pbTerrainTag
    if ($DEBUG && Input.press?(Input::CTRL)) ||
       (!terrain.waterfall && !terrain.waterfall_crest)
      $PokemonGlobal.descending_waterfall = false
      $game_player.through = false
      return
    end
    $stats.waterfalls_descended += 1 if !$PokemonGlobal.descending_waterfall
    $PokemonGlobal.descending_waterfall = true
    $game_player.through = true
  elsif $PokemonGlobal.ascending_waterfall
    terrain = $game_player.pbTerrainTag
    if ($DEBUG && Input.press?(Input::CTRL)) ||
       (!terrain.waterfall && !terrain.waterfall_crest)
      $PokemonGlobal.ascending_waterfall = false
      $game_player.through = false
      return
    end
    $PokemonGlobal.ascending_waterfall = true
    $game_player.through = true
  end
end

def pbWaterfall
  move = :WATERFALL
  movefinder = Settings::USE_HM_WITHOUT_LEARNING_THEM ? $player.get_pokemon_can_learn_move(move) : $player.get_pokemon_with_move(move)
  if !pbCheckHiddenMoveBadge(Settings::BADGE_FOR_WATERFALL, false) || (!$DEBUG && !movefinder)
    pbMessage(_INTL("Un muro de agua cae con un estruendo ensordecedor."))
    return false
  end
  if pbConfirmMessage(_INTL("Es una gran cascada. ¿Te gustaría usar Cascada?"))
    speciesname = (movefinder) ? movefinder.name : $player.name
    pbMessage(_INTL("¡{1} usó {2}!", speciesname, GameData::Move.get(move).name))
    pbHiddenMoveAnimation(movefinder)
    pbAscendWaterfall
    return true
  end
  return false
end

EventHandlers.add(:on_player_interact, :waterfall,
  proc {
    terrain = $game_player.pbFacingTerrainTag
    if terrain.waterfall
      pbWaterfall
    elsif terrain.waterfall_crest
      pbMessage(_INTL("Un muro de agua cae con un estruendo ensordecedor."))
    end
  }
)

HiddenMoveHandlers::CanUseMove.add(:WATERFALL, proc { |move, pkmn, showmsg|
  next false if !pbCheckHiddenMoveBadge(Settings::BADGE_FOR_WATERFALL, showmsg)
  if !$game_player.pbFacingTerrainTag.waterfall
    pbMessage(_INTL("No se puede usar aquí.")) if showmsg
    next false
  end
  next true
})

HiddenMoveHandlers::UseMove.add(:WATERFALL, proc { |move, pokemon|
  if !pbHiddenMoveAnimation(pokemon)
    pbMessage(_INTL("¡{1} usó {2}!", pokemon.name, GameData::Move.get(move).name))
  end
  pbAscendWaterfall
  next true
})


==============================================================================
# Script: Overworld_Fishing
==============================================================================
#===============================================================================
# Fishing
#===============================================================================
def pbFishingBegin
  $PokemonGlobal.fishing = true
  if !pbCommonEvent(Settings::FISHING_BEGIN_COMMON_EVENT)
    $game_player.set_movement_type(($PokemonGlobal.surfing) ? :surf_fishing : :fishing)
    $game_player.lock_pattern = true
    4.times do |pattern|
      $game_player.pattern = 3 - pattern
      pbWait(0.05)
    end
  end
end

def pbFishingEnd
  if !pbCommonEvent(Settings::FISHING_END_COMMON_EVENT)
    4.times do |pattern|
      $game_player.pattern = pattern
      pbWait(0.05)
    end
  end
  yield if block_given?
  $game_player.set_movement_type(($PokemonGlobal.surfing) ? :surfing_stopped : :walking_stopped)
  $game_player.lock_pattern = false
  $game_player.straighten
  $PokemonGlobal.fishing = false
end

def pbFishing(hasEncounter, rodType = 1)
  $stats.fishing_count += 1
  speedup = ($player.first_pokemon && [:STICKYHOLD, :SUCTIONCUPS].include?($player.first_pokemon.ability_id))
  biteChance = 20 + (25 * rodType)   # 45, 70, 95
  biteChance *= 1.5 if speedup   # 67.5, 100, 100
  hookChance = 100
  pbFishingBegin
  msgWindow = pbCreateMessageWindow
  ret = false
  loop do
    time = rand(5..10)
    time = [time, rand(5..10)].min if speedup
    message = ""
    time.times { message += ".   " }
    if pbWaitMessage(msgWindow, time)
      pbFishingEnd { pbMessageDisplay(msgWindow, _INTL("Parece que no pican...")) }
      break
    end
    if hasEncounter && rand(100) < biteChance
      $scene.spriteset.addUserAnimation(Settings::EXCLAMATION_ANIMATION_ID, $game_player.x, $game_player.y, true, 3)
      duration = rand(5..10) / 10.0   # 0.5-1 seconds
      if !pbWaitForInput(msgWindow, message + "\n" + _INTL("¡Oh! ¡Han picado!"), duration)
        pbFishingEnd { pbMessageDisplay(msgWindow, _INTL("El Pokémon ha escapado...")) }
        break
      end
      if Settings::FISHING_AUTO_HOOK || rand(100) < hookChance
        pbFishingEnd do
          pbMessageDisplay(msgWindow, _INTL("¡Un Pokémon ha picado el anzuelo!")) if !Settings::FISHING_AUTO_HOOK
        end
        ret = true
        break
      end
#      biteChance += 15
#      hookChance += 15
    else
      pbFishingEnd { pbMessageDisplay(msgWindow, _INTL("Parece que no pican...")) }
      break
    end
  end
  pbDisposeMessageWindow(msgWindow)
  return ret
end

# Show waiting dots before a Pokémon bites
def pbWaitMessage(msgWindow, time)
  message = ""
  (time + 1).times do |i|
    message += ".   " if i > 0
    pbMessageDisplay(msgWindow, message, false)
    pbWait(0.4) do |delta_t|
      return true if Input.trigger?(Input::USE) || Input.trigger?(Input::BACK)
    end
  end
  return false
end

# A Pokémon is biting, reflex test to reel it in
def pbWaitForInput(msgWindow, message, duration)
  pbMessageDisplay(msgWindow, message, false)
  twitch_frame_duration = 0.2   # 0.2 seconds
  timer_start = System.uptime
  loop do
    Graphics.update
    Input.update
    pbUpdateSceneMap
    # Twitch cycle: 1,0,1,0,0,0,0,0
    twitch_frame = ((System.uptime - timer_start) / twitch_frame_duration).to_i % 8
    case twitch_frame
    when 0, 2
      $game_player.pattern = 1
    else
      $game_player.pattern = 0
    end
    if Input.trigger?(Input::USE) || Input.trigger?(Input::BACK)
      $game_player.pattern = 0
      return true
    end
    break if !Settings::FISHING_AUTO_HOOK && System.uptime - timer_start > duration
  end
  return false
end


==============================================================================
# Script: Overworld_BerryPlants
==============================================================================
#===============================================================================
# Represents a planted berry. Stored in $PokemonGlobal.eventvars.
#===============================================================================
class BerryPlantData
  attr_accessor :new_mechanics        # false for Gen 3, true for Gen 4
  attr_accessor :berry_id
  attr_accessor :mulch_id             # Gen 4 mechanics
  attr_accessor :time_alive
  attr_accessor :time_last_updated
  attr_accessor :growth_stage
  attr_accessor :replant_count
  attr_accessor :watered_this_stage   # Gen 3 mechanics
  attr_accessor :watering_count       # Gen 3 mechanics
  attr_accessor :moisture_level       # Gen 4 mechanics
  attr_accessor :yield_penalty        # Gen 4 mechanics

  def initialize
    reset
  end

  def reset(planting = false)
    @new_mechanics      = Settings::NEW_BERRY_PLANTS
    @berry_id           = nil
    @mulch_id           = nil if !planting
    @time_alive         = 0
    @time_last_updated  = 0
    @growth_stage       = 0
    @replant_count      = 0
    @watered_this_stage = false
    @watering_count     = 0
    @moisture_level     = 100
    @yield_penalty      = 0
  end

  def plant(berry_id)
    reset(true)
    @berry_id          = berry_id
    @growth_stage      = 1
    @time_last_updated = pbGetTimeNow.to_i
  end

  def replant
    @time_alive         = 0
    @growth_stage       = 2
    @replant_count      += 1
    @watered_this_stage = false
    @watering_count     = 0
    @moisture_level     = 100
    @yield_penalty      = 0
  end

  def planted?
    return @growth_stage > 0
  end

  def growing?
    return @growth_stage > 0 && @growth_stage < 5
  end

  def grown?
    return @growth_stage >= 5
  end

  def replanted?
    return @replant_count > 0
  end

  def moisture_stage
    return 0 if !@new_mechanics
    return 2 if @moisture_level > 50
    return 1 if @moisture_level > 0
    return 0
  end

  def water
    @moisture_level = 100
    if !@watered_this_stage
      @watered_this_stage = true
      @watering_count += 1
    end
  end

  def berry_yield
    data = GameData::BerryPlant.get(@berry_id)
    if @new_mechanics
      return [data.maximum_yield * (5 - @yield_penalty) / 5, data.minimum_yield].max
    elsif @watering_count > 0
      ret = (data.maximum_yield - data.minimum_yield) * (@watering_count - 1)
      ret += rand(1 + data.maximum_yield - data.minimum_yield)
      return (ret / 4) + data.minimum_yield
    end
    return data.minimum_yield
  end

  # Old mechanics only update a plant when its map is loaded. New mechanics
  # update it every frame while its map is loaded.
  def update
    return if !planted?
    time_now = pbGetTimeNow
    time_delta = time_now.to_i - @time_last_updated
    return if time_delta <= 0
    new_time_alive = @time_alive + time_delta
    # Get all growth data
    plant_data = GameData::BerryPlant.get(@berry_id)
    time_per_stage = plant_data.hours_per_stage * 3600   # In seconds
    drying_per_hour = plant_data.drying_per_hour
    max_replants = GameData::BerryPlant::NUMBER_OF_REPLANTS
    stages_growing = GameData::BerryPlant::NUMBER_OF_GROWTH_STAGES
    stages_fully_grown = GameData::BerryPlant::NUMBER_OF_FULLY_GROWN_STAGES
    case @mulch_id
    when :GROWTHMULCH
      time_per_stage = (time_per_stage * 0.75).to_i
      drying_per_hour = (drying_per_hour * 1.5).ceil
    when :DAMPMULCH
      time_per_stage = (time_per_stage * 1.25).to_i
      drying_per_hour /= 2
    when :GOOEYMULCH
      max_replants = (max_replants * 1.5).ceil
    when :STABLEMULCH
      stages_fully_grown = (stages_fully_grown * 1.5).ceil
    end
    # Do replants
    done_replant = false
    loop do
      stages_this_life = stages_growing + stages_fully_grown - (replanted? ? 1 : 0)
      break if new_time_alive < stages_this_life * time_per_stage
      if @replant_count >= max_replants
        reset
        return
      end
      replant
      done_replant = true
      new_time_alive -= stages_this_life * time_per_stage
    end
    # Update how long plant has been alive for
    old_growth_stage = @growth_stage
    @time_alive = new_time_alive
    @growth_stage = 1 + (@time_alive / time_per_stage)
    @growth_stage += 1 if replanted?   # Replants start at stage 2
    @time_last_updated = time_now.to_i
    # Record watering (old mechanics), and apply drying out per hour (new mechanics)
    if @new_mechanics
      old_growth_hour = (done_replant) ? 0 : (@time_alive - time_delta) / 3600
      new_growth_hour = @time_alive / 3600
      if new_growth_hour > old_growth_hour
        (new_growth_hour - old_growth_hour).times do
          if @moisture_level > 0
            @moisture_level -= drying_per_hour
          else
            @yield_penalty += 1
          end
        end
      end
    else
      old_growth_stage = 0 if done_replant
      new_growth_stage = [@growth_stage, stages_growing + 1].min
      @watered_this_stage = false if new_growth_stage > old_growth_stage
      water if $game_screen && GameData::Weather.get($game_screen.weather_type).category == :Rain
    end
  end
end

#===============================================================================
#
#===============================================================================
class BerryPlantMoistureSprite
  def initialize(event, map, viewport = nil)
    @event          = event
    @map            = map
    @sprite         = IconSprite.new(0, 0, viewport)
    @sprite.ox      = 16
    @sprite.oy      = 24
    @moisture_stage = -1   # -1 = none, 0 = dry, 1 = damp, 2 = wet
    @disposed       = false
    update_graphic
  end

  def dispose
    @sprite.dispose
    @map      = nil
    @event    = nil
    @disposed = true
  end

  def disposed?
    return @disposed
  end

  def update_graphic
    case @moisture_stage
    when -1 then @sprite.setBitmap("")
    when 0  then @sprite.setBitmap("Graphics/Characters/berrytreedry")
    when 1  then @sprite.setBitmap("Graphics/Characters/berrytreedamp")
    when 2  then @sprite.setBitmap("Graphics/Characters/berrytreewet")
    end
  end

  def update
    return if !@sprite || !@event
    new_moisture = -1
    berry_plant = @event.variable
    if berry_plant.is_a?(BerryPlantData) && berry_plant.planted?
      new_moisture = berry_plant.moisture_stage
    end
    if new_moisture != @moisture_stage
      @moisture_stage = new_moisture
      update_graphic
    end
    @sprite.update
    @sprite.x      = ScreenPosHelper.pbScreenX(@event)
    @sprite.y      = ScreenPosHelper.pbScreenY(@event)
    @sprite.zoom_x = ScreenPosHelper.pbScreenZoomX(@event)
    @sprite.zoom_y = @sprite.zoom_x
    pbDayNightTint(@sprite)
  end
end

#===============================================================================
#
#===============================================================================
class BerryPlantSprite
  def initialize(event, map, _viewport)
    @event     = event
    @map       = map
    @old_stage = 0
    @disposed  = false
    berry_plant = event.variable
    return if !berry_plant
    @old_stage = berry_plant.growth_stage
    @event.character_name = ""
    update_plant(berry_plant)
    set_event_graphic(berry_plant, true)   # Set the event's graphic
  end

  def dispose
    @event    = nil
    @map      = nil
    @disposed = true
  end

  def disposed?
    @disposed
  end

  def set_event_graphic(berry_plant, full_check = false)
    return if !berry_plant || (berry_plant.growth_stage == @old_stage && !full_check)
    case berry_plant.growth_stage
    when 0
      @event.character_name = ""
    else
      if berry_plant.growth_stage == 1
        @event.character_name = "berrytreeplanted"   # Common to all berries
        @event.turn_down
      else
        filename = sprintf("berrytree_%s", GameData::Item.get(berry_plant.berry_id).id.to_s)
        if pbResolveBitmap("Graphics/Characters/" + filename)
          @event.character_name = filename
          case berry_plant.growth_stage
          when 2 then @event.turn_down    # X sprouted
          when 3 then @event.turn_left    # X taller
          when 4 then @event.turn_right   # X flowering
          else
            @event.turn_up if berry_plant.growth_stage >= 5   # X berries
          end
        else
          @event.character_name = "Object ball"
        end
      end
      if berry_plant.new_mechanics && @old_stage != berry_plant.growth_stage &&
         @old_stage > 0 && berry_plant.growth_stage <= GameData::BerryPlant::NUMBER_OF_GROWTH_STAGES + 1
        spriteset = $scene.spriteset(@map.map_id)
        spriteset&.addUserAnimation(Settings::PLANT_SPARKLE_ANIMATION_ID,
                                    @event.x, @event.y, false, 1)
      end
    end
    @old_stage = berry_plant.growth_stage
  end

  def update_plant(berry_plant, initial = false)
    berry_plant.update if berry_plant.planted? && (initial || berry_plant.new_mechanics)
  end

  def update
    berry_plant = @event.variable
    return if !berry_plant
    update_plant(berry_plant)
    set_event_graphic(berry_plant)
  end
end

