EventHandlers.add(:on_new_spriteset_map, :add_berry_plant_graphics,
  proc { |spriteset, viewport|
    map = spriteset.map
    map.events.each do |event|
      next if !event[1].name[/planta bayas/i]
      spriteset.addUserSprite(BerryPlantMoistureSprite.new(event[1], map, viewport))
      spriteset.addUserSprite(BerryPlantSprite.new(event[1], map, viewport))
    end
  }
)

#===============================================================================
#
#===============================================================================
def pbBerryPlant
  interp = pbMapInterpreter
  this_event = interp.get_self
  berry_plant = interp.getVariable
  if !berry_plant
    berry_plant = BerryPlantData.new
    interp.setVariable(berry_plant)
  end
  berry = berry_plant.berry_id
  # Interact with the event based on its growth
  if berry_plant.grown?
    this_event.turn_up   # Stop the event turning towards the player
    berry_plant.reset if pbPickBerry(berry, berry_plant.berry_yield)
    return
  elsif berry_plant.growing?
    berry_name = GameData::Item.get(berry).name
    case berry_plant.growth_stage
    when 1   # X planted
      this_event.turn_down   # Stop the event turning towards the player
      if berry_name.starts_with_vowel?
        pbMessage(_INTL("Una {1} se ha plantado aquí.", berry_name))
      else
        pbMessage(_INTL("Una {1} se ha plantado aquí.", berry_name))
      end
    when 2   # X sprouted
      this_event.turn_down   # Stop the event turning towards the player
      pbMessage(_INTL("La {1} ha germinado.", berry_name))
    when 3   # X taller
      this_event.turn_left   # Stop the event turning towards the player
      pbMessage(_INTL("La planta de {1} está creciendo.", berry_name))
    else     # X flowering
      this_event.turn_right   # Stop the event turning towards the player
      if Settings::NEW_BERRY_PLANTS
        pbMessage(_INTL("¡Esta planta de {1} ha florecido!", berry_name))
      else
        case berry_plant.watering_count
        when 4
          pbMessage(_INTL("¡Esta planta de {1} ha florecido fabulosamente!", berry_name))
        when 3
          pbMessage(_INTL("¡Esta planta de {1} ha florecido muy hermosa!", berry_name))
        when 2
          pbMessage(_INTL("¡Esta planta de {1} ha florecido muy bonita!", berry_name))
        when 1
          pbMessage(_INTL("¡Esta planta de {1} ha florecido muy linda!", berry_name))
        else
          pbMessage(_INTL("¡Esta planta de {1} ha florecido!", berry_name))
        end
      end
    end
    # Water the growing plant
    GameData::BerryPlant::WATERING_CANS.each do |item|
      next if !$bag.has?(item)
      break if !pbConfirmMessage(_INTL("¿Quieres regarla un poco con {1}?",
                                       GameData::Item.get(item).name))
      berry_plant.water
      pbMessage("\\se[Water berry plant]" + _INTL("{1} regó la planta.", $player.name) + "\\wtnp[40]")
      if Settings::NEW_BERRY_PLANTS
        pbMessage(_INTL("¡Ya tienes agüita!"))
      else
        pbMessage(_INTL("La planta parece estar encantada."))
      end
      break
    end
    return
  end
  # Nothing planted yet
  ask_to_plant = true
  if Settings::NEW_BERRY_PLANTS
    # New mechanics
    if berry_plant.mulch_id
      pbMessage(_INTL("{1} se ha colocado.", GameData::Item.get(berry_plant.mulch_id).name))
    else
      case pbMessage(_INTL("La tierra está fértil."),
                     [_INTL("Fertilizar"), _INTL("Plantar Baya"), _INTL("Salir")], -1)
      when 0   # Fertilize
        mulch = nil
        pbFadeOutIn do
          scene = PokemonBag_Scene.new
          screen = PokemonBagScreen.new(scene, $bag)
          mulch = screen.pbChooseItemScreen(proc { |item| GameData::Item.get(item).is_mulch? })
        end
        return if !mulch
        mulch_data = GameData::Item.get(mulch)
        if mulch_data.is_mulch?
          berry_plant.mulch_id = mulch
          $bag.remove(mulch)
          pbMessage(_INTL("La {1} se ha enterrado en la tierra.", mulch_data.name))
        else
          pbMessage(_INTL("¡Eso no va a fertilizar la tierra!"))
          return
        end
      when 1   # Plant Berry
        ask_to_plant = false
      else   # Exit/cancel
        return
      end
    end
  else
    # Old mechanics
    return if !pbConfirmMessage(_INTL("La tierra está suelta y fértil. ¿Quieres plantar una baya?"))
    ask_to_plant = false
  end
  if !ask_to_plant || pbConfirmMessage(_INTL("¿Quieres plantar una baya?"))
    pbFadeOutIn do
      scene = PokemonBag_Scene.new
      screen = PokemonBagScreen.new(scene, $bag)
      berry = screen.pbChooseItemScreen(proc { |item| GameData::Item.get(item).is_berry? })
    end
    if berry
      $stats.berries_planted += 1
      berry_plant.plant(berry)
      $bag.remove(berry)
      if Settings::NEW_BERRY_PLANTS
        pbMessage(_INTL("La {1} se ha plantado en la tierra.",
                        GameData::Item.get(berry).name))
      elsif GameData::Item.get(berry).name.starts_with_vowel?
        pbMessage(_INTL("{1} plantó una {2} en la tierra fértil.",
                        $player.name, GameData::Item.get(berry).name))
      else
        pbMessage(_INTL("{1} plantó una {2} en la tierra fértil.",
                        $player.name, GameData::Item.get(berry).name))
      end
    end
  end
end

#===============================================================================
#
#===============================================================================
def pbPickBerry(berry, qty = 1)
  berry = GameData::Item.get(berry)
  berry_name = (qty > 1) ? berry.portion_name_plural : berry.portion_name
  if qty > 1
    message = _INTL("¡Hay {1} \\c[1]{2}\\c[0]!\n¿Quieres recogerlas?", qty, berry_name)
  else
    message = _INTL("¡Hay 1 \\c[1]{1}\\c[0]!\n¿Quieres recogerla?", berry_name)
  end
  return false if !pbConfirmMessage(message)
  if !$bag.can_add?(berry, qty)
    pbMessage(_INTL("Qué mal...\nLa Mochila está llena..."))
    return false
  end
  $stats.berry_plants_picked += 1
  if qty >= GameData::BerryPlant.get(berry.id).maximum_yield
    $stats.max_yield_berry_plants += 1
  end
  $bag.add(berry, qty)
  if qty > 1
    pbMessage("\\me[Berry get]" + _INTL("Has recogido las {1} \\c[1]{2}\\c[0].", qty, berry_name) + "\\wtnp[30]")
  else
    pbMessage("\\me[Berry get]" + _INTL("Has recogido la \\c[1]{1}\\c[0].", berry_name) + "\\wtnp[30]")
  end
  pocket = berry.pocket
  pbMessage(_INTL("Has puesto {1} en\\nel bolsillo <icon=bagPocket{2}>\\c[1]{3}\\c[0].",
                  berry_name, pocket, PokemonBag.pocket_names[pocket - 1]) + "\1")
  if Settings::NEW_BERRY_PLANTS
    pbMessage(_INTL("La tierra ha vuelto a su estado fértil."))
  else
    pbMessage(_INTL("La tierra ha vuelto a su estado fértil."))
  end
  this_event = pbMapInterpreter.get_self
  pbSetSelfSwitch(this_event.id, "A", true)
  return true
end


==============================================================================
# Script: Overworld_DayCare
==============================================================================
#===============================================================================
# NOTE: In Gen 7+, the Day Care is replaced by the Pokémon Nursery, which works
#       in much the same way except deposited Pokémon no longer gain Exp because
#       of the player walking around and, in Gen 8+, deposited Pokémon are able
#       to learn egg moves from each other if they are the same species. In
#       Essentials, this code can be used for both facilities, and these
#       mechanics differences are set by some Settings.
# NOTE: The Day Care has a different price than the Pokémon Nursery. For the Day
#       Care, you are charged when you withdraw a deposited Pokémon and you pay
#       an amount based on how many levels it gained. For the Nursery, you pay
#       $500 up-front when you deposit a Pokémon. This difference will appear in
#       the Day Care Lady's event, not in these scripts.
#===============================================================================
class DayCare
  #=============================================================================
  # Code that generates an egg based on two given Pokémon.
  #=============================================================================
  module EggGenerator
    module_function

    def generate(mother, father)
      # Determine which Pokémon is the mother and which is the father
      # Ensure mother is female, if the pair contains a female
      # Ensure father is male, if the pair contains a male
      # Ensure father is genderless, if the pair is a genderless with Ditto
      if mother.male? || father.female? || mother.genderless?
        mother, father = father, mother
      end
      mother_data = [mother, mother.species_data.egg_groups.include?(:Ditto)]
      father_data = [father, father.species_data.egg_groups.include?(:Ditto)]
      # Determine which parent the egg's species is based from
      species_parent = (mother_data[1]) ? father : mother
      # Determine the egg's species
      baby_species = determine_egg_species(species_parent.species, mother, father)
      mother_data.push(mother.species_data.breeding_can_produce?(baby_species))
      father_data.push(father.species_data.breeding_can_produce?(baby_species))
      # Generate egg
      egg = generate_basic_egg(baby_species)
      # Inherit properties from parent(s)
      inherit_form(egg, species_parent, mother_data, father_data)
      inherit_nature(egg, mother, father)
      inherit_ability(egg, mother_data, father_data)
      inherit_moves(egg, mother_data, father_data)
      inherit_IVs(egg, mother, father)
      inherit_poke_ball(egg, mother_data, father_data)
      # Calculate other properties of the egg
      set_shininess(egg, mother, father)   # Masuda method and Shiny Charm
      set_pokerus(egg)
      # Recalculate egg's stats
      egg.calc_stats
      return egg
    end

    def determine_egg_species(parent_species, mother, father)
      ret = GameData::Species.get(parent_species).get_baby_species(true, mother.item_id, father.item_id)
      # Check for alternate offspring (i.e. Nidoran M/F, Volbeat/Illumise, Manaphy/Phione)
      offspring = GameData::Species.get(ret).offspring
      ret = offspring.sample if offspring.length > 0
      return ret
    end

    def generate_basic_egg(species)
      egg = Pokemon.new(species, Settings::EGG_LEVEL)
      egg.name           = _INTL("Huevo")
      egg.steps_to_hatch = egg.species_data.hatch_steps
      egg.obtain_text    = _INTL("Pareja Guardería")
      egg.happiness      = 120
      egg.form           = 0 if species == :SINISTEA
      # Set regional form
      new_form = MultipleForms.call("getFormOnEggCreation", egg)
      egg.form = new_form if new_form
      return egg
    end

    def inherit_form(egg, species_parent, mother, father)
      # mother = [mother, mother_ditto, mother_in_family]
      # father = [father, father_ditto, father_in_family]
      # Inherit form from the parent that determined the egg's species
      if species_parent.species_data.has_flag?("InheritFormFromMother")
        egg.form = species_parent.form
      end
      # Inherit form from a parent holding an Ever Stone
      [mother, father].each do |parent|
        next if !parent[2]   # Parent isn't a related species to the egg
        next if !parent[0].species_data.has_flag?("InheritFormWithEverStone")
        next if !parent[0].hasItem?(:EVERSTONE)
        egg.form = parent[0].form
        break
      end
    end

    def get_moves_to_inherit(egg, mother, father)
      # mother = [mother, mother_ditto, mother_in_family]
      # father = [father, father_ditto, father_in_family]
      move_father = (father[1]) ? mother[0] : father[0]
      move_mother = (father[1]) ? father[0] : mother[0]
      moves = []
      # Get level-up moves known by both parents
      egg.getMoveList.each do |move|
        next if move[0] <= egg.level   # Could already know this move by default
        next if !mother[0].hasMove?(move[1]) || !father[0].hasMove?(move[1])
        moves.push(move[1])
      end
      # Inherit Machine moves from father (or non-Ditto genderless parent)
      if Settings::BREEDING_CAN_INHERIT_MACHINE_MOVES && !move_father.female?
        GameData::Item.each do |i|
          move = i.move
          next if !move
          next if !move_father.hasMove?(move) || !egg.compatible_with_move?(move)
          moves.push(move)
        end
      end
      # Inherit egg moves from each parent
      if !move_father.female?
        egg.species_data.egg_moves.each do |move|
          moves.push(move) if move_father.hasMove?(move)
        end
      end
      if Settings::BREEDING_CAN_INHERIT_EGG_MOVES_FROM_MOTHER && move_mother.female?
        egg.species_data.egg_moves.each do |move|
          moves.push(move) if move_mother.hasMove?(move)
        end
      end
      # Learn Volt Tackle if a parent has a Light Ball and is in the Pichu family
      if egg.species == :PICHU && GameData::Move.exists?(:VOLTTACKLE) &&
         ((father[2] && father[0].hasItem?(:LIGHTBALL)) ||
          (mother[2] && mother[0].hasItem?(:LIGHTBALL)))
        moves.push(:VOLTTACKLE)
      end
      return moves
    end

    def inherit_moves(egg, mother, father)
      moves = get_moves_to_inherit(egg, mother, father)
      # Remove duplicates (keeping the latest ones)
      moves = moves.reverse
      moves |= []   # remove duplicates
      moves = moves.reverse
      # Learn moves
      first_move_index = moves.length - Pokemon::MAX_MOVES
      first_move_index = 0 if first_move_index < 0
      (first_move_index...moves.length).each { |i| egg.learn_move(moves[i]) }
    end

    def inherit_nature(egg, mother, father)
      new_natures = []
      new_natures.push(mother.nature) if mother.hasItem?(:EVERSTONE)
      new_natures.push(father.nature) if father.hasItem?(:EVERSTONE)
      return if new_natures.empty?
      egg.nature = new_natures.sample
    end

    # The female parent (or the non-Ditto parent) can pass down its Hidden
    # Ability (60% chance) or its regular ability (80% chance).
    # NOTE: This is how ability inheritance works in Gen 6+. Gen 5 is more
    #       restrictive, and even works differently between BW and B2W2, and I
    #       don't think that is worth adding in. Gen 4 and lower don't have
    #       ability inheritance at all, and again, I'm not bothering to add that
    #       in.
    def inherit_ability(egg, mother, father)
      # mother = [mother, mother_ditto, mother_in_family]
      # father = [father, father_ditto, father_in_family]
      parent = (mother[1]) ? father[0] : mother[0]   # The female or non-Ditto parent
      if parent.hasHiddenAbility?
        egg.ability_index = parent.ability_index if rand(100) < 60
      elsif rand(100) < 80
        egg.ability_index = parent.ability_index
      else
        egg.ability_index = (parent.ability_index + 1) % 2
      end
    end

    def inherit_IVs(egg, mother, father)
      # Get all stats
      stats = []
      GameData::Stat.each_main { |s| stats.push(s.id) }
      # Get the number of stats to inherit (includes ones inherited via Power items)
      inherit_count = 3
      if Settings::MECHANICS_GENERATION >= 6
        inherit_count = 5 if mother.hasItem?(:DESTINYKNOT) || father.hasItem?(:DESTINYKNOT)
      end
      # Inherit IV because of Power items (if both parents have the same Power
      # item, then the parent that passes that Power item's stat down is chosen
      # randomly)
      power_items = [
        [:POWERWEIGHT, :HP],
        [:POWERBRACER, :ATTACK],
        [:POWERBELT,   :DEFENSE],
        [:POWERLENS,   :SPECIAL_ATTACK],
        [:POWERBAND,   :SPECIAL_DEFENSE],
        [:POWERANKLET, :SPEED]
      ]
      power_stats = {}
      [mother, father].each do |parent|
        power_items.each do |item|
          next if !parent.hasItem?(item[0])
          power_stats[item[1]] ||= []
          power_stats[item[1]].push(parent.iv[item[1]])
          break
        end
      end
      power_stats.each_pair do |stat, new_stats|
        next if !new_stats || new_stats.length == 0
        new_stat = new_stats.sample
        egg.iv[stat] = new_stat
        stats.delete(stat)   # Don't try to inherit this stat's IV again
        inherit_count -= 1
      end
      # Inherit the rest of the IVs
      chosen_stats = stats.sample(inherit_count)
      chosen_stats.each { |stat| egg.iv[stat] = [mother, father].sample.iv[stat] }
    end

    # Poké Balls can only be inherited from parents that are related to the
    # egg's species.
    # NOTE: This is how Poké Ball inheritance works in Gen 7+. Gens 5 and lower
    #       don't have Poké Ball inheritance at all. In Gen 6, only a female
    #       parent can pass down its Poké Ball. I don't think it's worth adding
    #       in these variations on the mechanic.
    # NOTE: The official games treat Nidoran M/F and Volbeat/Illumise as
    #       unrelated for the purpose of this mechanic. Essentials treats them
    #       as related and allows them to pass down their Poké Balls.
    def inherit_poke_ball(egg, mother, father)
      # mother = [mother, mother_ditto, mother_in_family]
      # father = [father, father_ditto, father_in_family]
      balls = []
      [mother, father].each do |parent|
        balls.push(parent[0].poke_ball) if parent[2]
      end
      balls.delete(:MASTERBALL)    # Can't inherit this Ball
      balls.delete(:CHERISHBALL)   # Can't inherit this Ball
      egg.poke_ball = balls.sample if !balls.empty?
    end

    # NOTE: There is a bug in Gen 8 that skips the original generation of an
    #       egg's personal ID if the Masuda Method/Shiny Charm can cause any
    #       rerolls. Essentials doesn't have this bug, meaning eggs are slightly
    #       more likely to be shiny (in Gen 8+ mechanics) than in Gen 8 itself.
    def set_shininess(egg, mother, father)
      shiny_retries = 0
      if father.owner.language != mother.owner.language
        shiny_retries += (Settings::MECHANICS_GENERATION >= 8) ? 6 : 5
      end
      shiny_retries += 2 if $bag.has?(:SHINYCHARM)
      return if shiny_retries == 0
      shiny_retries.times do
        break if egg.shiny?
        egg.shiny = nil   # Make it recalculate shininess
        egg.personalID = rand(2**16) | (rand(2**16) << 16)
      end
    end

    def set_pokerus(egg)
      egg.givePokerus if rand(65_536) < Settings::POKERUS_CHANCE
    end
  end

  #=============================================================================
  # A slot in the Day Care, which can contain a Pokémon.
  #=============================================================================
  class DayCareSlot
    attr_reader :pokemon

    def initialize
      reset
    end

    def reset
      @pokemon = nil
      @initial_level = 0
    end

    def deposit(pkmn)
      @pokemon = pkmn
      @pokemon.heal
      @pokemon.form = 0 if @pokemon.isSpecies?(:SHAYMIN)
      @initial_level = pkmn.level
    end

    def filled?
      return !@pokemon.nil?
    end

    def pokemon_name
      return (filled?) ? @pokemon.name : ""
    end

    def level_gain
      return (filled?) ? @pokemon.level - @initial_level : 0
    end

    def cost
      return (level_gain + 1) * 100
    end

    def choice_text
      return nil if !filled?
      if @pokemon.male?
        return _INTL("{1} (♂, Nv.{2})", @pokemon.name, @pokemon.level)
      elsif @pokemon.female?
        return _INTL("{1} (♀, Nv.{2})", @pokemon.name, @pokemon.level)
      end
      return _INTL("{1} (Nv.{2})", @pokemon.name, @pokemon.level)
    end

    def add_exp(amount = 1)
      return if !filled?
      max_exp = @pokemon.growth_rate.maximum_exp
      return if @pokemon.exp >= max_exp
      old_level = @pokemon.level
      @pokemon.exp += amount
      return if @pokemon.level == old_level
      @pokemon.calc_stats
      move_list = @pokemon.getMoveList
      move_list.each { |move| @pokemon.learn_move(move[1]) if move[0] == @pokemon.level }
    end
  end

  #=============================================================================

  attr_reader   :slots
  attr_accessor :egg_generated
  attr_accessor :step_counter
  attr_accessor :gain_exp
  attr_accessor :share_egg_moves   # For deposited Pokémon of the same species

  MAX_SLOTS = 2

  def initialize
    @slots = []
    MAX_SLOTS.times { @slots.push(DayCareSlot.new) }
    reset_egg_counters
    @gain_exp = Settings::DAY_CARE_POKEMON_GAIN_EXP_FROM_WALKING
    @share_egg_moves = Settings::DAY_CARE_POKEMON_CAN_SHARE_EGG_MOVES
  end

  def [](index)
    return @slots[index]
  end

  def reset_egg_counters
    @egg_generated = false
    @step_counter = 0
  end

  def count
    return @slots.select { |slot| slot.filled? }.length
  end

  def get_compatibility
    return compatibility
  end

  def generate_egg
    return nil if self.count != 2
    pkmn1, pkmn2 = pokemon_pair
    return EggGenerator.generate(pkmn1, pkmn2)
  end

  def share_egg_move
    return if count != 2
    pkmn1, pkmn2 = pokemon_pair
    return if pkmn1.species != pkmn2.species
    egg_moves1 = pkmn1.species_data.get_egg_moves
    egg_moves2 = pkmn2.species_data.get_egg_moves
    known_moves1 = []
    known_moves2 = []
    if pkmn2.numMoves < Pokemon::MAX_MOVES
      pkmn1.moves.each { |m| known_moves1.push(m.id) if egg_moves2.include?(m.id) && !pkmn2.hasMove?(m.id) }
    end
    if pkmn1.numMoves < Pokemon::MAX_MOVES
      pkmn2.moves.each { |m| known_moves2.push(m.id) if egg_moves1.include?(m.id) && !pkmn1.hasMove?(m.id) }
    end
    if !known_moves1.empty?
      if known_moves2.empty?
        pkmn2.learn_move(known_moves1[0])
      else
        learner = [[pkmn1, known_moves2[0]], [pkmn2, known_moves1[0]]].sample
        learner[0].learn_move(learner[1])
      end
    elsif !known_moves2.empty?
      pkmn1.learn_move(known_moves2[0])
    end
  end

  def update_on_step_taken
    @step_counter += 1
    if @step_counter >= 256
      @step_counter = 0
      # Make an egg available at the Day Care
      if !@egg_generated && count == 2
        compat = compatibility
        egg_chance = [0, 20, 50, 70][compat]
        egg_chance = [0, 40, 80, 88][compat] if $bag.has?(:OVALCHARM)
        @egg_generated = true if rand(100) < egg_chance
      end
      # Have one deposited Pokémon learn an egg move from the other
      # NOTE: I don't know what the chance of this happening is.
      share_egg_move if @share_egg_moves && rand(100) < 50
    end
    # Day Care Pokémon gain Exp/moves
    if @gain_exp
      @slots.each { |slot| slot.add_exp }
    end
  end

  #-----------------------------------------------------------------------------

  def self.count
    return $PokemonGlobal.day_care.count
  end

  def self.egg_generated?
    return $PokemonGlobal.day_care.egg_generated
  end

  def self.reset_egg_counters
    $PokemonGlobal.day_care.reset_egg_counters
  end

  def self.get_details(index, name_var, cost_var)
    day_care = $PokemonGlobal.day_care
    $game_variables[name_var] = day_care[index].pokemon_name if name_var > 0
    $game_variables[cost_var] = day_care[index].cost if cost_var > 0
  end

  def self.get_level_gain(index, name_var, level_var)
    day_care = $PokemonGlobal.day_care
    $game_variables[name_var] = day_care[index].pokemon_name if name_var > 0
    $game_variables[level_var] = day_care[index].level_gain if level_var > 0
  end

  def self.get_compatibility(compat_var)
    $game_variables[compat_var] = $PokemonGlobal.day_care.get_compatibility if compat_var > 0
  end

  def self.deposit(party_index)
    $stats.day_care_deposits += 1
    day_care = $PokemonGlobal.day_care
    pkmn = $player.party[party_index]
    raise _INTL("No hay Pokémon en el índice {1} del equipo.", party_index) if pkmn.nil?
    day_care.slots.each do |slot|
      next if slot.filled?
      slot.deposit(pkmn)
      $player.party.delete_at(party_index)
      day_care.reset_egg_counters
      return
    end
    raise _INTL("No hay espacio para dejar Pokémon.")
  end

  def self.withdraw(index)
    day_care = $PokemonGlobal.day_care
    slot = day_care[index]
    if !slot.filled?
      raise _INTL("No se encuentra Pokémon en el espacio {1}.", index)
    elsif $player.party_full?
      raise _INTL("No hay espacio en el equipo para Pokémon.")
    end
    $stats.day_care_levels_gained += slot.level_gain
    $player.party.push(slot.pokemon)
    slot.reset
    day_care.reset_egg_counters
  end

  def self.choose(message, choice_var)
    day_care = $PokemonGlobal.day_care
    case day_care.count
    when 0
      raise _INTL("No hay Pokémon en la Guardería para elegir.")
    when 1
      day_care.slots.each_with_index { |slot, i| $game_variables[choice_var] = i if slot.filled? }
    else
      commands = []
      indices = []
      day_care.slots.each_with_index do |slot, i|
        choice_text = slot.choice_text
        next if !choice_text
        commands.push(choice_text)
        indices.push(i)
      end
      commands.push(_INTL("CANCELAR"))
      command = pbMessage(message, commands, commands.length)
      $game_variables[choice_var] = (command == commands.length - 1) ? -1 : indices[command]
    end
  end

  def self.collect_egg
    day_care = $PokemonGlobal.day_care
    egg = day_care.generate_egg
    given = false
    raise _INTL("No se puede generar el Huevo.") if egg.nil?
    raise _INTL("No hay espacio en el equipo para el Huevo.") unless can_add_egg?
    if incubator_has_space?
      ret = Kernel.pbConfirmMessage("¿Quieres agregar el Huevo a la incubadora?")
      if ret == true
        ret = addEgg(egg)
        if ret == true
          given = true
        end
      elsif !$player.party_full?
        $player.party.push(egg)
        given = true
      else
        return false
      end
    elsif !$player.party_full?
      $player.party.push(egg)
      given = true
    else
      return false
    end
    day_care.reset_egg_counters
    return given
  end

  #-----------------------------------------------------------------------------

  private

  def pokemon_pair
    pkmn1 = nil
    pkmn2 = nil
    @slots.each do |slot|
      next if !slot.filled?
      if pkmn1.nil?
        pkmn1 = slot.pokemon
      else
        pkmn2 = slot.pokemon
      end
    end
    raise _INTL("No se encuentran 2 Pokémon depositados.") if pkmn2.nil?
    return pkmn1, pkmn2
  end

  def pokemon_in_ditto_egg_group?(pkmn)
    return pkmn.species_data.egg_groups.include?(:Ditto)
  end

  def compatible_gender?(pkmn1, pkmn2)
    return true if pkmn1.female? && pkmn2.male?
    return true if pkmn1.male? && pkmn2.female?
    ditto1 = pokemon_in_ditto_egg_group?(pkmn1)
    ditto2 = pokemon_in_ditto_egg_group?(pkmn2)
    return true if ditto1 && !ditto2
    return true if ditto2 && !ditto1
    return false
  end

  def compatibility
    return 0 if self.count != 2
    # Find the Pokémon whose compatibility is being calculated
    pkmn1, pkmn2 = pokemon_pair
    # Shadow Pokémon cannot breed
    return 0 if pkmn1.shadowPokemon? || pkmn2.shadowPokemon?
    # Pokémon in the Undiscovered egg group cannot breed
    egg_groups1 = pkmn1.species_data.egg_groups
    egg_groups2 = pkmn2.species_data.egg_groups
    return 0 if egg_groups1.include?(:Undiscovered) ||
                egg_groups2.include?(:Undiscovered)
    # Pokémon that don't share an egg group (and neither is in the Ditto group)
    # cannot breed
    return 0 if !egg_groups1.include?(:Ditto) &&
                !egg_groups2.include?(:Ditto) &&
                (egg_groups1 & egg_groups2).length == 0
    # Pokémon with incompatible genders cannot breed
    return 0 if !compatible_gender?(pkmn1, pkmn2)
    # Pokémon can breed; calculate a compatibility factor
    ret = 1
    ret += 1 if pkmn1.species == pkmn2.species
    ret += 1 if pkmn1.owner.id != pkmn2.owner.id
    return ret
  end
end

#===============================================================================
# With each step taken, add Exp to Pokémon in the Day Care and try to generate
# an egg.
#===============================================================================
EventHandlers.add(:on_player_step_taken, :update_day_care,
  proc {
    $PokemonGlobal.day_care.update_on_step_taken
  }
)


==============================================================================
# Script: Overworld_RandomDungeons
==============================================================================
#===============================================================================
# Code that generates a random dungeon layout, and implements it in a given map.
#===============================================================================
module RandomDungeon
  #=============================================================================
  # Bitwise values used to keep track of the generation of node connections.
  #=============================================================================
  module EdgeMasks
    NORTH = 1
    EAST  = 2
    SOUTH = 4
    WEST  = 8
  end

  #=============================================================================
  # A node in a randomly generated dungeon. There is one node per cell, and
  # nodes are connected to each other.
  #=============================================================================
  class MazeNode
    def initialize
      @visitable = false
      @visited   = false
      @room      = false
      block_all_edges   # A bit being 1 means its edge is NOT connected to the adjacent node
    end

    def edge_pattern;       return @edges;            end
    def block_edge(e);      @edges |= e;              end
    def connect_edge(e);    @edges &= ~e;             end
    def block_all_edges;    @edges = 15;              end
    def connect_all_edges;  @edges = 0;               end
    def edge_blocked?(e);   return (@edges & e) != 0; end
    def all_edges_blocked?; return @edges != 0;       end
    def visitable?;         return @visitable;        end
    def set_visitable;      @visitable = true;        end
    def visited?;           return @visited;          end
    def set_visited;        @visited = true;          end
    def room?;              return @room;             end
    def set_room;           @room = true;             end
  end

  #=============================================================================
  # Maze generator. Given the number of nodes horizontally and vertically in a
  # map, connects all the nodes together.
  #=============================================================================
  class Maze
    attr_accessor :node_count_x, :node_count_y

    DIRECTIONS = [EdgeMasks::NORTH, EdgeMasks::SOUTH, EdgeMasks::EAST, EdgeMasks::WEST]

    def initialize(cw, ch, parameters)
      raise ArgumentError.new if cw == 0 || ch == 0
      @node_count_x = cw
      @node_count_y = ch
      @parameters = parameters
      @nodes = Array.new(@node_count_x * @node_count_y) { MazeNode.new }
    end

    def valid_node?(x, y)
      return x >= 0 && x < @node_count_x && y >= 0 && y < @node_count_y
    end

    def get_node(x, y)
      return @nodes[(y * @node_count_x) + x] if valid_node?(x, y)
      return nil
    end

    def node_visited?(x, y)
      return true if !valid_node?(x, y) || !@nodes[(y * @node_count_x) + x].visitable?
      return @nodes[(y * @node_count_x) + x].visited?
    end

    def set_node_visited(x, y)
      @nodes[(y * @node_count_x) + x].set_visited if valid_node?(x, y)
    end

    def node_edge_blocked?(x, y, edge)
      return false if !valid_node?(x, y)
      return @nodes[(y * @node_count_x) + x].edge_blocked?(edge)
    end

    def connect_node_edges(x, y, edge)
      return if !valid_node?(x, y)
      @nodes[(y * @node_count_x) + x].connect_edge(edge)
      new_x, new_y, new_edge = get_coords_in_direction(x, y, edge, true)
      raise ArgumentError.new if new_edge == 0
      @nodes[(new_y * @node_count_x) + new_x].connect_edge(new_edge) if valid_node?(new_x, new_y)
    end

    def room_count
      ret = 0
      @nodes.each { |node| ret += 1 if node.room? }
      return ret
    end

    def get_coords_in_direction(x, y, dir, include_direction = false)
      new_x = x
      new_y = y
      new_dir = 0
      case dir
      when EdgeMasks::NORTH
        new_dir = EdgeMasks::SOUTH
        new_y -= 1
      when EdgeMasks::SOUTH
        new_dir = EdgeMasks::NORTH
        new_y += 1
      when EdgeMasks::WEST
        new_dir = EdgeMasks::EAST
        new_x -= 1
      when EdgeMasks::EAST
        new_dir = EdgeMasks::WEST
        new_x += 1
      end
      return new_x, new_y, new_dir if include_direction
      return new_x, new_y
    end

    #---------------------------------------------------------------------------

    def generate_layout
      # Set visitable nodes
      visitable_nodes = set_visitable_nodes
      # Generate connections between all nodes
      generate_depth_first_maze(visitable_nodes)
      add_more_connections
      # Spawn rooms in some nodes
      spawn_rooms(visitable_nodes)
    end

    # Returns whether the node at (x, y) is active in the given layout.
    def check_active_node(x, y, layout)
      case layout
      when :no_corners
        return false if [0, @node_count_x - 1].include?(x) && [0, @node_count_y - 1].include?(y)
      when :ring
        return false if x > 0 && x < @node_count_x - 1 && y > 0 && y < @node_count_y - 1
      when :antiring
        return false if x == 0 || x == @node_count_x - 1 || y == 0 || y == @node_count_y - 1
      when :plus
        return false if x != @node_count_x / 2 && y != @node_count_y / 2
      when :diagonal_up
        return false if (x + y - @node_count_y + 1).abs >= 2
      when :diagonal_down
        return false if (x - y).abs >= 2
      when :cross
        return false if (x - y).abs >= 2 && (x + y - @node_count_y + 1).abs >= 2
      when :quadrants
        return false if (x == 0 || x == @node_count_x - 1) && y >= 2 && y < @node_count_y - 2
        return false if (y == 0 || y == @node_count_y - 1) && x >= 2 && x < @node_count_x - 2
      end
      return true
    end

    def set_visitable_nodes
      visitable_nodes = []
      @node_count_y.times do |y|
        @node_count_x.times do |x|
          next if !check_active_node(x, y, @parameters.node_layout)
          @nodes[(y * @node_count_x) + x].set_visitable
          visitable_nodes.push([x, y])
        end
      end
      return visitable_nodes
    end

    def generate_depth_first_maze(visitable_nodes)
      # Pick a cell to start in
      start = visitable_nodes.sample
      sx = start[0]
      sy = start[1]
      # Generate a maze
      connect_nodes_and_recurse_depth_first(sx, sy, 0)
    end

    def connect_nodes_and_recurse_depth_first(x, y, depth)
      set_node_visited(x, y)
      dirs = DIRECTIONS.shuffle
      4.times do |c|
        dir = dirs[c]
        cx, cy = get_coords_in_direction(x, y, dir)
        next if node_visited?(cx, cy)
        connect_node_edges(x, y, dir)
        connect_nodes_and_recurse_depth_first(cx, cy, depth + 1)
      end
    end

    def add_more_connections
      return if @parameters.extra_connections_count == 0
      possible_conns = []
      @node_count_x.times do |x|
        @node_count_y.times do |y|
          node = @nodes[(y * @node_count_x) + x]
          next if !node.visitable?
          DIRECTIONS.each do |dir|
            next if !node.edge_blocked?(dir)
            cx, cy, cdir = get_coords_in_direction(x, y, dir, true)
            new_node = get_node(cx, cy)
            next if !new_node || !new_node.visitable? || !new_node.edge_blocked?(cdir)
            possible_conns.push([x, y, dir])
          end
        end
      end
      possible_conns.sample(@parameters.extra_connections_count).each do |conn|
        connect_node_edges(*conn)
      end
    end

    def spawn_rooms(visitable_nodes)
      roomable_nodes = []
      visitable_nodes.each { |coord| roomable_nodes.push(coord) if check_active_node(*coord, @parameters.room_layout) }
      room_count = [roomable_nodes.length * @parameters.room_chance / 100, 1].max
      return if room_count == 0
      rooms = roomable_nodes.sample(room_count)
      rooms.each { |coords| @nodes[(coords[1] * @node_count_x) + coords[0]].set_room }
    end
  end

  #=============================================================================
  # Arrays of tile types in the dungeon map.
  #=============================================================================
  class DungeonLayout
    attr_accessor :width, :height
    alias xsize width
    alias ysize height

    # Used for debugging when printing out an ASCII image of the dungeon
    TEXT_SYMBOLS = {
      :void                   => "#",
      :room                   => " ",
      :corridor               => " ",
      :void_decoration        => "#",
      :void_decoration_large  => "#",
      :floor_decoration       => " ",
      :floor_decoration_large => " ",
      :floor_patch            => " ",
      :wall_top               => " ",
      :wall_1                 => Console.markup_style("=", bg: :brown),
      :wall_2                 => Console.markup_style("=", bg: :brown),
      :wall_3                 => Console.markup_style("=", bg: :brown),
      :wall_4                 => Console.markup_style("=", bg: :brown),
      :wall_6                 => Console.markup_style("=", bg: :brown),
      :wall_7                 => Console.markup_style("=", bg: :brown),
      :wall_8                 => Console.markup_style("=", bg: :brown),
      :wall_9                 => Console.markup_style("=", bg: :brown),
      :wall_in_1              => Console.markup_style("=", bg: :brown),
      :wall_in_3              => Console.markup_style("=", bg: :brown),
      :wall_in_7              => Console.markup_style("=", bg: :brown),
      :wall_in_9              => Console.markup_style("=", bg: :brown),
      :upper_wall_1           => Console.markup_style("~", bg: :gray),
      :upper_wall_2           => Console.markup_style("~", bg: :gray),
      :upper_wall_3           => Console.markup_style("~", bg: :gray),
      :upper_wall_4           => Console.markup_style("~", bg: :gray),
      :upper_wall_6           => Console.markup_style("~", bg: :gray),
      :upper_wall_7           => Console.markup_style("~", bg: :gray),
      :upper_wall_8           => Console.markup_style("~", bg: :gray),
      :upper_wall_9           => Console.markup_style("~", bg: :gray),
      :upper_wall_in_1        => Console.markup_style("~", bg: :gray),
      :upper_wall_in_3        => Console.markup_style("~", bg: :gray),
      :upper_wall_in_7        => Console.markup_style("~", bg: :gray),
      :upper_wall_in_9        => Console.markup_style("~", bg: :gray)
    }
    FLOOR_LAYER      = 0
    FLOOR_DECO_LAYER = 1
    WALL_LAYER       = 2

    def initialize(width, height)
      @width  = width
      @height = height
      @array  = [[], [], []]
      clear
    end

    def [](x, y, layer)
      return @array[layer][(y * @width) + x]
    end

    def []=(x, y, layer, value)
      @array[layer][(y * @width) + x] = value
    end

    def value(x, y)
      return :void if x < 0 || x >= @width || y < 0 || y >= @height
      [2, 1, 0].each do |layer|
        return @array[layer][(y * @width) + x] if @array[layer][(y * @width) + x] != :none
      end
      return :void
    end

    def clear
      @array.each_with_index do |arr, layer|
        (@width * @height).times { |i| arr[i] = (layer == 0) ? :void : :none }
      end
    end

    def set_wall(x, y, value)
      @array[FLOOR_LAYER][(y * @width) + x] = :room
      @array[WALL_LAYER][(y * @width) + x] = value
    end

    def set_ground(x, y, value)
      @array[FLOOR_LAYER][(y * @width) + x] = value
      @array[WALL_LAYER][(y * @width) + x] = :none
    end

    def write
      ret = ""
      @height.times do |y|
        @width.times do |x|
          ret += TEXT_SYMBOLS[value(x, y)] || "\e[30m\e[41m?\e[0m"
        end
        ret += "\n"
      end
      return ret
    end
  end

  #=============================================================================
  # The main dungeon generator class.
  #=============================================================================
  class Dungeon
    attr_accessor :width, :height
    alias xsize width
    alias ysize height
    attr_accessor :parameters, :rng_seed
    attr_accessor :tileset

    # 0 is none (index 0 only) or corridor/floor
    # -1 are tile combinations that need special attention
    # Other numbers correspond to tile types (see def get_wall_tile_for_coord)
    FLOOR_NEIGHBOURS_TO_WALL = [
      0, 2, 1, 2, 4, 11, 4, 11, 7, 9, 4, 11, 4, 11, 4, 11,
      8, 0, 17, 0, 17, 0, 17, 0, 8, 0, 17, 0, 17, 0, 17, 0,
      9, 13, -1, 13, 17, 0, 17, 0, 8, 0, 17, 0, 17, 0, 17, 0,
      8, 0, 17, 0, 17, 0, 17, 0, 8, 0, 17, 0, 17, 0, 17, 0,
      6, 13, 13, 13, 0, 0, 0, 0, 19, 0, 0, 0, 0, 0, 0, 0,
      19, 0, 0, 0, 0, 0, 0, 0, 19, 0, 0, 0, 0, 0, 0, 0,
      6, 13, 13, 13, 0, 0, 0, 0, 19, 0, 0, 0, 0, 0, 0, 0,
      19, 0, 0, 0, 0, 0, 0, 0, 19, 0, 0, 0, 0, 0, 0, 0,
      3, 2, 2, 2, 11, 11, 11, 11, -1, 11, 11, 11, 11, 11, 11, 11,
      19, 0, 0, 0, 0, 0, 0, 0, 19, 0, 0, 0, 0, 0, 0, 0,
      6, 13, 13, 13, 0, 0, 0, 0, 19, 0, 0, 0, 0, 0, 0, 0,
      19, 0, 0, 0, 0, 0, 0, 0, 19, 0, 0, 0, 0, 0, 0, 0,
      6, 13, 13, 13, 0, 0, 0, 0, 19, 0, 0, 0, 0, 0, 0, 0,
      19, 0, 0, 0, 0, 0, 0, 0, 19, 0, 0, 0, 0, 0, 0, 0,
      6, 13, 13, 13, 0, 0, 0, 0, 19, 0, 0, 0, 0, 0, 0, 0,
      19, 0, 0, 0, 0, 0, 0, 0, 19, 0, 0, 0, 0, 0, 0, 0
    ]
    FLOOR_LAYER      = 0
    FLOOR_DECO_LAYER = 1
    WALL_LAYER       = 2

    def initialize(width, height, tileset, parameters = nil)
      @tileset     = tileset
      @buffer_x    = ((Graphics.width.to_f / Game_Map::TILE_WIDTH) / 2).ceil
      @buffer_y    = ((Graphics.height.to_f / Game_Map::TILE_HEIGHT) / 2).ceil
      if @tileset.snap_to_large_grid
        @buffer_x += 1 if @buffer_x.odd?
        @buffer_y += 1 if @buffer_x.odd?
      end
      @parameters = parameters || GameData::DungeonParameters.new({})
      if @tileset.snap_to_large_grid
        @parameters.cell_width -= 1 if @parameters.cell_width.odd?
        @parameters.cell_height -= 1 if @parameters.cell_height.odd?
        @parameters.corridor_width += (@parameters.corridor_width == 1) ? 1 : -1 if @parameters.corridor_width.odd?
      end
      if width >= 20
        @width = width
      else
        @width = (width * @parameters.cell_width) + (2 * @buffer_x)
        @width += 1 if @tileset.snap_to_large_grid && @width.odd?
      end
      if height >= 20
        @height = height
      else
        @height = (height * @parameters.cell_height) + (2 * @buffer_y)
        @height += 1 if @tileset.snap_to_large_grid && @height.odd?
      end
      @usable_width = @width
      @usable_height = @height
      if @tileset.snap_to_large_grid
        @usable_width  -= 1 if @usable_width.odd?
        @usable_height -= 1 if @usable_height.odd?
      end
      @room_rects = []
      @map_data    = DungeonLayout.new(@width, @height)
      @need_redraw = false
    end

    def [](x, y, layer = nil)
      return @map_data.value(x, y) if layer.nil?
      return @map_data[x, y, layer]
    end

    def []=(x, y, layer, value)
      @map_data[x, y, layer] = value
    end

    def write
      return @map_data.write
    end

    #---------------------------------------------------------------------------

    # Returns whether the given coordinates are a room floor that isn't too
    # close to a corridor. For positioning events/the player upon entering.
    def isRoom?(x, y)
      return false if @map_data.value(x, y) != :room
      (-1..1).each do |i|
        (-1..1).each do |j|
          next if i == 0 && j == 0
          return false if @map_data.value(x + i, y + j) == :corridor
        end
      end
      return true   # No surrounding tiles are corridor floor
    end

    def tile_is_ground?(value)
      return [:room, :corridor].include?(value)
    end

    # Lower wall tiles only.
    def tile_is_wall?(value)
      return [:wall_1, :wall_2, :wall_3, :wall_4, :wall_6, :wall_7, :wall_8, :wall_9,
              :wall_in_1, :wall_in_3, :wall_in_7, :wall_in_9].include?(value)
    end

    def coord_is_ground?(x, y)
      return tile_is_ground?(@map_data[x, y, FLOOR_LAYER]) && !tile_is_wall?(@map_data[x, y, WALL_LAYER])
    end

    #---------------------------------------------------------------------------

    def generate
      @rng_seed = @parameters.rng_seed || $PokemonGlobal.dungeon_rng_seed || Random.new_seed
      $PokemonGlobal.dungeon_rng_seed = nil
      Random.srand(@rng_seed)
      maxWidth = @usable_width - (@buffer_x * 2)
      maxHeight = @usable_height - (@buffer_y * 2)
      return if maxWidth < 0 || maxHeight < 0
      loop do
        @need_redraw = false
        @map_data.clear
        # Generate the basic layout of the map
        generate_layout(maxWidth, maxHeight)
        next if @need_redraw
        # Draw walls
        generate_walls(maxWidth, maxHeight)
        next if @need_redraw
        # Draw decorations
        paint_decorations(maxWidth, maxHeight)
        # Draw wall top tiles
        paint_wall_top_tiles(maxWidth, maxHeight)
        break   # if !@need_redraw
      end
    end

    def generate_layout(maxWidth, maxHeight)
      cellWidth = @parameters.cell_width
      cellHeight = @parameters.cell_height
      # Map is too small, make the whole map a room
      if maxWidth < cellWidth || maxHeight < cellHeight
        paint_ground_rect(@buffer_x, @buffer_y, maxWidth, maxHeight, :room)
        return
      end
      # Generate connections between cells
      maze = Maze.new(maxWidth / cellWidth, maxHeight / cellHeight, @parameters)
      maze.generate_layout
      # If no rooms were generated, make the whole map a room
      if maze.room_count == 0
        paint_ground_rect(@buffer_x, @buffer_y, maxWidth, maxHeight, :room)
        return
      end
      # Draw each cell's contents in turn (room and corridors)
      (maxHeight / cellHeight).times do |y|
        (maxWidth / cellWidth).times do |x|
          paint_node_contents(@buffer_x + (x * cellWidth), @buffer_y + (y * cellHeight), maze.get_node(x, y))
        end
      end
      check_for_isolated_rooms
    end

    def generate_walls(maxWidth, maxHeight)
      # Lower layer
      errors = []
      maxHeight.times do |y|
        maxWidth.times do |x|
          next if !coord_is_ground?(@buffer_x + x, @buffer_y + y)
          paint_walls_around_ground(@buffer_x + x, @buffer_y + y, 0, errors)
        end
      end
      # Check for error tiles
      errors.each do |coord|
        resolve_wall_error(coord[0], coord[1], 0)
        break if @need_redraw
      end
      return if @need_redraw
      return if !@tileset.double_walls
      # Upper layer
      errors = []
      (maxHeight + 2).times do |y|
        (maxWidth + 2).times do |x|
          next if !tile_is_wall?(@map_data[@buffer_x + x - 1, @buffer_y + y - 1, WALL_LAYER])
          paint_walls_around_ground(@buffer_x + x - 1, @buffer_y + y - 1, 1, errors)
        end
      end
      # Check for error tiles
      errors.each do |coord|
        resolve_wall_error(coord[0], coord[1], 1)
        break if @need_redraw
      end
    end

    #---------------------------------------------------------------------------

    # Determines whether all floor tiles are contiguous. Sets @need_redraw if
    # there are 2+ floor regions that are isolated from each other.
    def check_for_isolated_rooms
      # Get a floor tile as a starting position
      start = nil
      maxWidth = @usable_width - (@buffer_x * 2)
      maxHeight = @usable_height - (@buffer_y * 2)
      maxHeight.times do |y|
        maxWidth.times do |x|
          next if !tile_is_ground?(@map_data[x + @buffer_x, y + @buffer_y, FLOOR_LAYER])
          start = [x, y]
          break
        end
        break if start
      end
      if !start
        @need_redraw = true
        return
      end
      # Flood fill (https://en.wikipedia.org/wiki/Flood_fill#Span_Filling)
      to_check = [
        [start[0], start[0], start[1], 1],
        [start[0], start[0], start[1] - 1, -1]
      ]
      visited = []
      loop do
        break if to_check.empty?
        checking = to_check.shift
        x1, x2, y, dy = checking
        x = x1
        if !visited[(y * maxWidth) + x] && tile_is_ground?(@map_data[x + @buffer_x, y + @buffer_y, FLOOR_LAYER])
          loop do
            break if visited[(y * maxWidth) + x - 1] || !tile_is_ground?(@map_data[x - 1 + @buffer_x, y + @buffer_y, FLOOR_LAYER])
            visited[(y * maxWidth) + x - 1] = true
            x -= 1
          end
        end
        to_check.push([x, x1 - 1, y - dy, -dy]) if x < x1
        loop do
          break if x1 > x2
          loop do
            break if visited[(y * maxWidth) + x1] || !tile_is_ground?(@map_data[x1 + @buffer_x, y + @buffer_y, FLOOR_LAYER])
            visited[(y * maxWidth) + x1] = true
            to_check.push([x, x1, y + dy, dy])
            to_check.push([x2 + 1, x1, y - dy, -dy]) if x1 > x2
            x1 += 1
          end
          x1 += 1
          loop do
            break if x1 >= x2
            break if !visited[(y * maxWidth) + x1] && tile_is_ground?(@map_data[x1 + @buffer_x, y + @buffer_y, FLOOR_LAYER])
            x1 += 1
          end
          x = x1
        end
      end
      # Check for unflooded floor tiles
      maxHeight.times do |y|
        maxWidth.times do |x|
          next if visited[(y * maxWidth) + x] || !tile_is_ground?(@map_data[x + @buffer_x, y + @buffer_y, FLOOR_LAYER])
          @need_redraw = true
          break
        end
        break if @need_redraw
      end
    end

    # Fixes (most) situations where it isn't immediately obvious how to draw a
    # wall around a floor area.
    def resolve_wall_error(x, y, layer = 0)
      if layer == 0
        is_neighbour = lambda { |til| return tile_is_ground?(til) }
      else
        is_neighbour = lambda { |til| return tile_is_wall?(til) }
      end
      tile = {
        :wall_1    => (layer == 0) ? :wall_1 : :upper_wall_1,
        :wall_2    => (layer == 0) ? :wall_2 : :upper_wall_2,
        :wall_3    => (layer == 0) ? :wall_3 : :upper_wall_3,
        :wall_4    => (layer == 0) ? :wall_4 : :upper_wall_4,
        :wall_6    => (layer == 0) ? :wall_6 : :upper_wall_6,
        :wall_7    => (layer == 0) ? :wall_7 : :upper_wall_7,
        :wall_8    => (layer == 0) ? :wall_8 : :upper_wall_8,
        :wall_9    => (layer == 0) ? :wall_9 : :upper_wall_9,
        :wall_in_1 => (layer == 0) ? :wall_in_1 : :upper_wall_in_1,
        :wall_in_3 => (layer == 0) ? :wall_in_3 : :upper_wall_in_3,
        :wall_in_7 => (layer == 0) ? :wall_in_7 : :upper_wall_in_7,
        :wall_in_9 => (layer == 0) ? :wall_in_9 : :upper_wall_in_9,
        :corridor  => (layer == 0) ? :corridor : :void
      }
      neighbours = 0
      neighbours |= 0x01 if is_neighbour.call(@map_data.value(x,     y - 1))   # N
      neighbours |= 0x02 if is_neighbour.call(@map_data.value(x + 1, y - 1))   # NE
      neighbours |= 0x04 if is_neighbour.call(@map_data.value(x + 1,     y))   # E
      neighbours |= 0x08 if is_neighbour.call(@map_data.value(x + 1, y + 1))   # SE
      neighbours |= 0x10 if is_neighbour.call(@map_data.value(x,     y + 1))   # S
      neighbours |= 0x20 if is_neighbour.call(@map_data.value(x - 1, y + 1))   # SW
      neighbours |= 0x40 if is_neighbour.call(@map_data.value(x - 1,     y))   # W
      neighbours |= 0x80 if is_neighbour.call(@map_data.value(x - 1, y - 1))   # NW
      case neighbours
      when 34
        # --f   floor tile (dashes are walls)
        # -o-   this tile
        # f--   floor tile
        if @map_data.value(x - 1, y - 1) == :void
          @map_data[x, y, WALL_LAYER] = tile[:wall_in_3]
          @map_data[x - 1, y, WALL_LAYER] = tile[:wall_in_7]
          @map_data[x, y - 1, WALL_LAYER] = tile[:wall_in_7]
          @map_data.set_wall(x - 1, y - 1, tile[:wall_7])
        elsif @map_data.value(x + 1, y + 1) == :void
          @map_data[x, y, WALL_LAYER] = tile[:wall_in_7]
          @map_data[x + 1, y, WALL_LAYER] = tile[:wall_in_3]
          @map_data[x, y + 1, WALL_LAYER] = tile[:wall_in_3]
          @map_data.set_wall(x + 1, y + 1, tile[:wall_3])
        elsif @map_data[x, y - 1, WALL_LAYER] == tile[:wall_4] && @map_data[x - 1, y, WALL_LAYER] == tile[:wall_in_9]
          @map_data[x, y, WALL_LAYER] = tile[:wall_in_3]
          @map_data[x, y - 1, WALL_LAYER] = tile[:wall_in_7]
          @map_data.set_ground(x - 1, y, tile[:corridor])
          @map_data[x - 1, y - 1, WALL_LAYER] = (@map_data[x - 1, y - 1, WALL_LAYER] == tile[:wall_6]) ? tile[:wall_in_9] : tile[:wall_8]
        elsif @map_data[x, y - 1, WALL_LAYER] == tile[:wall_in_1] && @map_data[x - 1, y, WALL_LAYER] == tile[:wall_8]
          @map_data[x, y, WALL_LAYER] = tile[:wall_in_3]
          @map_data.set_ground(x, y - 1, tile[:corridor])
          @map_data[x - 1, y, WALL_LAYER] = tile[:wall_in_7]
          @map_data[x - 1, y - 1, WALL_LAYER] = (@map_data[x - 1, y - 1, WALL_LAYER] == tile[:wall_2]) ? tile[:wall_in_1] : tile[:wall_4]
        elsif @map_data[x, y - 1, WALL_LAYER] == tile[:wall_in_1] && @map_data[x - 1, y, WALL_LAYER] == tile[:wall_in_9]
          @map_data[x, y, WALL_LAYER] = tile[:wall_in_3]
          @map_data.set_ground(x, y - 1, tile[:corridor])
          @map_data.set_ground(x - 1, y, tile[:corridor])
          if @map_data[x - 1, y - 1, WALL_LAYER] == :error
            @map_data[x - 1, y - 1, WALL_LAYER] = tile[:wall_in_7]
          else
            @map_data.set_ground(x - 1, y - 1, tile[:corridor])
          end
        elsif @map_data[x, y + 1, WALL_LAYER] == tile[:wall_6] && @map_data[x + 1, y, WALL_LAYER] == tile[:wall_in_1]
          @map_data[x, y, WALL_LAYER] = tile[:wall_in_7]
          @map_data[x, y + 1, WALL_LAYER] = tile[:wall_in_3]
          @map_data.set_ground(x + 1, y, tile[:corridor])
          @map_data[x + 1, y + 1, WALL_LAYER] = (@map_data[x + 1, y + 1, WALL_LAYER] == tile[:wall_4]) ? tile[:wall_in_1] : tile[:wall_2]
        elsif @map_data[x, y + 1, WALL_LAYER] == tile[:wall_in_9] && @map_data[x + 1, y, WALL_LAYER] == tile[:wall_2]
          @map_data[x, y, WALL_LAYER] = tile[:wall_in_7]
          @map_data.set_ground(x, y + 1, tile[:corridor])
          @map_data[x + 1, y, WALL_LAYER] = tile[:wall_in_3]
          @map_data[x + 1, y + 1, WALL_LAYER] = (@map_data[x + 1, y + 1, WALL_LAYER] == tile[:wall_8]) ? tile[:wall_in_9] : tile[:wall_6]
        elsif @map_data[x, y + 1, WALL_LAYER] == tile[:wall_in_9] && @map_data[x + 1, y, WALL_LAYER] == tile[:wall_in_1]
          @map_data[x, y, WALL_LAYER] = tile[:wall_in_7]
          @map_data.set_ground(x, y + 1, tile[:corridor])
          @map_data.set_ground(x + 1, y, tile[:corridor])
          if @map_data[x + 1, y + 1, WALL_LAYER] == :error
            @map_data[x + 1, y + 1, WALL_LAYER] = tile[:wall_in_3]
          else
            @map_data.set_ground(x + 1, y + 1, tile[:corridor])
          end
        else
          # Tile error can't be resolved; will redraw map
          @need_redraw = true
        end
      when 136
        # f--   floor tile (dashes are walls)
        # -o-   this tile
        # --f   floor tile
        if @map_data.value(x - 1, y + 1) == :void
          @map_data[x, y, WALL_LAYER] = tile[:wall_in_9]
          @map_data[x - 1, y, WALL_LAYER] = tile[:wall_in_1]
          @map_data[x, y + 1, WALL_LAYER] = tile[:wall_in_1]
          @map_data.set_wall(x - 1, y + 1, tile[:wall_1])
        elsif @map_data.value(x + 1, y - 1) == :void
          @map_data[x, y, WALL_LAYER] = tile[:wall_in_1]
          @map_data[x + 1, y, WALL_LAYER] = tile[:wall_in_9]
          @map_data[x, y - 1, WALL_LAYER] = tile[:wall_in_9]
          @map_data.set_wall(x + 1, y - 1, tile[:wall_9])
        elsif @map_data[x, y - 1, WALL_LAYER] == tile[:wall_6] && @map_data[x + 1, y, WALL_LAYER] == tile[:wall_in_7]
          @map_data[x, y, WALL_LAYER] = tile[:wall_in_1]
          @map_data[x, y - 1, WALL_LAYER] = tile[:wall_in_9]
          @map_data.set_ground(x + 1, y, tile[:corridor])
          @map_data[x + 1, y - 1, WALL_LAYER] = (@map_data[x + 1, y - 1, WALL_LAYER] == tile[:wall_4]) ? tile[:wall_in_7] : tile[:wall_8]
        elsif @map_data[x, y - 1, WALL_LAYER] == tile[:wall_in_3] && @map_data[x + 1, y, WALL_LAYER] == tile[:wall_8]
          @map_data[x, y, WALL_LAYER] = tile[:wall_in_1]
          @map_data.set_ground(x, y - 1, tile[:corridor])
          @map_data[x + 1, y, WALL_LAYER] = tile[:wall_in_9]
          @map_data[x + 1, y - 1, WALL_LAYER] = (@map_data[x + 1, y - 1, WALL_LAYER] == tile[:wall_2]) ? tile[:wall_in_3] : tile[:wall_6]
        elsif @map_data[x, y - 1, WALL_LAYER] == tile[:wall_in_3] && @map_data[x + 1, y, WALL_LAYER] == tile[:wall_in_7]
          @map_data[x, y, WALL_LAYER] = tile[:wall_in_1]
          @map_data.set_ground(x, y - 1, tile[:corridor])
          @map_data.set_ground(x + 1, y, tile[:corridor])
          if @map_data[x + 1, y - 1, WALL_LAYER] == :error
            @map_data[x + 1, y - 1, WALL_LAYER] = tile[:wall_in_9]
          else
            @map_data.set_ground(x + 1, y - 1, tile[:corridor])
          end
        elsif @map_data[x, y + 1, WALL_LAYER] == tile[:wall_4] && @map_data[x - 1, y, WALL_LAYER] == tile[:wall_in_3]
          @map_data[x, y, WALL_LAYER] = tile[:wall_in_9]
          @map_data[x, y + 1, WALL_LAYER] = tile[:wall_in_1]
          @map_data.set_ground(x - 1, y, tile[:corridor])
          @map_data[x - 1, y + 1, WALL_LAYER] = (@map_data[x - 1, y + 1, WALL_LAYER] == tile[:wall_6]) ? tile[:wall_in_3] : tile[:wall_2]
        elsif @map_data[x, y + 1, WALL_LAYER] == tile[:wall_in_7] && @map_data[x - 1, y, WALL_LAYER] == tile[:wall_2]
          @map_data[x, y, WALL_LAYER] = tile[:wall_in_9]
          @map_data.set_ground(x, y + 1, tile[:corridor])
          @map_data[x - 1, y, WALL_LAYER] = tile[:wall_in_1]
          @map_data[x - 1, y + 1, WALL_LAYER] = (@map_data[x - 1, y + 1, WALL_LAYER] == tile[:wall_8]) ? tile[:wall_in_7] : tile[:wall_4]
        elsif @map_data[x, y + 1, WALL_LAYER] == tile[:wall_in_7] && @map_data[x - 1, y, WALL_LAYER] == tile[:wall_in_3]
          @map_data[x, y, WALL_LAYER] = tile[:wall_in_9]
          @map_data.set_ground(x, y + 1, tile[:corridor])
          @map_data.set_ground(x - 1, y, tile[:corridor])
          if @map_data[x - 1, y + 1, WALL_LAYER] == :error
            @map_data[x - 1, y + 1, WALL_LAYER] = tile[:wall_in_1]
          else
            @map_data.set_ground(x - 1, y + 1, tile[:corridor])
          end
        else
          # Tile error can't be resolved; will redraw map
          @need_redraw = true
        end
      else
        @need_redraw = true
        raise "can't resolve error"
      end
    end

    #---------------------------------------------------------------------------

    # Draws a cell's contents, which is an underlying pattern based on
    # tile_layout (the corridors), and possibly a room on top of that.
    def paint_node_contents(cell_x, cell_y, node)
      # Draw corridors connecting this room
      paint_connections(cell_x, cell_y, node.edge_pattern)
      # Generate a randomly placed room
      paint_room(cell_x, cell_y) if node.room?
    end

    def paint_ground_rect(x, y, width, height, tile)
      height.times do |j|
        width.times do |i|
          @map_data[x + i, y + j, FLOOR_LAYER] = tile
        end
      end
    end

    # Draws corridors leading from the node at (cell_x, cell_y).
    def paint_connections(cell_x, cell_y, pattern)
      x_offset = (@parameters.cell_width - @parameters.corridor_width) / 2
      y_offset = (@parameters.cell_height - @parameters.corridor_width) / 2
      if @parameters.random_corridor_shift
        variance = @parameters.corridor_width
        variance /= 2 if @tileset.snap_to_large_grid
        if variance > 1
          x_shift = rand(variance) - (variance / 2)
          y_shift = rand(variance) - (variance / 2)
          if @tileset.snap_to_large_grid
            x_shift *= 2
            y_shift *= 2
          end
          x_offset += x_shift
          y_offset += y_shift
        end
      end
      if @tileset.snap_to_large_grid
        x_offset += 1 if x_offset.odd?
        y_offset += 1 if y_offset.odd?
      end
      if (pattern & RandomDungeon::EdgeMasks::NORTH) == 0
        paint_ground_rect(cell_x + x_offset, cell_y,
                          @parameters.corridor_width, y_offset + @parameters.corridor_width,
                          :corridor)
      end
      if (pattern & RandomDungeon::EdgeMasks::SOUTH) == 0
        paint_ground_rect(cell_x + x_offset, cell_y + y_offset,
                          @parameters.corridor_width, @parameters.cell_height - y_offset,
                          :corridor)
      end
      if (pattern & RandomDungeon::EdgeMasks::EAST) == 0
        paint_ground_rect(cell_x + x_offset, cell_y + y_offset,
                          @parameters.cell_width - x_offset, @parameters.corridor_width,
                          :corridor)
      end
      if (pattern & RandomDungeon::EdgeMasks::WEST) == 0
        paint_ground_rect(cell_x, cell_y + y_offset,
                          x_offset + @parameters.corridor_width, @parameters.corridor_width,
                          :corridor)
      end
    end

    # Draws a room at (cell_x, cell_y).
    def paint_room(cell_x, cell_y)
      width, height = @parameters.rand_room_size
      return if width <= 0 || height <= 0
      if @tileset.snap_to_large_grid
        width += (width <= @parameters.cell_width / 2) ? 1 : -1 if width.odd?
        height += (height <= @parameters.cell_height / 2) ? 1 : -1 if height.odd?
      end
      center_x, center_y = @parameters.rand_cell_center
      x = cell_x + center_x - (width / 2)
      y = cell_y + center_y - (height / 2)
      if @tileset.snap_to_large_grid
        x += 1 if x.odd?
        y += 1 if y.odd?
      end
      x = x.clamp(@buffer_x, @usable_width - @buffer_x - width)
      y = y.clamp(@buffer_y, @usable_height - @buffer_y - height)
      @room_rects.push([x, y, width, height])
      paint_ground_rect(x, y, width, height, :room)
    end

    # layer here is the cliff level above the ground, not a map data layer.
    def paint_walls_around_ground(x, y, layer, errors)
      (-1..1).each do |j|
        (-1..1).each do |i|
          next if i == 0 && j == 0
          next if @map_data[x + i, y + j, FLOOR_LAYER] != :void
          tile = get_wall_tile_for_coord(x + i, y + j, layer)
          if [:void, :corridor].include?(tile)
            @map_data[x + i, y + j, FLOOR_LAYER] = tile
          else
            @map_data.set_wall(x + i, y + j, tile)
          end
          errors.push([x + i, y + j]) if tile == :error
        end
      end
    end

    def get_wall_tile_for_coord(x, y, layer = 0)
      if layer == 0
        is_neighbour = lambda { |x2, y2| return tile_is_ground?(@map_data.value(x2, y2)) }
      else
        is_neighbour = lambda { |x2, y2| return tile_is_wall?(@map_data[x2, y2, WALL_LAYER]) }
      end
      neighbours = 0
      neighbours |= 0x01 if is_neighbour.call(x,     y - 1)   # N
      neighbours |= 0x02 if is_neighbour.call(x + 1, y - 1)   # NE
      neighbours |= 0x04 if is_neighbour.call(x + 1,     y)   # E
      neighbours |= 0x08 if is_neighbour.call(x + 1, y + 1)   # SE
      neighbours |= 0x10 if is_neighbour.call(x,     y + 1)   # S
      neighbours |= 0x20 if is_neighbour.call(x - 1, y + 1)   # SW
      neighbours |= 0x40 if is_neighbour.call(x - 1,     y)   # W
      neighbours |= 0x80 if is_neighbour.call(x - 1, y - 1)   # NW
      case FLOOR_NEIGHBOURS_TO_WALL[neighbours]
      when -1 then return :error   # Needs special attention
      when 1  then return (layer == 0) ? :wall_1 : :upper_wall_1
      when 2  then return (layer == 0) ? :wall_2 : :upper_wall_2
      when 3  then return (layer == 0) ? :wall_3 : :upper_wall_3
      when 4  then return (layer == 0) ? :wall_4 : :upper_wall_4
      when 6  then return (layer == 0) ? :wall_6 : :upper_wall_6
      when 7  then return (layer == 0) ? :wall_7 : :upper_wall_7
      when 8  then return (layer == 0) ? :wall_8 : :upper_wall_8
      when 9  then return (layer == 0) ? :wall_9 : :upper_wall_9
      when 11 then return (layer == 0) ? :wall_in_1 : :upper_wall_in_1
      when 13 then return (layer == 0) ? :wall_in_3 : :upper_wall_in_3
      when 17 then return (layer == 0) ? :wall_in_7 : :upper_wall_in_7
      when 19 then return (layer == 0) ? :wall_in_9 : :upper_wall_in_9
      end
      return :void if neighbours == 0 || layer == 1
      return :corridor
    end

    def paint_decorations(maxWidth, maxHeight)
      # Large patches (grass/sandy area)
      if @tileset.has_decoration?(:floor_patch)
        (maxHeight / @parameters.cell_height).times do |j|
          (maxWidth / @parameters.cell_width).times do |i|
            next if rand(100) >= @parameters.floor_patch_chance
            tiles_count = @tileset.tiles_of_type_count(:floor_patch)
            this_tile = (tiles_count > 1) ? rand(tiles_count) : 0
            # Random placing of floor patch tiles
            mid_x = (i * @parameters.cell_width) + rand(@parameters.cell_width)
            mid_y = (j * @parameters.cell_height) + rand(@parameters.cell_height)
            ((mid_y - @parameters.floor_patch_radius)..(mid_y + @parameters.floor_patch_radius)).each do |y|
              ((mid_x - @parameters.floor_patch_radius)..(mid_x + @parameters.floor_patch_radius)).each do |x|
                if @tileset.floor_patch_under_walls
                  next if !tile_is_ground?(@map_data[x + @buffer_x, y + @buffer_y, FLOOR_LAYER])
                else
                  next if !tile_is_ground?(@map_data.value(x + @buffer_x, y + @buffer_y))
                end
                if (((mid_x - 1)..(mid_x + 1)).include?(x) && ((mid_y - 1)..(mid_y + 1)).include?(y)) ||
                   rand(100) < @parameters.floor_patch_chance
                  @map_data[x + @buffer_x, y + @buffer_y, FLOOR_DECO_LAYER] = [:floor_patch, this_tile]
                end
              end
            end
            # Smoothing of placed floor patch tiles
            ((mid_y - @parameters.floor_patch_radius)..(mid_y + @parameters.floor_patch_radius)).each do |y|
              ((mid_x - @parameters.floor_patch_radius)..(mid_x + @parameters.floor_patch_radius)).each do |x|
                if @map_data[x + @buffer_x, y + @buffer_y, FLOOR_DECO_LAYER] == [:floor_patch, this_tile]
                  adj_count = 0
                  adj_count += 1 if @map_data[x + @buffer_x - 1, y + @buffer_y, FLOOR_DECO_LAYER] == [:floor_patch, this_tile]
                  adj_count += 1 if @map_data[x + @buffer_x, y + @buffer_y - 1, FLOOR_DECO_LAYER] == [:floor_patch, this_tile]
                  adj_count += 1 if @map_data[x + @buffer_x + 1, y + @buffer_y, FLOOR_DECO_LAYER] == [:floor_patch, this_tile]
                  adj_count += 1 if @map_data[x + @buffer_x, y + @buffer_y + 1, FLOOR_DECO_LAYER] == [:floor_patch, this_tile]
                  if adj_count == 0 || (adj_count == 1 && rand(100) < @parameters.floor_patch_smooth_rate * 2)
                    @map_data[x + @buffer_x, y + @buffer_y, FLOOR_DECO_LAYER] = :none
                  end
                else
                  if @tileset.floor_patch_under_walls
                    next if !tile_is_ground?(@map_data[x + @buffer_x, y + @buffer_y, FLOOR_LAYER])
                  else
                    next if !tile_is_ground?(@map_data.value(x + @buffer_x, y + @buffer_y))
                  end
                  adj_count = 0
                  adj_count += 1 if @map_data[x + @buffer_x - 1, y + @buffer_y, FLOOR_DECO_LAYER] == [:floor_patch, this_tile]
                  adj_count += 1 if @map_data[x + @buffer_x, y + @buffer_y - 1, FLOOR_DECO_LAYER] == [:floor_patch, this_tile]
                  adj_count += 1 if @map_data[x + @buffer_x + 1, y + @buffer_y, FLOOR_DECO_LAYER] == [:floor_patch, this_tile]
                  adj_count += 1 if @map_data[x + @buffer_x, y + @buffer_y + 1, FLOOR_DECO_LAYER] == [:floor_patch, this_tile]
                  if adj_count >= 2 && rand(100) < adj_count * @parameters.floor_patch_smooth_rate
                    @map_data[x + @buffer_x, y + @buffer_y, FLOOR_DECO_LAYER] = [:floor_patch, this_tile]
                  end
                end
              end
            end
          end
        end
      end
      # 2x2 floor decoration (crater)
      if @tileset.has_decoration?(:floor_decoration_large)
        ((maxWidth * maxHeight) / @parameters.floor_decoration_large_density).times do
          x = rand(maxWidth)
          y = rand(maxHeight)
          next if @map_data.value(x + @buffer_x, y + @buffer_y) != :room ||
                  @map_data.value(x + @buffer_x + 1, y + @buffer_y) != :room ||
                  @map_data.value(x + @buffer_x, y + @buffer_y + 1) != :room ||
                  @map_data.value(x + @buffer_x + 1, y + @buffer_y + 1) != :room
          4.times do |c|
            cx = x + @buffer_x + (c % 2)
            cy = y + @buffer_y + (c / 2)
            @map_data[cx, cy, FLOOR_DECO_LAYER] = (c == 0) ? :floor_decoration_large : :ignore
          end
        end
      end
      # 1x1 floor decoration
      if @tileset.has_decoration?(:floor_decoration)
        ((@usable_width * @usable_height) / @parameters.floor_decoration_density).times do
          x = rand(@usable_width)
          y = rand(@usable_height)
          next if !coord_is_ground?(@buffer_x + x, @buffer_y + y)
          @map_data[x + @buffer_x, y + @buffer_y, FLOOR_DECO_LAYER] = :floor_decoration
        end
      end
      # 2x2 void decoration (crevice)
      if @tileset.has_decoration?(:void_decoration_large)
        ((@width * @height) / @parameters.void_decoration_large_density).times do
          x = rand(@width - 1)
          y = rand(@height - 1)
          next if @map_data.value(x, y) != :void ||
                  @map_data.value(x + 1, y) != :void ||
                  @map_data.value(x, y + 1) != :void ||
                  @map_data.value(x + 1, y + 1) != :void
          4.times do |c|
            cx = x + (c % 2)
            cy = y + (c / 2)
            @map_data[cx, cy, FLOOR_DECO_LAYER] = (c == 0) ? :void_decoration_large : :ignore
          end
        end
      end
      # 1x1 void decoration (rock)
      if @tileset.has_decoration?(:void_decoration)
        ((@width * @height) / @parameters.void_decoration_density).times do
          x = rand(@width)
          y = rand(@height)
          next if @map_data.value(x, y) != :void
          @map_data[x, y, FLOOR_DECO_LAYER] = :void_decoration
        end
      end
    end

    def paint_wall_top_tiles(maxWidth, maxHeight)
      return if !@tileset.has_decoration?(:wall_top)
      maxWidth.times do |x|
        maxHeight.times do |y|
          next if ![:wall_2, :wall_in_1, :wall_in_3].include?(@map_data[x + @buffer_x, y + 1 + @buffer_y, WALL_LAYER])
          @map_data[x + @buffer_x, y + @buffer_y, WALL_LAYER] = :wall_top
        end
      end
    end

    #---------------------------------------------------------------------------

    # Convert dungeon layout into proper map tiles from a tileset, and modifies
    # the given map's data accordingly.
    def generateMapInPlace(map)
      # Change :room/:corridor tiles to :floor/:wall_floor tiles
      map.width.times do |i|
        map.height.times do |j|
          next if ![:room, :corridor].include?(@map_data[i, j, FLOOR_LAYER])
          if tile_is_wall?(@map_data[i, j, WALL_LAYER])
            @map_data[i, j, FLOOR_LAYER] = @tileset.has_decoration?(:wall_floor) ? :wall_floor : :floor
          else
            @map_data[i, j, FLOOR_LAYER] = :floor
          end
        end
      end
      # Draw tiles in map based on tile types
      map.width.times do |i|
        map.height.times do |j|
          3.times do |layer|
            tile_type = @map_data[i, j, layer]
            real_tile_type = (tile_type.is_a?(Array)) ? tile_type[0] : tile_type
            tile_version = (tile_type.is_a?(Array)) ? tile_type[1] : -1
            case real_tile_type
            when :ignore
            when :none
              map.data[i, j, layer] = 0
            when :void_decoration_large, :floor_decoration_large
              tile_id = @tileset.get_random_tile_of_type(real_tile_type, self, i, j, layer, tile_version)
              if tile_id < TilemapRenderer::TILESET_START_ID   # Autotile
                tile_id = TilemapRenderer::TILES_PER_AUTOTILE * (tile_id / TilemapRenderer::TILES_PER_AUTOTILE)
              end
              4.times do |c|
                this_tile = tile_id
                if tile_id < TilemapRenderer::TILESET_START_ID   # Autotile
                  this_tile += [34, 36, 40, 38][c]
                else
                  this_tile += (c % 2) + (8 * (c / 2))
                end
                map.data[i + (c % 2), j + (c / 2), layer] = this_tile
              end
            else
              tile_id = @tileset.get_random_tile_of_type(real_tile_type, self, i, j, layer, tile_version)
              map.data[i, j, layer] = tile_id
            end
          end
        end
      end
    end

    # Returns a random room tile a random room where an event of the given size
    # can be placed. Events cannot be placed adjacent to or overlapping each
    # other, and can't be placed right next to the wall of a room (to prevent
    # them blocking a corridor).
    def get_random_room_tile(map, occupied_tiles, event_width = 1, event_height = 1, passable_only = true)
      valid_rooms = @room_rects.clone
      valid_rooms.delete_if { |rect| rect[2] <= event_width + 1 || rect[3] <= event_height + 1 }
      return nil if valid_rooms.empty?
      1000.times do
        room = valid_rooms.sample
        x = 1 + rand(room[2] - event_width - 1)
        y = 1 + rand(room[3] - event_height - 1)
        valid_placement = true
        # Check that the event will be on a passable tile(s)
        if passable_only
          tileset = $data_tilesets[map.tileset_id]
          event_width.times do |i|
            event_height.times do |j|
              [2, 1, 0].each do |layer|
                tile_id = map.data[room[0] + x + i, room[1] + y + j, layer]
                next if tile_id == 0
                next if GameData::TerrainTag.try_get(tileset.terrain_tags[tile_id]).ignore_passability
                valid_placement = false if tileset.passages[tile_id] & 0x0f != 0
                break if !valid_placement
                break if tileset.priorities[tile_id] == 0
              end
              break if !valid_placement
            end
            break if !valid_placement
          end
        end
        next if !valid_placement
        # Check event's proximity to other placed events
        event_width.times do |i|
          event_height.times do |j|
            if occupied_tiles.any? { |item| (item[0] - (room[0] + x + i)).abs < 2 && (item[1] - (room[1] + y + j)).abs < 2 }
              valid_placement = false
            end
            break if !valid_placement
          end
          break if !valid_placement
        end
        next if !valid_placement
        # Found valid placement; use it
        event_width.times do |i|
          event_height.times do |j|
            occupied_tiles.push([room[0] + x + i, room[1] + y + j])
          end
        end
        return [room[0] + x, room[1] + y + event_height - 1]
      end
      return nil
    end
  end
end

#===============================================================================
# Variables that determine which dungeon parameters to use to generate a random
# dungeon.
#===============================================================================
class PokemonGlobalMetadata
  attr_writer   :dungeon_area, :dungeon_version
  attr_accessor :dungeon_rng_seed

  def dungeon_area
    return @dungeon_area || :none
  end

  def dungeon_version
    return @dungeon_version || 0
  end
end

#===============================================================================
# Code that generates a random dungeon layout, and implements it in a given map.
#===============================================================================
EventHandlers.add(:on_game_map_setup, :random_dungeon,
  proc { |map_id, map, _tileset_data|
    next if !GameData::MapMetadata.try_get(map_id)&.random_dungeon
    # Generate a random dungeon
    tileset_data = GameData::DungeonTileset.try_get(map.tileset_id)
    params = GameData::DungeonParameters.try_get($PokemonGlobal.dungeon_area,
                                                 $PokemonGlobal.dungeon_version)
    dungeon = RandomDungeon::Dungeon.new(params.cell_count_x, params.cell_count_y,
                                         tileset_data, params)
    dungeon.generate
    map.width = dungeon.width
    map.height = dungeon.height
    map.data.resize(map.width, map.height, 3)
    dungeon.generateMapInPlace(map)
    failed = false
    100.times do |i|
      failed = false
      occupied_tiles = []
      # Reposition events
      map.events.each_value do |event|
        event_width = 1
        event_height = 1
        if event.name[/size\((\d+),(\d+)\)/i]
          event_width = $~[1].to_i
          event_height = $~[2].to_i
        end
        tile = dungeon.get_random_room_tile(map, occupied_tiles, event_width, event_height)
        failed = true if !tile
        break if failed
        event.x = tile[0]
        event.y = tile[1]
      end
      next if failed
      # Reposition the player
      tile = dungeon.get_random_room_tile(map, occupied_tiles)
      next if !tile
      $game_temp.player_new_x = tile[0]
      $game_temp.player_new_y = tile[1]
      break
    end
    if failed
      raise _INTL("No se han podido colocar todos los eventos y al jugador en la habitación.")
    end
  }
)

