        pkmn.moves[i] = nil
      end
      pkmn.moves.compact!
      # Ensure pkmn has at least one move in the end
      pbLearnMove(pkmn, :CONFUSION) if pkmn.numMoves == 0
    else   # Ice Rider, Shadow Rider
      new_move = form_moves[form - 1]
      pbLearnMove(pkmn, new_move, true)
    end
  }
})

