class PokemonPokedexMenu_Scene
  SEEN_OBTAINED_TEXT_BASE   = Color.new(248, 248, 248)
  SEEN_OBTAINED_TEXT_SHADOW = Color.new(192, 32, 40)
  TEXT_HEADING_X            = 247 
  TEXT_HEADING_Y            = 136
  TEXT_HEADING_WIDTH        = 250
  TEXT_HEADING_HEIGHT       = 64
  COMMAND_BOX_X             = 40
  COMMAND_BOX_Y             = 192
  COMMAND_BOX_WIDTH         = Graphics.width - 84
  COMMAND_BOX_HEIGHT        = 192

  def pbUpdate
    pbUpdateSpriteHash(@sprites)
  end

  def pbStartScene(commands, commands2)
    @commands = commands
    @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = 99999
    @sprites = {}
    @sprites["background"] = IconSprite.new(0, 0, @viewport)
    @sprites["background"].setBitmap(_INTL("Graphics/UI/Pokedex/bg_menu"))
    text_tag = shadowc3tag(SEEN_OBTAINED_TEXT_BASE, SEEN_OBTAINED_TEXT_SHADOW)
    @sprites["headings"] = Window_AdvancedTextPokemon.newWithSize(
      text_tag + _INTL("VISTOS") + "     " + _INTL("OBTENIDOS") + "</c3>", TEXT_HEADING_X, TEXT_HEADING_Y, TEXT_HEADING_WIDTH, TEXT_HEADING_HEIGHT, @viewport
    )
    @sprites["headings"].windowskin = nil
    @sprites["commands"] = Window_DexesList.new(commands, commands2, COMMAND_BOX_WIDTH)
    @sprites["commands"].x      = COMMAND_BOX_X
    @sprites["commands"].y      = COMMAND_BOX_Y
    @sprites["commands"].height = COMMAND_BOX_HEIGHT
    @sprites["commands"].viewport = @viewport
    pbFadeInAndShow(@sprites) { pbUpdate }
  end

  def pbScene
    ret = -1
    loop do
      Graphics.update
      Input.update
      pbUpdate
      if Input.trigger?(Input::BACK)
        pbPlayCloseMenuSE
        break
      elsif Input.trigger?(Input::USE)
        ret = @sprites["commands"].index
        (ret == @commands.length - 1) ? pbPlayCloseMenuSE : pbSEPlay("GUI pokedex open")
        break
      end
    end
    return ret
  end

  def pbEndScene
    pbFadeOutAndHide(@sprites) { pbUpdate }
    pbDisposeSpriteHash(@sprites)
    @viewport.dispose
  end
end

#===============================================================================
#
#===============================================================================
class PokemonPokedexMenuScreen
  def initialize(scene)
    @scene = scene
  end

  def pbStartScreen
    commands  = []
    commands2 = []
    dexnames = Settings.pokedex_names
    $player.pokedex.accessible_dexes.each do |dex|
      # Handle National Dex (index -1) separately
      if dex == -1
        # National Dex is the last element in the array (not at index -1)
        national_dex_entry = dexnames.last
        if national_dex_entry.is_a?(Array)
          commands.push(national_dex_entry[0])
        else
          commands.push(national_dex_entry)
        end
      else
        if dexnames[dex].nil?
          commands.push(_INTL("Pokédex"))
        elsif dexnames[dex].is_a?(Array)
          commands.push(dexnames[dex][0])
        else
          commands.push(dexnames[dex])
        end
      end
      commands2.push([$player.pokedex.seen_count(dex),
                      $player.pokedex.owned_count(dex),
                      pbGetRegionalDexLength(dex)])
    end
    commands.push(_INTL("Salir"))
    @scene.pbStartScene(commands, commands2)
    loop do
      cmd = @scene.pbScene
      break if cmd < 0 || cmd >= commands2.length   # Cancel/Exit
      $PokemonGlobal.pokedexDex = $player.pokedex.accessible_dexes[cmd]
      pbFadeOutIn do
        scene = PokemonPokedex_Scene.new
        screen = PokemonPokedexScreen.new(scene)
        screen.pbStartScreen
      end
    end
    @scene.pbEndScene
  end
end


==============================================================================
# Script: UI_Pokedex_Main
==============================================================================
#===============================================================================
#
#===============================================================================
class Window_Pokedex < Window_DrawableCommand
  # Constantes para el layout y offsets dentro de la ventana del Pokédex
  # Offset horizontal aplicado al rectángulo de dibujo de cada entrada
  RECT_X_OFFSET       = 16
  # Ajuste de anchura para el rectángulo de dibujo (puede ser negativo)
  RECT_WIDTH_OFFSET   = -16
  # Offset X/Y para el icono de pokeball que indica poseído
  OWN_ICON_X_OFFSET   = -6
  OWN_ICON_Y_OFFSET   = 10
  # Offset X/Y para el icono que indica visto
  SEEN_ICON_X_OFFSET  = -6
  SEEN_ICON_Y_OFFSET  = 10
  # Offset X/Y para dibujar el número del Pokédex
  DEX_NUMBER_X_OFFSET = 36
  DEX_NUMBER_Y_OFFSET = 6
  # Offset X/Y para dibujar el nombre del Pokémon en la lista
  DEX_NAME_X_OFFSET   = 84
  DEX_NAME_Y_OFFSET   = 6
  def initialize(x, y, width, height, viewport)
    @commands = []
    super(x, y, width, height, viewport)
    @selarrow     = AnimatedBitmap.new("Graphics/UI/Pokedex/cursor_list")
    @pokeballOwn  = AnimatedBitmap.new("Graphics/UI/Pokedex/icon_own")
    @pokeballSeen = AnimatedBitmap.new("Graphics/UI/Pokedex/icon_seen")
    self.baseColor   = Color.new(88, 88, 80)
    self.shadowColor = Color.new(168, 184, 184)
    self.windowskin  = nil
  end

  def commands=(value)
    @commands = value
    refresh
  end

  def dispose
    @pokeballOwn.dispose
    @pokeballSeen.dispose
    super
  end

  def species
    return (@commands.length == 0) ? 0 : @commands[self.index][:species]
  end

  def itemCount
    return @commands.length
  end

  def drawItem(index, _count, rect)
    return if index >= self.top_row + self.page_item_max
    rect = Rect.new(rect.x + RECT_X_OFFSET, rect.y, rect.width + RECT_WIDTH_OFFSET, rect.height)
    species     = @commands[index][:species]
    indexNumber = @commands[index][:number]
    indexNumber -= 1 if @commands[index][:shift]
    if $player.seen?(species)
      if $player.owned?(species)
        pbCopyBitmap(self.contents, @pokeballOwn.bitmap, rect.x + OWN_ICON_X_OFFSET, rect.y + OWN_ICON_Y_OFFSET)
      else
        pbCopyBitmap(self.contents, @pokeballSeen.bitmap, rect.x + SEEN_ICON_X_OFFSET, rect.y + SEEN_ICON_Y_OFFSET)
      end
      num_text = sprintf("%03d", indexNumber)
      name_text = @commands[index][:name]
    else
      num_text = sprintf("%03d", indexNumber)
      name_text = "----------"
    end
    pbDrawShadowText(self.contents, rect.x + DEX_NUMBER_X_OFFSET, rect.y + DEX_NUMBER_Y_OFFSET, rect.width, rect.height,
                     num_text, self.baseColor, self.shadowColor)
    pbDrawShadowText(self.contents, rect.x + DEX_NAME_X_OFFSET, rect.y + DEX_NAME_Y_OFFSET, rect.width, rect.height,
                     name_text, self.baseColor, self.shadowColor)
  end

  def refresh
    @item_max = itemCount
    dwidth  = self.width - self.borderX
    dheight = self.height - self.borderY
    self.contents = pbDoEnsureBitmap(self.contents, dwidth, dheight)
    self.contents.clear
    @item_max.times do |i|
      next if i < self.top_item || i > self.top_item + self.page_item_max
      drawItem(i, @item_max, itemRect(i))
    end
    drawCursor(self.index, itemRect(self.index))
  end

  def update
    super
    @uparrow.visible   = false
    @downarrow.visible = false
  end
end

