#===============================================================================
class MoveSelectionSprite < Sprite
  attr_reader :preselected
  attr_reader :index

  # Constantes de posicionamiento del cursor de movimientos
  CURSOR_BASE_X       = 240
  CURSOR_BASE_Y       = 92
  CURSOR_OFFSET_Y     = 64
  FIFTH_MOVE_OFFSET_Y = -76
  FIFTH_MOVE_GAP      = 20

  def initialize(viewport = nil, fifthmove = false)
    super(viewport)
    @movesel = AnimatedBitmap.new("Graphics/UI/Summary/cursor_move")
    @frame = 0
    @index = 0
    @fifthmove = fifthmove
    @preselected = false
    @updating = false
    refresh
  end

  def dispose
    @movesel.dispose
    super
  end

  def index=(value)
    @index = value
    refresh
  end

  def preselected=(value)
    @preselected = value
    refresh
  end

  def refresh
    w = @movesel.width
    h = @movesel.height / 2
    self.x = CURSOR_BASE_X
    self.y = CURSOR_BASE_Y + (self.index * CURSOR_OFFSET_Y)
    self.y += FIFTH_MOVE_OFFSET_Y if @fifthmove
    self.y += FIFTH_MOVE_GAP if @fifthmove && self.index == Pokemon::MAX_MOVES
    self.bitmap = @movesel.bitmap
    if self.preselected
      self.src_rect.set(0, h, w, h)
    else
      self.src_rect.set(0, 0, w, h)
    end
  end

  def update
    @updating = true
    super
    @movesel.update
    @updating = false
    refresh
  end
end

#===============================================================================
#
#===============================================================================
class RibbonSelectionSprite < MoveSelectionSprite

  # Constantes de posicionamiento del cursor de cintas
  CURSOR_BASE_X   = 228
  CURSOR_BASE_Y   = 76
  CURSOR_OFFSET_X = 68
  CURSOR_OFFSET_Y = 68
  COLUMNS_PER_ROW = 4

  def initialize(viewport = nil)
    super(viewport)
    @movesel = AnimatedBitmap.new("Graphics/UI/Summary/cursor_ribbon")
    @frame = 0
    @index = 0
    @preselected = false
    @updating = false
    @spriteVisible = true
    refresh
  end

  def visible=(value)
    super
    @spriteVisible = value if !@updating
  end

  def refresh
    w = @movesel.width
    h = @movesel.height / 2
    self.x = CURSOR_BASE_X + ((self.index % COLUMNS_PER_ROW) * CURSOR_OFFSET_X)
    self.y = CURSOR_BASE_Y + ((self.index / COLUMNS_PER_ROW).floor * CURSOR_OFFSET_Y)
    self.bitmap = @movesel.bitmap
    if self.preselected
      self.src_rect.set(0, h, w, h)
    else
      self.src_rect.set(0, 0, w, h)
    end
  end

  def update
    @updating = true
    super
    self.visible = @spriteVisible && @index >= 0 && @index < 12
    @movesel.update
    @updating = false
    refresh
  end
end

