#
#===============================================================================
class PokemonTrainerCardScreen
  def initialize(scene)
    @scene = scene
  end

  def pbStartScreen
    @scene.pbStartScene
    @scene.pbTrainerCard
    @scene.pbEndScene
  end
end


==============================================================================
# Script: UI_Load
==============================================================================
#===============================================================================
#
#===============================================================================
class PokemonLoadPanel < Sprite
  attr_reader :selected

  TEXT_COLOR               = Color.new(232, 232, 232)
  TEXT_SHADOW_COLOR        = Color.new(136, 136, 136)
  MALE_TEXT_COLOR          = Color.new(56, 160, 248)
  MALE_TEXT_SHADOW_COLOR   = Color.new(56, 104, 168)
  FEMALE_TEXT_COLOR        = Color.new(240, 72, 88)
  FEMALE_TEXT_SHADOW_COLOR = Color.new(160, 64, 64)

  # Panel bitmap/source sizes and layout
  # Alto del panel de la opción "Continuar" en la imagen de fondos (en píxeles)
  PANEL_BG_CONTINUE_HEIGHT       = 222
  # Alto del panel para opciones "nuevas" (no continuar) en la imagen de fondos
  PANEL_BG_NEW_HEIGHT            = 46
  # Posición Y en la imagen de fondos donde están los paneles no-continuar
  PANEL_BG_NONCONTINUE_SRC_Y     = 444
  # Desplazamiento Y aplicado al usar la versión seleccionada del panel nuevo
  PANEL_NEW_SELECTED_OFFSET_Y    = 46

  # Desplazamiento horizontal del menú
  DESPLAZ_HORIZ_MENU  = 0
  # Desplazamiento horizontal de los datos (medallas, pokédex, tiempo) respecto al menú
  DESPLAZ_HORIZ_DATOS = 0
  # Desplazamiento horizontal del texto del mapa
  DESPLAZ_TEXTO_MAPA  = 0

  def initialize(index, title, isContinue, trainer, stats, mapid, viewport = nil)
    super(viewport)
    @index = index
    @title = title
    @isContinue = isContinue
    @trainer = trainer
    @totalsec = stats&.play_time.to_i || 0
    @mapid = mapid
    @selected = (index == 0)
    @bgbitmap = AnimatedBitmap.new("Graphics/UI/Load/panels")
    @refreshBitmap = true
    @refreshing = false
    refresh
  end

  def dispose
    @bgbitmap.dispose
    self.bitmap.dispose
    super
  end

  def selected=(value)
    return if @selected == value
    @selected = value
    @refreshBitmap = true
    refresh
  end

  def pbRefresh
    @refreshBitmap = true
    refresh
  end

  def refresh
    return if @refreshing
    return if disposed?
    @refreshing = true
    if !self.bitmap || self.bitmap.disposed?
      self.bitmap = Bitmap.new(@bgbitmap.width, PANEL_BG_CONTINUE_HEIGHT)
      pbSetSystemFont(self.bitmap)
    end
    if @refreshBitmap
      @refreshBitmap = false
      self.bitmap&.clear
      if @isContinue
        self.bitmap.blt(0, 0, @bgbitmap.bitmap, Rect.new(0, (@selected) ? PANEL_BG_CONTINUE_HEIGHT : 0, @bgbitmap.width, PANEL_BG_CONTINUE_HEIGHT))
      else
        self.bitmap.blt(0, 0, @bgbitmap.bitmap, Rect.new(0, PANEL_BG_NONCONTINUE_SRC_Y + ((@selected) ? PANEL_NEW_SELECTED_OFFSET_Y : 0), @bgbitmap.width, PANEL_BG_NEW_HEIGHT))
      end
      textpos = []
      if @isContinue
        textpos.push([@title, 32 + DESPLAZ_HORIZ_MENU, 16, :left, TEXT_COLOR, TEXT_SHADOW_COLOR])
        textpos.push([_INTL("Medallas:"), 32 + DESPLAZ_HORIZ_MENU, 118, :left, TEXT_COLOR, TEXT_SHADOW_COLOR])
        textpos.push([@trainer.badge_count.to_s, 206 + DESPLAZ_HORIZ_MENU + DESPLAZ_HORIZ_DATOS, 118, :right, TEXT_COLOR, TEXT_SHADOW_COLOR])
        textpos.push([_INTL("Pokédex:"), 32 + DESPLAZ_HORIZ_MENU, 150, :left, TEXT_COLOR, TEXT_SHADOW_COLOR])
        textpos.push([@trainer.pokedex.seen_count.to_s, 206 + DESPLAZ_HORIZ_MENU + DESPLAZ_HORIZ_DATOS, 150, :right, TEXT_COLOR, TEXT_SHADOW_COLOR])
        textpos.push([_INTL("Tiempo:"), 32 + DESPLAZ_HORIZ_MENU, 182, :left, TEXT_COLOR, TEXT_SHADOW_COLOR])
        hour = @totalsec / 60 / 60
        min  = @totalsec / 60 % 60
        if hour > 0
          textpos.push([_INTL("{1}h {2}m", hour, min), 206 + DESPLAZ_HORIZ_MENU + DESPLAZ_HORIZ_DATOS, 182, :right, TEXT_COLOR, TEXT_SHADOW_COLOR])
        else
          textpos.push([_INTL("{1}m", min), 206 + DESPLAZ_HORIZ_MENU + DESPLAZ_HORIZ_DATOS, 182, :right, TEXT_COLOR, TEXT_SHADOW_COLOR])
        end
        if @trainer.male?
          textpos.push([@trainer.name, 112 + DESPLAZ_HORIZ_MENU, 70, :left, MALE_TEXT_COLOR, MALE_TEXT_SHADOW_COLOR])
        elsif @trainer.female?
          textpos.push([@trainer.name, 112 + DESPLAZ_HORIZ_MENU, 70, :left, FEMALE_TEXT_COLOR, FEMALE_TEXT_SHADOW_COLOR])
        else
          textpos.push([@trainer.name, 112 + DESPLAZ_HORIZ_MENU, 70, :left, TEXT_COLOR, TEXT_SHADOW_COLOR])
        end
        mapname = pbGetMapNameFromId(@mapid)
        mapname.gsub!(/\\PN/, @trainer.name)
        textpos.push([mapname, 386 + DESPLAZ_HORIZ_MENU + DESPLAZ_TEXTO_MAPA, 16, :right, TEXT_COLOR, TEXT_SHADOW_COLOR])
      else
        textpos.push([@title, 32 + DESPLAZ_HORIZ_MENU, 14, :left, TEXT_COLOR, TEXT_SHADOW_COLOR])
      end
      pbDrawTextPositions(self.bitmap, textpos)
    end
    @refreshing = false
  end
end

#===============================================================================
#
#===============================================================================
class PokemonLoad_Scene

  # Altura total del espacio ocupado por un panel tipo "Continuar" en el listado (incluye separación)
  PANEL_TOTAL_HEIGHT_CONTINUE    = 224 
  
  # Altura total del espacio ocupado por un panel tipo "Nuevo" en el listado
  PANEL_TOTAL_HEIGHT_NEW         = 48

  # Player/party layout constants
  # Coordenada X base donde se centra el sprite del jugador en el panel
  PLAYER_CHAR_BASE_X = 112
  # Coordenada Y base donde se centra el sprite del jugador en el panel
  PLAYER_CHAR_BASE_Y = 112
  # Divisor usado para calcular el desplazamiento del charset (charwidth / PLAYER_CHAR_DIV)
  PLAYER_CHAR_DIV    = 8
  # Nivel Z para el sprite del jugador (orden de dibujo)
  PLAYER_Z           = 99999

  # Coordenada X inicial para dibujar los iconos de la party (primer slot)
  PARTY_START_X      = 334
  # Espacio horizontal entre iconos de la party cuando se colocan en columnas
  PARTY_X_SPACING    = 66
  # Coordenada Y inicial para dibujar los iconos de la party
  PARTY_START_Y      = 112
  # Espacio vertical entre filas de iconos de la party
  PARTY_Y_SPACING    = 50
  # Nivel Z para los iconos de la party (orden de dibujo)
  PARTY_Z            = 99999
  # Número máximo de iconos de party a considerar (tamaño del array mostrado)
  PARTY_MAX          = 6

  def pbStartScene(commands, show_continue, trainer, stats, map_id)
    @commands = commands
    @sprites = {}
    @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = 99998
    addBackgroundOrColoredPlane(@sprites, "background", "Load/bg", Color.new(248, 248, 248), @viewport)
    y = 32
    commands.length.times do |i|
      @sprites["panel#{i}"] = PokemonLoadPanel.new(
        i, commands[i], (show_continue) ? (i == 0) : false, trainer, stats, map_id, @viewport
      )
      @sprites["panel#{i}"].x = 48
      @sprites["panel#{i}"].y = y
      @sprites["panel#{i}"].pbRefresh
      y += (show_continue && i == 0) ? PANEL_TOTAL_HEIGHT_CONTINUE : PANEL_TOTAL_HEIGHT_NEW
    end
    @sprites["cmdwindow"] = Window_CommandPokemon.new([])
    @sprites["cmdwindow"].viewport = @viewport
    @sprites["cmdwindow"].visible  = false
  end

  def pbStartScene2
    pbFadeInAndShow(@sprites) { pbUpdate }
  end

  def pbStartDeleteScene
    @sprites = {}
    @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = 99998
    addBackgroundOrColoredPlane(@sprites, "background", "Load/bg", Color.new(248, 248, 248), @viewport)
  end

  def pbUpdate
    oldi = @sprites["cmdwindow"].index rescue 0
    pbUpdateSpriteHash(@sprites)
    newi = @sprites["cmdwindow"].index rescue 0
    if oldi != newi
      @sprites["panel#{oldi}"].selected = false
      @sprites["panel#{oldi}"].pbRefresh
      @sprites["panel#{newi}"].selected = true
      @sprites["panel#{newi}"].pbRefresh
      while @sprites["panel#{newi}"].y > Graphics.height - 80
        @commands.length.times do |i|
          @sprites["panel#{i}"].y -= PANEL_TOTAL_HEIGHT_NEW
        end
        PARTY_MAX.times do |i|
          break if !@sprites["party#{i}"]
          @sprites["party#{i}"].y -= PANEL_TOTAL_HEIGHT_NEW
        end
        @sprites["player"].y -= PANEL_TOTAL_HEIGHT_NEW if @sprites["player"]
      end
      while @sprites["panel#{newi}"].y < 32
        @commands.length.times do |i|
          @sprites["panel#{i}"].y += PANEL_TOTAL_HEIGHT_NEW
        end
        PARTY_MAX.times do |i|
          break if !@sprites["party#{i}"]
          @sprites["party#{i}"].y += PANEL_TOTAL_HEIGHT_NEW
        end
        @sprites["player"].y += PANEL_TOTAL_HEIGHT_NEW if @sprites["player"]
      end
    end
  end

  def pbSetParty(trainer)
    return if !trainer || !trainer.party
    meta = GameData::PlayerMetadata.get(trainer.character_ID)
    if meta
      filename = pbGetPlayerCharset(meta.walk_charset, trainer, true)
      @sprites["player"] = TrainerWalkingCharSprite.new(filename, @viewport)
      if !@sprites["player"].bitmap
        raise _INTL("No se ha encontrado el charset del jugador {1} andando (archivo: \"{2}\").", trainer.character_ID, filename)
      end
      charwidth  = @sprites["player"].bitmap.width
      charheight = @sprites["player"].bitmap.height
      @sprites["player"].x = PLAYER_CHAR_BASE_X - (charwidth / PLAYER_CHAR_DIV)
      @sprites["player"].y = PLAYER_CHAR_BASE_Y - (charheight / PLAYER_CHAR_DIV)
      @sprites["player"].z = PLAYER_Z
    end
    trainer.party.each_with_index do |pkmn, i|
      @sprites["party#{i}"] = PokemonIconSprite.new(pkmn, @viewport)
      @sprites["party#{i}"].setOffset(PictureOrigin::CENTER)
      @sprites["party#{i}"].x = PARTY_START_X + (PARTY_X_SPACING * (i % 2))
      @sprites["party#{i}"].y = PARTY_START_Y + (PARTY_Y_SPACING * (i / 2))
      @sprites["party#{i}"].z = PARTY_Z
    end
  end

  def pbChoose(commands)
    @sprites["cmdwindow"].commands = commands
    loop do
      Graphics.update
      Input.update
      pbUpdate
      if Input.trigger?(Input::USE)
        return @sprites["cmdwindow"].index
      end
    end
  end

  def pbEndScene
    pbFadeOutAndHide(@sprites) { pbUpdate }
    pbDisposeSpriteHash(@sprites)
    @viewport.dispose
  end

  def pbCloseScene
    pbDisposeSpriteHash(@sprites)
    @viewport.dispose
  end
end

#===============================================================================
#
#===============================================================================
class PokemonLoadScreen
  def initialize(scene)
    @scene = scene
    if SaveData.exists?
      @save_data = load_save_file(SaveData::FILE_PATH)
    else
      @save_data = {}
    end
  end

  # @param file_path [String] file to load save data from
  # @return [Hash] save data
  def load_save_file(file_path)
    save_data = SaveData.read_from_file(file_path)
    unless SaveData.valid?(save_data)
      if File.file?(file_path + ".bak")
        pbMessage(_INTL("El archivo está corrupto. Se va a cargar un respaldo."))
        save_data = load_save_file(file_path + ".bak")
      else
        self.prompt_save_deletion
        return {}
      end
    end
    return save_data
  end

  # Called if all save data is invalid.
  # Prompts the player to delete the save files.
  def prompt_save_deletion
    pbMessage(_INTL("La partida guardada está corrupta, o es incompatible con este juego.") + "\1")
    exit unless pbConfirmMessageSerious(
      _INTL("¿Quieres borrar la partida y empezar una nueva?")
    )
    self.delete_save_data
    $game_system   = Game_System.new
    $PokemonSystem = PokemonSystem.new
  end

  def pbStartDeleteScreen
    @scene.pbStartDeleteScene
    @scene.pbStartScene2
    if SaveData.exists?
      if pbConfirmMessageSerious(_INTL("¿Borrar todos los datos guardados?"))
        pbMessage(_INTL("Una vez que los datos se borren no habrá forma de recuperarlos.") + "\1")
        if pbConfirmMessageSerious(_INTL("¿Borrar los datos guardados de todos modos?"))
          pbMessage(_INTL("Borrando todos los datos. No cierres el juego.") + "\\wtnp[0]")
          self.delete_save_data
        end
      end
    else
      pbMessage(_INTL("No se han encontrado datos de guardado."))
    end
    @scene.pbEndScene
    $scene = pbCallTitle
  end

  def delete_save_data
    begin
      SaveData.delete_file
      pbMessage(_INTL("Los datos guardados se han borrado."))
    rescue SystemCallError
      pbMessage(_INTL("No se han podido borrar todos los datos guardados."))
    end
  end

  def pbStartLoadScreen
    check_for_updates() if defined?(check_for_updates) # Required for PokéUpdater to check for gameupdates.
    commands = []
    cmd_continue     = -1
    cmd_new_game     = -1
    cmd_options      = -1
    cmd_language     = -1
    cmd_mystery_gift = -1
    cmd_update       = -1
    cmd_debug        = -1
    cmd_quit         = -1
    show_continue = !@save_data.empty?
    if show_continue
      commands[cmd_continue = commands.length] = _INTL("Continuar")
      if @save_data[:player].mystery_gift_unlocked
        commands[cmd_mystery_gift = commands.length] = _INTL("Regalo Misterioso")
      end
    end
    commands[cmd_new_game = commands.length]  = _INTL("Nueva partida")
    commands[cmd_options = commands.length]   = _INTL("Opciones")
    commands[cmd_language = commands.length]  = _INTL("Idioma") if Settings::LANGUAGES.length >= 2
    commands[cmd_update=commands.length]      = _INTL("Buscar actualizaciones") if PluginManager.installed?("Pokemon Essentials Game Updater")
    commands[cmd_debug = commands.length]     = _INTL("Debug") if $DEBUG
    commands[cmd_quit = commands.length]      = _INTL("Cerrar Juego")
    map_id = show_continue ? @save_data[:map_factory].map.map_id : 0
    @scene.pbStartScene(commands, show_continue, @save_data[:player], @save_data[:stats], map_id)
    @scene.pbSetParty(@save_data[:player]) if show_continue
    @scene.pbStartScene2
    loop do
      command = @scene.pbChoose(commands)
      pbPlayDecisionSE if command != cmd_quit
      case command
      when cmd_continue
        @scene.pbEndScene
        Game.load(@save_data)
        return
      when cmd_new_game
        @scene.pbEndScene
        Game.start_new
        return
      when cmd_mystery_gift
        pbFadeOutIn { pbDownloadMysteryGift(@save_data[:player]) }
      when cmd_options
        if Settings::USE_NEW_OPTIONS_UI
          UI::Options.new(true).main
        else
          pbFadeOutIn do
            scene = PokemonOption_Scene.new
            screen = PokemonOptionScreen.new(scene)
            screen.pbStartScreen(true)
          end
        end
      when cmd_language
        @scene.pbEndScene
        $PokemonSystem.language = pbChooseLanguage
        MessageTypes.load_message_files(Settings::LANGUAGES[$PokemonSystem.language][1])
        if show_continue
          @save_data[:pokemon_system] = $PokemonSystem
          File.open(SaveData::FILE_PATH, "wb") { |file| Marshal.dump(@save_data, file) }
        end
        $scene = pbCallTitle
        return
      when cmd_debug
        pbFadeOutIn { pbDebugMenu(false) }
      when cmd_update
        validate_game_version_and_update(true) if defined?(validate_game_version_and_update)   
      when cmd_quit
        pbPlayCloseMenuSE
        @scene.pbEndScene
        $scene = nil
        return
      else
        pbPlayBuzzerSE
      end
    end
  end
end


==============================================================================
# Script: UI_Save
==============================================================================
def pbEmergencySave
  oldscene = $scene
  $scene = nil
  pbMessage(_INTL("El script está tardando mucho. Se va a reiniciar el juego."))
  return if !$player
  if SaveData.exists?
    File.open(SaveData::FILE_PATH, "rb") do |r|
      File.open(SaveData::FILE_PATH + ".bak", "wb") do |w|
        loop do
          s = r.read(4096)
          break if !s
          w.write(s)
        end
      end
    end
  end
  if Game.save
    pbMessage("\\se[]" + _INTL("Se ha guardado la partida.") + "\\me[GUI save game]\\wtnp[20]")
    pbMessage("\\se[]" + _INTL("Se ha hecho una copia del anterior archivo de guardado.") + "\\wtnp[20]")
  else
    pbMessage("\\se[]" + _INTL("El guardado ha fallado.") + "\\wtnp[30]")
  end
  $scene = oldscene
end

#===============================================================================
#
#===============================================================================
class PokemonSave_Scene
  LOCATION_TEXT_BASE   = Color.new(32, 152, 8)    # Green
  LOCATION_TEXT_SHADOW = Color.new(144, 240, 144)
  MALE_TEXT_BASE       = Color.new(0, 112, 248)   # Blue
  MALE_TEXT_SHADOW     = Color.new(120, 184, 232)
  FEMALE_TEXT_BASE     = Color.new(232, 32, 16)   # Red
  FEMALE_TEXT_SHADOW   = Color.new(248, 168, 184)
  OTHER_TEXT_BASE      = Color.new(0, 112, 248)   # Blue
  OTHER_TEXT_SHADOW    = Color.new(120, 184, 232)

  # Misc constants
  DEFAULT_VIEWPORT_Z        = 99999
  LOCWINDOW_MIN_WIDTH       = 228

  def pbStartScreen
    @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = DEFAULT_VIEWPORT_Z
    @sprites = {}
    totalsec = $stats.play_time.to_i
    hour = totalsec / 60 / 60
    min = totalsec / 60 % 60
    mapname = $game_map.name
    if $player.male?
      text_tag = shadowc3tag(MALE_TEXT_BASE, MALE_TEXT_SHADOW)
    elsif $player.female?
      text_tag = shadowc3tag(FEMALE_TEXT_BASE, FEMALE_TEXT_SHADOW)
    else
      text_tag = shadowc3tag(OTHER_TEXT_BASE, OTHER_TEXT_SHADOW)
    end
    location_tag = shadowc3tag(LOCATION_TEXT_BASE, LOCATION_TEXT_SHADOW)
    loctext = location_tag + "<ac>" + mapname + "</ac></c3>"
    loctext += _INTL("Jugador") + "<r>" + text_tag + $player.name + "</c3><br>"
    if hour > 0
      loctext += _INTL("Tiempo") + "<r>" + text_tag + _INTL("{1}h {2}m", hour, min) + "</c3><br>"
    else
      loctext += _INTL("Tiempo") + "<r>" + text_tag + _INTL("{1}m", min) + "</c3><br>"
    end
    loctext += _INTL("Medallas") + "<r>" + text_tag + $player.badge_count.to_s + "</c3><br>"
    if $player.has_pokedex
      loctext += _INTL("Pokédex") + "<r>" + text_tag + $player.pokedex.owned_count.to_s + "/" + $player.pokedex.seen_count.to_s + "</c3>"
    end
    @sprites["locwindow"] = Window_AdvancedTextPokemon.new(loctext)
    @sprites["locwindow"].viewport = @viewport
    @sprites["locwindow"].x = 0
    @sprites["locwindow"].y = 0
    @sprites["locwindow"].width = LOCWINDOW_MIN_WIDTH if @sprites["locwindow"].width < LOCWINDOW_MIN_WIDTH
    @sprites["locwindow"].visible = true
  end

  def pbEndScreen
    pbDisposeSpriteHash(@sprites)
    @viewport.dispose
  end
end

#===============================================================================
#
#===============================================================================
class PokemonSaveScreen
  def initialize(scene)
    @scene = scene
  end

  def pbDisplay(text, brief = false)
    @scene.pbDisplay(text, brief)
  end

  def pbDisplayPaused(text)
    @scene.pbDisplayPaused(text)
  end

  def pbConfirm(text)
    return @scene.pbConfirm(text)
  end

  def pbSaveScreen
    ret = false
    @scene.pbStartScreen
    if pbConfirmMessage(_INTL("¿Quieres guardar la partida?"))
      if SaveData.exists? && $game_temp.begun_new_game
        pbMessage(_INTL("¡AVISO!") + "\1")
        pbMessage(_INTL("Tienes ya un archivo de guardado de una partida diferente.") + "\1")
        pbMessage(_INTL("Si guardas ahora, todos los datos de la otra partida se perderán para siempre.") + "\1")
        if !pbConfirmMessageSerious(_INTL("¿Estás segur{1} de que quieres guardar la partida y sobreescribir el otro archivo?", $player.female? ? 'a' : 'o'))
          pbSEPlay("GUI save choice")
          @scene.pbEndScreen
          return false
        end
      end
      $game_temp.begun_new_game = false
      pbSEPlay("GUI save choice")
      if Game.save
        pbMessage("\\se[]" + _INTL("{1} guardó la partida.", $player.name) + "\\me[GUI save game]\\wtnp[20]")
        ret = true
      else
        pbMessage("\\se[]" + _INTL("El guardado ha fallado.") + "\\wtnp[30]")
        ret = false
      end
    else
      pbSEPlay("GUI save choice")
    end
    @scene.pbEndScreen
    return ret
  end
end
#===============================================================================
#
#===============================================================================
def pbSaveScreen
  scene = PokemonSave_Scene.new
  screen = PokemonSaveScreen.new(scene)
  ret = screen.pbSaveScreen
  return ret
end

