#===============================================================================
# Pokémon icons
#===============================================================================
class PokemonBoxIcon < IconSprite
  def initialize(pokemon, viewport = nil)
    super(0, 0, viewport)
    @pokemon = pokemon
    @release_timer_start = nil
    @should_be_grey = @pokemon&.fainted? && Settings::GREY_OUT_FAINTED
    refresh
  end

  def getPokemon
    return @pokemon
  end

  def releasing?
    return !@release_timer_start.nil?
  end

  def make_grey_if_fainted=(value)
    return if !Settings::GREY_OUT_FAINTED
    @should_be_grey = value
  end

  def release
    self.ox = self.src_rect.width / 2    # 32
    self.oy = self.src_rect.height / 2   # 32
    self.x += self.src_rect.width / 2    # 32
    self.y += self.src_rect.height / 2   # 32
    @release_timer_start = System.uptime
  end

  def refresh
    return if !@pokemon
    self.setBitmap(GameData::Species.icon_filename_from_pokemon(@pokemon))
    self.src_rect = Rect.new(0, 0, self.bitmap.height, self.bitmap.height)
  end

  def update
    super
    self.color = Color.new(0, 0, 0, 0)
    # Apply tone after any bitmap changes
    if @should_be_grey
      self.tone = Tone.new(0, 0, 0, 255)
    else
      self.tone = Tone.new(0, 0, 0, 0)
    end
    if releasing?
      self.zoom_x = lerp(1.0, 0.0, 1.5, @release_timer_start, System.uptime)
      self.zoom_y = self.zoom_x
      self.opacity = lerp(255, 0, 1.5, @release_timer_start, System.uptime)
      if self.opacity == 0
        @release_timer_start = nil
        dispose
      end
    end
  end
end

#===============================================================================
# Pokémon sprite
#===============================================================================
class MosaicPokemonSprite < PokemonSprite
  attr_reader :mosaic

  def initialize(*args)
    super(*args)
    @mosaic = 0
    @inrefresh = false
    @mosaicbitmap = nil
    @mosaicbitmap2 = nil
    @oldbitmap = self.bitmap
  end

  def dispose
    super
    @mosaicbitmap&.dispose
    @mosaicbitmap = nil
    @mosaicbitmap2&.dispose
    @mosaicbitmap2 = nil
  end

  def bitmap=(value)
    super
    mosaicRefresh(value)
  end

  def mosaic=(value)
    @mosaic = value
    @mosaic = 0 if @mosaic < 0
    mosaicRefresh(@oldbitmap)
  end

  def mosaicRefresh(bitmap)
    return if @inrefresh
    @inrefresh = true
    @oldbitmap = bitmap
    if @mosaic <= 0 || !@oldbitmap
      @mosaicbitmap&.dispose
      @mosaicbitmap = nil
      @mosaicbitmap2&.dispose
      @mosaicbitmap2 = nil
      self.bitmap = @oldbitmap
    else
      newWidth  = [(@oldbitmap.width / @mosaic), 1].max
      newHeight = [(@oldbitmap.height / @mosaic), 1].max
      @mosaicbitmap2&.dispose
      @mosaicbitmap = pbDoEnsureBitmap(@mosaicbitmap, newWidth, newHeight)
      @mosaicbitmap.clear
      @mosaicbitmap2 = pbDoEnsureBitmap(@mosaicbitmap2, @oldbitmap.width, @oldbitmap.height)
      @mosaicbitmap2.clear
      @mosaicbitmap.stretch_blt(Rect.new(0, 0, newWidth, newHeight), @oldbitmap, @oldbitmap.rect)
      @mosaicbitmap2.stretch_blt(
        Rect.new((-@mosaic / 2) + 1, (-@mosaic / 2) + 1, @mosaicbitmap2.width, @mosaicbitmap2.height),
        @mosaicbitmap, Rect.new(0, 0, newWidth, newHeight)
      )
      self.bitmap = @mosaicbitmap2
    end
    @inrefresh = false
  end
end

#===============================================================================
#
#===============================================================================
class AutoMosaicPokemonSprite < MosaicPokemonSprite
  INITIAL_MOSAIC = 10   # Pixellation factor
  
  def initialize(*args)
    super(*args)
    @should_be_grey = false
  end

  def mosaic=(value)
    @mosaic = value
    @mosaic = 0 if @mosaic < 0
    @start_mosaic = @mosaic if !@start_mosaic
  end

  def mosaic_duration=(val)
    @mosaic_duration = val
    @mosaic_duration = 0 if @mosaic_duration < 0
    @mosaic_timer_start = System.uptime if @mosaic_duration > 0
  end

  def make_grey_if_fainted=(value)
    return if !Settings::GREY_OUT_FAINTED
    @should_be_grey = value
  end

  def update
    super
    if @mosaic_timer_start
      @start_mosaic = INITIAL_MOSAIC if !@start_mosaic || @start_mosaic == 0
      new_mosaic = lerp(@start_mosaic, 0, @mosaic_duration, @mosaic_timer_start, System.uptime).to_i
      self.mosaic = new_mosaic
      mosaicRefresh(@oldbitmap)
      if new_mosaic == 0
        @mosaic_timer_start = nil
        @start_mosaic = nil
      end
    end
    # Apply tone after any bitmap changes
    if @should_be_grey
      self.tone = Tone.new(0, 0, 0, 255)
    else
      self.tone = Tone.new(0, 0, 0, 0)
    end
  end
end

#===============================================================================
# Cursor
#===============================================================================
class PokemonBoxArrow < Sprite

  HELD_POKEMON_Y_OFFSET = 16

  attr_accessor :quickswap

  # Time in seconds for the cursor to move down and back up to grab/drop a
  # Pokémon.
  GRAB_TIME = 0.4

  def initialize(viewport = nil)
    super(viewport)
    @holding    = false
    @updating   = false
    @quickswap  = false
    @heldpkmn   = nil
    @handsprite = ChangelingSprite.new(0, 0, viewport)
    @handsprite.add_bitmap(:point1, "Graphics/UI/Storage/cursor_point_1")
    @handsprite.add_bitmap(:point2, "Graphics/UI/Storage/cursor_point_2")
    @handsprite.add_bitmap(:grab, "Graphics/UI/Storage/cursor_grab")
    @handsprite.add_bitmap(:fist, "Graphics/UI/Storage/cursor_fist")
    @handsprite.add_bitmap(:point1q, "Graphics/UI/Storage/cursor_point_1_q")
    @handsprite.add_bitmap(:point2q, "Graphics/UI/Storage/cursor_point_2_q")
    @handsprite.add_bitmap(:grabq, "Graphics/UI/Storage/cursor_grab_q")
    @handsprite.add_bitmap(:fistq, "Graphics/UI/Storage/cursor_fist_q")
    @handsprite.change_bitmap(:fist)
    @spriteX = self.x
    @spriteY = self.y
  end

  def dispose
    @handsprite.dispose
    @heldpkmn&.dispose
    super
  end

  def x=(value)
    super
    @handsprite.x = self.x
    @spriteX = x if !@updating
    heldPokemon.x = self.x if holding?
  end

  def y=(value)
    super
    @handsprite.y = self.y
    @spriteY = y if !@updating
    heldPokemon.y = self.y + HELD_POKEMON_Y_OFFSET if holding?
  end

  def z=(value)
    super
    @handsprite.z = value
  end

  def visible=(value)
    super
    @handsprite.visible = value
    sprite = heldPokemon
    sprite.visible = value if sprite
  end

  def color=(value)
    super
    @handsprite.color = value
    sprite = heldPokemon
    sprite.color = value if sprite
  end

  def heldPokemon
    @heldpkmn = nil if @heldpkmn&.disposed?
    @holding = false if !@heldpkmn
    return @heldpkmn
  end

  def holding?
    return self.heldPokemon && @holding
  end

  def grabbing?
    return !@grabbing_timer_start.nil?
  end

  def placing?
    return !@placing_timer_start.nil?
  end

  def setSprite(sprite)
    if holding?
      @heldpkmn = sprite
      @heldpkmn.viewport = self.viewport if @heldpkmn
      @heldpkmn.z = 1 if @heldpkmn
      @holding = false if !@heldpkmn
      self.z = 2
    end
  end

  def deleteSprite
    @holding = false
    if @heldpkmn
      @heldpkmn.dispose if !@heldpkmn.disposed?
      @heldpkmn = nil
    end
  end

  def grab(sprite)
    @grabbing_timer_start = System.uptime
    @heldpkmn = sprite
    @heldpkmn.viewport = self.viewport
    @heldpkmn.z = 1
    self.z = 2
  end

  def place
    @placing_timer_start = System.uptime
  end

  def release
    @heldpkmn&.release
  end

  def update
    @updating = true
    super
    heldpkmn = heldPokemon
    heldpkmn&.update
    @handsprite.update
    if @handsprite && !@handsprite.disposed?
      @handsprite.update 
    end
    @holding = false if !heldpkmn
    if @grabbing_timer_start
      if System.uptime - @grabbing_timer_start <= GRAB_TIME / 2
        @handsprite.change_bitmap((@quickswap) ? :grabq : :grab)
        self.y = @spriteY + lerp(0, 16, GRAB_TIME / 2, @grabbing_timer_start, System.uptime)
      else
        @holding = true
        @handsprite.change_bitmap((@quickswap) ? :fistq : :fist)
        delta_y = lerp(16, 0, GRAB_TIME / 2, @grabbing_timer_start + (GRAB_TIME / 2), System.uptime)
        self.y = @spriteY + delta_y
        @grabbing_timer_start = nil if delta_y == 0
      end
    elsif @placing_timer_start
      if System.uptime - @placing_timer_start <= GRAB_TIME / 2
        @handsprite.change_bitmap((@quickswap) ? :fistq : :fist)
        self.y = @spriteY + lerp(0, 16, GRAB_TIME / 2, @placing_timer_start, System.uptime)
      else
        @holding = false
        @heldpkmn = nil
        @handsprite.change_bitmap((@quickswap) ? :grabq : :grab)
        delta_y = lerp(16, 0, GRAB_TIME / 2, @placing_timer_start + (GRAB_TIME / 2), System.uptime)
        self.y = @spriteY + delta_y
        @placing_timer_start = nil if delta_y == 0
      end
    elsif holding?
      @handsprite.change_bitmap((@quickswap) ? :fistq : :fist)
    else   # Idling
      self.x = @spriteX
      self.y = @spriteY
      if (System.uptime / 0.5).to_i.even?   # Changes every 0.5 seconds
        @handsprite.change_bitmap((@quickswap) ? :point1q : :point1)
      else
        @handsprite.change_bitmap((@quickswap) ? :point2q : :point2)
      end
    end
    @updating = false
  end
end

#===============================================================================
# Box
#===============================================================================
class PokemonBoxSprite < Sprite
  attr_accessor :refreshBox
  attr_accessor :refreshSprites

  BOX_WIDTH = 324
  BOX_HEIGHT = 296
  BOX_X = 184
  BOX_Y = 18
  BOX_NAME_X_OFFSET = 162
  BOX_NAME_Y = 14
  BOX_NAME_HEIGHT = 32
  POKEMON_BOX_SPRITE_Y_OFFSET = 30
  POKEMON_BOX_SPRITE_X_OFFSET = 10
  POKEMON_BOX_SPRITE_X_SPACING = 48
  POKEMON_BOX_SPRITE_Y_SPACING = 48


  def initialize(storage, boxnumber, viewport = nil)
    super(viewport)
    @storage = storage
    @boxnumber = boxnumber
    @refreshBox = true
    @refreshSprites = true
    @pokemonsprites = []
    PokemonBox::BOX_SIZE.times do |i|
      @pokemonsprites[i] = nil
      pokemon = @storage[boxnumber, i]
      @pokemonsprites[i] = PokemonBoxIcon.new(pokemon, viewport)
    end
    @contents = Bitmap.new(BOX_WIDTH, BOX_HEIGHT)
    self.bitmap = @contents
    self.x = BOX_X
    self.y = BOX_Y
    refresh
  end

  def dispose
    if !disposed?
      PokemonBox::BOX_SIZE.times do |i|
        @pokemonsprites[i]&.dispose
        @pokemonsprites[i] = nil
      end
      @boxbitmap.dispose
      @contents.dispose
      super
    end
  end

  def x=(value)
    super
    refresh
  end

  def y=(value)
    super
    refresh
  end

  def color=(value)
    super
    if @refreshSprites
      PokemonBox::BOX_SIZE.times do |i|
        if @pokemonsprites[i] && !@pokemonsprites[i].disposed?
          @pokemonsprites[i].color = value
        end
      end
    end
    refresh
  end

  def visible=(value)
    super
    PokemonBox::BOX_SIZE.times do |i|
      if @pokemonsprites[i] && !@pokemonsprites[i].disposed?
        @pokemonsprites[i].visible = value
      end
    end
    refresh
  end

  def getBoxBitmap
    if !@bg || @bg != @storage[@boxnumber].background
      curbg = @storage[@boxnumber].background
      if !curbg || (curbg.is_a?(String) && curbg.length == 0)
        @bg = @boxnumber % PokemonStorage::BASICWALLPAPERQTY
      else
        if curbg.is_a?(String) && curbg[/^box(\d+)$/]
          curbg = $~[1].to_i
          @storage[@boxnumber].background = curbg
        end
        @bg = curbg
      end
      if !@storage.isAvailableWallpaper?(@bg)
        @bg = @boxnumber % PokemonStorage::BASICWALLPAPERQTY
        @storage[@boxnumber].background = @bg
      end
      @boxbitmap&.dispose
      @boxbitmap = AnimatedBitmap.new("Graphics/UI/Storage/box_#{@bg}")
    end
  end

  def getPokemon(index)
    return @pokemonsprites[index]
  end

  def setPokemon(index, sprite)
    @pokemonsprites[index] = sprite
    @pokemonsprites[index].refresh
    refresh
  end

  def grabPokemon(index, arrow)
    sprite = @pokemonsprites[index]
    if sprite
      arrow.grab(sprite)
      @pokemonsprites[index] = nil
      refresh
    end
  end

  def deletePokemon(index)
    @pokemonsprites[index].dispose
    @pokemonsprites[index] = nil
    refresh
  end

  def refresh
    if @refreshBox
      boxname = @storage[@boxnumber].name
      getBoxBitmap
      @contents.blt(0, 0, @boxbitmap.bitmap, Rect.new(0, 0, BOX_WIDTH, BOX_HEIGHT))
      pbSetSystemFont(@contents)
      widthval = @contents.text_size(boxname).width
      xval = BOX_NAME_X_OFFSET - (widthval / 2)
      pbDrawShadowText(@contents, xval, BOX_NAME_Y, widthval, BOX_NAME_HEIGHT,
                       boxname, Color.new(248, 248, 248), Color.new(40, 48, 48))
      @refreshBox = false
    end
    yval = self.y + POKEMON_BOX_SPRITE_Y_OFFSET
    PokemonBox::BOX_HEIGHT.times do |j|
      xval = self.x + POKEMON_BOX_SPRITE_X_OFFSET
      PokemonBox::BOX_WIDTH.times do |k|
        sprite = @pokemonsprites[(j * PokemonBox::BOX_WIDTH) + k]
        if sprite && !sprite.disposed?
          sprite.viewport = self.viewport
          sprite.x = xval
          sprite.y = yval
          sprite.z = 1
        end
        xval += POKEMON_BOX_SPRITE_X_SPACING
      end
      yval += POKEMON_BOX_SPRITE_Y_SPACING
    end
  end

  def update
    super
    PokemonBox::BOX_SIZE.times do |i|
      if @pokemonsprites[i] && !@pokemonsprites[i].disposed?
        @pokemonsprites[i].update
      end
    end
  end
end

#===============================================================================
# Party pop-up panel
#===============================================================================
class PokemonBoxPartySprite < Sprite

  PARTY_BOX_WIDTH      = 172
  PARTY_BOX_HEIGHT     = 352
  PARTY_BOX_X          = 182
  PARTY_BOX_Y_OFFSET   = -352
  BACK_TEXT_X          = 86
  BACK_TEXT_Y          = 248
  PARTY_ICON_X_START   = 18
  PARTY_ICON_X_SPACING = 72
  PARTY_ICON_Y_START   = 2
  PARTY_ICON_Y_SPACING = 64
  PARTY_ICON_HEIGHT    = 16

  def initialize(party, viewport = nil)
    super(viewport)
    @party = party
    @boxbitmap = AnimatedBitmap.new("Graphics/UI/Storage/overlay_party")
    @pokemonsprites = []
    Settings::MAX_PARTY_SIZE.times do |i|
      @pokemonsprites[i] = nil
      pokemon = @party[i]
      @pokemonsprites[i] = PokemonBoxIcon.new(pokemon, viewport) if pokemon
    end
    @contents = Bitmap.new(PARTY_BOX_WIDTH, PARTY_BOX_HEIGHT)
    self.bitmap = @contents
    self.x = PARTY_BOX_X
    self.y = Graphics.height + PARTY_BOX_Y_OFFSET
    pbSetSystemFont(self.bitmap)
    refresh
  end

  def dispose
    Settings::MAX_PARTY_SIZE.times do |i|
      @pokemonsprites[i]&.dispose
    end
    @boxbitmap.dispose
    @contents.dispose
    super
  end

  def x=(value)
    super
    refresh
  end

  def y=(value)
    super
    refresh
  end

  def color=(value)
    super
    Settings::MAX_PARTY_SIZE.times do |i|
      if @pokemonsprites[i] && !@pokemonsprites[i].disposed?
        @pokemonsprites[i].color = pbSrcOver(@pokemonsprites[i].color, value)
      end
    end
  end

  def visible=(value)
    super
    Settings::MAX_PARTY_SIZE.times do |i|
      if @pokemonsprites[i] && !@pokemonsprites[i].disposed?
        @pokemonsprites[i].visible = value
      end
    end
  end

  def getPokemon(index)
    return @pokemonsprites[index]
  end

  def setPokemon(index, sprite)
    @pokemonsprites[index] = sprite
    @pokemonsprites.compact!
    refresh
  end

  def grabPokemon(index, arrow)
    sprite = @pokemonsprites[index]
    if sprite
      arrow.grab(sprite)
      @pokemonsprites.delete_at(index)
      refresh
    end
  end

  def deletePokemon(index)
    @pokemonsprites[index].dispose
    @pokemonsprites[index] = nil
    @pokemonsprites.compact!
    refresh
  end

  def refresh
    @contents.blt(0, 0, @boxbitmap.bitmap, Rect.new(0, 0, PARTY_BOX_WIDTH, PARTY_BOX_HEIGHT))
    pbDrawTextPositions(
      self.bitmap,
      [[_INTL("Atrás"), BACK_TEXT_X, BACK_TEXT_Y, :center, Color.new(248, 248, 248), Color.new(80, 80, 80), :outline]]
    )
    xvalues = []   # [18, 90, 18, 90, 18, 90]
    yvalues = []   # [2, 18, 66, 82, 130, 146]
    Settings::MAX_PARTY_SIZE.times do |i|
      xvalues.push(PARTY_ICON_X_START + (PARTY_ICON_X_SPACING * (i % 2)))
        yvalues.push(PARTY_ICON_Y_START + (PARTY_ICON_HEIGHT * (i % 2)) + (PARTY_ICON_Y_SPACING * (i / 2)))
      end
    @pokemonsprites.delete_if { |sprite| sprite&.disposed? }
    @pokemonsprites.each { |sprite| sprite&.refresh }
    Settings::MAX_PARTY_SIZE.times do |j|
      sprite = @pokemonsprites[j]
      next if sprite.nil? || sprite.disposed?
      sprite.viewport = self.viewport
      sprite.x = self.x + xvalues[j]
      sprite.y = self.y + yvalues[j]
      sprite.z = 1
    end
  end

  def update
    super
    Settings::MAX_PARTY_SIZE.times do |i|
      @pokemonsprites[i].update if @pokemonsprites[i] && !@pokemonsprites[i].disposed?
    end
  end
end

#===============================================================================
# Pokémon storage visuals
#===============================================================================
class PokemonStorageScene
  attr_reader :quickswap
  attr_accessor :sprites

  MARK_WIDTH  = 16
  MARK_HEIGHT = 16
  POKEMON_SPRITE_X = 90
  POKEMON_SPRITE_Y = 134
  BOX_PARTY_X = 182
  MARKING_BG_X = 292
  MARKING_BG_Y = 68
  MSG_WINDOW_X = 180
  MSG_WINDOW_Y = 0
  MSG_WINDOW_HEIGHT = 32

  ARROW_COORDS = {
    -1 => [314, -24],   # Box name
    -2 => [238, 278],   # Party Pokémon
    -3 => [414, 278],   # Close Box
    -4 => [314, -24],   # Move left
    -5 => [314, -24],    # Move right
    :default => { :x_start => 97, :x_spacing => 24, :y_start => 8, :y_spacing => 24}
  }

  PARTY_ARROW_START_X = 200
  PARTY_ARROW_X_SPACING = 72
  PARTY_ARROW_START_Y = 2
  PARTY_ARROW_HEIGHT = 16
  PARTY_ARROW_Y_SPACING = 64
  PARTY_ARROW_X_LAST = 236
  PARTY_ARROW_Y_LAST = 220
  
  SEARCH_BOX_MAX_LENGTH = 32

  SWITCH_BOX_X_OFFSET = 336

  MARKING_ARROWS_X_VALUES = [162, 191, 220, 162, 191, 220, 184, 184]
  MARKING_ARROWS_Y_VALUES = [24, 24, 24, 49, 49, 49, 77, 109]

  MARKING_OVERLAY_X_OFFSET = 336
  MARKING_OVERLAY_X_SPACING = 58
  MARKING_OVERLAY_Y_OFFSET = 106
  MARKING_OVERLAY_Y_SPACING = 50

  OK_TEXT_X = 402
  OK_TEXT_Y = 216
  CANCEL_TEXT_X = 402
  CANCEL_TEXT_Y = 280
  TEAM_TEXT_X = 270
  TEAM_TEXT_Y = 334
  EXIT_TEXT_X = 446
  EXIT_TEXT_Y = 334

  POKENAME_TEXT_X = 10
  POKENAME_TEXT_Y = 14
  GENDER_ICON_TEXT_X = 148
  GENDER_ICON_TEXT_Y = 14
  LEVEL_ICON_X = 6
  LEVEL_ICON_Y = 246
  LEVEL_NUMBER_X = 28
  LEVEL_NUMBER_Y = 240
  ABILITY_NAME_X = 86
  ABILITY_NAME_Y = 312
  ITEM_NAME_X = 86
  ITEM_NAME_Y = 348
  SHINY_ICON_X = 156
  SHINY_ICON_Y = 198
  TYPE_ICON_Y = 272
  TYPE_ICON_HEIGHT = 28
  # Cuando el Pokémon tiene un solo tipo, el icono se centra en la posición X_1.
  TYPE_ICON_X_1 = 52
  # Cuando tiene dos tipos, el primer icono se coloca en la posición X_2
  TYPE_ICON_X_2 = 18
  TYPE_ICON_X_SPACING = 70
  TYPE_ICON_RECT_WIDTH = 64
  MARKINGS_X = 70
  MARKINGS_Y = 240
  MARKING_RECT_WIDTH = 128
  MARKING_RECT_HEIGHT = 20

  def initialize
    @command = 1
  end

  def pbStartBox(screen, command)
    @screen = screen
    @storage = screen.storage
    @bgviewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @bgviewport.z = 99999
    @boxviewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @boxviewport.z = 99999
    @boxsidesviewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @boxsidesviewport.z = 99999
    @arrowviewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @arrowviewport.z = 99999
    @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = 99999
    @selection = 0
    @quickswap = false
    @sprites = {}
    @choseFromParty = false
    @command = command
    addBackgroundPlane(@sprites, "background", "Storage/bg", @bgviewport)
    @sprites["box"] = PokemonBoxSprite.new(@storage, @storage.currentBox, @boxviewport)
    @sprites["boxsides"] = IconSprite.new(0, 0, @boxsidesviewport)
    @sprites["boxsides"].setBitmap("Graphics/UI/Storage/overlay_main")
    @sprites["overlay"] = BitmapSprite.new(Graphics.width, Graphics.height, @boxsidesviewport)
    pbSetSystemFont(@sprites["overlay"].bitmap)
    @sprites["pokemon"] = AutoMosaicPokemonSprite.new(@boxsidesviewport)
    @sprites["pokemon"].setOffset(PictureOrigin::CENTER)
    @sprites["pokemon"].x = POKEMON_SPRITE_X
    @sprites["pokemon"].y = POKEMON_SPRITE_Y
    @sprites["boxparty"] = PokemonBoxPartySprite.new(@storage.party, @boxsidesviewport)
    if command != 2   # Drop down tab only on Deposit
      @sprites["boxparty"].x = BOX_PARTY_X
      @sprites["boxparty"].y = Graphics.height
    end
    @markingbitmap = AnimatedBitmap.new("Graphics/UI/Storage/markings")
    @sprites["markingbg"] = IconSprite.new(MARKING_BG_X, MARKING_BG_Y, @boxsidesviewport)
    @sprites["markingbg"].setBitmap("Graphics/UI/Storage/overlay_marking")
    @sprites["markingbg"].z = 10
    @sprites["markingbg"].visible = false
    @sprites["markingoverlay"] = BitmapSprite.new(Graphics.width, Graphics.height, @boxsidesviewport)
    @sprites["markingoverlay"].z = 11
    @sprites["markingoverlay"].visible = false
    pbSetSystemFont(@sprites["markingoverlay"].bitmap)
    @sprites["arrow"] = PokemonBoxArrow.new(@arrowviewport)
    @sprites["arrow"].z += 1
    if command == 2
      pbPartySetArrow(@sprites["arrow"], @selection)
      pbUpdateOverlay(@selection, @storage.party)
    else
      pbSetArrow(@sprites["arrow"], @selection)
      pbUpdateOverlay(@selection)
    end
    pbSetMosaic(@selection)
    pbSEPlay("PC access")
    pbFadeInAndShow(@sprites)
  end

  def pbCloseBox
    pbFadeOutAndHide(@sprites)
    pbDisposeSpriteHash(@sprites)
    @markingbitmap&.dispose
    @boxviewport.dispose
    @boxsidesviewport.dispose
    @arrowviewport.dispose
  end

  def pbDisplay(message)
    msgwindow = Window_UnformattedTextPokemon.newWithSize("", MSG_WINDOW_X, MSG_WINDOW_Y, Graphics.width - MSG_WINDOW_X, MSG_WINDOW_HEIGHT)
    msgwindow.viewport       = @viewport
    msgwindow.visible        = true
    msgwindow.letterbyletter = false
    msgwindow.resizeHeightToFit(message, Graphics.width - MSG_WINDOW_X)
    msgwindow.text = message
    pbBottomRight(msgwindow)
    loop do
      Graphics.update
      Input.update
      if Input.trigger?(Input::BACK) || Input.trigger?(Input::USE)
        break
      end
      msgwindow.update
      self.update
    end
    msgwindow.dispose
    Input.update
  end

  def pbShowCommands(message, commands, index = 0)
    ret = -1
    msgwindow = Window_UnformattedTextPokemon.newWithSize("", MSG_WINDOW_X, MSG_WINDOW_Y, Graphics.width - MSG_WINDOW_X, MSG_WINDOW_HEIGHT)
    msgwindow.viewport       = @viewport
    msgwindow.visible        = true
    msgwindow.letterbyletter = false
    msgwindow.text           = message
    msgwindow.resizeHeightToFit(message, Graphics.width - MSG_WINDOW_X)
    pbBottomRight(msgwindow)
    cmdwindow = Window_CommandPokemon.new(commands)
    cmdwindow.viewport = @viewport
    cmdwindow.visible  = true
    cmdwindow.resizeToFit(cmdwindow.commands)
    cmdwindow.height = Graphics.height - msgwindow.height if cmdwindow.height > Graphics.height - msgwindow.height
    pbBottomRight(cmdwindow)
    cmdwindow.y -= msgwindow.height
    cmdwindow.index = index
    loop do
      Graphics.update
      Input.update
      msgwindow.update
      cmdwindow.update
      if Input.trigger?(Input::BACK)
        ret = -1
        break
      elsif Input.trigger?(Input::USE)
        ret = cmdwindow.index
        break
      end
      self.update
    end
    msgwindow.dispose
    cmdwindow.dispose
    Input.update
    return ret
  end

  def pbSetArrow(arrow, selection)
    arrow_coords = ARROW_COORDS.fetch(selection, nil)
    if arrow_coords
      arrow.x = arrow_coords[0]
      arrow.y = arrow_coords[1]
    else
      default_coords = ARROW_COORDS[:default]
      arrow.x = (default_coords[:x_start] + (default_coords[:x_spacing] * (selection % PokemonBox::BOX_WIDTH))) * 2
      arrow.y = (default_coords[:y_start] + (default_coords[:y_spacing] * (selection / PokemonBox::BOX_WIDTH))) * 2
    end
  end

  def pbChangeSelection(key, selection)
    case key
    when Input::UP
      case selection
      when -1   # Box name
        selection = -2
      when -2   # Party
        selection = PokemonBox::BOX_SIZE - 1 - (PokemonBox::BOX_WIDTH * 2 / 3)   # 25
      when -3   # Close Box
        selection = PokemonBox::BOX_SIZE - (PokemonBox::BOX_WIDTH / 3)   # 28
      else
        selection -= PokemonBox::BOX_WIDTH
        selection = -1 if selection < 0
      end
    when Input::DOWN
      case selection
      when -1   # Box name
        selection = PokemonBox::BOX_WIDTH / 3   # 2
      when -2   # Party
        selection = -1
      when -3   # Close Box
        selection = -1
      else
        selection += PokemonBox::BOX_WIDTH
        if selection >= PokemonBox::BOX_SIZE
          if selection < PokemonBox::BOX_SIZE + (PokemonBox::BOX_WIDTH / 2)
            selection = -2   # Party
          else
            selection = -3   # Close Box
          end
        end
      end
    when Input::LEFT
      if selection == -1   # Box name
        selection = -4   # Move to previous box
      elsif selection == -2
        selection = -3
      elsif selection == -3
        selection = -2
      elsif (selection % PokemonBox::BOX_WIDTH) == 0   # Wrap around
        selection += PokemonBox::BOX_WIDTH - 1
      else
        selection -= 1
      end
    when Input::RIGHT
      if selection == -1   # Box name
        selection = -5   # Move to next box
      elsif selection == -2
        selection = -3
      elsif selection == -3
        selection = -2
      elsif (selection % PokemonBox::BOX_WIDTH) == PokemonBox::BOX_WIDTH - 1   # Wrap around
        selection -= PokemonBox::BOX_WIDTH - 1
      else
        selection += 1
      end
    end
    return selection
  end

  def pbPartySetArrow(arrow, selection)
    return if selection < 0
    xvalues = []   # [200, 272, 200, 272, 200, 272, 236]
    yvalues = []   # [2, 18, 66, 82, 130, 146, 220]
    Settings::MAX_PARTY_SIZE.times do |i|
      xvalues.push(PARTY_ARROW_START_X + (PARTY_ARROW_X_SPACING * (i % 2)))
      yvalues.push(PARTY_ARROW_START_Y + (PARTY_ARROW_HEIGHT * (i % 2)) + (PARTY_ARROW_Y_SPACING * (i / 2)))
    end
    xvalues.push(PARTY_ARROW_X_LAST)
    yvalues.push(PARTY_ARROW_Y_LAST)
    arrow.angle = 0
    arrow.mirror = false
    arrow.ox = 0
    arrow.oy = 0
    arrow.x = xvalues[selection]
    arrow.y = yvalues[selection]
  end

  def pbPartyChangeSelection(key, selection)
    case key
    when Input::LEFT
      selection -= 1
      selection = Settings::MAX_PARTY_SIZE if selection < 0
    when Input::RIGHT
      selection += 1
      selection = 0 if selection > Settings::MAX_PARTY_SIZE
    when Input::UP
      if selection == Settings::MAX_PARTY_SIZE
        selection = Settings::MAX_PARTY_SIZE - 1
      else
        selection -= 2
        selection = Settings::MAX_PARTY_SIZE if selection < 0
      end
    when Input::DOWN
      if selection == Settings::MAX_PARTY_SIZE
        selection = 0
      else
        selection += 2
        selection = Settings::MAX_PARTY_SIZE if selection > Settings::MAX_PARTY_SIZE
      end
    end
    return selection
  end

  def pbSelectBoxInternal(_party)
    selection = @selection
    pbSetArrow(@sprites["arrow"], selection)
    pbUpdateOverlay(selection)
    pbSetMosaic(selection)
    loop do
      Graphics.update
      Input.update
      key = -1
      key = Input::DOWN if Input.repeat?(Input::DOWN)
      key = Input::RIGHT if Input.repeat?(Input::RIGHT)
      key = Input::LEFT if Input.repeat?(Input::LEFT)
      key = Input::UP if Input.repeat?(Input::UP)
      if key >= 0
        pbPlayCursorSE
        selection = pbChangeSelection(key, selection)
        pbSetArrow(@sprites["arrow"], selection)
        case selection
        when -4
          nextbox = (@storage.currentBox + @storage.maxBoxes - 1) % @storage.maxBoxes
          pbSwitchBoxToLeft(nextbox)
          @storage.currentBox = nextbox
        when -5
          nextbox = (@storage.currentBox + 1) % @storage.maxBoxes
          pbSwitchBoxToRight(nextbox)
          @storage.currentBox = nextbox
        end
        selection = -1 if [-4, -5].include?(selection)
        pbUpdateOverlay(selection)
        pbSetMosaic(selection)
      end
      self.update
      if Input.trigger?(Input::JUMPUP)
        pbPlayCursorSE
        nextbox = (@storage.currentBox + @storage.maxBoxes - 1) % @storage.maxBoxes
        pbSwitchBoxToLeft(nextbox)
        @storage.currentBox = nextbox
        pbUpdateOverlay(selection)
        pbSetMosaic(selection)
      elsif Input.trigger?(Input::JUMPDOWN)
        pbPlayCursorSE
        nextbox = (@storage.currentBox + 1) % @storage.maxBoxes
        pbSwitchBoxToRight(nextbox)
        @storage.currentBox = nextbox
        pbUpdateOverlay(selection)
        pbSetMosaic(selection)
      elsif Input.trigger?(Input::SPECIAL)   # Jump to box name
        if selection != -1
          pbPlayCursorSE
          selection = -1
          pbSetArrow(@sprites["arrow"], selection)
          pbUpdateOverlay(selection)
          pbSetMosaic(selection)
        end
      elsif Input.trigger?(Input::AUX2)
        pbSearch
      elsif Input.trigger?(Input::ACTION) && @command == 0   # Organize only
        pbPlayDecisionSE
        pbSetQuickSwap(!@quickswap)
      elsif Input.trigger?(Input::BACK)
        @selection = selection
        return nil
      elsif Input.trigger?(Input::USE)
        @selection = selection
        if selection >= 0
          return [@storage.currentBox, selection]
        elsif selection == -1   # Box name
          return [-4, -1]
        elsif selection == -2   # Party Pokémon
          return [-2, -1]
        elsif selection == -3   # Close Box
          return [-3, -1]
        end
      end
    end
  end

  def pbSearch
    term = pbMessageFreeText(_INTL("¿Qué Pokémon buscar?"), "", false, SEARCH_BOX_MAX_LENGTH)
    return false if term.to_s.empty?
  
    search_results = {}
    @storage.maxBoxes.times do |box|
      next if @storage[box].nitems < 1
      @storage.maxPokemon(box).times do |i|
        pokemon = @storage[box, i]
        next unless pokemon && !pokemon.egg?
  
        if pokemon.species_data.name.downcase.include?(term.downcase)
          search_results[box] ||= []
          search_results[box] << i
        end
      end
    end
  
    return if search_results.empty?
  
    msg = _INTL("El Pokémon buscado está en las siguientes cajas. Elige a cual desplazarte.")
    commands, commands_keys = [], []
  
    search_results.keys.each do |box|
      commands << @storage[box].name
      commands_keys << box
    end
  
    chosen_box = pbShowCommands(msg, commands)
    return if chosen_box == -1 || !chosen_box
  
    key = commands_keys[chosen_box]
    pbJumpToBox(key)
    results = search_results[key]
  
    # Opacity change settings
    opacity_change = 15 # Amount to change opacity by per step
    total_steps = 7     # Number of steps for opacity change
    wait_time = 0.2     # Time to wait between each step
    max_pokemon = @storage.maxPokemon(key)
  
    # Decrease opacity in steps for Pokémon not in search results
    total_steps.times do
      max_pokemon.times do |i|
        pokemon = @storage[key, i]
        next unless pokemon
        if !results.include?(i)
          current_opacity = @sprites["box"].getPokemon(i).opacity
          @sprites["box"].getPokemon(i).opacity = [current_opacity - opacity_change, 0].max
        end
      end
      pbWait(wait_time)
    end
  
    pbWait(1.2)
  
    # Increase opacity in steps for Pokémon not in search results
    total_steps.times do
      max_pokemon.times do |i|
        pokemon = @storage[key, i]
        next unless pokemon
        if !results.include?(i)
          current_opacity = @sprites["box"].getPokemon(i).opacity
          @sprites["box"].getPokemon(i).opacity = [current_opacity + opacity_change, 255].min
        end
      end
      pbWait(wait_time)
    end
  end
  
  

  def pbSelectBox(party)
    return pbSelectBoxInternal(party) if @command == 1   # Withdraw
    ret = nil
    loop do
      ret = pbSelectBoxInternal(party) if !@choseFromParty
      if @choseFromParty || (ret && ret[0] == -2)   # Party Pokémon
        if !@choseFromParty
          pbShowPartyTab
          @selection = 0
        end
        ret = pbSelectPartyInternal(party, false)
        if ret < 0
          pbHidePartyTab
          @selection = -2
          @choseFromParty = false
        else
          @choseFromParty = true
          return [-1, ret]
        end
      else
        @choseFromParty = false
        return ret
      end
    end
  end

  def pbSelectPartyInternal(party, depositing)
    selection = @selection
    pbPartySetArrow(@sprites["arrow"], selection)
    pbUpdateOverlay(selection, party)
    pbSetMosaic(selection)
    lastsel = 1
    loop do
      Graphics.update
      Input.update
      key = -1
      key = Input::DOWN if Input.repeat?(Input::DOWN)
      key = Input::RIGHT if Input.repeat?(Input::RIGHT)
      key = Input::LEFT if Input.repeat?(Input::LEFT)
      key = Input::UP if Input.repeat?(Input::UP)
      if key >= 0
        pbPlayCursorSE
        newselection = pbPartyChangeSelection(key, selection)
        case newselection
        when -1
          return -1 if !depositing
        when -2
          selection = lastsel
        else
          selection = newselection
        end
        pbPartySetArrow(@sprites["arrow"], selection)
        lastsel = selection if selection > 0
        pbUpdateOverlay(selection, party)
        pbSetMosaic(selection)
      end
      self.update
      if Input.trigger?(Input::ACTION) && @command == 0   # Organize only
        pbPlayDecisionSE
        pbSetQuickSwap(!@quickswap)
      elsif Input.trigger?(Input::BACK)
        @selection = selection
        return -1
      elsif Input.trigger?(Input::USE)
        if selection >= 0 && selection < Settings::MAX_PARTY_SIZE
          @selection = selection
          return selection
        elsif selection == Settings::MAX_PARTY_SIZE   # Close Box
          @selection = selection
          return (depositing) ? -3 : -1
        end
      end
    end
  end

  def pbSelectParty(party)
    return pbSelectPartyInternal(party, true)
  end

  def pbChangeBackground(wp)
    duration = 0.2   # Time in seconds to fade out or fade in
    @sprites["box"].refreshSprites = false
    Graphics.update
    self.update
    # Fade old background to white
    timer_start = System.uptime
    loop do
      alpha = lerp(0, 255, duration, timer_start, System.uptime)
      @sprites["box"].color = Color.new(248, 248, 248, alpha)
      Graphics.update
      self.update
      break if alpha >= 255
    end
    # Fade in new background from white
    @sprites["box"].refreshBox = true
    @storage[@storage.currentBox].background = wp
    timer_start = System.uptime
    loop do
      alpha = lerp(255, 0, duration, timer_start, System.uptime)
      @sprites["box"].color = Color.new(248, 248, 248, alpha)
      Graphics.update
      self.update
      break if alpha <= 0
    end
    @sprites["box"].refreshSprites = true
    Input.update
  end

  def pbSwitchBoxToRight(new_box_number)
    start_x = @sprites["box"].x
    newbox = PokemonBoxSprite.new(@storage, new_box_number, @boxviewport)
    newbox.x = start_x + SWITCH_BOX_X_OFFSET
    timer_start = System.uptime
    loop do
      @sprites["box"].x = lerp(start_x, start_x - SWITCH_BOX_X_OFFSET, 0.25, timer_start, System.uptime)
      newbox.x = @sprites["box"].x + SWITCH_BOX_X_OFFSET
      self.update
      Graphics.update
      break if newbox.x == start_x
    end
    @sprites["box"].dispose
    @sprites["box"] = newbox
    Input.update
  end

  def pbSwitchBoxToLeft(new_box_number)
    start_x = @sprites["box"].x
    newbox = PokemonBoxSprite.new(@storage, new_box_number, @boxviewport)
    newbox.x = start_x - SWITCH_BOX_X_OFFSET
    timer_start = System.uptime
    loop do
      @sprites["box"].x = lerp(start_x, start_x + SWITCH_BOX_X_OFFSET, 0.25, timer_start, System.uptime)
      newbox.x = @sprites["box"].x - SWITCH_BOX_X_OFFSET
      self.update
      Graphics.update
      break if newbox.x == start_x
    end
    @sprites["box"].dispose
    @sprites["box"] = newbox
    Input.update
  end

  def pbJumpToBox(newbox)
    return if @storage.currentBox == newbox
    if newbox > @storage.currentBox
      pbSwitchBoxToRight(newbox)
    else
      pbSwitchBoxToLeft(newbox)
    end
    @storage.currentBox = newbox
  end

  def pbSetMosaic(selection)
    return if @screen.pbHeldPokemon
    return if @boxForMosaic == @storage.currentBox && @selectionForMosaic == selection
    @sprites["pokemon"].mosaic_duration = 0.25   # In seconds
    @boxForMosaic = @storage.currentBox
    @selectionForMosaic = selection
  end

  def pbSetQuickSwap(value)
    @quickswap = value
    @sprites["arrow"].quickswap = value
  end

  def pbShowPartyTab
    @sprites["arrow"].visible = false
    if !@screen.pbHeldPokemon
      pbUpdateOverlay(-1)
      pbSetMosaic(-1)
    end
    pbSEPlay("GUI storage show party panel")
    start_y = @sprites["boxparty"].y   # Graphics.height
    timer_start = System.uptime
    loop do
      @sprites["boxparty"].y = lerp(start_y, start_y - @sprites["boxparty"].height,
                                    0.4, timer_start, System.uptime)
      self.update
      Graphics.update
      break if @sprites["boxparty"].y == start_y - @sprites["boxparty"].height
    end
    Input.update
    @sprites["arrow"].visible = true
  end

  def pbHidePartyTab
    @sprites["arrow"].visible = false
    if !@screen.pbHeldPokemon
      pbUpdateOverlay(-1)
      pbSetMosaic(-1)
    end
    pbSEPlay("GUI storage hide party panel")
    start_y = @sprites["boxparty"].y   # Graphics.height - @sprites["boxparty"].height
    timer_start = System.uptime
    loop do
      @sprites["boxparty"].y = lerp(start_y, start_y + @sprites["boxparty"].height,
                                    0.4, timer_start, System.uptime)
      self.update
      Graphics.update
      break if @sprites["boxparty"].y == start_y + @sprites["boxparty"].height
    end
    Input.update
    @sprites["arrow"].visible = true
  end

  def pbHold(selected)
    pbSEPlay("GUI storage pick up")
    if selected[0] == -1
      @sprites["boxparty"].grabPokemon(selected[1], @sprites["arrow"])
    else
      @sprites["box"].grabPokemon(selected[1], @sprites["arrow"])
    end
    @grabber.carrying = true
    @grabber.setPivot(selected[1])
    @grabber.do_with(selected[1])
    while @sprites["arrow"].grabbing?
      Graphics.update
      Input.update
      self.update
    end
  end

  def pbSwap(selected, _heldpoke)
    pbSEPlay("GUI storage pick up")
    heldpokesprite = @sprites["arrow"].heldPokemon
    boxpokesprite = nil
    if selected[0] == -1
      boxpokesprite = @sprites["boxparty"].getPokemon(selected[1])
    else
      boxpokesprite = @sprites["box"].getPokemon(selected[1])
    end
    if selected[0] == -1
      @sprites["boxparty"].setPokemon(selected[1], heldpokesprite)
    else
      @sprites["box"].setPokemon(selected[1], heldpokesprite)
    end
    @sprites["arrow"].setSprite(boxpokesprite)
    @sprites["pokemon"].mosaic_duration = 0.25   # In seconds
    @boxForMosaic = @storage.currentBox
    @selectionForMosaic = selected[1]
  end

  def pbPlace(selected, _heldpoke)
    pbSEPlay("GUI storage put down")
    heldpokesprite = @sprites["arrow"].heldPokemon
    @sprites["arrow"].place
    while @sprites["arrow"].placing?
      Graphics.update
      Input.update
      self.update
    end
    if selected[0] == -1
      @sprites["boxparty"].setPokemon(selected[1], heldpokesprite)
    else
      @sprites["box"].setPokemon(selected[1], heldpokesprite)
    end
    @grabber.carrying = false
    @boxForMosaic = @storage.currentBox
    @selectionForMosaic = selected[1]
  end

  def pbWithdraw(selected, heldpoke, partyindex)
    pbHold(selected) if !heldpoke
    pbShowPartyTab
    pbPartySetArrow(@sprites["arrow"], partyindex)
    pbPlace([-1, partyindex], heldpoke)
    pbHidePartyTab
  end

  def pbStore(selected, heldpoke, destbox, firstfree)
    if heldpoke
      if destbox == @storage.currentBox
        heldpokesprite = @sprites["arrow"].heldPokemon
        @sprites["box"].setPokemon(firstfree, heldpokesprite)
        @sprites["arrow"].setSprite(nil)
      else
        @sprites["arrow"].deleteSprite
      end
    else
      sprite = @sprites["boxparty"].getPokemon(selected[1])
      if destbox == @storage.currentBox
        @sprites["box"].setPokemon(firstfree, sprite)
        @sprites["boxparty"].setPokemon(selected[1], nil)
      else
        @sprites["boxparty"].deletePokemon(selected[1])
      end
    end
  end

  def pbRelease(selected, heldpoke)
    box = selected[0]
    index = selected[1]
    if heldpoke
      sprite = @sprites["arrow"].heldPokemon
    elsif box == -1
      sprite = @sprites["boxparty"].getPokemon(index)
    else
      sprite = @sprites["box"].getPokemon(index)
    end
    if sprite
      sprite.release
      while sprite.releasing?
        Graphics.update
        sprite.update
        self.update
      end
      if heldpoke
        @sprites["arrow"].deleteSprite
      end
    end
  end

  def pbChooseBox(msg)
    commands = []
    @storage.maxBoxes.times do |i|
      box = @storage[i]
      if box
        commands.push(_INTL("{1} ({2}/{3})", box.name, box.nitems, box.length))
      end
    end
    return pbShowCommands(msg, commands, @storage.currentBox)
  end

  def pbChooseBoxWithSpace(msg, min_space = 1)
    commands = []
    box_num = []
    source_box = @grabber&.source_box
    
    # Add source box first if it has space
    if source_box && source_box >= 0 && source_box < @storage.maxBoxes
      box = @storage[source_box]
      if box && box.length - box.nitems >= min_space
        box_num << source_box
        commands.push(_INTL("{1} ({2}/{3})", box.name, box.nitems, box.length))
      end
    end
    
    # Add other boxes with space
    @storage.maxBoxes.times do |i|
      box = @storage[i]
      if box
        next if box.length - box.nitems < min_space
        next if i == source_box  # Skip if already added as source box
        box_num << i
        commands.push(_INTL("{1} ({2}/{3})", box.name, box.nitems, box.length))
      end
    end
    
    chosen_box = pbShowCommands(msg, commands, 0)  # Default to first option (source box if available)
    return chosen_box if chosen_box == -1
    return box_num[chosen_box]
  end

  def pbBoxName(helptext, minchars, maxchars)
    oldsprites = pbFadeOutAndHide(@sprites)
    ret = pbEnterBoxName(helptext, minchars, maxchars)
    @storage[@storage.currentBox].name = ret if ret.length > 0
    @sprites["box"].refreshBox = true
    pbRefresh
    pbFadeInAndShow(@sprites, oldsprites)
  end

  def pbChooseItem(bag)
    ret = nil
    pbFadeOutIn do
      scene = PokemonBag_Scene.new
      screen = PokemonBagScreen.new(scene, bag)
      ret = screen.pbChooseItemScreen(proc { |item| GameData::Item.get(item).can_hold? })
    end
    return ret
  end

  def pbSummary(selected, heldpoke)
    oldsprites = pbFadeOutAndHide(@sprites)
    scene = PokemonSummary_Scene.new
    screen = PokemonSummaryScreen.new(scene)
    if heldpoke
      screen.pbStartScreen([heldpoke], 0)
    elsif selected[0] == -1
      @selection = screen.pbStartScreen(@storage.party, selected[1])
      pbPartySetArrow(@sprites["arrow"], @selection)
      pbUpdateOverlay(@selection, @storage.party)
    else
      @selection = screen.pbStartScreen(@storage.boxes[selected[0]], selected[1])
      pbSetArrow(@sprites["arrow"], @selection)
      pbUpdateOverlay(@selection)
    end
    pbFadeInAndShow(@sprites, oldsprites)
  end

  def pbMarkingSetArrow(arrow, selection)
    if selection >= 0
      xvalues = MARKING_ARROWS_X_VALUES
      yvalues = MARKING_ARROWS_Y_VALUES
      arrow.angle = 0
      arrow.mirror = false
      arrow.ox = 0
      arrow.oy = 0
      arrow.x = xvalues[selection] * 2
      arrow.y = yvalues[selection] * 2
    end
  end

  def pbMarkingChangeSelection(key, selection)
    case key
    when Input::LEFT
      if selection < 6
        selection -= 1
        selection += 3 if selection % 3 == 2
      end
    when Input::RIGHT
      if selection < 6
        selection += 1
        selection -= 3 if selection % 3 == 0
      end
    when Input::UP
      if selection == 7
        selection = 6
      elsif selection == 6
        selection = 4
      elsif selection < 3
        selection = 7
      else
        selection -= 3
      end
    when Input::DOWN
      if selection == 7
        selection = 1
      elsif selection == 6
        selection = 7
      elsif selection >= 3
        selection = 6
      else
        selection += 3
      end
    end
    return selection
  end

  def pbMark(selected, heldpoke)
    @sprites["markingbg"].visible      = true
    @sprites["markingoverlay"].visible = true
    msg = _INTL("Marca a tu Pokémon.")
    msgwindow = Window_UnformattedTextPokemon.newWithSize("", MSG_WINDOW_X, 0, Graphics.width - MSG_WINDOW_X, MSG_WINDOW_Y)
    msgwindow.viewport       = @viewport
    msgwindow.visible        = true
    msgwindow.letterbyletter = false
    msgwindow.text           = msg
    msgwindow.resizeHeightToFit(msg, Graphics.width - MSG_WINDOW_X)
    pbBottomRight(msgwindow)
    base   = Color.new(248, 248, 248)
    shadow = Color.new(80, 80, 80)
    pokemon = heldpoke
    if heldpoke
      pokemon = heldpoke
    elsif selected[0] == -1
      pokemon = @storage.party[selected[1]]
    else
      pokemon = @storage.boxes[selected[0]][selected[1]]
    end
    markings = pokemon.markings.clone
    mark_variants = @markingbitmap.bitmap.height / MARK_HEIGHT
    index = 0
    redraw = true
    markrect = Rect.new(0, 0, MARK_WIDTH, MARK_HEIGHT)
    loop do
      # Redraw the markings and text
      if redraw
        @sprites["markingoverlay"].bitmap.clear
        (@markingbitmap.bitmap.width / MARK_WIDTH).times do |i|
          markrect.x = i * MARK_WIDTH
          markrect.y = [(markings[i] || 0), mark_variants - 1].min * MARK_HEIGHT
          @sprites["markingoverlay"].bitmap.blt(MARKING_OVERLAY_X_OFFSET + (MARKING_OVERLAY_X_SPACING * (i % 3)), MARKING_OVERLAY_Y_OFFSET + (MARKING_OVERLAY_Y_SPACING * (i / 3)),
                                                @markingbitmap.bitmap, markrect)
        end
        textpos = [
          [_INTL("OK"), OK_TEXT_X, OK_TEXT_Y, :center, base, shadow, :outline],
          [_INTL("Cancelar"), CANCEL_TEXT_X, CANCEL_TEXT_Y, :center, base, shadow, :outline]
        ]
        pbDrawTextPositions(@sprites["markingoverlay"].bitmap, textpos)
        pbMarkingSetArrow(@sprites["arrow"], index)
        redraw = false
      end
      Graphics.update
      Input.update
      key = -1
      key = Input::DOWN if Input.repeat?(Input::DOWN)
      key = Input::RIGHT if Input.repeat?(Input::RIGHT)
      key = Input::LEFT if Input.repeat?(Input::LEFT)
      key = Input::UP if Input.repeat?(Input::UP)
      if key >= 0
        oldindex = index
        index = pbMarkingChangeSelection(key, index)
        pbPlayCursorSE if index != oldindex
        pbMarkingSetArrow(@sprites["arrow"], index)
      end
      self.update
      if Input.trigger?(Input::BACK)
        pbPlayCancelSE
        break
      elsif Input.trigger?(Input::USE)
        pbPlayDecisionSE
        case index
        when 6   # OK
          pokemon.markings = markings
          break
        when 7   # Cancel
          break
        else
          markings[index] = ((markings[index] || 0) + 1) % mark_variants
          redraw = true
        end
      end
    end
    @sprites["markingbg"].visible      = false
    @sprites["markingoverlay"].visible = false
    msgwindow.dispose
  end

  def pbRefresh
    @sprites["box"].refresh
    @sprites["boxparty"].refresh
  end

  def pbHardRefresh
    oldPartyY = @sprites["boxparty"].y
    @sprites["box"].dispose
    @sprites["box"] = PokemonBoxSprite.new(@storage, @storage.currentBox, @boxviewport)
    @sprites["boxparty"].dispose
    @sprites["boxparty"] = PokemonBoxPartySprite.new(@storage.party, @boxsidesviewport)
    @sprites["boxparty"].y = oldPartyY
  end

  def drawMarkings(bitmap, x, y, _width, _height, markings)
    mark_variants = @markingbitmap.bitmap.height / MARK_HEIGHT
    markrect = Rect.new(0, 0, MARK_WIDTH, MARK_HEIGHT)
    (@markingbitmap.bitmap.width / MARK_WIDTH).times do |i|
      markrect.x = i * MARK_WIDTH
      markrect.y = [(markings[i] || 0), mark_variants - 1].min * MARK_HEIGHT
      bitmap.blt(x + (i * MARK_WIDTH), y, @markingbitmap.bitmap, markrect)
    end
  end

  def pbUpdateOverlay(selection, party = nil)
    overlay = @sprites["overlay"].bitmap
    overlay.clear
    buttonbase = Color.new(248, 248, 248)
    buttonshadow = Color.new(80, 80, 80)
    pbDrawTextPositions(
      overlay,
      [[_INTL("Equipo: {1}", (@storage.party.length rescue 0)), TEAM_TEXT_X, TEAM_TEXT_Y, :center, buttonbase, buttonshadow, :outline],
       [_INTL("Salir"), EXIT_TEXT_X, EXIT_TEXT_Y, :center, buttonbase, buttonshadow, :outline]]
    )
    pokemon = nil
    if @screen.pbHeldPokemon
      pokemon = @screen.pbHeldPokemon
    elsif selection >= 0
      pokemon = (party) ? party[selection] : @storage[@storage.currentBox, selection]
    end
    if !pokemon
      @sprites["pokemon"].visible = false
      return
    end
    @sprites["pokemon"].visible = true
    base   = Color.new(88, 88, 80)
    shadow = Color.new(168, 184, 184)
    nonbase   = Color.new(208, 208, 208)
    nonshadow = Color.new(224, 224, 224)
    pokename = pokemon.name
    textstrings = [
      [pokename, POKENAME_TEXT_X, POKENAME_TEXT_Y, :left, base, shadow]
    ]
    if !pokemon.egg?
      imagepos = []
      if pokemon.male?
        textstrings.push([_INTL("♂"), GENDER_ICON_TEXT_X, GENDER_ICON_TEXT_Y, :left, Color.new(24, 112, 216), Color.new(136, 168, 208)])
      elsif pokemon.female?
        textstrings.push([_INTL("♀"), GENDER_ICON_TEXT_X, GENDER_ICON_TEXT_Y, :left, Color.new(248, 56, 32), Color.new(224, 152, 144)])
      end
      imagepos.push([_INTL("Graphics/UI/Storage/overlay_lv"), LEVEL_ICON_X, LEVEL_ICON_Y])
      textstrings.push([pokemon.level.to_s, LEVEL_NUMBER_X, LEVEL_NUMBER_Y, :left, base, shadow])
      if pokemon.ability
        textstrings.push([pokemon.ability.name, ABILITY_NAME_X, ABILITY_NAME_Y, :center, base, shadow])
      else
        textstrings.push([_INTL("Sin habilidad"), ABILITY_NAME_X, ABILITY_NAME_Y, :center, nonbase, nonshadow])
      end
      if pokemon.item
        textstrings.push([pokemon.item.name, ITEM_NAME_X, ITEM_NAME_Y, :center, base, shadow])
      else
        textstrings.push([_INTL("Sin objeto"), ITEM_NAME_X, ITEM_NAME_Y, :center, nonbase, nonshadow])
      end
      imagepos.push(["Graphics/UI/shiny", SHINY_ICON_X, SHINY_ICON_Y]) if pokemon.shiny?
      typebitmap = AnimatedBitmap.new(_INTL("Graphics/UI/types"))
      pokemon.types.each_with_index do |type, i|
        type_number = GameData::Type.get(type).icon_position
        type_rect = Rect.new(0, type_number * TYPE_ICON_HEIGHT, TYPE_ICON_RECT_WIDTH, TYPE_ICON_HEIGHT)
        type_x = (pokemon.types.length == 1) ? TYPE_ICON_X_1 : TYPE_ICON_X_2 + (TYPE_ICON_X_SPACING * i)
        overlay.blt(type_x, TYPE_ICON_Y, typebitmap.bitmap, type_rect)
      end
      drawMarkings(overlay, MARKINGS_X, MARKINGS_Y, MARKING_RECT_WIDTH, MARKING_RECT_HEIGHT, pokemon.markings)
      pbDrawImagePositions(overlay, imagepos)
    end
    pbDrawTextPositions(overlay, textstrings)
    @sprites["pokemon"].setPokemonBitmap(pokemon)
    # Set grey state for animated sprite if Pokemon is fainted
    @sprites["pokemon"].make_grey_if_fainted = pokemon.fainted?
  end

  def update
    pbUpdateSpriteHash(@sprites)
  end
end

#===============================================================================
# Pokémon storage mechanics
#===============================================================================
class PokemonStorageScreen
  attr_reader :scene
  attr_reader :storage
  attr_accessor :heldpkmn

  BOX_NAME_MIN_CHARS = 0
  BOX_NAME_MAX_CHARS = 16

  def initialize(scene, storage)
    @scene = scene
    @storage = storage
    @pbHeldPokemon = nil
  end

  def organise_commands(selected, pokemon)
    commands = []
    cmdMove     = -1
    cmdSummary  = -1
    cmdWithdraw = -1
    cmdItem     = -1
    cmdMark     = -1
    cmdPokedex  = -1
    cmdRelease  = -1
    cmdDebug    = -1
    heldpoke = pbHeldPokemon
    if heldpoke
      helptext = _INTL("Has seleccionado a {1}.", heldpoke.name)
      commands[cmdMove = commands.length] = (pokemon) ? _INTL("Cambiar") : _INTL("Dejar")
    elsif pokemon
      helptext = _INTL("Has seleccionado a {1}.", pokemon.name)
      commands[cmdMove = commands.length] = _INTL("Mover")
    end
    commands[cmdSummary = commands.length]  = _INTL("Datos")
    commands[cmdWithdraw = commands.length] = (selected[0] == -1) ? _INTL("Guardar") : _INTL("Sacar")
    commands[cmdItem = commands.length]     = _INTL("Objeto")
    commands[cmdMark = commands.length]     = _INTL("Marcas")
    poke_for_dex = (pokemon) ? pokemon : @heldpkmn
    commands[cmdPokedex = commands.length]  = _INTL("Pokédex") if $player.has_pokedex && poke_for_dex && !poke_for_dex.egg? && $player.pokedex.species_in_unlocked_dex?(poke_for_dex.species)
    commands[cmdRelease = commands.length]  = _INTL("Liberar")
    commands[cmdDebug = commands.length]    = _INTL("Debug") if $DEBUG
    commands[commands.length]               = _INTL("Cancelar")
    command = pbShowCommands(helptext, commands)
    if cmdMove >= 0 && command == cmdMove   # Move/Shift/Place
      if @heldpkmn
        (pokemon) ? pbSwap(selected) : pbPlace(selected)
      else
        pbHold(selected)
      end
    elsif cmdSummary >= 0 && command == cmdSummary   # Summary
      pbSummary(selected, @heldpkmn)
    elsif cmdWithdraw >= 0 && command == cmdWithdraw   # Store/Withdraw
      (selected[0] == -1) ? pbStore(selected, @heldpkmn) : pbWithdraw(selected, @heldpkmn)
    elsif cmdItem >= 0 && command == cmdItem   # Item
      pbItem(selected, @heldpkmn)
    elsif cmdMark >= 0 && command == cmdMark   # Mark
      pbMark(selected, @heldpkmn)
    elsif cmdPokedex >= 0 && command == cmdPokedex   # Pokédex
      openPokedexOnPokemon(pokemon.species, pokemon.gender, pokemon.form) if pokemon
      openPokedexOnPokemon(@heldpkmn.species, @heldpkmn.gender, @heldpkmn.form) if !pokemon && @heldpkmn
    elsif cmdRelease >= 0 && command == cmdRelease   # Release
      pbRelease(selected, @heldpkmn)
    elsif cmdDebug >= 0 && command == cmdDebug   # Debug
      pbPokemonDebug((@heldpkmn) ? @heldpkmn : pokemon, selected, heldpoke)
    end
  end

  def pbStartScreen(command)
    $game_temp.in_storage = true
    @heldpkmn = nil
    case command
    when 0   # Organise
      @scene.pbStartBox(self, command)
      loop do
        selected = @scene.pbSelectBox(@storage.party)
        if selected.nil?
          if pbHeldPokemon
            pbDisplay(_INTL("¡Llevas un Pokémon!"))
            next
          end
          next if pbConfirm(_INTL("¿Continuar operaciones?"))
          break
        elsif selected[0] == -3   # Close box
          if pbHeldPokemon
            pbDisplay(_INTL("¡Llevas un Pokémon!"))
            next
          end
          if pbConfirm(_INTL("¿Salir del PC?"))
            pbSEPlay("PC close")
            break
          end
          next
        elsif selected[0] == -4   # Box name
          pbBoxCommands
        else
          pokemon = @storage[selected[0], selected[1]]
          heldpoke = pbHeldPokemon
          next if !pokemon && !heldpoke
          if @scene.quickswap
            if @heldpkmn
              (pokemon) ? pbSwap(selected) : pbPlace(selected)
            else
              pbHold(selected)
            end
          else
            organise_commands(selected, pokemon)
          end
        end
      end
      
      @scene.pbCloseBox
    when 1   # Withdraw
      @scene.pbStartBox(self, command)
      loop do
        selected = @scene.pbSelectBox(@storage.party)
        if selected.nil?
          next if pbConfirm(_INTL("¿Continuar con las operaciones?"))
          break
        else
          case selected[0]
          when -2   # Party Pokémon
            pbDisplay(_INTL("¿Cuál quieres coger?"))
            next
          when -3   # Close box
            if pbConfirm(_INTL("¿Salir del PC?"))
              pbSEPlay("PC close")
              break
            end
            next
          when -4   # Box name
            pbBoxCommands
            next
          end
          pokemon = @storage[selected[0], selected[1]]
          next if !pokemon
          command = pbShowCommands(_INTL("Has seleccionado a {1}.", pokemon.name),
                                   [_INTL("Sacar"),
                                    _INTL("Datos"),
                                    _INTL("Marcas"),
                                    _INTL("Liberar"),
                                    _INTL("Cancelar")])
          case command
          when 0 then pbWithdraw(selected, nil)
          when 1 then pbSummary(selected, nil)
          when 2 then pbMark(selected, nil)
          when 3 then pbRelease(selected, nil)
          end
        end
      end
      @scene.pbCloseBox
    when 2   # Deposit
      @scene.pbStartBox(self, command)
      loop do
        selected = @scene.pbSelectParty(@storage.party)
        if selected == -3   # Close box
          if pbConfirm(_INTL("¿Salir del PC?"))
            pbSEPlay("PC close")
            break
          end
          next
        elsif selected < 0
          next if pbConfirm(_INTL("¿Continuar con las operaciones?"))
          break
        else
          pokemon = @storage[-1, selected]
          next if !pokemon
          command = pbShowCommands(_INTL("Has seleccionado a {1}.", pokemon.name),
                                   [_INTL("Dejar"),
                                    _INTL("Datos"),
                                    _INTL("Marcas"),
                                    _INTL("Liberar"),
                                    _INTL("Cancelar")])
          case command
          when 0 then pbStore([-1, selected], nil)
          when 1 then pbSummary([-1, selected], nil)
          when 2 then pbMark([-1, selected], nil)
          when 3 then pbRelease([-1, selected], nil)
          end
        end
      end
      @scene.pbCloseBox
    when 3
      @scene.pbStartBox(self, command)
      @scene.pbCloseBox
    end
    $game_temp.in_storage = false
  end

  # For debug purposes.
  def pbUpdate
    @scene.update
  end

  # For debug purposes.
  def pbHardRefresh
    @scene.pbHardRefresh
  end

  # For debug purposes.
  def pbRefreshSingle(i)
    @scene.pbUpdateOverlay(i[1], (i[0] == -1) ? @storage.party : nil)
    @scene.pbHardRefresh
  end

  def pbDisplay(message)
    @scene.pbDisplay(message)
  end

  def pbConfirm(str)
    return pbShowCommands(str, [_INTL("Sí"), _INTL("No")]) == 0
  end

  def pbShowCommands(msg, commands, index = 0)
    return @scene.pbShowCommands(msg, commands, index)
  end

  def pbAble?(pokemon)
    pokemon && !pokemon.egg? && pokemon.hp > 0
  end

  def pbAbleCount
    count = 0
    @storage.party.each do |p|
      count += 1 if pbAble?(p)
    end
    return count
  end

  def pbHeldPokemon
    return @heldpkmn
  end

  def pbWithdraw(selected, heldpoke)
    box = selected[0]
    index = selected[1]
    raise _INTL("No se puede sacar del equipo...") if box == -1
    if @storage.party_full?
      pbDisplay(_INTL("¡Tu equipo está lleno!"))
      return false
    end
    @scene.pbWithdraw(selected, heldpoke, @storage.party.length)
    if heldpoke
      @storage.pbMoveCaughtToParty(heldpoke)
      @heldpkmn = nil
    else
      @storage.pbMove(-1, -1, box, index)
    end
    @scene.pbRefresh
    return true
  end

  def pbStore(selected, heldpoke)
    box = selected[0]
    index = selected[1]
    raise _INTL("No se puede depositar...") if box != -1
    if pbAbleCount <= 1 && pbAble?(@storage[box, index]) && !heldpoke
      pbPlayBuzzerSE
      pbDisplay(_INTL("¡Es tu último Pokémon!"))
    elsif heldpoke&.mail
      pbDisplay(_INTL("Debes retirar la carta que lleva."))
    elsif !heldpoke && @storage[box, index].mail
      pbDisplay(_INTL("Debes retirar la carta que lleva."))
    elsif heldpoke&.cannot_store
      pbDisplay(_INTL("¡{1} no quiere quedarse en el PC!", heldpoke.name))
    elsif !heldpoke && @storage[box, index].cannot_store
      pbDisplay(_INTL("¡{1} no quiere quedarse en el PC!", @storage[box, index].name))
    else
      loop do
        destbox = @scene.pbChooseBox(_INTL("¿Dejar en qué caja?"))
        if destbox >= 0
          firstfree = @storage.pbFirstFreePos(destbox)
          if firstfree < 0
            pbDisplay(_INTL("La Caja está llena."))
            next
          end
          if heldpoke || selected[0] == -1
            p = (heldpoke) ? heldpoke : @storage[-1, index]
            if Settings::HEAL_STORED_POKEMON
              old_ready_evo = p.ready_to_evolve
              p.heal
              p.ready_to_evolve = old_ready_evo
            end
          end
          @scene.pbStore(selected, heldpoke, destbox, firstfree)
          if heldpoke
            @storage.pbMoveCaughtToBox(heldpoke, destbox)
            @heldpkmn = nil
            @scene&.grabber&.carrying = false
          else
            @storage.pbMove(destbox, -1, -1, index)
          end
        end
        break
      end
      @scene.pbRefresh
    end
  end

  def pbHold(selected)
    box = selected[0]
    index = selected[1]
    if box == -1 && pbAble?(@storage[box, index]) && pbAbleCount <= 1
      pbPlayBuzzerSE
      pbDisplay(_INTL("¡Es tu último Pokémon!"))
      return
    end
    @scene.pbHold(selected)
    @heldpkmn = @storage[box, index]
    @storage.pbDelete(box, index)
    @scene.pbRefresh
  end

  def pbPlace(selected)
    box = selected[0]
    index = selected[1]
    if @storage[box, index]
      raise _INTL("La posición {1},{2} no está vacía...", box, index)
    elsif box != -1
      if index >= @storage.maxPokemon(box)
        pbDisplay("No se puede dejar ahí.")
        return
      elsif @heldpkmn.mail
        pbDisplay("Debes retirar la carta que lleva.")
        return
      elsif @heldpkmn.cannot_store
        pbDisplay(_INTL("¡{1} no quiere quedarse en el PC!", @heldpkmn.name))
        return
      end
    end
    if Settings::HEAL_STORED_POKEMON && box >= 0
      old_ready_evo = @heldpkmn.ready_to_evolve
      @heldpkmn.heal
      @heldpkmn.ready_to_evolve = old_ready_evo
    end
    @scene.pbPlace(selected, @heldpkmn)
    @storage[box, index] = @heldpkmn
    @storage.party.compact! if box == -1
    @scene.pbRefresh
    @heldpkmn = nil
    @scene.grabber.clear
  end

  def pbSwap(selected)
    box = selected[0]
    index = selected[1]
    if !@storage[box, index]
      raise _INTL("La posición {1},{2} está vacía...", box, index)
    end
    if @heldpkmn.cannot_store && box != -1
      pbPlayBuzzerSE
      pbDisplay(_INTL("¡{1} no quiere quedarse en el PC!", @heldpkmn.name))
      return false
    elsif box == -1 && pbAble?(@storage[box, index]) && pbAbleCount <= 1 && !pbAble?(@heldpkmn)
      pbPlayBuzzerSE
      pbDisplay(_INTL("¡Es tu último Pokémon!"))
      return false
    end
    if box != -1 && @heldpkmn.mail
      pbDisplay("Debes retirar la carta que lleva.")
      return false
    end
    if Settings::HEAL_STORED_POKEMON && box >= 0
      old_ready_evo = @heldpkmn.ready_to_evolve
      @heldpkmn.heal
      @heldpkmn.ready_to_evolve = old_ready_evo
    end
    @scene.pbSwap(selected, @heldpkmn)
    tmp = @storage[box, index]
    @storage[box, index] = @heldpkmn
    @heldpkmn = tmp
    @scene.pbRefresh
    return true
  end

  def pbRelease(selected, heldpoke)
    box = selected[0]
    index = selected[1]
    pokemon = (heldpoke) ? heldpoke : @storage[box, index]
    return if !pokemon
    if pokemon.egg?
      pbDisplay(_INTL("No puedes liberar un Huevo."))
      return false
    elsif pokemon.mail
      pbDisplay(_INTL("Debes retirar la carta que lleva."))
      return false
    elsif pokemon.cannot_release
      pbDisplay(_INTL("¡{1} no quiere separarse de ti!", pokemon.name))
      return false
    end
    if box == -1 && pbAbleCount <= 1 && pbAble?(pokemon) && !heldpoke
      pbPlayBuzzerSE
      pbDisplay(_INTL("¡Es tu último Pokémon!"))
      return
    end
    command = pbShowCommands(_INTL("¿Liberar este Pokémon?"), [_INTL("No"), _INTL("Sí")])
    if command == 1
      pkmnname = pokemon.name
      $bag.add(pokemon.item_id) if pokemon.hasItem?
      @scene.pbRelease(selected, heldpoke)
      if heldpoke
        @heldpkmn = nil
      else
        @storage.pbDelete(box, index)
      end
      @scene.pbRefresh
      pbDisplay(_INTL("Has liberado a {1}.", pkmnname))
      pbDisplay(_INTL("¡Adiós, {1}!", pkmnname))
      @scene.pbRefresh
    end
    return
  end

  def pbChooseMove(pkmn, helptext, index = 0)
    movenames = []
    pkmn.moves.each do |i|
      if i.total_pp <= 0
        movenames.push(_INTL("{1} (PP: ---)", i.name))
      else
        movenames.push(_INTL("{1} (PP: {2}/{3})", i.name, i.pp, i.total_pp))
      end
    end
    return @scene.pbShowCommands(helptext, movenames, index)
  end

  def pbSummary(selected, heldpoke)
    @scene.pbSummary(selected, heldpoke)
  end

  def pbMark(selected, heldpoke)
    @scene.pbMark(selected, heldpoke)
  end

  def pbItem(selected, heldpoke)
    box = selected[0]
    index = selected[1]
    pokemon = (heldpoke) ? heldpoke : @storage[box, index]
    if pokemon.egg?
      pbDisplay(_INTL("Los Huevos no pueden llevar objetos."))
      return
    elsif pokemon.mail
      pbDisplay(_INTL("Debes retirar la carta que lleva."))
      return
    end
    if pokemon.item
      itemname = pokemon.item.portion_name
      if pbConfirm(_INTL("¿Coger {1}?", itemname))
        if $bag.add(pokemon.item)
          pbDisplay(_INTL("Has cogido {1}.", itemname))
          pokemon.item = nil
          @scene.pbHardRefresh
        else
          pbDisplay(_INTL("No se puede guardar {1}.", itemname))
        end
      end
    else
      item = scene.pbChooseItem($bag)
      if item
        itemname = GameData::Item.get(item).name
        pokemon.item = item
        $bag.remove(item)
        pbDisplay(_INTL("Has equipado {1}.", itemname))
        @scene.pbHardRefresh
      end
    end
  end

  def pbBoxCommands
    commands = [
      _INTL("Saltar"),
      _INTL("Fondo"),
      _INTL("Nombre"),
      _INTL("Liberar Caja"),
      # _INTL("Ordenar Caja"),
      _INTL("Cancelar")
    ]
    command = pbShowCommands(_INTL("¿Qué hacer con?"), commands)
    case command
    when 0
      destbox = @scene.pbChooseBox(_INTL("¿Saltar a qué Caja?"))
      @scene.pbJumpToBox(destbox) if destbox >= 0
    when 1
      papers = @storage.availableWallpapers
      index = 0
      papers[1].length.times do |i|
        if papers[1][i] == @storage[@storage.currentBox].background
          index = i
          break
        end
      end
      wpaper = pbShowCommands(_INTL("Elige un fondo."), papers[0], index)
      @scene.pbChangeBackground(papers[1][wpaper]) if wpaper >= 0
    when 2
      @scene.pbBoxName(_INTL("¿Nombre de la caja?"),BOX_NAME_MIN_CHARS, BOX_NAME_MAX_CHARS)
    when 3
      pbReleaseBox(@storage.currentBox)
    # when 4
    #   pbSortBox(@storage.currentBox)
    end
  end

  def pbReleaseBox(box)
    released_count = 0
    stored_items = 0
    if pbConfirmMessageSerious(_INTL("¿Quieres liberar a todos los Pokémon de la Caja?"))
      for i in 0...@storage.maxPokemon(box)
        pokemon = @storage[box, i]
        next if !pokemon || pokemon.egg? || pokemon.mail || pokemon.cannot_release
        if pokemon.hasItem? # Recupera el objeto equipado si lleva alguno.
          stored_items += 1
          $bag.add(pokemon.item_id)
        end
        @storage.pbDelete(box, i)
        @scene.pbHardRefresh
        released_count += 1
        pbWait(0.2)
      end
      if released_count > 0
        pbDisplay(_INTL("¡Has liberado {1} Pokémon de esta caja!", released_count))
      else
        pbDisplay(_INTL("No hay Pokémon válidos para liberar en esta caja."))
      end
      if stored_items > 0
        pbDisplay(_INTL("Se ha#{stored_items > 1 ? 'n' : ''} guardado #{stored_items} objeto#{ stored_items > 1 ? 's' : '' } en tu mochila"))
      end
    end
    @scene.pbRefresh
  end

  def pbSortBox(box)
    commands = [
      _INTL("Por nombre de especie"),
      _INTL("Por Orden de Pokédex"),
      _INTL("Por Familia"),
      _INTL("Cancelar")
    ]
    command = pbShowCommands(_INTL("¿Cómo quieres ordenar la caja?"), commands)
    pokemon_array = []
    eggs = []

    return if command == -1 || command == commands.length - 1

    # Get all Pokémon in the box
    @storage.maxPokemon(box).times do |i|
      pokemon = @storage[box, i]
      next unless pokemon
      pokemon.egg? ? eggs << pokemon : pokemon_array << pokemon
    end

    case command
    when 0   # Sort by name
      pokemon_array.sort_by! { |p| p.species_data.name }
    when 1   # Sort by Pokédex number
      pokemon_array.sort_by! { |p| pbGetDexList(p.species)[1] }
    when 2   # Sort by evolution family
      pokemon_array.sort_by! do |p|
        species = GameData::Species.get(p.species)
        base_dex = pbGetDexList(species.get_family_species.first)[1]
        [base_dex, species.get_family_species.index(p.species)]
      end
    end

    # Add eggs at the end
    pokemon_array += eggs

    # Clear the box and place sorted Pokémon
    @storage.pbDelete(box, 0...@storage.maxPokemon(box))
    pokemon_array.each_with_index { |pkmn, i| @storage[box, i] = pkmn }

    @scene.pbRefresh
    @scene.pbHardRefresh
  end

  def pbChoosePokemon(_party = nil)
    $game_temp.in_storage = true
    @heldpkmn = nil
    @scene.pbStartBox(self, 1)
    retval = nil
    loop do
      selected = @scene.pbSelectBox(@storage.party)
      if selected && selected[0] == -3   # Close box
        if pbConfirm(_INTL("¿Salir de la Caja?"))
          pbSEPlay("PC close")
          break
        end
        next
      end
      if selected.nil?
        next if pbConfirm(_INTL("¿Continuar con las operaciones?"))
        break
      elsif selected[0] == -4   # Box name
        pbBoxCommands
      else
        pokemon = @storage[selected[0], selected[1]]
        next if !pokemon
        commands = [
          _INTL("Seleccionar"),
          _INTL("Datos"),
          _INTL("Sacar"),
          _INTL("Objetos"),
          _INTL("Marcas")
        ]
        commands.push(_INTL("Cancelar"))
        commands[2] = _INTL("Guardar") if selected[0] == -1
        helptext = _INTL("Has seleccionado a {1}.", pokemon.name)
        command = pbShowCommands(helptext, commands)
        case command
        when 0   # Select
          if pokemon
            retval = selected
            break
          end
        when 1
          pbSummary(selected, nil)
        when 2   # Store/Withdraw
          if selected[0] == -1
            pbStore(selected, nil)
          else
            pbWithdraw(selected, nil)
          end
        when 3
          pbItem(selected, nil)
        when 4
          pbMark(selected, nil)
        end
      end
    end
    @scene.pbCloseBox
    $game_temp.in_storage = false
    return retval
  end
end


==============================================================================
# Script: UI_ItemStorage
==============================================================================
#===============================================================================
#
#===============================================================================
class Window_PokemonItemStorage < Window_DrawableCommand
  attr_reader :bag
  attr_reader :pocket
  attr_reader :sortIndex

  QTY_X_OFFSET = -2

  def sortIndex=(value)
    @sortIndex = value
    refresh
  end

  def initialize(bag, x, y, width, height)
    @bag = bag
    @sortIndex = -1
    @adapter = PokemonItemMartAdapter.new
    super(x, y, width, height)
    self.windowskin = nil
  end

  def item
    item = @bag[self.index]
    return item ? item[0] : nil
  end

  def itemCount
    return @bag.length + 1
  end

  def drawItem(index, _count, rect)
    rect = drawCursor(index, rect)
    textpos = []
    if index == @bag.length
      textpos.push([_INTL("CANCELAR"), rect.x, rect.y, :left, self.baseColor, self.shadowColor])
    else
      item     = @bag[index][0]
      itemname = @adapter.getDisplayName(item)
      baseColor = (index == @sortIndex) ? Color.new(248, 24, 24) : self.baseColor
      textpos.push([itemname, rect.x, rect.y, :left, self.baseColor, self.shadowColor])
      if GameData::Item.get(item).show_quantity?
        qty     = _ISPRINTF("x{1: 2d}", @bag[index][1])
        sizeQty = self.contents.text_size(qty).width
        xQty = rect.x + rect.width - sizeQty + QTY_X_OFFSET
        textpos.push([qty, xQty, rect.y, :left, baseColor, self.shadowColor])
      end
    end
    pbDrawTextPositions(self.contents, textpos)
  end
end

#===============================================================================
#
#===============================================================================
class ItemStorage_Scene
  ITEMLISTBASECOLOR              = Color.new(88, 88, 80)
  ITEMLISTSHADOWCOLOR            = Color.new(168, 184, 184)
  ITEMTEXTBASECOLOR              = Color.new(248, 248, 248)
  ITEMTEXTSHADOWCOLOR            = Color.new(0, 0, 0)
  TITLEBASECOLOR                 = Color.new(248, 248, 248)
  TITLESHADOWCOLOR               = Color.new(0, 0, 0)
  ITEMSVISIBLE                   = 7
  ITEM_ICON_X                    = 50
  ITEM_ICON_Y                    = 334
  ITEM_WINDOW_X                  = 98
  ITEM_WINDOW_Y                  = 14
  ITEM_WINDOW_WIDTH              = 334
  ITEM_SPACING                   = 32
  ITEM_WINDOW_HEIGHT             = 32 + (ITEMSVISIBLE * ITEM_SPACING)
  POCKET_WINDOW_WIDTH            = 88
  POCKET_WINDOW_HEIGHT           = 64
  POCKET_WINDOW_X                = 14
  POCKET_WINDOW_Y                = 16
  ITEM_TEXT_WINDOW_X             = 84
  ITEM_TEXT_WINDOW_Y             = 272
  ITEM_TEXT_WINDOW_WIDTH         = Graphics.width - 84
  ITEM_TEXT_WINDOW_HEIGHT        = 128
  HELP_WINDOW_TEXT_LINES         = 1
  TOSS_WITHDRAW_ITEM_TEXT_X      = 0
  TOSS_WITHDRAW_ITEM_TEXT_Y      = 8
  TOSS_WITHDRAW_ITEM_TEXT_HEIGHT = 2

  def initialize(title)
    @title = title
  end

  def update
    pbUpdateSpriteHash(@sprites)
  end

  def pbStartScene(bag)
    @viewport   = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = 99999
    @bag = bag
    @sprites = {}
    @sprites["background"] = IconSprite.new(0, 0, @viewport)
    @sprites["background"].setBitmap("Graphics/UI/itemstorage_bg")
    @sprites["icon"] = ItemIconSprite.new(ITEM_ICON_X, ITEM_ICON_Y, nil, @viewport)
    # Item list
    @sprites["itemwindow"] = Window_PokemonItemStorage.new(@bag, ITEM_WINDOW_X, ITEM_WINDOW_Y, ITEM_WINDOW_WIDTH, ITEM_WINDOW_HEIGHT)
    @sprites["itemwindow"].viewport    = @viewport
    @sprites["itemwindow"].index       = 0
    @sprites["itemwindow"].baseColor   = ITEMLISTBASECOLOR
    @sprites["itemwindow"].shadowColor = ITEMLISTSHADOWCOLOR
    @sprites["itemwindow"].refresh
    # Title
    @sprites["pocketwindow"] = BitmapSprite.new(POCKET_WINDOW_WIDTH, POCKET_WINDOW_HEIGHT, @viewport)
    @sprites["pocketwindow"].x = POCKET_WINDOW_X
    @sprites["pocketwindow"].y = POCKET_WINDOW_Y
    pbSetNarrowFont(@sprites["pocketwindow"].bitmap)
    # Item description
    @sprites["itemtextwindow"] = Window_UnformattedTextPokemon.newWithSize("", ITEM_TEXT_WINDOW_X, ITEM_TEXT_WINDOW_Y, ITEM_TEXT_WINDOW_WIDTH, ITEM_TEXT_WINDOW_HEIGHT, @viewport)
    @sprites["itemtextwindow"].baseColor   = ITEMTEXTBASECOLOR
    @sprites["itemtextwindow"].shadowColor = ITEMTEXTSHADOWCOLOR
    @sprites["itemtextwindow"].windowskin  = nil
    @sprites["helpwindow"] = Window_UnformattedTextPokemon.new("")
    @sprites["helpwindow"].visible  = false
    @sprites["helpwindow"].viewport = @viewport
    # Letter-by-letter message window
    @sprites["msgwindow"] = Window_AdvancedTextPokemon.new("")
    @sprites["msgwindow"].visible  = false
    @sprites["msgwindow"].viewport = @viewport
    pbBottomLeftLines(@sprites["helpwindow"], HELP_WINDOW_TEXT_LINES)
    pbDeactivateWindows(@sprites)
    pbRefresh
    pbFadeInAndShow(@sprites)
  end

  def pbEndScene
    pbFadeOutAndHide(@sprites)
    pbDisposeSpriteHash(@sprites)
    @viewport.dispose
  end

  def pbChooseNumber(helptext, maximum)
    return UIHelper.pbChooseNumber(@sprites["helpwindow"], helptext, maximum) { update }
  end

  def pbDisplay(msg, brief = false)
    UIHelper.pbDisplay(@sprites["msgwindow"], msg, brief) { update }
  end

  def pbConfirm(msg)
    UIHelper.pbConfirm(@sprites["msgwindow"], msg) { update }
  end

  def pbShowCommands(helptext, commands)
    return UIHelper.pbShowCommands(@sprites["helpwindow"], helptext, commands) { update }
  end

  def pbRefresh
    bm = @sprites["pocketwindow"].bitmap
    # Draw title at upper left corner ("Toss Item/Withdraw Item")
    drawTextEx(bm, TOSS_WITHDRAW_ITEM_TEXT_X, TOSS_WITHDRAW_ITEM_TEXT_Y, bm.width, TOSS_WITHDRAW_ITEM_TEXT_HEIGHT, @title, TITLEBASECOLOR, TITLESHADOWCOLOR)
    itemwindow = @sprites["itemwindow"]
    # Draw item icon
    @sprites["icon"].item = itemwindow.item
    # Get item description
    if itemwindow.item
      @sprites["itemtextwindow"].text = GameData::Item.get(itemwindow.item).description
    else
      @sprites["itemtextwindow"].text = _INTL("Cerrar almacenamiento.")
    end
    itemwindow.refresh
  end

  def pbChooseItem
    pbRefresh
    @sprites["helpwindow"].visible = false
    itemwindow = @sprites["itemwindow"]
    itemwindow.refresh
    pbActivateWindow(@sprites, "itemwindow") do
      loop do
        Graphics.update
        Input.update
        olditem = itemwindow.item
        self.update
        pbRefresh if itemwindow.item != olditem
        if Input.trigger?(Input::BACK)
          return nil
        elsif Input.trigger?(Input::USE)
          if itemwindow.index < @bag.length
            pbRefresh
            return @bag[itemwindow.index][0]
          else
            return nil
          end
        end
      end
    end
  end
end

