#
#===============================================================================
def pbPurifyChamber
  $player.seen_purify_chamber = true
  pbFadeOutIn do
    scene = PurifyChamberScene.new
    screen = PurifyChamberScreen.new(scene)
    screen.pbStartPurify
  end
end

