==============================================================================
# Script: UI_MysteryGift
==============================================================================
#===============================================================================
# Mystery Gift system
# By Maruno
#===============================================================================
# This url is the location of an example Mystery Gift file.
# You should change it to your file's url once you upload it.
#===============================================================================
module MysteryGift
  URL = "https://pastebin.com/raw/tupastebin"   # Cambia esta URL por la de tu archivo de regalos misteriosos
end

#===============================================================================
# Creating a new Mystery Gift for the Master file, and editing an existing one.
#===============================================================================
# type: 0=Pokémon; 1 or higher=item (is the item's quantity).
# item: The thing being turned into a Mystery Gift (Pokémon object or item ID).
def pbEditMysteryGift(type, item, id = 0, giftname = "", password = nil)
  begin
    if type == 0   # Pokémon
      commands = [_INTL("Regalo Misterioso"),
                  _INTL("Lugar lejano")]
      commands.push(item.obtain_text) if item.obtain_text && !item.obtain_text.empty?
      commands.push(_INTL("[Custom]"))
      loop do
        command = pbMessage(
          _INTL("Elige una frase sobre el lugar donde se ha obtenido ese Pokémon."),
          commands, -1
        )
        if command < 0
          return nil if pbConfirmMessage(_INTL("¿Dejar de agregar este regalo?"))
        elsif command < commands.length - 1
          item.obtain_text = commands[command]
          break
        elsif command == commands.length - 1
          obtainname = pbMessageFreeText(_INTL("Introduce una frase."), "", false, 30)
          if obtainname != ""
            item.obtain_text = obtainname
            break
          end
          return nil if pbConfirmMessage(_INTL("¿Dejar de agregar este regalo?"))
        end
      end
    elsif type > 0   # Item
      params = ChooseNumberParams.new
      params.setRange(1, 99_999)
      params.setDefaultValue(type)
      params.setCancelValue(0)
      loop do
        newtype = pbMessageChooseNumber(_INTL("Elige la cantidad de {1}.",
                                              GameData::Item.get(item).name), params)
        if newtype == 0
          return nil if pbConfirmMessage(_INTL("¿Dejar de editar este regalo?"))
        else
          type = newtype
          break
        end
      end
    end
    if id == 0
      master = []
      idlist = []
      if FileTest.exist?("MysteryGiftMaster.txt")
        master = IO.read("MysteryGiftMaster.txt")
        master = pbMysteryGiftDecrypt(master)
      end
      master.each do |i|
        idlist.push(i[0])
      end
      params = ChooseNumberParams.new
      params.setRange(0, 99_999)
      params.setDefaultValue(id)
      params.setCancelValue(0)
      loop do
        newid = pbMessageChooseNumber(_INTL("Elige un ID único para este regalo."), params)
        if newid == 0
          return nil if pbConfirmMessage(_INTL("¿Dejar de editar este regalo?"))
        elsif idlist.include?(newid)
          pbMessage(_INTL("Ese ID ya está en uso por un Regalo Misterioso."))
        else
          id = newid
          break
        end
      end
    end
    loop do
      newgiftname = pbMessageFreeText(_INTL("Introduce un nombre para el regalo."), giftname, false, 250)
      if newgiftname != ""
        giftname = newgiftname
        break
      end
      return nil if pbConfirmMessage(_INTL("¿Dejar de editar este regalo?"))
    end
    # Pedir si el regalo tendrá contraseña
    has_password = pbConfirmMessage(_INTL("¿Quieres que este regalo requiera una contraseña?"))
    if has_password
      loop do
        new_password = pbMessageFreeText(_INTL("Introduce una contraseña de 8 caracteres."), "", false, 8)
        if new_password.length == 8
          password = new_password
          break
        else
          pbMessage(_INTL("La contraseña debe tener exactamente 8 caracteres."))
        end
      end
    end
    return [id, type, item, giftname, password]
  rescue
    pbMessage(_INTL("No se puede agregar el regalo."))
    return nil
  end
end

def pbCreateMysteryGift(type, item)
  gift = pbEditMysteryGift(type, item)
  if gift
    begin
      if FileTest.exist?("MysteryGiftMaster.txt")
        master = IO.read("MysteryGiftMaster.txt")
        master = pbMysteryGiftDecrypt(master)
        master.push(gift)
      else
        master = [gift]
      end
      string = pbMysteryGiftEncrypt(master)
      File.open("MysteryGiftMaster.txt", "wb") { |f| f.write(string) }
      pbMessage(_INTL("El regalo se ha guardado en MysteryGiftMaster.txt."))
    rescue
      pbMessage(_INTL("No se ha podido guardar el regalo en MysteryGiftMaster.txt."))
    end
  else
    pbMessage(_INTL("No se ha creado el regalo."))
  end
end

#===============================================================================
# Debug option for managing gifts in the Master file and exporting them to a
# file to be uploaded.
#===============================================================================
def pbManageMysteryGifts
  if !FileTest.exist?("MysteryGiftMaster.txt")
    pbMessage(_INTL("No se encuentra el archivo \"MysteryGiftMaster.txt\" con los Regalos Misteriosos. No has creado ningún regalo."))
    pbMessage(_INTL("Puedes crear Regalos tanto de Pokémon como de Objetos. Para los Pokémon, elige la opción Debug que aparece al seleccionarlos en tu equipo o en el PC. Para los Objetos, elige la opción Debug que aparece al seleccionarlos en la Mochila."))
    pbMessage(_INTL("Una vez creados de ese modo, podrás encontrarlos aquí para gestionarlos y subirlos a Internet."))
    return
  end
  # Load all gifts from the Master file.
  master = IO.read("MysteryGiftMaster.txt")
  master = pbMysteryGiftDecrypt(master)
  if !master || !master.is_a?(Array) || master.length == 0
    pbMessage(_INTL("No hay Regalos Misteriosos definidos en el archivo \"MysteryGiftMaster.txt\". No has creado ninguno."))
    pbMessage(_INTL("Puedes crear Regalos tanto de Pokémon como de Objetos. Para los Pokémon, elige la opción Debug que aparece al seleccionarlos en tu equipo o en el PC. Para los Objetos, elige la opción Debug que aparece al seleccionarlos en la Mochila."))
    pbMessage(_INTL("Una vez creados de ese modo, podrás encontrarlos aquí para gestionarlos y subirlos a Internet."))
    return
  end
  pbMessage(_INTL("Archivo \"MysteryGiftMaster.txt\" leído correctamente con los Regalos Misteriosos."))
  # Download all gifts from online
  msgwindow = pbCreateMessageWindow
  pbMessageDisplay(msgwindow, _INTL("Buscando ahora regalos misteriosos en el enlace en línea..."))
  begin
    online = pbDownloadToString(MysteryGift::URL)
  rescue MKXPError
    online = nil
    pbMessage(_INTL("Parece que no tienes conexión a Internet, por lo que no se han podido buscar los regalos.\\wtnp[20]"))
    return
  end
  pbDisposeMessageWindow(msgwindow)
  if nil_or_empty?(online)
    pbMessage(_INTL("No se han encontrado Regalos Misteriosos en el enlace de Internet tras la descarga. Parece que está vacío.\\wtnp[20]"))
    online = []
  else
    pbMessage(_INTL("Se han encontrado Regalos Misteriosos en el enlace de Internet.\\wtnp[20]"))
    online = pbMysteryGiftDecrypt(online, false)
    t = []
    online.each { |gift| t.push(gift[0]) }
    online = t
  end
  # Show list of all gifts.
  command = 0
  loop do
    commands = pbRefreshMGCommands(master, online)
    command = pbMessage("\\ts[]" + _INTL("Gestionar los Regalos Misteriosos (X = regalo encontrado ya en internet)."), commands, -1, nil, command)
    # Gift chosen
    if command == -1 || command == commands.length - 1   # Cancel
      break
    elsif command == commands.length - 4   # Export selected to file
      begin
        newfile = []
        master.each do |gift|
          newfile.push(gift) if online.include?(gift[0])
        end
        string = pbMysteryGiftEncrypt(newfile, false)
        File.open("MysteryGift.txt", "wb") { |f| f.write(string) }
        pbMessage(_INTL("Los regalos que has marcado con una X se han guardado en el archivo MysteryGift.txt."))
        pbMessage(_INTL("Ahora debes subir el contenido del archivo MysteryGift.txt a tu enlace de Internet (por ejemplo en la web de Pastebin) para que puedan ser descargados."))
      rescue
        pbMessage(_INTL("No se han podido guardar los datos en el archivo MysteryGift.txt. Inténtalo de nuevo."))
      end
    elsif command == commands.length - 3   # Borrar los regalos recibidos
      if pbConfirmMessage(_INTL("¿Quieres eliminar el registro de tu jugador de regalos misteriosos? Esto hará que puedas recibirlos todos de nuevo."))
        $player.mystery_gifts = []
        pbMessage(_INTL("Has eliminado correctamente los regalos recibidos."))

      end
    elsif command == commands.length - 2   # A gift
      pbMessage(_INTL("Este menú sirve para gestionar los Regalos Misteriosos."))
      pbMessage(_INTL("Los regalos marcados con una X al entrar en el menú son los que están en internet. El resto son los que están en el archivo \"MysteryGiftMaster.txt\"."))
      pbMessage(_INTL("Ten en cuenta que lo que busca es que en Internet haya un regalo con la misma ID que ese que has elegido. El contenido puede ser distinto, pero si comparten ID aparecerá igualmente marcado."))
      pbMessage(_INTL("Hay dos formas de crear un regalo de la nada: si es un Pokémon, selecciónalo en tu equipo o en el PC y elige la opción Debug. Ahí dentro verás la opción de convertirlo en Regalo Misterioso."))
      pbMessage(_INTL("Lo ideal es que edites un poco el Pokémon antes de crearlo y después elijas esta opción."))
      pbMessage(_INTL("La otra forma de crear los regalos es a partir de un objeto. Añádete el item que te interese desde el modo Debug a la mochila. Después, selecciona ese item dentro de la mochila y elige la opcion Debug y después Hacer Regalo Mist., y sigue los pasos que se indican."))
      pbMessage(_INTL("Una vez creados, al entrar en este menú verás que aparecen aquí, ya que se han guardado en el archivo \"MysteryGiftMaster.txt\"."))
      pbMessage(_INTL("En este menú, marca y desmarca los que quieras y después dale a \"Exportar elegidos\" para escribir los seleccionados en el archivo \"MysteryGift.txt\", que es un archivo distinto, y así poder subirlos a internet."))
      pbMessage(_INTL("Una vez hecho eso, copia y pega el contenido del archivo \"MysteryGift.txt\" en el enlace que hayas creado."))
      pbMessage(_INTL("Puedes usar servicios como la web de Pastebin para subir ahí tus regalos y que así tus jugadores puedan descargarlos."))
      pbMessage(_INTL("Recuerda que debes poner la URL de tu Pastebin en el script \"UI_MysteryGift\" dentro de los scripts del juego, a los que se accede desde el editor."))
      pbMessage(_INTL("Puedes encontrarlo rápidamente si entras en el editor de scripts, pulsas \"cntrl + shift + F\" y escribes \"module MysteryGift\"."))
      pbMessage(_INTL("¡IMPORTANTE! En el archivo \"MysteryGiftMaster.txt\" se pueden leer todos los datos de tus regalos y sus contraseñas. Te recomiendo que lo elimines de la carpeta del juego cuando lo vayas a compartir, para que nadie tenga acceso al mismo."))
    elsif command >= 0 && command < commands.length - 4   # A gift
      cmd = 0
      loop do
        commands = pbRefreshMGCommands(master, online)
        gift = master[command]
        cmds = [_INTL("Marcar/Desmarcar regalo"),
                _INTL("Editar el regalo"),
                _INTL("Recibir el regalo"),
                _INTL("Eliminar el regalo"),
                _INTL("Cancelar")]
        cmd = pbMessage("\\ts[]" + commands[command], cmds, -1, nil, cmd)
        case cmd
        when -1, cmds.length - 1
          break
        when 0   # Toggle on/offline
          if online.include?(gift[0])
            online.delete(gift[0])
          else
            online.push(gift[0])
          end
        when 1   # Edit
          password = gift[4] || nil
          newgift = pbEditMysteryGift(gift[1], gift[2], gift[0], gift[3], password)
          master[command] = newgift if newgift
        when 2   # Receive
          if !$player
            pbMessage(_INTL("No hay ninguna partida guardada cargada. No se puede recibir ningún regalo."))
            next
          end
          replaced = false
          $player.mystery_gifts.length.times do |i|
            if $player.mystery_gifts[i][0] == gift[0]
              $player.mystery_gifts[i] = gift
              replaced = true
            end
          end
          $player.mystery_gifts.push(gift) if !replaced
          pbReceiveMysteryGift(gift[0])
        when 3   # Delete
          if pbConfirmMessage(_INTL("¿Estás seguro de que quieres borrar este regalo? Se eliminará del archivo \"MysteryGiftMaster.txt\"."))
            master.delete_at(command)
            begin
              newfile = []
              master.each do |gift|
                newfile.push(gift)
              end
              string = pbMysteryGiftEncrypt(newfile)
              File.open("MysteryGiftMaster.txt", "wb") { |f| f.write(string) }
              pbMessage(_INTL("El regalo se ha eliminado correctamente del archivo \"MysteryGiftMaster.txt\"."))  
            rescue
              pbMessage(_INTL("No se han podido guardar los datos en el archivo \"MysteryGiftMaster.txt\". Inténtalo de nuevo."))
            end
          end
          break
        end
      end
    end
  end
end

def pbRefreshMGCommands(master, online)
  commands = []
  master.each do |gift|
    itemname = "BLANK"
    if gift[2].is_a?(Pokemon)
      itemname = gift[2].speciesName
    elsif gift[2].is_a?(Hash)
      itemname = gift[2][:name]
    else
      itemname = GameData::Item.get(gift[2]).name + sprintf(" x%d", gift[1])
    end
    ontext = ["[  ]", "[X]"][(online.include?(gift[0])) ? 1 : 0]
    commands.push(_INTL("{1} {2}: {3} ({4})", ontext, gift[0], gift[3], itemname))
  end
  commands.push(_INTL("-> Exportar elegidos a archivo"))
  commands.push(_INTL("-> Eliminar regalos del jugador"))
  commands.push(_INTL("-> Ayuda sobre cómo funciona"))
  commands.push(_INTL("Cancelar"))
  return commands
end

#===============================================================================
# Downloads all available Mystery Gifts that haven't been downloaded yet.
#===============================================================================
# Called from the Continue/New Game screen.
def pbDownloadMysteryGift(trainer)
  sprites = {}
  @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
  @viewport.z = 99999
  addBackgroundPlane(sprites, "background", "mysterygift_bg", @viewport)
  pbFadeInAndShow(sprites)
  pbBGMPlay("Regalo Misterioso", 70)
  loop do
    # Menú de opciones: regalos con contraseña o sin contraseña
    command = pbMessage("Elige qué tipo de Regalo Misterioso descargar.", [
          _INTL("Sin contraseña"),
          _INTL("Con contraseña"),
          _INTL("Cancelar")
      ], -1)
    case command
    when 0
      # Buscar regalos sin contraseña (el flujo original)
      pbDownloadGiftWithoutPassword(trainer)
    when 1
      # Buscar regalos con contraseña
      pbDownloadGiftWithPassword(trainer)
    when 2, -1
      break
    end
  end
  pbBGMFade(1.0)
  pbFadeOutAndHide(sprites)
  pbDisposeSpriteHash(sprites)
  @viewport.dispose
end




def pbDownloadGiftWithoutPassword(trainer)
  # Descargar la lista de regalos desde el servidor usando la URL correcta
  pbMessage(_INTL("Buscando regalos en línea...\\wtnp[20]"))
  begin
    data = pbDownloadToString(MysteryGift::URL)
  rescue MKXPError
    pbMessage(_INTL("Parece que no tienes conexión a Internet, No se pueden buscar regalos."))
    return
  end
  if !data
    pbMessage(_INTL("No se pudo descargar la lista de regalos."))
    return
  end
  # Desencriptar los datos recibidos
  online = pbMysteryGiftDecrypt(data, false)
  pending = []
  online.each do |gift|
    notgot = true
    trainer.mystery_gifts.each do |j|
      notgot = false if j[0] == gift[0]
    end
    pending.push(gift) if notgot
  end
  if pending.length == 0
    pbMessage(_INTL("No hay nuevos regalos disponibles."))
    return
  end

  # Filtrar solo los regalos que no tienen contraseña
  gifts_without_password = pending.select { |gift| gift.length == 4 || (gift.length == 5 && (gift[4].nil? || gift[4].empty?)) }
  # Verificar si hay regalos sin contraseña disponibles
  if gifts_without_password.empty?
    pbMessage(_INTL("No hay regalos disponibles."))
    return
  end
  # Mostrar al jugador la lista de regalos disponibles sin contraseña
  commands = []
  gifts_without_password.each do |gift|
    commands.push(_INTL("{1}", gift[3]))  # gift[3] es el nombre del regalo, gift[0] es el ID
  end
  commands.push(_INTL("Cancelar"))
  # El jugador elige un regalo para descargar
  command = pbMessage(_INTL("Elige un regalo para descargar."), commands, -1)
  if command < 0 || command >= gifts_without_password.length
    pbMessage(_INTL("No se ha descargado ningún regalo."))
    return
  end
  selected_gift = gifts_without_password[command]
  # Entregar el regalo al jugador
  pbReceiveGiftAnimation(selected_gift, trainer)
end



def pbDownloadGiftWithPassword(trainer)
  # Pedir al jugador la contraseña
  password = pbMessageFreeText(_INTL("Introduce la contraseña de 8 caracteres."), "", false, 8)
  if password.length != 8
    pbMessage(_INTL("La contraseña debe tener exactamente 8 caracteres."))
    return
  end
  pbMessage(_INTL("Buscando regalos con la contraseña indicada...\\wtnp[20]"))
  # Descargar la lista de regalos desde el servidor usando la URL
  begin
  data = pbDownloadToString(MysteryGift::URL)
  rescue MKXPError
    pbMessage(_INTL("Parece que no tienes conexión a Internet, No se pueden buscar regalos."))
    return
  end
  if !data
    pbMessage(_INTL("No se pudo descargar la lista de regalos."))
    pbMessage(_INTL("Parece que hay problemas para establecer la conexión a Internet."))
    return
  end
  # Desencriptar los datos recibidos
  online = pbMysteryGiftDecrypt(data, false)
  pending = []
  online.each do |gift|
    notgot = true
    trainer.mystery_gifts.each do |j|
      notgot = false if j[0] == gift[0]
    end
    pending.push(gift) if notgot
  end
  if pending.length == 0
    pbMessage(_INTL("No hay nuevos regalos disponibles."))
    return
  end

  # Buscar el regalo que coincida con la contraseña
  gift_found = nil
  regalos_pass = []
  pending.each do |gift|
    if gift.length == 5 && gift[4] == password  # gift[4] es la contraseña
      regalos_pass.push(gift)
      gift_found = gift
      # break
    end
  end
  # Verificar si se encontró un regalo con la contraseña proporcionada
  if gift_found.nil?
    pbMessage(_INTL("No se ha encontrado ningún regalo con esa contraseña."))
  else
    commands = []
    regalos_pass.each do |gift|
      commands.push(_INTL("{1}", gift[3]))  # gift[3] es el nombre del regalo, gift[0] es el ID
    end
    commands.push(_INTL("Cancelar"))
    # El jugador elige un regalo para descargar
    command = pbMessage(_INTL("Elige un regalo para descargar."), commands, -1)
    if command < 0 || command >= regalos_pass.length
      pbMessage(_INTL("No se ha descargado ningún regalo."))
      return
    end
    selected_gift = regalos_pass[command]
    # Entregar el regalo al jugador
    pbReceiveGiftAnimation(selected_gift, trainer)
  end
end


# Función para manejar la animación al recibir un regalo (puede ser sin o con contraseña)
def pbReceiveGiftAnimation( gift, trainer)
  if gift[1] == 0
    sprite = PokemonSprite.new(@viewport)
    sprite.setOffset(PictureOrigin::CENTER)
    sprite.setPokemonBitmap(gift[2])
    sprite.x = Graphics.width / 2
    sprite.y = -sprite.bitmap.height / 2
  else
    sprite = ItemIconSprite.new(0, 0, gift[2], @viewport)
    sprite.x = Graphics.width / 2
    sprite.y = -sprite.height / 2
  end
  timer_start = System.uptime
  start_y = sprite.y
  loop do
    sprite.y = lerp(start_y, Graphics.height / 2 + 30, 1.5, timer_start, System.uptime)
    Graphics.update
    Input.update
    sprite.update
    break if sprite.y >= Graphics.height / 2  + 30
  end
  pbMEPlay("Battle capture success")
  pbWait(3.0) {Graphics.update; sprite.update}
  pbMessage(_INTL("¡Se ha recibido el regalo!") + "\1") {Graphics.update; sprite.update}
  pbMessage(_INTL("Por favor, recoge tu regalo del repartidor de cualquier Centro Pokémon.")) {Graphics.update; sprite.update}
  trainer.mystery_gifts.push(gift)
  timer_start = System.uptime
  loop do
    sprite.opacity = lerp(255, 0, 1.5, timer_start, System.uptime)
    Graphics.update
    Input.update
    sprite.update
    break if sprite.opacity <= 0
  end
  sprite.dispose
end


#===============================================================================
# Converts an array of gifts into a string and back.
#===============================================================================
def pbMysteryGiftEncrypt(gift, master = true)
  gift.each do |gft|
    if gft[2].is_a?(Pokemon)
      gft[2] = create_hash_from_pkmn(gft[2])
    end
  end
  if Settings::ENCRIPTAR_REGALOS_MISTERIOSOS_EN_MASTER || !master
    ret = [Zlib::Deflate.deflate(Marshal.dump(gift))].pack("m")
  else
    ret = gift.inspect
  end
  return ret
end

def pbMysteryGiftDecrypt(gift, master = true)
  return [] if nil_or_empty?(gift)
  if Settings::ENCRIPTAR_REGALOS_MISTERIOSOS_EN_MASTER || !master
    ret = Marshal.load(Zlib::Inflate.inflate(gift.unpack("m")[0]))
  else
    ret = eval(gift)
  end
  if ret
    ret.each do |gft|
      if gft[1] == 0   # Pokémon
        # Cargamos el Pokémon
        gft[2] = create_pkmn_from_hash(gft[2])
      else   # Item
        gft[2] = GameData::Item.get(gft[2]).id
      end
    end
  end
  return ret
end

#===============================================================================
# Collecting a Mystery Gift from the deliveryman.
#===============================================================================
def pbNextMysteryGiftID
  $player.mystery_gifts.each do |i|
    return i[0] if i.length > 1
  end
  return 0
end

def pbReceiveMysteryGift(id)
  index = -1
  $player.mystery_gifts.length.times do |i|
    if $player.mystery_gifts[i][0] == id && $player.mystery_gifts[i].length > 1
      index = i
      break
    end
  end
  if index == -1
    pbMessage(_INTL("No se han encontrado regalos sin reclamar con la ID {1}.", id))
    return false
  end
  gift = $player.mystery_gifts[index]
  if gift[2].is_a?(Pokemon)   # Pokémon
    pokemon = gift[2]
    was_owned = $player.owned?(pokemon.species)
    if pbAddPokemonSilent(pokemon)
      pbMessage(_INTL("¡{1} recibió {2}!", $player.name, pokemon.name) + "\\me[Pkmn get]\\wtnp[80]")
      $player.mystery_gifts[index] = [id]
      # Show Pokédex entry for new species if it hasn't been owned before
      if Settings::SHOW_NEW_SPECIES_POKEDEX_ENTRY_MORE_OFTEN && !was_owned &&
         $player.has_pokedex && $player.pokedex.species_in_unlocked_dex?(pokemon.species)
        pbMessage(_INTL("Los datos de {1} se han añadido a la Pokédex.", pokemon.name))
        $player.pokedex.register_last_seen(pokemon)
        pbFadeOutIn do
          scene = PokemonPokedexInfo_Scene.new
          screen = PokemonPokedexInfoScreen.new(scene)
          screen.pbDexEntry(pokemon.species)
        end
      end
      return true
    end
  elsif gift[1] > 0   # Item
    item = gift[2]
    qty = gift[1]
    if $bag.can_add?(item, qty)
      $bag.add(item, qty)
      itm = GameData::Item.get(item)
      itemname = (qty > 1) ? itm.portion_name_plural : itm.portion_name
      if item == :DNASPLICERS
        pbMessage("\\me[Item get]" + _INTL("¡Has obtenido \\c[1]{1}\\c[0]!", itemname) + "\\wtnp[40]")
      elsif itm.is_machine?   # TM or HM
        if qty > 1
          pbMessage("\\me[Machine get]" + _INTL("¡Has obtenido {1} \\c[1]{2} {3}\\c[0]!",
                                                qty, itemname, GameData::Move.get(itm.move).name) + "\\wtnp[70]")
        else
          pbMessage("\\me[Machine get]" + _INTL("¡Has obtenido \\c[1]{1} {2}\\c[0]!", itemname,
                                                GameData::Move.get(itm.move).name) + "\\wtnp[70]")
        end
      elsif qty > 1
        pbMessage("\\me[Item get]" + _INTL("¡Has obtenido {1} \\c[1]{2}\\c[0]!", qty, itemname) + "\\wtnp[40]")
      elsif itemname.starts_with_vowel?
        pbMessage("\\me[Item get]" + _INTL("¡Has obtenido \\c[1]{1}\\c[0]!", itemname) + "\\wtnp[40]")
      else
        pbMessage("\\me[Item get]" + _INTL("¡Has obtenido \\c[1]{1}\\c[0]!", itemname) + "\\wtnp[40]")
      end
      $player.mystery_gifts[index] = [id]
      return true
    end
  end
  return false
end

#===============================================================================
# Converts a Pokémon into a hash.
#===============================================================================
def create_hash_from_pkmn(pokemon)
  # Creamos un array con las IDs de los movs.
  movs_array = []
  for i in pokemon.moves
    movs_array.push(i.id)
  end
  owner_id = pokemon.owner.id
  owner_name = pokemon.owner.name
  owner_gender = pokemon.owner.gender
  return {
    species: pokemon.species,
    nivel: pokemon.level,
    nombre: pokemon.name,
    forma: pokemon.form,
    felicidad: pokemon.happiness,
    pokeball: pokemon.poke_ball,
    genero: pokemon.gender,
    naturaleza: pokemon.nature.id,
    ivs: pokemon.iv,
    evs: pokemon.ev,
    habilidad: pokemon.ability.id,
    movimientos: movs_array,
    item: pokemon.item.id,
    cinta_aplicada: pokemon.ribbons,
    steps_to_hatch: pokemon.steps_to_hatch,
    shiny: pokemon.shiny?,
    super_shiny: pokemon.super_shiny?,
    cool: pokemon.cool,
    beauty: pokemon.beauty,
    cute: pokemon.cute,
    smart: pokemon.smart,
    tough: pokemon.tough,
    sheen: pokemon.sheen,
    pokerus: pokemon.pokerus,
    owner_id: owner_id,
    owner_name: owner_name,
    owner_gender: owner_gender,
    obtain_method: pokemon.obtain_method,
    obtain_map: pokemon.obtain_map,
    obtain_text: pokemon.obtain_text,
    obtain_level: pokemon.obtain_level,
    hatched_map: pokemon.hatched_map,
    fused: pokemon.fused,
    personalID: pokemon.personalID,
    ready_to_evolve: pokemon.ready_to_evolve,
    cannot_store: pokemon.cannot_store,
    cannot_release: pokemon.cannot_release,
    cannot_trade: pokemon.cannot_trade,
    scale: pokemon.scale,
    memento: pokemon.memento,
    spot_hash: pokemon.spot_hash,
    shiny_leaf: pokemon.shiny_leaf,
  }
end

#===============================================================================
# Converts a hash into a Pokémon.
#===============================================================================
def create_pkmn_from_hash(poke_hash)
  pokemon = Pokemon.new(poke_hash[:species],poke_hash[:nivel].to_i)
  pokemon.name = poke_hash[:nombre]
  pokemon.form = poke_hash[:forma]
  pokemon.happiness = poke_hash[:felicidad]
  pokemon.poke_ball = poke_hash[:pokeball]
  pokemon.gender = poke_hash[:genero]
  pokemon.nature = poke_hash[:naturaleza]
  pokemon.iv = poke_hash[:ivs]
  pokemon.ev = poke_hash[:evs]
  pokemon.ability = poke_hash[:habilidad]
  pokemon.moves = poke_hash[:movimientos]
  pokemon.item = poke_hash[:item]
  pokemon.ribbons = poke_hash[:cinta_aplicada]
  pokemon.steps_to_hatch = poke_hash[:steps_to_hatch]
  pokemon.shiny = poke_hash[:shiny]
  pokemon.super_shiny = poke_hash[:super_shiny]
  pokemon.moves = poke_hash[:moves]
  pokemon.cool = poke_hash[:cool]
  pokemon.beauty = poke_hash[:beauty]
  pokemon.cute = poke_hash[:cute]
  pokemon.smart = poke_hash[:smart]
  pokemon.tough = poke_hash[:tough]
  pokemon.sheen = poke_hash[:sheen]
  pokemon.pokerus = poke_hash[:pokerus]
  pokemon.owner.id = poke_hash[:owner_id]
  pokemon.owner.name = poke_hash[:owner_name]
  pokemon.owner.gender = poke_hash[:owner_gender]
  pokemon.obtain_method = poke_hash[:obtain_method]
  pokemon.obtain_map = poke_hash[:obtain_map]
  pokemon.obtain_text = poke_hash[:obtain_text]
  pokemon.obtain_level = poke_hash[:obtain_level]
  pokemon.hatched_map = poke_hash[:hatched_map]
  pokemon.fused = poke_hash[:fused]
  pokemon.personalID = poke_hash[:personalID]
  pokemon.ready_to_evolve = poke_hash[:ready_to_evolve]
  pokemon.cannot_store = poke_hash[:cannot_store]
  pokemon.cannot_release = poke_hash[:cannot_release]
  pokemon.cannot_trade = poke_hash[:cannot_trade]
  pokemon.scale = poke_hash[:scale]
  pokemon.memento = poke_hash[:memento]
  pokemon.spot_hash = poke_hash[:spot_hash]
  pokemon.shiny_leaf = poke_hash[:shiny_leaf]
  pokemon.calc_stats
  return pokemon
end

==============================================================================
# Script: UI_TextEntry
==============================================================================
#===============================================================================
#
#===============================================================================
class Window_CharacterEntry < Window_DrawableCommand
  XSIZE = 13
  YSIZE = 4

  def initialize(charset, viewport = nil)
    @viewport = viewport
    @charset = charset
    @othercharset = ""
    super(0, 96, 480, 192)
    colors = getDefaultTextColors(self.windowskin)
    self.baseColor = colors[0]
    self.shadowColor = colors[1]
    self.columns = XSIZE
    refresh
  end

  def setOtherCharset(value)
    @othercharset = value.clone
    refresh
  end

  def setCharset(value)
    @charset = value.clone
    refresh
  end

  def character
    if self.index < 0 || self.index >= @charset.length
      return ""
    else
      return @charset[self.index]
    end
  end

  def command
    return -1 if self.index == @charset.length
    return -2 if self.index == @charset.length + 1
    return -3 if self.index == @charset.length + 2
    return self.index
  end

  def itemCount
    return @charset.length + 3
  end

  def drawItem(index, _count, rect)
    rect = drawCursor(index, rect)
    if index == @charset.length # -1
      pbDrawShadowText(self.contents, rect.x, rect.y, rect.width, rect.height, "[ ]",
                       self.baseColor, self.shadowColor)
    elsif index == @charset.length + 1 # -2
      pbDrawShadowText(self.contents, rect.x, rect.y, rect.width, rect.height, @othercharset,
                       self.baseColor, self.shadowColor)
    elsif index == @charset.length + 2 # -3
      pbDrawShadowText(self.contents, rect.x, rect.y, rect.width, rect.height, _INTL("OK"),
                       self.baseColor, self.shadowColor)
    else
      pbDrawShadowText(self.contents, rect.x, rect.y, rect.width, rect.height, @charset[index],
                       self.baseColor, self.shadowColor)
    end
  end
end

#===============================================================================
# Text entry screen - free typing.
#===============================================================================
class PokemonEntryScene

  WINDOW_ENTRY_X = 0
  WINDOW_ENTRY_Y = 0
  WINDOW_ENTRY_WIDTH = 288
  WINDOW_ENTRY_HEIGHT = 96
  HELP_WINDOW_X = 24
  HELP_WINDOW_Y_OFFSET = -96
  HELP_WINDOW_WIDTH_OFFSET = -48
  HELP_WINDOW_HEIGHT = 96
  PLAYER_SHADOW_X = 66
  PLAYER_SHADOW_Y = 64
  PLAYER_SUBJECT_X_OFFSET = 88
  PLAYER_SUBJECT_Y_OFFSET = 76
  POKEMON_SHADOW_X = 66
  POKEMON_SHADOW_Y = 64
  POKEMON_SUBJECT_X = 88
  POKEMON_SUBJECT_Y = 54
  GENDER_SPRITE_WIDTH = 32
  GENDER_SPRITE_HEIGHT = 32
  GENDER_SPRITE_X = 430
  GENDER_SPRITE_Y = 54
  GENDER_TEXT_X = 0
  GENDER_TEXT_Y = 6
  NPC_SHADOW_X = 66
  NPC_SHADOW_Y = 64
  NPC_SUBJECT_X_OFFSET = 88
  NPC_SUBJECT_Y_OFFSET = 76
  STORAGE_BOX_SUBJECT_X_OFFSET = 88
  STORAGE_BOX_SUBJECT_Y_OFFSET = 52

  @@Characters = [
    [("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz").scan(/./), "[*]"],
    [("0123456789   !@\#$%^&*()   ~`-_+={}[]   :;'\"<>,.?/   ").scan(/./), "[A]"]
  ]
  USEKEYBOARD = true

  def pbStartScene(helptext, minlength, maxlength, initialText, subject = 0, pokemon = nil)
    @sprites = {}
    @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = 99999
    if USEKEYBOARD
      @sprites["entry"] = Window_TextEntry_Keyboard.new(
        initialText, WINDOW_ENTRY_X, WINDOW_ENTRY_Y, WINDOW_ENTRY_WIDTH, WINDOW_ENTRY_HEIGHT, helptext, true
      )
      Input.text_input = true
    else
      @sprites["entry"] = Window_TextEntry.new(initialText, WINDOW_ENTRY_X, WINDOW_ENTRY_Y, WINDOW_ENTRY_WIDTH, WINDOW_ENTRY_HEIGHT, helptext, true)
    end
    @sprites["entry"].x = (Graphics.width / 2) - (@sprites["entry"].width / 2) + 32
    @sprites["entry"].viewport = @viewport
    @sprites["entry"].visible = true
    @minlength = minlength
    @maxlength = maxlength
    @symtype = 0
    @sprites["entry"].maxlength = maxlength
    if !USEKEYBOARD
      @sprites["entry2"] = Window_CharacterEntry.new(@@Characters[@symtype][0])
      @sprites["entry2"].setOtherCharset(@@Characters[@symtype][1])
      @sprites["entry2"].viewport = @viewport
      @sprites["entry2"].visible = true
      @sprites["entry2"].x = (Graphics.width / 2) - (@sprites["entry2"].width / 2)
    end
    if minlength == 0
      @sprites["helpwindow"] = Window_UnformattedTextPokemon.newWithSize(
        _INTL("Escribe texto usando el teclado. Pulsa\nEnter para confirmar, o Esc para cancelar."),
        HELP_WINDOW_X, Graphics.height + HELP_WINDOW_Y_OFFSET, Graphics.width + HELP_WINDOW_WIDTH_OFFSET, HELP_WINDOW_HEIGHT, @viewport
      )
    else
      @sprites["helpwindow"] = Window_UnformattedTextPokemon.newWithSize(
        _INTL("Escribe texto usando el teclado. Pulsa\nEnter para confirmar."),
        HELP_WINDOW_X, Graphics.height + HELP_WINDOW_Y_OFFSET, Graphics.width + HELP_WINDOW_WIDTH_OFFSET, HELP_WINDOW_HEIGHT, @viewport
      )
    end
    @sprites["helpwindow"].letterbyletter = false
    @sprites["helpwindow"].viewport = @viewport
    @sprites["helpwindow"].visible = USEKEYBOARD
    @sprites["helpwindow"].baseColor = Color.new(16, 24, 32)
    @sprites["helpwindow"].shadowColor = Color.new(168, 184, 184)
    addBackgroundPlane(@sprites, "background", "Naming/bg_2", @viewport)
    case subject
    when 1   # Player
      meta = GameData::PlayerMetadata.get($player.character_ID)
      if meta
        @sprites["shadow"] = IconSprite.new(0, 0, @viewport)
        @sprites["shadow"].setBitmap("Graphics/UI/Naming/icon_shadow")
        @sprites["shadow"].x = PLAYER_SHADOW_X
        @sprites["shadow"].y = PLAYER_SHADOW_Y
        filename = pbGetPlayerCharset(meta.walk_charset, nil, true)
        @sprites["subject"] = TrainerWalkingCharSprite.new(filename, @viewport)
        charwidth = @sprites["subject"].bitmap.width
        charheight = @sprites["subject"].bitmap.height
        @sprites["subject"].x = PLAYER_SUBJECT_X_OFFSET - (charwidth / 8)
        @sprites["subject"].y = PLAYER_SUBJECT_Y_OFFSET - (charheight / 4)
      end
    when 2   # Pokémon
      if pokemon
        @sprites["shadow"] = IconSprite.new(0, 0, @viewport)
        @sprites["shadow"].setBitmap("Graphics/UI/Naming/icon_shadow")
        @sprites["shadow"].x = POKEMON_SHADOW_X
        @sprites["shadow"].y = POKEMON_SHADOW_Y
        @sprites["subject"] = PokemonIconSprite.new(pokemon, @viewport)
        @sprites["subject"].setOffset(PictureOrigin::CENTER)
        @sprites["subject"].x = POKEMON_SUBJECT_X
        @sprites["subject"].y = POKEMON_SUBJECT_Y
        @sprites["gender"] = BitmapSprite.new(GENDER_SPRITE_WIDTH, GENDER_SPRITE_HEIGHT, @viewport)
        @sprites["gender"].x = GENDER_SPRITE_X
        @sprites["gender"].y = GENDER_SPRITE_Y
        @sprites["gender"].bitmap.clear
        pbSetSystemFont(@sprites["gender"].bitmap)
        textpos = []
        if pokemon.male?
          textpos.push([_INTL("♂"), GENDER_TEXT_X, GENDER_TEXT_Y, :left, Color.new(0, 128, 248), Color.new(168, 184, 184)])
        elsif pokemon.female?
          textpos.push([_INTL("♀"), GENDER_TEXT_X, GENDER_TEXT_Y, :left, Color.new(248, 24, 24), Color.new(168, 184, 184)])
        end
        pbDrawTextPositions(@sprites["gender"].bitmap, textpos)
      end
    when 3   # NPC
      @sprites["shadow"] = IconSprite.new(0, 0, @viewport)
      @sprites["shadow"].setBitmap("Graphics/UI/Naming/icon_shadow")
      @sprites["shadow"].x = NPC_SHADOW_X
      @sprites["shadow"].y = NPC_SHADOW_Y
      @sprites["subject"] = TrainerWalkingCharSprite.new(pokemon.to_s, @viewport)
      charwidth = @sprites["subject"].bitmap.width
      charheight = @sprites["subject"].bitmap.height
      @sprites["subject"].x = NPC_SUBJECT_X_OFFSET - (charwidth / 8)
      @sprites["subject"].y = NPC_SUBJECT_Y_OFFSET - (charheight / 4)
    when 4   # Storage box
      @sprites["subject"] = TrainerWalkingCharSprite.new(nil, @viewport)
      @sprites["subject"].altcharset = "Graphics/UI/Naming/icon_storage"
      @sprites["subject"].anim_duration = 0.4
      charwidth = @sprites["subject"].bitmap.width
      charheight = @sprites["subject"].bitmap.height
      @sprites["subject"].x = STORAGE_BOX_SUBJECT_X_OFFSET - (charwidth / 8)
      @sprites["subject"].y = STORAGE_BOX_SUBJECT_Y_OFFSET - (charheight / 2)
    end
    pbFadeInAndShow(@sprites)
  end

  def pbEntry1
    ret = ""
    loop do
      Graphics.update
      Input.update
      if Input.triggerex?(:ESCAPE) && @minlength == 0
        ret = ""
        break
      elsif Input.triggerex?(:RETURN) && @sprites["entry"].text.length >= @minlength
        ret = @sprites["entry"].text
        break
      end
      @sprites["helpwindow"].update
      @sprites["entry"].update
      @sprites["subject"]&.update
    end
    Input.update
    return ret
  end

  def pbEntry2
    ret = ""
    loop do
      Graphics.update
      Input.update
      @sprites["helpwindow"].update
      @sprites["entry"].update
      @sprites["entry2"].update
      @sprites["subject"]&.update
      if Input.trigger?(Input::USE)
        index = @sprites["entry2"].command
        if index == -3 # Confirm text
          ret = @sprites["entry"].text
          if ret.length < @minlength || ret.length > @maxlength
            pbPlayBuzzerSE
          else
            pbPlayDecisionSE
            break
          end
        elsif index == -1   # Insert a space
          if @sprites["entry"].insert(" ")
            pbPlayDecisionSE
          else
            pbPlayBuzzerSE
          end
        elsif index == -2   # Change character set
          pbPlayDecisionSE
          @symtype += 1
          @symtype = 0 if @symtype >= @@Characters.length
          @sprites["entry2"].setCharset(@@Characters[@symtype][0])
          @sprites["entry2"].setOtherCharset(@@Characters[@symtype][1])
        else   # Insert given character
          if @sprites["entry"].insert(@sprites["entry2"].character)
            pbPlayDecisionSE
          else
            pbPlayBuzzerSE
          end
        end
        next
      end
    end
    Input.update
    return ret
  end

  def pbEntry
    return USEKEYBOARD ? pbEntry1 : pbEntry2
  end

  def pbEndScene
    pbFadeOutAndHide(@sprites)
    pbDisposeSpriteHash(@sprites)
    @viewport.dispose
    Input.text_input = false if USEKEYBOARD
  end
end

#===============================================================================
# Text entry screen - arrows to select letter.
#===============================================================================
class PokemonEntryScene2
  @@Characters = [
    [("ABCDEFGHIJ ,." + "KLMNOPQRST '-" + "UVWXYZ     ♂♀" + "             " + "0123456789   ").scan(/./), _INTL("MAYUS")],
    [("abcdefghij ,." + "klmnopqrst '-" + "uvwxyz     ♂♀" + "             " + "0123456789   ").scan(/./), _INTL("minus")],
    [("ÀÁÂÄÃàáâäã Ææ" + "ÈÉÊË èéêë  Çç" + "ÌÍÎÏ ìíîï  Œœ" + "ÒÓÔÖÕòóôöõ Ññ" + "ÙÚÛÜ ùúûü  Ýý").scan(/./), _INTL("acentos")],
    [(",.:;…•!?¡¿ ♂♀" + "“”‘’﴾﴿*~_^ ΡΚ" + "@\#&%+-×÷/= ΠΜ" + "◎○□△♠♥♦♣★✨  $" + "♈♌♒♐♩♪♫☽☾    ").scan(/./), _INTL("otros")]
  ]
  ROWS    = 13
  COLUMNS = 5
  MODE1   = -6
  MODE2   = -5
  MODE3   = -4
  MODE4   = -3
  BACK    = -2
  OK      = -1

  COORDS_PER_MODE = {
    PokemonEntryScene2::MODE1  => {:x => 44,  :y => 120, :cursortype => 1},
    PokemonEntryScene2::MODE2  => {:x => 106, :y => 120, :cursortype => 1},
    PokemonEntryScene2::MODE3  => {:x => 168, :y => 120, :cursortype => 1},
    PokemonEntryScene2::MODE4  => {:x => 230, :y => 120, :cursortype => 1},
    PokemonEntryScene2::BACK   => {:x => 314, :y => 120, :cursortype => 2},
    PokemonEntryScene2::OK     => {:x => 394, :y => 120, :cursortype => 2},
    :default                   => {
      :x => 0,   :y => 0,   :cursortype => 0,
      # Origen X del grid de caracteres (columna 0)
      :grid_x => 52,
      # Origen Y del grid de caracteres (fila 0)
      :grid_y => 180,
      # Ancho de cada celda del grid (espaciado X)
      :cell_w => 32,
      # Alto de cada celda del grid (espaciado Y)
      :cell_h => 38
    }
  }

  # Layout constants for the naming UI
  BITMAP_GRID_X = 44
  BITMAP_GRID_Y = 24
  BITMAP_CELL_W = 32
  BITMAP_CELL_H = 38

  MODE_ICON_X = 44
  MODE_ICON_STEP = 62
  MODE_ICON_Y = 120
  MODE_ICON_SRC_W = 60
  MODE_ICON_SRC_H = 44

  BLANK_X0 = 160
  BLANK_STEP = 24
  BLANK_Y_NORMAL = 78
  BLANK_Y_SELECTED = 82

  BOTTOMTAB_X = 22
  BOTTOMTAB_Y = 162
  TOPTAB_START_X = BOTTOMTAB_X - 504
  BOTTOMTAB_OFFSCREEN_Y = 414

  CONTROLS_X = 16
  CONTROLS_Y = 96

  TEXT_START_X = 172
  TEXT_STEP_X = 24

  class NameEntryCursor
    def initialize(viewport)
      @sprite = Sprite.new(viewport)
      @cursortype = 0
      @cursor1 = AnimatedBitmap.new("Graphics/UI/Naming/cursor_1")
      @cursor2 = AnimatedBitmap.new("Graphics/UI/Naming/cursor_2")
      @cursor3 = AnimatedBitmap.new("Graphics/UI/Naming/cursor_3")
      @cursorPos = 0
      updateInternal
    end

    def setCursorPos(value)
      @cursorPos = value
    end

    def updateCursorPos
      value = @cursorPos
        # Use COORDS_PER_MODE for special control positions (modes, back, ok)
        if PokemonEntryScene2::COORDS_PER_MODE.key?(value)
          coords = PokemonEntryScene2::COORDS_PER_MODE[value]
          @sprite.x = coords[:x]
          @sprite.y = coords[:y]
          @cursortype = coords[:cursortype]
        else
          if value >= 0
            default = PokemonEntryScene2::COORDS_PER_MODE[:default]
            @sprite.x = default[:grid_x] + (default[:cell_w] * (value % PokemonEntryScene2::ROWS))
            @sprite.y = default[:grid_y] + (default[:cell_h] * (value / PokemonEntryScene2::ROWS))
            @cursortype = default[:cursortype]
          end
        end
    end

    def visible=(value)
      @sprite.visible = value
    end

    def visible
      @sprite.visible
    end

    def color=(value)
      @sprite.color = value
    end

    def color
      @sprite.color
    end

    def disposed?
      @sprite.disposed?
    end

    def updateInternal
      @cursor1.update
      @cursor2.update
      @cursor3.update
      updateCursorPos
      case @cursortype
      when 0 then @sprite.bitmap = @cursor1.bitmap
      when 1 then @sprite.bitmap = @cursor2.bitmap
      when 2 then @sprite.bitmap = @cursor3.bitmap
      end
    end

    def update
      updateInternal
    end

    def dispose
      @cursor1.dispose
      @cursor2.dispose
      @cursor3.dispose
      @sprite.dispose
    end
  end

  def pbStartScene(helptext, minlength, maxlength, initialText, subject = 0, pokemon = nil)
    @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = 99999
    @helptext = helptext
    @helper = CharacterEntryHelper.new(initialText)
    # Create bitmaps
    @bitmaps = []
    @@Characters.length.times do |i|
      @bitmaps[i] = AnimatedBitmap.new(sprintf("Graphics/UI/Naming/overlay_tab_%d", i + 1))
      b = @bitmaps[i].bitmap.clone
      pbSetSystemFont(b)
      textPos = []
      COLUMNS.times do |y|
        ROWS.times do |x|
          pos = (y * ROWS) + x
          textPos.push([@@Characters[i][0][pos], BITMAP_GRID_X + (x * BITMAP_CELL_W), BITMAP_GRID_Y + (y * BITMAP_CELL_H), :center,
                        Color.new(16, 24, 32), Color.new(160, 160, 160)])
        end
      end
      pbDrawTextPositions(b, textPos)
      @bitmaps[@@Characters.length + i] = b
    end
    underline_bitmap = Bitmap.new(24, 6)
    underline_bitmap.fill_rect(2, 2, 22, 4, Color.new(168, 184, 184))
    underline_bitmap.fill_rect(0, 0, 22, 4, Color.new(16, 24, 32))
    @bitmaps.push(underline_bitmap)
    # Create sprites
    @sprites = {}
    @sprites["bg"] = IconSprite.new(0, 0, @viewport)
    @sprites["bg"].setBitmap("Graphics/UI/Naming/bg")
    case subject
    when 1   # Player
      meta = GameData::PlayerMetadata.get($player.character_ID)
      if meta
        @sprites["shadow"] = IconSprite.new(0, 0, @viewport)
        @sprites["shadow"].setBitmap("Graphics/UI/Naming/icon_shadow")
        @sprites["shadow"].x = 66
        @sprites["shadow"].y = 64
        filename = pbGetPlayerCharset(meta.walk_charset, nil, true)
        @sprites["subject"] = TrainerWalkingCharSprite.new(filename, @viewport)
        charwidth = @sprites["subject"].bitmap.width
        charheight = @sprites["subject"].bitmap.height
        @sprites["subject"].x = 88 - (charwidth / 8)
        @sprites["subject"].y = 76 - (charheight / 4)
      end
    when 2   # Pokémon
      if pokemon
        @sprites["shadow"] = IconSprite.new(0, 0, @viewport)
        @sprites["shadow"].setBitmap("Graphics/UI/Naming/icon_shadow")
        @sprites["shadow"].x = 66
        @sprites["shadow"].y = 64
        @sprites["subject"] = PokemonIconSprite.new(pokemon, @viewport)
        @sprites["subject"].setOffset(PictureOrigin::CENTER)
        @sprites["subject"].x = 88
        @sprites["subject"].y = 54
        @sprites["gender"] = BitmapSprite.new(32, 32, @viewport)
        @sprites["gender"].x = 430
        @sprites["gender"].y = 54
        @sprites["gender"].bitmap.clear
        pbSetSystemFont(@sprites["gender"].bitmap)
        textpos = []
        if pokemon.male?
          textpos.push([_INTL("♂"), 0, 6, :left, Color.new(0, 128, 248), Color.new(168, 184, 184)])
        elsif pokemon.female?
          textpos.push([_INTL("♀"), 0, 6, :left, Color.new(248, 24, 24), Color.new(168, 184, 184)])
        end
        pbDrawTextPositions(@sprites["gender"].bitmap, textpos)
      end
    when 3   # NPC
      @sprites["shadow"] = IconSprite.new(0, 0, @viewport)
      @sprites["shadow"].setBitmap("Graphics/UI/Naming/icon_shadow")
      @sprites["shadow"].x = 66
      @sprites["shadow"].y = 64
      @sprites["subject"] = TrainerWalkingCharSprite.new(pokemon.to_s, @viewport)
      charwidth = @sprites["subject"].bitmap.width
      charheight = @sprites["subject"].bitmap.height
      @sprites["subject"].x = 88 - (charwidth / 8)
      @sprites["subject"].y = 76 - (charheight / 4)
    when 4   # Storage box
      @sprites["subject"] = TrainerWalkingCharSprite.new(nil, @viewport)
      @sprites["subject"].altcharset = "Graphics/UI/Naming/icon_storage"
      @sprites["subject"].anim_duration = 0.4
      charwidth = @sprites["subject"].bitmap.width
      charheight = @sprites["subject"].bitmap.height
      @sprites["subject"].x = 88 - (charwidth / 8)
      @sprites["subject"].y = 52 - (charheight / 2)
    end
    @sprites["bgoverlay"] = BitmapSprite.new(Graphics.width, Graphics.height, @viewport)
    pbDoUpdateOverlay
    @blanks = []
    @mode = 0
    @minlength = minlength
    @maxlength = maxlength
    @maxlength.times do |i|
      @sprites["blank#{i}"] = Sprite.new(@viewport)
      @sprites["blank#{i}"].x = BLANK_X0 + (BLANK_STEP * i)
      @sprites["blank#{i}"].bitmap = @bitmaps[@bitmaps.length - 1]
      @blanks[i] = 0
    end
    @sprites["bottomtab"] = Sprite.new(@viewport)   # Current tab
    @sprites["bottomtab"].x = BOTTOMTAB_X
    @sprites["bottomtab"].y = BOTTOMTAB_Y
    @sprites["bottomtab"].bitmap = @bitmaps[@@Characters.length]
    @sprites["toptab"] = Sprite.new(@viewport)   # Next tab
    @sprites["toptab"].x = TOPTAB_START_X
    @sprites["toptab"].y = BOTTOMTAB_Y
    @sprites["toptab"].bitmap = @bitmaps[@@Characters.length + 1]
    @sprites["controls"] = IconSprite.new(0, 0, @viewport)
    @sprites["controls"].x = CONTROLS_X
    @sprites["controls"].y = CONTROLS_Y
    @sprites["controls"].setBitmap(_INTL("Graphics/UI/Naming/overlay_controls"))
    @sprites["overlay"] = BitmapSprite.new(Graphics.width, Graphics.height, @viewport)
    pbDoUpdateOverlay2
    @sprites["cursor"] = NameEntryCursor.new(@viewport)
    @cursorpos = 0
    @refreshOverlay = true
    @sprites["cursor"].setCursorPos(@cursorpos)
    pbFadeInAndShow(@sprites) { pbUpdate }
  end

  def pbUpdateOverlay
    @refreshOverlay = true
  end

  def pbDoUpdateOverlay2
    overlay = @sprites["overlay"].bitmap
    overlay.clear
    modeIcon = [[_INTL("Graphics/UI/Naming/icon_mode"), MODE_ICON_X + (@mode * MODE_ICON_STEP), MODE_ICON_Y, @mode * MODE_ICON_SRC_W, 0, MODE_ICON_SRC_W, MODE_ICON_SRC_H]]
    pbDrawImagePositions(overlay, modeIcon)
  end

  def pbDoUpdateOverlay
    return if !@refreshOverlay
    @refreshOverlay = false
    bgoverlay = @sprites["bgoverlay"].bitmap
    bgoverlay.clear
    pbSetSystemFont(bgoverlay)
    textPositions = [
      [@helptext, 160, 18, :left, Color.new(16, 24, 32), Color.new(168, 184, 184)]
    ]
    chars = @helper.textChars
    x = TEXT_START_X
    chars.each do |ch|
      textPositions.push([ch, x, 54, :center, Color.new(16, 24, 32), Color.new(168, 184, 184)])
      x += TEXT_STEP_X
    end
    pbDrawTextPositions(bgoverlay, textPositions)
  end

  def pbChangeTab(newtab = @mode + 1)
    pbSEPlay("GUI naming tab swap start")
    @sprites["cursor"].visible = false
    @sprites["toptab"].bitmap = @bitmaps[(newtab % @@Characters.length) + @@Characters.length]
    # Move bottom (old) tab down off the screen, and move top (new) tab right
    # onto the screen
    timer_start = System.uptime
    loop do
      @sprites["bottomtab"].y = lerp(BOTTOMTAB_Y, BOTTOMTAB_OFFSCREEN_Y, 0.5, timer_start, System.uptime)
      @sprites["toptab"].x = lerp(TOPTAB_START_X, BOTTOMTAB_X, 0.5, timer_start, System.uptime)
      Graphics.update
      Input.update
      pbUpdate
      break if @sprites["toptab"].x >= BOTTOMTAB_X && @sprites["bottomtab"].y >= BOTTOMTAB_OFFSCREEN_Y
    end
    # Swap top and bottom tab around
    @sprites["toptab"].x, @sprites["bottomtab"].x = @sprites["bottomtab"].x, @sprites["toptab"].x
    @sprites["toptab"].y, @sprites["bottomtab"].y = @sprites["bottomtab"].y, @sprites["toptab"].y
    @sprites["toptab"].bitmap, @sprites["bottomtab"].bitmap = @sprites["bottomtab"].bitmap, @sprites["toptab"].bitmap
    Graphics.update
    Input.update
    pbUpdate
    # Set the current mode
    @mode = newtab % @@Characters.length
    # Set the top tab up to be the next tab
    newtab = @bitmaps[((@mode + 1) % @@Characters.length) + @@Characters.length]
    @sprites["cursor"].visible = true
    @sprites["toptab"].bitmap = newtab
    @sprites["toptab"].x = TOPTAB_START_X
    @sprites["toptab"].y = BOTTOMTAB_Y
    pbSEPlay("GUI naming tab swap end")
    pbDoUpdateOverlay2
  end

  def pbUpdate
    @@Characters.length.times do |i|
      @bitmaps[i].update
    end
    # Update which inputted text's character's underline is lowered to indicate
    # which character is selected
    cursorpos = @helper.cursor.clamp(0, @maxlength - 1)
    @maxlength.times do |i|
      @blanks[i] = (i == cursorpos) ? 1 : 0
      @sprites["blank#{i}"].y = [78, 82][@blanks[i]]
    end
    pbDoUpdateOverlay
    pbUpdateSpriteHash(@sprites)
  end

  def pbColumnEmpty?(m)
    return false if m >= ROWS - 1
    chset = @@Characters[@mode][0]
    COLUMNS.times do |i|
      return false if chset[(i * ROWS) + m] != " "
    end
    return true
  end

  def wrapmod(x, y)
    result = x % y
    result += y if result < 0
    return result
  end

  def pbMoveCursor
    oldcursor = @cursorpos
    cursordiv = @cursorpos / ROWS   # The row the cursor is in
    cursormod = @cursorpos % ROWS   # The column the cursor is in
    cursororigin = @cursorpos - cursormod
    if Input.repeat?(Input::LEFT)
      if @cursorpos < 0   # Controls
        @cursorpos -= 1
        @cursorpos = OK if @cursorpos < MODE1
      else
        loop do
          cursormod = wrapmod(cursormod - 1, ROWS)
          @cursorpos = cursororigin + cursormod
          break unless pbColumnEmpty?(cursormod)
        end
      end
    elsif Input.repeat?(Input::RIGHT)
      if @cursorpos < 0   # Controls
        @cursorpos += 1
        @cursorpos = MODE1 if @cursorpos > OK
      else
        loop do
          cursormod = wrapmod(cursormod + 1, ROWS)
          @cursorpos = cursororigin + cursormod
          break unless pbColumnEmpty?(cursormod)
        end
      end
    elsif Input.repeat?(Input::UP)
      if @cursorpos < 0         # Controls
        case @cursorpos
        when MODE1 then @cursorpos = ROWS * (COLUMNS - 1)
        when MODE2 then @cursorpos = (ROWS * (COLUMNS - 1)) + 2
        when MODE3 then @cursorpos = (ROWS * (COLUMNS - 1)) + 4
        when MODE4 then @cursorpos = (ROWS * (COLUMNS - 1)) + 6
        when BACK  then @cursorpos = (ROWS * (COLUMNS - 1)) + 9
        when OK    then @cursorpos = (ROWS * (COLUMNS - 1)) + 11
        end
      elsif @cursorpos < ROWS   # Top row of letters
        case @cursorpos
        when 0, 1     then @cursorpos = MODE1
        when 2, 3     then @cursorpos = MODE2
        when 4, 5     then @cursorpos = MODE3
        when 6, 7     then @cursorpos = MODE4
        when 8, 9, 10 then @cursorpos = BACK
        when 11, 12   then @cursorpos = OK
        end
      else
        cursordiv = wrapmod(cursordiv - 1, COLUMNS)
        @cursorpos = (cursordiv * ROWS) + cursormod
      end
    elsif Input.repeat?(Input::DOWN)
      if @cursorpos < 0                      # Controls
        case @cursorpos
        when MODE1 then @cursorpos = 0
        when MODE2 then @cursorpos = 2
        when MODE3 then @cursorpos = 4
        when MODE4 then @cursorpos = 6
        when BACK  then @cursorpos = 9
        when OK    then @cursorpos = 11
        end
      elsif @cursorpos >= ROWS * (COLUMNS - 1)   # Bottom row of letters
        case cursormod
        when 0, 1     then @cursorpos = MODE1
        when 2, 3     then @cursorpos = MODE2
        when 4, 5     then @cursorpos = MODE3
        when 6, 7     then @cursorpos = MODE4
        when 8, 9, 10 then @cursorpos = BACK
        else               @cursorpos = OK
        end
      else
        cursordiv = wrapmod(cursordiv + 1, COLUMNS)
        @cursorpos = (cursordiv * ROWS) + cursormod
      end
    end
    if @cursorpos != oldcursor   # Cursor position changed
      @sprites["cursor"].setCursorPos(@cursorpos)
      pbPlayCursorSE
      return true
    end
    return false
  end

  def pbEntry
    ret = ""
    loop do
      Graphics.update
      Input.update
      pbUpdate
      next if pbMoveCursor
      if Input.trigger?(Input::SPECIAL)
        pbChangeTab
      elsif Input.trigger?(Input::ACTION)
        @cursorpos = OK
        @sprites["cursor"].setCursorPos(@cursorpos)
      elsif Input.trigger?(Input::BACK)
        @helper.delete
        pbPlayCancelSE
        pbUpdateOverlay
      elsif Input.trigger?(Input::USE)
        case @cursorpos
        when BACK   # Backspace
          @helper.delete
          pbPlayCancelSE
          pbUpdateOverlay
        when OK     # Done
          pbSEPlay("GUI naming confirm")
          if @helper.length >= @minlength
            ret = @helper.text
            break
          end
        when MODE1
          pbChangeTab(0) if @mode != 0
        when MODE2
          pbChangeTab(1) if @mode != 1
        when MODE3
          pbChangeTab(2) if @mode != 2
        when MODE4
          pbChangeTab(3) if @mode != 3
        else
          cursormod = @cursorpos % ROWS
          cursordiv = @cursorpos / ROWS
          charpos = (cursordiv * ROWS) + cursormod
          chset = @@Characters[@mode][0]
          @helper.delete if @helper.length >= @maxlength
          @helper.insert(chset[charpos])
          pbPlayCursorSE
          if @helper.length >= @maxlength
            @cursorpos = OK
            @sprites["cursor"].setCursorPos(@cursorpos)
          end
          pbUpdateOverlay
          # Auto-switch to lowercase letters after the first uppercase letter is selected
          pbChangeTab(1) if @mode == 0 && @helper.cursor == 1
        end
      end
    end
    Input.update
    return ret
  end

  def pbEndScene
    pbFadeOutAndHide(@sprites) { pbUpdate }
    @bitmaps.each do |bitmap|
      bitmap&.dispose
    end
    @bitmaps.clear
    pbDisposeSpriteHash(@sprites)
    @viewport.dispose
  end
end

