class ButtonEventScene < EventScene

  F1_IMAGE_X = 44
  F1_IMAGE_Y = 80
  F8_IMAGE_X = 44
  F8_IMAGE_Y = 278
  WARNING_TEXT_X = 134
  WARNING_TEXT_Y = 30
  WARNING_TEXT_WIDTH = 352
  SCREENSHOT_TEXT_X = 134
  SCREENSHOT_TEXT_Y = 270
  SCREENSHOT_TEXT_WIDTH = 352
  ARROWS_IMAGE_X = 16
  ARROWS_IMAGE_Y = 158
  ARROWS_TEXT_X = 134
  ARROWS_TEXT_Y = 100
  ARROWS_TEXT_WIDTH = 352
  USEKEY_IMAGE_X = 16
  USEKEY_IMAGE_Y = 90
  BACKKEY_IMAGE_X = 16
  BACKKEY_IMAGE_Y = 236
  USEKEY_TEXT_X = 134
  USEKEY_TEXT_Y = 34
  USEKEY_TEXT_WIDTH = 352
  BACKKEY_TEXT_X = 134
  BACKKEY_TEXT_Y = 214
  BACKKEY_TEXT_WIDTH = 352
  ACTIONKEY_IMAGE_X = 16
  ACTIONKEY_IMAGE_Y = 90
  SPECIALKEY_IMAGE_X = 16
  SPECIALKEY_IMAGE_Y = 236
  ACTIONKEY_TEXT_X = 134
  ACTIONKEY_TEXT_Y = 28
  ACTIONKEY_TEXT_WIDTH = 352
  SPECIALKEY_TEXT_X = 134
  SPECIALKEY_TEXT_Y = 200
  SPECIALKEY_TEXT_WIDTH = 352

  def initialize(viewport = nil)
    super
    Graphics.freeze
    @current_screen = 1
    addImage(0, 0, "Graphics/UI/Controls help/bg")
    @labels = []
    @label_screens = []
    @keys = []
    @key_screens = []

    addImageForScreen(1, F1_IMAGE_X, F1_IMAGE_Y, _INTL("Graphics/UI/Controls help/help_f1"))
    addImageForScreen(1, F8_IMAGE_X, F8_IMAGE_Y, _INTL("Graphics/UI/Controls help/help_f8"))
    addLabelForScreen(1, WARNING_TEXT_X, WARNING_TEXT_Y, WARNING_TEXT_WIDTH, _INTL("IMPORTANTE: Pulsa esta tecla en cualquier momento para ver los controles. Abre la ventana de Asignación de teclas, donde elegir qué teclas de teclado usar para cada control. También detecta un mando."))
    addLabelForScreen(1, SCREENSHOT_TEXT_X, SCREENSHOT_TEXT_Y, SCREENSHOT_TEXT_WIDTH, _INTL("Toma una captura de pantalla. Se guarda en la misma carpeta que el archivo de guardado."))

    addImageForScreen(2, ARROWS_IMAGE_X, ARROWS_IMAGE_Y, _INTL("Graphics/UI/Controls help/help_arrows"))
    addLabelForScreen(2, ARROWS_TEXT_X, ARROWS_TEXT_Y, ARROWS_TEXT_WIDTH, _INTL("Utiliza las teclas de flecha para mover al personaje principal.\n\nTambién puedes usar las teclas de flecha para seleccionar entradas y navegar por los menús."))

    addImageForScreen(3, USEKEY_IMAGE_X, USEKEY_IMAGE_Y, _INTL("Graphics/UI/Controls help/help_usekey"))
    addImageForScreen(3, BACKKEY_IMAGE_X, BACKKEY_IMAGE_Y, _INTL("Graphics/UI/Controls help/help_backkey"))
    addLabelForScreen(3, USEKEY_TEXT_X, USEKEY_TEXT_Y, USEKEY_TEXT_WIDTH, _INTL("Usado para confirmar una elección, interactuar con personas y cosas, y avanzar a través del texto. (Predeterminado: C)"))
    addLabelForScreen(3, BACKKEY_TEXT_X, BACKKEY_TEXT_Y, BACKKEY_TEXT_WIDTH, _INTL("Usado para salir, cancelar una elección y cancelar un modo. También abre el menú de Pausa. (Predeterminado: X)"))

    addImageForScreen(4, ACTIONKEY_IMAGE_X, ACTIONKEY_IMAGE_Y, _INTL("Graphics/UI/Controls help/help_actionkey"))
    addImageForScreen(4, SPECIALKEY_IMAGE_X, SPECIALKEY_IMAGE_Y, _INTL("Graphics/UI/Controls help/help_specialkey"))
    addLabelForScreen(4, ACTIONKEY_TEXT_X, ACTIONKEY_TEXT_Y, ACTIONKEY_TEXT_WIDTH, _INTL("Mientras te mueves, mantenlo presionado para moverte a una velocidad diferente. También tiene varias funciones según el contexto. (Predeterminado: Z)"))
    addLabelForScreen(4, SPECIALKEY_TEXT_X, SPECIALKEY_TEXT_Y, SPECIALKEY_TEXT_WIDTH, _INTL("Presiona para abrir el Menú de preparación, donde se pueden usar objetos registrados y movimientos disponibles en el campo. (Predeterminado: D)"))

    set_up_screen(@current_screen)
    Graphics.transition
    # Ir a la siguiente pantalla cuando el usuario presiona USAR
    onCTrigger.set(method(:pbOnScreenEnd))
  end

  def addLabelForScreen(number, x, y, width, text)
    @labels.push(addLabel(x, y, width, text))
    @label_screens.push(number)
    @picturesprites[@picturesprites.length - 1].opacity = 0
  end

  def addImageForScreen(number, x, y, filename)
    @keys.push(addImage(x, y, filename))
    @key_screens.push(number)
    @picturesprites[@picturesprites.length - 1].opacity = 0
  end

  def set_up_screen(number)
    @label_screens.each_with_index do |screen, i|
      @labels[i].moveOpacity((screen == number) ? 10 : 0, 10, (screen == number) ? 255 : 0)
    end
    @key_screens.each_with_index do |screen, i|
      @keys[i].moveOpacity((screen == number) ? 10 : 0, 10, (screen == number) ? 255 : 0)
    end
    pictureWait   # Actualizar escena de evento con los cambios
  end

  def pbOnScreenEnd(scene, *args)
    last_screen = [@label_screens.max, @key_screens.max].max
    if @current_screen >= last_screen
      # Terminar escena
      $game_temp.background_bitmap = Graphics.snap_to_bitmap
      Graphics.freeze
      @viewport.color = Color.black  # Asegurarse de que la pantalla esté en negro
      Graphics.transition(8, "fadetoblack")
      $game_temp.background_bitmap.dispose
      scene.dispose
    else
      # Siguiente pantalla
      @current_screen += 1
      onCTrigger.clear
      set_up_screen(@current_screen)
      onCTrigger.set(method(:pbOnScreenEnd))
    end
  end
end


==============================================================================
# Script: UI_EggHatching
==============================================================================
#===============================================================================
# * Animación de Eclosión de Huevo - por FL (Se agradecerán los créditos)
#                                     Ajustado por Maruno
#===============================================================================
# Este script es para Pokémon Essentials. Es una animación de eclosión de huevo 
# que funciona incluso con huevos especiales como el huevo de Manaphy.
#===============================================================================
# Para que este script funcione, colócalo encima de Main y coloca una imagen 
# (una hoja de sprite de 5 frames) con la altura del sprite de huevo y 5 veces 
# el ancho del sprite de huevo en Graphics/Battlers/eggCracks.
#===============================================================================

class PokemonEggHatch_Scene
 
  POKEMON_X_OFFSET = 0
  POKEMON_Y = 264
  EGG_HATCH_OFFSET_Y = 56

  def pbStartScene(pokemon)
    @sprites = {}
    @pokemon = pokemon
    @nicknamed = false
    @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = 99999
    # Create background image
    addBackgroundOrColoredPlane(@sprites, "background", "hatch_bg",
                                Color.new(248, 248, 248), @viewport)
    # Create egg sprite/Pokémon sprite
    @sprites["pokemon"] = PokemonSprite.new(@viewport)
    @sprites["pokemon"].setOffset(PictureOrigin::BOTTOM)
    @sprites["pokemon"].x = Graphics.width / 2 + POKEMON_X_OFFSET
    @sprites["pokemon"].y = POKEMON_Y + EGG_HATCH_OFFSET_Y
    @sprites["pokemon"].setSpeciesBitmap(@pokemon.species, @pokemon.gender,
                                         @pokemon.form, @pokemon.shiny?,
                                         false, false, true)   # Egg sprite
    # Load egg cracks bitmap
    crackfilename = GameData::Species.egg_cracks_sprite_filename(@pokemon.species, @pokemon.form)
    @hatchSheet = AnimatedBitmap.new(crackfilename)
    # Create egg cracks sprite
    @sprites["hatch"] = Sprite.new(@viewport)
    @sprites["hatch"].x = @sprites["pokemon"].x
    @sprites["hatch"].y = @sprites["pokemon"].y
    @sprites["hatch"].ox = @sprites["pokemon"].ox
    @sprites["hatch"].oy = @sprites["pokemon"].oy
    @sprites["hatch"].bitmap = @hatchSheet.bitmap
    @sprites["hatch"].src_rect = Rect.new(0, 0, @hatchSheet.width / 5, @hatchSheet.height)
    @sprites["hatch"].visible = false
    # Create flash overlay
    @sprites["overlay"] = BitmapSprite.new(Graphics.width, Graphics.height, @viewport)
    @sprites["overlay"].z = 200
    @sprites["overlay"].bitmap = Bitmap.new(Graphics.width, Graphics.height)
    @sprites["overlay"].bitmap.fill_rect(0, 0, Graphics.width, Graphics.height, Color.white)
    @sprites["overlay"].opacity = 0
    # Start up scene
    pbFadeInAndShow(@sprites)
  end

  def pbMain
    pbBGMPlay("Evolution")
    # Egg animation
    updateScene(1.5)
    pbPositionHatchMask(0)
    pbSEPlay("Battle ball shake")
    swingEgg(4)
    updateScene(0.2)
    pbPositionHatchMask(1)
    pbSEPlay("Battle ball shake")
    swingEgg(4)
    updateScene(0.4)
    pbPositionHatchMask(2)
    pbSEPlay("Battle ball shake")
    swingEgg(8, 2)
    updateScene(0.4)
    pbPositionHatchMask(3)
    pbSEPlay("Battle ball shake")
    swingEgg(16, 4)
    updateScene(0.2)
    pbPositionHatchMask(4)
    pbSEPlay("Battle recall")
    # Fade and change the sprite
    timer_start = System.uptime
    loop do
      tone_val = lerp(0, 255, 0.4, timer_start, System.uptime)
      @sprites["pokemon"].tone = Tone.new(tone_val, tone_val, tone_val)
      @sprites["overlay"].opacity = tone_val
      updateScene
      break if tone_val >= 255
    end
    updateScene(0.75)
    @sprites["pokemon"].setPokemonBitmap(@pokemon) # Pokémon sprite
    @sprites["pokemon"].x = Graphics.width / 2 + POKEMON_X_OFFSET
    @sprites["pokemon"].y = POKEMON_Y
    @pokemon.species_data.apply_metrics_to_sprite(@sprites["pokemon"], 1)
    @sprites["hatch"].visible = false
    timer_start = System.uptime
    loop do
      tone_val = lerp(255, 0, 0.4, timer_start, System.uptime)
      @sprites["pokemon"].tone = Tone.new(tone_val, tone_val, tone_val)
      @sprites["overlay"].opacity = tone_val
      updateScene
      break if tone_val <= 0
    end
    # Finish scene
    cry_duration = GameData::Species.cry_length(@pokemon)
    @pokemon.play_cry
    updateScene(cry_duration + 0.1)
    pbBGMStop
    pbMEPlay("Evolution success")
    @pokemon.name = nil
    pbMessage("\\se[]" + _INTL("¡{1} salió del Huevo!", @pokemon.name) + "\\wt[80]") { update }
    # Record the Pokémon's species as owned in the Pokédex
    was_owned = $player.owned?(@pokemon.species)
    $player.pokedex.register(@pokemon)
    $player.pokedex.set_owned(@pokemon.species)
    $player.pokedex.set_seen_egg(@pokemon.species)
    # Show Pokédex entry for new species if it hasn't been owned before
    if Settings::SHOW_NEW_SPECIES_POKEDEX_ENTRY_MORE_OFTEN && !was_owned &&
       $player.has_pokedex && $player.pokedex.species_in_unlocked_dex?(@pokemon.species)
      pbMessage(_INTL("Los datos de {1} se han añadido a la Pokédex.", @pokemon.name)) { update }
      $player.pokedex.register_last_seen(@pokemon)
      pbFadeOutIn do
        scene = PokemonPokedexInfo_Scene.new
        screen = PokemonPokedexInfoScreen.new(scene)
        screen.pbDexEntry(@pokemon.species)
      end
    end
    # Nickname the Pokémon
    if $PokemonSystem.givenicknames == 0 &&
       pbConfirmMessage(
         _INTL("¿Quieres ponerle un mote al {1} recién nacido?", @pokemon.name)
       ) { update }
      nickname = pbEnterPokemonName(_INTL("¿Mote de {1}?", @pokemon.name),
                                    0, Pokemon::MAX_NAME_SIZE, "", @pokemon, true)
      @pokemon.name = nickname
      @nicknamed = true
    end
  end

  def pbEndScene
    pbFadeOutAndHide(@sprites) { update } if !@nicknamed
    pbDisposeSpriteHash(@sprites)
    @hatchSheet.dispose
    @viewport.dispose
  end

  def pbPositionHatchMask(index)
    @sprites["hatch"].src_rect.x = index * @sprites["hatch"].src_rect.width
  end

  def swingEgg(speed, swingTimes = 1)
    @sprites["hatch"].visible = true
    amplitude = 8
    duration = 0.05 * amplitude / speed
    targets = []
    swingTimes.times do
      targets.push(@sprites["pokemon"].x + amplitude)
      targets.push(@sprites["pokemon"].x - amplitude)
    end
    targets.push(@sprites["pokemon"].x)
    targets.each_with_index do |target, i|
      timer_start = System.uptime
      start_x = @sprites["pokemon"].x
      loop do
        break if i.even? && @sprites["pokemon"].x >= target
        break if i.odd? && @sprites["pokemon"].x <= target
        @sprites["pokemon"].x = lerp(start_x, target, duration, timer_start, System.uptime)
        @sprites["hatch"].x = @sprites["pokemon"].x
        updateScene
      end
    end
    @sprites["pokemon"].x = targets[targets.length - 1]
    @sprites["hatch"].x   = @sprites["pokemon"].x
  end

  # Can be used for "wait" effect.
  def updateScene(duration = 0.01)
    timer_start = System.uptime
    while System.uptime - timer_start < duration
      Graphics.update
      Input.update
      self.update
    end
  end

  def update
    pbUpdateSpriteHash(@sprites)
  end
end

#===============================================================================
#
#===============================================================================
class PokemonEggHatchScreen
  def initialize(scene)
    @scene = scene
  end

  def pbStartScreen(pokemon)
    @scene.pbStartScene(pokemon)
    @scene.pbMain
    @scene.pbEndScene
  end
end

