#===============================================================================
def pbHatchAnimation(pokemon)
  pbMessage(_INTL("¿Y esto?") + "\1")
  pbFadeOutInWithMusic do
    scene = PokemonEggHatch_Scene.new
    screen = PokemonEggHatchScreen.new(scene)
    screen.pbStartScreen(pokemon)
  end
  return true
end

def pbHatch(pokemon)
  $stats.eggs_hatched += 1
  speciesname = pokemon.speciesName
  pokemon.name           = nil
  pokemon.owner          = Pokemon::Owner.new_from_trainer($player)
  pokemon.happiness      = 120
  pokemon.steps_to_hatch = 0
  pokemon.timeEggHatched = Time.now.to_i
  pokemon.obtain_method  = 1   # hatched from egg
  pokemon.hatched_map    = $game_map.map_id
  pokemon.record_first_moves
  if !pbHatchAnimation(pokemon)
    pbMessage(_INTL("¿Y esto?") + "\1")
    pbMessage(_INTL("...") + "\1")
    pbMessage(_INTL("... .... .....") + "\1")
    pbMessage(_INTL("¡{1} nació del Huevo!", speciesname))
    was_owned = $player.owned?(pokemon.species)
    $player.pokedex.register(pokemon)
    $player.pokedex.set_owned(pokemon.species)
    $player.pokedex.set_seen_egg(pokemon.species)
    # Show Pokédex entry for new species if it hasn't been owned before
    if Settings::SHOW_NEW_SPECIES_POKEDEX_ENTRY_MORE_OFTEN && !was_owned &&
       $player.has_pokedex && $player.pokedex.species_in_unlocked_dex?(pokemon.species)
      pbMessage(_INTL("Los datos de {1} se han añadido a la Pokédex.", speciesname))
      $player.pokedex.register_last_seen(pokemon)
      pbFadeOutIn do
        scene = PokemonPokedexInfo_Scene.new
        screen = PokemonPokedexInfoScreen.new(scene)
        screen.pbDexEntry(pokemon.species)
      end
    end
    # Nickname the Pokémon
    if $PokemonSystem.givenicknames == 0 &&
       pbConfirmMessage(_INTL("¿Quieres ponerle un mote al {1} recién nacido?", speciesname))
      nickname = pbEnterPokemonName(_INTL("¿Mote de {1}?", speciesname),
                                    0, Pokemon::MAX_NAME_SIZE, "", pokemon)
      pokemon.name = nickname
    end
  end
end

EventHandlers.add(:on_player_step_taken, :hatch_eggs,
  proc {
    $player.party.each do |egg|
      next if egg.steps_to_hatch <= 0
      egg.steps_to_hatch -= 1
      $player.pokemon_party.each do |pkmn|
        next if !pkmn.ability&.has_flag?("FasterEggHatching")
        egg.steps_to_hatch -= 1
        break
      end
      if egg.steps_to_hatch <= 0
        egg.steps_to_hatch = 0
        pbHatch(egg)
      end
    end
  }
)


==============================================================================
# Script: UI_Evolution
==============================================================================
#===============================================================================
# Evolution screen
#===============================================================================
class PokemonEvolutionScene
  EVOLUTION_BGM = "Evolution"

  SPRITE_1_Y_OFFSET = -64

  # Layout and timing constants
  VIEWPORT_Z = 99999
  BG_BUFFER = 80
  NARROW_BG_BASE = 64
  NARROW_Y_DELAY = 0.2
  LERP_FAST = 0.7
  LERP_SLOW = 0.5
  LERP_MED = 0.4

  EVOLUTION_ANIM_SECONDS = 9
  ANIM_FPS = 20
  ZOOM_START = 25
  ZOOM_EXTRA = 15
  ZOOM_DEFAULT = 12

  DELAY_SHORT = 1
  FLASH_WAIT = 0.25
  TONE_MAX = 255
  MESSAGE_WAIT = 80

  def self.pbDuplicatePokemon(pkmn, new_species)
    new_pkmn = pkmn.clone
    new_pkmn.species   = new_species
    new_pkmn.name      = nil
    new_pkmn.markings  = []
    new_pkmn.poke_ball = :POKEBALL
    new_pkmn.item      = nil
    new_pkmn.clearAllRibbons
    new_pkmn.calc_stats
    new_pkmn.heal
    # Add duplicate Pokémon to party
    $player.party.push(new_pkmn)
    # See and own duplicate Pokémon
    $player.pokedex.register(new_pkmn)
    $player.pokedex.set_owned(new_species)
  end

  def pbStartScreen(pokemon, newspecies)
    @pokemon = pokemon
    @newspecies = newspecies
    @sprites = {}
    @bgviewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @bgviewport.z = VIEWPORT_Z
    @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = VIEWPORT_Z
    @msgviewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @msgviewport.z = VIEWPORT_Z
    addBackgroundOrColoredPlane(@sprites, "background", "evolution_bg",
                                Color.new(248, 248, 248), @bgviewport)
    rsprite1 = PokemonSprite.new(@viewport)
    rsprite1.setOffset(PictureOrigin::CENTER)
    rsprite1.setPokemonBitmap(@pokemon, false)
    rsprite1.x = Graphics.width / 2 
    rsprite1.y = (Graphics.height + SPRITE_1_Y_OFFSET) / 2 
    rsprite2 = PokemonSprite.new(@viewport)
    rsprite2.setOffset(PictureOrigin::CENTER)
    rsprite2.setPokemonBitmapSpecies(@pokemon, @newspecies, false)
    rsprite2.x       = rsprite1.x
    rsprite2.y       = rsprite1.y
    rsprite2.visible = false
    @sprites["rsprite1"] = rsprite1
    @sprites["rsprite2"] = rsprite2
    @sprites["msgwindow"] = pbCreateMessageWindow(@msgviewport)
    set_up_animation
    pbFadeInAndShow(@sprites) { pbUpdate }
  end

  def set_up_animation
    sprite = PictureEx.new(0)
    sprite.setVisible(0, true)
    sprite.setColor(0, Color.new(255, 255, 255, 0))
    sprite2 = PictureEx.new(0)
    sprite2.setVisible(0, true)
    sprite2.setZoom(0, 0.0)
    sprite2.setColor(0, Color.new(255, 255, 255, 255))
    # Make sprite turn white
    sprite.moveColor(0, 25, Color.new(255, 255, 255, 255))
    total_duration = EVOLUTION_ANIM_SECONDS * ANIM_FPS   # seconds * fps
    duration = ZOOM_START + ZOOM_EXTRA
    zoom_duration = ZOOM_DEFAULT
    loop do
      # Shrink prevo sprite, enlarge evo sprite
      sprite.moveZoom(duration, zoom_duration, 0)
      sprite2.moveZoom(duration, zoom_duration, 110)
      duration += zoom_duration
      # If animation has played for long enough, end it now while the evo sprite is large
      break if duration >= total_duration
      # Enlarge prevo sprite, shrink evo sprite
      sprite.moveZoom(duration, zoom_duration, 110)
      sprite2.moveZoom(duration, zoom_duration, 0)
      duration += zoom_duration
      # Shorten the duration of zoom changes for the next cycle
      zoom_duration = [(zoom_duration / 1.2).round, 2].max
    end
    @picture1 = sprite
    @picture2 = sprite2
  end

  # Opens the evolution screen
  def pbEvolution(cancancel = true)
    pbBGMStop
    pbMessageDisplay(@sprites["msgwindow"], "\\se[]" + _INTL("¡Anda!") + "\1") { pbUpdate }
    pbPlayDecisionSE
    @pokemon.play_cry
    @sprites["msgwindow"].text = _INTL("¡{1} está evolucionando!", @pokemon.name)
    timer_start = System.uptime
    loop do
      Graphics.update
      Input.update
      pbUpdate
      break if System.uptime - timer_start >= DELAY_SHORT
    end
    pbMEPlay("Evolution start")
    pbBGMPlay(EVOLUTION_BGM)
    canceled = false
    timer_start = System.uptime
    loop do
      pbUpdateNarrowScreen(timer_start)
      @picture1.update
      setPictureSprite(@sprites["rsprite1"], @picture1)
      if @sprites["rsprite1"].zoom_x > 1.0
        @sprites["rsprite1"].zoom_x = 1.0
        @sprites["rsprite1"].zoom_y = 1.0
      end
      @picture2.update
      setPictureSprite(@sprites["rsprite2"], @picture2)
      if @sprites["rsprite2"].zoom_x > 1.0
        @sprites["rsprite2"].zoom_x = 1.0
        @sprites["rsprite2"].zoom_y = 1.0
      end
      Graphics.update
      Input.update
      pbUpdate(true)
      if Input.trigger?(Input::BACK) && cancancel
        pbBGMStop
        pbPlayCancelSE
        canceled = true
        break
      end
      break if !@picture1.running? && !@picture2.running?
    end
    pbFlashInOut(canceled)
    if canceled
      $stats.evolutions_cancelled += 1
      pbMessageDisplay(@sprites["msgwindow"],
                       _INTL("¿Eh? ¡{1} dejó de evolucionar!", @pokemon.name)) { pbUpdate }
    else
      pbEvolutionSuccess
    end
  end

  def pbUpdateNarrowScreen(timer_start)
    return if @bgviewport.rect.y >= BG_BUFFER
    buffer = BG_BUFFER
    @bgviewport.rect.height = Graphics.height - lerp(0, NARROW_BG_BASE + (buffer * 2), LERP_FAST, timer_start, System.uptime).to_i
    @bgviewport.rect.y = lerp(0, buffer, LERP_SLOW, timer_start + NARROW_Y_DELAY, System.uptime).to_i
    @sprites["background"].oy = @bgviewport.rect.y
  end

  def pbUpdateExpandScreen(timer_start)
    return if @bgviewport.rect.height >= Graphics.height
    buffer = BG_BUFFER
    @bgviewport.rect.height = Graphics.height - lerp(NARROW_BG_BASE + (buffer * 2), 0, LERP_FAST, timer_start, System.uptime).to_i
    @bgviewport.rect.y = lerp(buffer, 0, LERP_SLOW, timer_start, System.uptime).to_i
    @sprites["background"].oy = @bgviewport.rect.y
  end

  def pbFlashInOut(canceled)
    timer_start = System.uptime
    loop do
      Graphics.update
      pbUpdate(true)
      pbUpdateExpandScreen(timer_start)
      tone = lerp(0, TONE_MAX, LERP_FAST, timer_start, System.uptime)
      @viewport.tone.set(tone, tone, tone, 0)
      break if tone >= TONE_MAX
    end
    @bgviewport.rect.y      = 0
    @bgviewport.rect.height = Graphics.height
    @sprites["background"].oy = 0
    if canceled
      @sprites["rsprite1"].visible     = true
      @sprites["rsprite1"].zoom_x      = 1.0
      @sprites["rsprite1"].zoom_y      = 1.0
      @sprites["rsprite1"].color.alpha = 0
      @sprites["rsprite2"].visible     = false
    else
      @sprites["rsprite1"].visible     = false
      @sprites["rsprite2"].visible     = true
      @sprites["rsprite2"].zoom_x      = 1.0
      @sprites["rsprite2"].zoom_y      = 1.0
      @sprites["rsprite2"].color.alpha = 0
    end
    timer_start = System.uptime
    loop do
      Graphics.update
      pbUpdate(true)
      break if System.uptime - timer_start >= FLASH_WAIT
    end
    timer_start = System.uptime
    loop do
      Graphics.update
      pbUpdate
      pbUpdateExpandScreen(timer_start)
      tone = lerp(TONE_MAX, 0, LERP_MED, timer_start, System.uptime)
      @viewport.tone.set(tone, tone, tone, 0)
      break if tone <= 0
    end
  end

  def pbEvolutionSuccess
    $stats.evolution_count += 1
    # Play cry of evolved species
    cry_time = GameData::Species.cry_length(@newspecies, @pokemon.form)
    Pokemon.play_cry(@newspecies, @pokemon.form)
    timer_start = System.uptime
    loop do
      Graphics.update
      pbUpdate
      break if System.uptime - timer_start >= cry_time
    end
    pbBGMStop
    # Success jingle/message
    pbMEPlay("Evolution success")
    newspeciesname = GameData::Species.get(@newspecies).name
    pbMessageDisplay(@sprites["msgwindow"],
                     "\\se[]" + _INTL("¡Enhorabuena! ¡Tu {1} evolucionó en {2}!",
                                      @pokemon.name, newspeciesname) + "\\wt[80]") { pbUpdate }
    @sprites["msgwindow"].text = ""
    # Check for consumed item and check if Pokémon should be duplicated
    pbEvolutionMethodAfterEvolution
    @pokemon.form # gets the form after evolution
    # Modify Pokémon to make it evolved
    was_fainted = @pokemon.fainted?
    @pokemon.species = @newspecies
    @pokemon.hp = 0 if was_fainted
    @pokemon.calc_stats
    @pokemon.ready_to_evolve = false
    # See and own evolved species
    was_owned = $player.owned?(@newspecies)
    $player.pokedex.register(@pokemon)
    $player.pokedex.set_owned(@newspecies)
    moves_to_learn = []
    movelist = @pokemon.getMoveList
    movelist.each do |i|
      next if i[0] != 0 && i[0] != @pokemon.level   # 0 is "learn upon evolution"
      moves_to_learn.push(i[1])
    end
    # Show Pokédex entry for new species if it hasn't been owned before
    if Settings::SHOW_NEW_SPECIES_POKEDEX_ENTRY_MORE_OFTEN && !was_owned &&
       $player.has_pokedex && $player.pokedex.species_in_unlocked_dex?(@pokemon.species)
      pbMessageDisplay(@sprites["msgwindow"],
                       _INTL("Los datos de {1} se han añadido a la Pokédex.", newspeciesname)) { pbUpdate }
      $player.pokedex.register_last_seen(@pokemon)
      pbFadeOutIn do
        scene = PokemonPokedexInfo_Scene.new
        screen = PokemonPokedexInfoScreen.new(scene)
        screen.pbDexEntry(@pokemon.species)
        @sprites["msgwindow"].text = "" if moves_to_learn.length > 0
        pbEndScreen(false) if moves_to_learn.length == 0
      end
    end
    # Learn moves upon evolution for evolved species
    moves_to_learn.each do |move|
      pbLearnMove(@pokemon, move, true) { pbUpdate }
    end
  end

  def pbEvolutionMethodAfterEvolution
    @pokemon.action_after_evolution(@newspecies)
  end

  def pbUpdate(animating = false)
    if animating      # Pokémon shouldn't animate during the evolution animation
      @sprites["background"].update
      @sprites["msgwindow"].update
    else
      pbUpdateSpriteHash(@sprites)
    end
  end

  # Closes the evolution screen.
  def pbEndScreen(need_fade_out = true)
    pbDisposeMessageWindow(@sprites["msgwindow"]) if @sprites["msgwindow"]
    if need_fade_out
      pbFadeOutAndHide(@sprites) { pbUpdate }
    end
    pbDisposeSpriteHash(@sprites)
    @viewport.dispose
    @bgviewport.dispose
    @msgviewport.dispose
  end
end


==============================================================================
# Script: UI_Trading
==============================================================================
#===============================================================================
#
#===============================================================================
class PokemonTrade_Scene
  TRADE_BGM = "Evolution"
  SPRITE_1_Y = 264
  SPRITE_1_Z = 10
  SPRITE_2_Y = 264
  SPRITE_2_Z = 10
  PICTURE_BALL_Y = 48

  # Layout / timing constants
  VIEWPORT_Z = 99999
  SRC_W = 32
  SRC_H = 64
  COLOR_MOVE_DELAY = 2
  COLOR_MOVE_DUR = 5
  ZOOM_TIME_SHORT = 8
  MOVE_TO_BALL_Y = 48
  SE_JUMP_OFFSET = 5
  VISIBLE_FADE_OFFSET = 8
  DELAY_AFTER_RECALL_SMALL = 1
  DELAY_AFTER_RECALL_LARGE = 10
  MOVE_OFF_TOP_TIME = 6
  BALL_OFFSCREEN_Y = -32
  BALL_END_OFFSET = 128
  DELAY_OFFSET_2 = 2
  BOUNCE_TIMES = [4, 4, 3, 2]
  BOUNCE_DIVS = [1, 2, 4, 8]
  BASE_ZOOM = 100
  ZOOM_VARIATION = 5
  SQUISH_TIME = 2
  OPEN_DELAY = 15
  VISIBLE_OFF_DELAY = 5
  FPS_MULT = 20
  VISIBLE_AFTER_CRY_OFFSET = 4
  MSG_WAIT_INPUT = 50

  def pbUpdate
    pbUpdateSpriteHash(@sprites)
  end

  def pbRunPictures(pictures, sprites)
    loop do
      pictures.each { |pic| pic.update }
      sprites.each_with_index do |sprite, i|
        if sprite.is_a?(IconSprite)
          setPictureIconSprite(sprite, pictures[i])
        else
          setPictureSprite(sprite, pictures[i])
        end
      end
      Graphics.update
      Input.update
      running = false
      pictures.each { |pic| running = true if pic.running? }
      break if !running
    end
  end

  def pbStartScreen(pokemon, pokemon2, trader1, trader2)
    @sprites = {}
    @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = VIEWPORT_Z
    @pokemon  = pokemon
    @pokemon2 = pokemon2
    @trader1  = trader1
    @trader2  = trader2
    addBackgroundOrColoredPlane(@sprites, "background", "trade_bg",
                                Color.new(248, 248, 248), @viewport)
    @sprites["rsprite1"] = PokemonSprite.new(@viewport)
    @sprites["rsprite1"].setPokemonBitmap(@pokemon, false)
    @sprites["rsprite1"].setOffset(PictureOrigin::BOTTOM)
    @sprites["rsprite1"].x = Graphics.width / 2
    @sprites["rsprite1"].y = SPRITE_1_Y
    @sprites["rsprite1"].z = SPRITE_1_Z
    @pokemon.species_data.apply_metrics_to_sprite(@sprites["rsprite1"], 1)
    @sprites["rsprite2"] = PokemonSprite.new(@viewport)
    @sprites["rsprite2"].setPokemonBitmap(@pokemon2, false)
    @sprites["rsprite2"].setOffset(PictureOrigin::BOTTOM)
    @sprites["rsprite2"].x = Graphics.width / 2
    @sprites["rsprite2"].y = SPRITE_2_Y
    @sprites["rsprite2"].z = SPRITE_2_Z
    @pokemon2.species_data.apply_metrics_to_sprite(@sprites["rsprite2"], 1)
    @sprites["rsprite2"].visible = false
    @sprites["msgwindow"] = pbCreateMessageWindow(@viewport)
    pbFadeInAndShow(@sprites)
  end

  def pbScene1
    spriteBall = IconSprite.new(0, 0, @viewport)
    pictureBall = PictureEx.new(0)
    picturePoke = PictureEx.new(0)
    ballimage = sprintf("Graphics/Battle animations/ball_%s", @pokemon.poke_ball)
    ballopenimage = sprintf("Graphics/Battle animations/ball_%s_open", @pokemon.poke_ball)
    # Starting position of ball
    pictureBall.setXY(0, Graphics.width / 2, PICTURE_BALL_Y)
    pictureBall.setName(0, ballimage)
    pictureBall.setSrcSize(0, SRC_W, SRC_H)
    pictureBall.setOrigin(0, PictureOrigin::CENTER)
    pictureBall.setVisible(0, true)
    # Starting position of sprite
    picturePoke.setXY(0, @sprites["rsprite1"].x, @sprites["rsprite1"].y)
    picturePoke.setOrigin(0, PictureOrigin::BOTTOM)
    picturePoke.setVisible(0, true)
    # Change Pokémon color
    picturePoke.moveColor(COLOR_MOVE_DELAY, COLOR_MOVE_DUR, Color.new(248, 176, 140))
    # Recall
    delay = picturePoke.totalDuration
    picturePoke.setSE(delay, "Battle recall")
    pictureBall.setName(delay, ballopenimage)
    pictureBall.setSrcSize(delay, 32, 64)
    # Move sprite to ball
    picturePoke.moveZoom(delay, 8, 0)
    picturePoke.moveXY(delay, 8, Graphics.width / 2, 48)
    picturePoke.setSE(delay + SE_JUMP_OFFSET, "Battle jump to ball")
    picturePoke.setVisible(delay + VISIBLE_FADE_OFFSET, false)
    delay = picturePoke.totalDuration + DELAY_AFTER_RECALL_SMALL
    pictureBall.setName(delay, ballimage)
    pictureBall.setSrcSize(delay, SRC_W, SRC_H)
    # Make Poké Ball go off the top of the screen
    delay = picturePoke.totalDuration + DELAY_AFTER_RECALL_LARGE
    pictureBall.moveXY(delay, MOVE_OFF_TOP_TIME, Graphics.width / 2, BALL_OFFSCREEN_Y)
    # Play animation
    pbRunPictures(
      [picturePoke, pictureBall],
      [@sprites["rsprite1"], spriteBall]
    )
    spriteBall.dispose
  end

  def pbScene2
    spriteBall = IconSprite.new(0, 0, @viewport)
    pictureBall = PictureEx.new(0)
    picturePoke = PictureEx.new(0)
    ballimage = sprintf("Graphics/Battle animations/ball_%s", @pokemon2.poke_ball)
    ballopenimage = sprintf("Graphics/Battle animations/ball_%s_open", @pokemon2.poke_ball)
    # Starting position of ball
    pictureBall.setXY(0, Graphics.width / 2, BALL_OFFSCREEN_Y)
    pictureBall.setName(0, ballimage)
    pictureBall.setSrcSize(0, SRC_W, SRC_H)
    pictureBall.setOrigin(0, PictureOrigin::CENTER)
    pictureBall.setVisible(0, true)
    # Starting position of sprite
    picturePoke.setOrigin(0, PictureOrigin::BOTTOM)
    picturePoke.setZoom(0, 0)
    picturePoke.setColor(0, Color.new(248, 176, 240))
    picturePoke.setVisible(0, false)
    # Dropping ball
    y = Graphics.height - BALL_END_OFFSET   # end point of Poké Ball
    delay = picturePoke.totalDuration + DELAY_OFFSET_2
    4.times do |i|
      t = BOUNCE_TIMES[i]   # Time taken to rise or fall for each bounce
      d = BOUNCE_DIVS[i]    # Fraction of the starting height each bounce rises to
      delay -= t if i == 0
      if i > 0
        pictureBall.setZoomXY(delay, BASE_ZOOM + (ZOOM_VARIATION * (5 - i)), BASE_ZOOM - (ZOOM_VARIATION * (5 - i)))   # Squish
        pictureBall.moveZoom(delay, SQUISH_TIME, BASE_ZOOM)                      # Unsquish
        pictureBall.moveXY(delay, t, Graphics.width / 2, y - (BASE_ZOOM / d))
      end
      pictureBall.moveXY(delay + t, t, Graphics.width / 2, y)
      pictureBall.setSE(delay + (2 * t), "Battle ball drop")
      delay = pictureBall.totalDuration
    end
    picturePoke.setXY(delay, Graphics.width / 2, y)
    # Open Poké Ball
    delay = pictureBall.totalDuration + OPEN_DELAY
    pictureBall.setSE(delay, "Battle recall")
    pictureBall.setName(delay, ballopenimage)
    pictureBall.setSrcSize(delay, SRC_W, SRC_H)
    pictureBall.setVisible(delay + VISIBLE_OFF_DELAY, false)
    # Pokémon appears and enlarges
    picturePoke.setVisible(delay, true)
    picturePoke.moveZoom(delay, ZOOM_TIME_SHORT, BASE_ZOOM)
    picturePoke.moveXY(delay, ZOOM_TIME_SHORT, Graphics.width / 2, @sprites["rsprite2"].y)
    # Return Pokémon's color to normal and play cry
    delay = picturePoke.totalDuration
    picturePoke.moveColor(delay, COLOR_MOVE_DUR, Color.new(248, 176, 240, 0))
    cry = GameData::Species.cry_filename_from_pokemon(@pokemon2)
    picturePoke.setSE(delay, cry) if cry
    cry_length = (GameData::Species.cry_length(@pokemon2) * FPS_MULT).ceil
    picturePoke.setVisible(delay + cry_length + VISIBLE_AFTER_CRY_OFFSET, true)   # Time for the cry to play
    # Play animation
    pbRunPictures(
      [picturePoke, pictureBall],
      [@sprites["rsprite2"], spriteBall]
    )
    spriteBall.dispose
  end

  def pbEndScreen(need_fade_out = true)
    pbDisposeMessageWindow(@sprites["msgwindow"]) if @sprites["msgwindow"]
    pbFadeOutAndHide(@sprites) if need_fade_out
    pbDisposeSpriteHash(@sprites)
    @viewport.dispose
    newspecies = @pokemon2.check_evolution_on_trade(@pokemon)
    if newspecies
      evo = PokemonEvolutionScene.new
      evo.pbStartScreen(@pokemon2, newspecies)
      evo.pbEvolution(false)
      evo.pbEndScreen
    end
  end

  def pbTrade
    was_owned = $player.owned?(@pokemon2.species)
    $player.pokedex.register(@pokemon2)
    $player.pokedex.set_owned(@pokemon2.species)
    pbBGMStop
    @pokemon.play_cry
    speciesname1 = GameData::Species.get(@pokemon.species).name
    speciesname2 = GameData::Species.get(@pokemon2.species).name
    pbMessageDisplay(@sprites["msgwindow"],
                     _ISPRINTF("{1:s}\nID: {2:05d}   OT: {3:s}",
                               @pokemon.name, @pokemon.owner.public_id, @pokemon.owner.name) + "\\wtnp[0]") { pbUpdate }
    pbMessageWaitForInput(@sprites["msgwindow"], 50, true) { pbUpdate }
    pbPlayDecisionSE
    pbBGMPlay(TRADE_BGM)
    pbScene1
    pbMessageDisplay(@sprites["msgwindow"],
                     _INTL("A cambio del {2} de {1},\n{3} envía a {4}.", @trader1, speciesname1, @trader2, speciesname2) + "\1") { pbUpdate }
    pbMessageDisplay(@sprites["msgwindow"],
                     _INTL("{1} se despide de {2}.", @trader2, speciesname2)) { pbUpdate }
    pbScene2
    pbBGMStop
    pbMEPlay("Battle capture success")
    pbMessageDisplay(@sprites["msgwindow"],
                     _ISPRINTF("{1:s}\nID: {2:05d}   OT: {3:s}",
                               @pokemon2.name, @pokemon2.owner.public_id, @pokemon2.owner.name) + "\1") { pbUpdate }
    pbMessageDisplay(@sprites["msgwindow"],
                     _INTL("Cuida bien de {1}.", speciesname2)) { pbUpdate }
    # Show Pokédex entry for new species if it hasn't been owned before
    if Settings::SHOW_NEW_SPECIES_POKEDEX_ENTRY_MORE_OFTEN && !was_owned &&
       $player.has_pokedex && $player.pokedex.species_in_unlocked_dex?(@pokemon2.species)
      pbMessageDisplay(@sprites["msgwindow"],
                       _INTL("Los datos de {1} se han añadido a la Pokédex.", speciesname2)) { pbUpdate }
      $player.pokedex.register_last_seen(@pokemon2)
      pbFadeOutIn do
        scene = PokemonPokedexInfo_Scene.new
        screen = PokemonPokedexInfoScreen.new(scene)
        screen.pbDexEntry(@pokemon2.species)
        pbEndScreen(false)
      end
    end
  end
end

#===============================================================================
#
#===============================================================================
def pbStartTrade(pokemonIndex, newpoke, nickname, trainerName, trainerGender = 0)
  $stats.trade_count += 1
  myPokemon = $player.party[pokemonIndex]
  yourPokemon = nil
  resetmoves = true
  if newpoke.is_a?(Pokemon)
    newpoke.owner = Pokemon::Owner.new_foreign(trainerName, trainerGender)
    yourPokemon = newpoke
    resetmoves = false
  else
    species_data = GameData::Species.try_get(newpoke)
    raise _INTL("La especie {1} no existe.", newpoke) if !species_data
    yourPokemon = Pokemon.new(species_data.id, myPokemon.level)
    yourPokemon.owner = Pokemon::Owner.new_foreign(trainerName, trainerGender)
  end
  yourPokemon.name          = nickname
  yourPokemon.obtain_method = 2   # traded
  yourPokemon.reset_moves if resetmoves
  yourPokemon.record_first_moves
  pbFadeOutInWithMusic do
    evo = PokemonTrade_Scene.new
    evo.pbStartScreen(myPokemon, yourPokemon, $player.name, trainerName)
    evo.pbTrade
    evo.pbEndScreen
  end
  $player.party[pokemonIndex] = yourPokemon
end


==============================================================================
# Script: UI_HallOfFame
==============================================================================
#===============================================================================
# * Hall de la Fama - por FL (Se agradecerán los créditos)
#===============================================================================
#
# Este script es para Pokémon Essentials. Crea un Salón de la Fama que se puede
# registrar como en los juegos de la Generación 3.
#
#===============================================================================
#
# Para que este script funcione, colócalo encima de Main, coloca una imagen de 
# 512x384 en hallfamebars y un fondo de 8x24 en hallfamebg. Para llamar a este 
# script, utiliza 'pbHallOfFameEntry'. Después de registrar la primera entrada, 
# puedes acceder a los equipos del Salón de la Fama usando un PC. También puedes 
# comprobar el número de la última entrada del Salón de la Fama del jugador 
# usando '$PokemonGlobal.hallOfFameLastNumber'.
#
#===============================================================================
class HallOfFame_Scene
  # Cuando es true, todos los Pokémon estarán en una sola fila.
  # Cuando es false, todos los Pokémon estarán en dos filas.
  SINGLE_ROW_OF_POKEMON = false
  # Activa el movimiento de los Pokémon en la entrada del salón.
  ANIMATION = true
  # Tiempo en segundos para que un Pokémon se deslice a su posición desde fuera 
  # de la pantalla.
  APPEAR_SPEED = 0.4
  # Tiempo de espera (en segundos) entre mostrar cada Pokémon (y entrenador).
  ENTRY_WAIT_TIME = 3.0
  # Tiempo de espera (en segundos) al mostrar "¡Bienvenido al Salón de la Fama!".
  WELCOME_WAIT_TIME = 4.0
  # Límite máximo de entradas simultáneas en el salón guardadas.
  # 0 = No guarda ningún salón. -1 = Sin límite.
  # Es preferible usar números más grandes (como 500 y 1000) que no poner límite.
  # Si un jugador supera este límite, la primera entrada será eliminada.
  HALL_ENTRIES_LIMIT = 50
  # El nombre de la música de entrada. Pon "" para no reproducir nada.
  HALL_OF_FAME_BGM = "Salón de la Fama"
  # Permite que los huevos se muestren y se guarden en el salón.
  ALLOW_EGGS = true
  # Elimina las barras del salón cuando aparece el sprite del entrenador.
  REMOVE_BARS_WHEN_SHOWING_TRAINER = true
  # La velocidad de desvanecimiento final en la entrada.
  FINAL_FADE_DURATION = 1.0
  # Valor de opacidad del sprite cuando no está seleccionado.
  OPACITY = 64
  TEXT_BASE_COLOR   = Color.new(248, 248, 248)
  TEXT_SHADOW_COLOR = Color.new(0, 0, 0)

  VIEWPORT_Z = 99999
  OVERLAY_Z = 10

  # Constantes de diseño / posiciones
  # Multiplicador X y base usados cuando los Pokémon están en una sola fila
  POINT_SINGLE_MULT = 60
  POINT_SINGLE_BASE = 48
  # Factor y base X para columnas cuando hay varias filas
  POINT_X_FACTOR = 160
  POINT_X_BASE = 96

  # Coordenadas Y base y pasos para filas en modo single/normal
  Y_SINGLE_BASE = 180
  Y_SINGLE_STEP = 32
  Y_BASE = 96
  Y_ROW_STEP = 64

  # Posición del sprite del entrenador según layout
  TRAINER_Y_SINGLE = 208
  TRAINER_X_RIGHT_OFFSET = 96
  TRAINER_Y = 160

  # Posiciones y offsets para la información del pokémon en pantalla
  DEX_X = 32
  INFO_RIGHT_OFFSET = 192
  INFO_LINE1_OFFSET = 74
  LV_X = 64
  INFO_LINE2_OFFSET = 42
  # Offset desde el centro para el número del Hall en la cabecera
  CENTER_HALF_OFFSET = 104
  HALL_LABEL_Y = 6
  # Desplazamiento vertical para el mensaje de bienvenida
  WELCOME_Y_OFFSET = 68

  # Placement for pokemon icons
  def pbStartScene
    @sprites = {}
    @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = VIEWPORT_Z
    # Comment the below line to doesn't use a background
    addBackgroundPlane(@sprites, "bg", "Hall of Fame/bg", @viewport)
    @sprites["hallbars"] = IconSprite.new(@viewport)
    @sprites["hallbars"].setBitmap("Graphics/UI/Hall of Fame/bars")
    @sprites["overlay"] = BitmapSprite.new(Graphics.width, Graphics.height, @viewport)
    @sprites["overlay"].z = OVERLAY_Z
    pbSetSystemFont(@sprites["overlay"].bitmap)
    @alreadyFadedInEnd = false
    @useMusic = false
    @battlerIndex = 0
    @hallEntry = []
    @nationalDexList = [:NONE]
    GameData::Species.each_species { |s| @nationalDexList.push(s.species) }
  end

  def pbStartSceneEntry
    pbStartScene
    @useMusic = (HALL_OF_FAME_BGM && HALL_OF_FAME_BGM != "")
    pbBGMPlay(HALL_OF_FAME_BGM) if @useMusic
    saveHallEntry
    @movements = []
    createBattlers
    pbFadeInAndShow(@sprites) { pbUpdate }
  end

  def pbStartScenePC
    pbStartScene
    @hallIndex = $PokemonGlobal.hallOfFame.size - 1
    @hallEntry = $PokemonGlobal.hallOfFame[-1]
    createBattlers(false)
    pbFadeInAndShow(@sprites) { pbUpdate }
    pbUpdatePC
  end

  def pbEndScene
    $game_map.autoplay if @useMusic
    pbDisposeMessageWindow(@sprites["msgwindow"]) if @sprites.include?("msgwindow")
    pbFadeOutAndHide(@sprites) { pbUpdate } if !@alreadyFadedInEnd
    pbDisposeSpriteHash(@sprites)
    @viewport.dispose
  end

  def slowFadeOut(duration)
    col = Color.new(0, 0, 0, 0)
    timer_start = System.uptime
    loop do
      col.alpha = lerp(0, 255, duration, timer_start, System.uptime)
      @viewport.color = col
      Graphics.update
      Input.update
      pbUpdate
      break if col.alpha == 255
    end
  end

  # Dispose the sprite if the sprite exists and make it null
  def restartSpritePosition(sprites, spritename)
    sprites[spritename].dispose if sprites.include?(spritename) && sprites[spritename]
    sprites[spritename] = nil
  end

  # Change the pokémon sprites opacity except the index one
  def setPokemonSpritesOpacity(index, opacity = 255)
    @hallEntry.size.times do |n|
      @sprites["pokemon#{n}"].opacity = (n == index) ? 255 : opacity if @sprites["pokemon#{n}"]
    end
  end

  def saveHallEntry
    $player.party.each do |pkmn|
      # Clones every pokémon object
      @hallEntry.push(pkmn.clone) if !pkmn.egg? || ALLOW_EGGS
    end
    # Update the global variables
    $PokemonGlobal.hallOfFame.push(@hallEntry)
    $PokemonGlobal.hallOfFameLastNumber += 1
    if HALL_ENTRIES_LIMIT >= 0 && $PokemonGlobal.hallOfFame.size > HALL_ENTRIES_LIMIT
      $PokemonGlobal.hallOfFame.delete_at(0)
    end
  end

  # Return the x/y point position in screen for battler index number
  # Don't use odd numbers!
  def xpointformula(battlernumber)
    if SINGLE_ROW_OF_POKEMON
      ret = ((POINT_SINGLE_MULT * (battlernumber / 2)) + POINT_SINGLE_BASE) * (xpositionformula(battlernumber) - 1)
      return ret + (Graphics.width / 2)
    end
    return POINT_X_BASE + (POINT_X_FACTOR * xpositionformula(battlernumber))
  end

  def ypointformula(battlernumber)
    return Y_SINGLE_BASE - (Y_SINGLE_STEP * (battlernumber / 2)) if SINGLE_ROW_OF_POKEMON
    return Y_BASE + (Y_ROW_STEP * ypositionformula(battlernumber))
  end

  # Returns 0, 1 or 2 as the x position value (left, middle, right column)
  def xpositionformula(battlernumber)
    return (battlernumber % 2) * 2 if SINGLE_ROW_OF_POKEMON       # 0, 2, 0, 2, 0, 2
    return (1 - battlernumber) % 3 if (battlernumber / 3).even?   # First 3 mons: 1, 0, 2
    return (1 + battlernumber) % 3                                # Second 3 mons: 1, 2, 0
  end

  # Returns 0, 1 or 2 as the y position value (top, middle, bottom row)
  def ypositionformula(battlernumber)
    return 1 if SINGLE_ROW_OF_POKEMON      # 1, 1, 1, 1, 1, 1
    return ((battlernumber / 3) % 2) * 2   # 0, 0, 0, 2, 2, 2
  end

  def moveSprite(i)
    spritename = (i > -1) ? "pokemon#{i}" : "trainer"
    if !ANIMATION   # Skips animation, place directly in end position
      @sprites[spritename].x = @movements[i][1]
      @sprites[spritename].y = @movements[i][3]
      @movements[i][0] = @movements[i][1]
      @movements[i][2] = @movements[i][3]
      return
    end
    @movements[i][4] = System.uptime if !@movements[i][4]
    speed = (i > -1) ? APPEAR_SPEED : APPEAR_SPEED * 3
    @sprites[spritename].x = lerp(@movements[i][0], @movements[i][1], speed, @movements[i][4], System.uptime)
    @sprites[spritename].y = lerp(@movements[i][2], @movements[i][3], speed, @movements[i][4], System.uptime)
    @movements[i][0] = @movements[i][1] if @sprites[spritename].x == @movements[i][1]
    @movements[i][2] = @movements[i][3] if @sprites[spritename].y == @movements[i][3]
  end

  def createBattlers(hide = true)
    # Movement in animation
    Settings::MAX_PARTY_SIZE.times do |i|
      # Clear all pokémon sprites and dispose the ones that exists every time
      # that this method is call
      restartSpritePosition(@sprites, "pokemon#{i}")
      next if i >= @hallEntry.size
      end_x = xpointformula(i)
      end_y = ypointformula(i)
      @sprites["pokemon#{i}"] = PokemonSprite.new(@viewport)
      @sprites["pokemon#{i}"].setPokemonBitmap(@hallEntry[i])
      # This method doesn't put the exact coordinates
      @sprites["pokemon#{i}"].x = end_x
      @sprites["pokemon#{i}"].y = end_y
      @sprites["pokemon#{i}"].z = Settings::MAX_PARTY_SIZE - i if SINGLE_ROW_OF_POKEMON
      next if !hide
      # Animation distance calculation
      x_direction = xpositionformula(i) - 1
      y_direction = ypositionformula(i) - 1
      distance = 0
      if y_direction == 0
        distance = (x_direction > 0) ? end_x : Graphics.width - end_x
        distance += @sprites["pokemon#{i}"].bitmap.width / 2
      else
        distance = (y_direction > 0) ? end_y : Graphics.height - end_y
        distance += @sprites["pokemon#{i}"].bitmap.height / 2
      end
      start_x = end_x - (x_direction * distance)
      start_y = end_y - (y_direction * distance)
      @sprites["pokemon#{i}"].x = start_x
      @sprites["pokemon#{i}"].y = start_y
      @movements[i] = [start_x, end_x, start_y, end_y]
    end
  end

  def createTrainerBattler
    @sprites["trainer"] = IconSprite.new(@viewport)
    @sprites["trainer"].setBitmap(GameData::TrainerType.player_front_sprite_filename($player.trainer_type))
    if SINGLE_ROW_OF_POKEMON
      @sprites["trainer"].x = Graphics.width / 2
      @sprites["trainer"].y = TRAINER_Y_SINGLE
    else
      @sprites["trainer"].x = Graphics.width - TRAINER_X_RIGHT_OFFSET
      @sprites["trainer"].y = TRAINER_Y
    end
    @movements.push([Graphics.width / 2, @sprites["trainer"].x, @sprites["trainer"].y, @sprites["trainer"].y])
    @sprites["trainer"].z = 9
    @sprites["trainer"].ox = @sprites["trainer"].bitmap.width / 2
    @sprites["trainer"].oy = @sprites["trainer"].bitmap.height / 2
    if REMOVE_BARS_WHEN_SHOWING_TRAINER
      @sprites["overlay"].bitmap.clear
      @sprites["hallbars"].visible = false
    end
    if ANIMATION && !SINGLE_ROW_OF_POKEMON   # Trainer Animation
      @sprites["trainer"].x = @movements.last[0]
    else
      timer_start = System.uptime
      loop do
        Graphics.update
        Input.update
        pbUpdate
        break if System.uptime - timer_start >= ENTRY_WAIT_TIME
      end
    end
  end

  def writeTrainerData
    if $PokemonGlobal.hallOfFameLastNumber == 1
      totalsec = $stats.time_to_enter_hall_of_fame.to_i
    else
      totalsec = $stats.play_time.to_i
    end
    hour = totalsec / 60 / 60
    min = totalsec / 60 % 60
    pubid = sprintf("%05d", $player.public_ID)
    lefttext = _INTL("Nombre<r>{1}", $player.name) + "<br>"
    lefttext += _INTL("No. ID<r>{1}", pubid) + "<br>"
    if hour > 0
      lefttext += _INTL("Tiempo<r>{1}h {2}m", hour, min) + "<br>"
    else
      lefttext += _INTL("Tiempo<r>{1}m", min) + "<br>"
    end
    lefttext += _INTL("Pokédex<r>{1}/{2}",
                      $player.pokedex.owned_count, $player.pokedex.seen_count) + "<br>"
    @sprites["messagebox"] = Window_AdvancedTextPokemon.new(lefttext)
    @sprites["messagebox"].viewport = @viewport
    @sprites["messagebox"].width = 192 if @sprites["messagebox"].width < 192
    @sprites["msgwindow"] = pbCreateMessageWindow(@viewport)
    pbMessageDisplay(@sprites["msgwindow"],
                     _INTL("¡Campeón de la Liga!\n¡Enhorabuena!") + "\\^")
  end

  def writePokemonData(pokemon, hallNumber = -1)
    overlay = @sprites["overlay"].bitmap
    overlay.clear
    pokename = pokemon.name
    speciesname = pokemon.speciesName
    if pokemon.male?
      speciesname += "♂"
    elsif pokemon.female?
      speciesname += "♀"
    end
    pokename += "/" + speciesname
    pokename = _INTL("Huevo") + "/" + _INTL("Huevo") if pokemon.egg?
    idno = (pokemon.owner.name.empty? || pokemon.egg?) ? "?????" : sprintf("%05d", pokemon.owner.public_id)
    dexnumber = _INTL("No. ???")
    if !pokemon.egg?
      number = @nationalDexList.index(pokemon.species) || 0
      dexnumber = _ISPRINTF("No. {1:03d}", number)
    end
    textPositions = [
      [dexnumber, DEX_X, Graphics.height - INFO_LINE1_OFFSET, :left, TEXT_BASE_COLOR, TEXT_SHADOW_COLOR],
      [pokename, Graphics.width - INFO_RIGHT_OFFSET, Graphics.height - INFO_LINE1_OFFSET, :center, TEXT_BASE_COLOR, TEXT_SHADOW_COLOR],
      [_INTL("Nv. {1}", pokemon.egg? ? "?" : pokemon.level),
       LV_X, Graphics.height - INFO_LINE2_OFFSET, :left, TEXT_BASE_COLOR, TEXT_SHADOW_COLOR],
      [_INTL("No. ID {1}", pokemon.egg? ? "?????" : idno),
       Graphics.width - INFO_RIGHT_OFFSET, Graphics.height - INFO_LINE2_OFFSET, :center, TEXT_BASE_COLOR, TEXT_SHADOW_COLOR]
    ]
    if hallNumber > -1
      textPositions.push([_INTL("Hall de la Fama No."), (Graphics.width / 2) - CENTER_HALF_OFFSET, HALL_LABEL_Y, :left, TEXT_BASE_COLOR, TEXT_SHADOW_COLOR])
      textPositions.push([hallNumber.to_s, (Graphics.width / 2) + CENTER_HALF_OFFSET, HALL_LABEL_Y, :right, TEXT_BASE_COLOR, TEXT_SHADOW_COLOR])
    end
    pbDrawTextPositions(overlay, textPositions)
  end

  def writeWelcome
    overlay = @sprites["overlay"].bitmap
    overlay.clear
    pbDrawTextPositions(overlay, [[_INTL("¡Bienvenido al Hall de la Fama!"),
                                   Graphics.width / 2, Graphics.height - WELCOME_Y_OFFSET, :center, TEXT_BASE_COLOR, TEXT_SHADOW_COLOR]])
  end

  def pbAnimationLoop
    loop do
      Graphics.update
      Input.update
      pbUpdate
      pbUpdateAnimation
      break if @battlerIndex == @hallEntry.size + 2
    end
  end

  def pbPCSelection
    loop do
      Graphics.update
      Input.update
      pbUpdate
      continueScene = true
      break if Input.trigger?(Input::BACK)   # Exits
      if Input.trigger?(Input::USE)   # Moves the selection one entry backward
        @battlerIndex += 10
        continueScene = pbUpdatePC
      end
      if Input.trigger?(Input::LEFT)   # Moves the selection one pokémon forward
        @battlerIndex -= 1
        continueScene = pbUpdatePC
      end
      if Input.trigger?(Input::RIGHT)   # Moves the selection one pokémon backward
        @battlerIndex += 1
        continueScene = pbUpdatePC
      end
      break if !continueScene
    end
  end

  def pbUpdate
    pbUpdateSpriteHash(@sprites)
  end

  def pbUpdateAnimation
    if @battlerIndex <= @hallEntry.size
      if @movements[@battlerIndex] &&
         (@movements[@battlerIndex][0] != @movements[@battlerIndex][1] ||
         @movements[@battlerIndex][2] != @movements[@battlerIndex][3])
        spriteIndex = (@battlerIndex < @hallEntry.size) ? @battlerIndex : -1
        moveSprite(spriteIndex)
      else
        @battlerIndex += 1
        if @battlerIndex <= @hallEntry.size
          # If it is a pokémon, write the pokémon text, wait the
          # ENTRY_WAIT_TIME and goes to the next battler
          @hallEntry[@battlerIndex - 1].play_cry
          writePokemonData(@hallEntry[@battlerIndex - 1])
          timer_start = System.uptime
          loop do
            Graphics.update
            Input.update
            pbUpdate
            break if System.uptime - timer_start >= ENTRY_WAIT_TIME
          end
          if @battlerIndex < @hallEntry.size   # Preparates the next battler
            setPokemonSpritesOpacity(@battlerIndex, OPACITY)
            @sprites["overlay"].bitmap.clear
          else   # Show the welcome message and prepares the trainer
            setPokemonSpritesOpacity(-1)
            writeWelcome
            timer_start = System.uptime
            loop do
              Graphics.update
              Input.update
              pbUpdate
              break if System.uptime - timer_start >= WELCOME_WAIT_TIME
            end
            setPokemonSpritesOpacity(-1, OPACITY) if !SINGLE_ROW_OF_POKEMON
            createTrainerBattler
          end
        end
      end
    elsif @battlerIndex > @hallEntry.size
      # Write the trainer data and fade
      writeTrainerData
      timer_start = System.uptime
      loop do
        Graphics.update
        Input.update
        pbUpdate
        break if System.uptime - timer_start >= ENTRY_WAIT_TIME
      end
      pbBGMFade(FINAL_FADE_DURATION) if @useMusic
      slowFadeOut(FINAL_FADE_DURATION)
      @alreadyFadedInEnd = true
      @battlerIndex += 1
    end
  end

  def pbUpdatePC
    # Change the team
    if @battlerIndex >= @hallEntry.size
      @hallIndex -= 1
      return false if @hallIndex == -1
      @hallEntry = $PokemonGlobal.hallOfFame[@hallIndex]
      @battlerIndex = 0
      createBattlers(false)
    elsif @battlerIndex < 0
      @hallIndex += 1
      return false if @hallIndex >= $PokemonGlobal.hallOfFame.size
      @hallEntry = $PokemonGlobal.hallOfFame[@hallIndex]
      @battlerIndex = @hallEntry.size - 1
      createBattlers(false)
    end
    # Change the pokemon
    @hallEntry[@battlerIndex].play_cry
    setPokemonSpritesOpacity(@battlerIndex, OPACITY)
    hallNumber = $PokemonGlobal.hallOfFameLastNumber + @hallIndex -
                 $PokemonGlobal.hallOfFame.size + 1
    writePokemonData(@hallEntry[@battlerIndex], hallNumber)
    return true
  end
end

#===============================================================================
#
#===============================================================================
class HallOfFameScreen
  def initialize(scene)
    @scene = scene
  end

  def pbStartScreenEntry
    @scene.pbStartSceneEntry
    @scene.pbAnimationLoop
    @scene.pbEndScene
  end

  def pbStartScreenPC
    @scene.pbStartScenePC
    @scene.pbPCSelection
    @scene.pbEndScene
  end
end

#===============================================================================
#
#===============================================================================
MenuHandlers.add(:pc_menu, :hall_of_fame, {
  "name"      => _INTL("Hall de la Fama"),
  "order"     => 40,
  "condition" => proc { next $PokemonGlobal.hallOfFameLastNumber > 0 },
  "effect"    => proc { |menu|
    pbMessage("\\se[PC access]" + _INTL("Has accedido al Hall de la Fama."))
    pbHallOfFamePC
    next false
  }
})

#===============================================================================
#
#===============================================================================
class PokemonGlobalMetadata
  attr_writer :hallOfFame
  # Number necessary if hallOfFame array reach in its size limit
  attr_writer :hallOfFameLastNumber

  def hallOfFame
    @hallOfFame = [] if !@hallOfFame
    return @hallOfFame
  end

  def hallOfFameLastNumber
    return @hallOfFameLastNumber || 0
  end
end

#===============================================================================
#
#===============================================================================
def pbHallOfFameEntry
  scene = HallOfFame_Scene.new
  screen = HallOfFameScreen.new(scene)
  screen.pbStartScreenEntry
end

def pbHallOfFamePC
  scene = HallOfFame_Scene.new
  screen = HallOfFameScreen.new(scene)
  screen.pbStartScreenPC
end


==============================================================================
# Script: UI_Credits
==============================================================================
#==============================================================================
# * Scene_Credits
#------------------------------------------------------------------------------
# Desplaza los créditos que escribas debajo. Autor original desconocido.
#
## Editado por MiDas Mike para que no se reproduzca sobre el Título, sino que se
# ejecute llamando a lo siguiente:
#    $scene = Scene_Credits.new
#
## Nueva Edición 3/6/2007 11:14 PM por AvatarMonkeyKirby.
# Bueno, lo que he hecho es cambiar la parte del script que supuestamente hacía
# que los créditos terminaran automáticamente ¡para que realmente terminen! Sí, 
# terminarán de verdad cuando los créditos hayan terminado. Así que, las 
# personas a las que ahora debes dar crédito son: Desconocido, MiDas Mike y 
# AvatarMonkeyKirby.
#        - sinceramente tuyo,
#            Tu Amado
# Ah, sí, y también añadí una línea de código que atenúa el BGM para que se 
# desvanezca más rápido y suavemente.
#
## Nueva Edición 24/1/2012 por Maruno.
# Se añadió la capacidad de dividir una línea en dos mitades con <s>, con cada
# mitad alineada hacia el centro. Por favor, también dame créditos si se utiliza.
#
## Nueva Edición 22/2/2012 por Maruno.
# Los créditos ahora se desplazan correctamente cuando se reproducen con un 
# factor de zoom de 0.5. Se puede definir la música ahora. Los créditos no 
# pueden ser omitidos durante su primera reproducción.
#
## Nueva Edición 25/3/2020 por Maruno.
# La velocidad de desplazamiento ahora es independiente de la frecuencia de 
# cuadros. Ahora admite valores no enteros para SCROLL_SPEED.
#
## Nueva Edición 21/8/2020 por Marin.
# Ahora inserta automáticamente los créditos de los complementos que han sido
# registrados a través del módulo PluginManager.
#==============================================================================
class Scene_Credits
  # Backgrounds to show in credits. Found in Graphics/Titles/ folder
  BACKGROUNDS_LIST       = ["credits1", "credits2", "credits3", "credits4", "credits5"]
  CREDITS_BGM                    = "Credits"
  SCROLL_SPEED           = 40   # Pixels per second
  SECONDS_PER_BACKGROUND = 11
  TEXT_OUTLINE_COLOR     = Color.new(0, 0, 128, 255)
  TEXT_BASE_COLOR        = Color.new(255, 255, 255, 255)
  TEXT_SHADOW_COLOR      = Color.new(0, 0, 0, 100)

  # Constantes de layout y temporización
  # Altura en píxeles de cada línea de crédito
  LINE_HEIGHT = 32
  # Relleno vertical añadido al bitmap de créditos
  BITMAP_PADDING = 16
  # Factor de recorte para calcular el trim: Graphics.height / TRIM_DIVISOR
  TRIM_DIVISOR = 10
  # Margen usado al dividir una línea en dos mitades con <s>
  SPLIT_MARGIN = 20
  # Desplazamientos Y usados para dibujar sombras/contornos/texto base
  TEXT_Y_SHADOW = 12
  TEXT_Y_OUTLINE_TOP = 2
  TEXT_Y_BASE = 4
  TEXT_Y_OUTLINE_BOTTOM = 6
  # Desplazamiento X para contornos (izquierda/derecha)
  TEXT_X_OFFSET = 2

  # Z para viewports y sprites usados en créditos
  VIEWPORT_Z = 99999
  TEXT_VIEWPORT_Z = 99999
  CREDIT_SPRITE_Z = 9998

  # Duraciones usadas para fundidos y transiciones
  BGM_FADE_DURATION = 2.0
  TRANSITION_FADE_DURATION = 8

  def add_names_to_credits(credits, names, with_final_new_line = true)
    if names.length >= 5
      i = 0
      loop do
        credits.push(names[i] + "<s>" + (names[i + 1] || ""))
        i += 2
        break if i >= names.length
      end
    else
      names.each { |name| credits.push(name) }
    end
    credits.push("") if with_final_new_line
  end

  def get_text
    ret = Settings.game_credits || []
    # Add plugin credits
    if PluginManager.plugins.length > 0
      ret.push("", "", "")
      PluginManager.plugins.each do |plugin|
        pcred = PluginManager.credits(plugin)
        ret.push(_INTL("\"{1}\" v.{2} por:", plugin, PluginManager.version(plugin)))
        add_names_to_credits(ret, pcred)
      end
    end
    # Add Essentials credits
    ret.push("", "", "")
    ret.push(_INTL("\"Pokémon Essentials\" ha sido creado por:"))
    add_names_to_credits(ret, [
      "Poccil (Peter O.)",
      "Maruno",
      _INTL("Inspirado en el trabajo de Flameguru")
    ])
    ret.push(_INTL("Con contribuciones de:"))
    add_names_to_credits(ret, [
      "AvatarMonkeyKirby", "Boushy", "Brother1440", "FL.", "Genzai Kawakami",
      "Golisopod User", "help-14", "IceGod64", "Jacob O. Wobbrock", "KitsuneKouta",
      "Lisa Anthony", "Luka S.J.", "Marin", "MiDas Mike", "Near Fantastica",
      "PinkMan", "Popper", "Rataime", "Savordez", "SoundSpawn",
      "the__end", "Venom12", "Wachunga"
    ], false)
    ret.push(_INTL("y todos los demás que han ayudado"))
    ret.push("")
    ret.push(_INTL("\"mkxp-z\" por:"))
    add_names_to_credits(ret, [
      "Roza",
      _INTL("Basado en \"mkxp\" por Ancurio et al.")
    ])
    ret.push(_INTL("\"RPG Maker XP\" por:"))
    add_names_to_credits(ret, ["Enterbrain"])
    ret.push(_INTL("Pokémon es propiedad de:"))
    add_names_to_credits(ret, [
      "The Pokémon Company",
      "Nintendo",
      _INTL("Afilicado con Game Freak")
    ])
    ret.push("", "")
    ret.push(_INTL("Esto es un fanjuego sin ánimo de lucro."),
             _INTL("No se pretende infringir los derechos de autor."),
             _INTL("¡Por favor, apoya los juegos oficiales!"))
    return ret
  end

  def main
    @quit = false
    #-------------------------------
    # Animated Background Setup
    #-------------------------------
    @timer_start = System.uptime   # Time when the credits started
    @bg_index = 0
    @bitmap_height = Graphics.height   # For a single credits text bitmap
    @trim = Graphics.height / TRIM_DIVISOR
    # Number of game frames per background frame
    @realOY = -(Graphics.height - @trim)
    #-------------------------------
    # Credits text Setup
    #-------------------------------
    credit_lines = get_text
    #-------------------------------
    # Make background and text sprites
    #-------------------------------
    viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    viewport.z = VIEWPORT_Z
    text_viewport = Viewport.new(0, @trim, Graphics.width, Graphics.height - (@trim * 2))
    text_viewport.z = TEXT_VIEWPORT_Z
    @background_sprite = IconSprite.new(0, 0)
    @background_sprite.setBitmap("Graphics/Titles/" + BACKGROUNDS_LIST[0])
    @credit_sprites = []
    @total_height = credit_lines.size * LINE_HEIGHT
    lines_per_bitmap = @bitmap_height / LINE_HEIGHT
    num_bitmaps = (credit_lines.size.to_f / lines_per_bitmap).ceil
    num_bitmaps.times do |i|
      credit_bitmap = Bitmap.new(Graphics.width, @bitmap_height + BITMAP_PADDING)
      pbSetSystemFont(credit_bitmap)
      lines_per_bitmap.times do |j|
        line = credit_lines[(i * lines_per_bitmap) + j]
        next if !line
        line += " " if line.end_with?("<s>")
        line = line.split("<s>")
        xpos = 0
        align = 1   # Centre align
        linewidth = Graphics.width
        line.length.times do |k|
          text = line[k].strip
          if line.length > 1
            xpos = (k == 0) ? 0 : SPLIT_MARGIN + (Graphics.width / 2)
            align = (k == 0) ? 2 : 0   # Right align : left align
            linewidth = (Graphics.width / 2) - SPLIT_MARGIN
          end
          credit_bitmap.font.color = TEXT_SHADOW_COLOR
          credit_bitmap.draw_text(xpos, (j * LINE_HEIGHT) + TEXT_Y_SHADOW, linewidth, LINE_HEIGHT, text, align)
          credit_bitmap.font.color = TEXT_OUTLINE_COLOR
          credit_bitmap.draw_text(xpos + TEXT_X_OFFSET, (j * LINE_HEIGHT) + TEXT_Y_OUTLINE_TOP, linewidth, LINE_HEIGHT, text, align)
          credit_bitmap.draw_text(xpos,                   (j * LINE_HEIGHT) + TEXT_Y_OUTLINE_TOP, linewidth, LINE_HEIGHT, text, align)
          credit_bitmap.draw_text(xpos - TEXT_X_OFFSET, (j * LINE_HEIGHT) + TEXT_Y_OUTLINE_TOP, linewidth, LINE_HEIGHT, text, align)
          credit_bitmap.draw_text(xpos + TEXT_X_OFFSET, (j * LINE_HEIGHT) + TEXT_Y_BASE, linewidth, LINE_HEIGHT, text, align)
          credit_bitmap.draw_text(xpos - TEXT_X_OFFSET, (j * LINE_HEIGHT) + TEXT_Y_BASE, linewidth, LINE_HEIGHT, text, align)
          credit_bitmap.draw_text(xpos + TEXT_X_OFFSET, (j * LINE_HEIGHT) + TEXT_Y_OUTLINE_BOTTOM, linewidth, LINE_HEIGHT, text, align)
          credit_bitmap.draw_text(xpos,                   (j * LINE_HEIGHT) + TEXT_Y_OUTLINE_BOTTOM, linewidth, LINE_HEIGHT, text, align)
          credit_bitmap.draw_text(xpos - TEXT_X_OFFSET, (j * LINE_HEIGHT) + TEXT_Y_OUTLINE_BOTTOM, linewidth, LINE_HEIGHT, text, align)
          credit_bitmap.font.color = TEXT_BASE_COLOR
          credit_bitmap.draw_text(xpos, (j * LINE_HEIGHT) + TEXT_Y_BASE, linewidth, LINE_HEIGHT, text, align)
        end
      end
      credit_sprite = Sprite.new(text_viewport)
      credit_sprite.bitmap = credit_bitmap
      credit_sprite.z      = CREDIT_SPRITE_Z
      credit_sprite.oy     = @realOY - (@bitmap_height * i)
      @credit_sprites[i] = credit_sprite
    end
    #-------------------------------
    # Setup
    #-------------------------------
    # Stops all audio but background music
    previousBGM = $game_system.getPlayingBGM
    pbMEStop
    pbBGSStop
    pbSEStop
    pbBGMFade(BGM_FADE_DURATION)
    pbBGMPlay(CREDITS_BGM)
    Graphics.transition
    loop do
      Graphics.update
      Input.update
      update
      break if @quit
    end
    $game_temp.background_bitmap = Graphics.snap_to_bitmap
    pbBGMFade(BGM_FADE_DURATION)
    Graphics.freeze
    viewport.color = Color.black   # Ensure screen is black
    text_viewport.color = Color.black   # Ensure screen is black
    Graphics.transition(TRANSITION_FADE_DURATION, "fadetoblack")
    $game_temp.background_bitmap.dispose
    @background_sprite.dispose
    @credit_sprites.each { |s| s&.dispose }
    viewport.dispose
    text_viewport.dispose
    $PokemonGlobal.creditsPlayed = true
    pbBGMPlay(previousBGM)
    $scene = ($game_map) ? Scene_Map.new : nil
  end

  # Check if the credits should be cancelled
  def cancel?
    @quit = true if Input.trigger?(Input::USE) && $PokemonGlobal.creditsPlayed
    return @quit
  end

  # Checks if credits bitmap has reached its ending point
  def last?
    @quit = true if @realOY > @total_height + @trim
    return @quit
  end

  def update
    # Go to next slide
    new_bg_index = ((System.uptime - @timer_start) / SECONDS_PER_BACKGROUND) % BACKGROUNDS_LIST.length
    if @bg_index != new_bg_index
      @bg_index = new_bg_index
      @background_sprite.setBitmap("Graphics/Titles/" + BACKGROUNDS_LIST[@bg_index])
    end
    return if cancel?
    return if last?
    @realOY = (SCROLL_SPEED * (System.uptime - @timer_start)) - Graphics.height + @trim
    @credit_sprites.each_with_index { |s, i| s.oy = @realOY - (@bitmap_height * i) }
  end
end


