class TriadSquare
  attr_accessor :owner, :card, :type

  def initialize
    @owner = 0
    @card  = nil
    @type  = nil
  end

  def attack(panel)
    return @card.attack(panel)
  end

  def bonus(square)
    return @card.bonus(square.card)
  end

  def defense(panel)
    return @card.defense(panel)
  end
end

#===============================================================================
# Scene class for handling appearance of the screen
#===============================================================================
class TriadScene

  TRIPLE_TRIAD_BGM = "Triple Triad"

  def pbStartScene(battle)
    @sprites = {}
    @bitmaps = []
    @battle = battle
    # Allocate viewport
    @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = 99999
    addBackgroundPlane(@sprites, "background", "Triple Triad/bg", @viewport)
    @sprites["helpwindow"] = Window_AdvancedTextPokemon.newWithSize(
      "", 0, Graphics.height - 64, Graphics.width, 64, @viewport
    )
    (@battle.width * @battle.height).times do |i|
      @sprites["sprite#{i}"] = Sprite.new(@viewport)
      @sprites["sprite#{i}"].x = (Graphics.width / 2) - 118 + ((i % 3) * 78)
      @sprites["sprite#{i}"].y = 36 + ((i / 3) * 94)
      @sprites["sprite#{i}"].z = 2
      bm = TriadCard.createBack(@battle.board[i].type, true)
      @bitmaps.push(bm)
      @sprites["sprite#{i}"].bitmap = bm
    end
    @cardBitmaps         = []
    @opponentCardBitmaps = []
    @cardIndexes         = []
    @opponentCardIndexes = []
    @boardSprites        = []
    @boardCards          = []
    @battle.maxCards.times do |i|
      @sprites["player#{i}"] = Sprite.new(@viewport)
      @sprites["player#{i}"].x = Graphics.width - 92
      @sprites["player#{i}"].y = 44 + (44 * i)
      @sprites["player#{i}"].z = 2
      @cardIndexes.push(i)
    end
    @sprites["overlay"] = Sprite.new(@viewport)
    @sprites["overlay"].bitmap = Bitmap.new(Graphics.width, Graphics.height)
    pbSetSystemFont(@sprites["overlay"].bitmap)
    pbDrawTextPositions(
      @sprites["overlay"].bitmap,
      [[@battle.opponentName, 52, 10, :center, Color.new(248, 248, 248), Color.new(96, 96, 96)],
       [@battle.playerName, Graphics.width - 52, 10, :center, Color.new(248, 248, 248), Color.new(96, 96, 96)]]
    )
    @sprites["score"] = Sprite.new(@viewport)
    @sprites["score"].bitmap = Bitmap.new(Graphics.width, Graphics.height)
    pbSetSystemFont(@sprites["score"].bitmap)
    pbBGMPlay(TRIPLE_TRIAD_BGM)
    # Fade in all sprites
    pbFadeInAndShow(@sprites) { pbUpdate }
  end

  def pbEndScene
    pbBGMFade(1.0)
    pbFadeOutAndHide(@sprites) { pbUpdate }
    pbDisposeSpriteHash(@sprites)
    @bitmaps.each { |bm| bm.dispose }
    @viewport.dispose
  end

  def pbDisplay(text)
    @sprites["helpwindow"].text = text
    timer_start = System.uptime
    loop do
      Graphics.update
      Input.update
      pbUpdate
      break if System.uptime - timer_start >= 1.5
    end
  end

  def pbDisplayPaused(text)
    @sprites["helpwindow"].letterbyletter = true
    @sprites["helpwindow"].text           = text + "\1"
    loop do
      Graphics.update
      Input.update
      pbUpdate
      if Input.trigger?(Input::USE)
        if @sprites["helpwindow"].busy?
          pbPlayDecisionSE if @sprites["helpwindow"].pausing?
          @sprites["helpwindow"].resume
        else
          break
        end
      end
    end
    @sprites["helpwindow"].letterbyletter = false
    @sprites["helpwindow"].text           = ""
  end

  def pbNotifyCards(playerCards, opponentCards)
    @playerCards   = playerCards
    @opponentCards = opponentCards
  end

  def pbChooseTriadCard(cardStorage)
    commands    = []
    chosenCards = []
    cardStorage.each do |item|
      commands.push(_INTL("{1} x{2}", GameData::Species.get(item[0]).name, item[1]))
    end
    command = Window_CommandPokemonEx.newWithSize(commands, 0, 0, Graphics.width / 2, Graphics.height - 64, @viewport)
    @sprites["helpwindow"].text = _INTL("Elige {1} cartas para usarlas en este duelo.", @battle.maxCards)
    preview = Sprite.new(@viewport)
    preview.x = (Graphics.width / 2) + 20
    preview.y = 60
    preview.z = 4
    index = -1
    @battle.maxCards.times do |i|
      @sprites["player#{i}"] = Sprite.new(@viewport)
      @sprites["player#{i}"].x = Graphics.width - 92
      @sprites["player#{i}"].y = 44 + (44 * i)
      @sprites["player#{i}"].z = 2
    end
    loop do
      Graphics.update
      Input.update
      pbUpdate
      command.update
      if command.index != index
        preview.bitmap&.dispose
        if command.index < cardStorage.length
          item = cardStorage[command.index]
          preview.bitmap = TriadCard.new(item[0]).createBitmap(1)
        end
        index = command.index
      end
      if Input.trigger?(Input::BACK)
        if chosenCards.length > 0
          item = chosenCards.pop
          @battle.pbAdd(cardStorage, item)
          commands = []
          cardStorage.each do |itm|
            commands.push(_INTL("{1} x{2}", GameData::Species.get(itm[0]).name, itm[1]))
          end
          command.commands = commands
          index = -1
        else
          pbPlayBuzzerSE
        end
      elsif Input.trigger?(Input::USE)
        break if chosenCards.length == @battle.maxCards
        item = cardStorage[command.index]
        if !item || @battle.quantity(cardStorage, item[0]) == 0
          pbPlayBuzzerSE
        else
          pbPlayDecisionSE
          sprite = @sprites["player#{chosenCards.length}"]
          sprite.bitmap&.dispose
          @cardBitmaps[chosenCards.length] = TriadCard.new(item[0]).createBitmap(1)
          sprite.bitmap = @cardBitmaps[chosenCards.length]
          chosenCards.push(item[0])
          @battle.pbSubtract(cardStorage, item[0])
          commands = []
          cardStorage.each do |itm|
            commands.push(_INTL("{1} x{2}", GameData::Species.get(itm[0]).name, itm[1]))
          end
          command.commands = commands
          command.index = commands.length - 1 if command.index >= commands.length
          index = -1
        end
      end
      if Input.trigger?(Input::USE) || Input.trigger?(Input::BACK)
        @battle.maxCards.times do |i|
          @sprites["player#{i}"].visible = (i < chosenCards.length)
        end
        if chosenCards.length == @battle.maxCards
          @sprites["helpwindow"].text = _INTL("Se han elegido {1} cartas.", @battle.maxCards)
          command.visible = false
          command.active  = false
          preview.visible = false
        else
          @sprites["helpwindow"].text = _INTL("Elige {1} cartas para usarlas en este duelo.", @battle.maxCards)
          command.visible = true
          command.active  = true
          preview.visible = true
        end
      end
    end
    command.dispose
    preview.bitmap&.dispose
    preview.dispose
    return chosenCards
  end

  def pbShowPlayerCards(cards)
    @battle.maxCards.times do |i|
      @sprites["player#{i}"] = Sprite.new(@viewport)
      @sprites["player#{i}"].x      = Graphics.width - 92
      @sprites["player#{i}"].y      = 44 + (44 * i)
      @sprites["player#{i}"].z      = 2
      @sprites["player#{i}"].bitmap = TriadCard.new(cards[i]).createBitmap(1)
      @cardBitmaps.push(@sprites["player#{i}"].bitmap)
    end
  end

  def pbShowOpponentCards(cards)
    @battle.maxCards.times do |i|
      @sprites["opponent#{i}"] = Sprite.new(@viewport)
      @sprites["opponent#{i}"].x      = 12
      @sprites["opponent#{i}"].y      = 44 + (44 * i)
      @sprites["opponent#{i}"].z      = 2
      @sprites["opponent#{i}"].bitmap = @battle.openHand ? TriadCard.new(cards[i]).createBitmap(2) : TriadCard.createBack
      @opponentCardBitmaps.push(@sprites["opponent#{i}"].bitmap)
      @opponentCardIndexes.push(i)
    end
  end

  def pbViewOpponentCards(numCards)
    @sprites["helpwindow"].text = _INTL("Revisar las cartas del oponente.")
    choice     = 0
    lastChoice = -1
    loop do
      if lastChoice != choice
        y = 44
        @opponentCardIndexes.length.times do |i|
          @sprites["opponent#{@opponentCardIndexes[i]}"].bitmap = @opponentCardBitmaps[@opponentCardIndexes[i]]
          @sprites["opponent#{@opponentCardIndexes[i]}"].x      = (i == choice) ? 28 : 12
          @sprites["opponent#{@opponentCardIndexes[i]}"].y      = y
          @sprites["opponent#{@opponentCardIndexes[i]}"].z      = 2
          y += 44
        end
        lastChoice = choice
      end
      break if choice == -1
      Graphics.update
      Input.update
      pbUpdate
      if Input.repeat?(Input::DOWN)
        pbPlayCursorSE
        choice += 1
        choice = 0 if choice >= numCards
      elsif Input.repeat?(Input::UP)
        pbPlayCursorSE
        choice -= 1
        choice = numCards - 1 if choice < 0
      elsif Input.trigger?(Input::BACK)
        pbPlayCancelSE
        choice = -1
      end
    end
    return choice
  end

  def pbPlayerChooseCard(numCards)
    if @battle.openHand
      @sprites["helpwindow"].text = _INTL("Elige una carta, o comprueba tu oponente con la Z.")
    else
      @sprites["helpwindow"].text = _INTL("Elige una carta.")
    end
    choice     = 0
    lastChoice = -1
    loop do
      if lastChoice != choice
        y = 44
        @cardIndexes.length.times do |i|
          @sprites["player#{@cardIndexes[i]}"].bitmap = @cardBitmaps[@cardIndexes[i]]
          @sprites["player#{@cardIndexes[i]}"].x      = (i == choice) ? Graphics.width - 108 : Graphics.width - 92
          @sprites["player#{@cardIndexes[i]}"].y      = y
          @sprites["player#{@cardIndexes[i]}"].z      = 2
          y += 44
        end
        lastChoice = choice
      end
      Graphics.update
      Input.update
      pbUpdate
      if Input.repeat?(Input::DOWN)
        pbPlayCursorSE
        choice += 1
        choice = 0 if choice >= numCards
      elsif Input.repeat?(Input::UP)
        pbPlayCursorSE
        choice -= 1
        choice = numCards - 1 if choice < 0
      elsif Input.trigger?(Input::USE)
        pbPlayDecisionSE
        break
      elsif Input.trigger?(Input::ACTION) && @battle.openHand
        pbPlayDecisionSE
        pbViewOpponentCards(numCards)
        @sprites["helpwindow"].text = _INTL("Elige una carta, o revisa tu oponente con la Z.")
        choice     = 0
        lastChoice = -1
      end
    end
    return choice
  end

  def pbPlayerPlaceCard(cardIndex)
    @sprites["helpwindow"].text = _INTL("Coloca la carta.")
    boardX = 0
    boardY = 0
    doRefresh = true
    loop do
      if doRefresh
        y = 44
        @cardIndexes.length.times do |i|
          if i == cardIndex   # Card being placed
            @sprites["player#{@cardIndexes[i]}"].x = (Graphics.width / 2) - 118 + (boardX * 78)
            @sprites["player#{@cardIndexes[i]}"].y = 36 + (boardY * 94)
            @sprites["player#{@cardIndexes[i]}"].z = 4
          else   # Other cards in hand
            @sprites["player#{@cardIndexes[i]}"].x = Graphics.width - 92
            @sprites["player#{@cardIndexes[i]}"].y = y
            @sprites["player#{@cardIndexes[i]}"].z = 2
            y += 44
          end
        end
        doRefresh = false
      end
      Graphics.update
      Input.update
      pbUpdate
      if Input.repeat?(Input::DOWN)
        pbPlayCursorSE
        boardY += 1
        boardY = 0 if boardY >= @battle.height
        doRefresh = true
      elsif Input.repeat?(Input::UP)
        pbPlayCursorSE
        boardY -= 1
        boardY = @battle.height - 1 if boardY < 0
        doRefresh = true
      elsif Input.repeat?(Input::LEFT)
        pbPlayCursorSE
        boardX -= 1
        boardX = @battle.width - 1 if boardX < 0
        doRefresh = true
      elsif Input.repeat?(Input::RIGHT)
        pbPlayCursorSE
        boardX += 1
        boardX = 0 if boardX >= @battle.width
        doRefresh = true
      elsif Input.trigger?(Input::BACK)
        return nil
      elsif Input.trigger?(Input::USE)
        if @battle.isOccupied?(boardX, boardY)
          pbPlayBuzzerSE
        else
          pbPlayDecisionSE
          @sprites["player#{@cardIndexes[cardIndex]}"].z = 2
          break
        end
      end
    end
    return [boardX, boardY]
  end

  def pbEndPlaceCard(position, cardIndex)
    spriteIndex = @cardIndexes[cardIndex]
    boardIndex = (position[1] * @battle.width) + position[0]
    @boardSprites[boardIndex] = @sprites["player#{spriteIndex}"]
    @boardCards[boardIndex] = TriadCard.new(@playerCards[spriteIndex])
    pbRefresh
    @cardIndexes.delete_at(cardIndex)
    pbUpdateScore
  end

  def pbOpponentPlaceCard(triadCard, position, cardIndex)
    y = 44
    @opponentCardIndexes.length.times do |i|
      sprite = @sprites["opponent#{@opponentCardIndexes[i]}"]
      if i == cardIndex
        @opponentCardBitmaps[@opponentCardIndexes[i]] = triadCard.createBitmap(2)
        sprite.bitmap&.dispose
        sprite.bitmap = @opponentCardBitmaps[@opponentCardIndexes[i]]
        sprite.x = (Graphics.width / 2) - 118 + (position[0] * 78)
        sprite.y = 36 + (position[1] * 94)
        sprite.z = 2
      else
        sprite.x = 12
        sprite.y = y
        sprite.z = 2
        y += 44
      end
    end
  end

  def pbEndOpponentPlaceCard(position, cardIndex)
    spriteIndex = @opponentCardIndexes[cardIndex]
    boardIndex = (position[1] * @battle.width) + position[0]
    @boardSprites[boardIndex] = @sprites["opponent#{spriteIndex}"]
    @boardCards[boardIndex] = TriadCard.new(@opponentCards[spriteIndex])
    pbRefresh
    @opponentCardIndexes.delete_at(cardIndex)
    pbUpdateScore
  end

  def pbRefresh
    (@battle.width * @battle.height).times do |i|
      x = i % @battle.width
      y = i / @battle.width
      next if !@boardSprites[i]
      @boardSprites[i].bitmap&.dispose
      owner = @battle.getOwner(x, y)
      @boardSprites[i].bitmap = @boardCards[i].createBitmap(owner)
    end
  end

  def pbUpdateScore
    bitmap = @sprites["score"].bitmap
    bitmap.clear
    playerscore = 0
    oppscore    = 0
    (@battle.width * @battle.height).times do |i|
      if @boardSprites[i]
        playerscore += 1 if @battle.board[i].owner == 1
        oppscore    += 1 if @battle.board[i].owner == 2
      end
    end
    if @battle.countUnplayedCards
      playerscore += @cardIndexes.length
      oppscore    += @opponentCardIndexes.length
    end
    pbDrawTextPositions(
      bitmap,
      [[_INTL("{1}-{2}", oppscore, playerscore), Graphics.width / 2, 10, :center, Color.new(248, 248, 248), Color.new(96, 96, 96)]]
    )
  end

  def pbUpdate
    pbUpdateSpriteHash(@sprites)
  end
end

#===============================================================================
# Duel screen logic
#===============================================================================
class TriadScreen
  attr_accessor :openHand, :countUnplayedCards
  attr_reader   :width, :height
  attr_reader   :board
  attr_reader   :playerName
  attr_reader   :opponentName

  def initialize(scene)
    @scene = scene
    @width              = 3
    @height             = 3
    @sameWins           = false
    @openHand           = false
    @wrapAround         = false
    @elements           = false
    @randomHand         = false
    @countUnplayedCards = false
    @trade              = 0
  end

  def maxCards
    numcards = @width * @height
    if numcards.odd?
      numcards = (numcards / 2) + 1
    else
      numcards /= 2
    end
    return numcards
  end

  def isOccupied?(x, y)
    return @board[(y * @width) + x].owner != 0
  end

  def getOwner(x, y)
    return @board[(y * @width) + x].owner
  end

  def getPanel(x, y)
    return @board[(y * @width) + x]
  end

  def quantity(items, item)
    return ItemStorageHelper.quantity(items, item)
  end

  def pbAdd(items, item)
    return ItemStorageHelper.add(items, $PokemonGlobal.triads.maxSize,
                                 TriadStorage::MAX_PER_SLOT, item, 1)
  end

  def pbSubtract(items, item)
    return ItemStorageHelper.remove(items, item, 1)
  end

  def flipBoard(x, y, attackerParam = nil, recurse = false)
    panels = [x - 1, y, x + 1, y, x, y - 1, x, y + 1]
    panels[0] = (@wrapAround ? @width - 1 : 0) if panels[0] < 0            # left
    panels[2] = (@wrapAround ? 0 : @width - 1) if panels[2] > @width - 1     # right
    panels[5] = (@wrapAround ? @height - 1 : 0) if panels[5] < 0           # top
    panels[7] = (@wrapAround ? 0 : @height - 1) if panels[7] > @height - 1   # bottom
    attacker = attackerParam.nil? ? @board[(y * @width) + x] : attackerParam
    flips = []
    return nil if attackerParam && @board[(y * @width) + x].owner != 0
    return nil if !attacker.card || attacker.owner == 0
    4.times do |i|
      defenderX = panels[i * 2]
      defenderY = panels[(i * 2) + 1]
      defender  = @board[(defenderY * @width) + defenderX]
      next if !defender.card
      if attacker.owner != defender.owner
        attack  = attacker.attack(i)
        defense = defender.defense(i)
        if @elements
          # If attacker's type matches the tile's element, add
          # a bonus of 1 (only for original attacker, not combos)
          attack += 1 if !recurse && attacker.type == attacker.card.type
        else
          # Modifier depends on opponent's Pokémon type:
          # +1 - Super effective
          # -1 - Not very effective
          # -2 - Immune
#         attack += attacker.bonus(defender)
        end
        if attack > defense || (attack == defense && @sameWins)
          flips.push([defenderX, defenderY])
          if attackerParam.nil?
            defender.owner = attacker.owner
            if @sameWins
              # Combo with the "sameWins" rule
              ret = flipBoard(defenderX, defenderY, nil, true)
              flips.concat(ret) if ret
            end
          else
            if @sameWins
              # Combo with the "sameWins" rule
              ret = flipBoard(defenderX, defenderY, attackerParam, true)
              flips.concat(ret) if ret
            end
          end
        end
      end
    end
    return flips
  end

  # If pbStartScreen includes parameters, it should
  # pass the parameters to pbStartScene.
  def pbStartScreen(opponentName, minLevel, maxLevel, rules = nil, oppdeck = nil, prize = nil)
    raise _INTL("El nivel mínimo debe estar entre 0 y 9.") if minLevel < 0 || minLevel > 9
    raise _INTL("El nivel máximo debe estar entre 0 y 9.") if maxLevel < 0 || maxLevel > 9
    raise _INTL("El nivel máximo no debería ser inferior que el nivel mínimo.") if maxLevel < minLevel
    if rules.is_a?(Array) && rules.length > 0
      rules.each do |rule|
        @sameWins           = true if rule == "samewins"
        @openHand           = true if rule == "openhand"
        @wrapAround         = true if rule == "wrap"
        @elements           = true if rule == "elements"
        @randomHand         = true if rule == "randomhand"
        @countUnplayedCards = true if rule == "countunplayed"
        @trade              = 1    if rule == "direct"
        @trade              = 2    if rule == "winall"
        @trade              = 3    if rule == "noprize"
      end
    end
    @triadCards = []
    count = 0
    $PokemonGlobal.triads.length.times do |i|
      item = $PokemonGlobal.triads[i]
      ItemStorageHelper.add(@triadCards, $PokemonGlobal.triads.maxSize,
                            TriadStorage::MAX_PER_SLOT, item[0], item[1])
      count += item[1]   # Add item count to total count
    end
    @board = []
    @playerName   = $player ? $player.name : "Trainer"
    @opponentName = opponentName
    type_keys = GameData::Type.keys
    (@width * @height).times do |i|
      square = TriadSquare.new
      if @elements
        loop do
          trial_type = type_keys.sample
          type_data = GameData::Type.get(trial_type)
          next if type_data.pseudo_type
          square.type = type_data.id
          break
        end
      end
      @board.push(square)
    end
    @scene.pbStartScene(self)   # (param1, param2)
    # Check whether there are enough cards.
    if count < self.maxCards
      @scene.pbDisplayPaused(_INTL("No tienes suficientes cartas."))
      @scene.pbEndScene
      return 0
    end
    # Set the player's cards.
    cards = []
    if @randomHand   # Determine hand at random
      self.maxCards.times do
        randCard = @triadCards[rand(@triadCards.length)]
        pbSubtract(@triadCards, randCard[0])
        cards.push(randCard[0])
      end
      @scene.pbShowPlayerCards(cards)
    else
      cards = @scene.pbChooseTriadCard(@triadCards)
    end
    # Set the opponent's cards.
    if oppdeck.is_a?(Array) && oppdeck.length == self.maxCards   # Preset
      opponentCards = []
      oppdeck.each do |species|
        species_data = GameData::Species.try_get(species)
        if !species_data
          @scene.pbDisplayPaused(_INTL("El rival tiene una carta ilegal, \"{1}\".", species))
          @scene.pbEndScene
          return 0
        end
        opponentCards.push(species_data.id)
      end
    else
      species_keys = GameData::Species.keys
      candidates = []
      while candidates.length < 200
        card = species_keys.sample
        card_data = GameData::Species.get(card)
        card = card_data.id   # Make sure it's a symbol
        triad = TriadCard.new(card)
        total = triad.north + triad.south + triad.east + triad.west
        # Add random species and its total point count
        candidates.push([card, total])
        if candidates.length < 200 && $player.owned?(card_data.species)
          # Add again if player owns the species
          candidates.push([card, total])
        end
      end
      # sort by total point count
      candidates.sort! { |a, b| a[1] <=> b[1] }
      opponentCards = []
      self.maxCards.times do
        # Choose random card from candidates based on trainer's level
        index = minLevel + rand(20)
        opponentCards.push(candidates[index][0])
      end
    end
    originalCards = cards.clone
    originalOpponentCards = opponentCards.clone
    @scene.pbNotifyCards(cards.clone, opponentCards.clone)
    @scene.pbShowOpponentCards(opponentCards)
    @scene.pbDisplay(_INTL("Eligiendo al jugador que empezará..."))
    @scene.pbUpdateScore
    playerTurn = (rand(2) == 0)
    @scene.pbDisplay(_INTL("{1} irá primero.", (playerTurn) ? @playerName : @opponentName))
    (@width * @height).times do |i|
      position = nil
      triadCard = nil
      cardIndex = 0
      if playerTurn
        # Player's turn
        until position
          cardIndex = @scene.pbPlayerChooseCard(cards.length)
          triadCard = TriadCard.new(cards[cardIndex])
          position = @scene.pbPlayerPlaceCard(cardIndex)
        end
      else
        # Opponent's turn
        @scene.pbDisplay(_INTL("{1} está eligiendo movimiento...", @opponentName))
        scores = []
        opponentCards.length.times do |cardIdx|
          square = TriadSquare.new
          square.card = TriadCard.new(opponentCards[cardIdx])
          square.owner = 2
          (@width * @height).times do |j|
            x = j % @width
            y = j / @width
            square.type = @board[j].type
            flips = flipBoard(x, y, square)
            scores.push([cardIdx, x, y, flips.length]) if flips
          end
        end
        # Sort by number of flips
        scores.sort! { |a, b| (b[3] == a[3]) ? rand(-1..1) : b[3] <=> a[3] }
        scores = scores[0, opponentCards.length]   # Get the best results
        if scores.length == 0
          @scene.pbDisplay(_INTL("{1} no se puede mover por algún motivo...", @opponentName))
          playerTurn = !playerTurn
          continue
        end
        result = scores[rand(scores.length)]
        cardIndex = result[0]
        triadCard = TriadCard.new(opponentCards[cardIndex])
        position = [result[1], result[2]]
        @scene.pbOpponentPlaceCard(triadCard, position, cardIndex)
      end
      boardIndex = (position[1] * @width) + position[0]
      board[boardIndex].card  = triadCard
      board[boardIndex].owner = playerTurn ? 1 : 2
      flipBoard(position[0], position[1])
      if playerTurn
        cards.delete_at(cardIndex)
        @scene.pbEndPlaceCard(position, cardIndex)
      else
        opponentCards.delete_at(cardIndex)
        @scene.pbEndOpponentPlaceCard(position, cardIndex)
      end
      playerTurn = !playerTurn
    end
    # Determine the winner
    playerCount   = 0
    opponentCount = 0
    (@width * @height).times do |i|
      playerCount   += 1 if board[i].owner == 1
      opponentCount += 1 if board[i].owner == 2
    end
    if @countUnplayedCards
      playerCount   += cards.length
      opponentCount += opponentCards.length
    end
    result = 0
    if playerCount == opponentCount
      @scene.pbDisplayPaused(_INTL("El juego acaba en empate."))
      result = 3
      if @trade == 1
        # Keep only cards of your color
        originalCards.each { |crd| $PokemonGlobal.triads.remove(crd) }
        cards.each { |crd| $PokemonGlobal.triads.add(crd) }
        (@width * @height).times do |i|
          if board[i].owner == 1
            crd = GameData::Species.get_species_form(board[i].card.species, board[i].card.form).id
            $PokemonGlobal.triads.add(crd)
          end
        end
        @scene.pbDisplayPaused(_INTL("Mantuviste todas las cartas de tu color."))
      end
    elsif playerCount > opponentCount
      @scene.pbDisplayPaused(_INTL("{1} ganó contra {2}.", @playerName, @opponentName))
      result = 1
      if prize
        species_data = GameData::Species.try_get(prize)
        if species_data && $PokemonGlobal.triads.add(species_data.id)
          @scene.pbDisplayPaused(_INTL("Obtuvo la carta {1} de su oponente.", species_data.name))
        end
      else
        case @trade
        when 0   # Gain 1 random card from opponent's deck
          card = originalOpponentCards[rand(originalOpponentCards.length)]
          if $PokemonGlobal.triads.add(card)
            cardname = GameData::Species.get(card).name
            @scene.pbDisplayPaused(_INTL("Obtuvo la carta {1} de su oponente.", cardname))
          end
        when 1   # Keep only cards of your color
          originalCards.each { |crd| $PokemonGlobal.triads.remove(crd) }
          cards.each { |crd| $PokemonGlobal.triads.add(crd) }
          (@width * @height).times do |i|
            if board[i].owner == 1
              card = GameData::Species.get_species_form(board[i].card.species, board[i].card.form).id
              $PokemonGlobal.triads.add(card)
            end
          end
          @scene.pbDisplayPaused(_INTL("Mantuviste todas las cartas de tu color."))
        when 2   # Gain all opponent's cards
          originalOpponentCards.each { |crd| $PokemonGlobal.triads.add(crd) }
          @scene.pbDisplayPaused(_INTL("Recibió todas las cartas de su oponente."))
        end
      end
    else
      @scene.pbDisplayPaused(_INTL("{1} perdió contra {2}.", @playerName, @opponentName))
      result = 2
      case @trade
      when 0   # Lose 1 random card from your deck
        card = originalCards[rand(originalCards.length)]
        $PokemonGlobal.triads.remove(card)
        cardname = GameData::Species.get(card).name
        @scene.pbDisplayPaused(_INTL("El oponente obtuvo tu carta {1}.", cardname))
      when 1   # Keep only cards of your color
        originalCards.each { |crd| $PokemonGlobal.triads.remove(card) }
        cards.each { |crd| $PokemonGlobal.triads.add(crd) }
        (@width * @height).times do |i|
          if board[i].owner == 1
            card = GameData::Species.get_species_form(board[i].card.species, board[i].card.form).id
            $PokemonGlobal.triads.add(card)
          end
        end
        @scene.pbDisplayPaused(_INTL("Mantuviste todas las cartas de tu color.", cardname))
      when 2   # Lose all your cards
        originalCards.each { |crd| $PokemonGlobal.triads.remove(crd) }
        @scene.pbDisplayPaused(_INTL("El oponente obtuvo todas tus cartas."))
      end
    end
    @scene.pbEndScene
    return result
  end
end

#===============================================================================
# Start duel
#===============================================================================
def pbCanTriadDuel?
  card_count = $PokemonGlobal.triads.total_cards
  return card_count >= PokemonGlobalMetadata::MINIMUM_TRIAD_CARDS
end

def pbTriadDuel(name, minLevel, maxLevel, rules = nil, oppdeck = nil, prize = nil)
  ret = 0
  pbFadeOutInWithMusic do
    scene = TriadScene.new
    screen = TriadScreen.new(scene)
    ret = screen.pbStartScreen(name, minLevel, maxLevel, rules, oppdeck, prize)
  end
  return ret
end

#===============================================================================
# Card storage
#===============================================================================
class PokemonGlobalMetadata
  attr_writer :triads

  MINIMUM_TRIAD_CARDS = 5

  def triads
    @triads = TriadStorage.new if !@triads
    return @triads
  end
end

#===============================================================================
#
#===============================================================================
class TriadStorage
  attr_reader :items

  MAX_PER_SLOT = 999   # Max. number of items per slot

  def initialize
    @items = []
  end

  def [](i)
    return @items[i]
  end

  def length
    return @items.length
  end

  def empty?
    return @items.length == 0
  end

  def maxSize
    return @items.length + 1
  end

  def clear
    @items.clear
  end

  def get_item(index)
    return nil if index < 0 || index >= @items.length
    return @items[index][0]
  end

  # Number of the item in the given index
  def get_item_count(index)
    return 0 if index < 0 || index >= @items.length
    return @items[index][1]
  end

  def quantity(item)
    return ItemStorageHelper.quantity(@items, item)
  end

  def can_add?(item, qty = 1)
    return ItemStorageHelper.can_add?(@items, self.maxSize, MAX_PER_SLOT, item, qty)
  end

  def add(item, qty = 1)
    return ItemStorageHelper.add(@items, self.maxSize, MAX_PER_SLOT, item, qty)
  end

  def remove(item, qty = 1)
    return ItemStorageHelper.remove(@items, item, qty)
  end

  def total_cards
    ret = 0
    @items.each { |itm| ret += itm[1] }
    return ret
  end
end

#===============================================================================
# Card shop screen
#===============================================================================
def pbBuyTriads
  commands = []
  realcommands = []
  GameData::Species.each_species do |s|
    next if !$player.owned?(s.species)
    price = TriadCard.new(s.id).price
    commands.push([price, s.name, _INTL("{1} - ${2}", s.name, price.to_s_formatted), s.id])
  end
  if commands.length == 0
    pbMessage(_INTL("No hay cartas que puedas comprar."))
    return
  end
  commands.sort! { |a, b| a[1] <=> b[1] }   # Sort alphabetically
  commands.each do |command|
    realcommands.push(command[2])
  end
  # Scroll right before showing screen
  pbScrollMap(4, 3, 5)
  cmdwindow = Window_CommandPokemonEx.newWithSize(realcommands, 0, 0, Graphics.width / 2, Graphics.height)
  cmdwindow.z = 99999
  goldwindow = Window_UnformattedTextPokemon.newWithSize(
    _INTL("Dinero:\n{1}", pbGetGoldString), 0, 0, 32, 32
  )
  goldwindow.resizeToFit(goldwindow.text, Graphics.width)
  goldwindow.x = Graphics.width - goldwindow.width
  goldwindow.y = 0
  goldwindow.z = 99999
  preview = Sprite.new
  preview.x = (Graphics.width * 3 / 4) - 40
  preview.y = (Graphics.height / 2) - 48
  preview.z = 4
  preview.bitmap = TriadCard.new(commands[cmdwindow.index][3]).createBitmap(1)
  olditem = commands[cmdwindow.index][3]
  Graphics.frame_reset
  loop do
    Graphics.update
    Input.update
    cmdwindow.active = true
    cmdwindow.update
    goldwindow.update
    if commands[cmdwindow.index][3] != olditem
      preview.bitmap&.dispose
      preview.bitmap = TriadCard.new(commands[cmdwindow.index][3]).createBitmap(1)
      olditem = commands[cmdwindow.index][3]
    end
    if Input.trigger?(Input::BACK)
      break
    elsif Input.trigger?(Input::USE)
      price    = commands[cmdwindow.index][0]
      item     = commands[cmdwindow.index][3]
      itemname = commands[cmdwindow.index][1]
      cmdwindow.active = false
      cmdwindow.update
      if $player.money < price
        pbMessage(_INTL("No tienes suficiente dinero."))
        next
      end
      maxafford = (price <= 0) ? 99 : $player.money / price
      maxafford = 99 if maxafford > 99
      params = ChooseNumberParams.new
      params.setRange(1, maxafford)
      params.setInitialValue(1)
      params.setCancelValue(0)
      quantity = pbMessageChooseNumber(
        _INTL("¿La carta {1}? Ya veo. ¿Cuántas quieres?", itemname), params
      )
      next if quantity <= 0
      price *= quantity
      next if !pbConfirmMessage(_INTL("{1}, y quieres {2}. Serían ${3}. ¿Te parece bien?", itemname, quantity, price.to_s_formatted))
      if $player.money < price
        pbMessage(_INTL("No tienes suficiente dinero."))
        next
      end
      if !$PokemonGlobal.triads.can_add?(item, quantity)
        pbMessage(_INTL("No tienes espacio para más cartas."))
        next
      end
      $PokemonGlobal.triads.add(item, quantity)
      $player.money -= price
      goldwindow.text = _INTL("Dinero:\n{1}", pbGetGoldString)
      pbMessage(_INTL("¡Aquí tienes! ¡Muchas gracias!") + "\\se[Mart buy item]\\wtnp[20]")
    end
  end
  cmdwindow.dispose
  goldwindow.dispose
  preview.bitmap&.dispose
  preview.dispose
  Graphics.frame_reset
  # Scroll right before showing screen
  pbScrollMap(6, 3, 5)
end

def pbSellTriads
  total_cards = 0
  commands = []
  $PokemonGlobal.triads.length.times do |i|
    item = $PokemonGlobal.triads[i]
    speciesname = GameData::Species.get(item[0]).name
    commands.push(_INTL("{1} x{2}", speciesname, item[1]))
    total_cards += item[1]
  end
  commands.push(_INTL("CANCELAR"))
  if total_cards == 0
    pbMessage(_INTL("No tienes cartas."))
    return
  end
  # Scroll right before showing screen
  pbScrollMap(4, 3, 5)
  cmdwindow = Window_CommandPokemonEx.newWithSize(commands, 0, 0, Graphics.width / 2, Graphics.height)
  cmdwindow.z = 99999
  goldwindow = Window_UnformattedTextPokemon.newWithSize(
    _INTL("Dinero:\n{1}", pbGetGoldString), 0, 0, 32, 32
  )
  goldwindow.resizeToFit(goldwindow.text, Graphics.width)
  goldwindow.x = Graphics.width - goldwindow.width
  goldwindow.y = 0
  goldwindow.z = 99999
  preview = Sprite.new
  preview.x = (Graphics.width * 3 / 4) - 40
  preview.y = (Graphics.height / 2) - 48
  preview.z = 4
  item = $PokemonGlobal.triads.get_item(cmdwindow.index)
  preview.bitmap = TriadCard.new(item).createBitmap(1)
  olditem = $PokemonGlobal.triads.get_item(cmdwindow.index)
  done = false
  Graphics.frame_reset
  until done
    loop do
      Graphics.update
      Input.update
      cmdwindow.active = true
      cmdwindow.update
      goldwindow.update
      item = $PokemonGlobal.triads.get_item(cmdwindow.index)
      if olditem != item
        preview.bitmap&.dispose
        preview.bitmap = TriadCard.new(item).createBitmap(1) if item
        olditem = item
      end
      if Input.trigger?(Input::BACK)
        done = true
        break
      end
      if Input.trigger?(Input::USE)
        if cmdwindow.index >= $PokemonGlobal.triads.length
          done = true
          break
        end
        item = $PokemonGlobal.triads.get_item(cmdwindow.index)
        itemname = GameData::Species.get(item).name
        quantity = $PokemonGlobal.triads.quantity(item)
        price = TriadCard.new(item).price
        if price == 0
          pbDisplayPaused(_INTL("¿La carta {1}? Oh, no. No puedo comprar eso.", itemname))
          break
        end
        cmdwindow.active = false
        cmdwindow.update
        if quantity > 1
          params = ChooseNumberParams.new
          params.setRange(1, quantity)
          params.setInitialValue(1)
          params.setCancelValue(0)
          quantity = pbMessageChooseNumber(
            _INTL("¿La carta {1}? ¿Cuántas quieres vender?", itemname), params
          )
        end
        if quantity > 0
          price /= 4
          price *= quantity
          if pbConfirmMessage(_INTL("Puedo pagarte ${1}. ¿Te parece bien?", price.to_s_formatted))
            $player.money += price
            goldwindow.text = _INTL("Dinero:\n{1}", pbGetGoldString)
            $PokemonGlobal.triads.remove(item, quantity)
            pbMessage(_INTL("Has entregado las cartas de {1} y has recibido ${2}.", itemname, price.to_s_formatted) + "\\se[Mart buy item]\\wtnp[20]")
            commands = []
            $PokemonGlobal.triads.length.times do |i|
              item = $PokemonGlobal.triads[i]
              speciesname = GameData::Species.get(item[0]).name
              commands.push(_INTL("{1} x{2}", speciesname, item[1]))
            end
            commands.push(_INTL("CANCELAR"))
            cmdwindow.commands = commands
            break
          end
        end
      end
    end
  end
  cmdwindow.dispose
  goldwindow.dispose
  preview.bitmap&.dispose
  preview.dispose
  Graphics.frame_reset
  # Scroll right before showing screen
  pbScrollMap(6, 3, 5)
end

def pbTriadList
  total_cards = 0
  commands = []
  $PokemonGlobal.triads.length.times do |i|
    item = $PokemonGlobal.triads[i]
    speciesname = GameData::Species.get(item[0]).name
    commands.push(_INTL("{1} x{2}", speciesname, item[1]))
    total_cards += item[1]
  end
  commands.push(_INTL("CANCELAR"))
  if total_cards == 0
    pbMessage(_INTL("No tienes cartas."))
    return
  end
  cmdwindow = Window_CommandPokemonEx.newWithSize(commands, 0, 0, Graphics.width / 2, Graphics.height)
  cmdwindow.z = 99999
  sprite = Sprite.new
  sprite.x = (Graphics.width / 2) + 40
  sprite.y = 48
  sprite.z = 99999
  done = false
  lastIndex = -1
  until done
    loop do
      Graphics.update
      Input.update
      cmdwindow.update
      if lastIndex != cmdwindow.index
        sprite.bitmap&.dispose
        if cmdwindow.index < $PokemonGlobal.triads.length
          sprite.bitmap = TriadCard.new($PokemonGlobal.triads.get_item(cmdwindow.index)).createBitmap(1)
        end
        lastIndex = cmdwindow.index
      end
      if Input.trigger?(Input::BACK) ||
         (Input.trigger?(Input::USE) && cmdwindow.index >= $PokemonGlobal.triads.length)
        done = true
        break
      end
    end
  end
  cmdwindow.dispose
  sprite.dispose
end

#===============================================================================
# Give the player a particular card
#===============================================================================
def pbGiveTriadCard(species, quantity = 1)
  sp = GameData::Species.try_get(species)
  return false if !sp
  return false if !$PokemonGlobal.triads.can_add?(sp.id, quantity)
  $PokemonGlobal.triads.add(sp.id, quantity)
  return true
end


==============================================================================
# Script: Minigame_SlotMachine
==============================================================================
#===============================================================================
# "Slot Machine" mini-game
# By Maruno
#-------------------------------------------------------------------------------
# Run with:      pbSlotMachine(1)
# - The number is either 0 (easy), 1 (default) or 2 (hard).
#===============================================================================
class SlotMachineReel < BitmapSprite
  SCROLL_SPEED = 640   # Pixels moved per second
  ICONS_SETS = [[3, 2, 7, 6, 3, 1, 5, 2, 3, 0, 6, 4, 7, 5, 1, 3, 2, 3, 6, 0, 4, 5],   # Reel 1
                [0, 4, 1, 2, 7, 4, 6, 0, 1, 5, 4, 0, 1, 3, 4, 0, 1, 6, 7, 0, 1, 5],   # Reel 2
                [6, 2, 1, 4, 3, 2, 1, 4, 7, 3, 2, 1, 4, 3, 7, 2, 4, 3, 1, 2, 4, 5]]   # Reel 3
  SLIPPING = [0, 0, 0, 0, 0, 0, 1, 1, 1, 2, 2, 3]

  def initialize(x, y, reel_num, difficulty = 1)
    @viewport = Viewport.new(x, y, 64, 144)
    @viewport.z = 99999
    super(64, 144, @viewport)
    @reel_num = reel_num
    @difficulty = difficulty
    @reel = ICONS_SETS[reel_num - 1].clone
    @toppos = 0
    @current_y_pos = -1
    @spin_speed = SCROLL_SPEED
    @spin_speed /= 1.5 if difficulty == 0
    @spinning = false
    @stopping = false
    @slipping = 0
    @index = rand(@reel.length)
    @images = AnimatedBitmap.new(_INTL("Graphics/UI/Slot Machine/images"))
    @shading = AnimatedBitmap.new("Graphics/UI/Slot Machine/ReelOverlay")
    update
  end

  def startSpinning
    @spinning = true
    @spin_timer_start = System.uptime
    @initial_index = @index + 1
    @current_y_pos = -1
  end

  def spinning?
    return @spinning
  end

  def stopSpinning(noslipping = false)
    @stopping = true
    @slipping = SLIPPING.sample
    case @difficulty
    when 0   # Easy
      second_slipping = SLIPPING.sample
      @slipping = [@slipping, second_slipping].min
    when 2   # Hard
      second_slipping = SLIPPING.sample
      @slipping = [@slipping, second_slipping].max
    end
    @slipping = 0 if noslipping
  end

  def showing
    array = []
    3.times do |i|
      num = @index - i
      num += @reel.length if num < 0
      array.push(@reel[num])
    end
    return array   # [0] = top, [1] = middle, [2] = bottom
  end

  def update
    self.bitmap.clear
    if @spinning
      new_y_pos = (System.uptime - @spin_timer_start) * @spin_speed
      new_index = (new_y_pos / @images.height).to_i
      old_index = (@current_y_pos / @images.height).to_i
      @current_y_pos = new_y_pos
      @toppos = new_y_pos
      while @toppos > 0
        @toppos -= @images.height
      end
      if new_index != old_index
        if @stopping
          if @slipping == 0
            @spinning = false
            @stopping = false
            @toppos = 0
          else
            @slipping = [@slipping - new_index + old_index, 0].max
          end
        end
        if @spinning
          @index = (new_index + @initial_index) % @reel.length
        end
      end
    end
    4.times do |i|
      num = @index - i
      num += @reel.length if num < 0
      self.bitmap.blt(0, @toppos + (i * 48), @images.bitmap, Rect.new(@reel[num] * 64, 0, 64, 48))
    end
    self.bitmap.blt(0, 0, @shading.bitmap, Rect.new(0, 0, 64, 144))
  end
end

#===============================================================================
#
#===============================================================================
class SlotMachineScore < BitmapSprite
  attr_reader :score

  def initialize(x, y, score = 0)
    @viewport = Viewport.new(x, y, 70, 22)
    @viewport.z = 99999
    super(70, 22, @viewport)
    @numbers = AnimatedBitmap.new("Graphics/UI/Slot Machine/numbers")
    self.score = score
  end

  def score=(value)
    @score = value
    @score = Settings::MAX_COINS if @score > Settings::MAX_COINS
    refresh
  end

  def refresh
    self.bitmap.clear
    5.times do |i|
      digit = (@score / (10**i)) % 10 # Least significant digit first
      self.bitmap.blt(14 * (4 - i), 0, @numbers.bitmap, Rect.new(digit * 14, 0, 14, 22))
    end
  end
end

#===============================================================================
#
#===============================================================================
class SlotMachineScene
  attr_accessor :gameRunning
  attr_accessor :gameEnd
  attr_accessor :wager
  attr_accessor :replay

  def update
    pbUpdateSpriteHash(@sprites)
  end

  def pbPayout
    @replay = false
    payout = 0
    bonus = 0
    wonRow = []
    # Get reel pictures
    reel1 = @sprites["reel1"].showing
    reel2 = @sprites["reel2"].showing
    reel3 = @sprites["reel3"].showing
    combinations = [[reel1[1], reel2[1], reel3[1]],   # Centre row
                    [reel1[0], reel2[0], reel3[0]],   # Top row
                    [reel1[2], reel2[2], reel3[2]],   # Bottom row
                    [reel1[0], reel2[1], reel3[2]],   # Diagonal top left -> bottom right
                    [reel1[2], reel2[1], reel3[0]]]   # Diagonal bottom left -> top right
    combinations.length.times do |i|
      break if i >= 1 && @wager <= 1 # One coin = centre row only
      break if i >= 3 && @wager <= 2 # Two coins = three rows only
      wonRow[i] = true
      case combinations[i]
      when [1, 1, 1]   # Three Magnemites
        payout += 8
      when [2, 2, 2]   # Three Shellders
        payout += 8
      when [3, 3, 3]   # Three Pikachus
        payout += 15
      when [4, 4, 4]   # Three Psyducks
        payout += 15
      when [5, 5, 6], [5, 6, 5], [6, 5, 5], [6, 6, 5], [6, 5, 6], [5, 6, 6]   # 777 multi-colored
        payout += 90
        bonus = 1 if bonus < 1
      when [5, 5, 5], [6, 6, 6]   # Red 777, blue 777
        payout += 300
        bonus = 2 if bonus < 2
      when [7, 7, 7]   # Three replays
        @replay = true
      else
        if combinations[i][0] == 0   # Left cherry
          if combinations[i][1] == 0   # Centre cherry as well
            payout += 4
          else
            payout += 2
          end
        else
          wonRow[i] = false
        end
      end
    end
    @sprites["payout"].score = payout
    if payout > 0 || @replay
      if bonus > 0
        pbMEPlay("Slots big win")
      else
        pbMEPlay("Slots win")
      end
      # Show winning animation
      timer_start = System.uptime
      loop do
        frame = ((System.uptime - timer_start) / 0.125).to_i
        @sprites["window2"].bitmap&.clear
        @sprites["window1"].setBitmap(_INTL("Graphics/UI/Slot Machine/win"))
        @sprites["window1"].src_rect.set(152 * (frame % 4), 0, 152, 208)
        if bonus > 0
          @sprites["window2"].setBitmap(_INTL("Graphics/UI/Slot Machine/bonus"))
          @sprites["window2"].src_rect.set(152 * (bonus - 1), 0, 152, 208)
        end
        @sprites["light1"].visible = true
        @sprites["light1"].src_rect.set(0, 26 * (frame % 4), 96, 26)
        @sprites["light2"].visible = true
        @sprites["light2"].src_rect.set(0, 26 * (frame % 4), 96, 26)
        (1..5).each do |i|
          if wonRow[i - 1]
            @sprites["row#{i}"].visible = frame.even?
          else
            @sprites["row#{i}"].visible = false
          end
        end
        Graphics.update
        Input.update
        update
        break if System.uptime - timer_start >= 3.0
      end
      @sprites["light1"].visible = false
      @sprites["light2"].visible = false
      @sprites["window1"].src_rect.set(0, 0, 152, 208)
      # Pay out
      timer_start = System.uptime
      last_paid_tick = -1
      loop do
        break if @sprites["payout"].score <= 0
        Graphics.update
        Input.update
        update
        this_tick = ((System.uptime - timer_start) * 20).to_i   # Pay out 1 coin every 1/20 seconds
        if this_tick != last_paid_tick
          @sprites["payout"].score -= 1
          @sprites["credit"].score += 1
          this_tick = last_paid_tick
        end
        if Input.trigger?(Input::USE) || @sprites["credit"].score == Settings::MAX_COINS
          @sprites["credit"].score += @sprites["payout"].score
          @sprites["payout"].score = 0
        end
      end
      # Wait
      timer_start = System.uptime
      loop do
        Graphics.update
        Input.update
        update
        break if System.uptime - timer_start >= 0.5
      end
    else
      # Show losing animation
      timer_start = System.uptime
      loop do
        frame = ((System.uptime - timer_start) / 0.25).to_i
        @sprites["window2"].bitmap&.clear
        @sprites["window1"].setBitmap(_INTL("Graphics/UI/Slot Machine/lose"))
        @sprites["window1"].src_rect.set(152 * (frame % 2), 0, 152, 208)
        Graphics.update
        Input.update
        update
        break if System.uptime - timer_start >= 2.0
      end
    end
    @wager = 0
  end

  def pbStartScene(difficulty)
    @sprites = {}
    @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = 99999
    addBackgroundPlane(@sprites, "bg", "Slot Machine/bg", @viewport)
    @sprites["reel1"] = SlotMachineReel.new(64, 112, 1, difficulty)
    @sprites["reel2"] = SlotMachineReel.new(144, 112, 2, difficulty)
    @sprites["reel3"] = SlotMachineReel.new(224, 112, 3, difficulty)
    (1..3).each do |i|
      @sprites["button#{i}"] = IconSprite.new(68 + (80 * (i - 1)), 260, @viewport)
      @sprites["button#{i}"].setBitmap("Graphics/UI/Slot Machine/button")
      @sprites["button#{i}"].visible = false
    end
    (1..5).each do |i|
      y = [170, 122, 218, 82, 82][i - 1]
      @sprites["row#{i}"] = IconSprite.new(2, y, @viewport)
      @sprites["row#{i}"].setBitmap(sprintf("Graphics/UI/Slot Machine/line%1d%s",
                                            1 + (i / 2), (i >= 4) ? ((i == 4) ? "a" : "b") : ""))
      @sprites["row#{i}"].visible = false
    end
    @sprites["light1"] = IconSprite.new(16, 32, @viewport)
    @sprites["light1"].setBitmap("Graphics/UI/Slot Machine/lights")
    @sprites["light1"].visible = false
    @sprites["light2"] = IconSprite.new(240, 32, @viewport)
    @sprites["light2"].setBitmap("Graphics/UI/Slot Machine/lights")
    @sprites["light2"].mirror = true
    @sprites["light2"].visible = false
    @sprites["window1"] = IconSprite.new(358, 96, @viewport)
    @sprites["window1"].setBitmap(_INTL("Graphics/UI/Slot Machine/insert"))
    @sprites["window1"].src_rect.set(0, 0, 152, 208)
    @sprites["window2"] = IconSprite.new(358, 96, @viewport)
    @sprites["credit"] = SlotMachineScore.new(360, 66, $player.coins)
    @sprites["payout"] = SlotMachineScore.new(438, 66, 0)
    @wager = 0
    update
    pbFadeInAndShow(@sprites)
  end

  def pbMain
    loop do
      Graphics.update
      Input.update
      update
      @sprites["window1"].bitmap&.clear
      @sprites["window2"].bitmap&.clear
      if @sprites["credit"].score == Settings::MAX_COINS
        pbMessage(_INTL("Has obtenido {1} Monedas.", Settings::MAX_COINS.to_s_formatted))
        break
      elsif $player.coins == 0
        pbMessage(_INTL("Te has quedado sin Monedas.\nGame over!"))
        break
      elsif @gameRunning   # Reels are spinning
        @sprites["window1"].setBitmap(_INTL("Graphics/UI/Slot Machine/stop"))
        timer_start = System.uptime
        loop do
          frame = ((System.uptime - timer_start) / 0.25).to_i
          @sprites["window1"].src_rect.set(152 * (frame % 4), 0, 152, 208)
          Graphics.update
          Input.update
          update
          if Input.trigger?(Input::USE)
            pbSEPlay("Slots stop")
            if @sprites["reel1"].spinning?
              @sprites["reel1"].stopSpinning(@replay)
              @sprites["button1"].visible = true
            elsif @sprites["reel2"].spinning?
              @sprites["reel2"].stopSpinning(@replay)
              @sprites["button2"].visible = true
            elsif @sprites["reel3"].spinning?
              @sprites["reel3"].stopSpinning(@replay)
              @sprites["button3"].visible = true
            end
          end
          if !@sprites["reel3"].spinning?
            @gameEnd = true
            @gameRunning = false
          end
          break if !@gameRunning
        end
      elsif @gameEnd   # Reels have been stopped
        pbPayout
        # Reset graphics
        @sprites["button1"].visible = false
        @sprites["button2"].visible = false
        @sprites["button3"].visible = false
        (1..5).each do |i|
          @sprites["row#{i}"].visible = false
        end
        @gameEnd = false
      else   # Awaiting coins for the next spin
        @sprites["window1"].setBitmap(_INTL("Graphics/UI/Slot Machine/insert"))
        timer_start = System.uptime
        loop do
          frame = ((System.uptime - timer_start) / 0.4).to_i
          @sprites["window1"].src_rect.set(152 * (frame % 2), 0, 152, 208)
          if @wager > 0
            @sprites["window2"].setBitmap(_INTL("Graphics/UI/Slot Machine/press"))
            @sprites["window2"].src_rect.set(152 * (frame % 2), 0, 152, 208)
          end
          Graphics.update
          Input.update
          update
          if Input.trigger?(Input::DOWN) && @wager < 3 && @sprites["credit"].score > 0
            pbSEPlay("Slots coin")
            @wager += 1
            @sprites["credit"].score -= 1
            if @wager >= 3
              @sprites["row5"].visible = true
              @sprites["row4"].visible = true
            elsif @wager >= 2
              @sprites["row3"].visible = true
              @sprites["row2"].visible = true
            elsif @wager >= 1
              @sprites["row1"].visible = true
            end
          elsif @wager >= 3 || (@wager > 0 && @sprites["credit"].score == 0) ||
                (Input.trigger?(Input::USE) && @wager > 0) || @replay
            if @replay
              @wager = 3
              (1..5).each { |i| @sprites["row#{i}"].visible = true }
            end
            @sprites["reel1"].startSpinning
            @sprites["reel2"].startSpinning
            @sprites["reel3"].startSpinning
            @gameRunning = true
          elsif Input.trigger?(Input::BACK) && @wager == 0
            break
          end
          break if @gameRunning
        end
        break if !@gameRunning
      end
    end
    old_coins = $player.coins
    $player.coins = @sprites["credit"].score
    if $player.coins > old_coins
      $stats.coins_won += $player.coins - old_coins
    elsif $player.coins < old_coins
      $stats.coins_lost += old_coins - $player.coins
    end
  end

  def pbEndScene
    pbFadeOutAndHide(@sprites)
    pbDisposeSpriteHash(@sprites)
    @viewport.dispose
  end
end

#===============================================================================
#
#===============================================================================
class SlotMachine
  def initialize(scene)
    @scene = scene
  end

  def pbStartScreen(difficulty)
    @scene.pbStartScene(difficulty)
    @scene.pbMain
    @scene.pbEndScene
  end
end

#===============================================================================
#
#===============================================================================
def pbSlotMachine(difficulty = 1)
  if !$bag.has?(:COINCASE)
    pbMessage(_INTL("Es una Máquina Tragaperras."))
  elsif $player.coins == 0
    pbMessage(_INTL("¡No tienes Monedas para jugar!"))
  elsif $player.coins == Settings::MAX_COINS
    pbMessage(_INTL("¡Tu Monedero está lleno!"))
  else
    pbFadeOutIn do
      scene = SlotMachineScene.new
      screen = SlotMachine.new(scene)
      screen.pbStartScreen(difficulty)
    end
  end
end


