  def pbStartScene
    @sprites = {}
    @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = 99999
    addBackgroundPlane(@sprites, "bg", "Mining/bg", @viewport)
    @sprites["itemlayer"] = BitmapSprite.new(Graphics.width, Graphics.height, @viewport)
    @sprites["itemlayer"].z = 10
    @itembitmap = AnimatedBitmap.new("Graphics/UI/Mining/items")
    @ironbitmap = AnimatedBitmap.new("Graphics/UI/Mining/irons")
    @items = []
    @itemswon = []
    @iron = []
    pbDistributeItems
    pbDistributeIron
    BOARD_HEIGHT.times do |i|
      BOARD_WIDTH.times do |j|
        @sprites["tile#{j + (i * BOARD_WIDTH)}"] = MiningGameTile.new(@viewport)
        @sprites["tile#{j + (i * BOARD_WIDTH)}"].x = 32 * j
        @sprites["tile#{j + (i * BOARD_WIDTH)}"].y = 64 + (32 * i)
        @sprites["tile#{j + (i * BOARD_WIDTH)}"].z = 20
      end
    end
    @sprites["crack"] = MiningGameCounter.new(0, 4, @viewport)
    @sprites["cursor"] = MiningGameCursor.new(58, 0, @viewport)   # central position, pick
    @sprites["cursor"].z = 50
    @sprites["tool"] = IconSprite.new(434, 254, @viewport)
    @sprites["tool"].setBitmap("Graphics/UI/Mining/toolicons")
    @sprites["tool"].src_rect.set(0, 0, 68, 100)
    @sprites["tool"].z = 100
    update
    pbFadeInAndShow(@sprites)
  end

  def pbDistributeItems
    # Set items to be buried (index in ITEMS, x coord, y coord)
    item_list = ITEMS.clone
    item_list.delete_if { |i| GameData::Item.get(i[0]).is_mega_stone? && !ALLOW_MEGA_STONE_MINING }
    ptotal = 0
    item_list.each do |i|
      ptotal += i[1]
    end
    numitems = rand(2..4)
    tries = 0
    while numitems > 0
      rnd = rand(ptotal)
      added = false
      item_list.length.times do |i|
        rnd -= item_list[i][1]
        if rnd < 0
          if pbNoDuplicateItems(item_list[i][0])
            until added
              provx = rand(BOARD_WIDTH - item_list[i][4] + 1)
              provy = rand(BOARD_HEIGHT - item_list[i][5] + 1)
              if pbCheckOverlaps(false, provx, provy, item_list[i][4], item_list[i][5], item_list[i][6])
                @items.push([i, provx, provy])
                numitems -= 1
                added = true
              end
            end
          else
            break
          end
        end
        break if added
      end
      tries += 1
      break if tries >= 500
    end
    # Draw items on item layer
    layer = @sprites["itemlayer"].bitmap
    @items.each do |i|
      ox = item_list[i[0]][2]
      oy = item_list[i[0]][3]
      rectx = item_list[i[0]][4]
      recty = item_list[i[0]][5]
      layer.blt(32 * i[1], 64 + (32 * i[2]), @itembitmap.bitmap, Rect.new(32 * ox, 32 * oy, 32 * rectx, 32 * recty))
    end
  end

  def pbDistributeIron
    # Set iron to be buried (index in IRON, x coord, y coord)
    numitems = rand(4..6)
    tries = 0
    while numitems > 0
      rnd = rand(IRON.length)
      provx = rand(BOARD_WIDTH - IRON[rnd][2] + 1)
      provy = rand(BOARD_HEIGHT - IRON[rnd][3] + 1)
      if pbCheckOverlaps(true, provx, provy, IRON[rnd][2], IRON[rnd][3], IRON[rnd][4])
        @iron.push([rnd, provx, provy])
        numitems -= 1
      end
      tries += 1
      break if tries >= 500
    end
    # Draw items on item layer
    layer = @sprites["itemlayer"].bitmap
    @iron.each do |i|
      ox = IRON[i[0]][0]
      oy = IRON[i[0]][1]
      rectx = IRON[i[0]][2]
      recty = IRON[i[0]][3]
      layer.blt(32 * i[1], 64 + (32 * i[2]), @ironbitmap.bitmap, Rect.new(32 * ox, 32 * oy, 32 * rectx, 32 * recty))
    end
  end

  def pbNoDuplicateItems(newitem)
    return true if newitem == :HEARTSCALE   # Allow multiple Heart Scales
    fossils = [:DOMEFOSSIL, :HELIXFOSSIL, :OLDAMBER, :ROOTFOSSIL,
               :SKULLFOSSIL, :ARMORFOSSIL, :CLAWFOSSIL, 
               :PLUMEFOSSIL, :COVERFOSSIL, :JAWFOSSIL, :SAILFOSSIL]
    plates = [:INSECTPLATE, :DREADPLATE, :DRACOPLATE, :ZAPPLATE, :FISTPLATE,
              :FLAMEPLATE, :MEADOWPLATE, :EARTHPLATE, :ICICLEPLATE, :TOXICPLATE,
              :MINDPLATE, :STONEPLATE, :SKYPLATE, :SPOOKYPLATE, :IRONPLATE, :SPLASHPLATE]
    megastones = [:GENGARITE, :GARDEVOIRITE, :AMPHAROSITE, :VENUSAURITE, :CHARIZARDITEX, 
                  :CHARIZARDITEY, :BLASTOISINITE, :MEWTWONITEX, :MEWTWONITEY, :BLAZIKENITE, 
                  :MEDICHAMITE, :HOUNDOOMINITE, :AGGRONITE, :BANETTITE, :TYRANITARITE, :SCIZORITE, 
                  :PINSIRITE, :AERODACTYLITE, :LUCARIONITE, :ABOMASITE, :KANGASKHANITE, :GYARADOSITE, 
                  :ABSOLITE, :ALAKAZITE, :HERACRONITE, :MAWILITE, :MANECTITE, :GARCHOMPITE, :LATIASITE, 
                  :LATIOSITE, :SWAMPERTITE, :SCEPTILITE, :SABLENITE, :ALTARIANITE, :GALLADITE, :AUDINITE, 
                  :METAGROSSITE, :SHARPEDONITE, :SLOWBRONITE, :STEELIXITE, :PIDGEOTITE, :GLALITITE, 
                  :DIANCITE, :CAMERUPTITE, :LOPUNNITE, :SALAMENCITE, :BEEDRILLITE]
    item_list = ITEMS.clone
    item_list.delete_if { |i| GameData::Item.get(i[0]).is_mega_stone? && !ALLOW_MEGA_STONE_MINING }
    @items.each do |i|
      preitem = item_list[i[0]][0]
      return false if preitem == newitem   # No duplicate items
      return false if fossils.include?(preitem) && fossils.include?(newitem)
      return false if plates.include?(preitem) && plates.include?(newitem)
      return false if megastones.include?(preitem) && megastones.include?(newitem)
    end
    return true
  end

  def pbCheckOverlaps(checkiron, provx, provy, provwidth, provheight, provpattern)
    item_list = ITEMS.clone
    item_list.delete_if { |i| GameData::Item.get(i[0]).is_mega_stone? && !ALLOW_MEGA_STONE_MINING }
    @items.each do |i|
      prex = i[1]
      prey = i[2]
      prewidth = item_list[i[0]][4]
      preheight = item_list[i[0]][5]
      prepattern = item_list[i[0]][6]
      next if provx + provwidth <= prex || provx >= prex + prewidth ||
              provy + provheight <= prey || provy >= prey + preheight
      prepattern.length.times do |j|
        next if prepattern[j] == 0
        xco = prex + (j % prewidth)
        yco = prey + (j / prewidth).floor
        next if provx + provwidth <= xco || provx > xco ||
                provy + provheight <= yco || provy > yco
        return false if provpattern[xco - provx + ((yco - provy) * provwidth)] == 1
      end
    end
    if checkiron   # Check other irons as well
      @iron.each do |i|
        prex = i[1]
        prey = i[2]
        prewidth = IRON[i[0]][2]
        preheight = IRON[i[0]][3]
        prepattern = IRON[i[0]][4]
        next if provx + provwidth <= prex || provx >= prex + prewidth ||
                provy + provheight <= prey || provy >= prey + preheight
        prepattern.length.times do |j|
          next if prepattern[j] == 0
          xco = prex + (j % prewidth)
          yco = prey + (j / prewidth).floor
          next if provx + provwidth <= xco || provx > xco ||
                  provy + provheight <= yco || provy > yco
          return false if provpattern[xco - provx + ((yco - provy) * provwidth)] == 1
        end
      end
    end
    return true
  end

  def pbHit
    hittype = 0
    position = @sprites["cursor"].position
    if @sprites["cursor"].mode == 1   # Hammer
      pattern = [1, 2, 1,
                 2, 2, 2,
                 1, 2, 1]
      @sprites["crack"].hits += 2 if !($DEBUG && Input.press?(Input::CTRL))
    else                            # Pick
      pattern = [0, 1, 0,
                 1, 2, 1,
                 0, 1, 0]
      @sprites["crack"].hits += 1 if !($DEBUG && Input.press?(Input::CTRL))
    end
    if @sprites["tile#{position}"].layer <= pattern[4] && pbIsIronThere?(position)
      @sprites["tile#{position}"].layer -= pattern[4]
      pbSEPlay("Mining iron")
      hittype = 2
    else
      3.times do |i|
        ytile = i - 1 + (position / BOARD_WIDTH)
        next if ytile < 0 || ytile >= BOARD_HEIGHT
        3.times do |j|
          xtile = j - 1 + (position % BOARD_WIDTH)
          next if xtile < 0 || xtile >= BOARD_WIDTH
          @sprites["tile#{xtile + (ytile * BOARD_WIDTH)}"].layer -= pattern[j + (i * 3)]
        end
      end
      if @sprites["cursor"].mode == 1   # Hammer
        pbSEPlay("Mining hammer")
      else
        pbSEPlay("Mining pick")
      end
    end
    update
    Graphics.update
    hititem = (@sprites["tile#{position}"].layer == 0 && pbIsItemThere?(position))
    hittype = 1 if hititem
    @sprites["cursor"].animate(hittype)
    revealed = pbCheckRevealed
    if revealed.length > 0
      pbSEPlay("Mining reveal full")
      pbFlashItems(revealed)
    elsif hititem
      pbSEPlay("Mining reveal")
    end
  end

  def pbIsItemThere?(position)
    item_list = ITEMS.clone
    item_list.delete_if { |i| GameData::Item.get(i[0]).is_mega_stone? && !ALLOW_MEGA_STONE_MINING }
    posx = position % BOARD_WIDTH
    posy = position / BOARD_WIDTH
    @items.each do |i|
      index = i[0]
      width = item_list[index][4]
      height = item_list[index][5]
      pattern = item_list[index][6]
      next if posx < i[1] || posx >= (i[1] + width)
      next if posy < i[2] || posy >= (i[2] + height)
      dx = posx - i[1]
      dy = posy - i[2]
      return true if pattern[dx + (dy * width)] > 0
    end
    return false
  end

  def pbIsIronThere?(position)
    posx = position % BOARD_WIDTH
    posy = position / BOARD_WIDTH
    @iron.each do |i|
      index = i[0]
      width = IRON[index][2]
      height = IRON[index][3]
      pattern = IRON[index][4]
      next if posx < i[1] || posx >= (i[1] + width)
      next if posy < i[2] || posy >= (i[2] + height)
      dx = posx - i[1]
      dy = posy - i[2]
      return true if pattern[dx + (dy * width)] > 0
    end
    return false
  end

  def pbCheckRevealed
    ret = []
    item_list = ITEMS.clone
    item_list.delete_if { |i| GameData::Item.get(i[0]).is_mega_stone? && !ALLOW_MEGA_STONE_MINING }
    @items.length.times do |i|
      next if @items[i][3]
      revealed = true
      index = @items[i][0]
      width = item_list[index][4]
      height = item_list[index][5]
      pattern = item_list[index][6]
      height.times do |j|
        width.times do |k|
          layer = @sprites["tile#{@items[i][1] + k + ((@items[i][2] + j) * BOARD_WIDTH)}"].layer
          revealed = false if layer > 0 && pattern[k + (j * width)] > 0
          break if !revealed
        end
        break if !revealed
      end
      ret.push(i) if revealed
    end
    return ret
  end

  def pbFlashItems(revealed)
    return if revealed.length <= 0
    revealeditems = BitmapSprite.new(Graphics.width, Graphics.height, @viewport)
    revealeditems.z = 15
    revealeditems.color = Color.new(255, 255, 255, 0)
    flash_duration = 0.25
    item_list = ITEMS.clone
    item_list.delete_if { |i| GameData::Item.get(i[0]).is_mega_stone? && !ALLOW_MEGA_STONE_MINING }
    2.times do |i|
      alpha_start = (i == 0) ? 0 : 255
      alpha_end = (i == 0) ? 255 : 0
      timer_start = System.uptime
      loop do
        revealed.each do |index|
          burieditem = @items[index]
          revealeditems.bitmap.blt(32 * burieditem[1], 64 + (32 * burieditem[2]),
                                   @itembitmap.bitmap,
                                   Rect.new(32 * item_list[burieditem[0]][2], 32 * item_list[burieditem[0]][3],
                                            32 * item_list[burieditem[0]][4], 32 * item_list[burieditem[0]][5]))
        end
        flash_alpha = lerp(alpha_start, alpha_end, flash_duration / 2, timer_start, System.uptime)
        revealeditems.color.alpha = flash_alpha
        update
        Graphics.update
        break if flash_alpha == alpha_end
      end
    end
    revealeditems.dispose
    revealed.each do |index|
      @items[index][3] = true
      item = item_list[@items[index][0]][0]
      @itemswon.push(item)
    end
  end

  def pbMain
    pbSEPlay("Mining ping")
    pbMessage(_INTL("¡Se ha detectado algo en la pared!\n¡{1} confirmados!", @items.length))
    loop do
      update
      Graphics.update
      Input.update
      next if @sprites["cursor"].isAnimating?
      # Check end conditions
      if @sprites["crack"].hits >= 49
        @sprites["cursor"].visible = false
        pbSEPlay("Mining collapse")
        @sprites["collapse"] = BitmapSprite.new(Graphics.width, Graphics.height, @viewport)
        @sprites["collapse"].z = 999
        timer_start = System.uptime
        loop do
          collapse_height = lerp(0, Graphics.height, 0.8, timer_start, System.uptime)
          @sprites["collapse"].bitmap.fill_rect(0, 0, Graphics.width, collapse_height, Color.black)
          Graphics.update
          break if collapse_height == Graphics.height
        end
        pbMessage(_INTL("¡La pared se derrumbó!"))
        break
      end
      foundall = true
      @items.each do |i|
        foundall = false if !i[3]
        break if !foundall
      end
      if foundall
        @sprites["cursor"].visible = false
        pbWait(0.75)
        pbSEPlay("Mining found all")
        pbMessage(_INTL("¡Todo ha sido desenterrado!"))
        break
      end
      # Input
      if Input.trigger?(Input::UP) || Input.repeat?(Input::UP)
        if @sprites["cursor"].position >= BOARD_WIDTH
          pbSEPlay("Mining cursor")
          @sprites["cursor"].position -= BOARD_WIDTH
        end
      elsif Input.trigger?(Input::DOWN) || Input.repeat?(Input::DOWN)
        if @sprites["cursor"].position < (BOARD_WIDTH * (BOARD_HEIGHT - 1))
          pbSEPlay("Mining cursor")
          @sprites["cursor"].position += BOARD_WIDTH
        end
      elsif Input.trigger?(Input::LEFT) || Input.repeat?(Input::LEFT)
        if @sprites["cursor"].position % BOARD_WIDTH > 0
          pbSEPlay("Mining cursor")
          @sprites["cursor"].position -= 1
        end
      elsif Input.trigger?(Input::RIGHT) || Input.repeat?(Input::RIGHT)
        if @sprites["cursor"].position % BOARD_WIDTH < (BOARD_WIDTH - 1)
          pbSEPlay("Mining cursor")
          @sprites["cursor"].position += 1
        end
      elsif Input.trigger?(Input::ACTION)   # Change tool mode
        pbSEPlay("Mining tool change")
        newmode = (@sprites["cursor"].mode + 1) % 2
        @sprites["cursor"].mode = newmode
        @sprites["tool"].src_rect.set(newmode * 68, 0, 68, 100)
        @sprites["tool"].y = 254 - (144 * newmode)
      elsif Input.trigger?(Input::USE)   # Hit
        pbHit
      elsif Input.trigger?(Input::BACK)   # Quit
        break if pbConfirmMessage(_INTL("¿Estás segur{1} de que te quieres retirar?", $player.female? ? 'a' : 'o'))
      end
    end
    pbGiveItems
  end

  def pbGiveItems
    if @itemswon.length > 0
      @itemswon.each do |i|
        if $bag.add(i)
          pbMessage(_INTL("Has obtenido {1}.", GameData::Item.get(i).name) + "\\se[Mining item get]\\wtnp[30]")
        else
          pbMessage(_INTL("Has obtenido {1}, pero no tienes espacio en tu Mochila.",
                          GameData::Item.get(i).name))
        end
      end
    end
  end

  def pbEndScene
    pbFadeOutAndHide(@sprites)
    pbDisposeSpriteHash(@sprites)
    @viewport.dispose
  end
end

#===============================================================================
#
#===============================================================================
class MiningGame
  def initialize(scene)
    @scene = scene
  end

  def pbStartScreen
    @scene.pbStartScene
    @scene.pbMain
    @scene.pbEndScene
  end
end

#===============================================================================
#
#===============================================================================
def pbMiningGame
  pbFadeOutIn do
    scene = MiningGameScene.new
    screen = MiningGame.new(scene)
    screen.pbStartScreen
  end
end


==============================================================================
# Script: Minigame_TilePuzzles
==============================================================================
#===============================================================================
# Mini-juegos "Rompecabezas de Baldosas"
# Por Maruno
# Gráficos por the__end
#-------------------------------------------------------------------------------
# Ejecutar con:      pbTilePuzzle(game,board,width,height)
# game = 1 (rompecabezas de las Ruinas de Alfa),
#        2 (rompecabezas de las Ruinas de Alfa con rotaciones de fichas),
#        3 (Cuadrado Místico),
#        4 (intercambiar dos fichas adyacentes),
#        5 (intercambiar dos fichas adyacentes más rotaciones de fichas),
#        6 (cuadrado de Rubik),
#        7 (rotar ficha seleccionada más fichas adyacentes a la vez).
# board = El nombre/número de los gráficos que se utilizarán.
# width,height = Opcional, el número de fichas de ancho/alto del rompecabezas 
#                (0 para el valor predeterminado de 4).
#===============================================================================
class TilePuzzleCursor < BitmapSprite
  attr_accessor :game
  attr_accessor :position
  attr_accessor :arrows
  attr_accessor :selected
  attr_accessor :holding

  def initialize(game, position, tilewidth, tileheight, boardwidth, boardheight)
    @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = 99999
    super(Graphics.width, Graphics.height, @viewport)
    @game = game
    @position = position
    @tilewidth = tilewidth
    @tileheight = tileheight
    @boardwidth = boardwidth
    @boardheight = boardheight
    @arrows = []
    @selected = false
    @holding = false
    @cursorbitmap = AnimatedBitmap.new("Graphics/UI/Tile Puzzle/cursor")
    update
  end

  def update
    self.bitmap.clear
    x = (Graphics.width - (@tilewidth * @boardwidth)) / 2
    if @position >= @boardwidth * @boardheight
      x = ((x - (@tilewidth * (@boardwidth / 2).ceil)) / 2) - 10
      if (@position % @boardwidth) >= (@boardwidth / 2).ceil
        x = Graphics.width - x - (@tilewidth * @boardwidth)
      end
    end
    x += @tilewidth * (@position % @boardwidth)
    y = ((Graphics.height - (@tileheight * @boardheight)) / 2) - 32
    y += @tileheight * ((@position % (@boardwidth * @boardheight)) / @boardwidth)
    self.tone = Tone.new(0, (@holding ? 64 : 0), (@holding ? 64 : 0), 0)
    # Cursor
    if @game != 3
      expand = (@holding) ? 0 : 4
      4.times do |i|
        self.bitmap.blt(
          x + ((i % 2) * (@tilewidth - (@cursorbitmap.width / 4))) + (expand * (((i % 2) * 2) - 1)),
          y + ((i / 2) * (@tileheight - (@cursorbitmap.height / 2))) + (expand * (((i / 2) * 2) - 1)),
          @cursorbitmap.bitmap, Rect.new((i % 2) * @cursorbitmap.width / 4,
                                         (i / 2) * @cursorbitmap.height / 2,
                                         @cursorbitmap.width / 4, @cursorbitmap.height / 2)
        )
      end
    end
    # Arrows
    if @selected || @game == 3
      expand = (@game == 3) ? 0 : 4
      xin = [(@tilewidth - (@cursorbitmap.width / 4)) / 2, -expand,
             @tilewidth - (@cursorbitmap.width / 4) + expand, (@tilewidth - (@cursorbitmap.width / 4)) / 2]
      yin = [@tileheight - (@cursorbitmap.height / 2) + expand, (@tileheight - (@cursorbitmap.height / 2)) / 2,
             (@tileheight - (@cursorbitmap.height / 2)) / 2, -expand]
      4.times do |i|
        next if !@arrows[i]
        self.bitmap.blt(x + xin[i], y + yin[i], @cursorbitmap.bitmap,
                        Rect.new((@cursorbitmap.width / 2) + ((i % 2) * (@cursorbitmap.width / 4)),
                                 (i / 2) * (@cursorbitmap.height / 2),
                                 @cursorbitmap.width / 4, @cursorbitmap.height / 2))
      end
    end
  end
end

#===============================================================================
#
#===============================================================================
class TilePuzzleScene
  def initialize(game, board, width, height)
    @game = game
    @board = board
    @boardwidth = (width > 0) ? width : 4
    @boardheight = (height > 0) ? height : 4
  end

  def update
    xtop = (Graphics.width - (@tilewidth * @boardwidth)) / 2
    ytop = ((Graphics.height - (@tileheight * @boardheight)) / 2) + (@tileheight / 2) - 32
    (@boardwidth * @boardheight).times do |i|
      pos = -1
      @tiles.length.times do |j|
        pos = j if @tiles[j] == i
      end
      @sprites["tile#{i}"].z = 0
      @sprites["tile#{i}"].tone = Tone.new(0, 0, 0, 0)
      if @heldtile == i
        pos = @sprites["cursor"].position
        @sprites["tile#{i}"].z = 1
        @sprites["tile#{i}"].tone = Tone.new(64, 0, 0, 0) if @tiles[pos] >= 0
      end
      thisx = xtop
      if pos >= 0
        if pos >= @boardwidth * @boardheight
          thisx = ((xtop - (@tilewidth * (@boardwidth / 2).ceil)) / 2) - 10
          if (pos % @boardwidth) >= (@boardwidth / 2).ceil
            thisx = Graphics.width - thisx - (@tilewidth * @boardwidth)
          end
        end
        @sprites["tile#{i}"].x = thisx + (@tilewidth * (pos % @boardwidth)) + (@tilewidth / 2)
        @sprites["tile#{i}"].y = ytop + (@tileheight * ((pos % (@boardwidth * @boardheight)) / @boardwidth))
        next if @game == 3
        rotatebitmaps = [@tilebitmap, @tilebitmap1, @tilebitmap2, @tilebitmap3]
        @sprites["tile#{i}"].bitmap.clear
        if rotatebitmaps[@angles[i]]
          @sprites["tile#{i}"].bitmap.blt(0, 0, rotatebitmaps[@angles[i]].bitmap,
                                          Rect.new(@tilewidth * (i % @boardwidth), @tileheight * (i / @boardwidth), @tilewidth, @tileheight))
          @sprites["tile#{i}"].angle = 0
        else
          @sprites["tile#{i}"].bitmap.blt(0, 0, @tilebitmap.bitmap,
                                          Rect.new(@tilewidth * (i % @boardwidth), @tileheight * (i / @boardwidth), @tilewidth, @tileheight))
          @sprites["tile#{i}"].angle = @angles[i] * 90
        end
      end
    end
    updateCursor
    pbUpdateSpriteHash(@sprites)
  end

  def updateCursor
    arrows = []
    4.times do |i|
      arrows.push(pbCanMoveInDir?(@sprites["cursor"].position, (i + 1) * 2, @game == 6))
    end
    @sprites["cursor"].arrows = arrows
  end

  def pbStartScene
    @sprites = {}
    @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = 99999
    if pbResolveBitmap("Graphics/UI/Tile Puzzle/bg#{@board}")
      addBackgroundPlane(@sprites, "bg", "Tile Puzzle/bg#{@board}", @viewport)
    else
      addBackgroundPlane(@sprites, "bg", "Tile Puzzle/bg", @viewport)
    end
    @tilebitmap = AnimatedBitmap.new("Graphics/UI/Tile Puzzle/tiles#{@board}")
    @tilebitmap1 = nil
    @tilebitmap2 = nil
    @tilebitmap3 = nil
    if pbResolveBitmap("Graphics/UI/Tile Puzzle/tiles#{@board}_1")
      @tilebitmap1 = AnimatedBitmap.new("Graphics/UI/Tile Puzzle/tiles#{@board}_1")
    end
    if pbResolveBitmap("Graphics/UI/Tile Puzzle/tiles#{@board}_2")
      @tilebitmap2 = AnimatedBitmap.new("Graphics/UI/Tile Puzzle/tiles#{@board}_2")
    end
    if pbResolveBitmap("Graphics/UI/Tile Puzzle/tiles#{@board}_3")
      @tilebitmap3 = AnimatedBitmap.new("Graphics/UI/Tile Puzzle/tiles#{@board}_3")
    end
    @tilewidth = @tilebitmap.width / @boardwidth
    @tileheight = @tilebitmap.height / @boardheight
    (@boardwidth * @boardheight).times do |i|
      @sprites["tile#{i}"] = BitmapSprite.new(@tilewidth, @tileheight, @viewport)
      @sprites["tile#{i}"].ox = @tilewidth / 2
      @sprites["tile#{i}"].oy = @tileheight / 2
      break if @game == 3 && i >= (@boardwidth * @boardheight) - 1
      @sprites["tile#{i}"].bitmap.blt(0, 0, @tilebitmap.bitmap,
                                      Rect.new(@tilewidth * (i % @boardwidth), @tileheight * (i / @boardwidth), @tilewidth, @tileheight))
    end
    @heldtile = -1
    @angles = []
    @tiles = pbShuffleTiles
    @sprites["cursor"] = TilePuzzleCursor.new(@game, pbDefaultCursorPosition,
                                              @tilewidth, @tileheight, @boardwidth, @boardheight)
    update
    pbFadeInAndShow(@sprites)
  end

  def pbShuffleTiles
    ret = []
    (@boardwidth * @boardheight).times do |i|
      ret.push(i)
      @angles.push(0)
    end
    case @game
    when 6
      @tiles = ret
      5.times do
        pbShiftLine([2, 4, 6, 8][rand(4)], rand(@boardwidth * @boardheight), false)
      end
      return @tiles
    when 7
      @tiles = ret
      5.times do
        pbRotateTile(rand(@boardwidth * @boardheight), false)
      end
    else
      ret.shuffle!
      if @game == 3  # Make sure only solvable Mystic Squares are allowed.
        num = 0
        blank = -1
        (ret.length - 1).times do |i|
          blank = i if ret[i] == (@boardwidth * @boardheight) - 1
          (i...ret.length).each do |j|
            num += 1 if ret[j] < ret[i] && ret[i] != (@boardwidth * @boardheight) - 1 &&
                        ret[j] != (@boardwidth * @boardheight) - 1
          end
        end
        if @boardwidth.odd?
          ret = pbShuffleTiles if num.odd?
        elsif num.even? == (@boardheight - (blank / @boardwidth)).even?
          ret = pbShuffleTiles
        end
      end
      if @game == 1 || @game == 2
        ret2 = []
        (@boardwidth * @boardheight).times do |i|
          ret2.push(-1)
        end
        ret = ret2 + ret
      end
      if @game == 2 || @game == 5
        @angles.length.times do |i|
          @angles[i] = rand(4)
        end
      end
    end
    return ret
  end

  def pbDefaultCursorPosition
    if @game == 3
      (@boardwidth * @boardheight).times do |i|
        return i if @tiles[i] == (@boardwidth * @boardheight) - 1
      end
    end
    return 0
  end

  def pbMoveCursor(pos, dir)
    case dir
    when 2
      pos += @boardwidth
    when 4
      if pos >= @boardwidth * @boardheight
        if pos % @boardwidth == (@boardwidth / 2).ceil
          pos = (((pos % (@boardwidth * @boardheight)) / @boardwidth) * @boardwidth) + @boardwidth - 1
        else
          pos -= 1
        end
      elsif (pos % @boardwidth) == 0
        pos = (((pos / @boardwidth) + @boardheight) * @boardwidth) + (@boardwidth / 2).ceil - 1
      else
        pos -= 1
      end
    when 6
      if pos >= @boardwidth * @boardheight
        if pos % @boardwidth == (@boardwidth / 2).ceil - 1
          pos = ((pos % (@boardwidth * @boardheight)) / @boardwidth) * @boardwidth
        else
          pos += 1
        end
      elsif pos % @boardwidth >= @boardwidth - 1
        pos = (((pos / @boardwidth) + @boardheight) * @boardwidth) + (@boardwidth / 2).ceil
      else
        pos += 1
      end
    when 8
      pos -= @boardwidth
    end
    return pos
  end

  def pbCanMoveInDir?(pos, dir, swapping)
    return true if @game == 6 && swapping
    case dir
    when 2
      return false if (pos / @boardwidth) % @boardheight >= @boardheight - 1
    when 4
      if @game == 1 || @game == 2
        return false if pos >= @boardwidth * @boardheight && pos % @boardwidth == 0
      else
        return false if pos % @boardwidth == 0
      end
    when 6
      if @game == 1 || @game == 2
        return false if pos >= @boardwidth * @boardheight && pos % @boardwidth >= @boardwidth - 1
      else
        return false if pos % @boardwidth >= @boardwidth - 1
      end
    when 8
      return false if (pos / @boardwidth) % @boardheight == 0
    end
    return true
  end

  def pbRotateTile(pos, anim = true)
    if @heldtile >= 0
      if anim
        @sprites["cursor"].visible = false
        @sprites["tile#{@heldtile}"].z = 1
        old_angle = @sprites["tile#{@heldtile}"].angle
        timer_start = System.uptime
        loop do
          @sprites["tile#{@heldtile}"].angle = lerp(old_angle, old_angle - 90, 0.25, timer_start, System.uptime)
          pbUpdateSpriteHash(@sprites)
          Graphics.update
          Input.update
          break if @sprites["tile#{@heldtile}"].angle == old_angle - 90
        end
        @sprites["tile#{@heldtile}"].z = 0
        @sprites["cursor"].visible = true if !pbCheckWin
      end
      @angles[@heldtile] -= 1
      @angles[@heldtile] += 4 if @angles[@heldtile] < 0
    else
      return if @tiles[pos] < 0
      group = pbGetNearTiles(pos)
      if anim
        @sprites["cursor"].visible = false
        old_angles = []
        group.each do |i|
          @sprites["tile#{@tiles[i]}"].z = 1
          old_angles.push(@sprites["tile#{@tiles[i]}"].angle)
        end
        timer_start = System.uptime
        loop do
          group.each_with_index do |idx, i|
            @sprites["tile#{@tiles[idx]}"].angle = lerp(old_angles[i], old_angles[i] - 90, 0.25, timer_start, System.uptime)
          end
          pbUpdateSpriteHash(@sprites)
          Graphics.update
          Input.update
          break if @sprites["tile#{@tiles[group[0]]}"].angle == old_angles[0] - 90
        end
        group.each do |i|
          @sprites["tile#{@tiles[i]}"].z = 0
        end
        @sprites["cursor"].visible = true if !pbCheckWin
      end
      group.each do |i|
        tile = @tiles[i]
        @angles[tile] -= 1
        @angles[tile] += 4 if @angles[tile] < 0
      end
    end
  end

  def pbGetNearTiles(pos)
    ret = [pos]
    if @game == 7
      [2, 4, 6, 8].each do |i|
        ret.push(pbMoveCursor(pos, i)) if pbCanMoveInDir?(pos, i, true)
      end
    end
    return ret
  end

  def pbSwapTiles(dir)
    cursor = @sprites["cursor"].position
    return pbShiftLine(dir, cursor) if @game == 6
    movetile = pbMoveCursor(cursor, dir)
    @sprites["cursor"].visible = false
    @sprites["tile#{@tiles[cursor]}"].z = 1
    duration = 0.3
    timer_start = System.uptime
    if [2, 8].include?(dir)   # Swap vertically
      start_sprite_pos = @sprites["tile#{@tiles[movetile]}"].y
      start_cursor_pos = @sprites["tile#{@tiles[cursor]}"].y
      dist = (dir / 4).floor - 1
      loop do
        delta_y = lerp(0, @tileheight * dist, duration, timer_start, System.uptime)
        @sprites["tile#{@tiles[movetile]}"].y = start_sprite_pos + delta_y
        @sprites["tile#{@tiles[cursor]}"].y = start_cursor_pos - delta_y
        pbUpdateSpriteHash(@sprites)
        Graphics.update
        Input.update
        break if @sprites["tile#{@tiles[movetile]}"].y == start_sprite_pos + (@tileheight * dist)
      end
    else   # Swap horizontally
      start_sprite_pos = @sprites["tile#{@tiles[movetile]}"].x
      start_cursor_pos = @sprites["tile#{@tiles[cursor]}"].x
      dist = dir - 5
      loop do
        delta_x = lerp(0, @tilewidth * dist, duration, timer_start, System.uptime)
        @sprites["tile#{@tiles[movetile]}"].x = start_sprite_pos - delta_x
        @sprites["tile#{@tiles[cursor]}"].x = start_cursor_pos + delta_x
        pbUpdateSpriteHash(@sprites)
        Graphics.update
        Input.update
        break if @sprites["tile#{@tiles[movetile]}"].x == start_sprite_pos - (@tilewidth * dist)
      end
    end
    @tiles[cursor], @tiles[movetile] = @tiles[movetile], @tiles[cursor]
    @sprites["tile#{@tiles[cursor]}"].z = 0
    @sprites["cursor"].position = movetile
    @sprites["cursor"].selected = false
    @sprites["cursor"].visible = true if !pbCheckWin
    return true
  end

  def pbShiftLine(dir, cursor, anim = true)
    # Get tiles involved
    tiles = []
    dist = 0
    if [2, 8].include?(dir)
      dist = (dir / 4).floor - 1
      while (dist > 0 && cursor < (@boardwidth - 1) * @boardheight) ||
            (dist < 0 && cursor >= @boardwidth)
        cursor += (@boardwidth * dist)
      end
      @boardheight.times do |i|
        tiles.push(cursor - (i * dist * @boardwidth))
      end
    else
      dist = dir - 5
      while (dist > 0 && cursor % @boardwidth > 0) ||
            (dist < 0 && cursor % @boardwidth < @boardwidth - 1)
        cursor -= dist
      end
      @boardwidth.times do |i|
        tiles.push(cursor + (i * dist))
      end
    end
    # Shift tiles
    fade_duration = 0.4
    if anim
      @sprites["cursor"].visible = false
      timer_start = System.uptime
      loop do
        end_tile = @sprites["tile#{@tiles[tiles[tiles.length - 1]]}"]
        end_tile.opacity = lerp(255, 0, fade_duration, timer_start, System.uptime)
        Graphics.update
        Input.update
        break if end_tile.opacity == 0
      end
      duration = 0.3
      timer_start = System.uptime
      start_pos = []
      if [2, 8].include?(dir)
        tiles.each { |i| start_pos.push(@sprites["tile#{@tiles[i]}"].y) }
        loop do
          tiles.each_with_index do |idx, i|
            @sprites["tile#{@tiles[idx]}"].y = lerp(start_pos[i], start_pos[i] - (@tileheight * dist), duration, timer_start, System.uptime)
          end
          pbUpdateSpriteHash(@sprites)
          Graphics.update
          Input.update
          break if @sprites["tile#{@tiles[tiles[0]]}"].y == start_pos[0] - (@tileheight * dist)
        end
      else
        tiles.each { |i| start_pos.push(@sprites["tile#{@tiles[i]}"].x) }
        loop do
          tiles.each_with_index do |idx, i|
            @sprites["tile#{@tiles[idx]}"].x = lerp(start_pos[i], start_pos[i] + (@tilewidth * dist), duration, timer_start, System.uptime)
          end
          pbUpdateSpriteHash(@sprites)
          Graphics.update
          Input.update
          break if @sprites["tile#{@tiles[tiles[0]]}"].x == start_pos[0] + (@tilewidth * dist)
        end
      end
    end
    temp = []
    tiles.each do |i|
      temp.push(@tiles[i])
    end
    temp.length.times do |i|
      @tiles[tiles[(i + 1) % (temp.length)]] = temp[i]
    end
    if anim
      update
      timer_start = System.uptime
      loop do
        end_tile = @sprites["tile#{@tiles[tiles[0]]}"]
        end_tile.opacity = lerp(0, 255, fade_duration, timer_start, System.uptime)
        Graphics.update
        Input.update
        break if end_tile.opacity == 255
      end
      @sprites["cursor"].selected = false
      @sprites["cursor"].visible = true if !pbCheckWin
    end
    return true
  end

  def pbGrabTile(pos)
    @heldtile, @tiles[pos] = @tiles[pos], @heldtile
    @sprites["cursor"].holding = (@heldtile >= 0)
    @sprites["cursor"].visible = false if pbCheckWin
  end

  def pbCheckWin
    (@boardwidth * @boardheight).times do |i|
      return false if @tiles[i] != i
      return false if @angles[i] != 0
    end
    return true
  end

  def pbMain
    loop do
      update
      Graphics.update
      Input.update
      # Check end conditions
      if pbCheckWin
        @sprites["cursor"].visible = false
        if @game == 3
          extratile = @sprites["tile#{(@boardwidth * @boardheight) - 1}"]
          extratile.bitmap.clear
          extratile.bitmap.blt(0, 0, @tilebitmap.bitmap,
                               Rect.new(@tilewidth * (@boardwidth - 1), @tileheight * (@boardheight - 1),
                                        @tilewidth, @tileheight))
          extratile.opacity = 0
          timer_start = System.uptime
          loop do
            extratile.opacity = lerp(0, 255, 0.8, timer_start, System.uptime)
            Graphics.update
            Input.update
            break if extratile.opacity >= 255
          end
        else
          pbWait(0.5)
        end
        loop do
          Graphics.update
          Input.update
          break if Input.trigger?(Input::USE) || Input.trigger?(Input::BACK)
        end
        return true
      end
      # Input
      @sprites["cursor"].selected = (Input.press?(Input::USE) && @game >= 3 && @game <= 6)
      dir = 0
      dir = 2 if Input.trigger?(Input::DOWN) || Input.repeat?(Input::DOWN)
      dir = 4 if Input.trigger?(Input::LEFT) || Input.repeat?(Input::LEFT)
      dir = 6 if Input.trigger?(Input::RIGHT) || Input.repeat?(Input::RIGHT)
      dir = 8 if Input.trigger?(Input::UP) || Input.repeat?(Input::UP)
      if dir > 0
        if @game == 3 || (@game != 3 && @sprites["cursor"].selected)
          if pbCanMoveInDir?(@sprites["cursor"].position, dir, true)
            pbSEPlay("Tile Game cursor")
            pbSwapTiles(dir)
          end
        else
          if pbCanMoveInDir?(@sprites["cursor"].position, dir, false)
            pbSEPlay("Tile Game cursor")
            @sprites["cursor"].position = pbMoveCursor(@sprites["cursor"].position, dir)
          end
        end
      elsif (@game == 1 || @game == 2) && Input.trigger?(Input::USE)
        pbGrabTile(@sprites["cursor"].position)
      elsif (@game == 2 && Input.trigger?(Input::ACTION)) ||
            (@game == 5 && Input.trigger?(Input::ACTION)) ||
            (@game == 7 && Input.trigger?(Input::USE))
        pbRotateTile(@sprites["cursor"].position)
      elsif Input.trigger?(Input::BACK)
        return false
      end
    end
  end

  def pbEndScene
    pbFadeOutAndHide(@sprites)
    pbDisposeSpriteHash(@sprites)
    @viewport.dispose
  end
end

