==============================================================================
# Script: SafariZone
==============================================================================
#===============================================================================
#
#===============================================================================
class SafariState
  attr_accessor :ballcount
  attr_accessor :captures
  attr_accessor :decision
  attr_accessor :steps

  def initialize
    @start      = nil
    @ballcount  = 0
    @captures   = 0
    @inProgress = false
    @steps      = 0
    @decision   = 0
  end

  def pbReceptionMap
    return @inProgress ? @start[0] : 0
  end

  def inProgress?
    return @inProgress
  end

  def pbGoToStart
    if $scene.is_a?(Scene_Map)
      pbFadeOutIn do
        $game_temp.player_transferring   = true
        $game_temp.transition_processing = true
        $game_temp.player_new_map_id    = @start[0]
        $game_temp.player_new_x         = @start[1]
        $game_temp.player_new_y         = @start[2]
        $game_temp.player_new_direction = 2
        pbDismountBike
        $scene.transfer_player
      end
    end
  end

  def pbStart(ballcount)
    @start      = [$game_map.map_id, $game_player.x, $game_player.y, $game_player.direction]
    @ballcount  = ballcount
    @inProgress = true
    @steps      = Settings::SAFARI_STEPS
  end

  def pbEnd
    @start      = nil
    @ballcount  = 0
    @captures   = 0
    @inProgress = false
    @steps      = 0
    @decision   = 0
    $game_map.need_refresh = true
  end
end

#===============================================================================
#
#===============================================================================
def pbInSafari?
  if pbSafariState.inProgress?
    # Reception map is handled separately from safari map since the reception
    # map can be outdoors, with its own grassy patches.
    reception = pbSafariState.pbReceptionMap
    return true if $game_map.map_id == reception
    return true if $game_map.metadata&.safari_map
  end
  return false
end

def pbSafariState
  $PokemonGlobal.safariState = SafariState.new if !$PokemonGlobal.safariState
  return $PokemonGlobal.safariState
end

#===============================================================================
#
#===============================================================================
EventHandlers.add(:on_enter_map, :end_safari_game,
  proc { |_old_map_id|
    pbSafariState.pbEnd if !pbInSafari?
  }
)

EventHandlers.add(:on_player_step_taken_can_transfer, :safari_game_counter,
  proc { |handled|
    # handled is an array: [nil]. If [true], a transfer has happened because of
    # this event, so don't do anything that might cause another one
    next if handled[0]
    next if Settings::SAFARI_STEPS == 0 || !pbInSafari? || pbSafariState.decision != 0
    pbSafariState.steps -= 1
    next if pbSafariState.steps > 0
    pbMessage("\\se[Safari Zone end]" + _INTL("Megafonía: ¡Ding-dong!") + "\\wtnp[20]\1")
    pbMessage(_INTL("Megafonía: ¡Tu partida del Safari ha terminado!"))
    pbSafariState.decision = 1
    pbSafariState.pbGoToStart
    handled[0] = true
  }
)

#===============================================================================
#
#===============================================================================
EventHandlers.add(:on_calling_wild_battle, :safari_battle,
  proc { |pkmn, handled|
    # handled is an array: [nil]. If [true] or [false], the battle has already
    # been overridden (the boolean is its outcome), so don't do anything that
    # would override it again
    next if !handled[0].nil?
    next if !pbInSafari?
    handled[0] = pbSafariBattle(pkmn)
  }
)

def pbSafariBattle(pkmn, level = 1)
  # Generate a wild Pokémon based on the species and level
  pkmn = pbGenerateWildPokemon(pkmn, level) if !pkmn.is_a?(Pokemon)
  foeParty = [pkmn]
  # Calculate who the trainer is
  playerTrainer = $player
  # Create the battle scene (the visual side of it)
  scene = BattleCreationHelperMethods.create_battle_scene
  # Create the battle class (the mechanics side of it)
  battle = SafariBattle.new(scene, playerTrainer, foeParty)
  battle.ballCount = pbSafariState.ballcount
  BattleCreationHelperMethods.prepare_battle(battle)
  # Perform the battle itself
  outcome = Battle::Outcome::UNDECIDED
  pbBattleAnimation(pbGetWildBattleBGM(foeParty), 0, foeParty) do
    pbSceneStandby { outcome = battle.pbStartBattle }
  end
  Input.update
  # Update Safari game data based on result of battle
  pbSafariState.ballcount = battle.ballCount
  if pbSafariState.ballcount <= 0
    if outcome != Battle::Outcome::LOSE   # Last Safari Ball was used to catch the wild Pokémon
      pbMessage(_INTL("Megafonía: ¡Se te acabaron las Safari Balls! ¡Se acabó el tiempo!"))
    end
    pbSafariState.decision = 1
    pbSafariState.pbGoToStart
  end
  # Save the result of the battle in Game Variable 1
  #    0 - Undecided or aborted
  #    2 - Player ran out of Safari Balls
  #    3 - Player or wild Pokémon ran from battle, or player forfeited the match
  #    4 - Wild Pokémon was caught
  if outcome == Battle::Outcome::CATCH
    $stats.safari_pokemon_caught += 1
    pbSafariState.captures += 1
    $stats.most_captures_per_safari_game = [$stats.most_captures_per_safari_game, pbSafariState.captures].max
  end
  pbSet(1, outcome)
  # Used by the Poké Radar to update/break the chain
  EventHandlers.trigger(:on_wild_battle_end, pkmn.species_data.id, pkmn.level, outcome)
  # Return the outcome of the battle
  return outcome
end

#===============================================================================
#
#===============================================================================
class PokemonPauseMenu
  alias __safari_pbShowInfo pbShowInfo unless method_defined?(:__safari_pbShowInfo)

  def pbShowInfo
    __safari_pbShowInfo
    return if !pbInSafari?
    if Settings::SAFARI_STEPS <= 0
      @scene.pbShowInfo(_INTL("Balls: {1}", pbSafariState.ballcount))
    else
      @scene.pbShowInfo(_INTL("Pasos: {1}/{2}\nBalls: {3}",
                              pbSafariState.steps, Settings::SAFARI_STEPS, pbSafariState.ballcount))
    end
  end
end

MenuHandlers.add(:pause_menu, :quit_safari_game, {
  "name"      => _INTL("Salir"),
  "order"     => 60,
  "condition" => proc { next pbInSafari? },
  "effect"    => proc { |menu|
    menu.pbHideMenu
    if pbConfirmMessage(_INTL("¿Quieres salir de la partida actual del Safari en este momento?"))
      menu.pbEndScene
      pbSafariState.decision = 1
      pbSafariState.pbGoToStart
      next true
    end
    menu.pbRefresh
    menu.pbShowMenu
    next false
  }
})


==============================================================================
# Script: BugContest
==============================================================================
#===============================================================================
#
#===============================================================================
class BugContestState
  attr_accessor :ballcount
  attr_accessor :decision
  attr_accessor :lastPokemon
  attr_accessor :timer_start

  CONTESTANT_NAMES = [
    _INTL("Cazabichos Edu"),
    _INTL("Cazabichos Benito"),
    _INTL("Cazabichos José"),
    _INTL("Campista Barry"),
    _INTL("Entre. Guay Nico"),
    _INTL("Chica Alba"),
    _INTL("Dominguero Cintia"),
    _INTL("Joven Samuel")
  ]
  TIME_ALLOWED = Settings::BUG_CONTEST_TIME   # In seconds

  def initialize
    clear
    @lastContest = nil
  end

  # Returns whether the last contest ended less than 24 hours ago.
  def pbContestHeld?
    return false if !@lastContest
    return pbGetTimeNow.to_i - @lastContest < 24 * 60 * 60   # 24 hours
  end

  def expired?
    return false if !undecided?
    return false if TIME_ALLOWED <= 0
    return System.uptime - timer_start >= TIME_ALLOWED
  end

  def clear
    @ballcount    = 0
    @ended        = false
    @inProgress   = false
    @decision     = 0
    @lastPokemon  = nil
    @otherparty   = []
    @contestants  = []
    @places       = []
    @start        = nil
    @contestMaps  = []
    @reception    = []
  end

  def inProgress?
    return @inProgress
  end

  def undecided?
    return (@inProgress && @decision == 0)
  end

  def decided?
    return (@inProgress && @decision != 0) || @ended
  end

  def pbSetPokemon(chosenpoke)
    @chosenPokemon = chosenpoke
  end

  def pbSetContestMap(*maps)
    maps.each do |map|
      if map.is_a?(String)   # Map metadata flag
        GameData::MapMetadata.each do |map_data|
          @contestMaps.push(map_data.id) if map_data.has_flag?(map)
        end
      else
        @contestMaps.push(map)
      end
    end
  end

  # Reception map is handled separately from contest map since the reception map
  # can be outdoors, with its own grassy patches.
  def pbSetReception(*maps)
    maps.each do |map|
      if map.is_a?(String)   # Map metadata flag
        GameData::MapMetadata.each do |map_data|
          @reception.push(map_data.id) if map_data.has_flag?(map)
        end
      else
        @reception.push(map)
      end
    end
  end

  def pbOffLimits?(map)
    return false if @contestMaps.include?(map)
    return false if @reception.include?(map)
    return true
  end

  def pbSetJudgingPoint(startMap, startX, startY, dir = 8)
    @start = [startMap, startX, startY, dir]
  end

  def pbJudge
    judgearray = []
    if @lastPokemon
      judgearray.push([-1, @lastPokemon.species, pbBugContestScore(@lastPokemon)])
    end
    maps_with_encounters = []
    @contestMaps.each do |map|
      enc_type = :BugContest
      enc_type = :Land if !$PokemonEncounters.map_has_encounter_type?(map, enc_type)
      if $PokemonEncounters.map_has_encounter_type?(map, enc_type)
        maps_with_encounters.push([map, enc_type])
      end
    end
    raise _INTL("No hay Concursos de Bicho/encuentros para ningún mapa de Concurso de Bichos.") if maps_with_encounters.empty?
    @contestants.each do |cont|
      enc_data = maps_with_encounters.sample
      enc = $PokemonEncounters.choose_wild_pokemon_for_map(enc_data[0], enc_data[1])
      raise _INTL("No hay encuentros en el mapa {1} por algún motivo, así que no se puede juzgar el concurso.", enc_data[0]) if !enc
      pokemon = Pokemon.new(enc[0], enc[1])
      pokemon.hp = rand(1...pokemon.totalhp)
      score = pbBugContestScore(pokemon)
      judgearray.push([cont, pokemon.species, score])
    end
    raise _INTL("Hay muy pocos participantes del concurso de bichos") if judgearray.length < 3
    judgearray.sort! { |a, b| b[2] <=> a[2] }   # sort by score in descending order
    @places.push(judgearray[0])
    @places.push(judgearray[1])
    @places.push(judgearray[2])
  end

  def pbGetPlaceInfo(place)
    cont = @places[place][0]
    if cont < 0
      $game_variables[1] = $player.name
    else
      $game_variables[1] = CONTESTANT_NAMES[cont]
    end
    $game_variables[2] = GameData::Species.get(@places[place][1]).name
    $game_variables[3] = @places[place][2]
  end

  def pbClearIfEnded
    clear if !@inProgress && (!@start || @start[0] != $game_map.map_id)
  end

  def pbStartJudging
    @decision = 1
    pbJudge
    if $scene.is_a?(Scene_Map)
      pbFadeOutIn do
        $game_temp.player_transferring  = true
        $game_temp.player_new_map_id    = @start[0]
        $game_temp.player_new_x         = @start[1]
        $game_temp.player_new_y         = @start[2]
        $game_temp.player_new_direction = @start[3]
        pbDismountBike
        $scene.transfer_player
        $game_map.need_refresh = true   # in case player moves to the same map
      end
    end
  end

  def pbIsContestant?(i)
    return @contestants.any? { |item| i == item }
  end

  def pbStart(ballcount)
    @ballcount = ballcount
    @inProgress = true
    @otherparty = []
    @lastPokemon = nil
    @lastContest = nil
    @timer_start = System.uptime
    @places = []
    chosenpkmn = $player.party[@chosenPokemon]
    $player.party.length.times do |i|
      @otherparty.push($player.party[i]) if i != @chosenPokemon
    end
    @contestants = []
    [5, CONTESTANT_NAMES.length].min.times do
      loop do
        value = rand(CONTESTANT_NAMES.length)
        next if @contestants.include?(value)
        @contestants.push(value)
        break
      end
    end
    $player.party = [chosenpkmn]
    @decision = 0
    @ended = false
    $stats.bug_contest_count += 1
  end

  def place
    3.times do |i|
      return i if @places[i][0] < 0
    end
    return 3
  end

  def pbEnd(interrupted = false)
    return if !@inProgress
    @otherparty.each { |pkmn| $player.party.push(pkmn) }
    if interrupted
      @ended = false
    else
      pbNicknameAndStore(@lastPokemon) if @lastPokemon
      @ended = true
    end
    $stats.bug_contest_wins += 1 if place == 0
    @ballcount = 0
    @inProgress = false
    @decision = 0
    @lastPokemon = nil
    @otherparty = []
    @contestMaps = []
    @reception = []
    @lastContest = pbGetTimeNow.to_i
    $game_map.need_refresh = true
  end
end

