class SameSpeciesClause
  def isValid?(team)
    species = []
    team.each do |pkmn|
      species.push(pkmn.species) if pkmn && !species.include?(pkmn.species)
    end
    return species.length == 1
  end

  def errorMessage
    return _INTL("Los Pokémon deben ser de la misma especie.")
  end
end

#===============================================================================
#
#===============================================================================
class SpeciesClause
  def isValid?(team)
    species = []
    team.each do |pkmn|
      next if !pkmn
      return false if species.include?(pkmn.species)
      species.push(pkmn.species)
    end
    return true
  end

  def errorMessage
    return _INTL("Los Pokémon no pueden ser de la misma especie.")
  end
end

