module TypesProperty
  def self.set(_settingname, oldsetting)
    ret = oldsetting.clone
    index = 0
    loop do
      cmds = []
      2.times { |i| cmds.push(_INTL("Tipo {1} : {2}", i, ret[i] || "-")) }
      index = pbMessage(_INTL("Elige los tipos de esta especie."), cmds, -1)
      break if index < 0
      new_type = pbChooseTypeList(ret[index])
      ret[index] = new_type if new_type
      ret.uniq!
      ret.compact!
    end
    return ret if ret != oldsetting.compact && pbConfirmMessage(_INTL("¿Aplicar cambios?"))
    return oldsetting
  end

  def self.defaultValue
    return [:NORMAL]
  end

  def self.format(value)
    types = value.compact
    types.each_with_index { |type, i| types[i] = GameData::Type.try_get(types[i])&.real_name || "-" }
    return types.join(",")
  end
end

