#===============================================================================
class IVsProperty
  def initialize(limit)
    @limit = limit
  end

  def set(settingname, oldsetting)
    oldsetting = {} if !oldsetting
    properties = []
    data = []
    stat_ids = []
    GameData::Stat.each_main do |s|
      oldsetting[s.pbs_order] = 0 if !oldsetting[s.pbs_order]
      properties[s.pbs_order] = [s.name, LimitProperty2.new(@limit),
                                 _INTL("Valores individuales para la estadística {1} del Pokémon (0-{2}).", s.name, @limit)]
      data[s.pbs_order] = oldsetting[s.id]
      stat_ids[s.pbs_order] = s.id
    end
    pbPropertyList(settingname, data, properties, false)
    ret = {}
    stat_ids.each_with_index { |s, i| ret[s] = data[i] || 0 }
    return ret
  end

  def defaultValue
    return nil
  end

  def format(value)
    return "-" if !value
    array = []
    GameData::Stat.each_main do |s|
      next if s.pbs_order < 0
      array[s.pbs_order] = value[s.id] || 0
    end
    return array.join(",")
  end
end

#===============================================================================
#
#===============================================================================
class EVsProperty
  def initialize(limit)
    @limit = limit
  end

  def set(settingname, oldsetting)
    oldsetting = {} if !oldsetting
    properties = []
    data = []
    stat_ids = []
    GameData::Stat.each_main do |s|
      oldsetting[s.pbs_order] = 0 if !oldsetting[s.pbs_order]
      properties[s.pbs_order] = [s.name, LimitProperty2.new(@limit),
                                 _INTL("Puntos de esfuerzo para la estadística {1} del Pokémon (0-{2}).", s.name, @limit)]
      data[s.pbs_order] = oldsetting[s.id]
      stat_ids[s.pbs_order] = s.id
    end
    loop do
      pbPropertyList(settingname, data, properties, false)
      evtotal = 0
      data.each { |value| evtotal += value if value }
      break if evtotal <= Pokemon::EV_LIMIT
      pbMessage(_INTL("Los PE (EVs) totales ({1}) son más que los permitidos ({2}). Por favor, redúcelos.", evtotal, Pokemon::EV_LIMIT))
    end
    ret = {}
    stat_ids.each_with_index { |s, i| ret[s] = data[i] || 0 }
    return ret
  end

  def defaultValue
    return nil
  end

  def format(value)
    return "-" if !value
    array = []
    GameData::Stat.each_main do |s|
      next if s.pbs_order < 0
      array[s.pbs_order] = value[s.id] || 0
    end
    return array.join(",")
  end
end

