def chooseMapPoint(map, rgnmap = false)
  viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
  viewport.z = 99999
  title = Window_UnformattedTextPokemon.newWithSize(
    _INTL("Haz click en un punto del mapa."), 0, Graphics.height - 64, Graphics.width, 64, viewport
  )
  title.z = 2
  if rgnmap
    sprite = RegionMapSprite.new(map, viewport)
  else
    sprite = MapSprite.new(map, viewport)
  end
  sprite.z = 2
  ret = nil
  loop do
    Graphics.update
    Input.update
    xy = sprite.getXY
    if xy
      ret = xy
      break
    end
    if Input.trigger?(Input::BACK)
      ret = nil
      break
    end
  end
  sprite.dispose
  title.dispose
  return ret
end

