==============================================================================
#===============================================================================
# Core lister script
#===============================================================================
def pbListWindow(cmds, width = Graphics.width / 2)
  list = Window_CommandPokemon.newWithSize(cmds, 0, 0, width, Graphics.height)
  list.index     = 0
  list.rowHeight = 24
  pbSetSmallFont(list.contents)
  list.refresh
  return list
end

def pbListScreen(title, lister)
  viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
  viewport.z = 99999
  list = pbListWindow([])
  list.viewport = viewport
  list.z        = 2
  title = Window_UnformattedTextPokemon.newWithSize(
    title, Graphics.width / 2, 0, Graphics.width / 2, 64, viewport
  )
  title.z = 2
  lister.setViewport(viewport)
  selectedmap = -1
  commands = lister.commands
  selindex = lister.startIndex

  full_original_list = lister.commands.clone

  if commands.length == 0
    value = lister.value(-1)
    lister.dispose
    title.dispose
    list.dispose
    viewport.dispose
    return value
  end
  list.commands = commands
  list.index    = selindex
  selectedmap = list_screen_handle_input(list, lister, selectedmap, full_original_list)
  value = lister.value(selectedmap)
  lister.dispose
  title.dispose
  list.dispose
  viewport.dispose
  Input.update
  return value
end

def list_screen_handle_input(list, lister, selectedmap, full_original_list, screen_block = false, &block)
  breaked = false
  loop do
    Graphics.update
    Input.update
    list.update
    lister.update if defined?(lister.update)
    if list.index != selectedmap
      lister.refresh(list.index)
      selectedmap = list.index
    end
    if Input.trigger?(Input::BACK)
      selectedmap = -1 if !screen_block
      breaked = true
      break
    elsif Input.trigger?(Input::ACTION) && screen_block
      yield(Input::ACTION, lister.value(selectedmap))
      list.commands = lister.commands
      list.index = list.commands.length if list.index == list.commands.length
      lister.refresh(list.index)
    elsif Input.trigger?(Input::USE)
      if screen_block
        yield(Input::USE, lister.value(selectedmap))
        list.commands = lister.commands
        list.index = list.commands.length if list.index == list.commands.length
        lister.refresh(list.index)
      else
        breaked = true
        break
      end
    end
    list_screen_handle_input_enhancements(list, lister, selectedmap, full_original_list, screen_block, &block)
  end
  return selectedmap if breaked
end

def pbListScreenBlock(title, lister, &block)
  viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
  viewport.z = 99999
  list = pbListWindow([], Graphics.width / 2)
  list.viewport = viewport
  list.z        = 2
  title = Window_UnformattedTextPokemon.newWithSize(
    title, Graphics.width / 2, 0, Graphics.width / 2, 64, viewport
  )
  title.z = 2
  lister.setViewport(viewport)
  selectedmap = -1
  commands = lister.commands
  selindex = lister.startIndex

  full_original_list = lister.commands.clone

  if commands.length == 0
    value = lister.value(-1)
    lister.dispose
    title.dispose
    list.dispose
    viewport.dispose
    return value
  end
  list.commands = commands
  list.index = selindex
  list_screen_handle_input(list, lister, selectedmap, full_original_list, true, &block)
  lister.dispose
  title.dispose
  list.dispose
  viewport.dispose
  Input.update
end

#===============================================================================
#
#===============================================================================
class GraphicsLister
  def initialize(folder, selection)
    @sprite = IconSprite.new(0, 0)
    @sprite.bitmap = nil
    @sprite.x      = Graphics.width * 3 / 4
    @sprite.y      = ((Graphics.height - 64) / 2) + 64
    @sprite.z      = 2
    @folder = folder
    @selection = selection
    @commands = []
    @index = 0
  end

  def dispose
    @sprite.bitmap&.dispose
    @sprite.dispose
  end

  def setViewport(viewport)
    @sprite.viewport = viewport
  end

  def startIndex
    return @index
  end

  def commands
    @commands.clear
    Dir.chdir(@folder) do
      Dir.glob("*.png") { |f| @commands.push(f) }
      Dir.glob("*.gif") { |f| @commands.push(f) }
#      Dir.glob("*.jpg") { |f| @commands.push(f) }
#      Dir.glob("*.jpeg") { |f| @commands.push(f) }
#      Dir.glob("*.bmp") { |f| @commands.push(f) }
    end
    @commands.sort!
    @commands.length.times do |i|
      @index = i if @commands[i] == @selection
    end
    pbMessage(_INTL("No hay archivos.")) if @commands.length == 0
    return @commands
  end

  def value(index)
    return (index < 0) ? "" : @commands[index]
  end

  def refresh(index)
    return if index < 0
    @sprite.setBitmap(@folder + @commands[index])
    sprite_width = @sprite.bitmap.width
    sprite_height = @sprite.bitmap.height
    @sprite.ox = sprite_width / 2
    @sprite.oy = sprite_height / 2
    scale_x = (Graphics.width / 2).to_f / sprite_width
    scale_y = (Graphics.height - 64).to_f / sprite_height
    if scale_x < 1.0 || scale_y < 1.0
      min_scale = [scale_x, scale_y].min
      @sprite.zoom_x = @sprite.zoom_y = min_scale
    else
      @sprite.zoom_x = @sprite.zoom_y = 1.0
    end
  end
end

#===============================================================================
#
#===============================================================================
class MusicFileLister
  def initialize(bgm, setting)
    @oldbgm = getPlayingBGM
    @commands = []
    @bgm = bgm
    @setting = setting
    @index = 0
  end

  def dispose
    pbPlayBGM(@oldbgm)
  end

  def setViewport(viewport); end

  def getPlayingBGM
    ($game_system) ? $game_system.getPlayingBGM : nil
  end

  def pbPlayBGM(bgm)
    (bgm) ? pbBGMPlay(bgm) : pbBGMStop
  end

  def startIndex
    return @index
  end

  def commands
    folder = (@bgm) ? "Audio/BGM/" : "Audio/ME/"
    @commands.clear
    Dir.chdir(folder) do
      Dir.glob("*.wav") { |f| @commands.push(f) }
      Dir.glob("*.ogg") { |f| @commands.push(f) }
      Dir.glob("*.mp3") { |f| @commands.push(f) }
      Dir.glob("*.midi") { |f| @commands.push(f) }
      Dir.glob("*.mid") { |f| @commands.push(f) }
      Dir.glob("*.wma") { |f| @commands.push(f) }
    end
    @commands.uniq!
    @commands.sort! { |a, b| a.downcase <=> b.downcase }
    @commands.length.times do |i|
      @index = i if @commands[i] == @setting
    end
    pbMessage(_INTL("No hay archivos.")) if @commands.length == 0
    return @commands
  end

  def value(index)
    return (index < 0) ? "" : @commands[index]
  end

  def refresh(index)
    return if index < 0
    if @bgm
      pbPlayBGM(@commands[index])
    else
      pbPlayBGM("../../Audio/ME/" + @commands[index])
    end
  end
end

