#===============================================================================
# Item editor
#===============================================================================
def pbItemEditor
  properties = GameData::Item.editor_properties
  pbListScreenBlock(_INTL("Objetos"), ItemLister.new(0, true)) do |button, item|
    if item
      case button
      when Input::ACTION
        if item.is_a?(Symbol) && pbConfirmMessageSerious("¿Borrar este objeto?")
          GameData::Item::DATA.delete(item)
          GameData::Item.save
          Compiler.write_items
          pbMessage(_INTL("El objeto se ha borrado."))
        end
      when Input::USE
        if item.is_a?(Symbol)
          itm = GameData::Item.get(item)
          data = []
          properties.each do |prop|
            val = itm.get_property_for_PBS(prop[0])
            val = prop[1].defaultValue if val.nil? && prop[1].respond_to?(:defaultValue)
            data.push(val)
          end
          if pbPropertyList(itm.id.to_s, data, properties, true)
            # Construct item hash
            schema = GameData::Item.schema
            item_hash = {}
            properties.each_with_index do |prop, i|
              case prop[0]
              when "ID"
                item_hash[schema["SectionName"][0]] = data[i]
              else
                item_hash[schema[prop[0]][0]] = data[i]
              end
            end
            item_hash[:pbs_file_suffix] = itm.pbs_file_suffix
            # Add item's data to records
            GameData::Item.register(item_hash)
            GameData::Item.save
            Compiler.write_items
          end
        else   # Add a new item
          pbItemEditorNew(nil)
        end
      end
    end
  end
end

def pbItemEditorNew(default_name)
  # Choose a name
  name = pbMessageFreeText(_INTL("Por favor, introduce el nombre del objeto."),
                           (default_name) ? default_name.gsub(/_+/, " ") : "", false, 30)
  if nil_or_empty?(name)
    return if !default_name
    name = default_name
  end
  # Generate an ID based on the item name
  id = name.gsub(/é/, "e")
  id = id.gsub(/[^A-Za-z0-9_]/, "")
  id = id.upcase
  if id.length == 0
    id = sprintf("ITEM_%03d", GameData::Item.count)
  elsif !id[0, 1][/[A-Z]/]
    id = "ITEM_" + id
  end
  if GameData::Item.exists?(id)
    (1..100).each do |i|
      trial_id = sprintf("%s_%d", id, i)
      next if GameData::Item.exists?(trial_id)
      id = trial_id
      break
    end
  end
  if GameData::Item.exists?(id)
    pbMessage(_INTL("Error al crear el objeto. Elige un nombre diferente."))
    return
  end
  # Choose a pocket
  pocket = PocketProperty.set("", 0)
  return if pocket == 0
  # Choose a price
  price = LimitProperty.new(999_999).set(_INTL("Precio de compra"), -1)
  return if price == -1
  # Choose a description
  description = StringProperty.set(_INTL("Descripción"), "")
  # Construct item hash
  item_hash = {
    :id          => id.to_sym,
    :name        => name,
    :name_plural => name + "s",
    :pocket      => pocket,
    :price       => price,
    :description => description
  }
  # Add item's data to records
  GameData::Item.register(item_hash)
  GameData::Item.save
  Compiler.write_items
  pbMessage(_INTL("El objeto {1} se ha creado (ID: {2}).", name, id.to_s))
  pbMessage(_INTL("Pon el gráfico del objeto ({1}.png) en la carpeta Graphics/Items, o será invisible.", id.to_s))
end

#===============================================================================
# Pokémon species editor
#===============================================================================
def pbPokemonEditor
  properties = GameData::Species.editor_properties
  pbListScreenBlock(_INTL("Especies de Pokémon"), SpeciesLister.new(0, false)) do |button, species|
    if species
      case button
      when Input::ACTION
        if species.is_a?(Symbol) && pbConfirmMessageSerious("¿Eliminar esta especie?")
          GameData::Species::DATA.delete(species)
          GameData::Species.save
          Compiler.write_pokemon
          pbMessage(_INTL("La especie se ha eliminado."))
        end
      when Input::USE
        if species.is_a?(Symbol)
          spec = GameData::Species.get(species)
          data = []
          properties.each do |prop|
            val = spec.get_property_for_PBS(prop[0])
            val = prop[1].defaultValue if val.nil? && prop[1].respond_to?(:defaultValue)
            val = (val * 10).round if ["Height", "Weight"].include?(prop[0])
            data.push(val)
          end
          # Edit the properties
          if pbPropertyList(spec.id.to_s, data, properties, true)
            # Construct species hash
            schema = GameData::Species.schema
            species_hash = {}
            properties.each_with_index do |prop, i|
              data[i] = data[i].to_f / 10 if ["Height", "Weight"].include?(prop[0])
              case prop[0]
              when "ID"
                species_hash[schema["SectionName"][0]] = data[i]
              else
                species_hash[schema[prop[0]][0]] = data[i]
              end
            end
            species_hash[:pbs_file_suffix] = spec.pbs_file_suffix
            # Sanitise data
            Compiler.validate_compiled_pokemon(species_hash)
            species_hash[:evolutions].each do |evo|
              param_type = GameData::Evolution.get(evo[1]).parameter
              if param_type.nil?
                evo[2] = nil
              elsif param_type == Integer
                evo[2] = Compiler.cast_csv_value(evo[2], "u")
              elsif param_type != String
                evo[2] = Compiler.cast_csv_value(evo[2], "e", param_type)
              end
            end
            # Add species' data to records
            GameData::Species.register(species_hash)
            GameData::Species.save
            Compiler.write_pokemon
            pbMessage(_INTL("Datos guardados."))
          end
        else
          pbMessage(_INTL("No se puede añadir la nueva especie."))
        end
      end
    end
  end
end

#===============================================================================
# Regional Dexes editor
#===============================================================================
def pbRegionalDexEditor(dex)
  viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
  viewport.z = 99999
  cmd_window = pbListWindow([])
  info = Window_AdvancedTextPokemon.newWithSize(
    _INTL("Z+Arriba/Abajo: Reorganizar entradas\nZ+Derecha: Insertar nueva entrada\nZ+Izqda.: Eliminar entrada\nD: Vaciar entrada"),
    Graphics.width / 2, 64, Graphics.width / 2, Graphics.height - 64, viewport
  )
  info.z = 2
  dex.compact!
  ret = dex.clone
  commands = []
  refresh_list = true
  cmd = [0, 0]   # [action, index in list]
  loop do
    # Populate commands
    if refresh_list
      loop do
        break if dex.length == 0 || dex[-1]
        dex.slice!(-1)
      end
      commands = []
      dex.each_with_index do |species, i|
        text = (species) ? GameData::Species.get(species).real_name : "----------"
        commands.push(sprintf("%03d: %s", i + 1, text))
      end
      commands.push(sprintf("%03d: ----------", commands.length + 1))
      cmd[1] = [cmd[1], commands.length - 1].min
      refresh_list = false
    end
    # Choose to do something
    cmd = pbCommands3(cmd_window, commands, -1, cmd[1], true)
    case cmd[0]
    when 1   # Swap entry up
      if cmd[1] < dex.length - 1
        dex[cmd[1] + 1], dex[cmd[1]] = dex[cmd[1]], dex[cmd[1] + 1]
        refresh_list = true
      end
    when 2   # Swap entry down
      if cmd[1] > 0
        dex[cmd[1] - 1], dex[cmd[1]] = dex[cmd[1]], dex[cmd[1] - 1]
        refresh_list = true
      end
    when 3   # Delete spot
      if cmd[1] < dex.length
        dex.delete_at(cmd[1])
        refresh_list = true
      end
    when 4   # Insert spot
      if cmd[1] < dex.length
        dex.insert(cmd[1], nil)
        refresh_list = true
      end
    when 5   # Clear spot
      if dex[cmd[1]]
        dex[cmd[1]] = nil
        refresh_list = true
      end
    when 0
      if cmd[1] >= 0   # Edit entry
        case pbMessage("\\ts[]" + _INTL("¿Qué hacer con esta entrada?"),
                       [_INTL("Cambiar especie"), _INTL("Vaciar"),
                        _INTL("Insertar entrada"), _INTL("Eliminar entrada"),
                        _INTL("Cancelar")], 5)
        when 0   # Change species
          species = pbChooseSpeciesList(dex[cmd[1]])
          if species
            dex[cmd[1]] = species
            dex.each_with_index { |s, i| dex[i] = nil if i != cmd[1] && s == species }
            refresh_list = true
          end
        when 1   # Clear spot
          if dex[cmd[1]]
            dex[cmd[1]] = nil
            refresh_list = true
          end
        when 2   # Insert spot
          if cmd[1] < dex.length
            dex.insert(cmd[1], nil)
            refresh_list = true
          end
        when 3   # Delete spot
          if cmd[1] < dex.length
            dex.delete_at(cmd[1])
            refresh_list = true
          end
        end
      else   # Cancel
        case pbMessage(_INTL("¿Guardar cambios?"),
                       [_INTL("Sí"), _INTL("No"), _INTL("Cancelar")], 3)
        when 0   # Save all changes to Dex
          dex.slice!(-1) until dex[-1]
          ret = dex
          break
        when 1   # Just quit
          break
        end
      end
    end
  end
  info.dispose
  cmd_window.dispose
  viewport.dispose
  ret.compact!
  return ret
end

REGIONAL_DEX_EDITOR_HEIGHT = 64
def pbRegionalDexEditorMain
  viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
  viewport.z = 99999
  cmd_window = pbListWindow([])
  cmd_window.viewport = viewport
  cmd_window.z        = 2
  title = Window_UnformattedTextPokemon.newWithSize(
    _INTL("Editor de Dexes Regionales"), Graphics.width / 2, 0, Graphics.width / 2, REGIONAL_DEX_EDITOR_HEIGHT, viewport
  )
  title.z = 2
  info = Window_AdvancedTextPokemon.newWithSize(
    _INTL("Z+Arriba/Abajo: Reorganizar Dexes"), Graphics.width / 2, REGIONAL_DEX_EDITOR_HEIGHT,
    Graphics.width / 2, Graphics.height - REGIONAL_DEX_EDITOR_HEIGHT, viewport
  )
  info.z = 2
  dex_lists = []
  pbLoadRegionalDexes.each_with_index { |d, index| dex_lists[index] = d.clone }
  commands = []
  refresh_list = true
  cmd = [0, 0]   # [action, index in list]
  loop do
    # Populate commands
    if refresh_list
      commands = [_INTL("[AÑADIR POKÉDEX]")]
      dex_lists.each_with_index do |list, i|
        commands.push(_INTL("Dex {1} (tamaño {2})", i + 1, list.length))
      end
      refresh_list = false
    end
    # Choose to do something
    cmd = pbCommands3(cmd_window, commands, -1, cmd[1], true)
    case cmd[0]
    when 1   # Swap Dex up
      if cmd[1] > 0 && cmd[1] < commands.length - 1
        dex_lists[cmd[1] - 1], dex_lists[cmd[1]] = dex_lists[cmd[1]], dex_lists[cmd[1] - 1]
        refresh_list = true
      end
    when 2   # Swap Dex down
      if cmd[1] > 1
        dex_lists[cmd[1] - 2], dex_lists[cmd[1] - 1] = dex_lists[cmd[1] - 1], dex_lists[cmd[1] - 2]
        refresh_list = true
      end
    when 0   # Clicked on a command/Dex
      if cmd[1] == 0   # Add new Dex
        case pbMessage(_INTL("¿Completar esta nueva Dex?"),
                       [_INTL("Dejar en blanco"), _INTL("Dex Nacional"),
                        _INTL("Familias agrupadas en Dex Nacional"), _INTL("Cancelar")], 4)
        when 0   # Leave blank
          dex_lists.push([])
          refresh_list = true
        when 1   # Fill with National Dex
          new_dex = []
          GameData::Species.each_species { |s| new_dex.push(s.species) }
          dex_lists.push(new_dex)
          refresh_list = true
        when 2   # Fill with National Dex (grouped families)
          new_dex = []
          seen = []
          GameData::Species.each_species do |s|
            next if seen.include?(s.species)
            family = s.get_family_species
            new_dex.concat(family)
            seen.concat(family)
          end
          dex_lists.push(new_dex)
          refresh_list = true
        end
      elsif cmd[1] > 0   # Edit a Dex
        case pbMessage("\\ts[]" + _INTL("¿Qué hacer con esta Dex?"),
                       [_INTL("Editar"), _INTL("Copiar"), _INTL("Eliminar"), _INTL("Cancelar")], 4)
        when 0   # Edit
          dex_lists[cmd[1] - 1] = pbRegionalDexEditor(dex_lists[cmd[1] - 1])
          refresh_list = true
        when 1   # Copy
          dex_lists[dex_lists.length] = dex_lists[cmd[1] - 1].clone
          cmd[1] = dex_lists.length
          refresh_list = true
        when 2   # Delete
          dex_lists.delete_at(cmd[1] - 1)
          cmd[1] = [cmd[1], dex_lists.length].min
          refresh_list = true
        end
      else   # Cancel
        case pbMessage(_INTL("¿Guardar cambios?"),
                       [_INTL("Sí"), _INTL("No"), _INTL("Cancelar")], 3)
        when 0   # Save all changes to Dexes
          save_data(dex_lists, "Data/regional_dexes.dat")
          $game_temp.regional_dexes_data = nil
          Compiler.write_regional_dexes
          pbMessage(_INTL("Datos guardados."))
          break
        when 1   # Just quit
          break
        end
      end
    end
  end
  title.dispose
  info.dispose
  cmd_window.dispose
  viewport.dispose
end

def pbAppendEvoToFamilyArray(species, array, seenarray)
  return if seenarray[species]
  array.push(species)
  seenarray[species] = true
  evos = GameData::Species.get(species).get_evolutions
  if evos.length > 0
    subarray = []
    evos.each do |i|
      pbAppendEvoToFamilyArray(i[0], subarray, seenarray)
    end
    array.push(subarray) if subarray.length > 0
  end
end

def pbGetEvoFamilies
  seen = []
  ret = []
  GameData::Species.each_species do |sp|
    species = sp.get_baby_species
    next if seen[species]
    subret = []
    pbAppendEvoToFamilyArray(species, subret, seen)
    ret.push(subret.flatten) if subret.length > 0
  end
  return ret
end

def pbEvoFamiliesToStrings
  ret = []
  families = pbGetEvoFamilies
  families.length.times do |fam|
    string = ""
    families[fam].length.times do |p|
      if p >= 3
        string += " + #{families[fam].length - 3} más"
        break
      end
      string += "/" if p > 0
      string += GameData::Species.get(families[fam][p]).name
    end
    ret[fam] = string
  end
  return ret
end

#===============================================================================
# Battle animations rearranger
#===============================================================================
ANIMATIONS_ORGANISER_HEIGHT = 64
def pbAnimationsOrganiser
  list = pbLoadBattleAnimations
  if !list || !list[0]
    pbMessage(_INTL("No existen animaciones"))
    return
  end
  viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
  viewport.z = 99999
  cmdwin = pbListWindow([])
  cmdwin.viewport = viewport
  cmdwin.z        = 2
  title = Window_UnformattedTextPokemon.newWithSize(
    _INTL("Organizador de Animaciones"), Graphics.width / 2, 0, Graphics.width / 2, ANIMATIONS_ORGANISER_HEIGHT, viewport
  )
  title.z = 2
  info = Window_AdvancedTextPokemon.newWithSize(
    _INTL("Z+Arriba/Abajo: Intercambiar\nZ+Izda: Eliminar\nZ+Derecha: Insertar"),
    Graphics.width / 2, ANIMATIONS_ORGANISER_HEIGHT, Graphics.width / 2, Graphics.height - ANIMATIONS_ORGANISER_HEIGHT, viewport
  )
  info.z = 2
  commands = []
  refreshlist = true
  cmd = [0, 0]
  loop do
    if refreshlist
      commands = []
      list.length.times do |i|
        commands.push(sprintf("%d: %s", i, (list[i]) ? list[i].name : "???"))
      end
    end
    refreshlist = false
    cmd = pbCommands3(cmdwin, commands, -1, cmd[1], true)
    case cmd[0]
    when 1   # Swap animation up
      if cmd[1] >= 0 && cmd[1] < commands.length - 1
        list[cmd[1] + 1], list[cmd[1]] = list[cmd[1]], list[cmd[1] + 1]
        refreshlist = true
      end
    when 2   # Swap animation down
      if cmd[1] > 0
        list[cmd[1] - 1], list[cmd[1]] = list[cmd[1]], list[cmd[1] - 1]
        refreshlist = true
      end
    when 3   # Delete spot
      list.delete_at(cmd[1])
      cmd[1] = [cmd[1], list.length - 1].min
      refreshlist = true
      pbWait(0.2)
    when 4   # Insert spot
      list.insert(cmd[1], PBAnimation.new)
      refreshlist = true
      pbWait(0.2)
    when 0
      cmd2 = pbMessage(_INTL("¿Guardar cambios?"),
                       [_INTL("Sí"), _INTL("No"), _INTL("Cancelar")], 3)
      if [0, 1].include?(cmd2)
        if cmd2 == 0
          # Save animations here
          save_data(list, "Data/PkmnAnimations.rxdata")
          $game_temp.battle_animations_data = nil
          pbMessage(_INTL("Datos guardados."))
        end
        break
      end
    end
  end
  title.dispose
  info.dispose
  cmdwin.dispose
  viewport.dispose
end


==============================================================================
# Script: EditorScreens_TerrainTags
==============================================================================
#===============================================================================
# Edits the terrain tags of tiles in tilesets.
#===============================================================================
class PokemonTilesetScene
  TILE_SIZE            = 32   # in pixels
  TILES_PER_ROW        = 8
  TILESET_WIDTH        = TILES_PER_ROW * TILE_SIZE
  TILES_PER_AUTOTILE   = 48
  TILESET_START_ID     = TILES_PER_ROW * TILES_PER_AUTOTILE
  TILE_BACKGROUND      = Color.magenta
  CURSOR_COLOR         = Color.new(255, 0, 0)   # Red
  CURSOR_OUTLINE_COLOR = Color.white
  TEXT_COLOR           = Color.white
  TEXT_SHADOW_COLOR    = Color.black

  def initialize
    @tilesets_data = load_data("Data/Tilesets.rxdata")
    @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = 99999
    @sprites = {}
    @sprites["title"] = Window_UnformattedTextPokemon.newWithSize(
      _INTL("Editor de Tileset\nA/S: DESPLAZAR\nZ: MENU"),
      TILESET_WIDTH, 0, Graphics.width - TILESET_WIDTH, 128, @viewport
    )
    @sprites["background"] = BitmapSprite.new(Graphics.width, Graphics.height, @viewport)
    @sprites["tileset"] = BitmapSprite.new(TILESET_WIDTH, Graphics.height, @viewport)
    @sprites["tileset"].z = 10
    @sprites["overlay"] = BitmapSprite.new(Graphics.width, Graphics.height, @viewport)
    @sprites["overlay"].z = 20
    pbSetSystemFont(@sprites["overlay"].bitmap)
    @visible_height = @sprites["tileset"].bitmap.height / TILE_SIZE
    load_tileset(1)
  end

  def open_screen
    pbFadeInAndShow(@sprites)
  end

  def close_screen
    pbFadeOutAndHide(@sprites)
    pbDisposeSpriteHash(@sprites)
    @viewport.dispose
    @tilehelper.dispose
    if $game_map && $map_factory
      $map_factory.setup($game_map.map_id)
      $game_player.center($game_player.x, $game_player.y)
      if $scene.is_a?(Scene_Map)
        $scene.dispose
        # Reset map objects in each follower event
        $game_temp.followers = Game_FollowerFactory.new
        $scene.createSpritesets
      end
    end
  end

  def load_tileset(id)
    @tileset = @tilesets_data[id]
    @tilehelper&.dispose
    @tilehelper = TileDrawingHelper.fromTileset(@tileset)
    @x = 0
    @y = 0
    @top_y = 0
    @height = ((@tileset.terrain_tags.xsize - TILESET_START_ID) / TILES_PER_ROW) + 1
    draw_tiles
    draw_overlay
  end

  def choose_tileset
    commands = []
    (1...@tilesets_data.length).each do |i|
      commands.push(sprintf("%03d %s", i, @tilesets_data[i].name))
    end
    ret = pbShowCommands(nil, commands, -1)
    load_tileset(ret + 1) if ret >= 0
  end

  def draw_tiles
    @sprites["background"].bitmap.clear
    @sprites["tileset"].bitmap.clear
    @visible_height.times do |yy|
      autotile_row = (@top_y == 0 && yy == 0)   # Autotiles
      id_y_offset = (autotile_row) ? 0 : TILESET_START_ID + ((@top_y + yy - 1) * TILES_PER_ROW)
      break if @top_y + yy >= @height
      TILES_PER_ROW.times do |xx|
        @sprites["background"].bitmap.fill_rect(xx * TILE_SIZE, yy * TILE_SIZE, TILE_SIZE, TILE_SIZE, TILE_BACKGROUND)
        id_x_offset = (autotile_row) ? xx * TILES_PER_AUTOTILE : xx
        @tilehelper.bltTile(@sprites["tileset"].bitmap, xx * TILE_SIZE, yy * TILE_SIZE,
                            id_y_offset + id_x_offset)
      end
    end
  end

  def draw_overlay
    @sprites["overlay"].bitmap.clear
    # Draw all text over tiles (terrain tag numbers)
    textpos = []
    @visible_height.times do |yy|
      TILES_PER_ROW.times do |xx|
        tile_id = tile_ID_from_coordinates(xx, @top_y + yy)
        terr = @tileset.terrain_tags[tile_id]
        next if terr == 0
        textpos.push([terr.to_s, (xx * TILE_SIZE) + (TILE_SIZE / 2), (yy * TILE_SIZE) + 6,
                      :center, TEXT_COLOR, TEXT_SHADOW_COLOR, :outline])
      end
    end
    pbDrawTextPositions(@sprites["overlay"].bitmap, textpos)
    # Draw cursor
    draw_cursor
    # Draw information about selected tile on right side
    draw_tile_details
  end

  def draw_cursor
    cursor_x = @x * TILE_SIZE
    cursor_y = (@y - @top_y) * TILE_SIZE
    cursor_width = TILE_SIZE
    cursor_height = TILE_SIZE
    bitmap = @sprites["overlay"].bitmap
    bitmap.fill_rect(cursor_x - 2,                cursor_y - 2,                 cursor_width + 4, 8,  CURSOR_OUTLINE_COLOR)
    bitmap.fill_rect(cursor_x - 2,                cursor_y - 2,                 8, cursor_height + 4, CURSOR_OUTLINE_COLOR)
    bitmap.fill_rect(cursor_x - 2,                cursor_y + cursor_height - 6, cursor_width + 4, 8,  CURSOR_OUTLINE_COLOR)
    bitmap.fill_rect(cursor_x + cursor_width - 6, cursor_y - 2,                 8, cursor_height + 4, CURSOR_OUTLINE_COLOR)
    bitmap.fill_rect(cursor_x,                    cursor_y,                     cursor_width, 4,      CURSOR_COLOR)
    bitmap.fill_rect(cursor_x,                    cursor_y,                     4, cursor_height,     CURSOR_COLOR)
    bitmap.fill_rect(cursor_x,                    cursor_y + cursor_height - 4, cursor_width, 4,      CURSOR_COLOR)
    bitmap.fill_rect(cursor_x + cursor_width - 4, cursor_y,                     4, cursor_height,     CURSOR_COLOR)
  end

  def draw_tile_details
    overlay = @sprites["overlay"].bitmap
    tile_size = 4   # Size multiplier
    tile_x = (Graphics.width * 3 / 4) - (TILE_SIZE * tile_size / 2)
    tile_y = (Graphics.height / 2) - (TILE_SIZE * tile_size / 2)
    tile_id = tile_ID_from_coordinates(@x, @y) || 0
    # Draw tile (at 400% size)
    @sprites["background"].bitmap.fill_rect(tile_x, tile_y, TILE_SIZE * tile_size, TILE_SIZE * tile_size, TILE_BACKGROUND)
    @tilehelper.bltSmallTile(overlay, tile_x, tile_y, TILE_SIZE * tile_size, TILE_SIZE * tile_size, tile_id)
    # Draw box around tile image
    overlay.fill_rect(tile_x - 1,                       tile_y - 1,                       (TILE_SIZE * tile_size) + 2, 1, Color.white)
    overlay.fill_rect(tile_x - 1,                       tile_y - 1,                       1, (TILE_SIZE * tile_size) + 2, Color.white)
    overlay.fill_rect(tile_x - 1,                       tile_y + (TILE_SIZE * tile_size), (TILE_SIZE * tile_size) + 2, 1, Color.white)
    overlay.fill_rect(tile_x + (TILE_SIZE * tile_size), tile_y - 1,                       1, (TILE_SIZE * tile_size) + 2, Color.white)
    # Write terrain tag info about selected tile
    terrain_tag = @tileset.terrain_tags[tile_id] || 0
    if GameData::TerrainTag.exists?(terrain_tag)
      terrain_tag_name = sprintf("%d: %s", terrain_tag, GameData::TerrainTag.get(terrain_tag).real_name)
    else
      terrain_tag_name = terrain_tag.to_s
    end
    textpos = [
      [_INTL("Terrain Tag:"), Graphics.width * 3 / 4, tile_y + (TILE_SIZE * tile_size) + 22,
       :center, Color.new(248, 248, 248), Color.new(40, 40, 40)],
      [terrain_tag_name, Graphics.width * 3 / 4, tile_y + (TILE_SIZE * tile_size) + 54,
       :center, Color.new(248, 248, 248), Color.new(40, 40, 40)]
    ]
    # Draw all text
    pbDrawTextPositions(overlay, textpos)
  end

  def tile_ID_from_coordinates(x, y)
    return x * TILES_PER_AUTOTILE if y == 0   # Autotile
    return TILESET_START_ID + ((y - 1) * TILES_PER_ROW) + x
  end

  def set_terrain_tag_for_tile_ID(i, value)
    if i < TILESET_START_ID
      TILES_PER_AUTOTILE.times { |j| @tileset.terrain_tags[i + j] = value }
    else
      @tileset.terrain_tags[i] = value
    end
  end

  def update_cursor_position(x_offset, y_offset)
    old_x = @x
    old_y = @y
    old_top_y = @top_y
    if x_offset != 0
      @x += x_offset
      @x = @x.clamp(0, TILES_PER_ROW - 1)
    end
    if y_offset != 0
      @y += y_offset
      @y = @y.clamp(0, @height - 1)
      @top_y = @y if @y < @top_y
      @top_y = @y - @visible_height + 1 if @y >= @top_y + @visible_height
      @top_y = 0 if @top_y < 0
    end
    draw_tiles if @top_y != old_top_y
    draw_overlay if @x != old_x || @y != old_y
  end

  def pbStartScene
    open_screen
    loop do
      Graphics.update
      Input.update
      if Input.repeat?(Input::UP)
        update_cursor_position(0, -1)
      elsif Input.repeat?(Input::DOWN)
        update_cursor_position(0, 1)
      elsif Input.repeat?(Input::LEFT)
        update_cursor_position(-1, 0)
      elsif Input.repeat?(Input::RIGHT)
        update_cursor_position(1, 0)
      elsif Input.repeat?(Input::JUMPUP)
        update_cursor_position(0, -@visible_height / 2)
      elsif Input.repeat?(Input::JUMPDOWN)
        update_cursor_position(0, @visible_height / 2)
      elsif Input.trigger?(Input::ACTION)
        commands = [
          _INTL("Ir al final"),
          _INTL("Ir al principio"),
          _INTL("Cambiar tileset"),
          _INTL("Cancelar")
        ]
        case pbShowCommands(nil, commands, -1)
        when 0
          update_cursor_position(0, 99_999)
        when 1
          update_cursor_position(0, -99_999)
        when 2
          choose_tileset
        end
      elsif Input.trigger?(Input::BACK)
        if pbConfirmMessage(_INTL("¿Guardar cambios?"))
          save_data(@tilesets_data, "Data/Tilesets.rxdata")
          $data_tilesets = @tilesets_data
          pbMessage(_INTL("Para que los cambios se guarden, cierra y abre RPG Maker XP. No le des a guardar en el RPG Maker antes de cerrarlo o se perderán los cambios de tiles que acabas de hacer."))
        end
        break if pbConfirmMessage(_INTL("¿Salir del editor?"))
      elsif Input.trigger?(Input::USE)
        selected = tile_ID_from_coordinates(@x, @y)
        old_tag = @tileset.terrain_tags[selected]
        cmds = []
        ids = []
        old_idx = 0
        GameData::TerrainTag.each do |tag|
          old_idx = cmds.length if tag.id_number == old_tag
          cmds.push("#{tag.id_number}: #{tag.real_name}")
          ids.push(tag.id_number)
        end
        val = pbMessage("\\l[1]\\ts[]" + _INTL("Elige el tag del terreno."), cmds, -1, nil, old_idx)
        if val >= 0 && val != old_tag
          set_terrain_tag_for_tile_ID(selected, ids[val])
          draw_overlay
        end
      end
    end
    close_screen
  end
end

#===============================================================================
#
#===============================================================================
def pbTilesetScreen
  pbFadeOutIn do
    Graphics.resize_screen(Settings::SCREEN_WIDTH, Settings::SCREEN_HEIGHT * 2)
    pbSetResizeFactor(1)
    scene = PokemonTilesetScene.new
    scene.pbStartScene
    Graphics.resize_screen(Settings::SCREEN_WIDTH, Settings::SCREEN_HEIGHT)
    pbSetResizeFactor($PokemonSystem.screensize)
  end
end


