      @checkbox.x = self.x
      @checkbox.y = self.y
      @checkbox.width = checkboxwidth
      @checkbox.height = self.height
      @checkbox.bitmap = self.bitmap
      @checkbox.parent = self.parent
      @slider.x = self.x + checkboxwidth + 4
