  #=============================================================================
  #
  #=============================================================================
  class ControlWindow < SpriteWindow_Base
    attr_reader :controls

    def initialize(x, y, width, height)
      super(x, y, width, height)
      self.contents = Bitmap.new(width - 32, height - 32)
      pbSetNarrowFont(self.contents)
      @controls = []
    end

    def dispose
      self.contents.dispose
      super
    end

    def refresh
      @controls.each { |ctrl| ctrl.refresh }
    end

    def repaint
      @controls.each { |ctrl| ctrl.repaint }
    end

    def invalidate
      @controls.each { |ctrl| ctrl.invalidate }
    end

    def hittest?(i)
      mousepos = Mouse.getMousePos
      return false if !mousepos
      return false if i < 0 || i >= @controls.length
      rc = Rect.new(@controls[i].parentX, @controls[i].parentY,
                    @controls[i].width, @controls[i].height)
      return rc.contains?(mousepos[0], mousepos[1])
    end

    def addControl(control)
      i = @controls.length
      @controls[i] = control
      @controls[i].x = 0
      @controls[i].y = i * 32
      @controls[i].width = self.contents.width
      @controls[i].height = 32
      @controls[i].parent = self
      @controls[i].bitmap = self.contents
      @controls[i].invalidate
      refresh
      return i
    end

    def addLabel(label)
      return addControl(Label.new(label))
    end

    def addButton(label)
      return addControl(Button.new(label))
    end

    def addSlider(label, minvalue, maxvalue, curvalue)
      return addControl(Slider.new(label, minvalue, maxvalue, curvalue))
    end

    def addOptionalSlider(label, minvalue, maxvalue, curvalue)
      return addControl(OptionalSlider.new(label, minvalue, maxvalue, curvalue))
    end

    def addTextSlider(label, options, curvalue)
      return addControl(TextSlider.new(label, options, curvalue))
    end

    def addOptionalTextSlider(label, options, curvalue)
      return addControl(OptionalTextSlider.new(label, options, curvalue))
    end

    def addCheckbox(label)
      return addControl(Checkbox.new(label))
    end

    def addSpace
      return addControl(UIControl.new(""))
    end

    def update
      super
      @controls.each { |ctrl| ctrl.update }
      repaint
    end

    def changed?(i)
      return false if i < 0
      return @controls[i].changed
    end

    def value(i)
      return false if i < 0
      return @controls[i].curvalue
    end
  end
end


==============================================================================
# Script: AnimEditor_Interpolation
==============================================================================
module BattleAnimationEditor
  module_function

  #=============================================================================
  # Paths and interpolation
  #=============================================================================
  class ControlPointSprite < Sprite
    attr_accessor :dragging

    def initialize(red, viewport = nil)
      super(viewport)
      self.bitmap = Bitmap.new(6, 6)
      self.bitmap.fill_rect(0, 0, 6, 1, Color.black)
      self.bitmap.fill_rect(0, 0, 1, 6, Color.black)
      self.bitmap.fill_rect(0, 5, 6, 1, Color.black)
      self.bitmap.fill_rect(5, 0, 1, 6, Color.black)
      color = (red) ? Color.new(255, 0, 0) : Color.black
      self.bitmap.fill_rect(2, 2, 2, 2, color)
      self.x = -6
      self.y = -6
      self.visible = false
      @dragging = false
    end

    def mouseover
      if Input.time?(Input::MOUSELEFT) == 0 || !@dragging
        @dragging = false
        return
      end
      mouse = Mouse.getMousePos(true)
      return if !mouse
      self.x = [[mouse[0], 0].max, 512].min
      self.y = [[mouse[1], 0].max, 384].min
    end

    def hittest?
      return true if !self.visible
      mouse = Mouse.getMousePos(true)
      return false if !mouse
      return mouse[0] >= self.x && mouse[0] < self.x + 6 &&
             mouse[1] >= self.y && mouse[1] < self.y + 6
    end

    def inspect
      return "[#{self.x},#{self.y}]"
    end

    def dispose
      self.bitmap.dispose
      super
    end
  end

  #=============================================================================
  #
  #=============================================================================
  class PointSprite < Sprite
    def initialize(x, y, viewport = nil)
      super(viewport)
      self.bitmap = Bitmap.new(2, 2)
      self.bitmap.fill_rect(0, 0, 2, 2, Color.black)
      self.x = x
      self.y = y
    end

    def dispose
      self.bitmap.dispose
      super
    end
  end

  #=============================================================================
  #
  #=============================================================================
  class PointPath
    include Enumerable

    def initialize
      @points = []
      @distances = []
      @totaldist = 0
    end

    def [](x)
      return @points[x].clone
    end

    def each
      @points.each { |o| yield o.clone }
    end

    def size
      return @points.size
    end

    def length
      return @points.length
    end

    def totalDistance
      return @totaldist
    end

    def inspect
      p = []
      @points.each do |point|
        p.push([point[0].to_i, point[1].to_i])
      end
      return p.inspect
    end

    def isEndPoint?(x, y)
      return false if @points.length == 0
      index = @points.length - 1
      return @points[index][0] == x &&
             @points[index][1] == y
    end

    def addPoint(x, y)
      @points.push([x, y])
      if @points.length > 1
        len = @points.length
        dx = @points[len - 2][0] - @points[len - 1][0]
        dy = @points[len - 2][1] - @points[len - 1][1]
        dist = Math.sqrt((dx * dx) + (dy * dy))
        @distances.push(dist)
        @totaldist += dist
      end
    end

    def clear
      @points.clear
      @distances.clear
      @totaldist = 0
    end

    def smoothPointPath(frames, roundValues = false)
      raise ArgumentError.new("frames fuera de rango: #{frames}") if frames < 0
      ret = PointPath.new
      return ret if @points.length == 0
      step = 1.0 / frames
      t = 0.0
      (frames + 2).times do
        point = pointOnPath(t)
        if roundValues
          ret.addPoint(point[0].round, point[1].round)
        else
          ret.addPoint(point[0], point[1])
        end
        t += step
        t = [1.0, t].min
      end
      return ret
    end

    def pointOnPath(t)
      if t < 0 || t > 1
        raise ArgumentError.new("t fuera de rango para pointOnPath: #{t}")
      end
      return nil if @points.length == 0
      ret = @points[@points.length - 1].clone
      return ret if @points.length == 1
      curdist = 0
      distForT = @totaldist * t
      i = 0
      @distances.each do |dist|
        curdist += dist
        if dist > 0.0 && curdist >= distForT
          distT = 1.0 - ((curdist - distForT) / dist)
          dx = @points[i + 1][0] - @points[i][0]
          dy = @points[i + 1][1] - @points[i][1]
          ret = [@points[i][0] + (dx * distT),
                 @points[i][1] + (dy * distT)]
          break
        end
        i += 1
      end
      return ret
    end
  end

  #=============================================================================
  #
  #=============================================================================
  def catmullRom(p1, p2, p3, p4, t)
    # p1=prevPoint, p2=startPoint, p3=endPoint, p4=nextPoint, t is from 0 through 1
    t2 = t * t
    t3 = t2 * t
    return 0.5 * ((2 * p2) + (t * (p3 - p1)) +
           (t2 * ((2 * p1) - (5 * p2) + (4 * p3) - p4)) +
           (t3 * (p4 - (3 * p3) + (3 * p2) - p1)))
  end

  def getCatmullRomPoint(src, t)
    x = 0, y = 0
    t *= 3.0
    if t < 1.0
      x = catmullRom(src[0].x, src[0].x, src[1].x, src[2].x, t)
      y = catmullRom(src[0].y, src[0].y, src[1].y, src[2].y, t)
    elsif t < 2.0
      t -= 1.0
      x = catmullRom(src[0].x, src[1].x, src[2].x, src[3].x, t)
      y = catmullRom(src[0].y, src[1].y, src[2].y, src[3].y, t)
    else
      t -= 2.0
      x = catmullRom(src[1].x, src[2].x, src[3].x, src[3].x, t)
      y = catmullRom(src[1].y, src[2].y, src[3].y, src[3].y, t)
    end
    return [x, y]
  end

  def getCurvePoint(src, t)
    return getCatmullRomPoint(src, t)
  end

  def curveToPointPath(curve, numpoints)
    return nil if numpoints < 2
    path = PointPath.new
    step = 1.0 / (numpoints - 1)
    t = 0.0
    numpoints.times do
      point = getCurvePoint(curve, t)
      path.addPoint(point[0], point[1])
      t += step
    end
    return path
  end

  def pbDefinePath(canvas)
    sliderwin2 = ControlWindow.new(0, 0, 320, 320)
    sliderwin2.viewport = canvas.viewport
    sliderwin2.addSlider(_INTL("Número de frames:"), 2, 500, 20)
    sliderwin2.opacity = 200
    defcurvebutton = sliderwin2.addButton(_INTL("Definir Curva Suave"))
    defpathbutton = sliderwin2.addButton(_INTL("Definir Ruta a Mano Alzada"))
    okbutton = sliderwin2.addButton(_INTL("OK"))
    cancelbutton = sliderwin2.addButton(_INTL("Cancelar"))
    points = []
    path = nil
    loop do
      Graphics.update
      Input.update
      sliderwin2.update
      if sliderwin2.changed?(0)   # Number of frames
        if path
          path = path.smoothPointPath(sliderwin2.value(0), false)
          i = 0
          path.each do |point|
            if i < points.length
              points[i].x = point[0]
              points[i].y = point[1]
            else
              points.push(PointSprite.new(point[0], point[1], canvas.viewport))
            end
            i += 1
          end
          (i...points.length).each do |j|
            points[j].dispose
            points[j] = nil
          end
          points.compact!
        end
      elsif sliderwin2.changed?(defcurvebutton)
        points.each do |point|
          point.dispose
        end
        points.clear
        30.times do
          point = PointSprite.new(0, 0, canvas.viewport)
          point.visible = false
          points.push(point)
        end
        curve = [
          ControlPointSprite.new(true, canvas.viewport),
          ControlPointSprite.new(false, canvas.viewport),
          ControlPointSprite.new(false, canvas.viewport),
          ControlPointSprite.new(true, canvas.viewport)
        ]
        showline = false
        sliderwin2.visible = false
        # This window displays the mouse's current position
        window = Window_UnformattedTextPokemon.newWithSize(
          "", 0, 320 - 64, 128, 64, canvas.viewport
        )
        loop do
          Graphics.update
          Input.update
          if Input.trigger?(Input::BACK)
            break
          end
          if Input.trigger?(Input::MOUSELEFT)
            4.times do |j|
              next if !curve[j].hittest?
              if [1, 2].include?(j) && (!curve[0].visible || !curve[3].visible)
                next
              end
              curve[j].visible = true
              4.times do |k|
                curve[k].dragging = (k == j)
              end
              break
            end
          end
          4.times do |j|
            curve[j].mouseover
          end
          mousepos = Mouse.getMousePos(true)
          newtext = (mousepos) ? sprintf("(%d,%d)", mousepos[0], mousepos[1]) : "(??,??)"
          window.text = newtext if window.text != newtext
          if curve[0].visible && curve[3].visible &&
             !curve[0].dragging && !curve[3].dragging
            points.each do |point|
              point.visible = true
            end
            if !showline
              curve[1].visible = true
              curve[2].visible = true
              curve[1].x = curve[0].x + (0.3333 * (curve[3].x - curve[0].x))
              curve[1].y = curve[0].y + (0.3333 * (curve[3].y - curve[0].y))
              curve[2].x = curve[0].x + (0.6666 * (curve[3].x - curve[0].x))
              curve[2].y = curve[0].y + (0.6666 * (curve[3].y - curve[0].y))
            end
            showline = true
          end
          if showline
            step = 1.0 / (points.length - 1)
            t = 0.0
            points.length.times do |j|
              point = getCurvePoint(curve, t)
              points[j].x = point[0]
              points[j].y = point[1]
              t += step
            end
          end
        end
        window.dispose
        # dispose temporary path
        points.each do |point|
          point.dispose
        end
        points.clear
        if showline
          path = curveToPointPath(curve, sliderwin2.value(0))
#          File.open("pointpath.txt", "wb") { |f| f.write(path.inspect) }
          path.each do |point|
            points.push(PointSprite.new(point[0], point[1], canvas.viewport))
          end
        end
        curve.each do |point|
          point.dispose
        end
        sliderwin2.visible = true
        next
      elsif sliderwin2.changed?(defpathbutton)
        canceled = false
        pointpath = PointPath.new
        points.each do |point|
          point.dispose
        end
        points.clear
        window = Window_UnformattedTextPokemon.newWithSize(
          "", 0, 320 - 64, 128, 64, canvas.viewport
        )
        sliderwin2.visible = false
        loop do
          Graphics.update
          Input.update
          if Input.triggerex?(:ESCAPE)
            canceled = true
            break
          end
          if Input.trigger?(Input::MOUSELEFT)
            break
          end
          mousepos = Mouse.getMousePos(true)
          window.text = (mousepos) ? sprintf("(%d,%d)", mousepos[0], mousepos[1]) : "(??,??)"
        end
        until canceled
          mousepos = Mouse.getMousePos(true)
          if mousepos && !pointpath.isEndPoint?(mousepos[0], mousepos[1])
            pointpath.addPoint(mousepos[0], mousepos[1])
            points.push(PointSprite.new(mousepos[0], mousepos[1], canvas.viewport))
          end
          window.text = (mousepos) ? sprintf("(%d,%d)", mousepos[0], mousepos[1]) : "(??,??)"
          Graphics.update
          Input.update
          if Input.triggerex?(:ESCAPE) || Input.time?(Input::MOUSELEFT) == 0
            break
          end
        end
        window.dispose
        # dispose temporary path
        points.each do |point|
          point.dispose
        end
        points.clear
        # generate smooth path from temporary path
        path = pointpath.smoothPointPath(sliderwin2.value(0), true)
        # redraw path from smooth path
        path.each do |point|
          points.push(PointSprite.new(point[0], point[1], canvas.viewport))
        end
#        File.open("pointpath.txt", "wb") { |f| f.write(path.inspect) }
        sliderwin2.visible = true
        next
      elsif sliderwin2.changed?(okbutton) && path
#        File.open("pointpath.txt", "wb") { |f| f.write(path.inspect) }
        neededsize = canvas.currentframe + sliderwin2.value(0)
        if neededsize > canvas.animation.length
          canvas.animation.resize(neededsize)
        end
        thiscel = canvas.currentCel
        celnumber = canvas.currentcel
        (canvas.currentframe...neededsize).each do |j|
          cel = canvas.animation[j][celnumber]
          if !canvas.animation[j][celnumber]
            cel = pbCreateCel(0, 0, thiscel[AnimFrame::PATTERN], canvas.animation.position)
            canvas.animation[j][celnumber] = cel
          end
          cel[AnimFrame::X] = path[j - canvas.currentframe][0]
          cel[AnimFrame::Y] = path[j - canvas.currentframe][1]
        end
        break
      elsif sliderwin2.changed?(cancelbutton) || Input.trigger?(Input::BACK)
        break
      end
    end
    # dispose all points
    points.each do |point|
      point.dispose
    end
    points.clear
    sliderwin2.dispose
    return
  end
end


==============================================================================
# Script: AnimEditor_ExportImport
==============================================================================
module BattleAnimationEditor
  module_function

  #=============================================================================
  # Importing and exporting
  #=============================================================================
  def pbRgssChdir(dir)
    RTP.eachPathFor(dir) { |path| Dir.chdir(path) { yield } }
  end

  def tryLoadData(file)
    begin
      return load_data(file)
    rescue
      return nil
    end
  end

  def dumpBase64Anim(s)
    return [Zlib::Deflate.deflate(Marshal.dump(s))].pack("m").gsub(/\n/, "\r\n")
  end

  def loadBase64Anim(s)
    return Marshal.restore(Zlib::Inflate.inflate(s.unpack("m")[0]))
  end

  def pbExportAnim(animations)
    filename = pbMessageFreeText(_INTL("Introduce un nombre de archivo."), "", false, 32)
    if filename != ""
      begin
        filename += ".anm"
        File.open(filename, "wb") do |f|
          f.write(dumpBase64Anim(animations[animations.selected]))
        end
        failed = false
      rescue
        pbMessage(_INTL("No se ha podido guardar la animación como {1}.", filename))
        failed = true
      end
      if !failed
        pbMessage(_INTL("La animación se ha guardado como {1} en la carpeta del juego.", filename))
        pbMessage(_INTL("Es un archivo de texto, así que puede ser traspasado a otros de forma sencilla."))
      end
    end
  end

  def pbImportAnim(animations, canvas, animwin)
    animfiles = []
    pbRgssChdir(".") { animfiles.concat(Dir.glob("*.anm")) }
    cmdwin = pbListWindow(animfiles, 320)
    cmdwin.opacity = 200
    cmdwin.height = 480
    cmdwin.viewport = canvas.viewport
    loop do
      Graphics.update
      Input.update
      cmdwin.update
      if Input.trigger?(Input::USE) && animfiles.length > 0
        begin
          textdata = loadBase64Anim(IO.read(animfiles[cmdwin.index]))
          throw "Bad data" if !textdata.is_a?(PBAnimation)
          textdata.id = -1 # this is not an RPG Maker XP animation
          pbConvertAnimToNewFormat(textdata)
          animations[animations.selected] = textdata
        rescue
          pbMessage(_INTL("La animación no es válida o no puede ser cargada."))
          next
        end
        graphic = animations[animations.selected].graphic
        graphic = "Graphics/Animations/#{graphic}"
        if graphic && graphic != "" && !FileTest.image_exist?(graphic)
          pbMessage(_INTL("No se encuentra el archivo de la animación {1}. Se cargará la animación igualmente.", graphic))
        end
        canvas.loadAnimation(animations[animations.selected])
        animwin.animbitmap = canvas.animbitmap
        break
      end
      if Input.trigger?(Input::BACK)
        break
      end
    end
    cmdwin.dispose
    return
  end

  #=============================================================================
  # Format conversion
  #=============================================================================
  def pbConvertAnimToNewFormat(textdata)
    needconverting = false
    textdata.length.times do |i|
      next if !textdata[i]
      PBAnimation::MAX_SPRITES.times do |j|
        next if !textdata[i][j]
        needconverting = true if textdata[i][j][AnimFrame::FOCUS].nil?
        break if needconverting
      end
      break if needconverting
    end
    if needconverting
      textdata.length.times do |i|
        next if !textdata[i]
        PBAnimation::MAX_SPRITES.times do |j|
          next if !textdata[i][j]
          textdata[i][j][AnimFrame::PRIORITY] = 1 if textdata[i][j][AnimFrame::PRIORITY].nil?
          case j
          when 0      # User battler
            textdata[i][j][AnimFrame::FOCUS] = 2
            textdata[i][j][AnimFrame::X] = Battle::Scene::FOCUSUSER_X
            textdata[i][j][AnimFrame::Y] = Battle::Scene::FOCUSUSER_Y
          when 1   # Target battler
            textdata[i][j][AnimFrame::FOCUS] = 1
            textdata[i][j][AnimFrame::X] = Battle::Scene::FOCUSTARGET_X
            textdata[i][j][AnimFrame::Y] = Battle::Scene::FOCUSTARGET_Y
          else
            textdata[i][j][AnimFrame::FOCUS] = (textdata.position || 4)
            if textdata.position == 1
              textdata[i][j][AnimFrame::X] += Battle::Scene::FOCUSTARGET_X
              textdata[i][j][AnimFrame::Y] += Battle::Scene::FOCUSTARGET_Y - 2
            end
          end
        end
      end
    end
    return needconverting
  end

  def pbConvertAnimsToNewFormat
    pbMessage(_INTL("Se van a convertir las animaciones."))
    count = 0
    animations = pbLoadBattleAnimations
    if !animations || !animations[0]
      pbMessage(_INTL("No existen animaciones."))
      return
    end
    animations.length.times do |k|
      next if !animations[k]
      ret = pbConvertAnimToNewFormat(animations[k])
      count += 1 if ret
    end
    if count > 0
      save_data(animations, "Data/PkmnAnimations.rxdata")
      $game_temp.battle_animations_data = nil
    end
    pbMessage(_INTL("{1} se han convertido las animaciones al nuevo formato.", count))
  end
end


==============================================================================
# Script: AnimEditor_Functions
==============================================================================
module BattleAnimationEditor
  module_function

  #=============================================================================
  # Mini battle scene
  #=============================================================================
  class MiniBattler
    attr_accessor :index
    attr_accessor :pokemon

    def initialize(index); self.index = index; end
  end

  #=============================================================================
  #
  #=============================================================================
  class MiniBattle
    attr_accessor :battlers

    def initialize
      @battlers = []
      4.times { |i| @battlers[i] = MiniBattler.new(i) }
    end
  end

  #=============================================================================
  # Pop-up menus for buttons in bottom menu
  #=============================================================================
  def pbSelectAnim(canvas, animwin)
    animfiles = []
    pbRgssChdir(File.join("Graphics", "Animations")) { animfiles.concat(Dir.glob("*.png")) }
    cmdwin = pbListWindow(animfiles, 320)
    cmdwin.opacity = 200
    cmdwin.height = 512
    bmpwin = BitmapDisplayWindow.new(320, 0, 320, 448)
    ctlwin = ControlWindow.new(320, 448, 320, 64)
    cmdwin.viewport = canvas.viewport
    bmpwin.viewport = canvas.viewport
    ctlwin.viewport = canvas.viewport
    ctlwin.addSlider(_INTL("Matiz:"), 0, 359, 0)
    loop do
      bmpwin.bitmapname = cmdwin.commands[cmdwin.index]
      Graphics.update
      Input.update
      cmdwin.update
      bmpwin.update
      ctlwin.update
      bmpwin.hue = ctlwin.value(0) if ctlwin.changed?(0)
      if Input.trigger?(Input::USE) && animfiles.length > 0
        filename = cmdwin.commands[cmdwin.index]
        bitmap = AnimatedBitmap.new("Graphics/Animations/" + filename, ctlwin.value(0)).deanimate
        canvas.animation.graphic = File.basename(filename, ".*")
        canvas.animation.hue = ctlwin.value(0)
        canvas.animbitmap = bitmap
        animwin.animbitmap = bitmap
        break
      end
      if Input.trigger?(Input::BACK)
        break
      end
    end
    bmpwin.dispose
    cmdwin.dispose
    ctlwin.dispose
    return
  end

  def pbChangeMaximum(canvas)
    sliderwin2 = ControlWindow.new(0, 0, 320, 32 * 4)
    sliderwin2.viewport = canvas.viewport
    sliderwin2.addSlider(_INTL("Frames:"), 1, 1000, canvas.animation.length)
    okbutton = sliderwin2.addButton(_INTL("OK"))
    cancelbutton = sliderwin2.addButton(_INTL("Cancelar"))
    sliderwin2.opacity = 200
    loop do
      Graphics.update
      Input.update
      sliderwin2.update
      if sliderwin2.changed?(okbutton)
        canvas.animation.resize(sliderwin2.value(0))
        break
      end
      if sliderwin2.changed?(cancelbutton) || Input.trigger?(Input::BACK)
        break
      end
    end
    sliderwin2.dispose
    return
  end

  def pbAnimName(animation, cmdwin)
    window = ControlWindow.new(320, 128, 320, 32 * 4)
    window.z = 99999
    window.addControl(TextField.new(_INTL("Nuevo Nombre:"), animation.name))
    Input.text_input = true
    okbutton = window.addButton(_INTL("OK"))
    cancelbutton = window.addButton(_INTL("Cancelar"))
    window.opacity = 224
    loop do
      Graphics.update
      Input.update
      window.update
      if window.changed?(okbutton) || Input.triggerex?(:RETURN)
        cmdwin.commands[cmdwin.index] = _INTL("{1} {2}", cmdwin.index, window.controls[0].text)
        animation.name = window.controls[0].text
        break
      end
      if window.changed?(cancelbutton) || Input.triggerex?(:ESCAPE)
        break
      end
    end
    window.dispose
    Input.text_input = false
    return
  end

  def pbAnimList(animations, canvas, animwin)
    commands = []
    animations.length.times do |i|
      animations[i] = PBAnimation.new if !animations[i]
      commands[commands.length] = _INTL("{1} {2}", i, animations[i].name)
    end
    cmdwin = pbListWindow(commands, 320)
    cmdwin.height = 416
    cmdwin.opacity = 224
    cmdwin.index = animations.selected
    cmdwin.viewport = canvas.viewport
    helpwindow = Window_UnformattedTextPokemon.newWithSize(
      _INTL("Enter: Load/rename an animation\nEsc: Cancel"),
      320, 0, 320, 128, canvas.viewport
    )
    maxsizewindow = ControlWindow.new(0, 416, 320, 32 * 3)
    maxsizewindow.addSlider(_INTL("Animaciones Totales:"), 1, 2000, animations.length)
    maxsizewindow.addButton(_INTL("Cambiar tamaño de Lista de Anim."))
    maxsizewindow.opacity = 224
    maxsizewindow.viewport = canvas.viewport
    loop do
      Graphics.update
      Input.update
      cmdwin.update
      maxsizewindow.update
      helpwindow.update
      if maxsizewindow.changed?(1)
        newsize = maxsizewindow.value(0)
        animations.resize(newsize)
        commands.clear
        animations.length.times do |i|
          commands[commands.length] = _INTL("{1} {2}", i, animations[i].name)
        end
        cmdwin.commands = commands
        cmdwin.index = animations.selected
        next
      end
      if Input.trigger?(Input::USE) && animations.length > 0
        cmd2 = pbShowCommands(helpwindow,
                              [_INTL("Cargar Animación"),
                               _INTL("Renombrar"),
                               _INTL("Eliminar")], -1)
        case cmd2
        when 0   # Load Animation
          canvas.loadAnimation(animations[cmdwin.index])
          animwin.animbitmap = canvas.animbitmap
          animations.selected = cmdwin.index
          break
        when 1   # Rename
          pbAnimName(animations[cmdwin.index], cmdwin)
          cmdwin.refresh
        when 2   # Delete
          if pbConfirmMessage(_INTL("¿Estás seguro de que quieres eliminar esta animación?"))
            animations[cmdwin.index] = PBAnimation.new
            cmdwin.commands[cmdwin.index] = _INTL("{1} {2}", cmdwin.index, animations[cmdwin.index].name)
            cmdwin.refresh
          end
        end
      end
      if Input.trigger?(Input::BACK)
        break
      end
    end
    helpwindow.dispose
    maxsizewindow.dispose
    cmdwin.dispose
  end

  #=============================================================================
  # Pop-up menus for individual cels
  #=============================================================================
  def pbChooseNum(cel)
    ret = cel
    sliderwin2 = ControlWindow.new(0, 0, 320, 32 * 5)
    sliderwin2.z = 99999
    sliderwin2.addLabel(_INTL("Número Antiguo: {1}", cel))
    sliderwin2.addSlider(_INTL("Número Nuevo:"), 2, PBAnimation::MAX_SPRITES, cel)
    okbutton = sliderwin2.addButton(_INTL("OK"))
    cancelbutton = sliderwin2.addButton(_INTL("Cancelar"))
    loop do
      Graphics.update
      Input.update
      sliderwin2.update
      if sliderwin2.changed?(okbutton)
        ret = sliderwin2.value(1)
        break
      end
      if sliderwin2.changed?(cancelbutton) || Input.trigger?(Input::BACK)
        ret = -1
        break
      end
    end
    sliderwin2.dispose
    return ret
  end

  def pbSetTone(cel, previewsprite)
    sliderwin2 = ControlWindow.new(0, 0, 320, 320)
    sliderwin2.z = 99999
    sliderwin2.addSlider(_INTL("Offset Rojo:"), -255, 255, cel[AnimFrame::TONERED])
    sliderwin2.addSlider(_INTL("Offset Verde:"), -255, 255, cel[AnimFrame::TONEGREEN])
    sliderwin2.addSlider(_INTL("Offset Azul:"), -255, 255, cel[AnimFrame::TONEBLUE])
    sliderwin2.addSlider(_INTL("Tono Gris:"), 0, 255, cel[AnimFrame::TONEGRAY])
    okbutton = sliderwin2.addButton(_INTL("OK"))
    cancelbutton = sliderwin2.addButton(_INTL("Cancelar"))
    loop do
      previewsprite.tone.set(sliderwin2.value(0), sliderwin2.value(1),
                             sliderwin2.value(2), sliderwin2.value(3))
      Graphics.update
      Input.update
      sliderwin2.update
      if sliderwin2.changed?(okbutton)
        cel[AnimFrame::TONERED] = sliderwin2.value(0)
        cel[AnimFrame::TONEGREEN] = sliderwin2.value(1)
        cel[AnimFrame::TONEBLUE] = sliderwin2.value(2)
        cel[AnimFrame::TONEGRAY] = sliderwin2.value(3)
        break
      end
      if sliderwin2.changed?(cancelbutton) || Input.trigger?(Input::BACK)
        break
      end
    end
    sliderwin2.dispose
    return
  end

  def pbSetFlash(cel, previewsprite)
    sliderwin2 = ControlWindow.new(0, 0, 320, 320)
    sliderwin2.z = 99999
    sliderwin2.addSlider(_INTL("Rojo:"), 0, 255, cel[AnimFrame::COLORRED])
    sliderwin2.addSlider(_INTL("Verde:"), 0, 255, cel[AnimFrame::COLORGREEN])
    sliderwin2.addSlider(_INTL("Azul:"), 0, 255, cel[AnimFrame::COLORBLUE])
    sliderwin2.addSlider(_INTL("Alfa:"), 0, 255, cel[AnimFrame::COLORALPHA])
    okbutton = sliderwin2.addButton(_INTL("OK"))
    cancelbutton = sliderwin2.addButton(_INTL("Cancelar"))
    loop do
      previewsprite.tone.set(sliderwin2.value(0), sliderwin2.value(1),
                             sliderwin2.value(2), sliderwin2.value(3))
      Graphics.update
      Input.update
      sliderwin2.update
      if sliderwin2.changed?(okbutton)
        cel[AnimFrame::COLORRED] = sliderwin2.value(0)
        cel[AnimFrame::COLORGREEN] = sliderwin2.value(1)
        cel[AnimFrame::COLORBLUE] = sliderwin2.value(2)
        cel[AnimFrame::COLORALPHA] = sliderwin2.value(3)
        break
      end
      if sliderwin2.changed?(cancelbutton) || Input.trigger?(Input::BACK)
        break
      end
    end
    sliderwin2.dispose
    return
  end

  def pbCellProperties(canvas)
    cel = canvas.currentCel.clone # Clone cell, in case operation is canceled
    return if !cel
    sliderwin2 = ControlWindow.new(0, 0, 320, 32 * 16)
    previewwin = ControlWindow.new(320, 0, 192, 192)
    sliderwin2.viewport = canvas.viewport
    previewwin.viewport = canvas.viewport
    previewsprite = Sprite.new(canvas.viewport)
    previewsprite.bitmap = canvas.animbitmap
    previewsprite.z = previewwin.z + 1
    sliderwin2.z = previewwin.z + 2
    set0 = sliderwin2.addSlider(_INTL("Patrón:"), -2, 1000, cel[AnimFrame::PATTERN])
    set1 = sliderwin2.addSlider(_INTL("X:"), -64, 512 + 64, cel[AnimFrame::X])
    set2 = sliderwin2.addSlider(_INTL("Y:"), -64, 384 + 64, cel[AnimFrame::Y])
    set3 = sliderwin2.addSlider(_INTL("Zoom X:"), 5, 1000, cel[AnimFrame::ZOOMX])
    set4 = sliderwin2.addSlider(_INTL("Zoom Y:"), 5, 1000, cel[AnimFrame::ZOOMY])
    set5 = sliderwin2.addSlider(_INTL("Ángulo:"), 0, 359, cel[AnimFrame::ANGLE])
    set6 = sliderwin2.addSlider(_INTL("Opacidad:"), 0, 255, cel[AnimFrame::OPACITY])
    set7 = sliderwin2.addSlider(_INTL("Fusión:"), 0, 2, cel[AnimFrame::BLENDTYPE])
    set8 = sliderwin2.addTextSlider(_INTL("Voltear:"), [_INTL("Falso"), _INTL("Verdadero")], cel[AnimFrame::MIRROR])
    prio = [_INTL("Atrás"), _INTL("Al frente"), _INTL("Detrás del foco"), _INTL("Sobre el foco")]
    set9 = sliderwin2.addTextSlider(_INTL("Prioridad:"), prio, cel[AnimFrame::PRIORITY] || 1)
    foc = [_INTL("Usuario"), _INTL("Objetivo"), _INTL("Usuario y objetivo"), _INTL("Pantalla")]
    curfoc = [3, 1, 0, 2, 3][cel[AnimFrame::FOCUS] || canvas.animation.position || 4]
    set10 = sliderwin2.addTextSlider(_INTL("Foco:"), foc, curfoc)
    flashbutton = sliderwin2.addButton(_INTL("Establecer Color de Fusión"))
    tonebutton = sliderwin2.addButton(_INTL("Establecer Tono de Color"))
    okbutton = sliderwin2.addButton(_INTL("OK"))
    cancelbutton = sliderwin2.addButton(_INTL("Cancelar"))
    # Set X and Y for preview sprite
    cel[AnimFrame::X] = 320 + 96
    cel[AnimFrame::Y] = 96
    canvas.setSpriteBitmap(previewsprite, cel)
    pbSpriteSetAnimFrame(previewsprite, cel, nil, nil)
    previewsprite.z = previewwin.z + 1
    sliderwin2.opacity = 200
    loop do
      Graphics.update
      Input.update
      sliderwin2.update
      if sliderwin2.changed?(set0) ||
         sliderwin2.changed?(set3) ||
         sliderwin2.changed?(set4) ||
         sliderwin2.changed?(set5) ||
         sliderwin2.changed?(set6) ||
         sliderwin2.changed?(set7) ||
         sliderwin2.changed?(set8) ||
         sliderwin2.changed?(set9) ||
         sliderwin2.changed?(set10)
        # Update preview sprite
        cel[AnimFrame::PATTERN] = sliderwin2.value(set0) if set0 >= 0
        cel[AnimFrame::ZOOMX] = sliderwin2.value(set3)
        cel[AnimFrame::ZOOMY] = sliderwin2.value(set4)
        cel[AnimFrame::ANGLE] = sliderwin2.value(set5)
        cel[AnimFrame::OPACITY] = sliderwin2.value(set6)
        cel[AnimFrame::BLENDTYPE] = sliderwin2.value(set7)
        cel[AnimFrame::MIRROR] = sliderwin2.value(set8)
        cel[AnimFrame::PRIORITY] = sliderwin2.value(set9)
        cel[AnimFrame::FOCUS] = [2, 1, 3, 4][sliderwin2.value(set10)]
        canvas.setSpriteBitmap(previewsprite, cel)
        pbSpriteSetAnimFrame(previewsprite, cel, nil, nil)
        previewsprite.z = previewwin.z + 1
      end
      if sliderwin2.changed?(flashbutton)
        pbSetFlash(cel, previewsprite)
        pbSpriteSetAnimFrame(previewsprite, cel, nil, nil)
        previewsprite.z = previewwin.z + 1
      end
      if sliderwin2.changed?(tonebutton)
        pbSetTone(cel, previewsprite)
        pbSpriteSetAnimFrame(previewsprite, cel, nil, nil)
        previewsprite.z = previewwin.z + 1
      end
      if sliderwin2.changed?(okbutton)
        cel[AnimFrame::PATTERN] = sliderwin2.value(set0) if set0 >= 0
        cel[AnimFrame::X] = sliderwin2.value(set1)
        cel[AnimFrame::Y] = sliderwin2.value(set2)
        cel[AnimFrame::ZOOMX] = sliderwin2.value(set3)
        cel[AnimFrame::ZOOMY] = sliderwin2.value(set4)
        cel[AnimFrame::ANGLE] = sliderwin2.value(set5)
        cel[AnimFrame::OPACITY] = sliderwin2.value(set6)
        cel[AnimFrame::BLENDTYPE] = sliderwin2.value(set7)
        cel[AnimFrame::MIRROR] = sliderwin2.value(set8)
        cel[AnimFrame::PRIORITY] = sliderwin2.value(set9)
        cel[AnimFrame::FOCUS] = [2, 1, 3, 4][sliderwin2.value(set10)]
        thiscel = canvas.currentCel
        # Save by replacing current cell
        thiscel[0, thiscel.length] = cel
        break
      end
      if sliderwin2.changed?(cancelbutton) || Input.trigger?(Input::BACK)
        break
      end
    end
    previewwin.dispose
    previewsprite.dispose
    sliderwin2.dispose
    return
  end

  #=============================================================================
  # Pop-up menus for buttons in right hand menu
  #=============================================================================
  def pbTimingList(canvas)
    commands = []
    cmdNewSound = -1
    cmdNewBG = -1
    cmdEditBG = -1
    cmdNewFO = -1
    cmdEditFO = -1
    canvas.animation.timing.each { |i| commands.push(i.to_s) }
    commands[cmdNewSound = commands.length] = _INTL("Añadir: Reproducir sonido...")
    commands[cmdNewBG = commands.length] = _INTL("Añadir: Definir gráfico de fondo...")
    commands[cmdEditBG = commands.length] = _INTL("Añadir: Editar color/localización del fondo...")
    commands[cmdNewFO = commands.length] = _INTL("Añadir: Establecer gráfico en primer plano...")
    commands[cmdEditFO = commands.length] = _INTL("Añadir: Editar color/localiz. de gráfico en primer plano...")
    cmdwin = pbListWindow(commands, 480)
    cmdwin.x = 0
    cmdwin.y = 0
    cmdwin.width = 640
    cmdwin.height = 384
    cmdwin.opacity = 200
    cmdwin.viewport = canvas.viewport
    framewindow = ControlWindow.new(0, 384, 640, 32 * 4)
    framewindow.addSlider(_INTL("Frame:"), 1, canvas.animation.length, canvas.currentframe + 1)
    framewindow.addButton(_INTL("Definir Frame"))
    framewindow.addButton(_INTL("Eliminar Tiempo"))
    framewindow.opacity = 200
    framewindow.viewport = canvas.viewport
    loop do
      Graphics.update
      Input.update
      cmdwin.update
      framewindow.update
      if cmdwin.index != cmdNewSound &&
         cmdwin.index != cmdNewBG &&
         cmdwin.index != cmdEditBG &&
         cmdwin.index != cmdNewFO &&
         cmdwin.index != cmdEditFO
        if framewindow.changed?(1)   # Set Frame
          canvas.animation.timing[cmdwin.index].frame = framewindow.value(0) - 1
          cmdwin.commands[cmdwin.index] = canvas.animation.timing[cmdwin.index].to_s
          cmdwin.refresh
          next
        end
        if framewindow.changed?(2)   # Delete Timing
          canvas.animation.timing.delete_at(cmdwin.index)
          cmdwin.commands.delete_at(cmdwin.index)
          cmdNewSound -= 1 if cmdNewSound >= 0
          cmdNewBG -= 1 if cmdNewBG >= 0
          cmdEditBG -= 1 if cmdEditBG >= 0
          cmdNewFO -= 1 if cmdNewFO >= 0
          cmdEditFO -= 1 if cmdEditFO >= 0
          cmdwin.refresh
          next
        end
      end
      if Input.trigger?(Input::USE)
        redrawcmds = false
        if cmdwin.index == cmdNewSound   # Add new sound
          newaudio = PBAnimTiming.new(0)
          if pbSelectSE(canvas, newaudio)
            newaudio.frame = framewindow.value(0) - 1
            canvas.animation.timing.push(newaudio)
            redrawcmds = true
          end
        elsif cmdwin.index == cmdNewBG   # Add new background graphic set
          newtiming = PBAnimTiming.new(1)
          if pbSelectBG(canvas, newtiming)
            newtiming.frame = framewindow.value(0) - 1
            canvas.animation.timing.push(newtiming)
            redrawcmds = true
          end
        elsif cmdwin.index == cmdEditBG   # Add new background edit
          newtiming = PBAnimTiming.new(2)
          if pbEditBG(canvas, newtiming)
            newtiming.frame = framewindow.value(0) - 1
            canvas.animation.timing.push(newtiming)
            redrawcmds = true
          end
        elsif cmdwin.index == cmdNewFO   # Add new foreground graphic set
          newtiming = PBAnimTiming.new(3)
          if pbSelectBG(canvas, newtiming)
            newtiming.frame = framewindow.value(0) - 1
            canvas.animation.timing.push(newtiming)
            redrawcmds = true
          end
        elsif cmdwin.index == cmdEditFO   # Add new foreground edit
          newtiming = PBAnimTiming.new(4)
          if pbEditBG(canvas, newtiming)
            newtiming.frame = framewindow.value(0) - 1
            canvas.animation.timing.push(newtiming)
            redrawcmds = true
          end
        else
          # Edit a timing here
          case canvas.animation.timing[cmdwin.index].timingType
          when 0
            pbSelectSE(canvas, canvas.animation.timing[cmdwin.index])
          when 1, 3
            pbSelectBG(canvas, canvas.animation.timing[cmdwin.index])
          when 2, 4
            pbEditBG(canvas, canvas.animation.timing[cmdwin.index])
          end
          cmdwin.commands[cmdwin.index] = canvas.animation.timing[cmdwin.index].to_s
          cmdwin.refresh
        end
        if redrawcmds
          cmdwin.commands[cmdNewSound] = nil if cmdNewSound >= 0
          cmdwin.commands[cmdNewBG] = nil if cmdNewBG >= 0
          cmdwin.commands[cmdEditBG] = nil if cmdEditBG >= 0
          cmdwin.commands[cmdNewFO] = nil if cmdNewFO >= 0
          cmdwin.commands[cmdEditFO] = nil if cmdEditFO >= 0
          cmdwin.commands.compact!
          cmdwin.commands.push(canvas.animation.timing[canvas.animation.timing.length - 1].to_s)
          cmdwin.commands[cmdNewSound = cmdwin.commands.length] = _INTL("Añadir: Reproducir sonido...")
          cmdwin.commands[cmdNewBG = cmdwin.commands.length] = _INTL("Añadir: Definir gráfico de fondo...")
          cmdwin.commands[cmdEditBG = cmdwin.commands.length] = _INTL("Añadir: Editar color/localización del fondo...")
          cmdwin.commands[cmdNewFO = cmdwin.commands.length] = _INTL("Añadir: Establecer gráfico en primer plano...")
          cmdwin.commands[cmdEditFO = cmdwin.commands.length] = _INTL("Añadir: Editar color/localiz. de gráfico en primer plano...")
          cmdwin.refresh
        end
      elsif Input.trigger?(Input::BACK)
        break
      end
    end
    cmdwin.dispose
    framewindow.dispose
    return
  end

  def pbSelectSE(canvas, audio)
    filename = (audio.name != "") ? audio.name : ""
    displayname = (filename != "") ? filename : _INTL("<grito del usuario>")
    animfiles = []
    ret = false
    pbRgssChdir(File.join("Audio", "SE", "Anim")) do
      animfiles.concat(Dir.glob("*.wav"))
      animfiles.concat(Dir.glob("*.ogg"))
      animfiles.concat(Dir.glob("*.mp3"))
      animfiles.concat(Dir.glob("*.wma"))
    end
    animfiles.uniq!
    animfiles.sort! { |a, b| a.downcase <=> b.downcase }
    animfiles = [_INTL("[Reproducir grito del usuario]")] + animfiles
    cmdwin = pbListWindow(animfiles, 320)
    cmdwin.height = 480
    cmdwin.opacity = 200
    cmdwin.viewport = canvas.viewport
    maxsizewindow = ControlWindow.new(320, 0, 320, 32 * 8)
    maxsizewindow.addLabel(_INTL("Archivo: \"{1}\"", displayname))
    maxsizewindow.addSlider(_INTL("Volumen:"), 0, 100, audio.volume)
    maxsizewindow.addSlider(_INTL("Tono:"), 20, 250, audio.pitch)
    maxsizewindow.addButton(_INTL("Reproducir Sonido"))
    maxsizewindow.addButton(_INTL("Parar Sonido"))
    maxsizewindow.addButton(_INTL("OK"))
    maxsizewindow.addButton(_INTL("Cancelar"))
    maxsizewindow.opacity = 200
    maxsizewindow.viewport = canvas.viewport
    loop do
      Graphics.update
      Input.update
      cmdwin.update
      maxsizewindow.update
      if maxsizewindow.changed?(3) && animfiles.length > 0 && filename != ""   # Play Sound
        pbSEPlay(RPG::AudioFile.new("Anim/" + filename, maxsizewindow.value(1), maxsizewindow.value(2)))
      end
      pbSEStop if maxsizewindow.changed?(4) && animfiles.length > 0   # Stop Sound
      if maxsizewindow.changed?(5) # OK
        audio.name = File.basename(filename, ".*")
        audio.volume = maxsizewindow.value(1)
        audio.pitch = maxsizewindow.value(2)
        ret = true
        break
      end
      break if maxsizewindow.changed?(6)   # Cancel
      if Input.trigger?(Input::USE) && animfiles.length > 0
        filename = (cmdwin.index == 0) ? "" : cmdwin.commands[cmdwin.index]
        displayname = (filename != "") ? filename : _INTL("<user's cry>")
        maxsizewindow.controls[0].text = _INTL("Archivo: \"{1}\"", displayname)
      elsif Input.trigger?(Input::BACK)
        break
      end
    end
    cmdwin.dispose
    maxsizewindow.dispose
    return ret
  end

