  def pbBattleDebugBattlerInfo(battler)
    ret = ""
    return ret if battler.nil?
    # Battler index, name
    ret += sprintf("[%d] %s", battler.index, battler.pbThis)
    ret += "\n"
    # Species
    ret += _INTL("Especie: {1}", GameData::Species.get(battler.species).name)
    ret += "\n"
    # Form number
    ret += _INTL("Forma: {1}", battler.form)
    ret += "\n"
    # Level, gender, shininess
    ret += _INTL("Nivel {1}, {2}", battler.level,
                 (battler.pokemon.male?) ? "♂" : (battler.pokemon.female?) ? "♀" : _INTL("genderless"))
    ret += ", " + _INTL("variocolor") if battler.pokemon.shiny?
    ret += "\n"
    # HP
    ret += _INTL("PS: {1}/{2} ({3}%)", battler.hp, battler.totalhp, (100.0 * battler.hp / battler.totalhp).to_i)
    ret += "\n"
    # Status
    ret += _INTL("Estado: {1}", GameData::Status.get(battler.status).name)
    case battler.status
    when :SLEEP
      ret += " " + _INTL("({1} turnos restantes)", battler.statusCount)
    when :POISON
      if battler.statusCount > 0
        ret += " " + _INTL("(tóxico, {1}/16)", battler.effects[PBEffects::Toxic])
      end
    end
    ret += "\n"
    # Stat stages
    stages = []
    GameData::Stat.each_battle do |stat|
      next if battler.stages[stat.id] == 0
      stage_text = ""
      stage_text += "+" if battler.stages[stat.id] > 0
      stage_text += battler.stages[stat.id].to_s
      stage_text += " " + stat.name_brief
      stages.push(stage_text)
    end
    ret += _INTL("Cambios de estadísticas: {1}", (stages.empty?) ? "-" : stages.join(", "))
    ret += "\n"
    # Ability
    ret += _INTL("Habilidad: {1}", (battler.ability) ? battler.abilityName : "-")
    ret += "\n"
    # Held item
    ret += _INTL("Objeto: {1}", (battler.item) ? battler.itemName : "-")
    return ret
  end

  def pbBattleDebugPokemonInfo(pkmn)
    ret = ""
    return ret if pkmn.nil?
    sp_data = pkmn.species_data
    # Name, species
    ret += sprintf("%s (%s)", pkmn.name, sp_data.name)
    ret += "\n"
    # Form number
    ret += _INTL("Forma: {1}", sp_data.form)
    ret += "\n"
    # Level, gender, shininess
    ret += _INTL("Nivel {1}, {2}", pkmn.level,
                 (pkmn.male?) ? "♂" : (pkmn.female?) ? "♀" : _INTL("sin género"))
    ret += ", " + _INTL("variocolor") if pkmn.shiny?
    ret += "\n"
    # HP
    ret += _INTL("PS: {1}/{2} ({3}%)", pkmn.hp, pkmn.totalhp, (100.0 * pkmn.hp / pkmn.totalhp).to_i)
    ret += "\n"
    # Status
    ret += _INTL("Estado: {1}", GameData::Status.get(pkmn.status).name)
    case pkmn.status
    when :SLEEP
      ret += " " + _INTL("({1} turnos restantes)", pkmn.statusCount)
    when :POISON
      ret += " " + _INTL("(tóxico)") if pkmn.statusCount > 0
    end
    ret += "\n"
    # Ability
    ret += _INTL("Habilidad: {1}", pkmn.ability&.name || "-")
    ret += "\n"
    # Held item
    ret += _INTL("Objeto: {1}", pkmn.item&.name || "-")
    return ret
  end

  def pbBattlePokemonDebug(pkmn, battler = nil)
    # Setup windows
    viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
    viewport.z = 99999
    sprites = {}
    sprites["infowindow"] = Window_AdvancedTextPokemon.new("")
    infowindow = sprites["infowindow"]
    infowindow.x        = 0
    infowindow.y        = 0
    infowindow.width    = Graphics.width / 2
    infowindow.height   = Graphics.height
    infowindow.viewport = viewport
    infowindow.visible  = true
    sprites["dummywindow"] = Window_AdvancedTextPokemon.new("")
    sprites["dummywindow"].y = Graphics.height
    sprites["dummywindow"].width = Graphics.width
    sprites["dummywindow"].height = 0
    # Main loop
    need_refresh = true
    need_rebuild_commands = true
    cmd = 0
    commands = nil
    current_menu = nil
    loop do
      # Rebuild commands if needed (after actions that might change availability)
      if need_rebuild_commands
        old_current_menu = current_menu
        commands = CommandMenuList.new
        MenuHandlers.each_available(:battle_pokemon_debug_menu, pkmn, battler, self) do |option, hash, name|
          next if battler && hash["usage"] == :pokemon
          next if !battler && hash["usage"] == :battler
          commands.add(option, hash, name)
        end
        # Restore the current submenu if it still exists
        if old_current_menu && commands.hasSubMenu?(old_current_menu)
          commands.currentList = old_current_menu
        else
          current_menu = nil
        end
        # Clamp cmd to valid range (in case menu items were removed)
        cmd = [cmd, commands.list.length - 1].min if commands.list.length > 0
        cmd = 0 if cmd < 0
        need_rebuild_commands = false
      end
      if need_refresh
        if battler
          sprites["infowindow"].text = pbBattleDebugBattlerInfo(battler)
        else
          sprites["infowindow"].text = pbBattleDebugPokemonInfo(pkmn)
        end
        need_refresh = false
      end
      # Choose a command
      cmd = Kernel.pbShowCommands(sprites["dummywindow"], commands.list, -1, cmd)
      if cmd < 0   # Cancel
        parent = commands.getParent
        if parent   # Go up a level
          commands.currentList = parent[0]
          current_menu = parent[0]
          cmd = parent[1]
        else   # Exit
          break
        end
      else
        real_cmd = commands.getCommand(cmd)
        if commands.hasSubMenu?(real_cmd)
          commands.currentList = real_cmd
          current_menu = real_cmd
          cmd = 0
        else
          MenuHandlers.call(:battle_pokemon_debug_menu, real_cmd, "effect", pkmn, battler, self)
          need_refresh = true
          need_rebuild_commands = true
        end
      end
    end
    pbDisposeSpriteHash(sprites)
    viewport.dispose
  end
end

