MenuHandlers.add(:debug_menu, :test_wild_battle, {
  "name"        => _INTL("Testear combate salvaje"),
  "parent"      => :battle_menu,
  "description" => _INTL("Empezar combate individual contra un Pokémon salvaje. Eliges la especie/nivel."),
  "effect"      => proc {
