    if (hash[:category] || 2) == 2 && (hash[:power] || 0) != 0
      raise _INTL("El movimiento {1} está definido como un movimiento de Estado con un daño base distinto de cero.\n{2}",
                  hash[:real_name], FileLineData.linereport)
    elsif (hash[:category] || 2) != 2 && (hash[:power] || 0) == 0
      print _INTL("Advertencia: El movimiento {1} está definido como Físico o Especial pero tiene un daño base de 0. Se cambiará a un movimiento de Estado.\n{2}",
                  hash[:real_name], FileLineData.linereport)
      hash[:category] = 2
    end
