# Script: Bag with interactuable party
==============================================================================
#===============================================================================
# CREDITOS
# DiegoWT, Skyflyer, DPertierra
#===============================================================================
#===============================================================================
# Creating specific Bag and Party functionalities
#===============================================================================

# Making a minor edit to SpriteWindow_Selectable's update to avoid the
# pbPlayCursorSE to play while you scroll through the items' list
class SpriteWindow_Selectable < SpriteWindow_Base
  attr_reader :index
  attr_writer :ignore_input

  def update
    super
    if self.active && @item_max > 0 && @index >= 0 && !@ignore_input && @bag
      if Input.repeat?(Input::UP)
        if @index >= @column_max ||
           (Input.trigger?(Input::UP) && (@item_max % @column_max) == 0)
          oldindex = @index
          @index = (@index - @column_max + @item_max) % @item_max
          if @index != oldindex
            pbPlayCursorSE
            update_cursor_rect
          end
        end
      elsif Input.repeat?(Input::DOWN)
        if @index < @item_max - @column_max ||
           (Input.trigger?(Input::DOWN) && (@item_max % @column_max) == 0)
          oldindex = @index
          @index = (@index + @column_max) % @item_max
          if @index != oldindex
            pbPlayCursorSE
            update_cursor_rect
          end
        end
      elsif Input.repeat?(Input::JUMPUP)
        if @index > 0
          oldindex = @index
          @index = [self.index - self.page_item_max, 0].max
          if @index != oldindex
            pbPlayCursorSE
            self.top_row -= self.page_row_max
            update_cursor_rect
          end
        end
      elsif Input.repeat?(Input::JUMPDOWN)
        if @index < @item_max - 1
          oldindex = @index
          @index = [self.index + self.page_item_max, @item_max - 1].min
          if @index != oldindex
            pbPlayCursorSE
            self.top_row += self.page_row_max
            update_cursor_rect
          end
        end
      end
    elsif  self.active && @item_max > 0 && @index >= 0 && !@ignore_input
      if Input.repeat?(Input::UP)
        if @index >= @column_max ||
           (Input.trigger?(Input::UP) && (@item_max % @column_max) == 0)
          oldindex = @index
          @index = (@index - @column_max + @item_max) % @item_max
          if @index != oldindex
            pbPlayCursorSE
            update_cursor_rect
          end
        end
      elsif Input.repeat?(Input::DOWN)
        if @index < @item_max - @column_max ||
           (Input.trigger?(Input::DOWN) && (@item_max % @column_max) == 0)
          oldindex = @index
          @index = (@index + @column_max) % @item_max
          if @index != oldindex
            pbPlayCursorSE
            update_cursor_rect
          end
        end
      elsif Input.repeat?(Input::LEFT)
        if @column_max >= 2 && @index > 0
          oldindex = @index
          @index -= 1
          if @index != oldindex
            pbPlayCursorSE
            update_cursor_rect
          end
        end
      elsif Input.repeat?(Input::RIGHT)
        if @column_max >= 2 && @index < @item_max - 1
          oldindex = @index
          @index += 1
          if @index != oldindex
            pbPlayCursorSE
            update_cursor_rect
          end
        end
      elsif Input.repeat?(Input::JUMPUP)
        if @index > 0
          oldindex = @index
          @index = [self.index - self.page_item_max, 0].max
          if @index != oldindex
            pbPlayCursorSE
            self.top_row -= self.page_row_max
            update_cursor_rect
          end
        end
      elsif Input.repeat?(Input::JUMPDOWN)
        if @index < @item_max - 1
          oldindex = @index
          @index = [self.index + self.page_item_max, @item_max - 1].min
          if @index != oldindex
            pbPlayCursorSE
            self.top_row += self.page_row_max
            update_cursor_rect
          end
        end
      end
    end
  end
end

class Window_PokemonBag < Window_DrawableCommand
  attr_reader :pocket
  attr_accessor :sorting
  attr_accessor :party1sel
  attr_accessor :party2sel
  attr_accessor :filterlist

  # Coordenadas
  ITEM_X_OFFSET       = 16
  ITEM_Y_OFFSET       = 16
  ITEM_WIDTH_OFFSET   = 16
  CLOSE_TEXT_Y_OFFSET = 4
  MACHINE_NUMBER_Y_OFFSET = 4
  MACHINE_NAME_X_OFFSET = 70
  MACHINE_NAME_Y_OFFSET = 4
  REGISTER_ICON_WIDTH_OFFSET = 72
  REGISTER_ICON_Y_OFFSET = 10
  FAVORITE_REGISTERED_ICON_WIDTH_OFFSET = 30
  FAVORITE_ICON_Y_OFFSET = 13
  FAVORITE_KEYITEM_ICON_WIDTH_OFFSET = 92
  FAVORITE_ICON_WIDTH_OFFSET = 88
  QUANTITY_X_OFFSET = 16
  QUANTITY_Y_OFFSET = 2
  CURSOR_Y_OFFSET = 2

  # Colores
  BASE_COLOR_CLOSE_TEXT   = Color.new(78, 86, 100)
  SHADOW_COLOR_CLOSE_TEXT = Color.new(157, 171, 178)
  BASE_COLOR_SORTING      = Color.new(224, 0, 0)
  SHADOW_COLOR_SORTING    = Color.new(248, 144, 144)
  BASE_COLOR_SELECTION    = Color.new(78, 86, 100)
  SHADOW_COLOR_SELECTION  = Color.new(157, 171, 178)

  def initialize(bag, filterlist, pocket, x, y, width, height)
    @bag        = bag
    @filterlist = filterlist
    @pocket     = pocket
    @sorting  = false
    @party1sel = false
    @party2sel = false
    @adapter  = PokemonItemMartAdapter.new
    super(x, y, width, height)
    @selarrow   = AnimatedBitmap.new("Graphics/UI/Bag Screen with Party/cursor")
    @swaparrow  = AnimatedBitmap.new("Graphics/UI/Bag Screen with Party/cursor_swap")
    @party1arrow = AnimatedBitmap.new("Graphics/UI/Bag Screen with Party/cursor_party1")
    @party2arrow = AnimatedBitmap.new("Graphics/UI/Bag Screen with Party/cursor_party2")
    self.windowskin = nil
  end

  def dispose
    @swaparrow.dispose
    @party1arrow.dispose
    @party2arrow.dispose
    super
  end

  def pocket=(value)
    @pocket = value
    @item_max = (@filterlist) ? @filterlist[@pocket].length + 1 : @bag.pockets[@pocket].length + 1
    self.index = @bag.last_viewed_index(@pocket)
  end

  def page_row_max; return PokemonBag_Scene::ITEMSVISIBLE; end
  def page_item_max; return PokemonBag_Scene::ITEMSVISIBLE; end

  def item
    return nil if @filterlist && !@filterlist[@pocket][self.index]
    thispocket = @bag.pockets[@pocket]
    item = (@filterlist) ? thispocket[@filterlist[@pocket][self.index]] : thispocket[self.index]
    return (item) ? item[0] : nil
  end

  def itemCount
    return (@filterlist) ? @filterlist[@pocket].length + 1 : @bag.pockets[@pocket].length + 1
  end

  def itemRect(item)
    if item < 0 || item >= @item_max || item < self.top_item - 1 ||
       item > self.top_item + self.page_item_max
      return Rect.new(0, 0, 0, 0)
    else
      cursor_width = (self.width - self.borderX - ((@column_max - 1) * @column_spacing)) / @column_max
      x = item % @column_max * (cursor_width + @column_spacing)
      y = (item / @column_max * @row_height) - @virtualOy
      return Rect.new(x, y, cursor_width, @row_height)
    end
  end

  def drawCursor(index, rect)
    if self.index == index
      if @party1sel
        bmp = @party1arrow.bitmap
      elsif @party2sel
        bmp = @party2arrow.bitmap
      elsif @sorting
        bmp = @swaparrow.bitmap
      else
        bmp = @selarrow.bitmap
      end
      pbCopyBitmap(self.contents, bmp, rect.x, rect.y + CURSOR_Y_OFFSET)
    end
  end

  def drawItem(index, _count, rect)
    textpos = []
    rect = Rect.new(rect.x + ITEM_X_OFFSET, rect.y + ITEM_Y_OFFSET, rect.width - ITEM_WIDTH_OFFSET, rect.height)
    thispocket = @bag.pockets[@pocket]
    if index == self.itemCount - 1
      if @selarrow && index == self.index
        if @party2sel
          baseColor   = self.baseColor
          shadowColor = self.shadowColor
        else
          baseColor   = BASE_COLOR_CLOSE_TEXT
          shadowColor = SHADOW_COLOR_CLOSE_TEXT
        end
      else
        baseColor   = self.baseColor
        shadowColor = self.shadowColor
      end
      textpos.push([_INTL("CERRAR MOCHILA"), rect.x, rect.y + CLOSE_TEXT_Y_OFFSET, :left, baseColor, shadowColor])
    else
      item = (@filterlist) ? thispocket[@filterlist[@pocket][index]][0] : thispocket[index][0]
      baseColor   = self.baseColor
      shadowColor = self.shadowColor
      if @sorting && index == self.index
        baseColor   = BASE_COLOR_SORTING
        shadowColor = SHADOW_COLOR_SORTING
      elsif @party2sel && index == self.index
        baseColor   = self.baseColor
        shadowColor = self.shadowColor
      elsif @selarrow && index == self.index
        baseColor   = BASE_COLOR_SELECTION
        shadowColor = SHADOW_COLOR_SELECTION
      end
      item_data = GameData::Item.get(item)
      if item_data.is_machine?
        textpos.push(
          [@adapter.getDisplayNameMachineNumber(item), rect.x, rect.y + MACHINE_NUMBER_Y_OFFSET, :left, baseColor, shadowColor],
          [@adapter.getDisplayNameMachineName(item), rect.x + MACHINE_NAME_X_OFFSET, rect.y + MACHINE_NAME_Y_OFFSET, :left, baseColor, shadowColor]
        )
      else
        textpos.push(
          [@adapter.getDisplayName(item), rect.x, rect.y + 4, :left, baseColor, shadowColor]
        )
      end
      showing_register_icon = false
      if item_data.is_important?
        if @bag.registered?(item)
          pbDrawImagePositions(
            self.contents,
            [["Graphics/UI/Bag Screen with Party/icon_register", rect.x + rect.width - REGISTER_ICON_WIDTH_OFFSET, rect.y + REGISTER_ICON_Y_OFFSET, 0, 0, -1, 24]]
          )
          showing_register_icon = true
        elsif pbCanRegisterItem?(item)
          pbDrawImagePositions(
            self.contents,
            [["Graphics/UI/Bag Screen with Party/icon_register", rect.x + rect.width - REGISTER_ICON_WIDTH_OFFSET, rect.y + REGISTER_ICON_Y_OFFSET, 0, 24, -1, 24]]
          )
          showing_register_icon = true
        end
      end
      if @bag.favourite?(item)
        if !pbCanRegisterItem?(item) && !item_data.show_quantity? && !item_data.is_key_item? 
          pbDrawImagePositions(
            self.contents,
            [["Graphics/UI/Bag Screen with Party/favourite", rect.x + rect.width - FAVORITE_REGISTERED_ICON_WIDTH_OFFSET, rect.y + FAVORITE_ICON_Y_OFFSET, 0, 0, -1, 24]]
          )
        elsif item_data.is_key_item?
          pbDrawImagePositions(
            self.contents,
            [["Graphics/UI/Bag Screen with Party/favourite", rect.x + rect.width - FAVORITE_KEYITEM_ICON_WIDTH_OFFSET, rect.y + FAVORITE_ICON_Y_OFFSET, 0, 0, -1, 24]]
          )
        else
          pbDrawImagePositions(
            self.contents,
            [["Graphics/UI/Bag Screen with Party/favourite", rect.x + rect.width - FAVORITE_ICON_WIDTH_OFFSET, rect.y + FAVORITE_ICON_Y_OFFSET, 0, 0, -1, 24]]
          )
        end
      end
      if item_data.show_quantity? && !showing_register_icon
        qty = (@filterlist) ? thispocket[@filterlist[@pocket][index]][1] : thispocket[index][1]
        qtytext = _ISPRINTF("x{1: 3d}", qty)
        xQty    = rect.x + rect.width - self.contents.text_size(qtytext).width - QUANTITY_X_OFFSET
        textpos.push([qtytext, xQty, rect.y + QUANTITY_Y_OFFSET, :left, baseColor, shadowColor])
      end
    end
    pbDrawTextPositions(self.contents, textpos)
  end


  def refresh
    @item_max = itemCount
    self.update_cursor_rect
    dwidth  = self.width - self.borderX
    dheight = self.height - self.borderY
    self.contents = pbDoEnsureBitmap(self.contents, dwidth, dheight)
    self.contents.clear
    drawCursor(self.index, itemRect(self.index))
    @item_max.times do |i|
      next if i < self.top_item - 1 || i > self.top_item + self.page_item_max
      drawItem(i, @item_max, itemRect(i))
    end
  end

  def update
    super
    @uparrow.visible   = false
    @downarrow.visible = false
  end
end

class PokemonBagPartyBlankPanel < Sprite
  attr_accessor :text
  attr_accessor :text_color

  # Coordenadas
  PANEL_WIDTH = 112
  PANEL_X_OFFSET = 4
  PANEL_Y_BASE = 96
  PANEL_Y_OFFSET = 2

  def initialize(_pokemon,index,viewport=nil)
    super(viewport)
    self.x = (index % 2) * PANEL_WIDTH + PANEL_X_OFFSET
    self.y = (index % 2) + PANEL_Y_BASE + PANEL_Y_OFFSET
    @panelbgsprite = AnimatedBitmap.new("Graphics/UI/Bag Screen with Party/ptpanel_blank")
    self.bitmap = @panelbgsprite.bitmap
    @text = nil
  end

  def dispose
    @panelbgsprite.dispose
    super
  end

  def selected; return false; end
  def selected=(value); end
  def preselected; return false; end
  def preselected=(value); end
  def switching; return false; end
  def switching=(value); end
  def refresh; end
end

class PokemonBagPartyPanel < Sprite
  attr_reader :pokemon
  attr_reader :active
  attr_reader :selected
  attr_reader :preselected
  attr_reader :switching
  attr_reader :text
  attr_reader :text_color

  # Coordenadas del panel
  PANEL_WIDTH = 112
  PANEL_HEIGHT = 96
  PANEL_X_OFFSET = 4
  PANEL_Y_OFFSET = 2
  
  # Coordenadas de sprites internos
  HP_BAR_X_OFFSET = 6
  HP_BAR_Y_OFFSET = 60
  POKEMON_SPRITE_X_OFFSET = 32
  POKEMON_SPRITE_Y_OFFSET = 36
  HELD_ITEM_X_OFFSET = 76
  HELD_ITEM_Y_OFFSET = 40
  
  # Coordenadas de texto e iconos
  HP_TEXT_X = 52
  HP_TEXT_Y = 76
  HP_BAR_DRAW_X = 8
  HP_BAR_DRAW_Y = 62
  STATUS_ICON_X = 48
  STATUS_ICON_Y = 26
  POKERUS_ICON_X = 64
  POKERUS_ICON_Y = 44
  GENDER_TEXT_X = 92
  GENDER_TEXT_Y = 8
  SHINY_ICON_X = 84
  SHINY_ICON_Y = 44
  LEVEL_OVERLAY_X = 34
  LEVEL_OVERLAY_Y = 10
  LEVEL_TEXT_X = 58
  LEVEL_TEXT_Y = 8
  ANNOTATION_TEXT_X = 56
  ANNOTATION_TEXT_Y = 76
  
  # Colores de texto
  TEXT_BASE_COLOR = Color.new(248, 248, 248)
  TEXT_OUTLINE_COLOR = Color.new(0, 0, 0)
  TEXT_SHADOW_COLOR = Color.new(40, 40, 40)
  GENDER_MALE_COLOR = Color.new(116, 162, 237)
  GENDER_FEMALE_COLOR = Color.new(237, 116, 140)
  ANNOTATION_GRAY_COLOR = Color.new(90, 90, 90)
  ANNOTATION_SHADOW_COLOR = Color.new(40, 40, 40)
  ANNOTATION_LIGHT_SHADOW_COLOR = Color.new(140, 140, 140)

  def initialize(pokemon, index, viewport=nil)
    super(viewport)
    @pokemon = pokemon
    @active = (index == 0)   # true = rounded panel, false = rectangular panel
    @refreshing = true
    self.x = (index % 2) * PANEL_WIDTH + PANEL_X_OFFSET
    self.y = PANEL_HEIGHT * (index / 2) + PANEL_Y_OFFSET
    @panelbgsprite = ChangelingSprite.new(0, 0, viewport)
    @panelbgsprite.z = self.z
    if @active   # Rounded panel
      @panelbgsprite.add_bitmap(:APTO, "Graphics/UI/Bag Screen with Party/ptpanel_round_desel")
      @panelbgsprite.add_bitmap(:APTOsel, "Graphics/UI/Bag Screen with Party/ptpanel_round_sel")
      @panelbgsprite.add_bitmap(:fainted, "Graphics/UI/Bag Screen with Party/ptpanel_round_faint")
      @panelbgsprite.add_bitmap(:faintedsel, "Graphics/UI/Bag Screen with Party/ptpanel_round_faint_sel")
      @panelbgsprite.add_bitmap(:swap, "Graphics/UI/Bag Screen with Party/ptpanel_round_move")
      @panelbgsprite.add_bitmap(:swapsel, "Graphics/UI/Bag Screen with Party/ptpanel_round_move_sel")
      @panelbgsprite.add_bitmap(:swapsel2, "Graphics/UI/Bag Screen with Party/ptpanel_round_move_sel")
    else   # Rectangular panel
      @panelbgsprite.add_bitmap(:APTO, "Graphics/UI/Bag Screen with Party/ptpanel_rect_desel")
      @panelbgsprite.add_bitmap(:APTOsel, "Graphics/UI/Bag Screen with Party/ptpanel_rect_sel")
      @panelbgsprite.add_bitmap(:fainted, "Graphics/UI/Bag Screen with Party/ptpanel_rect_faint")
      @panelbgsprite.add_bitmap(:faintedsel, "Graphics/UI/Bag Screen with Party/ptpanel_rect_faint_sel")
      @panelbgsprite.add_bitmap(:swap, "Graphics/UI/Bag Screen with Party/ptpanel_rect_move")
      @panelbgsprite.add_bitmap(:swapsel, "Graphics/UI/Bag Screen with Party/ptpanel_rect_move_sel")
      @panelbgsprite.add_bitmap(:swapsel2, "Graphics/UI/Bag Screen with Party/ptpanel_rect_move_sel")
    end
    @pkmnsprite = PokemonIconSprite.new(pokemon, viewport)
    @pkmnsprite.setOffset(PictureOrigin::CENTER)
    @pkmnsprite.active = @active
    @pkmnsprite.z      = self.z + 1
    @hpbgsprite = ChangelingSprite.new(0, 0, viewport)
    @hpbgsprite.z = self.z + 2
    @hpbgsprite.add_bitmap(:APTO, "Graphics/UI/Bag Screen with Party/overlay_hp_back")
    @hpbgsprite.add_bitmap(:cursor, "Graphics/UI/Bag Screen with Party/overlay_hp_back")
    @helditemsprite = HeldItemIconSprite.new(0, 0, @pokemon, viewport)
    @helditemsprite.z = self.z + 3
    @overlaysprite = BitmapSprite.new(Graphics.width, Graphics.height, viewport)
    @overlaysprite.z = self.z + 4
    @hpbar    = AnimatedBitmap.new("Graphics/UI/Bag Screen with Party/overlay_hp")
    @statuses = AnimatedBitmap.new(_INTL("Graphics/UI/statuses"))
    @pokerus  = AnimatedBitmap.new("Graphics/UI/Bag Screen with Party/icon_pokerus") if BagScreenWiInParty::PKRSICON == true
    @selected      = false
    @preselected   = false
    @switching     = false
    @text          = nil
    @text_color    = nil
    @refreshBitmap = true
    @refreshing    = false
    refresh
  end

  def dispose
    @panelbgsprite.dispose
    @hpbgsprite.dispose
    @pkmnsprite.dispose
    @helditemsprite.dispose
    @overlaysprite.bitmap.dispose
    @overlaysprite.dispose
    @hpbar.dispose
    @statuses.dispose
    super
  end

  def x=(value)
    super
    refresh
  end

  def y=(value)
    super
    refresh
  end

  def color=(value)
    super
    refresh
  end

  def text=(value)
    if @text != value
      @text = value
      @refreshBitmap = true
      refresh
    end
  end

  def text_color=(value)
    if @text_color!=value
      @text_color = value
      @refreshBitmap = true
      refresh
    end
  end

  def pokemon=(value)
    @pokemon = value
    @pkmnsprite.pokemon = value if @pkmnsprite && !@pkmnsprite.disposed?
    @helditemsprite.pokemon = value if @helditemsprite && !@helditemsprite.disposed?
    @refreshBitmap = true
    refresh
  end

  def selected=(value)
    if @selected != value
      @selected = value
      refresh
    end
  end

  def preselected=(value)
    if @preselected != value
      @preselected = value
      refresh
    end
  end

  def switching=(value)
    if @switching != value
      @switching = value
      refresh
    end
  end

  def hp; return @pokemon.hp; end

  def refresh
    return if disposed?
    return if @refreshing
    @refreshing = true
    if @panelbgsprite && !@panelbgsprite.disposed?
      if self.selected
        if self.preselected;     @panelbgsprite.change_bitmap(:swapsel2)
        elsif @switching;        @panelbgsprite.change_bitmap(:swapsel)
        elsif @pokemon.fainted?; @panelbgsprite.change_bitmap(:faintedsel)
        else;                    @panelbgsprite.change_bitmap(:APTOsel)
        end
      else
        if self.preselected;     @panelbgsprite.change_bitmap(:swap)
        elsif @pokemon.fainted?; @panelbgsprite.change_bitmap(:fainted)
        else;                    @panelbgsprite.change_bitmap(:APTO)
        end
      end
      @panelbgsprite.x     = self.x
      @panelbgsprite.y     = self.y
      @panelbgsprite.color = self.color
    end
    if @hpbgsprite && !@hpbgsprite.disposed?
      @hpbgsprite.visible = !@pokemon.egg?
      if @hpbgsprite.visible
        if self.preselected || (self.selected); @hpbgsprite.change_bitmap(:cursor)
        else;                                   @hpbgsprite.change_bitmap(:APTO)
        end
        @hpbgsprite.x     = self.x + HP_BAR_X_OFFSET
        @hpbgsprite.y     = self.y + HP_BAR_Y_OFFSET
        @hpbgsprite.color = self.color
      end
    end
    if @pkmnsprite && !@pkmnsprite.disposed?
      @pkmnsprite.x        = self.x + POKEMON_SPRITE_X_OFFSET
      @pkmnsprite.y        = self.y + POKEMON_SPRITE_Y_OFFSET
      @pkmnsprite.color    = self.color
      @pkmnsprite.selected = self.selected
    end
    if @helditemsprite&.visible && !@helditemsprite.disposed?
      @helditemsprite.x     = self.x + HELD_ITEM_X_OFFSET
      @helditemsprite.y     = self.y + HELD_ITEM_Y_OFFSET
      @helditemsprite.color = self.color
    end
    if @overlaysprite && !@overlaysprite.disposed?
      @overlaysprite.x     = self.x
      @overlaysprite.y     = self.y
      @overlaysprite.color = self.color
    end
    if @refreshBitmap
      @refreshBitmap = false
      @overlaysprite.bitmap.clear if @overlaysprite.bitmap
      baseColor   = TEXT_BASE_COLOR
      outlineColor = TEXT_OUTLINE_COLOR
      pbSetSystemFont(@overlaysprite.bitmap)
      pbSetSmallFont(@overlaysprite.bitmap)
      textpos = []
      if !@pokemon.egg?
        if !@text || @text.length == 0
          # Draw HP numbers
          textpos.push([sprintf("% 3d /% 3d", @pokemon.hp, @pokemon.totalhp), HP_TEXT_X, HP_TEXT_Y, 2, baseColor, TEXT_SHADOW_COLOR, true, Graphics.width]) if !@text || @text.length == 0
        end
          # Draw HP bar
          if @pokemon.hp > 0
            w = @pokemon.hp * 94 / @pokemon.totalhp.to_f
            w = 1 if w < 1
            w = ((w / 2).round) * 2
            hpzone = 0
            hpzone = 1 if @pokemon.hp <= (@pokemon.totalhp / 2).floor
            hpzone = 2 if @pokemon.hp <= (@pokemon.totalhp / 4).floor
            hprect = Rect.new(0, hpzone * 8, w, 8)
            @overlaysprite.bitmap.blt(HP_BAR_DRAW_X, HP_BAR_DRAW_Y, @hpbar.bitmap, hprect)
          end
          # Draw status
          status = -1
          if @pokemon.fainted?
            status = GameData::Status.count - 1
          elsif @pokemon.status != :NONE
            status = GameData::Status.get(@pokemon.status).icon_position
          end
          if status >= 0
            statusrect = Rect.new(0, 16 * status, 44, 16)
            @overlaysprite.bitmap.blt(STATUS_ICON_X, STATUS_ICON_Y, @statuses.bitmap, statusrect)
          end
        # Draw Pokerus icon
          if BagScreenWiInParty::PKRSICON == true
            if @pokemon.pokerusStage == 1
              @overlaysprite.bitmap.blt(POKERUS_ICON_X, POKERUS_ICON_Y, @pokerus.bitmap, Rect.new(0, 0, 16, 16))
            elsif @pokemon.pokerusStage == 2
              @overlaysprite.bitmap.blt(POKERUS_ICON_X, POKERUS_ICON_Y, @pokerus.bitmap, Rect.new(0, 16, 16, 16))
            end
          end
        # Draw gender symbol
        if @pokemon.male?
          textpos.push([_INTL("♂"), GENDER_TEXT_X, GENDER_TEXT_Y, 0, GENDER_MALE_COLOR, outlineColor, true, Graphics.width])
        elsif @pokemon.female?
          textpos.push([_INTL("♀"), GENDER_TEXT_X, GENDER_TEXT_Y, 0, GENDER_FEMALE_COLOR, outlineColor, true, Graphics.width])
        end
        # Draw shiny icon
        if @pokemon.shiny? && BagScreenWiInParty::SHINYICON == true
          pbDrawImagePositions(@overlaysprite.bitmap,
                               [["Graphics/UI/Bag Screen with Party/shiny", SHINY_ICON_X, SHINY_ICON_Y, 0, 0, 16, 16]])
        end
      end
      pbDrawTextPositions(@overlaysprite.bitmap, textpos)
      # Draw level text
      if !@pokemon.egg?
        pbDrawImagePositions(@overlaysprite.bitmap,
                             [["Graphics/UI/Bag Screen with Party/overlay_lv", LEVEL_OVERLAY_X, LEVEL_OVERLAY_Y, 0, 0, 22, 14]])
        pbSetSmallFont(@overlaysprite.bitmap)
        pbDrawTextPositions(@overlaysprite.bitmap,
                            [[@pokemon.level.to_s, LEVEL_TEXT_X, LEVEL_TEXT_Y, 0, baseColor, outlineColor, true, Graphics.width]])
      end
      # Draw annotation text
      if @text && @text.length > 0
        pbSetSystemFont(@overlaysprite.bitmap)
        pbSetSmallFont(@overlaysprite.bitmap)
        if @text_color
          pbDrawTextPositions(@overlaysprite.bitmap,
                              [[@text,ANNOTATION_TEXT_X,ANNOTATION_TEXT_Y,2,ANNOTATION_GRAY_COLOR,ANNOTATION_SHADOW_COLOR, true, Graphics.width]])
        elsif @text_color == false
          pbDrawTextPositions(@overlaysprite.bitmap,[
                              [@text,ANNOTATION_TEXT_X,ANNOTATION_TEXT_Y,2,baseColor,ANNOTATION_LIGHT_SHADOW_COLOR,true,Graphics.width]])
        else
          pbDrawTextPositions(@overlaysprite.bitmap,[
                              [@text,ANNOTATION_TEXT_X,ANNOTATION_TEXT_Y,2,baseColor,TEXT_SHADOW_COLOR,true,Graphics.width]])
        end
      end
    end
    @refreshing = false
  end

  def update
    super
    @panelbgsprite.update if @panelbgsprite && !@panelbgsprite.disposed?
    @hpbgsprite.update if @hpbgsprite && !@hpbgsprite.disposed?
    @pkmnsprite.update if @pkmnsprite && !@pkmnsprite.disposed?
    @helditemsprite.update if @helditemsprite && !@helditemsprite.disposed?
  end
end

#===============================================================================
# Bag visuals
#===============================================================================
class PokemonBag_Scene
