  def pbUpdate
    pbUpdateSpriteHash(@sprites)
    @sprites["panorama"].x  = 0 if @sprites["panorama"].x == PANORAMA_STOP_X
    @sprites["panorama"].x -= PANORAMA_SCROLL_SPEED if BagScreenWiInParty::PANORAMA == true
  end

  def pbStartScene(bag, party = $player.party, choosing = false, filterproc = nil, resetpocket = true)
    @viewport   = Viewport.new(0, 0, Graphics.width, Graphics.height)
    @viewport.z = 99999
    @bag        = bag
    @choosing   = choosing
    @filterproc = filterproc
    @party      = party
    
    pbRefreshFilter
    lastpocket = @bag.last_viewed_pocket
    numfilledpockets = @bag.pockets.length - 1
    if @choosing
      numfilledpockets = 0
      if @filterlist.nil?
        (1...@bag.pockets.length).each do |i|
          numfilledpockets += 1 if @bag.pockets[i].length > 0
        end
      else
        (1...@bag.pockets.length).each do |i|
          numfilledpockets += 1 if @filterlist[i].length > 0
        end
      end
      lastpocket = (resetpocket) ? 1 : @bag.last_viewed_pocket
      if (@filterlist && @filterlist[lastpocket].length == 0) ||
         (!@filterlist && @bag.pockets[lastpocket].length == 0)
        (1...@bag.pockets.length).each do |i|
          if @filterlist && @filterlist[i].length > 0
            lastpocket = i
            break
          elsif !@filterlist && @bag.pockets[i].length > 0
            lastpocket = i
            break
          end
        end
      end
    end
    @bag.last_viewed_pocket = lastpocket
    
    @sliderbitmap = AnimatedBitmap.new(_INTL("Graphics/UI/Bag Screen with Party/icon_slider"))
    @pocketbitmap = AnimatedBitmap.new(_INTL("Graphics/UI/Bag Screen with Party/icon_pocket"))
    
    @sprites = {}
    @sprites["background"] = IconSprite.new(0, 0, @viewport)
    @sprites["background"].setBitmap("Graphics/UI/Bag Screen with Party/bg")
    @sprites["gradient"] = IconSprite.new(0, 0, @viewport)
    @sprites["gradient"].setBitmap("Graphics/UI/Bag Screen with Party/grad")
    @sprites["panorama"] = IconSprite.new(0, 0, @viewport)
    @sprites["panorama"].setBitmap("Graphics/UI/Bag Screen with Party/panorama")
    
    if BagScreenWiInParty::BGSTYLE == 1 # BW Style
      if $player.female?
        @sprites["background"].color = BG_COLOR_FEMALE_BG
        @sprites["gradient"].color = BG_COLOR_FEMALE_GRAD
        @sprites["panorama"].color = BG_COLOR_FEMALE_PAN
      else
        @sprites["background"].color = BG_COLOR_MALE_BG
        @sprites["gradient"].color = BG_COLOR_MALE_GRAD
        @sprites["panorama"].color = BG_COLOR_MALE_PAN
      end
    elsif BagScreenWiInParty::BGSTYLE == 2 # HGSS Style
      pbPocketColor
    end
    @sprites["ui1"] = IconSprite.new(0, 0, @viewport)
    @sprites["ui1"].setBitmap("Graphics/UI/Bag Screen with Party/ui1")
    @sprites["ui2"] = IconSprite.new(0, 0, @viewport)
    @sprites["ui2"].setBitmap("Graphics/UI/Bag Screen with Party/ui2")
    
    for i in 0...Settings::MAX_PARTY_SIZE
      if @party[i]
        @sprites["pokemon#{i}"] = PokemonBagPartyPanel.new(@party[i], i, @viewport)
      else
        @sprites["pokemon#{i}"] = PokemonBagPartyBlankPanel.new(@party[i], i, @viewport)
      end
    end
    
    @sprites["overlay"] = BitmapSprite.new(Graphics.width, Graphics.height, @viewport)
    @sprites["overlay_aux"] = BitmapSprite.new(Graphics.width, Graphics.height, @viewport)
    pbSetSystemFont(@sprites["overlay"].bitmap)
    
    @sprites["pocketicon"] = BitmapSprite.new(POCKET_ICON_BITMAP_WIDTH, POCKET_ICON_BITMAP_HEIGHT, @viewport)
    @sprites["pocketicon"].x = POCKET_ICON_X
    @sprites["pocketicon"].y = POCKET_ICON_Y
    @sprites["currentpocket"] = IconSprite.new(0, 0, @viewport)
    @sprites["currentpocket"].setBitmap("Graphics/UI/Bag Screen with Party/icon_pocket")
    @sprites["currentpocket"].x = CURRENT_POCKET_X
    @sprites["currentpocket"].y = CURRENT_POCKET_Y
    @sprites["currentpocket"].src_rect = Rect.new(0, 0, CURRENT_POCKET_ICON_SIZE, CURRENT_POCKET_ICON_SIZE)
    
    @sprites["itemlist"] = Window_PokemonBag.new(@bag, @filterlist, lastpocket, ITEM_LIST_X, ITEM_LIST_Y, ITEM_LIST_WIDTH, ITEM_LIST_HEIGHT_BASE + ITEMSVISIBLE * 32)
    @sprites["itemlist"].viewport    = @viewport
    @sprites["itemlist"].pocket      = lastpocket
    @sprites["itemlist"].index       = @bag.last_viewed_index(lastpocket)
    @sprites["itemlist"].baseColor   = ITEMLISTBASECOLOR
    @sprites["itemlist"].shadowColor = ITEMLISTSHADOWCOLOR
    @sprites["itemicon"] = ItemIconSprite.new(ITEM_ICON_X, Graphics.height - ITEM_ICON_Y_FROM_BOTTOM, nil, @viewport)
    @sprites["itemtext"] = Window_UnformattedTextPokemon.newWithSize(
      "", ITEM_TEXT_X, ITEM_TEXT_Y, Graphics.width - ITEM_TEXT_WIDTH_OFFSET, ITEM_TEXT_HEIGHT, @viewport
    )
    @sprites["itemtext"].baseColor   = ITEMTEXTBASECOLOR
    @sprites["itemtext"].shadowColor = ITEMTEXTSHADOWCOLOR
    @sprites["itemtext"].visible     = true
    @sprites["itemtext"].windowskin  = nil
    @sprites["helpwindow"] = Window_UnformattedTextPokemon.new("")
    @sprites["helpwindow"].visible  = false
    @sprites["helpwindow"].viewport = @viewport
    pbBottomLeftLines(@sprites["helpwindow"], 1)
    @sprites["msgwindow"] = Window_AdvancedTextPokemon.new("")
    @sprites["msgwindow"].visible  = false
    @sprites["msgwindow"].viewport = @viewport
    @sprites["msgwindow"].letterbyletter = true
    pbBottomLeftLines(@sprites["msgwindow"], 2)
    
    ## Dibujar textos de Ordenar y Buscar
    overlay_aux = @sprites["overlay_aux"].bitmap
    pbSetTinyFont(overlay_aux)
    pbDrawTextPositions(
      overlay_aux,
      [[_INTL("Z: Ordenar"), SORT_TEXT_X, SORT_TEXT_Y, nil, POCKETNAMEBASECOLOR, POCKETNAMEOUTLINECOLOR, :outline, Graphics.width],
       [_INTL("D: Buscar"), SEARCH_TEXT_X, SEARCH_TEXT_Y, nil, POCKETNAMEBASECOLOR, POCKETNAMEOUTLINECOLOR, :outline, Graphics.width]]
    )
    pbUpdateAnnotation
    pbDeactivateWindows(@sprites)
    pbRefresh
    pbFadeInAndShow(@sprites)
    $game_temp.bag_scene = self if $bag.has?(:EGGHATCHER)
  end

  def pbPocketColor
    case @bag.last_viewed_pocket
    when 1
      @sprites["background"].color = POCKET_1_BG
      @sprites["gradient"].color = POCKET_1_GRAD
      @sprites["panorama"].color = POCKET_1_PAN
    when 2
      @sprites["background"].color = POCKET_2_BG
      @sprites["gradient"].color = POCKET_2_GRAD
      @sprites["panorama"].color = POCKET_2_PAN
    when 3
      @sprites["background"].color = POCKET_3_BG
      @sprites["gradient"].color = POCKET_3_GRAD
      @sprites["panorama"].color = POCKET_3_PAN
    when 4
      @sprites["background"].color = POCKET_4_BG
      @sprites["gradient"].color = POCKET_4_GRAD
      @sprites["panorama"].color = POCKET_4_PAN
    when 5
      @sprites["background"].color = POCKET_5_BG
      @sprites["gradient"].color = POCKET_5_GRAD
      @sprites["panorama"].color = POCKET_5_PAN
    when 6
      @sprites["background"].color = POCKET_6_BG
      @sprites["gradient"].color = POCKET_6_GRAD
      @sprites["panorama"].color = POCKET_6_PAN
    when 7
      @sprites["background"].color = POCKET_7_BG
      @sprites["gradient"].color = POCKET_7_GRAD
      @sprites["panorama"].color = POCKET_7_PAN
    when 8
      @sprites["background"].color = POCKET_8_BG
      @sprites["gradient"].color = POCKET_8_GRAD
      @sprites["panorama"].color = POCKET_8_PAN
    end
  end
  
  def pbFadeOutScene
    @oldsprites = pbFadeOutAndHide(@sprites)
    @oldtext = []
    for i in 0...Settings::MAX_PARTY_SIZE
      @oldtext.push(@sprites["pokemon#{i}"].text)
      @sprites["pokemon#{i}"].dispose
    end
  end
  
  def pbFadeInScene
    for i in 0...Settings::MAX_PARTY_SIZE
      if @party[i]
        @sprites["pokemon#{i}"] = PokemonBagPartyPanel.new(@party[i], i, @viewport)
      else
        @sprites["pokemon#{i}"] = PokemonBagPartyBlankPanel.new(@party[i], i, @viewport)
      end
      @sprites["pokemon#{i}"].text = @oldtext[i]
    end
    @oldtext = nil
    pbFadeInAndShow(@sprites, @oldsprites)
    @oldsprites = nil
  end

  def pbEndScene
    pbFadeOutAndHide(@sprites) if !@oldsprites
    @oldsprites = nil
    dispose
  end

  def dispose
    pbDisposeSpriteHash(@sprites)
    @sliderbitmap.dispose
    @pocketbitmap.dispose
    @viewport.dispose
  end

  def pbDisplay(text, brief = false)
    @sprites["msgwindow"].text    = text
    @sprites["msgwindow"].visible = true
    pbPlayDecisionSE
    loop do
      Graphics.update
      Input.update
      pbUpdate
      if @sprites["msgwindow"].busy?
        if Input.trigger?(Input::USE)
          pbPlayDecisionSE if @sprites["msgwindow"].pausing?
          @sprites["msgwindow"].resume
        end
      elsif Input.trigger?(Input::BACK) || Input.trigger?(Input::USE)
        break
      end
    end
    @sprites["msgwindow"].visible = false
  end

  def update
    pbUpdateSpriteHash(@sprites)
  end
  
  def pbConfirm(msg)
    UIHelper.pbConfirm(@sprites["msgwindow"], msg) { pbUpdate }
  end

  def pbChooseNumber(helptext, maximum, initnum = 1)
    return UIHelper.pbChooseNumber(@sprites["helpwindow"], helptext, maximum, initnum) { pbUpdate }
  end

  def pbShowCommands(helptext, commands, index = 0)
    return UIHelper.pbShowCommands(@sprites["helpwindow"], helptext, commands, index) { pbUpdate }
  end

  def pbRefresh
    # Draw the pocket icons
    pocketX  = []; incrementX = 0 # Fixes pockets' X coordinates
    @bag.pockets.length.times do |i|
      break if pocketX.length == @bag.pockets.length
      pocketX.push(incrementX)
      incrementX += POCKET_ANIMATION_OFFSET if i.odd?
    end
    pocketAcc = @sprites["itemlist"].pocket - 1 # Current pocket
    @sprites["pocketicon"].bitmap.clear
    (1...@bag.pockets.length).each do |i|
      pocketValue = i - 1
      @sprites["pocketicon"].bitmap.blt(
        (i - 1) * POCKET_ICON_WIDTH + pocketX[pocketValue], (i % 2) * POCKET_ICON_HEIGHT, @pocketbitmap.bitmap,
        Rect.new((i - 1) * POCKET_ICON_SPRITE_SIZE, 0, POCKET_ICON_SPRITE_SIZE, POCKET_ICON_SPRITE_SIZE)) if pocketValue != pocketAcc # Unblocked icons
    end
    if @choosing && @filterlist
      (1...@bag.pockets.length).each do |i|
        next if @filterlist[i].length > 0
        pocketValue = i - 1
        @sprites["pocketicon"].bitmap.blt(
          (i - 1) * POCKET_ICON_WIDTH + pocketX[pocketValue], (i % 2) * POCKET_ICON_HEIGHT, @pocketbitmap.bitmap,
          Rect.new((i - 1) * POCKET_ICON_SPRITE_SIZE, 56, POCKET_ICON_SPRITE_SIZE, POCKET_ICON_SPRITE_SIZE)) # Blocked icons
      end
    end
    @sprites["currentpocket"].x = CURRENT_POCKET_X + ((pocketAcc) * POCKET_ICON_WIDTH) + pocketX[pocketAcc]
    @sprites["currentpocket"].y = CURRENT_POCKET_Y - (((pocketAcc) % 2) * POCKET_ICON_HEIGHT)
    @sprites["currentpocket"].src_rect = Rect.new((pocketAcc) * POCKET_ICON_SPRITE_SIZE, POCKET_ICON_SPRITE_SIZE, POCKET_ICON_SPRITE_SIZE, POCKET_ICON_SPRITE_SIZE) # Current pocket icon
    # Refresh stuff
    @sprites["itemlist"].refresh
    pbRefreshIndexChanged
    pbRefreshParty
    pbPocketColor if BagScreenWiInParty::BGSTYLE == 2
  end
  
  def pbRefreshParty
    for i in 0...Settings::MAX_PARTY_SIZE
      if @party[i]
        @sprites["pokemon#{i}"].pokemon = @party[i]
      else
      end
    end
  end
  
  def pbRefreshIndexChanged
    itemlist = @sprites["itemlist"]
    overlay = @sprites["overlay"].bitmap
    overlay.clear
    # Draw the pocket name
    pbDrawTextPositions(
      overlay,
      [[PokemonBag.pocket_names[@bag.last_viewed_pocket - 1], POCKET_NAME_X, POCKET_NAME_Y, :center, POCKETNAMEBASECOLOR, POCKETNAMEOUTLINECOLOR, true, Graphics.width]]
    )
    # Draw slider arrows
    showslider = false
    if itemlist.top_row > 0
      overlay.blt(SLIDER_TOP_X, SLIDER_TOP_Y, @sliderbitmap.bitmap, Rect.new(0, 0, 36, 38))
      showslider = true
    end
    if itemlist.top_item + itemlist.page_item_max < itemlist.itemCount
      overlay.blt(SLIDER_BOTTOM_X, SLIDER_BOTTOM_Y, @sliderbitmap.bitmap, Rect.new(0, 38, 36, 38))
      showslider = true
    end
    # Draw slider box
    if showslider
      sliderheight = SLIDER_HEIGHT
      boxheight = (sliderheight * itemlist.page_row_max / itemlist.row_max).floor
      boxheight += [(sliderheight - boxheight) / 2, sliderheight / 6].min
      boxheight = [boxheight.floor, SLIDER_MIN_BOX_HEIGHT].max
      y = SLIDER_Y_START
      y += ((sliderheight - boxheight) * itemlist.top_row / (itemlist.row_max - itemlist.page_row_max)).floor
      overlay.blt(SLIDER_BOX_X, y, @sliderbitmap.bitmap, Rect.new(36, 0, 36, 4))
      i = 0
      while i * 16 < boxheight - 4 - 18
        height = [boxheight - 4 - 18 - (i * 16), 16].min
        overlay.blt(SLIDER_BOX_X, y + 4 + (i * 16), @sliderbitmap.bitmap, Rect.new(36, 4, 36, height))
        i += 1
      end
      overlay.blt(SLIDER_BOX_X, y + boxheight - 18, @sliderbitmap.bitmap, Rect.new(36, 20, 36, 18))
    end
    # Set the selected item's icon
    @sprites["itemicon"].item = itemlist.item
    # Set the selected item's description
    @sprites["itemtext"].text =
      (itemlist.item) ? GameData::Item.get(itemlist.item).description : _INTL("Cerrar Mochila.")
  end

  def pbRefreshFilter
    @filterlist = nil
    return if !@choosing
    return if @filterproc.nil?
    @filterlist = []
    (1...@bag.pockets.length).each do |i|
      @filterlist[i] = []
      @bag.pockets[i].length.times do |j|
        @filterlist[i].push(j) if @filterproc.call(@bag.pockets[i][j][0])
      end
    end
  end


  def pbHardRefresh
    oldtext      = []
    lastselected = -1
    for i in 0...Settings::MAX_PARTY_SIZE
      if @sprites["pokemon#{i}"].respond_to?(:text)
        oldtext.push(@sprites["pokemon#{i}"].text)
      end
      lastselected = i if @sprites["pokemon#{i}"]&.selected
      @sprites["pokemon#{i}"]&.dispose
    end
    lastselected = @party.length - 1 if lastselected >= @party.length
    lastselected = 0 if lastselected < 0
    for i in 0...Settings::MAX_PARTY_SIZE
      if @party[i]
        @sprites["pokemon#{i}"] = PokemonBagPartyPanel.new(@party[i], i, @viewport)
      else
        @sprites["pokemon#{i}"] = PokemonBagPartyBlankPanel.new(@party[i], i, @viewport)
      end
      @sprites["pokemon#{i}"].text = oldtext[i] if oldtext[i]
    end
    pbSelect(lastselected)
  end

  def pbRefreshSingle(i)
    sprite = @sprites["pokemon#{i}"]
    if sprite
      if sprite.is_a?(PokemonBagPartyPanel)
        sprite.pokemon = sprite.pokemon
      else
        sprite.refresh
      end
    end
  end
  
  def pbUpdateAnnotation
    itemwindow = @sprites["itemlist"]
    item       = itemwindow.item
    itm        = GameData::Item.get(item) if item
    if @bag.last_viewed_pocket == 1 && item #Items Pocket
      annotations = nil
      annotations = []
      color_annotations=[]
      if itm.is_evolution_stone?
        for i in $player.party
          elig = i.check_evolution_on_use_item(itm)
          annotations.push((elig) ? _INTL("APTO") : _INTL("NO APTO"))
          color_annotations.push((elig) ? nil : true)
        end
      else
        for i in 0...Settings::MAX_PARTY_SIZE
          @sprites["pokemon#{i}"].text = annotations[i] if  annotations
          @sprites["pokemon#{i}"].text_color = color_annotations[i] if annotations
        end
      end
      for i in 0...Settings::MAX_PARTY_SIZE
        @sprites["pokemon#{i}"].text = annotations[i] if  annotations
        @sprites["pokemon#{i}"].text_color = color_annotations[i] if annotations


      end
    elsif @bag.last_viewed_pocket == 4 && item #TMs Pocket
      annotations = nil
      annotations = []
      color_annotations=[]
      if itm.is_machine?
        machine = itm.move
        move = GameData::Move.get(machine).id
        movelist = nil
        if movelist!=nil && movelist.is_a?(Array)
          for i in 0...movelist.length
            movelist[i] = GameData::Move.get(movelist[i]).id
          end
        end
        $player.party.each_with_index do |pkmn, i|
          if pkmn.egg?
            annotations[i] = _INTL("NO APTO")
            color_annotations[i] = true
          elsif pkmn.hasMove?(move)
            annotations[i] = _INTL("APRENDIDO")
            color_annotations[i] = false
          else
            species = pkmn.species
            if movelist && movelist.any? { |j| j == species }
              # Checked data from movelist given in parameter
              annotations[i] = _INTL("APTO")
              color_annotations[i] = nil
            elsif pkmn.compatible_with_move?(move)
              # Checked data from Pokémon's tutor moves in pokemon.txt
              annotations[i] = _INTL("APTO")
              color_annotations[i] = nil
            else
              annotations[i] = _INTL("NO APTO")
              color_annotations[i] = true
            end
          end
        end
      else
        for i in @party
          annotations.push((elig) ? _INTL("APTO") : _INTL("NO APTO"))
          color_annotations.push((elig) ? nil : true)
        end
      end
      for i in 0...Settings::MAX_PARTY_SIZE
        @sprites["pokemon#{i}"].text = annotations[i] if annotations
        @sprites["pokemon#{i}"].text_color = color_annotations[i] if annotations
      end
    else #Others, only show HP
      for i in 0...Settings::MAX_PARTY_SIZE
        @sprites["pokemon#{i}"].text = nil if @sprites["pokemon#{i}"].text 
        @sprites["pokemon#{i}"].text_color = color_annotations[i] if @sprites["pokemon#{i}"].text 
      end
    end
  end
      
  # Called when the item screen wants an item to be chosen from the screen
  def pbChooseItem
    @sprites["helpwindow"].visible = false
    itemwindow = @sprites["itemlist"]
    thispocket = @bag.pockets[itemwindow.pocket]
    swapinitialpos = -1
    pbActivateWindow(@sprites, "itemlist") {
      loop do
        oldindex = itemwindow.index
        Graphics.update
        Input.update
        pbUpdate
        pbUpdateAnnotation
        if itemwindow.sorting && itemwindow.index >= thispocket.length
          itemwindow.index = (oldindex == thispocket.length - 1) ? 0 : thispocket.length - 1
        end
        if itemwindow.index != oldindex
          # Move the item being switched
          if itemwindow.sorting
            thispocket.insert(itemwindow.index, thispocket.delete_at(oldindex))
          end
          # Update selected item for current pocket
          @bag.set_last_viewed_index(itemwindow.pocket, itemwindow.index)
          pbRefresh
        end
        if itemwindow.sorting
          if Input.trigger?(Input::ACTION) ||
             Input.trigger?(Input::USE)
            itemwindow.sorting = false
            pbPlayDecisionSE
            pbRefresh
          elsif Input.trigger?(Input::BACK)
            thispocket.insert(swapinitialpos, thispocket.delete_at(itemwindow.index))
            itemwindow.index = swapinitialpos
            itemwindow.sorting = false
            pbPlayCancelSE
            pbRefresh
          end
        else
          # Plays SE when scrolling the item list
          if Input.repeat?(Input::UP) && thispocket.length   > 0 || 
             Input.repeat?(Input::DOWN) && thispocket.length > 0
            pbSEPlay("GUI bag cursor") if itemwindow.index != oldindex
          end
          # Change pockets
          if Input.trigger?(Input::LEFT)
            newpocket = itemwindow.pocket
            loop do
              newpocket = (newpocket == 1) ? PokemonBag.pocket_count : newpocket - 1
              break if !@choosing || newpocket == itemwindow.pocket
              if @filterlist
                break if @filterlist[newpocket].length > 0
              elsif @bag.pockets[newpocket].length > 0
                break
              end
            end
            if itemwindow.pocket != newpocket
              itemwindow.pocket = newpocket
              @bag.last_viewed_pocket = itemwindow.pocket
              thispocket = @bag.pockets[itemwindow.pocket]
              pbRefresh
              pbSEPlay("GUI bag pocket")
              @sprites["currentpocket"].x -= POCKET_ANIMATION_OFFSET
              pbWait(0.1) {pbUpdate}
              @sprites["currentpocket"].x += POCKET_ANIMATION_OFFSET
            end
          elsif Input.trigger?(Input::RIGHT)
            newpocket = itemwindow.pocket
            loop do
              newpocket = (newpocket == PokemonBag.pocket_count) ? 1 : newpocket + 1
              break if !@choosing || newpocket == itemwindow.pocket
              if @filterlist
                break if @filterlist[newpocket].length > 0
              elsif @bag.pockets[newpocket].length > 0
                break
              end
            end
            if itemwindow.pocket != newpocket
              itemwindow.pocket = newpocket
              @bag.last_viewed_pocket = itemwindow.pocket
              thispocket = @bag.pockets[itemwindow.pocket]
              pbRefresh
              pbSEPlay("GUI bag pocket")
              @sprites["currentpocket"].x += POCKET_ANIMATION_OFFSET
              pbWait(0.1) {pbUpdate}
              @sprites["currentpocket"].x -= POCKET_ANIMATION_OFFSET
            end
          elsif Input.trigger?(Input::SPECIAL)   # Search items
            BagSearcher.new(thispocket, itemwindow, self)
          elsif Input.trigger?(Input::ACTION) # Sort Items
            sort_keys = @bag.last_viewed_pocket == 4 ? [:number, :name, :type] : [:type, :name]
            sort_commands = @bag.last_viewed_pocket == 4 ? [_INTL("Número"),_INTL("Alfabéticamente"), _INTL("Tipo")] : [_INTL("Categoría"), _INTL("Alfabéticamente")]
            option = pbMessage(_INTL("¿Cómo deseas ordenar tus objetos?"), sort_commands, -1)
            if option != -1 && option < sort_keys.length
              sorted_pocket = sort_pocket(sort_keys[option], thispocket, itemwindow.pocket)
              if sorted_pocket && !sorted_pocket.empty?
                @bag.pockets[itemwindow.pocket] = sorted_pocket
                thispocket = @bag.pockets[itemwindow.pocket]
                # Refresh filter list if filtering is active
                if @filterlist
                  pbRefreshFilter
                  itemwindow.filterlist = @filterlist
                end
                pbPlayDecisionSE
                pbRefresh
              end
            end
          elsif Input.trigger?(Input::BACK)   # Cancel the item screen
            pbPlayCloseMenuSE
            return nil
          elsif Input.trigger?(Input::USE)   # Choose selected item
            (itemwindow.item) ? pbPlayDecisionSE : pbPlayCloseMenuSE
            return itemwindow.item
          end
        end
      end
    }
  end

  def sort_pocket(sort_method, pocket, pocket_number = nil)
    # Separar favoritos y no favoritos
    favourites_in_pocket = pocket.select { |item| @bag.favourite?(item[0]) }
    not_favs = pocket - favourites_in_pocket
    # Ordenar favoritos y no favoritos según el método elegido
    sorted_favs = []
    sorted_non_favs = []
    case sort_method
    when :number
      tms = []
      trs = []
      hms = []
      sorted_non_favs = not_favs.sort_by { |item| 
        natural_sort_key(GameData::Item.get(item[0]).name.downcase) 
      }
      sorted_non_favs.each do |item|
        item_data = GameData::Item.get(item[0])
        if item_data.is_TM?
          tms << item
        elsif item_data.is_TR?
          trs << item
        elsif item_data.is_HM?
          hms << item
        end
      end
      sorted_non_favs = tms + trs + hms
      sorted_favs = favourites_in_pocket.sort_by { |item| 
        natural_sort_key(GameData::Item.get(item[0]).name.downcase) 
      }
    when :name
      if @bag.last_viewed_pocket == 4
        sorted_favs = favourites_in_pocket.sort_by { |item| 
          natural_sort_key(GameData::Move.get(GameData::Item.get(item[0]).move).name.downcase) 
        }
        sorted_non_favs = not_favs.sort_by { |item| 
          natural_sort_key(GameData::Move.get(GameData::Item.get(item[0]).move).name.downcase) 
        }
      else
        sorted_favs = favourites_in_pocket.sort_by { |item| 
          natural_sort_key(GameData::Item.get(item[0]).name.downcase) 
        }
        sorted_non_favs = not_favs.sort_by { |item| 
          natural_sort_key(GameData::Item.get(item[0]).name.downcase) 
        }
      end
    when :type
      if @bag.last_viewed_pocket == 4
        sorted_favs = favourites_in_pocket.sort_by { |item| 
          GameData::Move.get(GameData::Item.get(item[0]).move).type 
        }
        sorted_non_favs = not_favs.sort_by { |item| 
          GameData::Move.get(GameData::Item.get(item[0]).move).type 
        }
      else
        order_array = GameData::Item.from_pocket(pocket_number)
        sorted_favs = favourites_in_pocket.sort_by { |item| order_array.index(item[0]) }
        sorted_non_favs = not_favs.sort_by { |item| order_array.index(item[0]) }
      end
    end
    # Combinar favoritos y no favoritos
    sorted_pocket = sorted_favs + sorted_non_favs
    sorted_pocket
  end

  def pbSetHelpText(helptext)
    helpwindow = @sprites["helpwindow"]
    pbBottomLeftLines(helpwindow, 1)
    helpwindow.text = helptext
    helpwindow.width = HELP_WINDOW_WIDTH
    helpwindow.visible = true
  end

  def pbChangeSelection(key,currentsel)
    numsprites = @party.length - 1
    case key
    when Input::LEFT
      begin
        currentsel -= 1
      end while currentsel >= 0 && currentsel < @party.length && !@party[currentsel]
      if currentsel >= @party.length && currentsel < Settings::MAX_PARTY_SIZE
        currentsel = @party.length - 1
      end
      currentsel = numsprites if currentsel < 0 || currentsel > numsprites
    when Input::RIGHT
      begin
        currentsel += 1
      end while currentsel < @party.length && !@party[currentsel]
      currentsel = 0 if currentsel == @party.length
    when Input::UP
      if currentsel > numsprites
        currentsel -= 1
        while currentsel > 0 && currentsel < numsprites && !@party[currentsel]
          currentsel -= 1
        end 
      else
        begin
          currentsel -= 2
        end while currentsel > 0 && !@party[currentsel]
      end
      if currentsel > numsprites && currentsel < numsprites
        currentsel = numsprites
      end
      currentsel = numsprites if currentsel < 0
    when Input::DOWN
      if currentsel >= Settings::MAX_PARTY_SIZE - 1
        currentsel += 1
      else
        currentsel += 2
        currentsel = Settings::MAX_PARTY_SIZE if currentsel < Settings::MAX_PARTY_SIZE && !@party[currentsel]
      end
      if currentsel >= @party.length && currentsel < Settings::MAX_PARTY_SIZE
        currentsel = Settings::MAX_PARTY_SIZE
      elsif currentsel > numsprites
        currentsel = 0
      end
    end
    return currentsel
  end
  
  def pbChangeCursor(number)
    # 1 for using/giving an item to a Pokémon; 2 for exiting; 3 for interacting
    itemwindow = @sprites["itemlist"]
    if number == 1
      itemwindow.party1sel = true
    elsif number == 2
      itemwindow.party1sel = false
      itemwindow.party2sel = false
    elsif number == 3
      itemwindow.party2sel = true
    end
    pbRefresh
  end
  
  def pbChoosePoke(option, switching = false)
    # 0 to choose a Pokémon; 1 to hold an item; 2 to use an item; 3 to interact; 4 to switch party items
    for i in 0...Settings::MAX_PARTY_SIZE
      @sprites["pokemon#{i}"].preselected = (switching && i == @activecmd)
      @sprites["pokemon#{i}"].switching   = switching
    end
    @sprites["pokemon#{@activecmd}"].selected = false if switching
    @activecmd = 0
    for i in 0...Settings::MAX_PARTY_SIZE
      @sprites["pokemon#{i}"].selected = (i == @activecmd)
    end
    itemwindow = @sprites["itemlist"]
    item = itemwindow.item
    if option == 3 || option == 4
      pbChangeCursor(3)
    else
      pbChangeCursor(1)
    end
    loop do
      Graphics.update
      Input.update
      pbUpdate
      oldsel = @activecmd
      key = -1
      key = Input::DOWN if Input.repeat?(Input::DOWN) && @party.length > 2
      key = Input::RIGHT if Input.repeat?(Input::RIGHT)
      key = Input::LEFT if Input.repeat?(Input::LEFT)
      key = Input::UP if Input.repeat?(Input::UP) && @party.length > 2
      if key >= 0 && @party.length > 1
        @activecmd = pbChangeSelection(key, @activecmd)
      end
      if @activecmd != oldsel   # Changing selection
        pbPlayCursorSE
        numsprites = Settings::MAX_PARTY_SIZE
        for i in 0...numsprites
          @sprites["pokemon#{i}"].selected = (i == @activecmd)
        end
      end
      if Input.trigger?(Input::USE)
        pkmn = @party[@activecmd]
        if option == 0 # Choose
          return @activecmd
        elsif option == 1 # Hold
          if @activecmd >= 0
            ret = pbGiveItemToPokemon(item, @party[@activecmd], self, @activecmd)
            pbChangeCursor(2)
            @sprites["pokemon#{@activecmd}"].selected = false
            break
          end
        elsif option == 2 # Use
          ret = pbBagUseItem(@bag, item, PokemonBagScreen, self, @activecmd)
          pbRefresh; pbUpdateAnnotation
          if !$bag.has?(item)
            @sprites["pokemon#{@activecmd}"].selected = false
            pbChangeCursor(2)
            break
          end
        elsif option == 3 # Interaction
          pbPlayDecisionSE
          loop do
            cmdSummary     = -1
            cmdTake        = -1 
            cmdMove        = -1
            commands = []
            # Generate command list
            commands[cmdSummary = commands.length]       = _INTL("Datos")
            commands[cmdTake = commands.length]          = _INTL("Coger Objeto") if pkmn.hasItem?
            commands[cmdMove = commands.length]          = _INTL("Mover Objeto") if pkmn.hasItem? && !GameData::Item.get(pkmn.item).is_mail?
            commands[commands.length]                    = _INTL("Cancelar")
            # Show commands generated above
            if pkmn.hasItem?
              item = pkmn.item
              itemname = item.name
              # = (itemname.starts_with_vowel?) ? "an" : "a"
              command = pbShowCommands(_INTL("{1} tiene equipado {2}.", pkmn.name, itemname), commands)
            else
              command = pbShowCommands(_INTL("Has elegido a {1}.", pkmn.name), commands)
            end
            if cmdSummary >= 0 && command == cmdSummary   # Summary
              pbSummary(@activecmd)
            elsif cmdTake >= 0 && command == cmdTake && pkmn.hasItem?  # Take item
              if pbTakeItemFromPokemon(pkmn, self)
                pbRefresh
              end
              break
            elsif cmdMove >= 0 && command == cmdMove && pkmn.hasItem? && !GameData::Item.get(pkmn.item).is_mail?  # Move item
              oldpkmn = pkmn
              loop do
                pbPreSelect(oldpkmn)
                newpkmn = pbChoosePoke(4, true)
                if newpkmn < 0
                  pbClearSwitching
                  break 
                end
                newpkmn = @party[newpkmn]
                if newpkmn == oldpkmn
                  pbClearSwitching
                  break 
                end
                if newpkmn.egg?
                  pbDisplay(_INTL("Los Huevos no pueden llevar objetos."))
                elsif !newpkmn.hasItem?
                  newpkmn.item = item
                  oldpkmn.item = nil
                  pbClearSwitching; pbRefresh
                  pbDisplay(_INTL("Has equipado {1} a {2}.", newpkmn.name, itemname))
                  break
                elsif GameData::Item.get(newpkmn.item).is_mail?
                  pbDisplay(_INTL("Debes quitarle la carta a {1} para equiparle un objeto.", newpkmn.name))
                else
                  newitem = newpkmn.item
                  newitemname = newitem.name
                  if newitem == :LEFTOVERS
                    pbDisplay(_INTL("{1} ya tiene equipado unos {2}.\1", newpkmn.name, newitemname))
                  elsif newitemname.starts_with_vowel?
                    pbDisplay(_INTL("{1} ya tiene equipado {2}.\1", newpkmn.name, newitemname))
                  else
                    pbDisplay(_INTL("{1} ya tiene equipado {2}.\1", newpkmn.name, newitemname))
                  end
                  if pbConfirm(_INTL("¿Quieres intercambiar los dos objetos?"))
                    newpkmn.item = item
                    oldpkmn.item = newitem
                    pbClearSwitching; pbRefresh
                    pbDisplay(_INTL("Has equipado {2} a {1}.", newpkmn.name, itemname))
                    pbDisplay(_INTL("Has equipado {2} a {1}.", oldpkmn.name, newitemname))
                  else
                    pbClearSwitching; pbRefresh
                  end
                  break
                end
              end
              break
            else
              break
            end
          end
        elsif option == 4 # Interaction for switching item
          return @activecmd
        end
      elsif Input.trigger?(Input::BACK)
        if option != 4
          pbSEPlay("GUI storage hide party panel")
          pbChangeCursor(2)
        else
          pbPlayCancelSE
        end
        if switching
          return -1
        elsif option == 0
          @sprites["pokemon#{@activecmd}"].selected = false
          return -1
        else
          @sprites["pokemon#{@activecmd}"].selected = false
          return
        end
      end
      break if ret == 2 && option == 2  # End screen
    end
  end
  
  def pbChoosePokemon(text = nil)
    # For fusing/unfusing Pokemon
    fusioncmd  = @activecmd
    @activecmd = 0
    for i in 0...Settings::MAX_PARTY_SIZE
      @sprites["pokemon#{i}"].selected = (i == @activecmd)
    end
    @sprites["pokemon#{fusioncmd}"].selected = true
    loop do
      Graphics.update
      Input.update
      pbUpdate
      oldsel = @activecmd
      key = -1
      key = Input::DOWN if Input.repeat?(Input::DOWN) && @party.length > 2
      key = Input::RIGHT if Input.repeat?(Input::RIGHT)
      key = Input::LEFT if Input.repeat?(Input::LEFT)
      key = Input::UP if Input.repeat?(Input::UP) && @party.length > 2
      if key >= 0 && @party.length > 1
        @activecmd = pbChangeSelection(key,@activecmd)
      end
      if @activecmd != oldsel   # Changing selection
        pbPlayCursorSE
        numsprites = Settings::MAX_PARTY_SIZE
        for i in 0...numsprites
          @sprites["pokemon#{i}"].selected = (i == @activecmd)
        end
        @sprites["pokemon#{fusioncmd}"].selected = true
      end
      if Input.trigger?(Input::USE)
        @sprites["pokemon#{fusioncmd}"].selected = false if fusioncmd != @activecmd
        return @activecmd
      elsif Input.trigger?(Input::BACK)
        pbPlayCancelSE
        @sprites["pokemon#{fusioncmd}"].selected = false if fusioncmd != @activecmd
        return -1
      end
    end
  end
  
  def pbSummary(pkmnid, inbattle=false)
    oldsprites = pbFadeOutAndHide(@sprites)
    scene = PokemonSummary_Scene.new
    screen = PokemonSummaryScreen.new(scene,inbattle)
    screen.pbStartScreen(@party,pkmnid)
    yield if block_given?
    pbFadeInAndShow(@sprites,oldsprites)
  end

  def pbSelect(item)
    @activecmd = item
    numsprites = Settings::MAX_PARTY_SIZE
    for i in 0...numsprites
      @sprites["pokemon#{i}"].selected = (i == @activecmd)
    end
  end
  
  def pbPreSelect(item)
    @othercmd = item
  end

  def pbClearSwitching
    for i in 0...Settings::MAX_PARTY_SIZE
      @sprites["pokemon#{i}"].preselected = false
      @sprites["pokemon#{i}"].switching   = false
    end
  end
  
  def pbChooseMove(pokemon, helptext, index = 0)
    movenames = []
    pokemon.moves.each do |i|
      next if !i || !i.id
      if i.total_pp <= 0
        movenames.push(_INTL("{1} (PP: ---)", i.name))
      else
        movenames.push(_INTL("{1} (PP: {2}/{3})", i.name, i.pp, i.total_pp))
      end
    end
    return pbShowCommands(helptext,movenames,index)
  end
end

#===============================================================================
# Bag mechanics
#===============================================================================
class PokemonBagScreen
  def initialize(scene, bag)
    @bag   = bag
    @scene = scene
  end

  def pbStartScreen
    @scene.pbStartScene(@bag, $player.party)
    item = nil
    loop do
      item = @scene.pbChooseItem
      break if !item
      itm = GameData::Item.get(item)
      cmdRead     = -1
      cmdUse      = -1
      cmdRegister = -1
      cmdFavourite = -1
      cmdGive     = -1
      cmdToss     = -1
      cmdDebug    = -1
      commands = []
      # Generate command list
      commands[cmdRead = commands.length]       = _INTL("Leer") if itm.is_mail?
      if ItemHandlers.hasOutHandler(item) || (itm.is_machine? && $player.party.length > 0)
        if ItemHandlers.hasUseText(item)
          commands[cmdUse = commands.length]    = ItemHandlers.getUseText(item)
        else
          commands[cmdUse = commands.length]    = _INTL("Usar")
        end
      end
      commands[cmdGive = commands.length]       = _INTL("Dar") if $player.pokemon_party.length > 0 && itm.can_hold?
      commands[cmdToss = commands.length]       = _INTL("Tirar") if !itm.is_important? || $DEBUG
      if @bag.registered?(item)
        commands[cmdRegister = commands.length] = _INTL("No regis.")
      elsif pbCanRegisterItem?(item)
        commands[cmdRegister = commands.length] = _INTL("Registrar")
      end
      if @bag.favourite?(item)
        commands[cmdFavourite = commands.length] = _INTL("No fav.")
      else
        commands[cmdFavourite = commands.length] = _INTL("Favorito")
      end
      commands[cmdDebug = commands.length]      = _INTL("Debug") if $DEBUG
      commands[commands.length]                 = _INTL("Cancelar")
      # Show commands generated above
      itemname = itm.name
      command = @scene.pbShowCommands(_INTL("Has seleccionado {1}.", itemname), commands)
      if cmdRead >= 0 && command == cmdRead   # Read mail
        pbFadeOutIn {
          pbDisplayMail(Mail.new(item, "", ""))
        }
      elsif cmdUse >= 0 && command == cmdUse   # Use item
        useType = itm.field_use
        # ret: 0 = Item wasn't used; 1 = Item used; 2 = Close Bag to use in field
        if useType == 1 # Consumables
          pbSEPlay("GUI storage show party panel")
          ret = @scene.pbChoosePoke(2, false)
        elsif useType == 3 || useType == 4 || useType == 5 # TM, HM and TR
          machine = itm.move
          movename = GameData::Move.get(machine).name
          pbMessage(_INTL("\\se[PC access]Has seleccionado {1}.\1", itm.name)) {@scene.pbUpdate}
          if pbConfirmMessage(_INTL("¿Quieres enseñarle {1} a un Pokémon?", movename)) {@scene.pbUpdate}
            pbSEPlay("GUI storage show party panel")
            ret = @scene.pbChoosePoke(2, false)
          end
        else
          ret = pbUseItem(@bag, item, @scene)
        end
        break if ret == 2   # End screen
        @scene.pbRefresh
        next
      elsif cmdGive >= 0 && command == cmdGive   # Give item to Pokémon
        if $player.pokemon_count == 0
          @scene.pbDisplay(_INTL("No hay Pokémon."))
        elsif itm.is_important?
          @scene.pbDisplay(_INTL("No se puede equipar {1}.", itm.portion_name))
        else
          @scene.pbChoosePoke(1, false)
        end
      elsif cmdToss >= 0 && command == cmdToss   # Toss item
        qty = @bag.quantity(item)
        if qty > 1
          helptext = _INTL("¿Qué cantidad de {1} tirar?", itm.portion_name_plural)
          qty = @scene.pbChooseNumber(helptext, qty)
        end
        if qty > 0
          itemname = (qty > 1) ? itm.portion_name_plural : itm.portion_name
          if pbConfirm(_INTL("¿Segur{1} que quieres tirar {2} {3}?",$player.female? ? 'a' : 'o', qty, itemname))
            pbDisplay(_INTL("Has tirado {1} {2}.", qty, itemname))
            qty.times { @bag.remove(item) }
            @scene.pbRefresh
          end
        end
      elsif cmdRegister >= 0 && command == cmdRegister   # Register item
        if @bag.registered?(item)
          @bag.unregister(item)
        else
          @bag.register(item)
        end
        @scene.pbRefresh
      elsif cmdFavourite >= 0 && command == cmdFavourite   # Favourite item
        if @bag.favourite?(item)
          @bag.unfavourite(item)
        else
          @bag.favourite(item)
        end
        @scene.pbRefresh
      elsif cmdDebug >= 0 && command == cmdDebug   # Debug
        command = 0
        loop do
          command = @scene.pbShowCommands(_INTL("¿Qué hacer con {1}?", itemname),
                                          [_INTL("Cambiar cantidad"),
                                           _INTL("Hacer Regalo Mist."),
                                           _INTL("Cancelar")], command)
          case command
          ### Cancel ###
          when -1, 2
            break
          ### Change quantity ###
          when 0
            qty = @bag.quantity(item)
            itemplural = itm.name_plural
            params = ChooseNumberParams.new
            params.setRange(0, Settings::BAG_MAX_PER_SLOT)
            params.setDefaultValue(qty)
            newqty = pbMessageChooseNumber(
              _INTL("Elige nueva cantidad de {1} (max. {2}).", itemplural, Settings::BAG_MAX_PER_SLOT), params
            ) { @scene.pbUpdate }
            if newqty > qty
              @bag.add(item, newqty - qty)
            elsif newqty < qty
              @bag.remove(item, qty - newqty)
            end
            @scene.pbRefresh
            break if newqty == 0
          ### Make Mystery Gift ###
          when 1
            pbCreateMysteryGift(1, item)
          end
        end
      end
    end
    ($game_temp.fly_destination) ? @scene.dispose : @scene.pbEndScene
    return item
  end

  def pbDisplay(text)
    @scene.pbDisplay(text)
  end

  def pbConfirm(text)
    return @scene.pbConfirm(text)
  end

  # UI logic for the item screen for choosing an item.
  def pbChooseItemScreen(proc = nil)
    oldlastpocket = @bag.last_viewed_pocket
    oldchoices = @bag.last_pocket_selections.clone
    $bag.reset_last_selections if proc
    @scene.pbStartScene(@bag, $player.party, true, proc)
    item = @scene.pbChooseItem
    @scene.pbEndScene
    @bag.last_viewed_pocket = oldlastpocket
    @bag.last_pocket_selections = oldchoices
    return item
  end

  # UI logic for withdrawing an item in the item storage screen.
  def pbWithdrawItemScreen
    if !$PokemonGlobal.pcItemStorage
      $PokemonGlobal.pcItemStorage = PCItemStorage.new
    end
    storage = $PokemonGlobal.pcItemStorage
    @scene.pbStartScene(storage)
    loop do
      item = @scene.pbChooseItem
      break if !item
      itm = GameData::Item.get(item)
      qty = storage.quantity(item)
      if qty > 1 && !itm.is_important?
        qty = @scene.pbChooseNumber(_INTL("¿Cuántos quieres tirar?"), qty)
      end
      next if qty <= 0
      if @bag.can_add?(item, qty)
        if !storage.remove(item, qty)
          raise "No se pueden tirar objetos del almacenamiento"
        end
        if !@bag.add(item, qty)
          raise "No se pueden sacar objetos del almacenamiento"
        end
        @scene.pbRefresh
        dispqty = (itm.is_important?) ? 1 : qty
        itemname = (dispqty > 1) ? itm.portion_name_plural : itm.portion_name
        pbDisplay(_INTL("Has sacado {1} {2}.", dispqty, itemname))
      else
        pbDisplay(_INTL("No tienes más hueco en la Mochila."))
      end
    end
    @scene.pbEndScene
  end

  # UI logic for depositing an item in the item storage screen.
  def pbDepositItemScreen
    @scene.pbStartScene(@bag,$player.party)
    if !$PokemonGlobal.pcItemStorage
      $PokemonGlobal.pcItemStorage = PCItemStorage.new
    end
    storage = $PokemonGlobal.pcItemStorage
    loop do
      item = @scene.pbChooseItem
      break if !item
      itm = GameData::Item.get(item)
      qty = @bag.quantity(item)
      if qty > 1 && !itm.is_important?
        qty = @scene.pbChooseNumber(_INTL("¿Cuántos quieres dejar?"), qty)
      end
      if qty > 0
        if storage.can_add?(item, qty)
          if !@bag.remove(item, qty)
            raise "No se pueden eliminar objetos de la Mochila"
          end
          if !storage.add(item, qty)
            raise "No se pueden dejar obejtos en el almacenamiento"
          end
          @scene.pbRefresh
          dispqty  = (itm.is_important?) ? 1 : qty
          itemname = (dispqty > 1) ? itm.portion_name_plural : itm.portion_name
          pbDisplay(_INTL("Has dejado {1} {2}.", dispqty, itemname))
        else
          pbDisplay(_INTL("No hay espacio para almacenar objetos."))
        end
      end
    end
    @scene.pbEndScene
  end

  # UI logic for tossing an item in the item storage screen.
  def pbTossItemScreen
    if !$PokemonGlobal.pcItemStorage
      $PokemonGlobal.pcItemStorage = PCItemStorage.new
    end
    storage = $PokemonGlobal.pcItemStorage
    @scene.pbStartScene(storage)
    loop do
      item = @scene.pbChooseItem
      break if !item
      itm = GameData::Item.get(item)
      if itm.is_important?
        @scene.pbDisplay(_INTL("¡Eso es muy importante para ser tirado!"))
        next
      end
      qty = storage.quantity(item)
      itemname       = itm.portion_name
      itemnameplural = itm.portion_name_plural
      if qty > 1
        qty = @scene.pbChooseNumber(_INTL("Cuántos {1} tirar?", itemnameplural), qty)
      end
      next if qty <= 0
      itemname = itemnameplural if qty > 1
      next if !pbConfirm(_INTL("¿Segur{1} que quieres tirar {2} {3}?", $player.female? ? 'a' : 'o', qty, itemname))
      if !storage.remove(item, qty)
        raise "No se pueden borrar objetos del almacenamiento"
      end
      @scene.pbRefresh
      pbDisplay(_INTL("Has tirado {1} {2}.", qty, itemname))
    end
    @scene.pbEndScene
  end
end

#=============================================================================
# New function for using an item
#=============================================================================
# @return [Integer] 0 = item wasn't used; 1 = item used; 2 = close Bag to use in field
def pbBagUseItem(bag, item, scene, screen, chosen, bagscene=nil)
  itm     = GameData::Item.get(item)
  useType = itm.field_use
  pkmn    = $player.party[chosen]
  if itm.is_machine?    # TM, HM or TR
    if $player.pokemon_count == 0
      pbMessage(_INTL("No hay Pokémon.")) { screen.pbUpdate }
      return 0
    end
    machine = itm.move
    return 0 if !machine
    movename = GameData::Move.get(machine).name
    move     = GameData::Move.get(machine).id
    movelist = nil; bymachine = false; oneusemachine = false
    if movelist != nil && movelist.is_a?(Array)
      for i in 0...movelist.length
        movelist[i] = GameData::Move.get(movelist[i]).id
      end
    end
    if pkmn.egg?
      pbMessage(_INTL("Los Huevos no pueden aprender movimientos.")) { screen.pbUpdate }
    elsif pkmn.shadowPokemon?
      pbMessage(_INTL("Los Pokémon Oscuros no pueden aprender movimientos.")) { screen.pbUpdate }
    elsif movelist && !movelist.any? { |j| j == pkmn.species }
      pbMessage(_INTL("{1} no puede aprender {2}.", pkmn.name, movename)) { screen.pbUpdate }
    elsif !pkmn.compatible_with_move?(move)
      pbMessage(_INTL("{1} no puede aprender {2}.", pkmn.name, movename)) { screen.pbUpdate }
    else
      if pbLearnMove(pkmn, move, false, bymachine) { screen.pbUpdate }
        pkmn.add_first_move(move) if oneusemachine
        bag.remove(itm) if itm.consumed_after_use?
      end
    end
    screen.pbRefresh; screen.pbUpdate
    return 1
  elsif useType == 1 # Item is usable on a Pokémon
    if $player.pokemon_count == 0
      pbMessage(_INTL("No hay Pokémon.")) { screen.pbUpdate }
      return 0
    end
    qty = 1
    ret = false
    screen.pbRefresh
    if pbCheckUseOnPokemon(item, pkmn, screen)
      #ret = ItemHandlers.triggerUseOnPokemon(item, qty, pkmn, screen)
      max_at_once = ItemHandlers.triggerUseOnPokemonMaximum(item, pkmn)
      max_at_once = [max_at_once, $bag.quantity(itm)].min	
      if max_at_once > 1
        qty = screen.pbChooseNumber(
          _INTL("¿Qué cantidad de {1} quieres usar?", GameData::Item.get(item).name), max_at_once
        )
        scene.pbSetHelpText("") if screen.is_a?(PokemonPartyScreen)
      end
      if qty > 0
        ret = ItemHandlers.triggerUseOnPokemon(item, qty, pkmn, screen)
        if ret && useType == 1 # Usable on Pokémon, consumed
          $bag.remove(item, qty)  if itm.consumed_after_use? { screen.pbRefresh }
        end 
        if !$bag.has?(item) && itm.num_pocket != 8
          screen.pbDisplay(_INTL("No te quedan más {1}.", itm.portion_name)) { screen.pbUpdate }
          screen.pbChangeCursor(2)
        end
      end
      screen.pbRefresh
    end
    bagscene.pbRefresh if bagscene
    return 1
  else
    pbMessage(_INTL("Aquí no se puede usar.")) { screen.pbUpdate }
    return 0
  end
end

#=============================================================================
# Reprogamming Sacred Ash to work with the party from the bag
#=============================================================================
ItemHandlers::UseInField.add(:SACREDASH, proc { |item|
  if $player.pokemon_count == 0
    pbMessage(_INTL("No hay Pokémon."))
    next false
  end
  canrevive = false
  $player.pokemon_party.each do |i|
    next if !i.fainted?
    canrevive = true
    break
  end
  if !canrevive
    pbMessage(_INTL("No tendría ningún efecto."))
    next false
  end
  revived = 0
  $player.party.each_with_index do |pkmn, i|
    next if !pkmn.fainted?
    revived += 1
    pkmn.heal
  end
  if revived > 1
    pbMessage(_INTL("Has restaurado los PS de tu Pokémon."))
  elsif revived == 1
    pbMessage(_INTL("Has restaurado los PS de tu Pokémon."))
  end
  next (revived > 0)
})

#=============================================================================
# Battle scene for openning the Bag screen and choosing an item to use
#=============================================================================
class Battle::Scene
  def pbItemMenu(idxBattler, _firstAction)
    # Fade out and hide all sprites
    visibleSprites = pbFadeOutAndHide(@sprites)
    # Set Bag starting positions
    oldLastPocket = $bag.last_viewed_pocket
    oldChoices    = $bag.last_pocket_selections.clone
    if @bagLastPocket
      $bag.last_viewed_pocket     = @bagLastPocket
      $bag.last_pocket_selections = @bagChoices
    else
      $bag.reset_last_selections
    end
    # Setting up the party and starting the Bag screen
    partyPos = @battle.pbPartyOrder(idxBattler)
    partyStart, _partyEnd = @battle.pbTeamIndexRangeFromBattlerIndex(idxBattler)
    modParty = @battle.pbPlayerDisplayParty(idxBattler)
    itemScene = PokemonBag_Scene.new
    itemScene.pbStartScene($bag, modParty, true,
                           proc { |item|
                             useType = GameData::Item.get(item).battle_use
                             next useType && useType > 0
                           }, false)
    # Loop while in Bag screen
    wasTargeting = false
    loop do
      # Select an item
      item = itemScene.pbChooseItem
      break if !item
      # Choose a command for the selected item
      item = GameData::Item.get(item)
      itemName = item.name
      useType = item.battle_use
      cmdUse = -1
      commands = []
      commands[cmdUse = commands.length] = _INTL("Usar") if useType && useType != 0
      commands[commands.length]          = _INTL("Cancelar")
      command = itemScene.pbShowCommands(_INTL("Has seleccionado a {1}.", itemName), commands)
      next unless cmdUse >= 0 && command == cmdUse   # Use
      # Use types:
      # 0 = not usable in battle
      # 1 = use on Pokémon (lots of items, Blue Flute)
      # 2 = use on Pokémon's move (Ethers)
      # 3 = use on battler (X items, Persim Berry, Red/Yellow Flutes)
      # 4 = use on opposing battler (Poké Balls)
      # 5 = use no target (Poké Doll, Guard Spec., Poké Flute, Launcher items)
      case useType
      when 1, 2, 3   # Use on Pokémon/Pokémon's move/battler
        # Auto-choose the Pokémon/battler whose action is being decided if they
        # are the only available Pokémon/battler to use the item on
        case useType
        when 1   # Use on Pokémon
          if @battle.pbTeamLengthFromBattlerIndex(idxBattler) == 1
            break if yield item.id, useType, @battle.battlers[idxBattler].pokemonIndex, -1, itemScene
          end
        when 3   # Use on battler
          if @battle.pbPlayerBattlerCount == 1
            break if yield item.id, useType, @battle.battlers[idxBattler].pokemonIndex, -1, itemScene
          end
        end
        # Get player's party
        party    = @battle.pbParty(idxBattler)
        partyPos = @battle.pbPartyOrder(idxBattler)
        partyStart, _partyEnd = @battle.pbTeamIndexRangeFromBattlerIndex(idxBattler)
        modParty = @battle.pbPlayerDisplayParty(idxBattler)
        # Start Pokémon selection
        idxParty = -1
        # Loop while in party screen
        loop do
          # Select a Pokémon
          pbPlayDecisionSE
          idxParty = itemScene.pbChoosePoke(0,false)
          break if idxParty < 0
          idxPartyRet = -1
          partyPos.each_with_index do |pos, i|
            next if pos != idxParty + partyStart
            idxPartyRet = i
            break
          end
          next if idxPartyRet < 0
          pkmn = party[idxPartyRet]
          next if !pkmn || pkmn.egg?
          idxMove = -1
          if useType == 2   # Use on Pokémon's move
            idxMove = itemScene.pbChooseMove(pkmn,_INTL("¿Qué movimiento restaurar?"))
            next if idxMove < 0
          end
          break if yield item.id, useType, idxPartyRet, idxMove, itemScene
        end
        # Cancelled choosing a Pokémon; show the Bag screen again
        break if idxParty >= 0
      when 4   # Use on opposing battler (Poké Balls)
        idxTarget = -1
        if @battle.pbOpposingBattlerCount(idxBattler) == 1
          @battle.allOtherSideBattlers(idxBattler).each { |b| idxTarget = b.index }
          break if yield item.id, useType, idxTarget, -1, itemScene
        else
          wasTargeting = true
          # Fade out and hide Bag screen
          itemScene.pbFadeOutScene
          # Fade in and show the battle screen, choosing a target
          tempVisibleSprites = visibleSprites.clone
          tempVisibleSprites["commandWindow"] = false
          tempVisibleSprites["targetWindow"]  = true
          idxTarget = pbChooseTarget(idxBattler, GameData::Target.get(:Foe), tempVisibleSprites)
          if idxTarget >= 0
            break if yield item.id, useType, idxTarget, -1, self
          end
          # Target invalid/cancelled choosing a target; show the Bag screen again
          wasTargeting = false
          pbFadeOutAndHide(@sprites)
          itemScene.pbFadeInScene
        end
      when 5   # Use with no target
        break if yield item.id, useType, idxBattler, -1, itemScene
      end
    end
    @bagLastPocket = $bag.last_viewed_pocket
    @bagChoices    = $bag.last_pocket_selections.clone
    $bag.last_viewed_pocket     = oldLastPocket
    $bag.last_pocket_selections = oldChoices
    # Close Bag screen
    itemScene.pbEndScene
    # Fade back into battle screen (if not already showing it)
    pbFadeInAndShow(@sprites, visibleSprites) if !wasTargeting
  end
end

==============================================================================
# Script: BetterMoveRelearner
==============================================================================
#===============================================================================
#
#===============================================================================
class UI::MoveReminderCursor < IconSprite
  attr_accessor :top_index

  CURSOR_WIDTH     = 258
  CURSOR_HEIGHT    = 72
  CURSOR_THICKNESS = 6

  def initialize(viewport = nil)
    super(0, 0, viewport)
    setBitmap("Graphics/UI/Move Reminder/cursor")
    self.src_rect = Rect.new(0, 0, CURSOR_WIDTH, CURSOR_HEIGHT)
    self.z = 1600
    @bg_sprite = IconSprite.new(x, y, viewport)
    @bg_sprite.setBitmap("Graphics/UI/Move Reminder/cursor")
    @bg_sprite.src_rect = Rect.new(0, CURSOR_HEIGHT, CURSOR_WIDTH, CURSOR_HEIGHT)
    @top_index = 0
    self.index = 0
  end

  def dispose
    @bg_sprite.dispose
    @bg_sprite = nil
    super
  end

  def index=(value)
    @index = value
    refresh_position
  end

  def visible=(value)
    super
    @bg_sprite.visible = value
  end

  def refresh_position
    return if @index < 0
    self.x = UI::MoveReminderVisuals::MOVE_LIST_X
    self.y = UI::MoveReminderVisuals::MOVE_LIST_Y - CURSOR_THICKNESS
    self.y += (@index - @top_index) * UI::MoveReminderVisuals::MOVE_LIST_SPACING
    @bg_sprite.x = self.x
    @bg_sprite.y = self.y
  end
end

#===============================================================================
#
#===============================================================================
class UI::MoveReminderVisuals < UI::BaseVisuals
  attr_reader :index

  GRAPHICS_FOLDER   = "Move Reminder/"   # Subfolder in Graphics/UI
  TEXT_COLOR_THEMES = {   # These color themes are added to @sprites[:overlay]
    :default => [Color.new(248, 248, 248), Color.new(0, 0, 0)],   # Base and shadow colour
    :white   => [Color.new(248, 248, 248), Color.new(0, 0, 0)],
    :black   => [Color.new(64, 64, 64), Color.new(176, 176, 176)],
    :header  => [Color.new(88, 88, 80), Color.new(168, 184, 184)]
  }
  MOVE_LIST_X        = 0
  MOVE_LIST_Y        = 84
  MOVE_LIST_SPACING  = 64    # Y distance between top of two adjacent move areas
  VISIBLE_MOVES      = 4
  TYPE_ICONS_X       = 396
  TYPE_ICONS_Y       = 70
  TYPE_ICONS_SPACING = 6
  POKEMON_ICON_X     = 314
  POKEMON_ICON_Y     = 84
  HEADER_X           = 16
  HEADER_Y           = 14
  BUTTON_DOWN_WIDTH  = 76
  BUTTON_DOWN_HEIGHT = 32
  BUTTON_DOWN_X      = 47
  BUTTON_DOWN_Y      = 350
  BUTTON_UP_WIDTH    = 76
  BUTTON_UP_HEIGHT   = 32
  BUTTON_UP_X        = 135
  BUTTON_UP_Y        = 350
  MOVE_NAME_X_OFFSET = 76
  MOVE_NAME_Y_OFFSET = 6
  LEVEL_OR_TM_X_OFFSET = 12
  LEVEL_OR_TM_Y_OFFSET = 36
  PP_LABEL_X_OFFSET   = 150
  PP_LABEL_Y_OFFSET   = 38
  PP_VALUE_X_OFFSET   = 240
  PP_VALUE_Y_OFFSET   = 38
  POWER_LABEL_X       = 278
  POWER_LABEL_Y       = 120
  POWER_VALUE_X       = 480
  POWER_VALUE_Y       = 120
  ACCURACY_LABEL_X    = 278
  ACCURACY_LABEL_Y    = 152
  ACCURACY_VALUE_X    = 480
  ACCURACY_VALUE_Y    = 152
  CATEGORY_LABEL_X    = 278
  CATEGORY_LABEL_Y    = 184
  CATEGORY_ICON_X     = 436
  CATEGORY_ICON_Y     = 178
  DESCRIPTION_X       = 275
  DESCRIPTION_Y       = 215
  DESCRIPTION_WIDTH   = 235
  DESCRIPTION_LINES   = 5
  TYPE_ICON_X_OFFSET  = 8
  TYPE_ICON_Y_OFFSET  = 1
  MOVE_NAME_WIDTH     = 230

  # Color del punto rojo (puedes cambiarlo a otro color)
  NEW_MOVE_INDICATOR_COLOR = Color.new(255, 60, 60)  # Rojo
  
  # Radio del punto en píxeles
  NEW_MOVE_INDICATOR_RADIUS = 6
  
  # Mostrar borde blanco alrededor del punto
  NEW_MOVE_INDICATOR_BORDER = true
  
  # Color del borde
  NEW_MOVE_INDICATOR_BORDER_COLOR = Color.new(255, 255, 255)  # Blanco
  INDICATOR_OFFSET_X = 105
  INDICATOR_OFFSET_Y = 45

  def initialize(pokemon, moves)
    @pokemon   = pokemon
    @moves     = moves
    @top_index = 0
    @index     = 0
    super()
    refresh_cursor
    # Mark initial move as seen
    if Settings::SHOW_INDICATOR_FOR_UNSEEN_MOVES_IN_MOVE_RELEARNER && !@moves.empty?
      initial_move = @moves[@index]
      if initial_move && !@pokemon.seen_move?(initial_move[0])
        $PokemonGlobal.add_seen_move(@pokemon.species, initial_move[0])
      end
    end
  end

  def initialize_bitmaps
    @bitmaps[:types]   = AnimatedBitmap.new(UI_FOLDER + _INTL("types"))
    @bitmaps[:buttons] = AnimatedBitmap.new(graphics_folder + "buttons")
  end

  def initialize_sprites
    # Pokémon icon
    @sprites[:pokemon_icon] = PokemonIconSprite.new(@pokemon, @viewport)
    @sprites[:pokemon_icon].setOffset(PictureOrigin::CENTER)
    @sprites[:pokemon_icon].x = POKEMON_ICON_X
    @sprites[:pokemon_icon].y = POKEMON_ICON_Y
    @sprites[:pokemon_icon].z = 200
    # Cursor
    @sprites[:cursor] = UI::MoveReminderCursor.new(@viewport)
  end

  #-----------------------------------------------------------------------------

  def moves=(move_list)
    @moves = move_list
    @index = @moves.length - 1 if @index >= @moves.length
    refresh_on_index_changed(@index)
    @cursor.visible = false if @moves.empty?
    refresh
  end

  #-----------------------------------------------------------------------------

  def refresh_overlay
    super
    draw_header
    draw_pokemon_type_icons(TYPE_ICONS_X, TYPE_ICONS_Y, TYPE_ICONS_SPACING)
    draw_moves_list
    draw_move_properties
    draw_buttons
  end

  def draw_header
    draw_text(_INTL("¿Enseñar movimiento?"), HEADER_X, HEADER_Y, theme: :header)
  end

  # x and y are the top left corner of the type icon if there is only one type.
  def draw_pokemon_type_icons(x, y, spacing)
    @pokemon.types.each_with_index do |type, i|
      type_number = GameData::Type.get(type).icon_position
      offset = ((@pokemon.types.length - 1) * (GameData::Type::ICON_SIZE[0] + spacing) / 2)
      offset = (offset / 2) * 2
      type_x = x - offset + ((GameData::Type::ICON_SIZE[0] + spacing) * i)
      draw_image(@bitmaps[:types], type_x, y,
                 0, type_number * GameData::Type::ICON_SIZE[1], *GameData::Type::ICON_SIZE)
    end
  end

  def draw_moves_list
    VISIBLE_MOVES.times do |i|
      move = @moves[@top_index + i]
      next if move.nil?
      draw_move_in_list(move, MOVE_LIST_X, MOVE_LIST_Y + (i * MOVE_LIST_SPACING))
    end
  end

  def draw_move_in_list(move, x, y)
    move_data = GameData::Move.get(move[0])

    # Draw move type icon
    type_number = GameData::Type.get(move_data.display_type(@pokemon)).icon_position
    draw_image(@bitmaps[:types], x + TYPE_ICON_X_OFFSET, y + TYPE_ICON_Y_OFFSET,
                0, type_number * GameData::Type::ICON_SIZE[1], *GameData::Type::ICON_SIZE)

    # Draw move name
    move_name = move_data.name
    move_name = crop_text(move_name, MOVE_NAME_WIDTH)
    draw_text(move_name, x + MOVE_NAME_X_OFFSET, y + MOVE_NAME_Y_OFFSET)

    # Draw move learn level or TM/HM
    if move[1]
      tm_hm = move[1] == :TM ? _INTL("MT") : move[1] == :HM ? _INTL("MO") : move[1]
      draw_text(tm_hm, x + LEVEL_OR_TM_X_OFFSET, y + LEVEL_OR_TM_Y_OFFSET)
    end

    # Draw PP text
    if move_data.total_pp > 0
      draw_text(_INTL("PP"), x + PP_LABEL_X_OFFSET, y + PP_LABEL_Y_OFFSET, theme: :black)
      draw_text(sprintf("%d/%d", move_data.total_pp, move_data.total_pp), x + PP_VALUE_X_OFFSET, y + PP_VALUE_Y_OFFSET, align: :right, theme: :black)
    end

    # Draw indicator for unseen moves
    if Settings::SHOW_INDICATOR_FOR_UNSEEN_MOVES_IN_MOVE_RELEARNER && !@pokemon.seen_move?(move[0])
      indicator_x = x + INDICATOR_OFFSET_X
      indicator_y = y + INDICATOR_OFFSET_Y
      
      # Draw border circle if enabled
      if NEW_MOVE_INDICATOR_BORDER
        border_radius = NEW_MOVE_INDICATOR_RADIUS + 2
        @sprites[:overlay].bitmap.bmp_circle(NEW_MOVE_INDICATOR_BORDER_COLOR, border_radius, indicator_x, indicator_y, false)
      end
      
      # Draw main indicator circle
      @sprites[:overlay].bitmap.bmp_circle(NEW_MOVE_INDICATOR_COLOR, NEW_MOVE_INDICATOR_RADIUS, indicator_x, indicator_y, false)
    end
  end

  def draw_move_properties
    move = @moves[@index]
    move_data = GameData::Move.get(move[0])
    # Power
    draw_text(_INTL("POTENCIA"), POWER_LABEL_X, POWER_LABEL_Y)
    power_text = move_data.display_power(@pokemon)
    power_text = "---" if power_text == 0   # Status move
    power_text = "???" if power_text == 1   # Variable power move
    draw_text(power_text, POWER_VALUE_X, POWER_VALUE_Y, align: :right, theme: :black)
    # Accuracy
    draw_text(_INTL("PRECISIÓN"), ACCURACY_LABEL_X, ACCURACY_LABEL_Y)
    accuracy = move_data.display_accuracy(@pokemon)
    if accuracy == 0
      draw_text("---", ACCURACY_VALUE_X, ACCURACY_VALUE_Y, align: :right, theme: :black)
    else
      draw_text(accuracy, ACCURACY_VALUE_X, ACCURACY_VALUE_Y, align: :right, theme: :black)
      draw_text("%", ACCURACY_VALUE_X, ACCURACY_VALUE_Y, theme: :black)
    end

    # Draw move category
    draw_text(_INTL("CATEGORÍA"), CATEGORY_LABEL_X, CATEGORY_LABEL_Y)
    draw_image(UI_FOLDER + "category", CATEGORY_ICON_X, CATEGORY_ICON_Y,
               0, move_data.display_category(@pokemon) * GameData::Move::CATEGORY_ICON_SIZE[1], *GameData::Move::CATEGORY_ICON_SIZE)

    # Description
    draw_paragraph_text(move_data.description, DESCRIPTION_X, DESCRIPTION_Y, DESCRIPTION_WIDTH, DESCRIPTION_LINES, theme: :black)
  end

  def draw_buttons
    draw_image(@bitmaps[:buttons], BUTTON_DOWN_X, BUTTON_DOWN_Y, 0, 0, BUTTON_DOWN_WIDTH, BUTTON_DOWN_HEIGHT) if @index < @moves.length - 1 
    draw_image(@bitmaps[:buttons], BUTTON_UP_X, BUTTON_UP_Y, BUTTON_DOWN_WIDTH, 0, BUTTON_UP_WIDTH, BUTTON_UP_HEIGHT) if @top_index > 0
  end

  #-----------------------------------------------------------------------------

  def refresh_cursor
    @sprites[:cursor].top_index = @top_index
    @sprites[:cursor].index = @index
  end

  def refresh_on_index_changed(old_index)
    pbPlayCursorSE if old_index != @index && defined?(old_index)
    # Mark move as seen when cursor passes over it
    if Settings::SHOW_INDICATOR_FOR_UNSEEN_MOVES_IN_MOVE_RELEARNER && old_index != @index
      current_move = @moves[@index]
      if current_move && !@pokemon.seen_move?(current_move[0])
        $PokemonGlobal.add_seen_move(@pokemon.species, current_move[0])
      end
    end
    # Change @top_index to keep @index in the middle of the visible list (or as
    # close to it as possible)
    middle_range_top = (VISIBLE_MOVES / 2) - ((VISIBLE_MOVES + 1) % 2)
    middle_range_bottom = VISIBLE_MOVES / 2
    if @index < @top_index + middle_range_top
      @top_index = @index - middle_range_top
    elsif @index > @top_index + middle_range_bottom
      @top_index = @index - middle_range_bottom
    end
    @top_index = @top_index.clamp(0, [@moves.length - VISIBLE_MOVES, 0].max)
    refresh_cursor
    refresh
  end

  #-----------------------------------------------------------------------------

  def update_input
    # Check for movement to a new move
    update_cursor_movement
    # Check for interaction
    if Input.trigger?(Input::USE)
      return update_interaction(Input::USE)
    elsif Input.trigger?(Input::BACK)
      return update_interaction(Input::BACK)
    elsif Input.trigger?(Input::ACTION)
      return update_interaction(Input::ACTION)
    end
    return nil
  end

  def update_cursor_movement
    old_index = @index
    # Check for movement to a new move
    if Input.repeat?(Input::UP)
      @index -= 1
      if Input.trigger?(Input::UP)
        @index = @moves.length - 1 if @index < 0   # Wrap around
      else
        @index = 0 if @index < 0
      end
    elsif Input.repeat?(Input::DOWN)
      @index += 1
      if Input.trigger?(Input::DOWN)
        @index = 0 if @index >= @moves.length   # Wrap around
      else
        @index = @moves.length - 1 if @index >= @moves.length
      end
    elsif Input.repeat?(Input::JUMPUP)
      @index -= VISIBLE_MOVES
      @index = 0 if @index < 0
    elsif Input.repeat?(Input::JUMPDOWN)
      @index += VISIBLE_MOVES
      @index = @moves.length - 1 if @index >= @moves.length
    end
    if old_index != @index
      refresh_on_index_changed(old_index)
    end
    
    return old_index != @index
  end

  def update_interaction(input)
    case input
    when Input::USE
      pbPlayDecisionSE
      return :learn
    when Input::BACK
      pbPlayCloseMenuSE
      return :quit
    end
    return nil
  end
end

#===============================================================================
#
#===============================================================================
class UI::MoveReminder < UI::BaseScreen
  attr_reader :pokemon
  

  ACTIONS = HandlerHash.new

  SCREEN_ID = :move_reminder_screen

  # mode is either :normal or :single.
  def initialize(pokemon, mode: :normal, required_item: nil)
    @pokemon = pokemon
    @mode = mode
    @required_item = required_item
    @moves = []
    @result = nil
    @consumed_items = 0
    generate_move_list
    super()
  end

  def initialize_visuals
    @visuals = UI::MoveReminderVisuals.new(@pokemon, @moves)
  end

  def required_item
    return @required_item
  end

  def consumed_items
    return @consumed_items
  end

  def consumed_items=(value)
    @consumed_items = value
  end

  def show_consumed_items_message
    return if @required_item.nil? || @consumed_items <= 0
    item_name = GameData::Item.get(@required_item).name_plural
    pbMessage(_INTL("\\PN entregó {1} {2} a cambio.", @consumed_items, item_name))
  end

  #-----------------------------------------------------------------------------

  def generate_move_list
    @moves = []
    return if !@pokemon || @pokemon.egg? || @pokemon.shadowPokemon?
    @pokemon.getMoveList.each do |move|
      next if move[0] > @pokemon.level || @pokemon.hasMove?(move[1])
      # @moves.push(move[1]) if !@moves.include?(move[1])
      move_to_add = move.is_a?(GameData::Move) ? move.id : move[1]
      @moves << [move_to_add, _INTL("Nv. #{move[0].to_i.abs}")] if !@moves.include?(move_to_add)
    end
    if Settings::MOVE_RELEARNER_CAN_TEACH_MORE_MOVES && @pokemon.first_moves
      first_moves = []
      @pokemon.first_moves.each do |move|
        first_moves.push([move, _INTL("Nv. 1")]) if !@moves.any? { |m| m[0] == move } && !@pokemon.hasMove?(move)
      end
      @moves = first_moves + @moves   # List first moves before level-up moves
    end
    @moves = @moves.uniq { |move| move[0] }   # remove duplicates based on move ID

    if Settings::SHOW_MTS_MOS_IN_MOVE_RELEARNER
      tms = pbGetTMMoves(@pokemon)
      for tm in tms
        if !@moves.any? { |m| m[0] == tm[0] }
            @moves.push([tm[0], tm[1]])
        end
      end
    end

  end

  def refresh_move_list
    generate_move_list
    @visuals.moves = @moves
  end

  #-----------------------------------------------------------------------------

  def move
    return @moves[self.index]
  end

  #-----------------------------------------------------------------------------

  #===============================================================================
  # Actions that can be triggered in the Move Reminder screen.
  #===============================================================================
  ACTIONS.add(:learn, {
    :effect => proc { |screen|
      # move Array len 2
      # Possible values
      # [:MOVE_ID, "Nv X."]
      # [:MOVE_ID, "TM"]
      # [:MOVE_ID, "HM"]
      move = screen.move
      next if !screen.show_confirm_message(_INTL("¿Enseñar {1}?", GameData::Move.get(move[0]).name))

      is_machine = [:TM, :HM].include?(move[1]) ? true : false
      
      # Check if player has required item (only for non-machine moves)
      if !is_machine && screen.required_item && !$bag.has?(screen.required_item)
        screen.show_message(_INTL("No tienes más {1}.", GameData::Item.get(screen.required_item).name_plural))
        screen.end_screen
        next
      end
      
      relearn = is_machine ? false : true
      next if !pbLearnMove(screen.pokemon, move[0], false, is_machine, relearn)
      
      # Remove required item if specified (only for non-machine moves)
      if !is_machine && screen.required_item
        $bag.remove(screen.required_item)
        screen.consumed_items = screen.consumed_items + 1
      end
      
      $stats.moves_taught_by_reminder += 1 if !is_machine
      $stats.moves_taught_by_item     += 1 if is_machine
      
      if screen.mode == :normal
        screen.refresh_move_list
        # Check if player still has items (only for non-machine moves)
        if !is_machine && screen.required_item && !$bag.has?(screen.required_item)
          screen.show_message(_INTL("No tienes más {1}.", GameData::Item.get(screen.required_item).name_plural))
          screen.end_screen
        end
      else
        screen.end_screen
      end
    }
  })

  #-----------------------------------------------------------------------------

  def main
    return if @disposed
    start_screen
    @visuals.refresh if @visuals
    Graphics.update
    loop do
      on_start_main_loop
      command = @visuals.navigate
      break if command == :quit && (@mode == :normal ||
               show_confirm_message(_INTL("¿Prefieres que {1} no aprenda un movimiento nuevo?", @pokemon.name)))
      perform_action(command)
      if @moves.empty?
        show_message(_INTL("No hay más movimientos para que {1} aprenda.", @pokemon.name))
        break
      end
      if @disposed
        @result = true
        break
      end
    end
    end_screen
    return @result
  end
end

#===============================================================================
#
#===============================================================================
def pbRelearnMoveScreen(pkmn, required_item = nil)
  ret = true
  pbFadeOutIn do
    mode = Settings::CLOSE_MOVE_RELEARNER_AFTER_TEACHING_MOVE ? :single : :normal
    move_reminder = UI::MoveReminder.new(pkmn, mode: mode, required_item: required_item)
    ret = move_reminder.main
    move_reminder.show_consumed_items_message
  end
  return ret
end

def pbGetTMMoves(pokemon)
  tmmoves = []
  for item_aux in $bag.pockets[4]
    item = GameData::Item.get(item_aux[0])
    if item.is_machine?
      machine = item.move
      tmorhm = item.is_HM? ? :HM : :TM
      if pokemon.compatible_with_move?(machine) && !pokemon.hasMove?(machine)
        tmmoves.push([machine, tmorhm])
      end
    end
  end
  return tmmoves
end

