def expshare_enabled?
	return false unless $PokemonGlobal
	$PokemonGlobal.expshare_enabled ||= Settings::EXPSHARE_ENABLED || $player&.has_exp_all || $bag.has?(:EXPSHARE2)
	$PokemonGlobal.expshare_enabled ? true : false
end

class PokemonGlobalMetadata
	attr_accessor :expshare_enabled
	alias initialize_expshare initialize
	def initialize
		initialize_expshare
		@expshare_enabled = Settings::EXPSHARE_ENABLED
	end
end

if Settings::USE_NEW_EXP_SHARE
	class PokemonSystem
		attr_accessor :expshareon
	end

	MenuHandlers.add(:options_menu, :expshareon, {
		"name"        => _INTL("Rep. Exp. al capturar"),
		"order"       => 40,
		"type"        => Settings::USE_NEW_OPTIONS_UI ? :array : EnumOption,
		"condition"   => proc { next expshare_enabled? },
		"parameters"  => proc { [_INTL("Sí"), _INTL("No")] },
		"description" => _INTL("Si quieres que los Pokémon capturados tengan el repartir experiencia activado."),
		"get_proc"    => proc { next $PokemonSystem.expshareon },
		"set_proc"    => proc { |value, _scene| $PokemonSystem.expshareon = value }
	})

    MenuHandlers.add(:party_menu, :expshare, {
		"name"      => _INTL("Repartir Exp."),
		"order"     => 70,
		"condition" => proc { next expshare_enabled? },
		"effect"    => proc { |screen, party, party_idx|
			pokemon = party[party_idx]
			
			txt_individual = pokemon.expshare ? _INTL("Desactivar a {1}", pokemon.name) : _INTL("Activar a {1}", pokemon.name)
			txt_individual_msg = pokemon.expshare ? _INTL("desactivado") : _INTL("activado")
			txt_all_on     = _INTL("Activar a todos")
			txt_all_off    = _INTL("Desactivar a todos")
			txt_cancel     = _INTL("Cancelar")
			commands = []
			cmd_individual = -1
			cmd_all_on     = -1
			cmd_all_off    = -1
			cmd_cancel     = -1

			if !pokemon.egg?
				commands.push(txt_individual)
				cmd_individual = commands.length - 1
			end

			commands.push(txt_all_on)
			cmd_all_on = commands.length - 1
			commands.push(txt_all_off)
			cmd_all_off = commands.length - 1
			commands.push(txt_cancel)
			cmd_cancel = commands.length - 1
			cmd = screen.pbShowCommands(_INTL("¿Qué hacer?"), commands, 0)
			

			if cmd >= 0
				if cmd == cmd_individual
					pokemon.expshare = !pokemon.expshare
					screen.scene.pbRefresh
					screen.pbDisplay( _INTL("Se ha {1} el Repartir Exp. en {2}.", txt_individual_msg, pokemon.name))						
				elsif cmd == cmd_all_on
					party.each do |pkmn| 
						pkmn.expshare = true if !pkmn.egg? 
					end
					screen.scene.pbRefresh
					screen.pbDisplay(_INTL("Se ha activado el Repartir Exp. para todo el equipo."))					
				elsif cmd == cmd_all_off
					party.each { |pkmn| pkmn.expshare = false }
					screen.scene.pbRefresh
					screen.pbDisplay(_INTL("Se ha desactivado el Repartir Exp. para todo el equipo."))
				elsif cmd == cmd_cancel
					# No hace nada (Inserte meme del gato)
				end
			end
			
			next true
		}   
	})

	def toggle_expshare
		$PokemonGlobal.expshare_enabled ||= Settings::EXPSHARE_ENABLED || $player&.has_exp_all || $bag.has?(:EXPSHARE2)
		$PokemonGlobal.expshare_enabled = !$PokemonGlobal.expshare_enabled
		$player.party.each { |pokemon| pokemon.expshare = $PokemonGlobal.expshare_enabled }
	end
	
	class Pokemon
		attr_accessor(:expshare)    # Repartir experiencia
		alias initialize_old initialize
		def initialize(species, level, player = $player, withMoves = true, recheck_form = true)
			initialize_old(species, level, player, withMoves)
			$PokemonSystem.expshareon ||= 0
			@expshare = expshare_enabled? && $PokemonSystem.expshareon == 0
		end 
	end
	
	class PokemonPartyPanel < Sprite
		alias initialize_old initialize
		def initialize(pokemon,index,viewport=nil)
			initialize_old(pokemon,index,viewport)
			if @pokemon.expshare && !@pokemon.egg?
				@expicon = ChangelingSprite.new(0, 0, viewport)
				@expicon.add_bitmap(:expicon,"Graphics/Pictures/expicon")
				@expicon.z=self.z+3 # For compatibility with RGSS2
			end
		end


		alias refresh_overlay_information_old refresh_overlay_information
		def refresh_overlay_information
			refresh_overlay_information_old
			draw_exp_icon
		end

		def draw_exp_icon
			return if !@pokemon.expshare || @pokemon.egg?
			pbDrawImagePositions(@overlaysprite.bitmap, 
			[["Graphics/Pictures/expicon", 226, 70, 0, 0]])
		end

		def refresh_exp_icon
			return if !@expicon || @expicon.disposed?
			@expicon.x=self.x+226
			@expicon.y=self.y+68
			@expicon.color=self.color
		end

		def dispose
			@panelbgsprite.dispose
			@hpbgsprite.dispose
			@ballsprite.dispose
			@pkmnsprite.dispose
			@helditemsprite.dispose
			@overlaysprite.bitmap.dispose
			@overlaysprite.dispose
			@hpbar.dispose
			@statuses.dispose
			@expicon.dispose if @expicon
			super
		end
		
		def refresh
			return if disposed?
			return if @refreshing
			@refreshing = true
			refresh_panel_graphic
			refresh_hp_bar_graphic
			refresh_ball_graphic
			refresh_pokemon_icon
			refresh_held_item_icon
			refresh_exp_icon
			if @overlaysprite && !@overlaysprite.disposed?
			@overlaysprite.x     = self.x
			@overlaysprite.y     = self.y
			@overlaysprite.color = self.color
			end
			refresh_overlay_information
			@refreshBitmap = false
			@refreshing = false
		end

		alias update_old update
		def update
			update_old
			@expicon.update if @expicon 
		end
	end
	
	class Battle 
	################################################################################
	# Experiencia en captura reducida
	################################################################################
		def pbGainExp
			# Play wild victory music if it's the end of the battle (has to be here)
			@scene.pbWildBattleSuccess if wildBattle? && pbAllFainted?(1) && !pbAllFainted?(0)
			return if !@internalBattle || @rules[:no_exp_gain]
			# Go through each battler in turn to find the Pokémon that participated in
			# battle against it, and award those Pokémon Exp/EVs
			expAll = $player.has_exp_all || $bag.has?(:EXPALL)
			p1 = pbParty(0)
			@battlers.each do |b|
				next unless b&.opposes?   # Can only gain Exp from fainted foes
				next if b.participants.length == 0
				next unless b.fainted? || b.captured
				# Count the number of participants
				numPartic = 0
				b.participants.each do |partic|
					next unless p1[partic]&.able? && pbIsOwner?(0, partic)
					numPartic += 1
				end
				# Find which Pokémon have an Exp Share
				expShare = []
				if !expAll
					eachInTeam(0, 0) do |pkmn, i|
						next if !pkmn.able?
						next if !pkmn.hasItem?(:EXPSHARE) && initialItem(0, i) != :EXPSHARE && !pkmn.expshare
						expShare.push(i)
					end
				end
				# Calculate EV and Exp gains for the participants
				if numPartic > 0 || expShare.length > 0 || expAll
				unGroupMessage = !Settings::GROUP_EXP_SHARE_MESSAGE && expShare.length > 0 && expShare.length > b.participants.length ? true : false
				# Gain EVs and Exp for participants
				eachInTeam(0, 0) do |pkmn, i|
					next if !pkmn.able?
					next unless b.participants.include?(i) || expShare.include?(i)
					showMessage = b.participants.include?(i) || unGroupMessage ? true : false
					pbGainEVsOne(i, b)
					pbGainExpOne(i, b, numPartic, expShare, expAll, showMessage)
				end
				if !unGroupMessage && (expShare.length > numPartic && pbParty(0).length > 1)
					pbDisplayPaused(_INTL("¡Tus otros Pokémon también ganaron puntos de experiencia!"))
				end
				# Gain EVs and Exp for all other Pokémon because of Exp All
				if expAll
					showMessage = true
					eachInTeam(0, 0) do |pkmn, i|
						next if !pkmn.able?
						next if b.participants.include?(i) || expShare.include?(i)
						pbDisplayPaused(_INTL("¡Tus otros Pokémon también ganaron puntos de experiencia!")) if showMessage && (expShare.length > numPartic && pbParty(0).length > 1)
						showMessage = false
						pbGainEVsOne(i, b)
						pbGainExpOne(i, b, numPartic, expShare, expAll, false)
					end
				end
			end
			# Clear the participants array
			b.participants = []
			end
		end
	end
end

==============================================================================
# Script: Fondos Terrenos
==============================================================================
HAZARD_OPACITY = 180
class Battle::Scene
  
  def sceneWait(numframes)
    numframes.times do
      pbUpdate
    end
  end
  
  def pbDeleteField(bg = 'terrain_bg', base1 = 'base_terrain_0', base2 = 'base_terrain_1')
    if @sprites[bg]&.visible
      20.times do
        @sprites[bg].opacity -= 8
        @sprites[base1].opacity -= 8
        @sprites[base2].opacity -= 8
        sceneWait(2)
      end
    end
  end

  def pbDeleteTrickRoomBackground
    if @sprites["trick_room_bg"]&.visible
      25.times do
        @sprites["trick_room_bg"].opacity -= 8
        sceneWait(2)
      end
    end
  end

  def pbSetTrickRoomBackground
    if @battle.field.effects[PBEffects::TrickRoom] <= 0
      pbDeleteTrickRoomBackground
    else
      bg = pbAddSprite("trick_room_bg", 0, 0, "Graphics/Animations/PRAS- Trick Room BG", @viewport)
      bg.z = 1
      bg.opacity = 0
      bg.visible = true

      pbSEPlay("PRSFX- Trick Room", 80)
      25.times do
        @sprites["trick_room_bg"].opacity += 8
        sceneWait(2)
      end
    end
  end
  
  def pbSetFieldBackground
    if @battle.field.terrain == :None 
      pbCreateBackdropSprites
      pbDeleteField
    else
      pbDeleteField
      
      if @battle.field.terrain == :Grassy
        field = "Grassy Terrain"
        sound = "PRSFX- Grassy Terrain"
      elsif @battle.field.terrain == :Misty
        field = "Misty Terrain"
        sound = "PRSFX- Misty Terrain"
      elsif @battle.field.terrain == :Psychic
        field = "Psychic Terrain"
        sound = "PRSFX- Psychic Terrain"
      elsif @battle.field.terrain == :Electric
        field = "Electric Terrain"
        sound = "PRSFX- Electric Terrain"
      end
      
      bg = pbAddSprite("terrain_bg", 0, 0, "Graphics/Animations/PRAS- #{field} BG", @viewport)
      bg.z = 2
      bg.opacity = 0
      bg.visible = true

      playerBase = "Graphics/Animations/#{field}playerbase"
      enemyBase  = "Graphics/Animations/#{field}enemybase"

      2.times do |side|
        baseX, baseY = Battle::Scene.pbBattlerPosition(side)
        base = pbAddSprite("base_terrain_#{side}", baseX, baseY,
                           (side == 0) ? playerBase : enemyBase, @viewport)
        base.z = 3
        base.opacity = 0
        base.visible = true
        if base.bitmap
          base.ox = base.bitmap.width / 2
          base.oy = (side == 0) ? base.bitmap.height : base.bitmap.height / 2
        end
      end

      pbSEPlay(sound, 80)
      20.times do
        @sprites["terrain_bg"].opacity += 8
        @sprites["base_terrain_0"].opacity += 8
        @sprites["base_terrain_1"].opacity += 8
        sceneWait(2)
      end
    end
    
    # Update hazard visuals after setting terrain
    pbUpdateHazardSprites
  end

  # Clear all hazard sprites
  def pbDeleteHazardSprites
    return if !Settings::SHOW_HAZARDS_IN_BATTLE
    # Clear all possible hazard sprites for both sides
    ["stealthrock_0", "stealthrock_1", "stickyweb_0", "stickyweb_1"].each do |sprite_id|
      if @sprites[sprite_id]
        @sprites[sprite_id].visible = false
        @sprites[sprite_id].dispose
        @sprites.delete(sprite_id)
      end
    end
    
    # Clear spikes (up to 3 layers per side)
    2.times do |side|
      3.times do |layer|
        sprite_id = "spikes_#{side}_#{layer}"
        if @sprites[sprite_id]
          @sprites[sprite_id].visible = false
          @sprites[sprite_id].dispose
          @sprites.delete(sprite_id)
        end
      end
    end
    
    # Clear toxic spikes (up to 2 layers per side)
    2.times do |side|
      2.times do |layer|
        sprite_id = "toxicspikes_#{side}_#{layer}"
        if @sprites[sprite_id]
          @sprites[sprite_id].visible = false
          @sprites[sprite_id].dispose
          @sprites.delete(sprite_id)
        end
      end
    end
  end

  # Update all hazard sprites based on current battle state
  def pbUpdateHazardSprites
    return if !@battle
    return if !Settings::SHOW_HAZARDS_IN_BATTLE

    hazards_folder = File.join("Graphics", "UI", "Battle", "hazards")
    
    begin
      pbDeleteHazardSprites
    rescue
      # Silently handle any errors in deleting sprites
    end
    
    2.times do |side|
      sideData = @battle.sides[side]
      baseX, baseY = Battle::Scene.pbBattlerPosition(side)
      

      
      # Stealth Rock - appears floating around the field
      if sideData.effects[PBEffects::StealthRock]
        offset_x = [10, 10][side]           # Spread horizontally
        offset_y = [20, -10][side]         # Keep near the base level
        stealth = pbAddSprite("stealthrock_#{side}", baseX + offset_x, baseY + offset_y,
                             File.join(hazards_folder, "stealth_rock"), @viewport)
        stealth.z = 4
        stealth.opacity = HAZARD_OPACITY
        stealth.visible = true
        if stealth.bitmap
          stealth.ox = stealth.bitmap.width / 2
          stealth.oy = stealth.bitmap.height / 2
        end
      end
      
      # Spikes - appears on the ground (up to 3 layers)
      spikes_count = sideData.effects[PBEffects::Spikes]
      spikes_count.times do |layer|
          # Position spikes in different locations for each layer
          offset_x = [[0, -25, 25], [0, -25, 25]][side][layer]        # Spread horizontally
          offset_y = [[0, 5, -5], [0, 5, -5]][side][layer]          # Keep near the base level
          
          final_x = baseX + offset_x
          final_y = baseY + offset_y
        
        # Try the custom hazards folder first, fallback to original graphics
        spikes_graphic = File.join(hazards_folder, "spikes")
        
        spikes = pbAddSprite("spikes_#{side}_#{layer}", final_x, final_y, spikes_graphic, @viewport)
        spikes.z = 4 + layer * 0.1  # Slight z-ordering for layers
        spikes.opacity = HAZARD_OPACITY  # Each layer more visible: 150, 175, 200
        spikes.visible = true
        
        if spikes.bitmap
          spikes.ox = spikes.bitmap.width / 2
          spikes.oy = (side == 0) ? spikes.bitmap.height : spikes.bitmap.height / 2
        end
      end
      
      # Toxic Spikes - appears on the ground (up to 2 layers)
      toxic_count = sideData.effects[PBEffects::ToxicSpikes]
      toxic_count.times do |layer|
        # Position toxic spikes in different locations for each layer  
        offset_x = [[25, -25], [25, -25]][side][layer]           # Spread horizontally
        offset_y = [[30, 30], [-20, -20]][side][layer]            # Keep near the base level
        
        toxic = pbAddSprite("toxicspikes_#{side}_#{layer}", baseX + offset_x, baseY + offset_y,
                           File.join(hazards_folder, "toxic_spikes"), @viewport)
        toxic.z = 4 + layer * 0.1  # Slight z-ordering for layers
        # toxic.z = 100 + layer * 0.1 if side == 0 # Slight z-ordering for layers 
        toxic.opacity = HAZARD_OPACITY  # Each layer more visible: 140, 180
        toxic.visible = true

        if toxic.bitmap
          toxic.ox = toxic.bitmap.width / 2
          toxic.oy = (side == 0) ? toxic.bitmap.height : toxic.bitmap.height / 2
        end
      end
      
      # Sticky Web - appears as webbing on the ground
      if sideData.effects[PBEffects::StickyWeb]
        offset_x = [10, 0][side]           # Spread horizontally
        offset_y = [20, -20][side]            # Keep near the base level
        web = pbAddSprite("stickyweb_#{side}", baseX + offset_x, baseY + offset_y,
                         File.join(hazards_folder, "sticky_web"), @viewport)
        web.z = 4
        web.opacity = HAZARD_OPACITY
        web.visible = true
        if web.bitmap
          web.ox = web.bitmap.width / 2
          web.oy = (side == 0) ? web.bitmap.height : web.bitmap.height / 2
        end
      end
    end
  end
end

class Battle
  def on_terrain_start
    @scene.pbSetFieldBackground
  end

  alias pbEndTerrain_bg pbEndTerrain
  def pbEndTerrain
    pbEndTerrain_bg
    @scene.pbSetFieldBackground
  end
end

