# Script: Repelente Infinito
==============================================================================
#===============================================================================
# Infinite Repel by dpertierra
# https://github.com/Pokemon-Fan-Games/InifiniteRepel
# https://twitter.com/dpertierra
#===============================================================================
class PokemonGlobalMetadata
  attr_accessor :infRepel
  attr_accessor :repel
end

def pbToggleInfiniteRepel()
  $PokemonGlobal.infRepel ||= false
  if !$PokemonGlobal.infRepel
    pbMessage("Se activó el repelente infinito.")
    $bag.replace_item(:INFREPELOFF, :INFREPEL)
    $bag.replace_registered(:INFREPELOFF, :INFREPEL)
  else
    pbMessage("Se desactivó el repelente infinito.")
    $bag.replace_item(:INFREPEL, :INFREPELOFF)
    $bag.replace_registered(:INFREPEL, :INFREPELOFF)
  end
  $PokemonGlobal.infRepel = !$PokemonGlobal.infRepel
  return 0
end

ItemHandlers::UseFromBag.add(:INFREPEL,proc{|item| pbToggleInfiniteRepel() })
ItemHandlers::UseFromBag.add(:INFREPELOFF,proc{|item| pbToggleInfiniteRepel() })
ItemHandlers::UseInField.add(:INFREPEL,proc{|item| pbToggleInfiniteRepel() })
ItemHandlers::UseInField.add(:INFREPELOFF,proc{|item| pbToggleInfiniteRepel() })
ItemHandlers::UseText.add(:INFREPEL, proc { |item| next _INTL("Desactivar")})
ItemHandlers::UseText.add(:INFREPELOFF, proc { |item| next _INTL("Activar")})

alias pbBattleOnStepTakenOverride pbBattleOnStepTaken 
def pbBattleOnStepTaken(repel_active)
  $PokemonGlobal.infRepel ||= false
  repel = ($PokemonGlobal.infRepel || $PokemonGlobal.repel > 0 || repel_active) ? true : false
  pbBattleOnStepTakenOverride(repel)
end

==============================================================================
# Script: Marin's Map Exporter
==============================================================================
#==============================================================================#
#                              Map Exporter                                    #
#                                by Marin                                      #
#==============================================================================#
# Manually export a map using `pbExportMap(id)`, or go into the Debug menu and #
#            choose the `Export a Map` option that is now in there.            #
#                                                                              #
#  `pbExportMap(id, options)`, where `options` is an array that can contain:   #
#       - :events  ->  This will also export all events present on the map     #
#       - :player  ->  This will also export the player if they're on that map #
#  `id` can be nil, which case it will use the current map the player is on.   #
#==============================================================================#
#                    Please give credit when using this.                       #
#==============================================================================#

# This is where the map will be exported to once it has been created.
# If this file already exists, it is overwritten.
EXPORTEDMAPBASENAME = "MapExporter/MAPA_EXPORTADO_"



def pbExportMap(id = nil, options = [])
  mapExporter = MarinMapExporter.new(id, options)
  return mapExporter.exported_file
end

def pbExportAMap
  vp = Viewport.new(0, 0, Graphics.width, Graphics.height)
  vp.z = 99999
  s = Sprite.new(vp)
  s.bitmap = Bitmap.new(Graphics.width, Graphics.height)
  s.bitmap.fill_rect(0, 0, Graphics.width, Graphics.height, Color.new(0,0,0))
  mapid = pbListScreen(_INTL("Exportar Mapa"),MapLister.new(pbDefaultMap))
  if mapid > 0
    player = $game_map.map_id == mapid
    if player
      cmds = [_INTL("Exportar"), _INTL("[  ] Eventos"), _INTL("[  ] Jugador"), _INTL("Cancelar")]
    else
      cmds = [_INTL("Exportar"), _INTL("[  ] Eventos"), _INTL("Cancelar")]
    end
    cmd = 0
    loop do
      cmd = pbShowCommands(nil,cmds,-1,cmd)
      if cmd == 0
        Graphics.update
        options = []
        options << :events if cmds[1].split("")[1] == "X"
        options << :player if player && cmds[2].split("")[1] == "X"
        msgwindow = Window_AdvancedTextPokemon.newWithSize(
            _INTL("Guardando... Por favor, espera."),
            0, Graphics.height - 96, Graphics.width, 96, vp
        )
        msgwindow.setSkin(MessageConfig.pbGetSpeechFrame)
        Graphics.update
        exported_file = pbExportMap(mapid, options)
        msgwindow.setText(_INTL("El mapa se ha exportado como #{exported_file}"))
        60.times { Graphics.update; Input.update }
        #pbDisposeMessageWindow(msgwindow)
        break
      elsif cmd == 1
        if cmds[1].split("")[1] == " "
          cmds[1] = _INTL("[X] Eventos")
        else
          cmds[1] = _INTL("[  ] Eventos")
        end
      elsif cmd == 2 && player
        if cmds[2].split("")[1] == " "
          cmds[2] = _INTL("[X] Jugador")
        else
          cmds[2] = _INTL("[  ] Jugador")
        end
      elsif cmd == 3 || cmd == 2 && !player || cmd == -1
        break
      end
    end
  end
  s.bitmap.dispose
  s.dispose
  vp.dispose
end

MenuHandlers.add(:debug_menu,:exportmap, {
  "parent"      => :field_menu,
  "name"        => _INTL("Exporta un Mapa"),
  "description" => _INTL("Elige un mapa para exportarlo como PNG."),
  "effect"      => proc { |sprites, viewport|
    pbExportAMap
  }
})

class MarinMapExporter
  attr_accessor :exported_file
  def initialize(id = nil, options = [])
    @exported_file = nil
    @id = id || $game_map.map_id
    @options = options
    @data = load_data("Data/Map#{@id.to_digits}.rxdata")
    @tiles = @data.data
    @result = Bitmap.new(32 * @tiles.xsize, 32 * @tiles.ysize)
    @tilesetdata = load_data("Data/Tilesets.rxdata")
    tilesetname = @tilesetdata[@data.tileset_id].tileset_name
    @tileset = Bitmap.new("Graphics/Tilesets/#{tilesetname}")
    @autotiles = @tilesetdata[@data.tileset_id].autotile_names
        .filter { |e| e && e.size > 0 }
        .map { |e| Bitmap.new("Graphics/Autotiles/#{e}") }
    for z in 0..2
      for y in 0...@tiles.ysize
        for x in 0...@tiles.xsize
          id = @tiles[x, y, z]
          next if id == 0
          if id < 384 # Autotile
            build_autotile(@result, x * 32, y * 32, id)
          else # Normal tile
            @result.blt(x * 32, y * 32, @tileset,
                Rect.new(32 * ((id - 384) % 8),32 * ((id - 384) / 8).floor,32,32))
          end
        end
      end
    end
    if @options.include?(:events)
      keys = @data.events.keys.sort { |a, b| @data.events[a].y <=> @data.events[b].y }
      keys.each do |id|
        event = @data.events[id]
        page = pbGetActiveEventPage(event, @id)
        if page && page.graphic && page.graphic.character_name && page.graphic.character_name.size > 0
          bmp = Bitmap.new("Graphics/Characters/#{page.graphic.character_name}")
          if bmp
            bmp = bmp.clone
            bmp.hue_change(page.graphic.character_hue) unless page.graphic.character_hue == 0
            ex = bmp.width / 4 * page.graphic.pattern
            ey = bmp.height / 4 * (page.graphic.direction / 2 - 1)
            @result.blt(event.x * 32 + 16 - bmp.width / 8, (event.y + 1) * 32 - bmp.height / 4, bmp,
                Rect.new(ex, ey, bmp.width / 4, bmp.height / 4))
          end
          bmp = nil
        end
      end
    end
    if @options.include?(:player) && $game_map.map_id == @id && $game_player.character_name &&
       $game_player.character_name.size > 0
      bmp = Bitmap.new("Graphics/Characters/#{$game_player.character_name}")
      dir = $game_player.direction
      @result.blt($game_player.x * 32 + 16 - bmp.width / 8, ($game_player.y + 1) * 32 - bmp.height / 4,
          bmp, Rect.new(0, bmp.height / 4 * (dir / 2 - 1), bmp.width / 4, bmp.height / 4))
    end
    @exported_file = "#{EXPORTEDMAPBASENAME}#{Time.now.strftime('%d_%m_%YT%H_%M_%S')}.png"  
    Dir.mkdir("MapExporter") if !Dir.exists?("MapExporter")
    @result.save_to_png(@exported_file)
    Input.update
  end
  
  def build_autotile(bitmap, x, y, id)
    autotile = @autotiles[id / 48 - 1]
    return unless autotile
    if autotile.height == 32
      bitmap.blt(x,y,autotile,Rect.new(0,0,32,32))
    else
      id %= 48
      tiles = TileDrawingHelper::AUTOTILE_PATTERNS[id >> 3][id & 7]
      src = Rect.new(0,0,0,0)
      halfTileWidth = halfTileHeight = halfTileSrcWidth = halfTileSrcHeight = 32 >> 1
      for i in 0...4
        tile_position = tiles[i] - 1
        src.set((tile_position % 6) * halfTileSrcWidth,
           (tile_position / 6) * halfTileSrcHeight, halfTileSrcWidth, halfTileSrcHeight)
        bitmap.blt(i % 2 * halfTileWidth + x, i / 2 * halfTileHeight + y,
            autotile, src)
      end
    end
  end
end

==============================================================================
# Script: Overworld Shadows EX
==============================================================================
#===============================================================================
# CREDITOS
# Golisopod User, Wolf PP, Marin, Zik
# Website    = https://www.youtube.com/watch?v=dQw4w9WgXcQ
#===============================================================================
module OWShadowSettings
  
  # If true, calculates the shadow size based on the sprite's pixels.
  # If false, uses the size defined in FIXED_SHADOW_SIZE for all.
  AUTOMATIC_SHADOW_GENERATION = false

  # Fixed shadow size when automatic generation is disabled (false).
  # A value of 10 to 14 is standard for normal-sized characters.
  FIXED_SHADOW_SIZE = 12

  # ============================================================================
  # Set this to true if you want the event name and character name blacklists to be case sensitive.
  CASE_SENSITIVE_BLACKLISTS = false

  # If an event name contains one of these words, it will not have a shadow.
  SHADOWLESS_EVENT_NAME     = [
    "door", "FlechaSalida", "nurse", "Enfermera", "Healing balls", "Balls curativas", "Mart","Tendero", "SmashRock", "RocaRompible", "StrengthBoulder", "PiedraFuerza",
    "CutTree", "ArbolCorte", "HeadbuttTree", "ArbolGolpeCabeza", "BerryPlant", "Planta Bayas", ".shadowless", ".noshadow", ".sl", "Entrada Mazmorra Bosque", "Entrada Cueva", "Relic Stone",
    "Escalera", "Puerta", "ExitArrow", "NoShadow"
  ]

  # If the character file and event uses contains one of these words in its filename, it will not have a shadow.
  SHADOWLESS_CHARACTER_NAME = ["nil"]

  # If an event stands on a tile with one of these terrain tags, it will not have a shadow.
  # (Names can be seen in the script section "Terrain Tag")
  SHADOWLESS_TERRAIN_NAME   = [
    :Grass, :DeepWater, :StillWater, :Water, :Waterfall, :WaterfallCrest,
    :Puddle
  ]

  # Hash to adjust the shadow radius for specific character files.
  # Key: Part of the filename (e.g., "PIKACHU").
  # Value: [RADIUS, X, Y]
  CHARACTER_SHADOW_FIX = {
    "PIKACHU" => [-2, 0, 0],
    "SNORLAX" => [8, 0, 0],
  }
end

#-------------------------------------------------------------------------------
# New Class for Shadow object
#-------------------------------------------------------------------------------
class Sprite_OWShadow
  attr_reader :visible
  #-----------------------------------------------------------------------------
  # Initialize a shadow sprite based on the name of the event
  #-----------------------------------------------------------------------------
  def initialize(sprite, event, viewport = nil)
    @rsprite  = sprite
    @event    = event
    @viewport = viewport
    @sprite   = Sprite.new(viewport)
    @disposed = false
    @remove   = false
    @fix_radius = 0
    @fix_x      = 0
    @fix_y      = 0
    
    # Store data for both directions
    @shadow_data_down = nil
    @shadow_data_up   = nil
    
    # Track character/bitmap changes to regenerate shadow when needed
    @last_character_name = nil
    @last_bitmap = nil  # Track the actual bitmap object
    
    update
  end
  #-----------------------------------------------------------------------------
  # Helper to calculate coordinates for a specific row
  #-----------------------------------------------------------------------------
  def get_frame_coordinates(row_direction)
    rect = @rsprite.src_rect
    bitmap = @rsprite.bitmap
    
    # Si el src_rect tiene las dimensiones completas del bitmap, calculamos el tamaño del frame
    # dividiendo por 4 (formato estándar de spritesheets 4x4)
    if rect.width == bitmap.width && rect.height == bitmap.height
      cw = bitmap.width / 4
      ch = bitmap.height / 4
    else
      cw = rect.width
      ch = rect.height
    end
    
    sx = 0
    sy = 0   

    if @event.respond_to?(:character_name) && @event.character_name && !@event.character_name.empty?
      # Detect single sheet: starts with $ or !, OR is a Follower sprite
      char_name = @event.character_name
      is_single_sheet = char_name[/^[\$\!]./] ? true : false
      is_single_sheet = true if char_name.downcase.include?("follower")
      
      if is_single_sheet
        sx = 0
        sy = ch * row_direction
      else
        idx = (@event.respond_to?(:character_index) ? @event.character_index : 0)
        char_col = idx % 4
        char_row = idx / 4        
        frames_per_char = (bitmap.width / cw) / 4
        frames_per_char = 4 if frames_per_char < 1        
        sx = char_col * (frames_per_char * cw)
        sy = (char_row * (4 * ch)) + (ch * row_direction)
      end
    end    

    if sx + cw > bitmap.width || sy + ch > bitmap.height
      return rect.x, rect.y
    end   

    return sx, sy
  end
  #-----------------------------------------------------------------------------
  # Analyzes pixel density to ignore thin adornments
  #-----------------------------------------------------------------------------
  def analyze_footprint(bitmap, sx, sy, cw, ch)
    # Settings for "Smart" detection
    scan_height = 12
    density_threshold = 3
    
    scan_y_start = [ch - scan_height, 0].max
    scan_y_end   = ch
    
    min_x = cw
    max_x = 0
    found_body = false

    (0...cw).each do |x|
      pixel_count = 0
      (scan_y_start...scan_y_end).each do |y|
        next if (sx + x) >= bitmap.width || (sy + y) >= bitmap.height
        if bitmap.get_pixel(sx + x, sy + y).alpha > 20 # Tolerance for semi-transparency
          pixel_count += 1
        end
      end
      
      # If this has enough "mass", it's the start of the body
      if pixel_count >= density_threshold
        min_x = x
        found_body = true
        break
      end
    end

    if found_body
      (0...cw).to_a.reverse.each do |x|
        pixel_count = 0
        (scan_y_start...scan_y_end).each do |y|
          next if (sx + x) >= bitmap.width || (sy + y) >= bitmap.height
          if bitmap.get_pixel(sx + x, sy + y).alpha > 20
            pixel_count += 1
          end
        end
        
        if pixel_count >= density_threshold
          max_x = x
          break
        end
      end
      
      real_width = max_x - min_x + 1
      
      # Calculate Offset
      feet_center = min_x + (real_width / 2.0)
      frame_center = cw / 2.0
      offset_x = feet_center - frame_center
      
      return real_width, offset_x
    else
      return fallback_scan(bitmap, sx, sy, cw, ch)
    end
  end
  #-----------------------------------------------------------------------------
  # Fallback scan for sprites with very thin legs/floating
  #-----------------------------------------------------------------------------
  def fallback_scan(bitmap, sx, sy, cw, ch)
    scan_y_start = [ch - 8, 0].max
    scan_y_end = ch
    min_x = cw
    max_x = 0
    found = false
    
    (0...cw).each do |x|
      (scan_y_start...scan_y_end).each do |y|
        next if (sx + x) >= bitmap.width || (sy + y) >= bitmap.height
        if bitmap.get_pixel(sx + x, sy + y).alpha > 0
          min_x = x
          found = true
          break
        end
      end
      break if found
    end
    
    if found
      (0...cw).to_a.reverse.each do |x|
        (scan_y_start...scan_y_end).each do |y|
          next if (sx + x) >= bitmap.width || (sy + y) >= bitmap.height
          if bitmap.get_pixel(sx + x, sy + y).alpha > 0
            max_x = x
            break
          end
        end
        break if max_x > 0
      end
      real_width = max_x - min_x + 1
      feet_center = min_x + (real_width / 2.0)
      frame_center = cw / 2.0
      return real_width, (feet_center - frame_center)
    end
    
    return cw, 0
  end
  #-----------------------------------------------------------------------------
  # Generate a shadow bitmap and offset
  #-----------------------------------------------------------------------------
  def generate_shadow_data(row_direction)
    return nil if !@rsprite.bitmap || @rsprite.disposed?
    
    bitmap = @rsprite.bitmap
    rect = @rsprite.src_rect
    
    # Si el src_rect tiene las dimensiones completas del bitmap, calculamos el tamaño del frame
    # dividiendo por 4 (formato estándar de spritesheets 4x4)
    if rect.width == bitmap.width && rect.height == bitmap.height
      cw = bitmap.width / 4
      ch = bitmap.height / 4
    else
      cw = rect.width
      ch = rect.height
    end
    
    # Get coordinates for the specific frame (Down or Up)
    sx, sy = get_frame_coordinates(row_direction)

    if OWShadowSettings::AUTOMATIC_SHADOW_GENERATION
      real_width, offset_x = analyze_footprint(bitmap, sx, sy, cw, ch)
      logical_width = (real_width * 0.9 / 2).ceil + 4
    else
      offset_x = 0
      logical_width = OWShadowSettings::FIXED_SHADOW_SIZE
    end

    # Apply Character Fix
    if OWShadowSettings::AUTOMATIC_SHADOW_GENERATION
      real_width, offset_x = analyze_footprint(bitmap, sx, sy, cw, ch)
      logical_width = (real_width * 0.9 / 2).ceil + 4
    else
      offset_x = 0
      logical_width = OWShadowSettings::FIXED_SHADOW_SIZE
    end
    
    # Apply Character Radius Fix
    logical_width += @fix_radius    
    logical_width = [logical_width, 8].max
    logical_width -= 1 if logical_width.odd?    
    logical_height = (logical_width * 0.5).ceil
    logical_height = [logical_height, 4].max
    logical_height += 1 if logical_height.odd?
    
    bmp = Bitmap.new(logical_width * 2, logical_height * 2)
    color = Color.new(0, 0, 0, 80)
    
    cx = logical_width / 2.0 - 0.5
    cy = logical_height / 2.0 - 0.5
    rx = logical_width / 2.0
    ry = logical_height / 2.0

    (0...logical_height).each do |y|
      (0...logical_width).each do |x|
        dx = (x - cx) / rx
        dy = (y - cy) / ry
        if (dx**2 + dy**2) <= 0.9
           bmp.fill_rect(x * 2, y * 2, 2, 2, color)
        end
      end
    end
    
    return { :bitmap => bmp, :offset => offset_x }
  end
  #-----------------------------------------------------------------------------
  # Invalidate shadow data to force regeneration
  #-----------------------------------------------------------------------------
  def invalidate_shadow_data
    @shadow_data_down[:bitmap].dispose if @shadow_data_down && @shadow_data_down[:bitmap]
    @shadow_data_up[:bitmap].dispose if @shadow_data_up && @shadow_data_up[:bitmap]
    @shadow_data_down = nil
    @shadow_data_up = nil
  end
  #-----------------------------------------------------------------------------
  # Override the bitmap of the shadow sprite
  #-----------------------------------------------------------------------------
  def set_bitmap(name)
    invalidate_shadow_data
    @sprite.dispose if @sprite && !@sprite.disposed?
    @sprite = nil
    @sprite = Sprite.new(@viewport)
    update
  end
  #-----------------------------------------------------------------------------
  # Dispose the shadow bitmap
  #-----------------------------------------------------------------------------
  def dispose
    return if @disposed
    @sprite.dispose if @sprite
    @shadow_data_down[:bitmap].dispose if @shadow_data_down && @shadow_data_down[:bitmap]
    @shadow_data_up[:bitmap].dispose if @shadow_data_up && @shadow_data_up[:bitmap]
    @sprite = nil
    @disposed = true
  end
  #-----------------------------------------------------------------------------
  # Check whether the shadow has been disposed
  #-----------------------------------------------------------------------------
  def disposed?; return @disposed; end
  #-----------------------------------------------------------------------------
  # Calculation of shadow size and position
  #-----------------------------------------------------------------------------
  def update
    return if disposed? || !$scene.is_a?(Scene_Map)
    @sprite = Sprite.new(@viewport) if !@sprite
    
    # Check if character graphic or bitmap changed - if so, regenerate shadow
    current_char_name = @event.respond_to?(:character_name) ? @event.character_name : nil
    current_bitmap = @rsprite.bitmap
    
    # Invalidate if character name changed
    if current_char_name != @last_character_name
      @last_character_name = current_char_name
      @fix_radius = 0
      @fix_x      = 0
      @fix_y      = 0
      if current_char_name
        OWShadowSettings::CHARACTER_SHADOW_FIX.each do |key, value|
          if current_char_name.include?(key)
            @fix_radius = value[0]
            @fix_x      = value[1]
            @fix_y      = value[2]
            break
          end
        end
      end
      
      invalidate_shadow_data
    end
    
    # Invalidate if bitmap object changed (happens when events are created by code)
    if current_bitmap != @last_bitmap
      @last_bitmap = current_bitmap
      invalidate_shadow_data
    end
    
    # Generate shadow data if needed
    if (!@shadow_data_down || !@shadow_data_up) && @rsprite.bitmap && !@rsprite.disposed?
      @shadow_data_down = generate_shadow_data(0) # Row 0: Down
      @shadow_data_up   = generate_shadow_data(3) # Row 3: Up
    end
    
    return unless @shadow_data_down # Wait until generation is successful

    is_floating = @event.respond_to?(:is_floating) && @event.is_floating
    float_offset = (is_floating && @event.respond_to?(:float_offset)) ? @event.float_offset : 0
    if @event.jumping?
      ground_y = (@event.real_y - $game_map.display_y + 3) / 4 + 32
      jump_offset = (ground_y - @rsprite.y).abs
    elsif is_floating
      ground_y = @rsprite.y + float_offset
      jump_offset = 0
    else
      ground_y = @rsprite.y
      jump_offset = 0
    end
    if @event.direction == 8 || @event.direction == 6
      current_data = @shadow_data_up
    else
      current_data = @shadow_data_down
    end
    current_data = @shadow_data_down if current_data.nil?

    s_off_x = (@event.respond_to?(:shadow_offset_x) ? @event.shadow_offset_x.to_i : 0)
    s_off_y = (@event.respond_to?(:shadow_offset_y) ? @event.shadow_offset_y.to_i : 0)
    @sprite.bitmap  = current_data[:bitmap]
    @sprite.x       = @rsprite.x + s_off_x + @fix_x
    @sprite.y       = ground_y + s_off_y + @fix_y
    @sprite.ox      = (current_data[:bitmap].width / 2) - current_data[:offset]
    @sprite.oy      = current_data[:bitmap].height
    @sprite.z       = @event.screen_z(current_data[:bitmap].height) - 1
    scale_factor = 1.0

    if @event.jumping?
      scale_factor = 1.0 - (jump_offset * 0.01)
    elsif is_floating
      scale_factor = 1.0 - (float_offset * 0.03)
    end

    scale_factor = 0.4 if scale_factor < 0.4
    scale_factor = 1.2 if scale_factor > 1.2

    @sprite.zoom_x  = @rsprite.zoom_x * scale_factor
    @sprite.zoom_y  = @rsprite.zoom_y * scale_factor
    
    @sprite.opacity = @rsprite.opacity
    @sprite.visible = @rsprite.visible && @event.shows_shadow?
  end
end

#-------------------------------------------------------------------------------
# New Method for setting shadow of any event given the map id and event id
#-------------------------------------------------------------------------------
def pbSetOverworldShadow(name, event_id = nil, map_id = nil)
  return if !$scene.is_a?(Scene_Map)
  return if nil_or_empty?(name)
  if !event_id
    $scene.spritesetGlobal.playersprite.ow_shadow.set_bitmap(name)
  else
    map_id = $game_map.map_id if !map_id
    $scene.spritesets[map_id].character_sprites[(event_id - 1)].ow_shadow.set_bitmap(name)
  end
end

#-------------------------------------------------------------------------------
# Referencing and initializing Shadow Sprite in Sprite_Character
#-------------------------------------------------------------------------------
class Sprite_Character
  attr_accessor :ow_shadow
  #-----------------------------------------------------------------------------
  # Initializing Shadow with Character
  #-----------------------------------------------------------------------------
  alias __ow_shadow__initialize initialize unless private_method_defined?(:__ow_shadow__initialize)
  def initialize(*args)
    __ow_shadow__initialize(*args)
    @ow_shadow = Sprite_OWShadow.new(self, args[1], args[0])
    update
  end
  #-----------------------------------------------------------------------------
  # Disposing Shadow with Character
  #-----------------------------------------------------------------------------
  alias __ow_shadow__dispose dispose unless method_defined?(:__ow_shadow__dispose)
  def dispose(*args)
    __ow_shadow__dispose(*args)
    @ow_shadow.dispose if @ow_shadow
    @ow_shadow = nil
  end
  #-----------------------------------------------------------------------------
  # Updating Shadow with Character
  #-----------------------------------------------------------------------------
  alias __ow_shadow__update update unless method_defined?(:__ow_shadow__update)
  def update(*args)
    __ow_shadow__update(*args)
    return if !@ow_shadow
    @ow_shadow.update
  end
end

#-------------------------------------------------------------------------------
# Adding shadow checking method to Game_Event
#-------------------------------------------------------------------------------
class Game_Character
  attr_reader :jump_count
  attr_reader :jump_distance
  attr_reader :jump_distance_left
  attr_reader :jump_peak
  #-----------------------------------------------------------------------------
  # Initializing Shadow with event
  #-----------------------------------------------------------------------------
  alias __ow_shadow__initialize initialize unless private_method_defined?(:__ow_shadow__initialize)
  def initialize(*args)
    __ow_shadow__initialize(*args)
    @shows_shadow = false
  end
  #-----------------------------------------------------------------------------
  # Updating Shadow with Character
  #-----------------------------------------------------------------------------
  alias __ow_shadow__calculate_bush_depth calculate_bush_depth unless method_defined?(:__ow_shadow__calculate_bush_depth)
  def calculate_bush_depth(*args)
    __ow_shadow__calculate_bush_depth(*args)
    @shows_shadow = shows_shadow?(true)
  end
  #-----------------------------------------------------------------------------
  # Check whether the character should have a shadow
  #-----------------------------------------------------------------------------
  def shows_shadow?(recalc = false)
    return @shows_shadow if !recalc
    return false if nil_or_empty?(self.character_name) || self.transparent
    if OWShadowSettings::CASE_SENSITIVE_BLACKLISTS
      return false if OWShadowSettings::SHADOWLESS_CHARACTER_NAME.any?{ |e| self.character_name[/#{e}/] }
      return false if self.respond_to?(:name) && OWShadowSettings::SHADOWLESS_EVENT_NAME.any? { |e| self.name[/#{e}/]}
    else
      return false if OWShadowSettings::SHADOWLESS_CHARACTER_NAME.any?{ |e| self.character_name[/#{e}/i] }
      return false if self.respond_to?(:name) && OWShadowSettings::SHADOWLESS_EVENT_NAME.any? { |e| self.name[/#{e}/]}
    end
    terrain = $game_map.terrain_tag(self.x, self.y)
    return false if OWShadowSettings::SHADOWLESS_TERRAIN_NAME.any? { |e| terrain == e } if terrain
    return true
  end
  #-----------------------------------------------------------------------------
  # Updating Shadows when transparency is changed
  #-----------------------------------------------------------------------------
  alias __ow_shadow__transparent_set transparent= unless method_defined?(:__ow_shadow__transparent_set)
  def transparent=(*args)
    __ow_shadow__transparent_set(*args)
    @shows_shadow = shows_shadow?(true)
  end
  #-----------------------------------------------------------------------------
end

#-------------------------------------------------------------------------------
# Updating Shadow with Character
#-------------------------------------------------------------------------------
class Game_Event
  alias __ow_shadow__refresh refresh unless method_defined?(:__ow_shadow__refresh)
  def refresh(*args)
    ret = __ow_shadow__refresh(*args)
    @shows_shadow = shows_shadow?(true)
    return ret
  end
end

class Game_Player
  #-----------------------------------------------------------------------------
  # Updating Shadow with Player's Movement
  #-----------------------------------------------------------------------------
  alias __ow_shadow__set_movement_type set_movement_type unless method_defined?(:__ow_shadow__set_movement_type)
  def set_movement_type(*args)
    ret = __ow_shadow__set_movement_type(*args)
    @shows_shadow = shows_shadow?(true)
    return ret
  end
  #-----------------------------------------------------------------------------
end

