==============================================================================
# Script: Pokevial
==============================================================================
#===============================================================================
# CREDITOS
# Voltseon, DPertierra, lavinytuttini
#===============================================================================
class PokemonGlobalMetadata
    attr_accessor :vial_charges
    attr_accessor :max_vial_charges
    attr_accessor :vial_locked
end

INITIAL_CHARGES_POKEVIAL = 1 
INFINITE_POKEVIAL = false

ItemHandlers::UseFromBag.add(:VIAL, proc { |item| use_pokevial; next 1 })
ItemHandlers::UseInField.add(:VIAL, proc { |item| use_pokevial; next 1 })

def init_pokevial
  $PokemonGlobal.vial_charges ||= INITIAL_CHARGES_POKEVIAL
  $PokemonGlobal.max_vial_charges ||= INITIAL_CHARGES_POKEVIAL
  $PokemonGlobal.vial_locked ||= false
end

def lock_vial
  return unless ensure_pokevial_initialized
  $PokemonGlobal.vial_locked = true
  pbMessage(_INTL("El Curaportátil ha sido bloqueado."))
end

def unlock_vial
  return unless ensure_pokevial_initialized
  $PokemonGlobal.vial_locked = false
  pbMessage(_INTL("El Curaportátil ha sido desbloqueado."))
end

def ensure_pokevial_initialized
  return false unless has_player_pokevial
  init_pokevial
  true
end

def has_player_pokevial
  $bag.has?(:VIAL) || $bag.has?(:EMPTYVIAL)
end


def show_message_pokevial
  if $PokemonGlobal.vial_charges <= 0
    pbMessage(_INTL("El Curaportátil está vacío. Recárgalo en el Centro Pokémon."))
    return false
  end
  if !INFINITE_POKEVIAL
    pbMessage(_INTL("Tienes {1} {2} {3} de un máximo de {4}.",
      $PokemonGlobal.vial_charges,
      $PokemonGlobal.vial_charges == 1 ? _INTL("curación") : _INTL("curaciones"),
      $PokemonGlobal.vial_charges == 1 ? _INTL("disponible") : _INTL("disponibles"),
      $PokemonGlobal.max_vial_charges))
  end
  true
end

def max_vial_charges
  ensure_pokevial_initialized
  $PokemonGlobal.max_vial_charges || 0
end

def vial_charges
  ensure_pokevial_initialized
  $PokemonGlobal.vial_charges || 0
end

def vial_full?
  ensure_pokevial_initialized
  $PokemonGlobal.vial_charges == $PokemonGlobal.max_vial_charges
end


def use_pokevial
  return unless ensure_pokevial_initialized
  if $PokemonGlobal.vial_locked
    pbMessage(_INTL("El Curaportátil está bloqueado."))
    return
  end
  return unless show_message_pokevial
  if pbConfirmMessage(_INTL("¿Quieres curar a tu equipo?"))
    heal_party_with_pokevial
  end
end

def heal_party_with_pokevial
  $player.heal_party
  pbMEPlay("Pkmn healing")
  pbMessage(_INTL("¡Tu equipo Pokémon se ha curado al completo!"))
  $PokemonGlobal.vial_charges -= 1 if !INFINITE_POKEVIAL
  $bag.replace_item(:VIAL, :EMPTYVIAL) if $PokemonGlobal.vial_charges <= 0
end

def recharge_vial
    return unless ensure_pokevial_initialized
    $PokemonGlobal.vial_charges = $PokemonGlobal.max_vial_charges
    pbMessage(_INTL("¡Tu Curaportátil ha sido recargado!")) if !INFINITE_POKEVIAL
    $bag.replace_item(:EMPTYVIAL,:VIAL) if $bag.has?(:EMPTYVIAL)
end

def add_new_vial_charge
    return unless ensure_pokevial_initialized || INFINITE_POKEVIAL
    $PokemonGlobal.max_vial_charges += 1
    # Se hace de esta forma para que recibir una nueva carga no restaure completamente el vial
    $PokemonGlobal.vial_charges += 1
    pbMessage(_INTL("¡Ahora tu Curaportátil puede almacenar {1} carga#{$PokemonGlobal.max_vial_charges > 1 ? 's' : ''}!",$PokemonGlobal.max_vial_charges))
end

def remove_vial_charge
  return unless ensure_pokevial_initialized || INFINITE_POKEVIAL
  if $PokemonGlobal.max_vial_charges > 1
    $PokemonGlobal.max_vial_charges -= 1
    # Se hace de esta forma para que al eliminar una carga no restaure completamente el vial
    $PokemonGlobal.vial_charges -= 1 if $PokemonGlobal.vial_charges > 0
    pbMessage(_INTL("¡Ahora tu Curaportátil puede almacenar {1} carga#{$PokemonGlobal.max_vial_charges > 1 ? 's' : ''}!", 
                           $PokemonGlobal.max_vial_charges))
  end
end


==============================================================================
# Script: Species Introduction
==============================================================================
#===============================================================================
# * Show Species Introdution - by FL (Credits will be apreciated)
#===============================================================================
#
# This script is for Pokémon Essentials. It shows a picture with the pokémon
# species in a border together with a message containing the name and kind, play
# it's cry and mark it as seen in pokédex. Good to make the starter selection
# event. 
#
#== INSTALLATION ===============================================================
#
# Put it above main OR convert into a plugin.
#
#== HOW TO USE =================================================================
#
# Use 'SpeciesIntro.new(sp).show', where sp is the species symbol.
#
#== NOTES ======================================================================
#
# You can look and change SpeciesIntro instance atributes, directly or by
# methods. This way you can change the sprite gender and other effects. Look at
# below examples:
#
#== EXAMPLES ===================================================================
#
# - Show Chikorita:
#
# SpeciesIntro.new(:CHIKORITA).show
#
# - Show shiny west Shellos, without registering at Pokédex as seen:
#
# SpeciesIntro.new(:SHELLOS_1).set_shiny(true).set_mark_as_seen(false).show
#
# - Show shiny Speed Deoxys, with custom message:
#
# si = SpeciesIntro.new(:DEOXYS)
# si.form = 3
# si.shiny = true
# si.message_complement = ".\nAn dangerous alien."
# si.show
#
#===============================================================================

if defined?(PluginManager) && !PluginManager.installed?("Show Species Introduction")
  PluginManager.register({                                                 
    :name    => "Show Species Introduction",                                        
    :version => "1.1",                                                     
    :link    => "https://www.pokecommunity.com/showthread.php?t=504992",             
    :credits => "FL"
  })
end

class SpeciesIntro
  attr_accessor :species
  attr_accessor :form
  attr_accessor :gender
  attr_accessor :shiny
  attr_accessor :shadow
  attr_accessor :mark_as_seen
  attr_accessor :message_complement
  
  def set_form(form)
    @form = form
    return self
  end
  
  def set_gender(gender)
    @gender = gender
    return self
  end
  
  def set_shiny(shiny)
    @shiny = shiny
    return self
  end
  
  def set_shadow(shadow)
    @shadow = shadow
    return self
  end
  
  def set_mark_as_seen(mark_as_seen)
    @mark_as_seen = mark_as_seen
    return self
  end

  def initialize(species)
    species_and_form = Bridge.species_and_form(species)
    @species = species_and_form[0]
    @form = species_and_form[1]
    @gender = 0
    @mark_as_seen = true
  end

  def name
    return Bridge.species_name(@species)
  end

  def category
    return Bridge.species_category(@species, @form)
  end
  
  def set_message_complement(message_complement)
    @message_complement = message_complement
    return self
  end
  
  def text_message
    ret = name
    ret += @message_complement || _INTL(". El Pokémon {1}.", category)
    return ret
  end

  def create_picture_icon(bitmap)
    ret = PictureWindow.new(bitmap)
    if PluginManager.installed?("Sprites Animados") || PluginManager.installed?("[DBK] Animated Pokémon System")
      ret.width = ret.height
      ret.zoom_x = ret.zoom_x * 2
      ret.zoom_y = ret.zoom_y * 2
      ret.x = (Graphics.width/2)
      ret.x = ret.x/2
      ret.x -= (ret.width/2)
      ret.y = ((Graphics.height-96)/2)
      ret.y = ret.y/2
      ret.y -= (ret.height/2)
      #ret.y += 10
    else
      ret.x = (Graphics.width/2) - (ret.width/2)
      ret.y = ((Graphics.height-96)/2) - (ret.height/2)
    end
    return ret
  end

  def show
    if @mark_as_seen
      Bridge.register_as_seen(@species, @form, @gender, @shiny)
    end
    bitmap = Bridge.pokemon_front_sprite_filename(
      @species, @form, @gender, @shiny, @shadow
    )
    Bridge.play_cry(@species, @form)
    if bitmap # to prevent crashes
      iconwindow = create_picture_icon(bitmap)
      Bridge.message(text_message)
      iconwindow.dispose
    end
  end

  module Bridge
    module_function

    def major_version
      ret = 0
      if defined?(Essentials)
        ret = Essentials::VERSION.split(".")[0].to_i
      elsif defined?(ESSENTIALS_VERSION)
        ret = ESSENTIALS_VERSION.split(".")[0].to_i
      elsif defined?(ESSENTIALSVERSION)
        ret = ESSENTIALSVERSION.split(".")[0].to_i
      end
      return ret
    end

    MAJOR_VERSION = major_version

    def message(string, &block)
      return Kernel.pbMessage(string, &block) if MAJOR_VERSION < 20
      return pbMessage(string, &block)
    end

    def species_name(species)
      return PBSpecies.getName(species) if MAJOR_VERSION < 19
      return GameData::Species.get(species).name
    end

    def species_category(species, form)
      if MAJOR_VERSION < 19
        ret = pbGetMessage(
          MessageTypes::Kinds, fspecies_from_form_v18_minus(species, form)
        )
        ret ||= pbGetMessage(MessageTypes::Kinds, species)
        return ret
      end
      return GameData::Species.get_species_form(species, form).category
    end

    def species_and_form(species_full)
      return [getID(PBSpecies, species_full), 0] if MAJOR_VERSION < 17
      if MAJOR_VERSION < 19
        return pbGetSpeciesFromFSpecies(getID(PBSpecies, species_full))
      end
      species_form = GameData::Species.get_species_form(species_full, 0)
      return [species_form.species, species_form.form]
    end

    def pokemon_front_sprite_filename(species, form, gender, shiny, shadow)
      if MAJOR_VERSION < 19
        return pbCheckPokemonBitmapFiles([
          species, false, gender, shiny, form, shadow
        ])
      end
      return GameData::Species.front_sprite_filename(
        species, form, gender, shiny, shadow
      )
    end

    def register_as_seen(species, form, gender, shiny)
      if MAJOR_VERSION < 19
        $Trainer.seen[species]=true
        if MAJOR_VERSION >= 17
          pbSeenForm(fspecies_from_form_v18_minus(species,form))
        end
        return
      end
      (MAJOR_VERSION<20 ? $Trainer : $player).pokedex.register(
        species, gender, form, shiny
      )
    end

    def play_cry(species, form)
      if MAJOR_VERSION < 19
        pbPlayCry(species)
        return
      end
      GameData::Species.play_cry_from_species(species, form)
    end

    def fspecies_from_form_v18_minus(species, form)
      return species if MAJOR_VERSION < 17
      return pbGetFSpeciesFromForm(species, form)
    end
  end
end

==============================================================================
# Script: Storage System Utilities
==============================================================================
#===============================================================================
# Storage Grabber
# By Swdfm
# Used For Storage Utilities
#===============================================================================
class StorageGrabber
  def initialize
    clear
  end
  
  #===============================================================================
  # Adds hovered over pokemon to held pokemon
  #===============================================================================
  def add_to(position, position_1)
    @mons.push([position, position_1])
  end

  #===============================================================================
  # Is the grabber holding a Pokemon?
  #===============================================================================
  def holding_anything?
    return !@mons.empty?
  end
  
  #===============================================================================
  # Sets the pivot (top left Pokemon)
  #===============================================================================
  def setPivot(selection)
    @pivot      = selection
    @mock_pivot = selection
  end
  
  #===============================================================================
  # Begins hovering phase
  #===============================================================================
  def do_with(selection)
    p_col = @pivot % PokemonBox::BOX_WIDTH
    p_row = (@pivot / PokemonBox::BOX_WIDTH).floor
    s_col = selection % PokemonBox::BOX_WIDTH
    s_row = (selection / PokemonBox::BOX_WIDTH).floor
    @mons = []
    f_row = [p_row, s_row].min # F stands for flow
    f_col = [p_col, s_col].min
    @mock_pivot = f_col + f_row * PokemonBox::BOX_WIDTH
    for i in 0...PokemonBox::BOX_WIDTH
      next if (i < p_col && i < s_col) || (i > p_col && i > s_col)
      for j in 0...PokemonBox::BOX_HEIGHT
        next if (j < p_row && j < s_row) || (j > p_row && j > s_row)
        add_to(i - f_col,  j - f_row)
      end
    end
  end
  
  #===============================================================================
  # Is the grabber carrying?
  #===============================================================================
  def carrying
    return @carrying
  end
  
  def carrying=(value)
    @carrying = value
  end
  
  #===============================================================================
  # Adds Pokémon and their positions (relative to top left) to @carried_mons
  #===============================================================================
  def pack_up(storage, box_num)
    ret   = []
    p_col = @mock_pivot % PokemonBox::BOX_WIDTH
    p_row = (@mock_pivot / PokemonBox::BOX_WIDTH).floor
    for i in @mons
      x, y = i
      sel  = (p_row + y) * PokemonBox::BOX_WIDTH + (p_col + x)
      pkmn = storage[box_num, sel]
      ret.push([pkmn, x, y])
    end
    @carried_mons = ret
    @source_box = box_num  # Track the source box
  end
  
  #===============================================================================
  # Gets storage index of carried mons for deletion
  #===============================================================================
  def get_carried_mons
    ret   = []
    p_col = @mock_pivot % PokemonBox::BOX_WIDTH
    p_row = (@mock_pivot / PokemonBox::BOX_WIDTH).floor
    for i in @carried_mons
      x = i[1] + p_col
      y = i[2] + p_row
      ret.push(y * PokemonBox::BOX_WIDTH + x)
    end
    return ret
  end
  
  #===============================================================================
  # Places mons in those positions
  # STOPS IF THERE IS NOT A SPACE FOR EVERY MON
  #===============================================================================
  def place_with_positions(storage, box_num, selection)
    s_col = selection % PokemonBox::BOX_WIDTH
    s_row = (selection / PokemonBox::BOX_WIDTH).floor
    can_place = true
    for i in @carried_mons
      col = s_col + i[1]
      if col >= PokemonBox::BOX_WIDTH
        can_place = false 
        next
      end
      row = s_row + i[2]
      if row >= PokemonBox::BOX_HEIGHT
        can_place = false
        next
      end
      pseudo_sel = row * PokemonBox::BOX_WIDTH + col
      can_place = false if storage[box_num, pseudo_sel] # Occupied
    end
    return can_place
  end
  
  #===============================================================================
  # Gets index number of mons proposed to be put in boxes in above def.
  #===============================================================================
  def get_new_carried_mons(selection)
    
    ret   = []
    s_col = selection % PokemonBox::BOX_WIDTH
    s_row = (selection / PokemonBox::BOX_WIDTH).floor
    for i in @carried_mons
      col = s_col + i[1]
      row = s_row + i[2]
      pseudo_sel = row * PokemonBox::BOX_WIDTH + col
      ret.push([pseudo_sel, i[0]])
    end
    return ret
  end
  
  #===============================================================================
  # Removes any poured Pokemon
  #===============================================================================
  def pour(count)
    return if count == 0
    to_del = get_new_carried_mons(0)
	  to_del = to_del.sort{ |a, b| a[0] <=> b[0] }
	  ret = @carried_mons.clone
    count.times do
      ret.pop
    end
  	@carried_mons = ret
  end
  
  #===============================================================================
  # Clears everything
  #===============================================================================
  def clear
    @mons         = []
    @pivot        = nil
    @mock_pivot   = nil
    @carrying     = false
    @carried_mons = []
    @source_box   = nil
  end
  
  #===============================================================================
  # Utilities
  #===============================================================================
  def mons
    return @mons
  end
  
  def mock_pivot
    return @mock_pivot
  end
  
  def contains_an_egg?
    for i in @carried_mons
      return true if i[0]&.egg?
    end
    return false
  end
  
  def carried_mons
    return @carried_mons
  end
  
  def source_box
    return @source_box
  end
end

