# 2. pbChooseList command enhancements
#-------------------------------------------------------------------------------
def commands_sortable_handle_input_enhancements(command, cmdwindow, cmdIfCancel, sortable)
  if Input.triggerex?(:F)
    searchTerm = pbOpenGenericListSearch
    if searchTerm
      command = [2, searchTerm]
      return command
    end
  end
