def pbChoosePokemonForTradePC(wanted, form = -1)
variableNumber = 1
nameVarNumber = 2
  wanted = GameData::Species.get(wanted).species
  @chosen = pbChooseTradablePokemonPC(variableNumber, nameVarNumber, wanted, form, proc { |pkmn, wanted_species|
  })
