class PokemonGlobalMetadata
  attr_accessor :eggs
  alias old_initialize initialize
  def initialize
    old_initialize
    @eggs ||= [nil,nil,nil,nil,nil,nil]
  end
end

#Box sprite of the hatcher
class EggSprite < Sprite
  
  EGG_X_OFFSET = 2
  EGG_Y_OFFSET = -5
  STEPS_X = 35
  STEPS_Y = 60
  TEXT_ALIGNMENT = :center
  SELECTION_RECT_X = 0
  SELECTION_RECT_Y = 0
  SELECTION_RECT_WIDTH = 68
  SELECTION_RECT_HEIGHT = 100

  def initialize(viewport,selected,pokemon, x, y)
    super(viewport)
    @sprites = {}
    @animframe = 0
    @curFrame = 0
    @pokemon = pokemon
    @selected = selected
    self.bitmap = Bitmap.new(68, 100)
    self.x = x
    self.y = y
    refresh
  end
  
  def refresh
    if @pokemon != nil
      @frameskip = 20
      steps = @pokemon.steps_to_hatch
      sprite = GameData::Species.egg_icon_filename(@pokemon.species, @pokemon.form)
      @frameskip = 15 if steps<10200
      @frameskip = 10 if steps<2550
      @frameskip = 5 if steps<1275
      @sprites["egg"] = AnimatedSprite.create(sprite,2,@frameskip,self.viewport)
      @sprites["egg"].x = self.x + EGG_X_OFFSET
      @sprites["egg"].y = self.y + EGG_Y_OFFSET
      @sprites["egg"].play
      base = Color.new(6,35,52)
      shadow= Color.new(169,179,184)
      pbSetSystemFont(self.bitmap)
      pbDrawTextPositions(self.bitmap,[[steps.to_s, STEPS_X, STEPS_Y, TEXT_ALIGNMENT, base,shadow]])
    end

    if @selected
      self.bitmap.blt(0,0,Bitmap.new("Graphics/Pictures/Egg Hatcher/selection"), Rect.new(SELECTION_RECT_X, SELECTION_RECT_Y, SELECTION_RECT_WIDTH, SELECTION_RECT_HEIGHT))
    end
  end

  def dispose
    super
    pbDisposeSpriteHash(@sprites)
  end
  
  def update
    pbUpdateSpriteHash(@sprites)
  end
end

#GlobalScene
class Hatcher
  TEXT_WIDTH = 183
  TEXT_HEIGHT = 183
  TEXT_X = 290
  TEXT_Y = 80
  EGG_START_X = 46
  EGG_X_SPACING = 80
  EGG_START_Y_FIRST = 46
  EGG_START_Y_LAST = 158
  TEXT_DESC_X = 0
  TEXT_DESC_Y = 10
  TEXT_DESC_WIDTH = 183
  def initialize
    if !$PokemonGlobal.eggs
      $PokemonGlobal.eggs ||= [nil,nil,nil,nil,nil,nil]
    end
    @viewport = Viewport.new(0,0,Graphics.width,Graphics.height)
    @viewport.z = 99999
    @sprites = {}
    @eggs = {}
    @index = 0
    
    @sprites["bg"] = Sprite.new(@viewport)
    @sprites["bg"].bitmap = Bitmap.new("Graphics/Pictures/Egg Hatcher/hatcherbg")

    @sprites["text"] = Sprite.new(@viewport)
    @sprites["text"].bitmap = Bitmap.new(TEXT_WIDTH,TEXT_HEIGHT)
    @sprites["text"].x = TEXT_X
    @sprites["text"].y = TEXT_Y
    pbSetSystemFont(@sprites["text"].bitmap)
    refresh
  end
  
  def refresh
    disposeEggs
    @sprites["text"].bitmap.clear
    eggs = $PokemonGlobal.eggs
    for index in 0..5
      if index < 3
        x = EGG_START_X + EGG_X_SPACING * index
        y = EGG_START_Y_FIRST
      else
        x = EGG_START_X + EGG_X_SPACING * (index - 3)
        y = EGG_START_Y_LAST
      end
      selected = (index == @index)? true : false
      @eggs["#{index}"] = EggSprite.new(@viewport,selected,eggs[index], x, y)
    end
    
    if eggs[@index] != nil
      pokemon = eggs[@index]
      steps = pokemon.steps_to_hatch
      eggstate = _INTL("Parece que va a tardar un buen rato en eclosionar.")
      eggstate = _INTL("¿Qué eclosionará de esto? No parece estar cerca de eclosionar.") if steps < 10_200
      eggstate = _INTL("Parece moverse ocasionalmente. Puede estar cerca de eclosionar.") if steps < 2550
      eggstate = _INTL("¡Se escuchan sonido desde dentro! ¡Eclosionará pronto!") if steps < 1275
      drawFormattedTextEx(@sprites["text"].bitmap,TEXT_DESC_X,TEXT_DESC_Y,TEXT_DESC_WIDTH,eggstate)
    else
      eggstate = _INTL("Selecciona una incubadora para añadir un Huevo.")
      drawFormattedTextEx(@sprites["text"].bitmap,TEXT_DESC_X,TEXT_DESC_Y,TEXT_DESC_WIDTH,eggstate)
    end
  end
  
  def disposeEggs
    @eggs.each_value{|egg|
      egg.dispose
    }
  end
  
  def dispose
    disposeEggs
    pbDisposeSpriteHash(@sprites)
    @viewport.dispose
  end
  
  def update
    loop do
      @eggs.each_value{|egg|
      egg.update
      }
      #Egg selector
      if Input.trigger?(Input::RIGHT) && (@index+1)%3 != 0
        @index += 1
        pbSEPlay("Choose")
        refresh
      end
      if Input.trigger?(Input::LEFT) && (@index != 0 && @index != 3)
        @index -= 1
        pbSEPlay("Choose")
        refresh
      end
      if Input.trigger?(Input::UP) && @index >= 3
        @index -= 3
        pbSEPlay("Choose")
        refresh
      end
      if Input.trigger?(Input::DOWN) && @index <= 2 
        @index += 3
        pbSEPlay("Choose")
        refresh
      end
      #Manipulate an egg
      if Input.trigger?(Input::USE)
        if $PokemonGlobal.eggs[@index] == nil
          ret = pbConfirmMessage(_INTL("La incubadora está vacía\n¿Quieres agregar un Huevo?"))
          if ret == true
            if Settings::INCUBATOR_CHOOSE_EGG_FROM_PC
              chosen = pbChooseEggFromPC
              if chosen && chosen.is_a?(Pokemon)
                $PokemonGlobal.eggs[@index] = chosen
              end
            else
              chosen=0
              pbFadeOutIn(99999){
                scene = PokemonParty_Scene.new
                screen = PokemonPartyScreen.new(scene, $player.party)
                screen.pbStartScene(_INTL("Elige un Huevo."),false)
                chosen=screen.pbChoosePokemon
                screen.pbEndScene
              }
              if chosen != -1 && $player.party[chosen] != nil
                if !$player.party[chosen].egg?
                  pbMessage(_INTL("El Pokémon elegido no es un Huevo."))
                else
                  $PokemonGlobal.eggs[@index] = $player.party[chosen]
                  $player.party.delete_at(chosen)
                  $game_temp.bag_scene.pbHardRefresh if $game_temp && $game_temp.bag_scene && defined?($game_temp.bag_scene.pbHardRefresh)
                end
              end
            end
          end
        else
          ret = pbConfirmMessage(_INTL("¿Quieres sacar este Huevo de la incubadora?"))
          if ret == true
            takeEgg($PokemonGlobal.eggs[@index],@index)
            $game_temp.bag_scene.pbHardRefresh if $game_temp && $game_temp.bag_scene && defined?($game_temp.bag_scene.pbHardRefresh)
          end
        end
        refresh
      end
      #Close scene
      if Input.trigger?(Input::BACK)
        dispose
        Input.update
        break
      end
    
      Graphics.update
      Input.update
    end
  end
end

def takeEgg(egg,index)
  sel = pbConfirmMessage(_INTL("¿Quieres agregarlo a tu equipo?"))
  if sel==true
    pbMessage(_INTL("Tu equipo está lleno.\1")) if $player.party.length == 6
    pbStorePokemon(egg)
  else
    if pbBoxesFull?
      pbMessage(_INTL("¡No hay mas espacio para Pokémon!\1"))
      pbMessage(_INTL("¡Las cajas están llenas y no pueden recibir mas Pokémon!"))
      return
    end
    oldcurbox=$PokemonStorage.currentBox
    storedbox=$PokemonStorage.pbStoreCaught(egg)
    curboxname=$PokemonStorage[oldcurbox].name
    boxname=$PokemonStorage[storedbox].name
    if storedbox!=oldcurbox
      pbMessage(_INTL("La caja \"{1}\" está llena.\1",curboxname))
      pbMessage(_INTL("{1} fue transferido a la caja \"{2}.\"",egg.name,boxname))
    else
      pbMessage(_INTL("{1} fue transferido a la caja \"{2}.\"",egg.name,boxname))
    end
  end
  $PokemonGlobal.eggs[index] = nil
end

def pbGenerateEgg(pkmn, text = "")
  return false if !pkmn || !(GameData::Item.exists?(:EGGHATCHER) && $bag.has?(:EGGHATCHER))  && $player.party_full?
  # return false if !pkmn || $player.party_full?
  pkmn = Pokemon.new(pkmn, Settings::EGG_LEVEL) if !pkmn.is_a?(Pokemon)
  # Set egg's details
  pkmn.name           = _INTL("Huevo")
  pkmn.steps_to_hatch = pkmn.species_data.hatch_steps
  pkmn.obtain_text    = text
  pkmn.calc_stats
  # Add egg to party
  if (GameData::Item.exists?(:EGGHATCHER) && $bag.has?(:EGGHATCHER))
    ret = pbConfirmMessage(_INTL("¿Quieres agregar el Huevo a la incubadora?"))
    if ret == true
      ret = addEgg(pkmn)
      if ret == true
        return true
      else
        return false if $player.party_full?  
      end
    else
      return false if $player.party_full?
    end
  end
  pbStorePokemon(pkmn)
  return true
end

def can_add_egg?
  return true if !$player.party_full? || incubator_has_space?
  return false
end

def incubator_has_space?
  return false if !GameData::Item.exists?(:EGGHATCHER) || !$bag.has?(:EGGHATCHER) 
  return true if !$PokemonGlobal.eggs
  return $PokemonGlobal.eggs.include?(nil)
end

def addEgg(egg)
  if !$PokemonGlobal.eggs
    $PokemonGlobal.eggs ||= [nil,nil,nil,nil,nil,nil]
  end
  $PokemonGlobal.eggs.each_index{|index|
    if $PokemonGlobal.eggs[index] == nil
      $PokemonGlobal.eggs[index] = egg
      return true
    end
  }
  pbMessage("La incubadora está llena.")
  return false
end


EventHandlers.add(:on_step_taken, :incubadora, proc{|sender,e|
  next if !$player || !$PokemonGlobal.eggs
  $PokemonGlobal.eggs.each_with_index do |egg, i|
    next unless egg
    next unless egg.steps_to_hatch.positive?
    egg.steps_to_hatch -= 1
    $player.pokemon_party.each do |poke|
      next if !poke.ability&.has_flag?("FasterEggHatching")
      egg.steps_to_hatch -= 1
      break
    end
    if egg.steps_to_hatch <= 0
      egg.steps_to_hatch = 0
      pbHatch(egg)
      takeEgg(egg,i)
    end
  end
})



def openHatcher
  scene = Hatcher.new
  scene.update
end


class PokemonStorageScreen
  def pbChooseEggFromPC
    $game_temp.in_storage = true
    @heldpkmn = nil
    @scene.pbStartBox(self, 0)
    retval = nil
    to_delete =  []
    loop do
      selected = @scene.pbSelectBox(@storage.party)
      if selected && selected[0] == -3   # Close box
        if pbConfirm(_INTL("¿Salir del PC?"))
          pbSEPlay("PC close")
          break
        end
        next
      end
      if selected.nil?
        next if pbConfirm(_INTL("¿Continuar operaciones?"))
        break
      elsif selected[0] == -4   # Box name
        pbBoxCommands
      else
        pokemon = @storage[selected[0], selected[1]]
        next if !pokemon
        commands = [
          _INTL("Elegir"),
          _INTL("Datos"),
        ]
        commands.push(_INTL("Debug")) if $DEBUG
        commands.push(_INTL("Cancelar"))
        helptext = _INTL("Huevo elegido.")
        command = pbShowCommands(helptext, commands)
        case command
        when 0   # Select
          if pokemon.egg?
            retval = pokemon
            to_delete = selected
            break
          else
            pbMessage(_INTL("¡Debes elegir un huevo!"))
          end
        when 1 # Summary
          pbSummary(selected, nil)
        when 2
          if $DEBUG
            pbPokemonDebug(pokemon, selected)
          end
        end
      end
    end
    @scene.pbCloseBox
    $game_temp.in_storage = false
    if retval && retval.is_a?(Pokemon)
      if to_delete[0] == -1
        $player.party.delete_at(to_delete[1])
        $game_temp&.bag_scene&.pbHardRefresh
      else
        @storage[to_delete[0], to_delete[1]] = nil
      end
    end
    return retval
  end
end

def pbChooseEggFromPC
  chosen = nil
  pbFadeOutIn {
    scene = PokemonStorageScene.new
    screen = PokemonStorageScreen.new(scene, $PokemonStorage)
    chosen = screen.pbChooseEggFromPC
  }
  chosen
end


